#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 10
#define SPI_SPEED 1000000
#define SPI_CS_GPIO 8

static volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct spidev spi;
    int fd;
    char msg[128];
    int ret;
    uint8_t tx[1] = {0x01};
    uint8_t rx[2];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    fd = open(SPI_DEV_PATH, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Initialize SPI
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        goto error_close_spi;
    }
    if (ioctl(fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        goto error_close_spi;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set bits per word");
        goto error_close_spi;
    }
    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to read bits per word");
        goto error_close_spi;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        goto error_close_spi;
    }
    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        goto error_close_spi;
    }

    // Main loop
    while (!stop_flag) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Read from ADC
        ret = spi_read(fd, tx, rx, 1);
        if (ret < 0) {
            perror("Failed to read from SPI");
            goto error_close_spi;
        }

        // Log the ADC value with timestamp
        sprintf(msg, "Timestamp: %ld.%09ld, ADC Value: %d\n", (long)ts.tv_sec, (long)ts.tv_nsec, (rx[1] << 2) | (rx[0] >> 6));
        printf("%s", msg);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    close(fd);
    return 0;

error_close_spi:
    close(fd);
    return 1;
}

