#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/types.h>

#define I2C_ADDR 0x48 // MLX91219 address when ADDR pin is tied to GND
#define ADC_ADDR 0x48 // ADS1115 address
#define ADC_REG_CONFIG 0x00
#define ADC_REG_CONVERSION 0x00
#define ADC_CONFIG_SINGLE_ENDED 0x8000
#define ADC_CONFIG_PGA_4_096V 0x0000
#define ADC_CONFIG_DRATE_128SPS 0x0000
#define ADC_CONFIG_MASK 0x000F

#define ADC_CONFIG_SINGLE_ENDED_AIN0 (ADC_CONFIG_SINGLE_ENDED | (0 << 4))
#define ADC_CONFIG_PGA_4_096V_AIN0 (ADC_CONFIG_PGA_4_096V | (0 << 2))
#define ADC_CONFIG_DRATE_128SPS_AIN0 (ADC_CONFIG_DRATE_128SPS | (0 << 0))

#define ADC_CONFIG_VALUE (ADC_CONFIG_SINGLE_ENDED_AIN0 | ADC_CONFIG_PGA_4_096V_AIN0 | ADC_CONFIG_DRATE_128SPS_AIN0)

#define ADC_READ_REG_CONVERSION 0x00

#define ADC_GAIN_4_096V 4.096

int i2c_fd;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    char i2c_device_path[20];
    sprintf(i2c_device_path, "/dev/i2c-%d", 1); // I2C bus 1

    i2c_fd = open(i2c_device_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADC_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Configure ADS1115
    uint16_t config_value = ADC_CONFIG_VALUE;
    if (write(i2c_fd, &config_value, 2) != 2) {
        perror("Failed to write configuration to ADS1115");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint16_t adc_data;
        if (read(i2c_fd, &adc_data, 2) != 2) {
            perror("Failed to read ADC data");
            close(i2c_fd);
            return 1;
        }

        // Convert ADC data to amperes
        float current = (float)adc_data * (ADC_GAIN_4_096V / 32768.0);

        printf("Current: %.2f A\n", current);

        usleep(500000); // Sleep for 500 ms
    }

    close(i2c_fd);
    return 0;
}

