#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <signal.h>
#include <stdint.h>
#include <time.h>

#define BCM2708_PERI_BASE 0x20000000
#define GPIO_BASE (BCM2708_PERI_BASE + 0x200000) /* GPIO controller */

#define SPI0_BASE (BCM2708_PERI_BASE + 0x204000) /* SPI0 controller */
#define SPI0_CS (SPI0_BASE + 0x40) /* SPI0 Chip Select */

#define MCP3008_ADDR 0x48 /* MCP3008 I2C address */

#define SPI_CS_CE0 (1 << 0) /* Chip Select for CE0 */

#define GPIO_SET 0x1c /* Set bits */
#define GPIO_CLR 0x28 /* Clear bits */
#define GPIO_LEV0 0x34 /* Level 0 */

#define GPIO_PIN_D0 4 /* Flame sensor digital output */
#define GPIO_PIN_CE0 8 /* MCP3008 Chip Enable */

#define SPI_SPEED 1000000 /* 1 MHz */

volatile unsigned *gpio, *spi;

void setup_gpio() {
    int mem_fd;
    unsigned char *mem_map;

    mem_fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (mem_fd < 0) {
        perror("Failed to open /dev/mem");
        exit(1);
    }

    mem_map = mmap(
        NULL,
        4096,
        PROT_READ | PROT_WRITE,
        MAP_SHARED,
        mem_fd,
        GPIO_BASE
    );

    if (mem_map == MAP_FAILED) {
        perror("mmap error");
        exit(1);
    }

    close(mem_fd);

    gpio = (volatile unsigned *)mem_map;

    // Set GPIO4 (D0) as input
    gpio[GPIO_SET] = (1 << GPIO_PIN_D0);
    gpio[GPIO_CLR] = (1 << GPIO_PIN_D0);

    // Set GPIO8 (CE0) as output
    gpio[GPIO_SET] = (1 << GPIO_PIN_CE0);
    gpio[GPIO_CLR] = (1 << GPIO_PIN_CE0);
}

void setup_spi() {
    int spi_fd;
    unsigned char spi_buf[4];

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        perror("Failed to set SPI mode");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_8) < 0) {
        perror("Failed to set bits per word");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        exit(1);
    }

    spi = (volatile unsigned *)mmap(
        NULL,
        4096,
        PROT_READ | PROT_WRITE,
        MAP_SHARED,
        spi_fd,
        SPI0_BASE
    );

    if (spi == MAP_FAILED) {
        perror("mmap error");
        exit(1);
    }
}

void cleanup() {
    munmap((void *)spi, 4096);
    munmap((void *)gpio, 4096);
}

int read_flame_sensor() {
    int flame_detected = 0;

    // Read digital output D0 (GPIO4)
    if ((gpio[GPIO_LEV0] & (1 << GPIO_PIN_D0)) == 0) {
        flame_detected = 1;
    }

    return flame_detected;
}

int read_adc(int channel) {
    int adc_value = 0;
    unsigned char spi_buf[3];

    // Set MCP3008 Chip Enable (GPIO8) low
    gpio[GPIO_CLR] = (1 << GPIO_PIN_CE0);

    // Send SPI command to read ADC value
    spi_buf[0] = 0b01100000 | (channel & 0x07); // Start bit + single-ended + channel
    spi_buf[1] = 0;
    spi_buf[2] = 0;

    if (write(spi_fd, spi_buf, 3) != 3) {
        perror("Failed to write to SPI");
        return -1;
    }

    if (read(spi_fd, spi_buf, 3) != 3) {
        perror("Failed to read from SPI");
        return -1;
    }

    // Calculate ADC value
    adc_value = ((spi_buf[1] << 8) | spi_buf[2]) & 0x0FFF;

    // Set MCP3008 Chip Enable (GPIO8) high
    gpio[GPIO_SET] = (1 << GPIO_PIN_CE0);

    return adc_value;
}

void log_data(int flame_detected, int adc_value) {
    FILE *file;
    time_t rawtime;
    struct tm *timeinfo;

    file = fopen("flame_data.csv", "a");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d\n",
        timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
        timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
        flame_detected, adc_value);

    fclose(file);
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

int main() {
    int flame_detected;
    int adc_value;

    signal(SIGINT, handle_sigint);

    setup_gpio();
    setup_spi();

    while (1) {
        flame_detected = read_flame_sensor();
        adc_value = read_adc(0);

        if (flame_detected == -1 || adc_value == -1) {
            fprintf(stderr, "Error reading sensor or ADC\n");
            continue;
        }

        log_data(flame_detected, adc_value);

        sleep(1);
    }

    cleanup();
    return 0;
}

