#include <pigpio.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_ADDR 0x48
#define I2C_BUS 1
#define CHANNEL AIN0
#define TEMP_THRESHOLD 60
#define DEBOUNCE_MS 50
#define MONITOR_INTERVAL_MS 100
#define FIRE_LOG_FILE "fire_log.txt"

static volatile sig_atomic_t running = 1;

void handle_sigint(int signum) {
    running = 0;
}

int init_gpiod() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpio");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_line_request_any(chip, "flame", GPIOD_LINE_DIRECTION_IN);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line for flame sensor\n");
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_direction_set(line, GPIOD_LINE_DIRECTION_IN)) {
        fprintf(stderr, "Failed to set direction for flame sensor GPIO\n");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_request_any(chip, "buzzer", GPIOD_LINE_DIRECTION_OUT)) {
        fprintf(stderr, "Failed to request GPIO line for buzzer\n");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_direction_set(line, GPIOD_LINE_DIRECTION_OUT)) {
        fprintf(stderr, "Failed to set direction for buzzer GPIO\n");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    return 0;
}

int init_i2c() {
    int i2c_handle;

    if (wiringPiI2CSetup(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    i2c_handle = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (wiringPiI2CWriteReg8(i2c_handle, 0x00, 0x86)) {
        fprintf(stderr, "Failed to configure ADC\n");
        return 1;
    }

    return 0;
}

int read_temperature() {
    int i2c_handle = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device for temperature reading\n");
        return -1;
    }

    int raw_data = wiringPiI2CReadReg16(i2c_handle, CHANNEL);
    if (raw_data < 0) {
        fprintf(stderr, "Failed to read temperature from ADC\n");
        return -1;
    }

    int temperature = (raw_data * 0.1875);
    return temperature;
}

void log_event(const char *event, int temperature) {
    FILE *log_file = fopen(FIRE_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - %s",
            now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
            now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, event);

    if (temperature > 0) {
        fprintf(log_file, " Temperature: %d°C", temperature);
    }

    fprintf(log_file, "\n");
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_handle;
    int flame_sensor_value;
    int temperature;

    signal(SIGINT, handle_sigint);

    if (init_gpiod()) {
        return 1;
    }

    if (init_i2c()) {
        gpiod_chip_put(chip);
        return 1;
    }

    while (running) {
        flame_sensor_value = gpiod_line_get_value(line);

        if (flame_sensor_value == 1) {
            usleep(DEBOUNCE_MS * 1000);
            if (gpiod_line_get_value(line) == 1) {
                log_event("Flame detected!", 0);
            }
        }

        temperature = read_temperature();
        if (temperature > TEMP_THRESHOLD) {
            log_event("Temperature exceeded 60°C", temperature);
        }

        if (flame_sensor_value == 1 && temperature > TEMP_THRESHOLD) {
            gpiod_line_set_value(line, 1);
            sleep(2);
            gpiod_line_set_value(line, 0);
            log_event("Fire detected!", temperature);
        }

        usleep(MONITOR_INTERVAL_MS * 1000);
    }

    gpiod_line_release(line);
    gpiod_chip_put(chip);
    wiringPiI2CClose(i2c_handle);
    return 0;
}

