#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>

#define MLX91219_CURRENT_THRESHOLD 1000 // Define your threshold here

// GPIO constants
#define GPIO_BASE "/dev/gpiomem"
#define GPIO_ADDR 0x20200000
#define GPIO_LENGTH 4096
#define GPIO_EXPORT 0x24
#define GPIO_UNEXPORT 0x25
#define GPIO_SET 0x1C
#define GPIO_CLR 0x28

// SPI constants
#define SPI_PATH "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_BITS 8

// Helper function to handle errors
void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

// Helper function to read SPI data
uint16_t read_spi() {
    int fd;
    uint8_t tx_buf[1] = {0};
    uint8_t rx_buf[2];
    int ret;

    fd = open(SPI_PATH, O_RDWR);
    if (fd < 0) {
        handle_error("Failed to open SPI device");
    }

    ret = ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        handle_error("Failed to set SPI mode");
    }

    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret < 0) {
        handle_error("Failed to set bits per word");
    }

    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        handle_error("Failed to set SPI speed");
    }

    ret = write(fd, tx_buf, sizeof(tx_buf));
    if (ret < 0) {
        handle_error("Failed to write to SPI");
    }

    ret = read(fd, rx_buf, sizeof(rx_buf));
    if (ret < 0) {
        handle_error("Failed to read from SPI");
    }

    close(fd);

    // Combine two bytes into a 16-bit value
    return (rx_buf[0] << 8) | rx_buf[1];
}

// Helper function to control GPIO
void control_gpio(int state) {
    int fd;
    uint32_t *gpio_addr;
    uint32_t *gpio_set, *gpio_clr;

    fd = open(GPIO_BASE, O_RDWR | O_SYNC);
    if (fd < 0) {
        handle_error("Failed to open GPIO device");
    }

    gpio_addr = mmap(NULL, GPIO_LENGTH, PROT_READ | PROT_WRITE, MAP_SHARED, fd, GPIO_ADDR);
    if (gpio_addr == MAP_FAILED) {
        handle_error("Failed to mmap GPIO device");
    }

    gpio_set = (uint32_t *)((char *)gpio_addr + GPIO_SET);
    gpio_clr = (uint32_t *)((char *)gpio_addr + GPIO_CLR);

    // Export GPIO 18
    if (ioctl(fd, GPIO_EXPORT, 18) < 0) {
        handle_error("Failed to export GPIO 18");
    }

    // Set GPIO 18 to output
    if (ioctl(fd, GPIO_SET, 18) < 0) {
        handle_error("Failed to set GPIO 18 to output");
    }

    // Control the fan
    if (state) {
        *gpio_set = 1 << 18; // Set GPIO 18 HIGH
    } else {
        *gpio_clr = 1 << 18; // Set GPIO 18 LOW
    }

    munmap(gpio_addr, GPIO_LENGTH);
    close(fd);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    control_gpio(0); // Turn off the fan
    exit(EXIT_SUCCESS);
}

int main() {
    uint16_t adc_value;
    FILE *log_file;
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        handle_error("Failed to open log file");
    }

    // Main loop
    while (1) {
        // Read ADC value
        adc_value = read_spi();

        // Check for sensor-absent condition
        if (adc_value == 0 || adc_value == 0xFFFF) {
            printf("Sensor absent\n");
            continue;
        }

        // Log the reading
        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
        fprintf(log_file, "%s %d\n", timestamp, adc_value);
        fflush(log_file);

        // Control the fan based on the threshold
        if (adc_value > MLX91219_CURRENT_THRESHOLD) {
            control_gpio(1); // Turn on the fan
        } else {
            control_gpio(0); // Turn off the fan
        }

        // Sleep for 1 second
        sleep(1);
    }

    fclose(log_file);
    return 0;
}

