#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define I2C_ADDR 0x5A // Default I2C address for MICS-4514
#define I2C_BUS 1
#define LOG_FILE "co_log.txt"
#define INTERVAL 5000 // 5 seconds in milliseconds

// Simulated 16-bit raw reading
#define RAW_READING 10000

// Calibrated logarithmic curve parameters (example values)
#define LOG_A 0.0001
#define LOG_B 0.01

// Function to convert raw reading to ppm
double raw_to_ppm(int raw_reading) {
    return LOG_A * raw_reading + LOG_B;
}

// Function to handle SIGINT and SIGTERM
void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    // Cleanup code here (e.g., close file, release resources)
    exit(0);
}

int main() {
    struct i2c_client *client;
    int ret;
    FILE *log_file;
    struct timespec ts;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C bus
    if ((ret = i2c_bus_new(I2C_BUS, 0)) < 0) {
        perror("i2c_bus_new");
        return 1;
    }

    // Create I2C client
    if ((ret = i2c_client_new(ret, I2C_ADDR, 0)) < 0) {
        perror("i2c_client_new");
        i2c_bus_del(I2C_BUS);
        return 1;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        i2c_client_del(client);
        i2c_bus_del(I2C_BUS);
        return 1;
    }

    // Main loop
    while (1) {
        // Simulate reading from sensor
        int raw_reading = RAW_READING;

        // Convert raw reading to ppm
        double ppm = raw_to_ppm(raw_reading);

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log timestamped ppm value
        fprintf(log_file, "%ld.%09ld: %.2f ppm\n", (long)ts.tv_sec, (long)ts.tv_nsec, ppm);

        // Sleep for 5 seconds
        usleep(INTERVAL);
    }

    // Cleanup code here (e.g., close file, release resources)
    fclose(log_file);
    i2c_client_del(client);
    i2c_bus_del(I2C_BUS);

    return 0;
}

