#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x5A // Replace with actual I2C address of the sensor
#define I2C_DEV "/dev/i2c-1" // Replace with actual I2C device file
#define LOG_FILE "co_log.txt"
#define ALERT_LOG "alert_log.txt"
#define ALERT_THRESHOLD 25

int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_sensor() {
    char buffer[4];
    int bytes_read;

    bytes_read = read(i2c_fd, buffer, 4);
    if (bytes_read != 4) {
        perror("Error reading from I2C device");
        return -1;
    }

    uint16_t ox = (buffer[0] << 8) | buffer[1];
    uint16_t red = (buffer[2] << 8) | buffer[3];

    // Convert OX value to CO concentration in ppm
    float co_ppm = (float)ox / 1000.0;

    return co_ppm;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting up signal handlers");
        return 1;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    FILE *alert_log = fopen(ALERT_LOG, "a");
    if (alert_log == NULL) {
        perror("Error opening alert log file");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        float co_ppm = read_sensor();
        if (co_ppm < 0) {
            break;
        }

        fprintf(log_file, "%f\n", co_ppm);
        fflush(log_file);

        if (co_ppm >= ALERT_THRESHOLD) {
            fprintf(alert_log, "CO concentration exceeded %d ppm at %s\n", ALERT_THRESHOLD, ctime(&time(NULL)));
            fflush(alert_log);
        }

        sleep(5);
    }

    fclose(log_file);
    fclose(alert_log);
    close(i2c_fd);

    return 0;
}

