#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define GPIO_OUT1 2
#define GPIO_OUT2 3
#define SAMPLE_INTERVAL 100 // in milliseconds
#define LOG_FILE "audio_log.txt"

// Function prototypes
void handle_signal(int signum);
void read_sensor(int sensor_id, double *level);

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[2];
    struct gpiod_line_request *requests[2];
    FILE *log_file;
    double levels[2] = {0.0, 0.0};
    double averages[2] = {0.0, 0.0};
    int samples = 0;
    int sample_count = 10; // Number of samples to average

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize GPIO lines
    chip = gpiod_chip_open_by_name("gpio");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return 1;
    }

    for (int i = 0; i < 2; i++) {
        lines[i] = gpiod_line_request_by_name(chip, "gpio" + (i + '0'), "audio_sample", GPIOD_LINE_DIRECTION_OUT);
        if (!lines[i]) {
            perror("Failed to request GPIO line");
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(lines[j]);
            }
            gpiod_chip_close(chip);
            fclose(log_file);
            return 1;
        }

        requests[i] = gpiod_line_request_get(lines[i]);
        if (!requests[i]) {
            perror("Failed to get line request");
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(lines[j]);
            }
            gpiod_chip_close(chip);
            fclose(log_file);
            return 1;
        }
    }

    // Main loop
    while (1) {
        for (int i = 0; i < 2; i++) {
            read_sensor(i, &levels[i]);
        }

        averages[0] = averages[0] * (sample_count - 1) / sample_count + levels[0] / sample_count;
