#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX91204_ADDR 0x3C
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x00
#define ADS1115_REG_CONVERSION_RESULT_HIGH 0x00
#define ADS1115_REG_CONVERSION_RESULT_LOW 0x01
#define MLX91204_REG_CURRENT_LSB 0x00
#define MLX91204_REG_CURRENT_MSB 0x01

#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0

int i2c_file_descriptor;
int circular_buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void handle_sigint(int signum) {
    printf("Received SIGINT, shutting down...\n");
    close(i2c_file_descriptor);
    exit(0);
}

int i2c_read_register(uint8_t reg, uint8_t *data, size_t length) {
    int bytes_read;
    bytes_read = write(i2c_file_descriptor, &reg, 1);
    if (bytes_read != 1) {
        perror("Failed to write register address");
        return -1;
    }
    bytes_read = read(i2c_file_descriptor, data, length);
    if (bytes_read != length) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

int i2c_write_register(uint8_t reg, uint8_t *data, size_t length) {
    int bytes_written;
    bytes_written = write(i2c_file_descriptor, &reg, 1);
    if (bytes_written != 1) {
        perror("Failed to write register address");
        return -1;
    }
    bytes_written = write(i2c_file_descriptor, data, length);
    if (bytes_written != length) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

int setup_ads1115() {
    uint8_t config_data = 0x86; // Set to single-ended mode, gain 2/3, and data rate 10SPS
    if (i2c_write_register(ADS1115_REG_CONFIG, &config_data, 1) < 0) {
        return -1;
    }
    return 0;
