#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_WTIME 0x03
#define TCS34725_RATIOS 0x04
#define TCS34725_CLEAR 0x06
#define TCS34725_RED 0x07
#define TCS34725_GREEN 0x08
#define TCS34725_BLUE 0x09
#define TCS34725_CONTROL 0x0A
#define TCS34725_ID 0x0F

#define TCS34725_ATIME_2_4MS 0x04
#define TCS34725_WTIME_100MS 0x40

#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x10

#define TCS34725_CONTROL_AIEN 0x10

#define TCS34725_ID_VALUE 0x44

#define TCS34725_CLEAR_VALUE 0x00
#define TCS34725_RED_VALUE 0x00
#define TCS34725_GREEN_VALUE 0x00
#define TCS34725_BLUE_VALUE 0x00

#define TCS34725_MAX_READ_FAILS 3

static int i2c_fd;
static int read_fails = 0;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(1);
}

int read_i2c(uint8_t reg, uint8_t *data, size_t len) {
    int ret;
    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C register 0x%02X\n", reg);
        read_fails++;
        return -1;
    }
    ret = read(i2c_fd, data, len);
    if (ret != len) {
        fprintf(stderr, "Error reading from I2C register 0x%02X\n", reg);
        read_fails++;
        return -1;
    }
    read_fails = 0;
    return 0;
}

int write_i2c(uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg | TCS34725_COMMAND_BIT, data};
    int ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X\n", reg);
        read_fails++;
        return -1;
    }
    read_fails = 0;
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request request;
    struct gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    struct gpiod_line_value value = { .level = 1 };

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    i2c_fd = gpiod_chip_get_line_by_name(chip, "i2c-1");
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to get I2C line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    request.consumer = "TCS34725";
    request.request = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    request.flags = flags;
    line = gpiod_line_request(chip, "i2c-1", &request);
    if (!line) {
        fprintf(stderr, "Failed to request I2C line\n");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    if (write_i2c(TCS34725_ATIME, TCS34725_ATIME_2_4MS) < 0 ||
        write_i2c(TCS34725_WTIME, TCS34725_WTIME_100MS) < 0 ||
        write_i2c(TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        gpiod_line_free(line);
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t id_reg;
    if (read_i2c(TCS34725_ID, &id_reg, 1) < 0 || id_reg != TCS34725_ID_VALUE) {
        fprintf(stderr, "Failed to read sensor ID or ID mismatch\n");
        gpiod_line_free(line);
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *csv_file = fopen("color_log.csv", "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpiod_line_free(line);
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    if (fseek(csv_file, 0, SEEK_END) != 0) {
        fprintf(stderr, "Failed to seek to end of CSV file\n");
        fclose(csv_file);
        gpiod_line_free(line);
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    char header[] = "Timestamp,Clear,Red,Green,Blue\n";
    if (ftell(csv_file) == 0) {
        fwrite(header, sizeof(header), 1, csv_file);
    }

    while (1) {
        uint8_t clear_reg, red_reg, green_reg, blue_reg;
        if (read_i2c(TCS34725_CLEAR, &clear_reg, 1) < 0 ||
            read_i2c(TCS34725_RED, &red_reg, 1) < 0 ||
            read_i2c(TCS34725_GREEN, &green_reg, 1) < 0 ||
            read_i2c(TCS34725_BLUE, &blue_reg, 1) < 0) {
            if (read_fails >= TCS34725_MAX_READ_FAILS) {
                fprintf(stderr, "Too many consecutive I2C read failures, exiting\n");
                break;
            }
            continue;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", now_tm);

        fprintf(csv_file, "%s%02X,%02X,%02X,%02X\n", timestamp, clear_reg, red_reg, green_reg, blue_reg);
        fflush(csv_file);

        usleep(1000000); // Sleep for 1 second
    }

    fclose(csv_file);
    gpiod_line_free(line);
    close(i2c_fd);
    gpiod_chip_close(chip);

    return 0;
}

