        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    if (write(spi_fd, &tr, sizeof(tr)) < 0) {
        perror("write");
        return -1;
    }

    if (read(spi_fd, &tr, sizeof(tr)) < 0) {
        perror("read");
        return -1;
    }

    return (int)tr.rx_buf;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    spi_fd = open(SPI_DEV_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("ioctl");
        close(spi_fd);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        close(spi_fd);
        return 1;
    }

    fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");

    while (1) {
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        int moisture1 = read_adc(SPI_CHANNEL_0);
        int moisture2 = read_adc(SPI_CHANNEL_1);

        if (moisture1 < 0 || moisture2 < 0) {
            fprintf(stderr, "Error reading sensor values\n");
            continue;
        }

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                moisture1, moisture2);

        fflush(log_file);
        usleep(5000000); // Sleep for 5 seconds
    }

    fclose(log_file);
    close(spi_fd);

    return 0;
}
