#define MCP3008_SPI_BITS 12
#define MCP3008_SPI_SPEED 1000000
#define CURRENT_LOG_FILE "current_log.csv"
#define MAX_RETRIES 3
#define OVERCURRENT_LIMIT 10.0

struct gpiod_line *shutdown_line;

void handle_signal(int signum) {
    gpiod_line_free(shutdown_line);
    gpiod_chip_put(shutdown_line->chip);
    gpiod_chip_free(shutdown_line->chip);
    exit(signum);
}

int spi_read(int fd, uint8_t *data, size_t len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = read(fd, data, len);
        if (result == len) {
            return 0;
        } else if (result < 0 && errno == EINTR) {
            retries++;
            continue;
        } else {
            return -1;
        }
    }

    return -1;
}

int spi_write(int fd, uint8_t *data, size_t len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = write(fd, data, len);
        if (result == len) {
            return 0;
        } else if (result < 0 && errno == EINTR) {
            retries++;
            continue;
        } else {
            return -1;
        }
    }

    return -1;
}

int read_adc(int fd) {
    uint8_t cmd[3] = {0x01, (MCP3008_CHANNEL << 6) | 0x18, 0};
    uint8_t data[3];

    if (spi_write(fd, cmd, 3) < 0) {
        return -1;
    }

    if (spi_read(fd, data, 3) < 0) {
        return -1;
    }

    int adc_value = ((data[1] << 8) | data[2]) >> 4;
    return adc_value;
}

double convert_to_amperes(int adc_value) {
    // Assuming a linear conversion from ADC value to amperes
    // Replace this with the actual conversion formula for your sensor
    return (double)adc_value * 0.01; // Example conversion
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *shutdown_line;
    int fd;
    int adc_value;
    double current;
    FILE *file;
    char timestamp[20];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    shutdown_line = gpiod_line_request_any(chip, "shutdown", GPIOD_LINE_DIRECTION_OUT);
    if (!shutdown_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_set_value(shutdown_line, 1); // Set initial state to high

    fd = open(MCP3008_SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_free(shutdown_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &MCP3008_SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        gpiod_line_free(shutdown_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &MCP3008_SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        gpiod_line_free(shutdown_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &MCP3008_SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        gpiod_line_free(shutdown_line);
        gpiod_chip_put(chip);
        return 1;
    }

    file = fopen(CURRENT_LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        close(fd);
        gpiod_line_free(shutdown_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (fseek(file, 0, SEEK_END) != 0) {
        perror("Failed to seek to end of file");
        fclose(file);
        close(fd);
        gpiod_line_free(shutdown_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,Current (A)\n");
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        adc_value = read_adc(fd);
        if (adc_value < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        current = convert_to_amperes(adc_value);

        if (current > OVERCURRENT_LIMIT) {
            gpiod_line_set_value(shutdown_line, 0); // Drive GPIO17 low
            fprintf(file, "%s,%f\n", timestamp, current);
            fprintf(file, "Overcurrent event at %s\n", timestamp);
            sleep(1);
            gpiod_line_set_value(shutdown_line, 1); // Drive GPIO17 high
        } else {
            fprintf(file, "%s,%f\n", timestamp, current);
        }

        sleep(1);
    }

    fclose(file);
    close(fd);
    gpiod_line_free(shutdown_line);
    gpiod_chip_put(chip);
    gpiod_chip_free(chip);

    return 0;
}

