#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define MLX90817_ADDR 0x3C
#define MLX90817_REG_PRESSURE 0x00

static FILE *log_file;
static int i2c_handle;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2c_close(i2c_handle);
    }
    i2c_cleanup();
    exit(signum);
}

int read_pressure() {
    int ret;
    uint8_t data[2];

    ret = i2c_read_device(i2c_handle, MLX90817_REG_PRESSURE, data, 2);
    if (ret != 2) {
        fprintf(stderr, "Failed to read pressure data from MLX90817 (ret=%d)\n", ret);
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int main() {
    struct timespec ts;
    char timestamp[20];
    int pressure;

    if (i2c_open(1, MLX90817_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    i2c_handle = i2c_open(1, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    log_file = fopen("pressure_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(i2c_handle);
        return 1;
    }

    fprintf(log_file, "Timestamp,Pressure (kPa)\n");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        time_t rawtime;
        struct tm *timeinfo;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        pressure = read_pressure();
        if (pressure >= 0) {
            fprintf(log_file, "%s,%d\n", timestamp, pressure);
            fflush(log_file);
        }

        nanosleep(&ts, NULL);
    }

    return 0;
}

