This C program interfaces with the Melexis MLX90817 absolute pressure sensor on I2C bus 1, reads the sensor once per second, and appends each measurement to a file named `pressure_log.csv`. It checks every I2C call and every file operation for errors, printing to stderr the register and the driver error code on any I2C read failure while continuing without logging. It handles sensor-absent conditions such as I2C open failure or repeated read failures. On receipt of SIGINT or SIGTERM, it cleanly closes the I2C handle, flushes and closes the log file, and invokes the library's cleanup API before exiting.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define MLX90834_I2C_ADDR 0x3C
#define ADS1115_I2C_ADDR 0x48
#define PRESSURE_CHANNEL 0
#define TEMPERATURE_CHANNEL 1
#define MAX_RETRIES 3
#define PRESSURE_THRESHOLD 105.0

int i2c_fd;
int gpiopin;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpiopin >= 0) {
        gpioTerminate();
    }
    exit(0);
}

int read_i2c_sensor(int addr, int channel, int retries) {
    int i;
    int result = -1;
    for (i = 0; i < retries; i++) {
        if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
            perror("I2C_SLAVE");
            return -1;
        }
        if (write(i2c_fd, &channel, 1) != 1) {
            perror("write");
            return -1;
        }
        if (read(i2c_fd, &result, 2) != 2) {
            perror("read");
            return -1;
        }
        if (result >= 0) {
            break;
        }
    }
    return result;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    gpiopin = 17;
    if (gpioSetMode(gpiopin, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }

    char i2c_device[] = "/dev/i2c-1";
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    while (1) {
        int pressure_raw = read_i2c_sensor(MLX90834_I2C_ADDR, PRESSURE_CHANNEL, MAX_RETRIES);
        int temperature_raw = read_i2c_sensor(ADS1115_I2C_ADDR, TEMPERATURE_CHANNEL, MAX_RETRIES);

        if (pressure_raw < 0 || temperature_raw < 0) {
            perror("read_i2c_sensor");
            continue;
        }

        float pressure = (float)pressure_raw / 1000.0; // Assuming pressure is in milli-kPa
        float temperature = (float)temperature_raw / 100.0; // Assuming temperature is in centi-degrees Celsius

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            if (gpioWrite(gpiopin, PI_ON) < 0) {
                perror("gpioWrite");
            }
        } else {
            if (gpioWrite(gpiopin, PI_OFF) < 0) {
                perror("gpioWrite");
            }
        }

        sleep(1);
    }

    return 0;
}

