        if (current > MAX_CURRENT) {
            gpiod_line_set_value(motor_shutdown_line, 1);
            fprintf(stderr, "OVERCURRENT event: %.2f A\n", current);
            fprintf(log_fd, "OVERCURRENT event: %.2f A at %ld.%09ld\n", current, ts.tv_sec, ts.tv_nsec);
            fflush(log_fd);
            exit(EXIT_FAILURE);
        }

        fprintf(log_fd, "%.2f A at %ld.%09ld\n", current, ts.tv_sec, ts.tv_nsec);
        fflush(log_fd);

        clock_gettime(CLOCK_REALTIME, &ts);
        usleep(100000); // 100 ms delay
    }

    close(log_fd);
    gpiod_line_free(motor_shutdown_line);
    gpiod_line_free(spi_ce_line);
    gpiod_chip_put(spi_chip);
    close(spi_fd);

    return 0;
}

