#define SPI_CE_PIN 8
#define SPI_SCLK_PIN 11
#define SPI_MOSI_PIN 10
#define SPI_MISO_PIN 9
#define ADC_CHANNEL 0
#define VOLTAGE_THRESHOLD 2.5
#define ALARM_PIN 4

static FILE *log_file;
static struct spi_device *spi;
static struct gpiod_line *alarm_line;

void handle_signal(int signum) {
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_free(alarm_line);
    }

    if (spi) {
        spi_device_close(spi);
    }

    if (log_file) {
        fclose(log_file);
    }

    exit(signum);
}

void log_voltage(double voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S,", timeinfo);
    fprintf(log_file, "%sVoltage: %.2f V\n", buffer, voltage);
    fflush(log_file);
}

int main() {
    int ret;
    uint8_t tx_buffer[3] = {0x01 << 6, 0x00, 0x00};
    uint8_t rx_buffer[3];
    double voltage;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((spi = spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    if ((ret = spi_device_chip_select_setup(spi, SPI_CE_PIN, 0, 0)) < 0) {
        fprintf(stderr, "Failed to set up chip select for SPI\n");
        spi_close(spi);
        return 1;
    }

    if ((alarm_line = gpiod_line_request(ALARM_PIN, "Alarm", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        fprintf(stderr, "Failed to request GPIO line for alarm\n");
        spi_close(spi);
        return 1;
    }

    if ((log_file = fopen("co_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_free(alarm_line);
        spi_close(spi);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (spi_read(spi, tx_buffer, rx_buffer, 3) < 0) {
            fprintf(stderr, "SPI read failed, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        voltage = (double)(rx_buffer[1] << 8 | rx_buffer[2]) * 3.3 / 1024;
        log_voltage(voltage);

        if (voltage > VOLTAGE_THRESHOLD) {
            gpiod_line_set_value(alarm_line, 1);
        } else {
            gpiod_line_set_value(alarm_line, 0);
        }

        sleep(1);
    }

    return 0;
}

