#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>

#include <linux/spi/spidev.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MAX_CONCENTRATION 1000 // ppm
#define LOG_FILE "methane_log.txt"

int spi_fd;
FILE *log_file;

void handle_signal(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_spi() {
    spi_fd = open(SPI_DEV_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to read bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

void close_spi() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int read_sensor() {
    uint8_t tx[3] = {0x01, 0x80, 0x00}; // Start bit, channel select, dummy byte
    uint8_t rx[3];

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx, &rx);
    if (ret < 1) {
        perror("Failed to transfer data over SPI");
        return -1;
    }

    // Convert ADC value to ppm
    int adc_value = (rx[1] << 8) | rx[2];
    int ppm = (adc_value * 3300) / 4095; // Assuming 3.3V reference and 10-bit ADC

    return ppm;
}

void log_reading(int ppm) {
    struct tm *tm;
    char timestamp[20];
    time_t now = time(NULL);

    tm = localtime_r(&now, tm);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(log_file, "%s %d ppm\n", timestamp, ppm);
    fflush(log_file);
}

int main() {
    setup_signal_handlers();

    spi_fd = open_spi();
    if (spi_fd < 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close_spi();
        return 1;
    }

