#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define I2C_ADDR 0x48
#define I2C_BUS 1
#define I2C_SDA 2
#define I2C_SCL 3
#define I2C_CHANNEL 0
#define I2C_SAMPLE_RATE 1
#define PRESSURE_FILE "pressure_log.txt"

static FILE *pressure_log;

void handle_sigint(int signum) {
    if (pressure_log) {
        fclose(pressure_log);
    }
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sda, *scl;
    int i2c_fd;
    int pressure_value;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = wiringPiI2CSetup(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    // Initialize gpiod
    if (gpiod_chip_open(I2C_SDA, &chip) < 0) {
        fprintf(stderr, "Failed to open gpiod chip for SDA\n");
        return 1;
    }

    // Set SDA line as output
    if (gpiod_line_request(chip, "sda", &sda, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request SDA line\n");
        return 1;
    }

    // Set SCL line as output
    if (gpiod_line_request(chip, "scl", &scl, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request SCL line\n");
        return 1;
    }

    // Open pressure log file
    pressure_log = fopen(PRESSURE_FILE, "w");
    if (!pressure_log) {
        fprintf(stderr, "Failed to open pressure log file\n");
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (1) {
        // Read pressure value from ADC
        pressure_value = wiringPiI2CReadReg16(i2c_fd, I2C_CHANNEL);
        if (pressure_value < 0) {
            fprintf(stderr, "Failed to read pressure value from ADC\n");
            continue;
        }

        // Validate pressure value
        if (pressure_value < 0 || pressure_value > 100000) {
            fprintf(stderr, "Invalid pressure value: %d\n", pressure_value);
            continue;
        }

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Log pressure value with timestamp
        fprintf(pressure_log, "%s %d\n", timestamp, pressure_value);
        fflush(pressure_log);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    if (pressure_log) {
        fclose(pressure_log);
    }
    gpiod_line_free(scl);
    gpiod_line_free(sda);
    gpiod_chip_close(chip);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

