#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define GPIO_CHIP "gpiochip4"
#define GPIO_CE0 8
#define GPIO_SCLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define TMP36_OFFSET 0.5
#define TMP36_SCALE 0.01
#define TEMP_LOG "temperature_log.csv"

static int spi_fd = -1;
static struct gpiod_line *ce0_line = NULL;
static struct gpiod_line *sclk_line = NULL;
static struct gpiod_line *mosi_line = NULL;
static struct gpiod_line *miso_line = NULL;
static FILE *log_file = NULL;

void handle_signal(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (ce0_line != NULL) {
        gpiod_line_free(ce0_line);
    }
    if (sclk_line != NULL) {
        gpiod_line_free(sclk_line);
    }
    if (mosi_line != NULL) {
        gpiod_line_free(mosi_line);
    }
    if (miso_line != NULL) {
        gpiod_line_free(miso_line);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct spi_ioc_transfer spi_transfer;
    uint8_t spi_buffer[2];
    int spi_result;
    int adc_value;
    double temperature_celsius;
    struct timespec ts;
    struct tm *tm_info;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode, bits per word, and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI mode, bits per word, or speed");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO lines
    ce0_line = gpiod_line_request(GPIO_CHIP, GPIO_CE0, "CE0", 0);
    if (ce0_line == NULL) {
        perror("Failed to request CE0 GPIO line");
        close(spi_fd);
        return 1;
    }

    sclk_line = gpiod_line_request(GPIO_CHIP, GPIO_SCLK, "SCLK", 0);
    if (sclk_line == NULL) {
        perror("Failed to request SCLK GPIO line");
        gpiod_line_free(ce0_line);
        close(spi_fd);
        return 1;
    }

    mosi_line = gpiod_line_request(GPIO_CHIP, GPIO_MOSI, "MOSI", 0);
    if (mosi_line == NULL) {
        perror("Failed to request MOSI GPIO line");
        gpiod_line_free(ce0_line);
        gpiod_line_free(sclk_line);
        close(spi_fd);
        return 1;
    }

    miso_line = gpiod_line_request(GPIO_CHIP, GPIO_MISO, "MISO", 1);
    if (miso_line == NULL) {
        perror("Failed to request MISO GPIO line");
        gpiod_line_free(ce0_line);
        gpiod_line_free(sclk_line);
        gpiod_line_free(mosi_line);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(TEMP_LOG, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_free(ce0_line);
        gpiod_line_free(sclk_line);
        gpiod_line_free(mosi_line);
        gpiod_line_free(miso_line);
        close(spi_fd);
        return 1;
    }

    // Write header if file is newly created
    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    while (1) {
        // Prepare SPI transfer
        spi_transfer.tx_buf = (unsigned long)spi_buffer;
        spi_transfer.rx_buf = (unsigned long)spi_buffer;
        spi_transfer.len = 2;
        spi_transfer.delay_usecs = 0;
        spi_transfer.speed_hz = SPI_SPEED;
        spi_transfer.bits_per_word = SPI_BITS;
        spi_transfer.cs_change = 1;

        // Perform SPI transfer
        spi_result = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
        if (spi_result < 1) {
            perror("Failed SPI transfer");
            break;
        }

        // Read ADC value
        adc_value = (spi_buffer[1] << 8) | spi_buffer[0];

        // Validate ADC reading
        if (adc_value < 0 || adc_value > 4095) {
            fprintf(stderr, "Invalid ADC reading: %d\n", adc_value);
            continue;
        }

        // Convert ADC value to Celsius temperature
        temperature_celsius = (adc_value * TMP36_SCALE) - TMP36_OFFSET;

        // Check temperature range
        if (temperature_celsius < -40 || temperature_celsius > 125) {
            fprintf(stderr, "Temperature out of range: %.2f°C\n", temperature_celsius);
            continue;
        }

        // Log temperature
        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, temperature_celsius);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_free(ce0_line);
    gpiod_line_free(sclk_line);
    gpiod_line_free(mosi_line);
    gpiod_line_free(miso_line);
    close(spi_fd);

    return 0;
}

