#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <mcp3008.h>

#define SPI_DEV "/dev/spidev0.0"
#define LOG_FILE "impact_log.txt"
#define IMPACT_THRESHOLD 1000

static struct gpiod_line *cs_line;
static struct mcp3008_dev *mcp3008;
static FILE *log_file;

void cleanup(void) {
    if (log_file) {
        fclose(log_file);
    }
    if (mcp3008) {
        mcp3008_close(mcp3008);
    }
    if (cs_line) {
        gpiod_line_free(cs_line);
    }
    exit(EXIT_SUCCESS);
}

void handle_sigint(int signum) {
    cleanup();
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;
    int ret;

    // Initialize libgpiod
    if ((ret = gpiod_chip_open("/dev/gpiochip0", &chip)) < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request GPIO8 for chip select
    req = gpiod_line_request_by_name(chip, "gpio8", "MCP3008 CS", 0);
    if (!req) {
        perror("gpiod_line_request_by_name");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO8 to output
    if ((ret = gpiod_line_direction_set(req, GPIO_LINE_DIRECTION_OUT)) < 0) {
        perror("gpiod_line_direction_set");
        gpiod_line_free(req);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO8 to low (active)
    if ((ret = gpiod_line_set_value(req, 0)) < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_free(req);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    cs_line = req;

    // Initialize MCP3008
    if ((ret = mcp3008_open(SPI_DEV, 0, 1000000, 0, &mcp3008)) < 0) {
        perror("mcp3008_open");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("fopen");
        mcp3008_close(mcp3008);
        cleanup();
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, handle_sigint);

    while (1) {
        // Read ADC values
        int x, y, z;
        if ((ret = mcp3008_read(mcp3008, 0, &x)) < 0 ||
            (ret = mcp3008_read(mcp3008, 1, &y)) < 0 ||
            (ret = mcp3008_read(mcp3008, 2, &z)) < 0) {
            perror("mcp3008_read");
            cleanup();
            return EXIT_FAILURE;
        }

        // Check if values are within valid range
        if (x < 0 || x > 1023 || y < 0 || y > 1023 || z < 0 || z > 1023) {
            fprintf(stderr, "Invalid ADC value(s)\n");
            cleanup();
            return EXIT_FAILURE;
        }

        // Log values
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d, %d\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, x, y, z);

        // Check for impact
        if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
            fprintf(log_file, "IMPACT DETECTED\n");
        }

        // Sleep for 10ms (100Hz sampling rate)
        usleep(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

