// Function prototypes
void handle_sigint(int signum);
int read_sensor_data(int i2c_handle);

int main() {
    int i2c_handle = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device.\n");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2c_close(i2c_handle);
        return 1;
    }

    // Write header row
    fprintf(log_file, "Timestamp,IR_ADC,RED_ADC,Error\n");

    signal(SIGINT, handle_sigint);

    while (1) {
        int ir_adc, red_adc, error = 0;
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        if (read_sensor_data(i2c_handle) != 0) {
            error = 1;
        }

        fprintf(log_file, "%ld,%d,%d,%d\n", now, ir_adc, red_adc, error);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    i2c_close(i2c_handle);

    return 0;
}

void handle_sigint(int signum) {
    printf("\nReceived SIGINT, performing graceful shutdown...\n");
    exit(0);
}

int read_sensor_data(int i2c_handle) {
    uint8_t buffer[4];
    int ret;

    // Read IR and RED ADC values
    ret = i2c_read_i2c_block_data(i2c_handle, 0x00, buffer, 4);
    if (ret < 0) {
        // Check if the error is due to a transient issue or sensor absence
        if (errno == EIO) {
            return 1; // Transient I2C error
        } else {
            return 2; // Sensor absent/uninitialized
        }
    }

    // Convert raw ADC values to 16-bit integers
    int ir_adc = (buffer[0] << 8) | buffer[1];
    int red_adc = (buffer[2] << 8) | buffer[3];

    // Log the raw ADC values as proxy values for HR and SpO₂
    // (Note: The Si1172 requires a proprietary algorithm to convert raw PPG samples to true HR and SpO₂)

    return 0; // Success
}

