#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <libmcp3008.h>

#define LOG_FILE "flow_log.csv"
#define SPI_SPEED 1000000 // 1 MHz
#define CHANNEL 0
#define FULL_SCALE 1023
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 5.0

// Function to convert ADC value to flow rate
double adc_to_flow_rate(uint16_t adc_value) {
    if (adc_value == 0 || adc_value == FULL_SCALE) {
        return -1.0; // Sensor absent condition
    }
    double flow_rate = (adc_value / (double)FULL_SCALE) * (MAX_FLOW_RATE - MIN_FLOW_RATE) + MIN_FLOW_RATE;
    return flow_rate;
}

// Function to log the flow rate with timestamp
void log_flow_rate(double flow_rate, const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s,%f\n", timestamp, flow_rate);
    fclose(log_file);
}

// Signal handler to clean up on SIGINT or SIGTERM
void cleanup(int signum) {
    mcp3008_close(spi);
    mcp3008_deinit();
    fclose(log_file);
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    int spi_fd;
    spi_fd = mcp3008_init(SPI_SPEED, CHANNEL);
    if (spi_fd < 0) {
        perror("Failed to initialize SPI");
        fclose(log_file);
        return 1;
    }

    while (1) {
        uint16_t adc_value;
        int result = mcp3008_read(spi_fd, &adc_value);
        if (result < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        double flow_rate = adc_to_flow_rate(adc_value);
        if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
            fprintf(stderr, "Flow rate out of range: %f L/min\n", flow_rate);
            continue;
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", tv.tv_usec);

        log_flow_rate(flow_rate, timestamp);

        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    mcp3008_close(spi_fd);
    mcp3008_deinit();

    return 0;
}

