    spi_fd = mcp3008_init(SPI_SPEED, CHANNEL);
    if (spi_fd < 0) {
        perror("Failed to initialize SPI");
        fclose(log_file);
        return 1;
    }

    while (1) {
        uint16_t adc_value;
        int result = mcp3008_read(spi_fd, &adc_value);
        if (result < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        double flow_rate = adc_to_flow_rate(adc_value);
        if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
            fprintf(stderr, "Flow rate out of range: %f L/min\n", flow_rate);
            continue;
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", tv.tv_usec);

        log_flow_rate(flow_rate, timestamp);

        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    mcp3008_close(spi_fd);
    mcp3008_deinit();

    return 0;
}
