    if (signum == SIGINT) {
        stop_flag = 1;
    }
}

int read_adc(int channel) {
    int fd;
    uint8_t cmd[3] = {0x01, (channel << 6) | 0x18, 0};
    uint8_t data[3];

    fd = open(MCP3008_SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &MCP3008_SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &MCP3008_SPI_BITS) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &MCP3008_SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    if (write(fd, cmd, 3) != 3) {
        perror("Failed to write to SPI device");
        close(fd);
        return -1;
    }

    if (read(fd, data, 3) != 3) {
        perror("Failed to read from SPI device");
        close(fd);
        return -1;
    }

    close(fd);

    return ((data[1] << 8) | data[2]) & 0x03FF;
}

