#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <mcp3008.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define LOG_FILE "moisture_log.txt"

static mcp3008_t *spi;
static gpiod_chip *chip;
static gpiod_line *spi_cs;

void cleanup(int signum) {
    if (spi) {
        mcp3008_close(spi);
        spi = NULL;
    }
    if (spi_cs) {
        gpiod_line_free(spi_cs);
        spi_cs = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    exit(signum);
}

int main() {
    struct timespec delay = { .tv_sec = 60 };
    FILE *log_file;
    int adc_value;
    char timestamp[20];

    // Initialize GPIOn library
    if ((chip = gpiod_chip_open("/dev/gpiomem")) == NULL) {
        perror("Failed to open GPIOn chip");
        return EXIT_FAILURE;
    }

    // Request SPI chip select line
    if ((spi_cs = gpiod_line_request(chip, "SPI0_CE0", "MCP3008 CS", 0, GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        perror("Failed to request SPI chip select line");
        goto cleanup;
    }

    // Initialize MCP3008 SPI
    if ((spi = mcp3008_open(SPI_CHANNEL, spi_cs)) == NULL) {
        perror("Failed to open MCP3008 SPI");
        goto cleanup;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Infinite loop to read sensor
    while (1) {
        // Read ADC value
        if (mcp3008_read(spi, ADC_CHANNEL, &adc_value) != 0) {
            perror("Failed to read ADC value");
            continue;
        }

        // Check if ADC value is within valid range
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *tm = gmtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

        // Write to log file
        if (fprintf(log_file, "%s,%d\n", timestamp, adc_value) < 0) {
            perror("Failed to write to log file");
        }

        // Sleep for 60 seconds
        nanosleep(&delay, NULL);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    cleanup(0);

    return EXIT_SUCCESS;
}

