#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define CHANNEL 0
#define RETRIES 3
#define BUZZER_PIN 18
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"

int spi_fd;
int buzzer_fd;
double ambient_temp = 25.0;

void handle_sigint(int signum) {
    printf("\nReceived SIGINT (Ctrl+C). Stopping sampling loop...\n");
    close(spi_fd);
    close(buzzer_fd);
    exit(0);
}

double read_adc() {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long) &CHANNEL,
        .rx_buf = (unsigned long) &CHANNEL,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 1,
    };

    int ret;
    for (int i = 0; i < RETRIES; i++) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 1) {
            fprintf(stderr, "SPI transfer failed: %d\n", ret);
            continue;
        }

        double raw_adc = (double) CHANNEL * 1023.0 / 4095.0;
        if (raw_adc < 0.0 || raw_adc > 1023.0) {
            fprintf(stderr, "ADC value out of range, retrying...\n");
            continue;
        }

        return raw_adc;
    }

    return -1.0;
}

void read_ambient_temp() {
    FILE *file = fopen(AMBIENT_TEMP_FILE, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open ambient temperature file.\n");
        return;
    }

    if (fscanf(file, "%lf", &ambient_temp) != 1) {
        fprintf(stderr, "Failed to read ambient temperature from file.\n");
        fclose(file);
        return;
    }

    fclose(file);
}

void log_flame_data(double raw_adc, double voltage, double compensated_voltage, double temp) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S,", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
