#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE_SELECT 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW 70
#define LED_GPIO 17
#define FILE_NAME "water_levels.json"

static int spi_fd;
static struct gpiod_line *led_line;
static FILE *json_file;

void handle_signal(int signum) {
    if (spi_fd >= 0) {
        spi_close(spi_fd);
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_free(led_line);
    }
    if (json_file) {
        fclose(json_file);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct timespec sleep_duration = { .tv_sec = 0, .tv_nsec = 100000000 };
    int spi_result;
    int water_level;
    char json_object[100];
    struct tm *time_info;
    struct timespec current_time;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((spi_fd = spi_open(SPI_CHANNEL, SPI_CE_SELECT, SPI_SPEED, SPI_FLAGS)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    if ((led_line = gpiod_line_request(LED_GPIO, "LED", GPIOD_LINE_DIRECTION_OUT)) == NULL) {
        fprintf(stderr, "Failed to request GPIO line for LED\n");
        spi_close(spi_fd);
        return 1;
    }

    if ((json_file = fopen(FILE_NAME, "a")) == NULL) {
        fprintf(stderr, "Failed to open JSON file\n");
        gpiod_line_free(led_line);
        spi_close(spi_fd);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    fprintf(json_file, "[");
    fflush(json_file);

    while (1) {
        spi_result = spi_read(spi_fd, &water_level, 1);
        if (spi_result < 0) {
            fprintf(stderr, "SPI read error: %s\n", spi_perror(spi_result));
            continue;
        }

        water_level = (water_level * 100) / 1023;

        time(&current_time);
        time_info = localtime(&current_time);
        strftime(json_object, sizeof(json_object), "{\"timestamp\": \"%FT%T.%03dZ\", \"level\": %d}", time_info, (int)(current_time.tv_nsec / 1000000), water_level);

        fprintf(json_file, "%s,", json_object);
        fflush(json_file);

        if (water_level > WATER_LEVEL_THRESHOLD_HIGH) {
            gpiod_line_set_value(led_line, 1);
        } else if (water_level < WATER_LEVEL_THRESHOLD_LOW) {
            gpiod_line_set_value(led_line, 0);
        }

        nanosleep(&sleep_duration, NULL);
    }

    fclose(json_file);
    gpiod_line_free(led_line);
    spi_close(spi_fd);
    gpioTerminate();

    return 0;
}

