static gpiod_chip *chip;
static gpiod_line *cs_line;
static int spi_fd;

void cleanup(void) {
    if (cs_line) {
        gpiod_line_free(cs_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioTerminate();
}

void handle_signal(int signum) {
    cleanup();
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    FILE *file;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((chip = gpiod_chip_open("/dev/gpiomem")) == NULL) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        exit(EXIT_FAILURE);
    }

    if ((cs_line = gpiod_line_request_any(chip, "CE0", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        fprintf(stderr, "Failed to request CE0 line\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to set CE0 line value\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_10) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if ((file = fopen("airflow_log.csv", "a")) == NULL) {
        fprintf(stderr, "Failed to open airflow_log.csv\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (fseek(file, 0, SEEK_END) < 0) {
        fprintf(stderr, "Failed to seek to end of airflow_log.csv\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,Airflow (L/min)\n");
    }

    while (1) {
        uint8_t tx[3] = {0x01 << 6, 0x00, 0x00};
        uint8_t rx[3];

        if (gpiod_line_set_value(cs_line, 0) < 0) {
            fprintf(stderr, "Failed to set CE0 line value\n");
            cleanup();
            exit(EXIT_FAILURE);
        }

        ret = spi_write_read(spi_fd, tx, rx, 3);
        if (ret < 0) {
            fprintf(stderr, "SPI write/read failed\n");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_set_value(cs_line, 1) < 0) {
            fprintf(stderr, "Failed to set CE0 line value\n");
            cleanup();
            exit(EXIT_FAILURE);
        }

        uint16_t adc_value = (rx[1] << 8) | rx[2];
        double airflow = (adc_value * 5.0 / 1023.0) * 1000.0; // Assuming 5V reference and 1000 L/min full scale

        time(&ts.tv_sec);
        ts.tv_nsec = 0;
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        fprintf(file, "%s,%f\n", timestamp, airflow);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    fclose(file);
    cleanup();

    return EXIT_SUCCESS;
}

