#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 10
#define SPI_CS_GPIO 8
#define LOG_FILE "soil_moisture.log"

static int spi_fd = -1;
static int sample_interval = 1; // Default sample interval in seconds

void cleanup_spi() {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
}

void handle_signal(int signum) {
    cleanup_spi();
    exit(signum == SIGINT ? 0 : 1);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    struct spi_ioc_transfer spi_transfer;
    char timestamp[20];
    int raw_value, moisture_percentage;
    FILE *log_file;

    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval. Using default (%d seconds).\n", sample_interval);
        }
    }

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEV_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup_spi();
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup_spi();
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        cleanup_spi();
        exit(1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup_spi();
        exit(1);
    }

    while (1) {
        memset(&spi_transfer, 0, sizeof(spi_transfer));
        spi_transfer.tx_buf = (unsigned long) 0x00;
        spi_transfer.rx_buf = (unsigned long) &raw_value;
        spi_transfer.len = 3;
        spi_transfer.delay_usecs = 0;
        spi_transfer.speed_hz = SPI_SPEED;
        spi_transfer.bits_per_word = SPI_BITS;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 1) {
            perror("Failed SPI transfer");
            continue;
        }

        moisture_percentage = (raw_value * 100) / 1023;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);

        fprintf(log_file, "%s, Raw Value: %d, Moisture Percentage: %d%%\n", timestamp, raw_value, moisture_percentage);
        fflush(log_file);

        sleep(sample_interval);
    }

    fclose(log_file);
    cleanup_spi();

    return 0;
}

