    .tx_buf = (unsigned long) &spi_transfer.tx_buf,
    .rx_buf = (unsigned long) &spi_transfer.rx_buf,
    .len = 3,
    .delay_usecs = 0,
    .speed_hz = SPI_SPEED,
    .bits_per_word = SPI_BITS,
};

// SPI mode structure
struct spi_ioc_transfer spi_mode = {
