    .rx_buf = (unsigned long) &spi_mode.rx_buf,
    .len = 3,
    .delay_usecs = 0,
    .speed_hz = SPI_SPEED,
    .bits_per_word = SPI_BITS,
    .cs_change = 1,
};

// SPI configuration structure
struct spi_ioc_transfer spi_config = {
    .tx_buf = (unsigned long) &spi_config.tx_buf,
    .rx_buf = (unsigned long) &spi_config.rx_buf,
    .len = 3,
    .delay_usecs = 0,
    .speed_hz = SPI_SPEED,
    .bits_per_word = SPI_BITS,
    .cs_change = 1,
};

// SPI transfer buffer
uint8_t spi_transfer_buffer[3] = {0x01, 0x80, 0x00};

// SPI mode buffer
uint8_t spi_mode_buffer[3] = {0x01, 0x80, 0x00};

// SPI configuration buffer
uint8_t spi_config_buffer[3] = {0x01, 0x80, 0x00};

// Function to handle signals
void signal_handler(int signum) {
    printf("\nSignal %d received, cleaning up...\n", signum);
    close(spi_fd);
    exit(signum);
}

int main() {
    int spi_fd = -1;
    uint16_t adc_value = 0;
    float moisture_percentage = 0.0;

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open SPI device
    spi_fd = open(SPI_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        goto cleanup;
    }

    // Set SPI bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to read SPI bits per word");
        goto cleanup;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        goto cleanup;
    }

    // Set SPI configuration
    spi_transfer.tx_buf = (unsigned long) spi_transfer_buffer;
    spi_transfer.rx_buf = (unsigned long) &adc_value;
    spi_transfer.len = 3;
    spi_transfer.delay_usecs = 0;
    spi_transfer.speed_hz = SPI_SPEED;
    spi_transfer.bits_per_word = SPI_BITS;
    spi_transfer.cs_change = 1;

    while (1) {
        // Perform SPI transfer
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 1) {
            perror("Failed SPI transfer");
            goto cleanup;
        }

        // Calculate moisture percentage
        moisture_percentage = (adc_value / 1023.0) * 100.0;

        // Log the ADC value and moisture percentage
        printf("ADC Value: %d, Moisture Percentage: %.2f%%\n", adc_value, moisture_percentage);

        // Sleep for 5 seconds
        sleep(SPI_READ_INTERVAL / 1000);
    }

cleanup:
    // Close SPI device
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return 0;
}

