    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        goto cleanup;
    }

    // Set SPI configuration
    spi_transfer.tx_buf = (unsigned long) spi_transfer_buffer;
    spi_transfer.rx_buf = (unsigned long) &adc_value;
    spi_transfer.len = 3;
    spi_transfer.delay_usecs = 0;
    spi_transfer.speed_hz = SPI_SPEED;
    spi_transfer.bits_per_word = SPI_BITS;
    spi_transfer.cs_change = 1;

