#define PRESSURE_READ_CMD 0x00

#define PRESSURE_MIN 0
#define PRESSURE_MAX 1000

static struct gpiod_line *spi_cs;

void cleanup(int signum) {
    if (spi_cs) {
        gpiod_line_free(spi_cs);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int read_pressure() {
    int ret;
    uint8_t cmd[2] = {PRESSURE_READ_CMD, PRESSURE_SENSOR_ADDR};
    uint8_t data[2];

    ret = gpiod_line_set_value(spi_cs, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }

    ret = spi_read(SPI_DEVICE, cmd, 2, data, 2, SPI_MODE, SPI_SPEED);
    if (ret < 0) {
        perror("spi_read");
        gpiod_line_set_value(spi_cs, 1);
        return -1;
    }

    gpiod_line_set_value(spi_cs, 1);

    int pressure = (data[0] << 8) | data[1];

    if (pressure == 0 || pressure == 1023) {
        fprintf(stderr, "Sensor absent condition detected (voltage stuck at 0V or 3.3V)\n");
        return -1;
    }

    if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
        fprintf(stderr, "Out-of-range ADC value detected\n");
        return -1;
    }

    return pressure;
}

