        perror("gpiod_chip_open");
        return 1;
    }

    if (gpiod_line_get_props(spi_cs, &props) < 0) {
        perror("gpiod_line_get_props");
        return 1;
    }

    req.consumer = "pressure_sensor";
    req.request = GPIOD_LINE_REQUEST_OUTPUT;
    req.flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request_by_name(spi_cs, "8", &req) < 0) {
        perror("gpiod_line_request_by_name");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        int pressure = read_pressure();

        if (pressure >= 0) {
            printf("%s: Pressure = %d\n", ctime(&ts.tv_sec), pressure);
        }

        sleep(1);
    }

    cleanup(0);
    return 0;
}

