#include <libgpiod.h>

#define SPI_PATH "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_CS_GPIO 8
#define SPI_CS_ACTIVE_LOW 1
#define SPI_CS_POLARITY 0
#define SPI_CS_DEASSERT_AFTER_TRANSFER 1
#define SPI_CS_DEASSERT_AFTER_TRANSFER_DELAY 0
#define SPI_CHANNEL 0
#define SENSOR_ABSENT_VALUE 0
#define SENSOR_FAULT_VALUE 1023
#define SAMPLE_INTERVAL 5000 // 5 seconds

static int spi_fd = -1;
static struct gpiod_line *spi_cs_line = NULL;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (spi_cs_line != NULL) {
        gpiod_line_free(spi_cs_line);
    }
    exit(EXIT_FAILURE);
}

void handle_signal(int signum) {
    cleanup();
}

int main() {
    struct spi_ioc_transfer spi_transfer = {
        .tx_buf = (unsigned long)0,
        .rx_buf = (unsigned long)0,
        .len = SPI_BITS,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    struct gpiod_line_request request = {
        .consumer = "spi_cs",
        .flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW,
        .polarity = SPI_CS_POLARITY,
        .debounce_timeout_ns = 0,
    };

    struct gpiod_line_consumer consumer = {
        .consumer = "spi_cs",
        .flags = GPIOD_LINE_CONSUMER_DEASSERT_AFTER_TRANSFER | GPIOD_LINE_CONSUMER_DEASSERT_AFTER_TRANSFER_DELAY,
        .delay_ns = SPI_CS_DEASSERT_AFTER_TRANSFER_DELAY,
    };

    struct gpiod_line_consumer_request consumer_request = {
        .consumer = &consumer,
    };

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_fd = open(SPI_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        cleanup();
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to read SPI bits per word");
        cleanup();
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        cleanup();
    }

    spi_cs_line = gpiod_line_request(SPI_CS_GPIO, &request);
    if (spi_cs_line == NULL) {
        perror("Failed to request GPIO line");
        cleanup();
    }

    gpiod_line_consumer_request(spi_cs_line, &consumer_request);

    while (1) {
        spi_transfer.tx_buf = (unsigned long)0;
        spi_transfer.rx_buf = (unsigned long)&spi_transfer.rx_buf;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 1) {
            perror("Failed SPI transfer");
            cleanup();
        }

        unsigned int adc_value = spi_transfer.rx_buf;

        if (adc_value == SENSOR_ABSENT_VALUE || adc_value == SENSOR_FAULT_VALUE) {
            fprintf(stderr, "Sensor fault detected: ADC value is %d\n", adc_value);
        } else {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(stdout, "Timestamp: %ld.%09ld, ADC Value: %d\n", (long)ts.tv_sec, (long)ts.tv_nsec);
        }

        usleep(SAMPLE_INTERVAL * 1000); // Sleep for 5 seconds
    }

    cleanup();

    return 0;
}

