#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define SPI_TIMEOUT 100

#define MOISTURE_MAX 1023
#define MOISTURE_MIN 0
#define MOISTURE_PERCENT_MAX 100

static volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int read_adc(int fd) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long) &tr.tx_buf,
        .rx_buf = (unsigned long) &tr.rx_buf,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    return (tr.rx_buf[1] << 8) | tr.rx_buf[2];
}

int main() {
    int fd;
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction failed");
        return 1;
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0 ||
        ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to configure SPI device");
        close(fd);
        return 1;
    }

    while (!stop_flag) {
        int moisture_value = read_adc(fd);
        if (moisture_value < 0) {
            continue;
        }

        int moisture_percent = (moisture_value * MOISTURE_PERCENT_MAX) / (MOISTURE_MAX - MOISTURE_MIN);
        printf("Moisture: %d%%\n", moisture_percent);

        sleep(5);
    }

    close(fd);
    return 0;
}

