#define SPI_MODE 0
#define SPI_SPEED 1000000
#define CSV_FILE "environmental_data.csv"

struct spi_ioc_transfer spi_transfer[NUM_CHANNELS];

void handle_signal(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    close(spi_fd);
    fclose(csv_file);
    exit(0);
}

int main() {
    int spi_fd = -1;
    FILE *csv_file = NULL;
    struct spi_ioc_transfer *transfer;
    uint8_t buffer[3];
    uint16_t voltage;
    char timestamp[20];
    time_t rawtime;

    // Open SPI device
    spi_fd = open(SPI_DEV_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI mode or speed");
        close(spi_fd);
        return 1;
    }

    // Open CSV file for writing
    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(spi_fd);
        return 1;
    }

    // Set up SPI transfers
    for (int i = 0; i < NUM_CHANNELS; i++) {
        transfer = &spi_transfer[i];
        transfer->tx_buf = (unsigned long)buffer;
        transfer->rx_buf = (unsigned long)buffer + 1;
        transfer->len = 3;
        transfer->delay_usecs = 0;
        transfer->speed_hz = SPI_SPEED;
        transfer->bits_per_word = 8;
        transfer->cs_change = 1;
        transfer->tx_nbits = 1;
        transfer->rx_nbits = 12;
        transfer->pad = 0;
        transfer->csc = i;
    }

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer[i]) < 1) {
                perror("Failed SPI transfer");
                break;
            }

            // Convert ADC value to voltage
            voltage = (buffer[1] << 8) | buffer[2];
            voltage = (voltage * 3.3) / 4096;

            // Log timestamp and voltage
            time(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&rawtime));
            fprintf(csv_file, "%s,%d,%f\n", timestamp, i, voltage);
        }

        usleep(1000000); // Sleep for 1 second
    }

    // Cleanup on exit
    fclose(csv_file);
    close(spi_fd);

    return 0;
}

