#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define BUFFER_SIZE 20
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define SPI_CE0 0
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11
#define GPIO_RELAY 17

typedef struct {
    int moisture_reading;
    time_t timestamp;
    int pump_state;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;
int pump_state = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_release(spi_fd);
        gpiod_release(relay_fd);
        gpioTerminate();
        exit(0);
    }
}

int read_adc(int channel) {
    uint8_t cmd[3] = {0x01, (channel << 6) | 0x18, 0x00};
    uint8_t data[3];

    if (gpiod_spi_transfer(spi_fd, cmd, data, 3) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int adc_value = ((data[1] & 0x0F) << 8) | data[2];
    return adc_value;
}

void log_entry(int moisture_reading, int pump_state) {
    time_t now = time(NULL);
    log_buffer[buffer_index].moisture_reading = moisture_reading;
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].pump_state = pump_state;

    printf("Moisture Reading: %d, Timestamp: %s, Pump State: %s\n",
           log_buffer[buffer_index].moisture_reading, ctime(&now),
           log_buffer[buffer_index].pump_state ? "On" : "Off");

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        perror("GPIO initialization failed");
        return 1;
    }

    gpiod_chip *chip = gpiod_chip_open(SPI_CE0);
    if (!chip) {
        perror("Failed to open SPI chip");
        return 1;
    }

    spi_fd = gpiod_chip_get_spi(chip, SPI_CHANNEL);
    if (!spi_fd) {
        perror("Failed to get SPI device");
        return 1;
    }

    if (gpiod_spi_open(spi_fd, GPIO_MOSI, GPIO_MISO, GPIO_SCLK, SPI_SPEED, SPI_MODE) < 0) {
        perror("Failed to open SPI interface");
        return 1;
    }

    gpiod_line *relay_line = gpiod_line_request(chip, GPIO_RELAY, "Relay", 0, GPIOD_LINE_DIRECTION_OUTPUT);
    if (!relay_line) {
        perror("Failed to request GPIO line for relay");
        return 1;
    }

    relay_fd = gpiod_line_get_line(relay_line);
    if (!relay_fd) {
        perror("Failed to get GPIO line for relay");
        return 1;
    }

    while (1) {
        int moisture_reading = read_adc(0);
        if (moisture_reading < 0) {
            continue;
        }

        if (moisture_reading < LOW_THRESHOLD && pump_state == 0) {
            gpiod_line_set_value(relay_fd, 1);
            pump_state = 1;
            log_entry(moisture_reading, pump_state);
        } else if (moisture_reading > HIGH_THRESHOLD && pump_state == 1) {
            gpiod_line_set_value(relay_fd, 0);
            pump_state = 0;
            log_entry(moisture_reading, pump_state);
        } else {
            log_entry(moisture_reading, pump_state);
        }

        sleep(5);
    }

    return 0;
}

