#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define MAX30102_ADDR 0x57
#define MAX30102_PART_ID 0x00
#define MAX30102_SPO2 0x04
#define MAX30102_HR 0x06
#define MAX30102_MAX_VALUE 0xFF
#define MAX30102_MIN_SPO2 95
#define MAX30102_MAX_HR 100

static FILE *log_file;
static i2c_t *i2c_handle;

void handle_signal(int signum) {
    if (i2c_handle) {
        i2c_close(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

void init_logging() {
    log_file = fopen("health_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(1);
    }
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle) {
        i2c_close(i2c_handle);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        exit(1);
    }

    i2c_handle = i2c_open(1, MAX30102_ADDR, 0);
    if (i2c_handle == NULL) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    uint8_t part_id;
    if (i2c_read_device(i2c_handle, MAX30102_PART_ID, &part_id, 1) != 1) {
        perror("Failed to read Part ID register");
        cleanup();
        exit(1);
    }

    if (part_id != 0x30102) {
        fprintf(stderr, "MAX30102 sensor not found\n");
        cleanup();
        exit(1);
    }

    init_logging();

    while (1) {
        uint8_t spo2, hr;
        if (i2c_read_device(i2c_handle, MAX30102_SPO2, &spo2, 1) != 1 ||
            i2c_read_device(i2c_handle, MAX30102_HR, &hr, 1) != 1) {
            perror("Failed to read SpO2 or HR");
            cleanup();
            exit(1);
        }

        if (spo2 < MAX30102_MIN_SPO2 || hr > MAX30102_MAX_HR) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);
            fprintf(log_file, "%s - SpO2: %u, HR: %u\n", timestamp, spo2, hr);
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

