#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x48 // ADS1115 address with A0 grounded
#define I2C_DEV "/dev/i2c-1"
#define GPIO_RELAY 17
#define GPIO_REED 27
#define RELAY_ON 1
#define RELAY_OFF 0
#define THRESHOLD 1000 // Example threshold, adjust as needed
#define LOG_FILE "/var/log/door_events.log"

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    if (write(fd, buf, len + 1) != len + 1) {
        perror("i2c_read: write");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("i2c_read: read");
        return -1;
    }
    memcpy(data, buf + 1, len);
    return 0;
}

// GPIO setup function
int setup_gpios(void) {
    int fd;
    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("setup_gpios: open export");
        return -1;
    }
    if (write(fd, "17", 2) != 2) {
        perror("setup_gpios: write relay");
        close(fd);
        return -1;
    }
    close(fd);

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("setup_gpios: open export");
        return -1;
    }
    if (write(fd, "27", 2) != 2) {
        perror("setup_gpios: write reed");
        close(fd);
        return -1;
    }
    close(fd);

    fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (fd < 0) {
        perror("setup_gpios: open relay direction");
        return -1;
    }
    if (write(fd, "out", 3) != 3) {
        perror("setup_gpios: write relay direction");
        close(fd);
        return -1;
    }
    close(fd);

    fd = open("/sys/class/gpio/gpio27/direction", O_WRONLY);
    if (fd < 0) {
        perror("setup_gpios: open reed direction");
        return -1;
    }
    if (write(fd, "in", 2) != 2) {
        perror("setup_gpios: write reed direction");
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

// GPIO cleanup function
void cleanup_gpios(void) {
    int fd;
    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("cleanup_gpios: open unexport");
        return;
    }
    if (write(fd, "17", 2) != 2) {
        perror("cleanup_gpios: write relay unexport");
    }
    if (write(fd, "27", 2) != 2) {
        perror("cleanup_gpios: write reed unexport");
    }
    close(fd);
}

// ADC read function
int read_adc(int fd) {
    uint8_t data[2];
    if (i2c_read(fd, 0x00, data, 2) < 0) {
        return -1;
    }
    return (data[0] << 8) | data[1];
}

// Main function
int main(void) {
    int fd;
    int adc_value;
    int baseline_sum = 0;
    int baseline_count = 0;
    int baseline_avg = 0;
    int relay_state = RELAY_OFF;
    int reed_state = 0;
    struct timespec ts;
    struct timespec ts_start;
    struct timespec ts_end;
    FILE *log_file;

    // Open I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("main: open i2c");
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("main: i2c_slave");
        close(fd);
        return 1;
    }

    // Setup GPIOs
    if (setup_gpios() < 0) {
        close(fd);
        return 1;
    }

    // Initial calibration phase
    for (int i = 0; i < 10; i++) {
        adc_value = read_adc(fd);
        if (adc_value < 0) {
            printf("Sensor absent, continuing...\n");
            continue;
        }
        baseline_sum += adc_value;
        baseline_count++;
        usleep(50000); // 50 ms
    }
    baseline_avg = baseline_sum / baseline_count;

    // Main loop
    while (1) {
        adc_value = read_adc(fd);
        if (adc_value < 0) {
            printf("Sensor absent, continuing...\n");
            continue;
        }

        if (adc_value < baseline_avg - THRESHOLD) {
            if (relay_state == RELAY_OFF) {
                relay_state = RELAY_ON;
                printf("Triggering relay...\n");
                fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
                if (fd < 0) {
                    perror("main: open relay value");
                    continue;
                }
                if (write(fd, "1", 1) != 1) {
                    perror("main: write relay on");
                    close(fd);
                    continue;
                }
                close(fd);
                usleep(3000000); // 3 seconds
                fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
                if (fd < 0) {
                    perror("main: open relay value");
                    continue;
                }
                if (write(fd, "0", 1) != 1) {
                    perror("main: write relay off");
                    close(fd);
                    continue;
                }
                close(fd);
                relay_state = RELAY_OFF;
            }
        }

        // Read reed sensor
        fd = open("/sys/class/gpio/gpio27/value", O_RDONLY);
        if (fd < 0) {
            perror("main: open reed value");
            continue;
        }
        if (read(fd, &reed_state, 1) != 1) {
            perror("main: read reed value");
            close(fd);
            continue;
        }
        close(fd);

        // Log event
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("main: fopen log file");
            continue;
        }
        ts.tv_sec = time(NULL);
        ts.tv_nsec = 0;
        fprintf(log_file, "%ld.%09ld: ", ts.tv_sec, ts.tv_nsec);
        if (reed_state == 0) {
            fprintf(log_file, "door opened\n");
        } else {
            fprintf(log_file, "door not opened\n");
        }
        fclose(log_file);

        // Sleep for 200 ms
        ts_start.tv_sec = 0;
        ts_start.tv_nsec = 0;
        ts_end.tv_sec = 0;
        ts_end.tv_nsec = 200000000; // 200 ms
        nanosleep(&ts_start, &ts_end);
    }

    // Cleanup
    cleanup_gpios();
    close(fd);
    return 0;
}

