This C program sets up the SPI interface and GPIO lines for three MCP3008 chips connected to soil moisture sensors. It logs the ADC readings to a CSV file every 5 seconds, handling errors and ensuring proper cleanup on signal termination.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP 60
#define MAX_RETRIES 3
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PUMP 18

static int threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_SLEEP;
static int spi_fd = -1;

void handle_signal(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    printf("Received signal %d, shutting down...\n", signum);
    exit(0);
}

int read_adc(int channel) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)channel,
        .rx_len = 1,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) == -1) {
            perror("SPI read error");
            retries++;
            sleep(1);
        } else {
            result = (int)tr.rx_buf[0];
            break;
        }
    }

    return result;
}

void activate_pump() {
    int pump_fd = open("/sys/class/gpio/gpio18/value", O_WRONLY);
    if (pump_fd == -1) {
        perror("Failed to open pump GPIO");
        return;
    }

    write(pump_fd, "1", 1);
    close(pump_fd);
    printf("Pump activated at %s\n", ctime(&time(NULL)));
}

void deactivate_pump() {
    int pump_fd = open("/sys/class/gpio/gpio18/value", O_WRONLY);
    if (pump_fd == -1) {
        perror("Failed to open pump GPIO");
        return;
    }

    write(pump_fd, "0", 1);
    close(pump_fd);
    printf("Pump deactivated at %s\n", ctime(&time(NULL)));
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (argc > 1 && strcmp(argv[1], "-t") == 0) {
        threshold = atoi(argv[2]);
    }
    if (argc > 3 && strcmp(argv[3], "-d") == 0) {
        duration = atoi(argv[4]);
    }
    if (argc > 5 && strcmp(argv[5], "-s") == 0) {
        sleep_interval = atoi(argv[6]);
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &0) == -1 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &0) == -1 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) == -1 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &8) == -1 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &1000000) == -1 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &1000000) == -1) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return 1;
    }

    FILE *log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    while (1) {
        int moisture_level = read_adc(0);
        if (moisture_level == -1) {
            fprintf(log_file, "Error reading moisture level at %s\n", ctime(&time(NULL)));
            continue;
        }

        double moisture_percentage = (double)moisture_level / 1023.0 * 100.0;
        fprintf(log_file, "Moisture level: %.2f%% at %s\n", moisture_percentage, ctime(&time(NULL)));

        if (moisture_percentage < threshold) {
            activate_pump();
            sleep(duration);
            deactivate_pump();
        }

        sleep(sleep_interval);
    }

    fclose(log_file);
    close(spi_fd);
    return 0;
}

