#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <mcp3008.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define CHANNEL 0
#define THRESHOLD 500
#define LOG_FILE "/var/log/sound_events.log"

static struct gpiod_line *spi_cs;
static struct mcp3008_dev *mcp3008;

void cleanup(int signum) {
    if (spi_cs) {
        gpiod_line_free(spi_cs);
    }
    if (mcp3008) {
        mcp3008_free(mcp3008);
    }
    exit(signum);
}

int main() {
    struct gpiod_line_request *req;
    struct gpiod_line_consumer *consumer;
    struct mcp3008_dev *dev;
    int ret;
    int value;
    char timestamp[20];
    FILE *log_file;

    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize SPI
    if ((ret = gpiod_line_request_new("/sys/class/gpio/gpio8/request", &req)) < 0) {
        perror("gpiod_line_request_new");
        exit(EXIT_FAILURE);
    }
    if ((ret = gpiod_line_request_set_consumer(req, "SPI CS", &consumer)) < 0) {
        perror("gpiod_line_request_set_consumer");
        gpiod_line_request_free(req);
        exit(EXIT_FAILURE);
    }
    if ((ret = gpiod_line_request_enable(req)) < 0) {
        perror("gpiod_line_request_enable");
        gpiod_line_request_free(req);
        exit(EXIT_FAILURE);
    }
    spi_cs = gpiod_line_request_get_line(req);

    if ((ret = gpiod_line_export(spi_cs)) < 0) {
        perror("gpiod_line_export");
        gpiod_line_request_free(req);
        exit(EXIT_FAILURE);
    }

    if ((ret = gpiod_line_request_set_function(req, GPIOD_LINE_FUNCTION_OUTPUT)) < 0) {
        perror("gpiod_line_request_set_function");
        gpiod_line_request_free(req);
        exit(EXIT_FAILURE);
    }

    if ((ret = gpiod_line_request_set_value(req, 1)) < 0) {
        perror("gpiod_line_request_set_value");
        gpiod_line_request_free(req);
