#define I2C_ADDR 0x48 // PCF8591 I2C address
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_INTERVAL 100 // 100 ms

int i2c_fd;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(1);
}

int main() {
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg msg[2];

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install SIGINT handler");
        close(i2c_fd);
        return 1;
    }

    // Initialize I2C message structure
    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = malloc(msg[0].len);
    msg[0].buf[0] = 0x40; // Start conversion on AIN0

    msg[1].addr = I2C_ADDR;
    msg[1].flags = 0;
    msg[1].len = 1;
    msg[1].buf = malloc(msg[1].len);

    // Infinite loop to sample AIN0
    while (1) {
        // Perform dummy read
        i2c_data.msgs = msg;
        i2c_data.nmsgs = 2;
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
            perror("Failed to perform I2C read");
            free(msg[0].buf);
            free(msg[1].buf);
            close(i2c_fd);
            return 1;
        }

        // Read current sample
        msg[1].buf[0] = 0x41; // Read AIN0
        i2c_data.msgs = msg;
        i2c_data.nmsgs = 2;
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
            perror("Failed to perform I2C read");
            free(msg[0].buf);
            free(msg[1].buf);
            close(i2c_fd);
            return 1;
        }

        // Print the sample value
        printf("AIN0 sample: %d\n", msg[1].buf[0]);

        // Sleep for 100 ms
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    free(msg[0].buf);
    free(msg[1].buf);
    close(i2c_fd);

    return 0;
}

