#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>

#define ADC_BASE 0x20
#define ADC_SPI_CS 0x00
#define ADC_SPI_CLK 0x01
#define ADC_SPI_DOUT 0x02
#define ADC_SPI_DIN 0x03

#define GPIO_BASE 0x2020C000
#define GPIO_SET 0x2020C004
#define GPIO_CLR 0x2020C008
#define GPIO_LEV0 0x2020C01C

#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define SPI_CS 0

#define THRESHOLD 300
#define WATERING_INTERVAL 60
#define PUMP_DURATION 10

volatile unsigned *spi_base;
volatile unsigned *gpio_base;

void spi_init() {
    int fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open /dev/mem");
        exit(EXIT_FAILURE);
    }

    spi_base = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, ADC_BASE);
    if (spi_base == MAP_FAILED) {
        perror("Failed to mmap ADC base");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
}

void spi_deinit() {
    if (spi_base != MAP_FAILED) {
        munmap(spi_base, 4096);
    }
}

void spi_transfer(unsigned char data) {
    unsigned char result = 0;

    spi_base[ADC_SPI_CS] = SPI_CS;
    spi_base[ADC_SPI_CLK] = 0;
    spi_base[ADC_SPI_DOUT] = data;

    for (int i = 0; i < 8; i++) {
        spi_base[ADC_SPI_CLK] = 1;
        result = (result << 1) | (spi_base[ADC_SPI_DIN] & 1);
        spi_base[ADC_SPI_CLK] = 0;
    }

    spi_base[ADC_SPI_CS] = 0;

    return result;
}

void spi_read_adc(int channel) {
    unsigned char cmd = (channel << 6) | 0x18;
    unsigned char result = 0;

    spi_transfer(cmd);
    result = spi_transfer(0);
    result = spi_transfer(0);

    return result;
}

void gpio_init() {
    int fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open /dev/mem");
        exit(EXIT_FAILURE);
    }

    gpio_base = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, GPIO_BASE);
    if (gpio_base == MAP_FAILED) {
        perror("Failed to mmap GPIO base");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);

    // Set GPIO18 as output
    gpio_base[GPIO_SET] = (1 << 18);
}

void gpio_deinit() {
    if (gpio_base != MAP_FAILED) {
        munmap(gpio_base, 4096);
    }
}

void activate_pump() {
    gpio_base[GPIO_SET] = (1 << 18);
}

void deactivate_pump() {
    gpio_base[GPIO_CLR] = (1 << 18);
}

void handle_signal(int signum) {
    deactivate_pump();
    spi_deinit();
    gpio_deinit();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_init();
    gpio_init();

    FILE *file = fopen("watering_events.txt", "a");
    if (file == NULL) {
        perror("Failed to open file");
        spi_deinit();
        gpio_deinit();
        exit(EXIT_FAILURE);
    }

    while (1) {
        unsigned char adc_value = spi_read_adc(SPI_CHANNEL);

        if (adc_value < THRESHOLD) {
            activate_pump();
            fprintf(file, "Watering event at %s, moisture level: %d\n", ctime(&time(NULL)), adc_value);
            fflush(file);
            sleep(PUMP_DURATION);
            deactivate_pump();
        }

        sleep(WATERING_INTERVAL);
    }

    fclose(file);
    spi_deinit();
    gpio_deinit();

    return EXIT_SUCCESS;
}

