#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_CS_HIGH 0
#define SPI_LOOP 0
#define SPI_TX_BUF_LEN 3
#define SPI_RX_BUF_LEN 3

#define FULL_SCALE_ADC_VALUE 1023
#define RAIN_INTENSITY_THRESHOLD 500

static int spi_fd = -1;

void handle_sigint(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

int init_spi() {
    struct spi_ioc_transfer spi_transfer;
    struct spi_ioc_transfer *transfers = malloc(sizeof(struct spi_ioc_transfer));

    spi_fd = open(SPI_DEV_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        goto error;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        goto error;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set bits per word");
        goto error;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to read bits per word");
        goto error;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        goto error;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        goto error;
    }

    memset(transfers, 0, sizeof(struct spi_ioc_transfer));
    transfers->tx_buf = (unsigned long)malloc(SPI_TX_BUF_LEN * sizeof(unsigned char));
    transfers->rx_buf = (unsigned long)malloc(SPI_RX_BUF_LEN * sizeof(unsigned char));
    transfers->len = SPI_TX_BUF_LEN;
    transfers->delay_usecs = 0;
    transfers->speed_hz = SPI_SPEED;
    transfers->bits_per_word = SPI_BITS;
    transfers->cs_change = SPI_CS_HIGH;
    transfers->loop = SPI_LOOP;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) < 1) {
        perror("Failed to send SPI message");
        goto error;
    }

    free(transfers->tx_buf);
    free(transfers->rx_buf);
    free(transfers);

    return 0;

error:
    if (spi_fd != -1) {
        close(spi_fd);
    }
    return -1;
