This C program reads a potentiometer connected to an MCP3008 ADC via the SPI0 bus on a Raspberry Pi. It initializes the SPI interface, reads the ADC value, and updates the PWM output on GPIO18 based on the ADC reading. The program runs in a loop, reading the ADC and updating the PWM every 100 milliseconds. It also handles SIGINT and SIGTERM signals to stop the PWM output and release resources before exiting.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define DEFAULT_THRESHOLD 100.0
#define I2C_ADDR 0x48
#define I2C_BUS 1
#define ADC_PGA_GAIN 4.096
#define ADC_SAMPLE_RATE 860
#define ADC_CHANNEL 0
#define GPIO_LED 17
#define LED_ON_TIME 50
#define LED_OFF_TIME 50
#define BLINK_DURATION 1000

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate(); // Release GPIO resources

    exit(EXIT_SUCCESS);
}

void blink_led(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    for (int i = 0; i < 2; i++) {
        gpioWrite(GPIO_LED, 1);
        usleep(LED_ON_TIME * 1000);
        gpioWrite(GPIO_LED, 0);
        usleep(LED_OFF_TIME * 1000);
    }

    gpioTerminate();
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    int i2c_fd;
    int adc_data;

    if (argc > 1 && strcmp(argv[1], "-t") == 0) {
        if (argc < 3) {
            fprintf(stderr, "Missing threshold value after -t\n");
            return EXIT_FAILURE;
        }

        threshold = atof(argv[2]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (write(i2c_fd, "86", 1) != 1) {
            fprintf(stderr, "Failed to write to ADC\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        if (read(i2c_fd, &adc_data, 2) != 2) {
            fprintf(stderr, "Failed to read from ADC\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        double voltage = (double)adc_data * (ADC_PGA_GAIN / 32767.0);
        double gauss = voltage / 0.0001; // Assuming 1V = 10000 Gauss

        printf("Magnetic field strength: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            blink_led();
        }

        usleep(100000); // 100 ms delay
    }

    close(i2c_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

