#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <mraa/aio.h>
#include <mraa/spi.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define HUMIDITY_THRESHOLD_LOW 30
#define HUMIDITY_THRESHOLD_HIGH 35
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"

static int spi_fd = -1;
static int relay_pin = 17;
static int pump_state = 0;
static mraa_aio_context aio_context;
static mosquitto *mosq;
static int mosq_sub_id;

void handle_signal(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);
    if (spi_fd != -1) {
        close(spi_fd);
        syslog(LOG_INFO, "Closed SPI interface.");
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        syslog(LOG_INFO, "Disconnected from MQTT and destroyed client.");
    }
    if (aio_context) {
        mraa_aio_close(aio_context);
        syslog(LOG_INFO, "Closed AIO context.");
    }
    exit(0);
}

void spi_transfer(uint8_t *tx, uint8_t *rx, uint8_t length) {
    int ret;
    if ((ret = spi_write(spi_fd, tx, length)) != length) {
        syslog(LOG_ERR, "SPI transfer failed: %d", ret);
        exit(1);
    }
    if ((ret = spi_read(spi_fd, rx, length)) != length) {
        syslog(LOG_ERR, "SPI read failed: %d", ret);
        exit(1);
    }
}

void read_sensor() {
    uint8_t tx[3] = {0x01, 0x80 | SPI_CHANNEL, 0x00};
    uint8_t rx[3];
    spi_transfer(tx, rx, 3);
    int adc_value = ((rx[1] << 8) | rx[2]) >> 4;
    double voltage = adc_value * 3.3 / 1024.0;
    double humidity = voltage * 100;
    syslog(LOG_INFO, "Moisture: %.2f%%", humidity);

    if (humidity < HUMIDITY_THRESHOLD_LOW && pump_state == 0) {
        syslog(LOG_INFO, "Activating pump.");
        if (gpioWrite(relay_pin, PI_ON) != 0) {
            syslog(LOG_ERR, "Failed to activate pump.");
        } else {
            pump_state = 1;
        }
    } else if (humidity > HUMIDITY_THRESHOLD_HIGH && pump_state == 1) {
        syslog(LOG_INFO, "Deactivating pump.");
        if (gpioWrite(relay_pin, PI_OFF) != 0) {
            syslog(LOG_ERR, "Failed to deactivate pump.");
        } else {
            pump_state = 0;
        }
    }

    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL_MOISTURE, &humidity, 4, 0, 0) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture value to MQTT.");
    }
}

void mosq_callback(struct mosquitto *mosq, void *obj, int message_id, int qos, const char *topic, const char *payload, int payload_len) {
    if (strcmp(topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
        if (strcmp(payload, "pump_on") == 0) {
            syslog(LOG_INFO, "Received 'pump_on' command.");
            if (gpioWrite(relay_pin, PI_ON) != 0) {
                syslog(LOG_ERR, "Failed to activate pump.");
            } else {
                pump_state = 1;
            }
        } else if (strcmp(payload, "pump_off") == 0) {
            syslog(LOG_INFO, "Received 'pump_off' command.");
            if (gpioWrite(relay_pin, PI_OFF) != 0) {
                syslog(LOG_ERR, "Failed to deactivate pump.");
            } else {
                pump_state = 0;
            }
        } else {
            syslog(LOG_INFO, "Received unknown command: %s", payload);
        }
    }
}

