        syslog(LOG_ERR, "Failed to open SPI device.");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode.");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE_0) < 0) {
        syslog(LOG_ERR, "Failed to read SPI mode.");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD_8) < 0) {
        syslog(LOG_ERR, "Failed to set bits per word.");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS_PER_WORD_8) < 0) {
        syslog(LOG_ERR, "Failed to read bits per word.");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        syslog(LOG_ERR, "Failed to set SPI speed.");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        syslog(LOG_ERR, "Failed to read SPI speed.");
        return 1;
    }

    if ((aio_context = mraa_aio_init(0)) == NULL) {
        syslog(LOG_ERR, "Failed to initialize AIO context.");
        return 1;
    }

    if ((mosq = mosquitto_new("soil_moisture_monitor", true, NULL)) == NULL) {
        syslog(LOG_ERR, "Failed to create MQTT client.");
        return 1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_disconnect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, mosq_callback);

    if (mosquitto_connect(mosq, "broker.example.com", 1883, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker.");
        return 1;
    }

    if (mosquitto_subscribe(mosq, &mosq_sub_id, MQTT_TOPIC_PUMP_CONTROL, 0) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic.");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_sensor();
        sleep(60);
    }

    return 0;
}

