#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEV_PATH "/dev/spidev0.0"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_BITS 10
#define VDD 3.3 // 3.3V

static volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int main() {
    int fd;
    struct spi_ioc_transfer tr;
    uint8_t tx_buf[2] = {0x01, 0x80}; // Channel 0, start bit
    uint8_t rx_buf[2];
    double voltage;

    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Open SPI device
    fd = open(SPI_DEV_PATH, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return 1;
    }
    if (ioctl(fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        close(fd);
        return 1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return 1;
    }
    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        close(fd);
        return 1;
    }

    // Configure SPI transfer
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 2;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS;

    // Read ADC value in a loop
    while (!stop_flag) {
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
            perror("Failed to send SPI message");
            close(fd);
            return 1;
        }

        // Calculate voltage
        uint16_t raw_value = (rx_buf[1] << 8) | rx_buf[0];
        voltage = (double)raw_value * VDD / 1024.0;

        printf("Raw Value: %d, Voltage: %.2f V\n", raw_value, voltage);

        usleep(500000); // Sleep for 500 ms
    }

    // Clean up
    close(fd);
    return 0;
}

