#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libmcp3008.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS 0
#define FILE_NAME "sensor_data.csv"
#define INTERVAL 5

mcp3008_t *mcp3008;
FILE *file;

void handle_signal(int signum) {
    if (file) {
        fclose(file);
    }
    if (mcp3008) {
        mcp3008_close(mcp3008);
    }
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    mcp3008 = mcp3008_init(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_CS);
    if (!mcp3008) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        return EXIT_FAILURE;
    }

    file = fopen(FILE_NAME, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file %s\n", FILE_NAME);
        mcp3008_close(mcp3008);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_values[3];
        char timestamp[20];
        time_t rawtime;
        struct tm *timeinfo;

        if (mcp3008_read_adc(mcp3008, 0, &adc_values[0]) != 0) {
            fprintf(stderr, "Failed to read ADC channel 0\n");
            goto cleanup;
        }
        if (mcp3008_read_adc(mcp3008, 1, &adc_values[1]) != 0) {
            fprintf(stderr, "Failed to read ADC channel 1\n");
            goto cleanup;
        }
        if (mcp3008_read_adc(mcp3008, 2, &adc_values[2]) != 0) {
            fprintf(stderr, "Failed to read ADC channel 2\n");
            goto cleanup;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (fprintf(file, "%s,%d,%d,%d\n", timestamp, adc_values[0], adc_values[1], adc_values[2]) == -1) {
            fprintf(stderr, "Failed to write to file %s\n", FILE_NAME);
            goto cleanup;
        }

        fflush(file);
        sleep(INTERVAL);
    }

cleanup:
    if (file) {
        fclose(file);
    }
    if (mcp3008) {
        mcp3008_close(mcp3008);
    }
    return EXIT_FAILURE;
}

