    while (1) {
        uint16_t adc_values[3];
        char timestamp[20];
        time_t rawtime;
        struct tm *timeinfo;

        if (mcp3008_read_adc(mcp3008, 0, &adc_values[0]) != 0) {
            fprintf(stderr, "Failed to read ADC channel 0\n");
            goto cleanup;
        }
        if (mcp3008_read_adc(mcp3008, 1, &adc_values[1]) != 0) {
            fprintf(stderr, "Failed to read ADC channel 1\n");
            goto cleanup;
        }
        if (mcp3008_read_adc(mcp3008, 2, &adc_values[2]) != 0) {
            fprintf(stderr, "Failed to read ADC channel 2\n");
            goto cleanup;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (fprintf(file, "%s,%d,%d,%d\n", timestamp, adc_values[0], adc_values[1], adc_values[2]) == -1) {
            fprintf(stderr, "Failed to write to file %s\n", FILE_NAME);
            goto cleanup;
        }

        fflush(file);
        sleep(INTERVAL);
    }

cleanup:
    if (file) {
        fclose(file);
    }
    if (mcp3008) {
        mcp3008_close(mcp3008);
    }
    return EXIT_FAILURE;
}
