#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_BITS 8
#define MOTOR_GPIO17 17
#define MOTOR_GPIO27 27
#define MOTOR_PWM_FREQ 100 // 100 Hz
#define MOTOR_PWM_DUTY_MAX 100
#define NOISE_THRESHOLD 500
#define LOG_FILE "vibration_log.txt"

int spi_fd;
int motor_pwm_fd[2];

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received SIGINT or SIGTERM, shutting down...\n");
        close(spi_fd);
        for (int i = 0; i < 2; i++) {
            close(motor_pwm_fd[i]);
        }
        exit(0);
    }
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = SPI_BITS,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &tr.mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &tr.mode) < 0) {
        perror("Failed to read SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &tr.bits_per_word) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &tr.bits_per_word) < 0) {
        perror("Failed to read bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &tr.speed_hz) < 0) {
        perror("Failed to set max speed");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &tr.speed_hz) < 0) {
        perror("Failed to read max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(int channel) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)&channel,
        .len = SPI_BITS,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    if (write(spi_fd, &tr, sizeof(tr)) < 0) {
        perror("Failed to write SPI transfer");
        return -1;
    }

    if (read(spi_fd, &channel, SPI_BITS / 8) < 0) {
        perror("Failed to read ADC value");
        return -1;
    }

    return channel;
}

int init_motor_pwm(int gpio) {
    char filename[32];
    snprintf(filename, sizeof(filename), "/sys/class/gpio/gpio%d/pwm", gpio);

    int fd = open(filename, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM file");
        return -1;
    }

    if (write(fd, "enable", 7) < 0) {
        perror("Failed to enable PWM");
        close(fd);
        return -1;
    }

    snprintf(filename, sizeof(filename), "/sys/class/gpio/gpio%d/pwm/period", gpio);
    fd = open(filename, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM period file");
        close(fd);
        return -1;
    }

    if (write(fd, "10000", 5) < 0) {
        perror("Failed to set PWM period");
        close(fd);
        return -1;
    }

    snprintf(filename, sizeof(filename), "/sys/class/gpio/gpio%d/pwm/duty_cycle", gpio);
    fd = open(filename, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM duty cycle file");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_spi() < 0) {
        return 1;
    }

    motor_pwm_fd[0] = init_motor_pwm(MOTOR_GPIO17);
    if (motor_pwm_fd[0] < 0) {
        close(spi_fd);
        return 1;
    }

    motor_pwm_fd[1] = init_motor_pwm(MOTOR_GPIO27);
    if (motor_pwm_fd[1] < 0) {
        close(spi_fd);
        close(motor_pwm_fd[0]);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        close(motor_pwm_fd[0]);
        close(motor_pwm_fd[1]);
        return 1;
    }

    while (1) {
        int noise_level = read_adc(0);
        if (noise_level < 0) {
            continue; // Skip iteration on ADC read error
        }

        if (noise_level > NOISE_THRESHOLD) {
            for (int i = 0; i < 2; i++) {
                char filename[32];
                snprintf(filename, sizeof(filename), "/sys/class/gpio/gpio%d/pwm/duty_cycle", MOTOR_GPIO17 + i);
                int fd = open(filename, O_WRONLY);
                if (fd < 0) {
                    perror("Failed to open PWM duty cycle file");
                    continue;
                }

                if (write(fd, "5000", 5) < 0) {
                    perror("Failed to set PWM duty cycle");
                    close(fd);
                    continue;
                }

                close(fd);
            }

            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d\n", now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday, now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);
        } else {
            for (int i = 0; i < 2; i++) {
                char filename[32];
                snprintf(filename, sizeof(filename), "/sys/class/gpio/gpio%d/pwm/duty_cycle", MOTOR_GPIO17 + i);
                int fd = open(filename, O_WRONLY);
                if (fd < 0) {
                    perror("Failed to open PWM duty cycle file");
                    continue;
                }

                if (write(fd, "0", 1) < 0) {
                    perror("Failed to set PWM duty cycle");
                    close(fd);
                    continue;
                }

                close(fd);
            }
        }

        usleep(10000); // Sleep for 10 ms
    }

    fclose(log_file);
    close(spi_fd);
    close(motor_pwm_fd[0]);
    close(motor_pwm_fd[1]);

    return 0;
}

