#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <mcp3008.h>
#include <i2c-dev.h>

#define MAX9814_I2C_ADDR 0x19
#define BH1750_I2C_ADDR 0x23
#define SPI_DEV "/dev/spidev0.0"
#define I2C_DEV "/dev/i2c-1"
#define LOG_FILE "tamper_log.csv"

int spi_fd;
int i2c_fd;

void handle_signal(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    fclose(stdout);
    exit(signum);
}

int read_max9814(void) {
    int error_code = 0;
    int sound_level_db = 0;

    // Read from MCP3008 ADC
    if (mcp3008_read(spi_fd, 0) != 0) {
        error_code = 1;
    } else {
        sound_level_db = mcp3008_read(spi_fd, 0);
    }

    return error_code;
}

int read_bh1750(void) {
    int error_code = 0;
    uint8_t data[2];

    // Write command to BH1750
    if (write(i2c_fd, "\x00", 1) != 1) {
        error_code = 2;
    }

    // Wait 180ms
    usleep(180000);

    // Read data from BH1750
    if (read(i2c_fd, data, 2) != 2) {
        error_code = 3;
    } else {
        int light_level_lux = (data[0] << 8) | data[1];
        // Assuming conversion to lux is done here
    }

    return error_code;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd == -1) {
        perror("open SPI");
        return 1;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd == -1) {
        perror("open I2C");
        close(spi_fd);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        int sound_error = read_max9814();
        int light_error = read_bh1750();

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d, %d\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                sound_error, light_error, 0); // Assuming 0 for error_code

        fflush(log_file);
        sleep(5);
    }

    fclose(log_file);
    close(spi_fd);
    close(i2c_fd);

    return 0;
}

