#include <libgpiod.h>
#include <mcp3008.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_PUMP 17
#define THRESHOLD 0.30
#define RETRY_COUNT 3

static struct gpiod_line *pump_line;
static struct mcp3008 *adc;

void handle_signal(int signum) {
    if (adc) {
        mcp3008_close(adc);
    }
    if (pump_line) {
        gpiod_line_request_release(pump_line);
        gpiod_line_free(pump_line);
    }
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *pump_line;
    struct mcp3008 *adc;
    int ret;
    int retry_count = 0;
    int moisture_reading;
    double moisture_percentage;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    pump_line = gpiod_line_request(chip, GPIO_PUMP, "pump", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!pump_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    adc = mcp3008_open(SPI_CHANNEL, SPI_SPEED);
    if (!adc) {
        perror("Failed to open SPI device");
        gpiod_line_request_release(pump_line);
        gpiod_line_free(pump_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        moisture_reading = 0;
        retry_count = 0;

        // Read moisture sensor value
        while (retry_count < RETRY_COUNT) {
            ret = mcp3008_read(adc, 0);
            if (ret < 0) {
                perror("Failed to read ADC");
                retry_count++;
                sleep(1);
            } else {
                moisture_reading = ret;
                break;
            }
        }

        if (retry_count == RETRY_COUNT) {
            fprintf(stderr, "Failed to read moisture sensor after %d retries\n", RETRY_COUNT);
            continue;
        }

        // Calculate moisture percentage
        moisture_percentage = (double)moisture_reading / 1023.0 * 100.0;

        // Log reading
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        printf("Moisture: %.2f%% at %02d:%02d:%02d\n", moisture_percentage, now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec);

        // Control pump
        if (moisture_percentage < THRESHOLD) {
            gpiod_line_set_value(pump_line, 1);
        } else {
            gpiod_line_set_value(pump_line, 0);
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Cleanup on exit
    handle_signal(0);

    return 0;
}

