#define SPI_SPEED 1000000
#define CO2_THRESHOLD 700
#define SAMPLE_INTERVAL 5000

static struct gpiod_line *fan_line;
static struct mcp3008_spi *spi;
static int log_fd;

void handle_signal(int signum) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_free(fan_line);
    }
    if (spi) {
        mcp3008_spi_close(spi);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct mcp3008_spi_config spi_config;
    int adc_value;
    double co2_ppm;
    char timestamp[32];

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    memset(&request, 0, sizeof(request));
    request.consumer = "MQ-135 CO2 Monitor";
    request.consumer_user = getuid();
    request.request_type = GPIO_REQUEST_DIRECTION_OUTPUT;
    request.flags = GPIO_LINE_REQUEST_ACTIVE_HIGH;
    request.line.consumer = "MQ-135 CO2 Monitor";
    request.line.consumer_user = getuid();
    request.line.direction = GPIO_DIRECTION_OUT;
    request.line.flags = GPIO_LINE_FLAG_ACTIVE_LOW;

    fan_line = gpiod_line_request_any(chip, &request);
    if (!fan_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    spi_config.bus = 0;
    spi_config.device = 0;
    spi_config.mode = 0;
    spi_config.speed_hz = SPI_SPEED;
    spi = mcp3008_spi_open(&spi_config);
    if (!spi) {
        perror("Failed to open SPI");
        gpiod_line_free(fan_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        mcp3008_spi_close(spi);
        gpiod_line_free(fan_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        adc_value = mcp3008_spi_read(spi, 0);
        if (adc_value == -1) {
            perror("Failed to read ADC value");
            continue;
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        // Convert ADC value to CO2 ppm
        co2_ppm = (double)adc_value * 1000.0 / 1023.0;

        // Log data
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(log_fd, "%s,%.2f,%d\n", timestamp, co2_ppm, gpiod_line_get_value(fan_line));
        fflush(log_fd);

        // Control fan
        if (co2_ppm > CO2_THRESHOLD) {
            gpiod_line_set_value(fan_line, 1);
        } else {
            gpiod_line_set_value(fan_line, 0);
        }

        // Sleep for 5 seconds
        sleep(SAMPLE_INTERVAL / 1000);
    }

    // Cleanup
    handle_signal(0);

    return 0;
}

