#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_CE_SELECT 0
#define GPIO_RELAY 17
#define DEBOUNCE_DELAY 1000
#define LOG_FILE "door_events.log"
#define DISTANCE_THRESHOLD 20

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static FILE *log_file;

void handle_sigint(int signum) {
    gpiod_line_free(relay_line);
    gpiod_chip_put(chip);
    fclose(log_file);
    exit(0);
}

int read_adc(int channel) {
    int result;
    if (spi_read(SPI_CHANNEL, &result, 1, SPI_SPEED, SPI_CE_SELECT) != 0) {
        perror("spi_read");
        return -1;
    }
    return result;
}

int calculate_distance(int adc_value) {
    // Assuming a linear relationship between ADC value and distance
    // Replace this with the actual conversion formula for your sensor
    return (adc_value * 100) / 1023;
}

void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s - %s\n", buffer, message);
    fflush(log_file);
}

int main() {
    int adc_value;
    int distance;
    int last_detected = 0;
    struct timespec ts;

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if ((chip = gpiod_chip_open("/dev/gpiomem")) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    if ((relay_line = gpiod_line_request_any(chip, "relay", GPIO_RELAY,
                                             GPIOD_LINE_DIRECTION_OUTPUT,
                                             GPIOD_LINE_ACTIVE_HIGH)) == NULL) {
        perror("gpiod_line_request_any");
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        adc_value = read_adc(SPI_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        distance = calculate_distance(adc_value);

        if (distance < DISTANCE_THRESHOLD && !last_detected) {
            gpiod_line_set_value(relay_line, 1);
            log_event("Door detected");
            last_detected = 1;
            ts.tv_sec = DEBOUNCE_DELAY / 1000;
            ts.tv_nsec = (DEBOUNCE_DELAY % 1000) * 1000000;
            nanosleep(&ts, NULL);
        } else if (distance >= DISTANCE_THRESHOLD && last_detected) {
            gpiod_line_set_value(relay_line, 0);
            last_detected = 0;
        }

        usleep(100000); // Sleep for 100 ms
    }

    return 0;
}

