#define SPI_MODE 0
#define GPIO_CE0 8
#define GPIO_PWM 17
#define PWM_FREQ 100
#define PWM_DUTY_RANGE 100
#define LOG_FILE "irrigation.log"
#define LOG_INTERVAL 5

static int spi_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *ce0_line;
static struct gpiod_line *pwm_line;
static int pwm_value = 0;

void handle_signal(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (ce0_line) {
        gpiod_line_request_release(ce0_line);
        gpiod_chip_put(chip);
    }
    if (pwm_line) {
        gpiod_line_request_release(pwm_line);
        gpiod_chip_put(chip);
