int read_adc(int adc_channel) {
    uint8_t cmd[3] = {0x01, (adc_channel << 6) | 0x18, 0};
    uint8_t data[3];
    int ret;

    if ((ret = spi_write_read(spi_fd, cmd, 3, data, 3)) < 0) {
        perror("spi_write_read");
        return -1;
    }

    return ((data[1] << 8) | data[2]) & 0x3FF;
}

