#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define SPI_RETRY_COUNT 5
#define SPI_BACKOFF_FACTOR 2
#define SPI_BACKOFF_MAX 1024
#define MOISTURE_FILE "soil_data.txt"

static int spi_fd = -1;
static struct gpiod_line *spi_cs_line = NULL;

void spi_init() {
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line_request_config config = {
        .consumer = "soil_moisture_sensor",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_value = 1,
    };

    if (gpiod_line_request_by_name("SPI0_CE0", &config, &spi_cs_line) < 0) {
        perror("Failed to request SPI CE0 line");
        exit(EXIT_FAILURE);
    }
}

void spi_deinit() {
    gpiod_line_free(spi_cs_line);
    spi_cs_line = NULL;
    close(spi_fd);
    spi_fd = -1;
}

int spi_read(uint8_t *data, size_t length) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)data,
        .rx_buf = (unsigned long)data,
        .len = length,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    int ret = 0;
    for (int i = 0; i < SPI_RETRY_COUNT; i++) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 1) {
            if (errno == EINTR) {
                continue;
            }
            if (errno == EAGAIN) {
                usleep(i * SPI_BACKOFF_FACTOR);
                continue;
            }
            break;
        }
        break;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

void handle_signal(int signum) {
    spi_deinit();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_init();

    int moisture_fd = open(MOISTURE_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (moisture_fd < 0) {
        perror("Failed to open moisture data file");
        spi_deinit();
        exit(EXIT_FAILURE);
    }

    uint8_t command[3] = {0x01, 0x00, 0x00}; // Start bit, single-ended mode, channel 0

    while (1) {
        if (spi_read(command, 3) < 0) {
            continue;
        }

        uint16_t adc_value = (command[1] << 8) | command[2];
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %u\n", adc_value);
            continue;
        }

        double moisture_percentage = (double)adc_value / 1023.0 * 100.0;
        char timestamp[32];
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(moisture_fd, "%s: %.2f%%\n", timestamp, moisture_percentage);
        fflush(moisture_fd);

        sleep(5);
    }

    close(moisture_fd);
    spi_deinit();

    return EXIT_SUCCESS;
}

