int read_spi(uint8_t channel) {
    int fd;
    uint8_t cmd[3] = {0x01, channel, 0x00};
    uint8_t data[3];

    fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open /dev/mem");
        return -1;
    }

    uint32_t *spi_base = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, SPI_BASE);
    if (spi_base == MAP_FAILED) {
        perror("Failed to mmap SPI base");
        close(fd);
        return -1;
    }

    // Set CS low
    spi_base[SPI_CS] &= ~SPI_CS_MASK;

    // Write command to FIFO
    spi_base[SPI_FIFO] = cmd[0];
    spi_base[SPI_FIFO] = cmd[1];
    spi_base[SPI_FIFO] = cmd[2];

    // Wait for transmission to complete
    while ((spi_base[SPI_FIFO] & 0x80) == 0);

    // Read data from FIFO
    data[0] = spi_base[SPI_FIFO];
    data[1] = spi_base[SPI_FIFO];
    data[2] = spi_base[SPI_FIFO];

    // Set CS high
    spi_base[SPI_CS] |= SPI_CS_MASK;

    munmap(spi_base, 4096);
    close(fd);

    return (data[1] << 8) | data[2];
}

