#define AQI_THRESHOLD 100
#define RETRY_COUNT 3
#define RETRY_DELAY 1000

static int spi_fd = -1;
static struct gpiod_line *fan_line = NULL;
static FILE *log_file = NULL;

void handle_signal(int signum) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_free(fan_line);
        fan_line = NULL;
    }

    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if ((spi_fd = mcp3008_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) == -1) {
        perror("mcp3008_open");
        return EXIT_FAILURE;
    }

    if ((fan_line = gpiod_line_request(GPIO_FAN, "fan", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        perror("gpiod_line_request");
        goto cleanup_spi;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        goto cleanup_fan;
    }

    while (1) {
        int retry_count = RETRY_COUNT;
        int adc_value = -1;

        do {
            adc_value = mcp3008_read(spi_fd, 0);
            if (adc_value == -1) {
                perror("mcp3008_read");
                sleep(RETRY_DELAY / 1000);
            }
        } while (adc_value == -1 && --retry_count > 0);

        if (adc_value == -1) {
            perror("mcp3008_read");
            goto cleanup_log;
        }

        // Compute AQI value from ADC value (example: AQI = adc_value / 10)
        int aqi = adc_value / 10;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d AQI: %d\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, aqi);

        if (aqi > AQI_THRESHOLD) {
            gpiod_line_set_value(fan_line, 1);
        } else {
            gpiod_line_set_value(fan_line, 0);
        }

        sleep(5);
    }

cleanup_log:
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

cleanup_fan:
    if (fan_line) {
        gpiod_line_free(fan_line);
        fan_line = NULL;
    }

cleanup_spi:
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }

    return EXIT_SUCCESS;
}

