#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define MCP3008_SPI_DEV "/dev/spidev0.0"
#define MCP3008_SPI_MODE 0
#define MCP3008_SPI_BITS 8
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_SPI_CS 8

#define MAX_RETRIES 3
#define RETRY_DELAY 100

struct spi_ioc_transfer spi_transfer = { \
    .tx_buf = (unsigned long) &tx_data, \
    .rx_buf = (unsigned long) &rx_data, \
    .len = 1, \
    .delay_usecs = 0, \
    .speed_hz = MCP3008_SPI_SPEED, \
    .bits_per_word = MCP3008_SPI_BITS, \
};

int spi_fd;
struct gpiod_line *spi_cs_line;

void handle_signal(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (spi_cs_line) {
        gpiod_line_free(spi_cs_line);
    }
    exit(signum);
}

int read_adc(int channel) {
    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        spi_transfer.tx_buf = (unsigned long) &tx_data;
        spi_transfer.rx_buf = (unsigned long) &rx_data;
        spi_transfer.len = 1;
        spi_transfer.delay_usecs = 0;
        spi_transfer.speed_hz = MCP3008_SPI_SPEED;
        spi_transfer.bits_per_word = MCP3008_SPI_BITS;

        tx_data = (channel << 6) | 0x18; // Start bit + single-ended mode

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 1) {
            perror("SPI transfer failed");
            retries++;
            usleep(RETRY_DELAY * 1000);
        } else {
            result = (rx_data & 0xFF) << 2; // Shift to get 10-bit result
            break;
        }
    }

    if (result == -1) {
        fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
    }

    return result;
}

int main() {
    int adc_value;
    FILE *log_file;
    struct timespec ts;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_fd = open(MCP3008_SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &MCP3008_SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &MCP3008_SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &MCP3008_SPI_BITS) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &MCP3008_SPI_BITS) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &MCP3008_SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &MCP3008_SPI_SPEED) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return 1;
    }

    spi_cs_line = gpiod_line_request(MCP3008_SPI_CS, "MCP3008 CS", 0);
    if (!spi_cs_line) {
        perror("Failed to request GPIO line");
        close(spi_fd);
        return 1;
    }

    gpiod_line_set_value(spi_cs_line, 0);

    log_file = fopen("alcohol_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_free(spi_cs_line);
        close(spi_fd);
        return 1;
    }

    while (1) {
        adc_value = read_adc(0);

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(log_file, "%s: Sensor absent\n", ctime(&ts));
        } else if (adc_value > 50) {
            fprintf(log_file, "%s: Alcohol detected! Limit exceeded.\n", ctime(&ts));
        } else if (adc_value < 20) {
            fprintf(log_file, "%s: Sobriety confirmed.\n", ctime(&ts));
        } else {
            fprintf(log_file, "%s: Alcohol level within acceptable range.\n", ctime(&ts));
        }

        fflush(log_file);
        nanosleep(&ts, NULL);
    }

    fclose(log_file);
    gpiod_line_free(spi_cs_line);
    close(spi_fd);

    return 0;
}

