This C program reads the voltage from an MQ-3 alcohol sensor using an MCP3008 ADC on SPI0 CE0 (GPIO8) on a Raspberry Pi Zero W. It samples the sensor once every second, classifies the reading into three ranges, and logs the measurements with ISO 8601 UTC timestamps. The program handles ADC read errors, sensor-absent conditions, and gracefully shuts down on receipt of SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_MODE 0
#define GPIO_RELAY 18
#define THRESHOLD 300
#define LOG_FILE "irrigation.log"

static gpiod_chip *chip;
static gpiod_line *relay_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_free(relay_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int read_sensor() {
    int value;
    if (gpiod_line_get_value(relay_line) != 0) {
        gpiod_line_set_value(relay_line, 0);
    }
    value = spi_read(SPI_CHANNEL);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value\n");
        return -1;
    }
    return value;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((chip = gpiod_chip_open("/dev/gpiomem")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if ((relay_line = gpiod_line_request_any(chip, "GPIO%d", GPIO_RELAY, "Relay", 0)) == NULL) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_set_value(relay_line, 0) < 0) {
        perror("Failed to set relay line value");
        gpiod_line_free(relay_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_free(relay_line);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        int value = read_sensor();
        if (value >= 0) {
            char timestamp[32];
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
            if (value < THRESHOLD) {
                gpiod_line_set_value(relay_line, 1);
                fprintf(log_file, "%s: Sensor value %d, Pump ON\n", timestamp, value);
            } else {
                gpiod_line_set_value(relay_line, 0);
                fprintf(log_file, "%s: Sensor value %d, Pump OFF\n", timestamp, value);
            }
        }
        fclose(log_file);
        sleep(60);
    }

    return 0;
}

