    if (gpioWrite(pin, 1) < 0) {
        perror("Failed to set motor enable");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpioPWM(pin, speed) < 0) {
        perror("Failed to set PWM duty cycle");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

