        perror("Failed to set GPIO mode for Motor 1 enable");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(MOTOR_2_EN_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode for Motor 2 enable");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(MOTOR_1_DIR_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode for Motor 1 direction");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(MOTOR_2_DIR_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode for Motor 2 direction");
        cleanup();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_flag) {
        uint16_t pot1_value = read_adc(POT_1_CHANNEL);
        uint16_t pot2_value = read_adc(POT_2_CHANNEL);

        if (pot1_value == 0 || pot2_value == 0) {
            printf("One or both potentiometers are absent or reporting an error.\n");
            sleep(1);
            continue;
        }

        int speed1 = (pot1_value * SPEED_MAP_MAX) / 1023;
        int speed2 = (pot2_value * SPEED_MAP_MAX) / 1023;

        set_motor_speed(MOTOR_1_EN_PIN, speed1);
        set_motor_speed(MOTOR_2_EN_PIN, speed2);

        set_motor_direction(MOTOR_1_DIR_PIN, 1);
        set_motor_direction(MOTOR_2_DIR_PIN, 0);

        sleep(SPEED_HOLD_TIME);

        set_motor_speed(MOTOR_1_EN_PIN, 0);
        set_motor_speed(MOTOR_2_EN_PIN, 0);

        sleep(PAUSE_TIME);

        set_motor_direction(MOTOR_1_DIR_PIN, 0);
        set_motor_direction(MOTOR_2_DIR_PIN, 1);

        sleep(SPEED_HOLD_TIME);

        set_motor_speed(MOTOR_1_EN_PIN, 0);
        set_motor_speed(MOTOR_2_EN_PIN, 0);

        sleep(PAUSE_TIME);
    }

    cleanup();
    return 0;
}

