#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <stdbool.h>

#define SPI_DEV "/dev/spidev0.0"
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11
#define LED_PIN 17
#define CHANNEL 0
#define DEBOUNCE_MS 10
#define CALIBRATION_TIME 5000

struct spi_ioc_transfer spi_transfer;
struct spi_ioc_transfer *spi_transfers;

int spi_fd;
int spi_mode;

void handle_sigint(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    close(spi_fd);
    printf("SPI handle closed.\n");
    exit(0);
}

void setup_spi() {
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        perror("Failed to set SPI mode");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &spi_mode) < 0) {
        perror("Failed to read SPI mode");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_mode) < 0) {
        perror("Failed to set bits per word");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &spi_mode) < 0) {
        perror("Failed to read bits per word");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_mode) < 0) {
        perror("Failed to set max speed");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &spi_mode) < 0) {
        perror("Failed to read max speed");
        exit(1);
    }

    printf("SPI initialized successfully.\n");
}

void setup_gpio() {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO export file");
        exit(1);
    }

    if (write(fd, "17", 2) < 0) {
        perror("Failed to export GPIO 17");
        exit(1);
    }

    close(fd);

    fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        exit(1);
    }

    if (write(fd, "out", 3) < 0) {
        perror("Failed to set GPIO 17 direction to output");
        exit(1);
    }

    close(fd);

    printf("GPIO initialized successfully.\n");
}

void calibrate_ambient_noise() {
    int sum = 0;
    int samples = 0;
    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);

    while (true) {
        int sample = read_adc_channel(CHANNEL);
        sum += sample;
        samples++;

        clock_gettime(CLOCK_REALTIME, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000000 + end.tv_nsec - start.tv_nsec >= CALIBRATION_TIME) {
            break;
        }
    }

    int baseline = sum / samples;
    printf("Calibrated ambient noise level: %d\n", baseline);
}

int read_adc_channel(int channel) {
    spi_transfer.tx_buf = (unsigned long)(0x00 | (channel << 6));
    spi_transfer.rx_buf = (unsigned long)NULL;
    spi_transfer.len = 3;
    spi_transfer.delay_usecs = 0;
    spi_transfer.speed_hz = 1000000; // 1 MHz
    spi_transfer.bits_per_word = 8;

    spi_transfers = &spi_transfer;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfers) < 0) {
        perror("Failed to send SPI message");
        exit(1);
    }

    int sample = (spi_transfer.rx_buf[1] << 8) | spi_transfer.rx_buf[2];
    return sample;
}

void toggle_led(bool state) {
    char buf[10];
    int fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value file");
        exit(1);
    }

    if (state) {
        sprintf(buf, "1");
    } else {
        sprintf(buf, "0");
    }

    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Failed to write GPIO value");
        exit(1);
    }

    close(fd);
}

int main() {
    signal(SIGINT, handle_sigint);

    setup_spi();
    setup_gpio();

    calibrate_ambient_noise();

    bool led_state = false;
    struct timespec last_toggle;
    clock_gettime(CLOCK_REALTIME, &last_toggle);

    while (true) {
        int sample = read_adc_channel(CHANNEL);

        if (sample > baseline && (clock_gettime(CLOCK_REALTIME, &last_toggle).tv_sec * 1000000000 + last_toggle.tv_nsec - clock_gettime(CLOCK_REALTIME, &last_toggle).tv_sec * 1000000000 + last_toggle.tv_nsec >= DEBOUNCE_MS * 1000)) {
            if (!led_state) {
                toggle_led(true);
                led_state = true;
            }
        } else if (sample <= baseline) {
            if (led_state) {
                toggle_led(false);
                led_state = false;
            }
        }

        usleep(10000); // 10 ms sleep
    }

    return 0;
}

