            if (!led_state) {
                toggle_led(true);
                led_state = true;
            }
        } else if (sample <= baseline) {
            if (led_state) {
                toggle_led(false);
                led_state = false;
            }
        }

        usleep(10000); // 10 ms sleep
    }

    return 0;
}
