#include <sys/mman.h>
#include <sys/time.h>
#include <time.h>
#include <signal.h>
#include <stdint.h>

#define SPI_PATH "/dev/spidev0.0"
#define GPIO_PATH "/sys/class/gpio/gpiochip8"
#define LOG_FILE "audio_log.txt"

#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_MAX_SPEED_HZ 1000000

#define GPIO_CE0 8
#define GPIO_OUT 0
#define GPIO_HIGH 1

#define NANOS_PER_SEC 1000000000
#define SAMPLE_RATE 1000
#define SAMPLE_INTERVAL (NANOS_PER_SEC / SAMPLE_RATE)

static volatile uint8_t *spi_base;
static int spi_fd;
static int log_fd;
static int gpio_fd;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_fd != -1) {
        fclose(log_fd);
    }
    if (gpio_fd != -1) {
        char path[256];
        sprintf(path, "%s/value", GPIO_PATH);
        FILE *gpio_file = fopen(path, "w");
        if (gpio_file) {
            fprintf(gpio_file, "%d", GPIO_OUT);
            fclose(gpio_file);
        }
        close(gpio_fd);
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct timespec ts;
    uint8_t adc_value;
    uint64_t timestamp_ns;

    // Open SPI device
    spi_fd = open(SPI_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        perror("Failed to configure SPI");
        cleanup();
        return 1;
    }

    // Open log file
    log_fd = fopen(LOG_FILE, "w");
    if (!log_fd) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Open GPIO device
    gpio_fd = open(GPIO_PATH, O_RDONLY);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Toggle CE0
        char path[256];
        sprintf(path, "%s/value", GPIO_PATH);
        FILE *gpio_file = fopen(path, "w");
        if (gpio_file) {
            fprintf(gpio_file, "%d", GPIO_HIGH);
            fclose(gpio_file);
        }

        // Read ADC value
        uint8_t tx_buf[1] = {0x00};
        uint8_t rx_buf[1];
        if (write(spi_fd, tx_buf, 1) != 1 || read(spi_fd, rx_buf, 1) != 1) {
            perror("Failed to read ADC value");
            cleanup();
            return 1;
        }
        adc_value = rx_buf[0];

        // Toggle CE0 back
        if (gpio_file) {
            fprintf(gpio_file, "%d", GPIO_OUT);
            fclose(gpio_file);
        }

        // Get timestamp
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
        timestamp_ns = ts.tv_sec * NANOS_PER_SEC + ts.tv_nsec;

        // Write to log file
        fprintf(log_fd, "%llu|%u\n", (unsigned long long)timestamp_ns, adc_value);
        fflush(log_fd);

        // Sleep until next sample
        ts.tv_sec = 0;
        ts.tv_nsec = SAMPLE_INTERVAL;
        nanosleep(&ts, NULL);
    }

    cleanup();
    return 0;
}

