#include <stdint.h>

#define SPI_PATH "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define SPI_CS_CE0 0
#define ADC_CHANNEL 0
#define RETRY_DELAY 100 // 100 ms
#define LOG_FILE "gas_log.txt"

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int spi_open() {
    int fd = open(SPI_PATH, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to read bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int spi_transfer(int fd, uint8_t command) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)&command,
        .rx_buf = (unsigned long)NULL,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("Failed SPI transfer");
        return -1;
    }

    return 0;
}

int read_adc(int fd) {
    uint8_t command = 0b11000000 | (ADC_CHANNEL & 0x07); // Start bit + single-ended mode + channel selection
    int retry_count = 0;

    while (retry_count < 3) {
        if (spi_transfer(fd, command) == 0) {
            return 0; // Success
        }

        usleep(RETRY_DELAY * 1000); // Sleep for 100 ms
        retry_count++;
    }

    return -1; // Failed after retries
}

int main() {
    int fd = spi_open();
    if (fd < 0) {
        return 1;
    }

    signal(SIGINT, sigint_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    while (!stop_flag) {
        int adc_value = read_adc(fd);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        double voltage = (adc_value * 3.3) / 1024.0; // Assuming 3.3V reference
        fprintf(log_file, "%ld %.3f 1000\n", time(NULL), voltage); // Placeholder PPM value

        printf("Voltage: %.3f V\n", voltage);
        fflush(stdout);

        sleep(1);
    }

    fclose(log_file);
    close(fd);

    return 0;
}

