// Kalman filter state
typedef struct {
    double x;
    double P;
} kalman_state;

// Kalman filter functions
void kalman_init(kalman_state *state) {
    state->x = 0.0;
    state->P = 1.0;
}

double kalman_update(kalman_state *state, double measurement) {
    double K;
    double y = measurement - state->x;
    K = state->P / (state->P + R_NOISE);
    state->x += K * y;
    state->P = (1 - K) * state->P;
    return state->x;
}

// SPI transaction function
int spi_transaction(int channel, int *data) {
    int fd;
    struct spi_ioc_transfer tr;
    int ret;

    fd = open(SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_WR_MODE, &0); // SPI mode 0
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_RD_MODE, &0); // Verify SPI mode
    if (ret < 0) {
        perror("Failed to read SPI mode");
        close(fd);
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &8); // 8 bits per word
    if (ret < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &0); // Verify bits per word
    if (ret < 0) {
        perror("Failed to read bits per word");
        close(fd);
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &500000); // 500 kHz
    if (ret < 0) {
        perror("Failed to set max speed");
        close(fd);
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &0); // Verify max speed
    if (ret < 0) {
        perror("Failed to read max speed");
        close(fd);
        return -1;
    }

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)data;
    tr.rx_buf = (unsigned long)data;
    tr.len = 1;
    tr.delay_usecs = 0;
    tr.speed_hz = 500000;
    tr.bits_per_word = 8;
    tr.cs_change = 1;

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("Failed SPI transaction");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Main function
int main() {
    int fd;
    int data[ADC_CHANNELS];
    kalman_state kalman_states[ADC_CHANNELS];
    struct sigaction sa;
    struct timespec ts;
    int i;

    // Initialize Kalman filters
    for (i = 0; i < ADC_CHANNELS; i++) {
        kalman_init(&kalman_states[i]);
    }

    // Set up signal handling
    sa.sa_handler = SIG_DFL;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        for (i = 0; i < ADC_CHANNELS; i++) {
            if (spi_transaction(i, &data[i]) < 0) {
                perror("Failed SPI transaction");
                return 1;
            }

            // Convert ADC value to voltage
            double voltage = (data[i] * 3.3) / 1024.0;

            // Convert voltage to acceleration in g
            double acceleration = (voltage - 1.65) / 0.33;

            // Apply Kalman filter
            acceleration = kalman_update(&kalman_states[i], acceleration);

            // Print filtered acceleration
            printf("Axis %d: %.2f g\n", i, acceleration);
        }

        // Sleep for the filter interval
        ts.tv_sec = 0;
        ts.tv_nsec = FILTER_INTERVAL;
        nanosleep(&ts, NULL);
    }

    return 0;
}

