#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_SENSOR1 4
#define GPIO_SENSOR2 17
#define GPIO_SENSOR3 27
#define FILE_NAME "magnetic_log.txt"
#define VOLTAGE 3.3
#define MAGNETIC_FIELD_SCALE 100.0 // mT per volt

static gpiod_chip *chip;
static gpiod_line *sensor1, *sensor2, *sensor3;
static FILE *log_file;

void handle_sigint(int signum) {
    if (sensor1) gpiod_line_put(sensor1);
    if (sensor2) gpiod_line_put(sensor2);
    if (sensor3) gpiod_line_put(sensor3);
    if (chip) gpiod_chip_put(chip);
    if (log_file) fclose(log_file);
    exit(0);
}

int main() {
    int sensor1_state, sensor2_state, sensor3_state;
    double sensor1_field, sensor2_field, sensor3_field;

    // Initialize libgpiod
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO lines
    if ((sensor1 = gpiod_line_request_any(chip, "sensor1", GPIO_SENSOR1, 0)) == NULL) {
        perror("Failed to request GPIO line for sensor1");
        goto cleanup;
    }
    if ((sensor2 = gpiod_line_request_any(chip, "sensor2", GPIO_SENSOR2, 0)) == NULL) {
        perror("Failed to request GPIO line for sensor2");
        goto cleanup;
    }
    if ((sensor3 = gpiod_line_request_any(chip, "sensor3", GPIO_SENSOR3, 0)) == NULL) {
        perror("Failed to request GPIO line for sensor3");
        goto cleanup;
    }

    // Set GPIO lines to input
    if (gpiod_line_direction_input(sensor1) < 0) {
        perror("Failed to set direction for sensor1");
        goto cleanup;
    }
    if (gpiod_line_direction_input(sensor2) < 0) {
        perror("Failed to set direction for sensor2");
        goto cleanup;
    }
    if (gpiod_line_direction_input(sensor3) < 0) {
        perror("Failed to set direction for sensor3");
        goto cleanup;
    }

    // Open log file
    if ((log_file = fopen(FILE_NAME, "a")) == NULL) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Main loop
    while (1) {
        sensor1_state = gpiod_line_get_value(sensor1);
        sensor2_state = gpiod_line_get_value(sensor2);
        sensor3_state = gpiod_line_get_value(sensor3);

        sensor1_field = (sensor1_state ? VOLTAGE : 0.0) * MAGNETIC_FIELD_SCALE;
        sensor2_field = (sensor2_state ? VOLTAGE : 0.0) * MAGNETIC_FIELD_SCALE;
        sensor3_field = (sensor3_state ? VOLTAGE : 0.0) * MAGNETIC_FIELD_SCALE;

        if (sensor1_field < -100.0 || sensor1_field > 100.0) {
            fprintf(stderr, "Warning: Sensor1 magnetic field out of range: %.2f mT\n", sensor1_field);
        }
        if (sensor2_field < -100.0 || sensor2_field > 100.0) {
            fprintf(stderr, "Warning: Sensor2 magnetic field out of range: %.2f mT\n", sensor2_field);
        }
        if (sensor3_field < -100.0 || sensor3_field > 100.0) {
            fprintf(stderr, "Warning: Sensor3 magnetic field out of range: %.2f mT\n", sensor3_field);
        }

        if (sensor1_state != -1 && sensor2_state != -1 && sensor3_state != -1) {
            fprintf(log_file, "%.2f,%.2f,%.2f\n", sensor1_field, sensor2_field, sensor3_field);
            fflush(log_file);
        }

        usleep(100000); // Sleep for 100 milliseconds
    }

cleanup:
    if (sensor1) gpiod_line_put(sensor1);
    if (sensor2) gpiod_line_put(sensor2);
    if (sensor3) gpiod_line_put(sensor3);
    if (chip) gpiod_chip_put(chip);
    if (log_file) fclose(log_file);

    return 0;
}

