#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <mcp3008.h>

#define GPIO_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define THRESHOLD 30
#define LOG_FILE "watering.log"

static gpiod_chip *chip;
static gpiod_line *pump_line;
static mcp3008_t *adc;

void handle_signal(int signum) {
    gpiod_line_set_value(pump_line, 0);
    fprintf(stderr, "Received signal %d, turning off pump and exiting.\n", signum);
    exit(signum);
}

void log_event(const char *event) {
    time_t now;
    struct tm *now_tm;
    char buffer[80];

    time(&now);
    now_tm = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", now_tm);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s - %s\n", buffer, event);
    fclose(log_file);
}

int main() {
    int ret;
    unsigned int moisture_level;

    log_event("Program started");

    // Initialize GPIO
    if ((ret = gpiod_chip_open("/dev/gpiochip0", &chip)) < 0) {
        perror("Failed to open GPIO chip");
        return ret;
    }

    if ((ret = gpiod_line_request_any(chip, GPIO_PIN, "Pump Relay", &pump_line, GPIOD_LINE_DIRECTION_OUTPUT)) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return ret;
    }

    // Initialize SPI
    if ((ret = mcp3008_init(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        perror("Failed to initialize MCP3008");
        gpiod_line_free(pump_line);
        gpiod_chip_close(chip);
        return ret;
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        if ((ret = mcp3008_read(SPI_CHANNEL, &moisture_level, MCP3008_CHANNEL_0, MCP3008_SINGLE_ENDED)) < 0) {
            perror("Failed to read ADC");
            continue;
        }

        if (moisture_level < THRESHOLD) {
            if (gpiod_line_get_value(pump_line) == 0) {
                gpiod_line_set_value(pump_line, 1);
                log_event("Pump turned on");
            }
        } else {
            if (gpiod_line_get_value(pump_line) == 1) {
                gpiod_line_set_value(pump_line, 0);
                log_event("Pump turned off");
            }
        }

        sleep(60);
    }

    // Cleanup
    gpiod_line_free(pump_line);
    gpiod_chip_close(chip);
    mcp3008_uninit();

    log_event("Program terminated");

    return 0;
}

