#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

#define LED_GPIO 17
#define MAX_RECONNECT_BACKOFF 60

static int reconnect_backoff = 1;
static bool led_state = false;
static struct mosquitto *mosq;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void handle_signal(int signum) {
    if (mosq) {
        mosquitto_disconnect(mosq);
    }
    if (line) {
        gpiod_line_request_release(line);
        gpiod_chip_put(chip);
    }
    exit(signum == SIGINT ? 0 : 1);
}

void on_connect(struct mosquitto *mosq, void *obj, int result) {
    if (result == 0) {
        printf("Connected to MQTT broker\n");
        mosquitto_subscribe(mosq, NULL, "home/led_control", 0);
    } else {
        fprintf(stderr, "Failed to connect to MQTT broker: %d\n", result);
        sleep(reconnect_backoff);
        reconnect_backoff = reconnect_backoff * 2 > MAX_RECONNECT_BACKOFF ? MAX_RECONNECT_BACKOFF : reconnect_backoff * 2;
        mosquitto_reconnect(mosq);
    }
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *message) {
    json_error_t error;
    json_t *root = json_loads(message->payload, 0, &error);
    if (!root) {
        fprintf(stderr, "Failed to parse JSON: %s\n", error.text);
        return;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json || !json_is_boolean(led_state_json)) {
        fprintf(stderr, "Invalid JSON payload: expected 'led_state' key with boolean value\n");
        json_decref(root);
        return;
    }

    led_state = json_is_true(led_state_json);
    gpiod_line_set_value(line, led_state ? 1 : 0);
    json_decref(root);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "gpio%d", LED_GPIO, "rpi_led_control", 0, GPIOD_LINE_DIRECTION_OUTPUT, &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_set_value(line, 0); // Turn off LED at startup

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        gpiod_line_request_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    mosq = mosquitto_new("rpi_led_control", true, NULL);
    if (!mosq) {
        perror("Failed to create MQTT client");
        gpiod_line_request_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    if (mosquitto_connect(mosq, "mqtt.eclipseprojects.io", 1883, 60)) {
        perror("Failed to connect to MQTT broker");
        gpiod_line_request_release(line);
        gpiod_chip_put(chip);
        mosquitto_destroy(mosq);
        return 1;
    }

    mosquitto_loop(mosq, 0, 1);

    gpiod_line_request_release(line);
    gpiod_chip_put(chip);
    mosquitto_destroy(mosq);
    gpioTerminate();

    return 0;
}

