#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_DO_PIN 17
#define GPIO_LED_PIN 18
#define DELAY_MS 100
#define ALARM_DURATION 1000

static struct gpiod_line *sensor_line;
static struct gpiod_line *led_line;

void handle_signal(int signum) {
    if (sensor_line) {
        gpiod_line_request_release(sensor_line);
    }
    if (led_line) {
        gpiod_line_request_release(led_line);
    }
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    int ret;

    // Initialize libgpiod
    ret = gpiod_chip_open(NULL, &chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_to_str(ret));
        return EXIT_FAILURE;
    }

    // Request sensor line
    memset(&request, 0, sizeof(request));
    request.consumer = "SoundSensor";
    request.consumer_user = getuid();
    request.flags = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    request.line.direction = GPIOD_LINE_DIRECTION_INPUT;
    request.line.consumer_gpios = &chip->lines[GPIO_DO_PIN];
    sensor_line = gpiod_line_request(chip, &request);
    if (!sensor_line) {
        fprintf(stderr, "Failed to request sensor line: %s\n", gpiod_error_to_str(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request LED line
    memset(&request, 0, sizeof(request));
    request.consumer = "AlarmLED";
    request.consumer_user = getuid();
    request.flags = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    request.line.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    request.line.consumer_gpios = &chip->lines[GPIO_LED_PIN];
    led_line = gpiod_line_request(chip, &request);
    if (!led_line) {
        fprintf(stderr, "Failed to request LED line: %s\n", gpiod_error_to_str(ret));
        gpiod_line_request_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        int value;
        ret = gpiod_line_get_value(sensor_line, &value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read sensor value: %s\n", gpiod_error_to_str(ret));
            handle_signal(EXIT_FAILURE);
        }

        printf("Sound level: %d\n", value);

        if (value == 0) {
            // Sound detected, trigger alarm
            gpiod_line_set_value(led_line, 1);
            usleep(ALARM_DURATION * 1000);
            gpiod_line_set_value(led_line, 0);
        }

        usleep(DELAY_MS * 1000);
    }

    // Cleanup
    handle_signal(EXIT_SUCCESS);

    return EXIT_SUCCESS;
}

