#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

volatile sig_atomic_t shutdown_requested = 0;

void handle_signal(int signum) {
    shutdown_requested = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_event *event;
    int fd;
    char buffer[128];
    struct timespec ts;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Get the line
    if (gpiod_line_request_by_consumer(chip, "vibration-monitor", &line) < 0) {
        perror("gpiod_line_request_by_consumer");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the line to falling edge detection
    if (gpiod_line_set_edge(line, GPIOD_LINE_BOTH_EDGES) < 0) {
        perror("gpiod_line_set_edge");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    fd = open("/var/log/vibration_shutdown.log", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd < 0) {
        perror("open");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

