#define BUFFER_SIZE 120
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 10
#define SPI_SPEED 1000000

static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int spi_fd = -1;
static int file_fd = -1;

void handle_signal(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (file_fd != -1) {
        close(file_fd);
        file_fd = -1;
    }
    exit(signum);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi_transfer = {
        .tx_buf = (unsigned long)0x00,
        .rx_buf = (unsigned long)0x00,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
        perror("Failed to send SPI message");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int read_temperature() {
    struct spi_ioc_transfer spi_transfer = {
        .tx_buf = (unsigned long)0x00,
        .rx_buf = (unsigned long)&temperature_buffer[buffer_index],
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
        perror("Failed to read temperature");
        return -1;
    }

    temperature_buffer[buffer_index] = (float)temperature_buffer[buffer_index] * 0.48828125; // Convert ADC value to temperature
    printf("Temperature: %.2f °C\n", temperature_buffer[buffer_index]);

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    return 0;
}

int write_buffer_to_file() {
    if (file_fd == -1) {
        file_fd = open("temp_log.dat", O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (file_fd < 0) {
            perror("Failed to open file for writing");
            return -1;
        }
    }

    if (write(file_fd, temperature_buffer, sizeof(temperature_buffer)) != sizeof(temperature_buffer)) {
        perror("Failed to write buffer to file");
        close(file_fd);
        file_fd = -1;
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_spi() < 0) {
        return 1;
    }

    while (1) {
        if (read_temperature() < 0) {
            continue;
        }

        if (write_buffer_to_file() < 0) {
            continue;
        }

        sleep(5);
    }

    return 0;
}

