#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>

#define BH1750_ADDR 0x23
#define MAX4466_ADDR 0x60
#define MCP3008_SPI_DEV "/dev/spidev0.0"
#define BUFFER_SIZE 1024

int i2c_fd;
int spi_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(signum);
}

int read_bh1750(void) {
    int ret;
    uint8_t data[2];

    ret = read(i2c_fd, data, 2);
    if (ret != 2) {
        perror("Error reading BH1750");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int read_max4466(void) {
    int ret;
    uint8_t cmd = 0x00;
    uint8_t data[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)&cmd,
        .rx_buf = (unsigned long)data,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("Error reading MAX4466");
        return -1;
    }

    return (data[1] << 8) | data[2];
}

int main(void) {
    struct sigaction sa;
    struct timespec ts;
    char buffer[BUFFER_SIZE];
    FILE *log_file;
    int light_value, sound_value;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting BH1750 address");
        close(i2c_fd);
        return 1;
    }

    spi_fd = open(MCP3008_SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("environmental_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    while (1) {
        light_value = read_bh1750();
        if (light_value < 0) {
            continue;
        }

        sound_value = read_max4466();
        if (sound_value < 0) {
            continue;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        snprintf(buffer, BUFFER_SIZE, "%04d-%02d-%02d %02d:%02d:%02d, Light: %d, Sound: %d\n",
                 now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                 now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                 light_value, sound_value);

        if (fwrite(buffer, strlen(buffer), 1, log_file) != 1) {
            perror("Error writing to log file");
        }

        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    fclose(log_file);
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

