#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define FILE_NAME "flame_events.log"

static gpiod_line *line;

void cleanup(int signum) {
    if (line) {
        gpiod_line_free(line);
        line = NULL;
    }
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main() {
    gpiod_chip *chip;
    gpiod_line_request_flags flags = GPIOD_LINE_ACTIVE_LOW | GPIOD_LINE_OPEN_DRAIN | GPIOD_LINE_PULL_DOWN;
    gpiod_line_consumer_type consumer_type = GPIOD_LINE_CONSUMER_USER;
    gpiod_line_consumer_user_data user_data = { .name = "Flame Sensor", .version = "1.0" };

    // Initialize libgpiod
    if (gpiod_chip_open("/dev/gpiomem", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    if (gpiod_line_request_any(chip, GPIO_PIN, &flags, consumer_type, &user_data, &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the line to input
    if (gpiod_line_set_consumer(line, consumer_type, &user_data) < 0) {
        perror("Failed to set line to input");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    FILE *log_file = fopen(FILE_NAME, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Register cleanup function for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register signal handler");
        fclose(log_file);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int state;
        if (gpiod_line_get_value(line, &state) < 0) {
            perror("Failed to read GPIO line value");
            fclose(log_file);
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, GPIO_PIN, state);

        if (state == 1) {
            printf("Flame detected!\n");
        }

        usleep(1000000); // Sleep for 1 second
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

