                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, GPIO_PIN, state);

        if (state == 1) {
            printf("Flame detected!\n");
        }

        usleep(1000000); // Sleep for 1 second
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
