#define SPI_DEV_PATH "/dev/spidev0.0"
#define I2C_DEV_PATH "/dev/i2c-1"
#define TMP36_ADDR 0x48
#define MCP4725_ADDR 0x60
#define SPI_SPEED 500000
#define SAMPLE_INTERVAL 500000 // 0.5 seconds in microseconds

int spi_fd;
int i2c_fd;
FILE *log_file;

int read_adc(int channel) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long) &channel,
        .rx_buf = (unsigned long) &channel,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return channel;
}

int write_i2c(int addr, int value) {
    char buf[2] = { (char)(value & 0xFF), (char)((value >> 8) & 0xFF) };

    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }

    return 0;
}

double adc_to_temp(int adc_value) {
    return (adc_value * 0.0048828125) - 0.5;
}

