        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE_0) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_8) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS_8) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return 1;
    }

    i2c_fd = open(I2C_DEV_PATH, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        close(spi_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MCP4725_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    log_file = fopen("temperature_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    while (1) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            continue; // Retry on error
        }

        double temp_celsius = adc_to_temp(adc_value);
        int dac_value = (int)(temp_celsius * 255.0 / 100.0); // Assuming 0-100°C range

        if (write_i2c(MCP4725_ADDR, dac_value) < 0) {
            continue; // Retry on error
        }

        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        fprintf(log_file, "%s - Raw ADC: %d, Temp (°C): %.2f, DAC Voltage: %d\n", asctime(timeinfo), adc_value, temp_celsius, dac_value);
        fflush(log_file);

        printf("%s - Raw ADC: %d, Temp (°C): %.2f, DAC Voltage: %d\n", asctime(timeinfo), adc_value, temp_celsius, dac_value);
        fflush(stdout);

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

