#define SPI_CHANNEL_COUNT 3
#define SPI_CHANNEL_BASE 0
#define SPI_CHANNEL_RANGE 3

#define LOG_FILE "soil_data.txt"

struct spi_ioc_transfer spi_transfer[SPI_CHANNEL_COUNT];

int spi_fd;
int spi_result;

void spi_init() {
    spi_fd = open(SPI_DEV_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        exit(1);
    }

    for (int i = 0; i < SPI_CHANNEL_COUNT; i++) {
        spi_transfer[i].tx_buf = (unsigned long) &spi_transfer[i].len;
        spi_transfer[i].rx_buf = (unsigned long) &spi_transfer[i].len;
        spi_transfer[i].len = 3;
        spi_transfer[i].delay_usecs = 0;
        spi_transfer[i].speed_hz = SPI_SPEED;
        spi_transfer[i].bits_per_word = 8;
        spi_transfer[i].cs_change = 1;
        spi_transfer[i].tx_nbits = 8;
        spi_transfer[i].rx_nbits = 8;
        spi_transfer[i].tx_buf = (unsigned long) &spi_transfer[i].len;
        spi_transfer[i].rx_buf = (unsigned long) &spi_transfer[i].len;
        spi_transfer[i].delay_usecs = 0;
        spi_transfer[i].speed_hz = SPI_SPEED;
        spi_transfer[i].bits_per_word = 8;
        spi_transfer[i].cs_change = 1;
        spi_transfer[i].tx_nbits = 8;
        spi_transfer[i].rx_nbits = 8;
    }
}

void spi_transfer_read(int channel) {
    spi_transfer[channel].tx_buf = (unsigned long) &spi_transfer[channel].len;
    spi_transfer[channel].rx_buf = (unsigned long) &spi_transfer[channel].len;
    spi_transfer[channel].len = 3;
    spi_transfer[channel].delay_usecs = 0;
    spi_transfer[channel].speed_hz = SPI_SPEED;
    spi_transfer[channel].bits_per_word = 8;
    spi_transfer[channel].cs_change = 1;
    spi_transfer[channel].tx_nbits = 8;
    spi_transfer[channel].rx_nbits = 8;

    spi_result = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer[channel]);
    if (spi_result < 0) {
        perror("Failed to transfer SPI data");
        exit(1);
    }
}

void spi_close() {
    close(spi_fd);
}

void log_data(const char *timestamp, int channel, int value) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }

    fprintf(log_file, "%s %d: %d\n", timestamp, channel, value);
    fclose(log_file);
}

int main() {
    spi_init();

    while (1) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        for (int i = 0; i < SPI_CHANNEL_COUNT; i++) {
            spi_transfer_read(i);
            int value = spi_transfer[i].rx_buf & 0xFF;

            if (value < 0 || value > 1023) {
                fprintf(stderr, "Invalid ADC value for channel %d\n", i);
                continue;
            }

            log_data(timestamp, i, value);
        }

        sleep(60);
    }

    spi_close();
    return 0;
}

