// GPIO pins for relays 1-4
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Global variables for GPIO lines
struct gpiod_line *relay1_line;
struct gpiod_line *relay2_line;
struct gpiod_line *relay3_line;
struct gpiod_line *relay4_line;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    if (relay1_line) {
        gpiod_line_set_value(relay1_line, 0);
        gpiod_line_free(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_set_value(relay2_line, 0);
        gpiod_line_free(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_set_value(relay3_line, 0);
        gpiod_line_free(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_set_value(relay4_line, 0);
        gpiod_line_free(relay4_line);
    }
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Initialize GPIO chip
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Initialize relay lines
    if (gpiod_line_request_any(chip, RELAY1_PIN, "Relay1", &line) < 0) {
        perror("gpiod_line_request_any");
        return 1;
    }
    relay1_line = line;

    if (gpiod_line_request_any(chip, RELAY2_PIN, "Relay2", &line) < 0) {
        perror("gpiod_line_request_any");
        return 1;
    }
    relay2_line = line;

    if (gpiod_line_request_any(chip, RELAY3_PIN, "Relay3", &line) < 0) {
        perror("gpiod_line_request_any");
        return 1;
    }
    relay3_line = line;

    if (gpiod_line_request_any(chip, RELAY4_PIN, "Relay4", &line) < 0) {
        perror("gpiod_line_request_any");
        return 1;
    }
    relay4_line = line;

    // Set all relay lines to inactive (LOW)
    if (gpiod_line_set_value(relay1_line, 0) < 0) {
        perror("gpiod_line_set_value");
        return 1;
    }
    if (gpiod_line_set_value(relay2_line, 0) < 0) {
        perror("gpiod_line_set_value");
        return 1;
    }
    if (gpiod_line_set_value(relay3_line, 0) < 0) {
        perror("gpiod_line_set_value");
        return 1;
    }
    if (gpiod_line_set_value(relay4_line, 0) < 0) {
        perror("gpiod_line_set_value");
        return 1;
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Infinite loop to activate and deactivate relays
    while (1) {
        if (gpiod_line_set_value(relay1_line, 1) < 0) {
