#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <mcp3008.h>

#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define DEBOUNCE_DELAY 500
#define THRESHOLD 500
#define LED_GPIO 16
#define LOG_FILE "sound_events.log"

static struct gpiod_line *led_line;
static struct mcp3008 *adc;

void handle_sigint(int signum) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_free(led_line);
    }
    if (adc) {
        mcp3008_close(adc);
    }
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    struct mcp3008 *adc;
    int value;
    time_t now;
    char timestamp[20];

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    led_line = gpiod_line_request(chip, LED_GPIO, "LED", 0);
    if (!led_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize ADC
    adc = mcp3008_open(SPI_SPEED, ADC_CHANNEL);
    if (!adc) {
        perror("Failed to open ADC");
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        value = mcp3008_read(adc);
        if (value < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        if (value > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            time(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            FILE *log_file = fopen(LOG_FILE, "a");
            if (!log_file) {
                perror("Failed to open log file");
            } else {
                fprintf(log_file, "%s: Sound detected\n", timestamp);
                fclose(log_file);
            }
            usleep(DEBOUNCE_DELAY * 1000);
            gpiod_line_set_value(led_line, 0);
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup
    if (led_line) {
        gpiod_line_free(led_line);
    }
    if (adc) {
        mcp3008_close(adc);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

