#define MOTOR_REVERSE 0
#define PWM_DUTY 150
#define PWM_RANGE 255
#define GPIO_IN1 17
#define GPIO_IN2 18
#define GPIO_ENA 27

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int spi_init() {
    int fd;
    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int spi_read(int fd, uint8_t *data) {
    int ret;
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)data,
        .rx_buf = (unsigned long)data,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("Failed to transfer SPI data");
        return -1;
    }

    return 0;
}

int motor_init() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[3];

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    lines[0] = gpiod_line_request_any(chip, "IN1", GPIO_IN1, 0);
    if (!lines[0]) {
        perror("Failed to request GPIO IN1");
        gpiod_chip_put(chip);
        return -1;
    }

    lines[1] = gpiod_line_request_any(chip, "IN2", GPIO_IN2, 0);
    if (!lines[1]) {
        perror("Failed to request GPIO IN2");
        gpiod_line_free(lines[0]);
        gpiod_chip_put(chip);
        return -1;
    }

    lines[2] = gpiod_line_request_any(chip, "ENA", GPIO_ENA, 0);
    if (!lines[2]) {
        perror("Failed to request GPIO ENA");
        gpiod_line_free(lines[0]);
        gpiod_line_free(lines[1]);
        gpiod_chip_put(chip);
        return -1;
    }

    gpiod_line_direction_output(lines[0]);
    gpiod_line_direction_output(lines[1]);
    gpiod_line_direction_output(lines[2]);

    return 0;
}

void motor_forward(struct gpiod_line *lines[3]) {
    gpiod_line_set_value(lines[0], 1);
    gpiod_line_set_value(lines[1], 0);
    gpiod_line_set_value(lines[2], PWM_DUTY);
}

void motor_reverse(struct gpiod_line *lines[3]) {
    gpiod_line_set_value(lines[0], 0);
    gpiod_line_set_value(lines[1], 1);
    gpiod_line_set_value(lines[2], PWM_DUTY);
}

void motor_stop(struct gpiod_line *lines[3]) {
    gpiod_line_set_value(lines[0], 0);
    gpiod_line_set_value(lines[1], 0);
    gpiod_line_set_value(lines[2], 0);
}

void motor_cleanup(struct gpiod_line *lines[3]) {
    gpiod_line_free(lines[0]);
    gpiod_line_free(lines[1]);
    gpiod_line_free(lines[2]);
}

int main() {
    int spi_fd;
    uint8_t data;
    struct gpiod_line *lines[3];
    FILE *log_file;
    int rain_level;
    struct timespec ts;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_fd = spi_init();
    if (spi_fd < 0) {
        return 1;
    }

    if (motor_init() < 0) {
        close(spi_fd);
        return 1;
    }

    log_file = fopen("rain_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        motor_cleanup(lines);
        close(spi_fd);
        return 1;
    }

    while (!stop_flag) {
        if (spi_read(spi_fd, &data) < 0) {
            fprintf(stderr, "Failed to read SPI data\n");
            continue;
        }

        rain_level = data;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld: %d\n", (long)ts.tv_sec, (long)ts.tv_nsec, rain_level);
        fflush(log_file);

        if (rain_level > RAIN_THRESHOLD) {
            motor_forward(lines);
            sleep(3);
            motor_stop(lines);
        } else {
            motor_reverse(lines);
            sleep(3);
            motor_stop(lines);
        }

        sleep(1);
    }

    motor_stop(lines);
    fclose(log_file);
    motor_cleanup(lines);
    close(spi_fd);

    return 0;
}

