#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define GPIO_FILE "/sys/class/gpio/gpio%d/value"
#define LOG_FILE "distance_log.txt"
#define MAX_RETRIES 5

static int retry_count = 0;

void handle_signal(int signum) {
    gpiod_chip_unexport(chip);
    printf("Program terminated.\n");
    exit(signum);
}

int read_sensor() {
    char buffer[10];
    FILE *file = fopen(snprintf(buffer, sizeof(buffer), GPIO_FILE, GPIO_PIN), "r");
    if (file == NULL) {
        if (retry_count < MAX_RETRIES) {
            printf("Error opening GPIO file. Retrying in 1 second...\n");
            sleep(1);
            retry_count++;
            return read_sensor();
        } else {
            printf("Failed to open GPIO file after %d retries.\n", MAX_RETRIES);
            return -1;
        }
    }

    char *value = fgets(buffer, sizeof(buffer), file);
    fclose(file);

    if (value == NULL) {
        if (retry_count < MAX_RETRIES) {
            printf("Error reading GPIO file. Retrying in 1 second...\n");
            sleep(1);
            retry_count++;
            return read_sensor();
        } else {
            printf("Failed to read GPIO file after %d retries.\n", MAX_RETRIES);
            return -1;
        }
    }

    return atoi(value);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    gpiod_line *line = gpiod_line_request(chip, GPIO_PIN, "distance_sensor", 0, 0, 0, 0);
    if (line == NULL) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        int distance = read_sensor();
        if (distance == -1) {
            printf("Error reading sensor. Retrying...\n");
            sleep(1);
            continue;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s %d\n", timestamp, distance);
        fflush(log_file);

        if (distance < 200) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

