#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define THRESHOLD 30
#define PUMP_GPIO 17
#define LOG_FILE "soil_moisture.log"

static int spi_fd;
static struct gpiod_chip *gpiod_chip;
static struct gpiod_line *gpiod_line;

void handle_sigint(int signum) {
    gpiod_line_request_free(gpiod_line);
    gpiod_chip_put(gpiod_chip);
    close(spi_fd);
    exit(0);
}

int init_spi() {
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to send SPI message");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int init_gpiod() {
    gpiod_chip = gpiod_chip_open("gpiochip0");
    if (!gpiod_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpiod_line = gpiod_line_request(gpiod_chip, PUMP_GPIO, "pump",
                                   GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!gpiod_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(gpiod_chip);
        return -1;
    }

    return 0;
}

int read_adc() {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)&adc_value,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read ADC value");
        return -1;
    }

    return 0;
}

int main() {
    int adc_value;
    int moisture_percentage;
    int pump_status = 0;

    signal(SIGINT, handle_sigint);

    if (init_spi() < 0 || init_gpiod() < 0) {
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_request_free(gpiod_line);
        gpiod_chip_put(gpiod_chip);
        close(spi_fd);
        return 1;
    }

    while (1) {
        if (read_adc() < 0) {
            continue;
        }

        moisture_percentage = (adc_value * 100) / 1023;

        if (moisture_percentage < THRESHOLD) {
            gpiod_line_set_value(gpiod_line, 1);
            pump_status = 1;
        } else {
            gpiod_line_set_value(gpiod_line, 0);
            pump_status = 0;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(log_file, "%02d:%02d:%02d - %d%% - %s\n",
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                moisture_percentage, pump_status ? "ON" : "OFF");

        fflush(log_file);
        usleep(60 * 1000 * 1000);
    }

    fclose(log_file);
    gpiod_line_request_free(gpiod_line);
    gpiod_chip_put(gpiod_chip);
    close(spi_fd);

    return 0;
}

