#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_PATH "/dev/spidev0.0"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define SPI_CS_GPIO 8
#define LOG_FILE "magnetic_log.txt"
#define THRESHOLD 10.0
#define LED_GPIO 21
#define SAMPLE_INTERVAL 100 // in milliseconds

static int spi_fd;
static struct gpiod_line *led_line;

void spi_init() {
    spi_fd = open(SPI_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to read SPI bits per word");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        exit(EXIT_FAILURE);
    }
}

void spi_close() {
    close(spi_fd);
}

int spi_read(uint8_t channel) {
    uint8_t tx[1] = {0x00};
    uint8_t rx[1];

    tx[0] = (1 << 7) | (channel & 0x07); // Set the start bit and channel

    if (write(spi_fd, tx, 1) != 1) {
        perror("Failed to write to SPI");
        return -1;
    }

    if (read(spi_fd, rx, 1) != 1) {
        perror("Failed to read from SPI");
        return -1;
    }

    return rx[0];
}

void led_init() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_any(chip, "LED", LED_GPIO,
                                  GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!line) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    led_line = line;
}

void led_on() {
    if (gpiod_line_set_value(led_line, 1)) {
        perror("Failed to set LED on");
    }
}

void led_off() {
    if (gpiod_line_set_value(led_line, 0)) {
        perror("Failed to set LED off");
    }
}

void led_cleanup() {
    gpiod_line_free(led_line);
}

void handle_sigint(int signum) {
    led_off();
    spi_close();
    led_cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec ts;
    int adc_value;
    double magnetic_field;
    FILE *log_file;

    signal(SIGINT, handle_sigint);

    spi_init();
    led_init();

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ts.tv_sec = 0;
        ts.tv_nsec = SAMPLE_INTERVAL * 1000000; // 100 ms

        nanosleep(&ts, NULL);

        adc_value = spi_read(SPI_CHANNEL);
        if (adc_value < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        magnetic_field = (double)adc_value * 5.0 / 1024.0; // Assuming 5V reference

        fprintf(log_file, "%ld.%09ld: %.2f mT\n", ts.tv_sec, ts.tv_nsec / 1000000000, magnetic_field);
        fflush(log_file);

        if (magnetic_field > THRESHOLD) {
            led_on();
        } else {
            led_off();
        }
    }

    fclose(log_file);
    return 0;
}

