int init_spi() {
    spi_fd = open(SPI_DEV_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi_transfer = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_transfer.bits_per_word) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &spi_transfer.bits_per_word) < 0) {
        perror("Failed to read bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_transfer.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &spi_transfer.speed_hz) < 0) {
        perror("Failed to read SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc() {
    struct spi_ioc_transfer spi_transfer = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)&spi_transfer.len,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

