This C program reads the analog output from the Melexis MLX91209 current sensor using an MCP3008 ADC connected to the SPI bus on a Raspberry Pi 3 Model B+. It samples the current once every second, converts the ADC reading to amperes, and appends a line to a CSV file named `current_log.txt` in the format "timestamp,current_A". The program verifies each initialization step, handles sensor-absent or communication failures, and installs handlers for SIGINT and SIGTERM to perform a clean shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <mcp3008.h>

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        stop_flag = 1;
    }
}

int main() {
    FILE *log_file;
    struct timespec ts;
    int adc_value;
    double voltage, current;

    // Initialize the MCP3008 ADC
    if (mcp3008_init(SPI0, 0) < 0) {
        perror("Failed to initialize MCP3008");
        return 1;
    }

    // Open the log file
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        mcp3008_close();
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!stop_flag) {
        // Sample the sensor
        if ((adc_value = mcp3008_read(0)) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        // Convert ADC reading to voltage
        voltage = (double)adc_value * (5.0 / 1023.0);

        // Check if voltage is within the valid range
        if (voltage < 0.0 || voltage > 5.0) {
            fprintf(stderr, "Warning: Voltage out of range (0-5V)\n");
            continue;
        }

        // Convert voltage to current (assuming a 1000 ohm resistor)
        current = voltage / 1000.0;

        // Get the current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Format the timestamp
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Write the current value to the log file
        fprintf(log_file, "%s %.2f A\n", timestamp, current);
        fflush(log_file);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    mcp3008_close();

    return 0;
}

