#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_SENSOR1 4
#define GPIO_SENSOR2 17
#define DEBOUNCE_COUNT 5
#define DEBOUNCE_INTERVAL 2
#define LOG_INTERVAL 1000

gpiod_chip *chip;
gpiod_line *sensor1, *sensor2;

void handle_sigint(int signum) {
    gpiod_line_request_free(sensor1);
    gpiod_line_request_free(sensor2);
    gpiod_chip_put(chip);
    exit(0);
}

int read_sensor(gpiod_line *line) {
    int result = 0;
    for (int i = 0; i < DEBOUNCE_COUNT; i++) {
        result += gpiod_line_get_value(line);
        usleep(DEBOUNCE_INTERVAL * 1000);
    }
    return result >= DEBOUNCE_COUNT / 2 ? 1 : 0;
}

int main() {
    int status;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    sensor1 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_SENSOR1, "sensor1", 0);
    if (!sensor1) {
        fprintf(stderr, "Failed to request GPIO line for sensor1\n");
        gpiod_chip_put(chip);
        return 1;
    }

    sensor2 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_SENSOR2, "sensor2", 0);
    if (!sensor2) {
        fprintf(stderr, "Failed to request GPIO line for sensor2\n");
        gpiod_line_request_free(sensor1);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        int sensor1_state = read_sensor(sensor1);
        int sensor2_state = read_sensor(sensor2);

        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("ALERT: Both sensors detect object\n");
        } else {
            printf("%d\n", sensor1_state | (sensor2_state << 1));
        }

        usleep(LOG_INTERVAL * 1000);
    }

    // Cleanup
    gpiod_line_request_free(sensor1);
    gpiod_line_request_free(sensor2);
    gpiod_chip_put(chip);

    return 0;
}

