#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t stop_flag = 0;

int read_mcp3008(int channel) {
    int adc_value;
    uint8_t cmd[3] = {0x01, (channel << 6) | 0x18, 0};
    uint8_t data[3];

    if (spi_write(SPI_CHANNEL, cmd, 3, data, 3) != 3) {
        fprintf(stderr, "SPI transfer failed, retrying...\n");
        sleep(1);
        return -1;
    }

    adc_value = ((data[1] & 0x0F) << 8) | data[2];
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    double moisture_level = ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
    return moisture_level;
}

void log_data(double moisture_level) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S,", timeinfo);
    fprintf(file, "%s%.2f\n", buffer, moisture_level);
    fprintf(stdout, "%s%.2f\n", buffer, moisture_level);

    fclose(file);
}

void signal_handler(int signal) {
    stop_flag = 1;
}

void spi_setup(spi_config_t config) {
    if (spi_open(SPI_CHANNEL, 0, SPI_BAUD, &config) < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        spi_close(SPI_CHANNEL);
        gpioInitialise();
        exit(EXIT_FAILURE);
    }
}

int main() {
    spi_config_t config = {0};
    config.bits = 8;
    config.max_speed_hz = SPI_BAUD;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }

    spi_setup(config);

    signal(SIGINT, signal_handler);

    while (!stop_flag) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            double moisture_level = calculate_moisture_level(adc_value);
            log_data(moisture_level);
        }
        sleep(READ_DELAY);
    }

    spi_close(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

