#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>
#include <libcamera/libcamera.h>
#include <syslog.h>
#include <signal.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY 200000 // 200ms in microseconds
#define POLL_INTERVAL 50000 // 50ms in microseconds

static struct gpiod_line *pir_line;
static struct camera_manager *manager;
static struct camera_device *device;

void log_event(const char *event) {
    syslog(LOG_INFO, "%s", event);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Received SIGINT or SIGTERM, initiating shutdown...");
        gpiod_line_free(pir_line);
        camera_device_unref(device);
        camera_manager_unref(manager);
        closelog();
        exit(0);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (openlog("pir_monitor", LOG_PID, LOG_USER) == -1) {
        perror("openlog");
        exit(1);
    }

    log_event("Starting PIR sensor monitor...");

    if (gpiod_line_request(GPIO_PIN, "pir_sensor", GPIOD_LINE_DIRECTION_INPUT, 0, 0, 0, &pir_line) < 0) {
        perror("gpiod_line_request");
        exit(1);
    }

    if (gpiod_line_set_debounce(pir_line, DEBOUNCE_DELAY) < 0) {
        perror("gpiod_line_set_debounce");
        exit(1);
    }

    if (gpiod_line_enable(pir_line) < 0) {
        perror("gpiod_line_enable");
        exit(1);
    }

    manager = camera_manager_new();
    if (!manager) {
        log_event("Failed to initialize camera manager.");
        exit(1);
    }

    device = camera_manager_get_device(manager, 0);
    if (!device) {
        log_event("Failed to get camera device.");
        exit(1);
    }

    while (1) {
        int current_state = gpiod_line_get_value(pir_line);
        if (current_state == 1) {
            log_event("Motion detected.");
            char filename[100];
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            snprintf(filename, sizeof(filename), "/home/pi/security_cam/%" PRIu32 "-%02d-%02dT%02d:%02d:%02d.jpg",
                     1900 + tm_info->tm_year, 1 + tm_info->tm_mon, tm_info->tm_mday, tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);

            if (mkdir("/home/pi/security_cam", 0755) == -1 && errno != EEXIST) {
                perror("mkdir");
                exit(1);
            }

            pid_t pid = fork();
            if (pid == 0) {
                char *args[] = {"libcamera-still", "-o", filename, NULL};
                execvp("libcamera-still", args);
                perror("execvp");
                exit(1);
            } else if (pid > 0) {
                int status;
                waitpid(pid, &status, 0);
                if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
                    log_event("Capture successful.");
                } else {
                    log_event("Capture failed.");
                }
            } else {
                perror("fork");
                exit(1);
            }
        }

        usleep(POLL_INTERVAL);
    }

    return 0;
}

