#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>

#define BUFFER_SIZE 1024 * 1024
#define NUM_BUFFERS 1

int camera_fd;
void *buffer;

void handle_signal(int signum) {
    if (munmap(buffer, BUFFER_SIZE) == -1) {
        perror("munmap");
    }
    close(camera_fd);
    exit(signum);
}

int main(int argc, char *argv[]) {
    char *device = "/dev/video0";
    if (argc > 1) {
        device = argv[1];
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    camera_fd = open(device, O_RDWR);
    if (camera_fd == -1) {
        perror("open");
        return 1;
    }

    if (ioctl(camera_fd, V4L2_QUERYCAP, &cap) == -1) {
        perror("ioctl V4L2_QUERYCAP");
        close(camera_fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(camera_fd);
        return 1;
    }

    struct v4l2_format format;
    memset(&format, 0, sizeof(format));
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format.fmt.pix.width = 640;
    format.fmt.pix.height = 480;
    format.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    format.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(camera_fd, V4L2_REQBUFS, &req) == -1) {
        perror("ioctl V4L2_REQBUFS");
        close(camera_fd);
        return 1;
    }

    if (req.num_buffers < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffers\n");
        close(camera_fd);
        return 1;
    }

    if (ioctl(camera_fd, V4L2_QUERYBUF, &buf) == -1) {
        perror("ioctl V4L2_QUERYBUF");
        close(camera_fd);
        return 1;
    }

    buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(camera_fd);
        return 1;
    }

    if (ioctl(camera_fd, V4L2_STREAMON, &buf_type) == -1) {
        perror("ioctl V4L2_STREAMON");
        munmap(buffer, BUFFER_SIZE);
        close(camera_fd);
        return 1;
    }

    int frame_count = 0;
    while (1) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(camera_fd, &readfds);

        if (select(camera_fd + 1, &readfds, NULL, NULL, &timeout) == -1) {
            perror("select");
            munmap(buffer, BUFFER_SIZE);
            close(camera_fd);
            return 1;
        }

        if (FD_ISSET(camera_fd, &readfds)) {
            if (ioctl(camera_fd, V4L2_DQBUF, &buf) == -1) {
                if (errno == EAGAIN) {
                    continue;
                }
                perror("ioctl V4L2_DQBUF");
                munmap(buffer, BUFFER_SIZE);
                close(camera_fd);
                return 1;
            }

            char filename[20];
            sprintf(filename, "image_%04d.pgm", frame_count);
            FILE *file = fopen(filename, "wb");
            if (file == NULL) {
                perror("fopen");
                munmap(buffer, BUFFER_SIZE);
                close(camera_fd);
                return 1;
            }

            fwrite(buffer, buf.bytesused, 1, file);
            fclose(file);

            if (ioctl(camera_fd, V4L2_QBUF, &buf) == -1) {
                perror("ioctl V4L2_QBUF");
                munmap(buffer, BUFFER_SIZE);
                close(camera_fd);
                return 1;
            }

            frame_count++;
        }
    }

    munmap(buffer, BUFFER_SIZE);
    close(camera_fd);
    return 0;
}

