static struct v4l2_buffer buf;
static struct v4l2_format fmt;
static struct v4l2_capability cap;
static struct v4l2_framebuffer framebuf;
static void *buffers[BUFFER_COUNT];

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        for (int i = 0; i < BUFFER_COUNT; i++) {
            munmap(buffers[i], reqbuf.length);
        }
        free(buffers);
        close(fd);
        exit(0);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) || !(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support video capture and streaming.\n");
        close(fd);
        return 1;
    }

    reqbuf.count = BUFFER_COUNT;
    reqbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbuf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &reqbuf) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return 1;
    }

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 192;
    fmt.fmt.pix.height = 192;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return 1;
    }

    buffers = malloc(reqbuf.count * sizeof(void*));
    if (!buffers) {
        perror("Failed to allocate memory for buffers");
        close(fd);
        return 1;
    }

    for (int i = 0; i < reqbuf.count; i++) {
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            for (int j = 0; j < i; j++) {
                munmap(buffers[j], reqbuf.length);
            }
            free(buffers);
            close(fd);
            return 1;
        }
        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Failed to map buffer");
            for (int j = 0; j < i; j++) {
                munmap(buffers[j], reqbuf.length);
            }
            free(buffers);
            close(fd);
            return 1;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf) < 0) {
        perror("Failed to start streaming");
        for (int i = 0; i < reqbuf.count; i++) {
            munmap(buffers[i], reqbuf.length);
        }
        free(buffers);
        close(fd);
        return 1;
    }

    FILE *file = fopen("image.jpg", "wb");
    if (!file) {
        perror("Failed to open file for writing");
        for (int i = 0; i < reqbuf.count; i++) {
            munmap(buffers[i], reqbuf.length);
        }
        free(buffers);
        close(fd);
        return 1;
    }

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        fclose(file);
        for (int i = 0; i < reqbuf.count; i++) {
            munmap(buffers[i], reqbuf.length);
        }
        free(buffers);
        close(fd);
        return 1;
    }

    if (buf.bytesused <= 0) {
        fprintf(stderr, "Dequeued buffer has zero bytes used.\n");
        fclose(file);
        for (int i = 0; i < reqbuf.count; i++) {
            munmap(buffers[i], reqbuf.length);
        }
        free(buffers);
        close(fd);
        return 1;
    }

    fwrite(buffers[buf.index], buf.bytesused, 1, file);
    fclose(file);

    if (ioctl(fd, VIDIOC_STREAMOFF, &buf) < 0) {
        perror("Failed to stop streaming");
        for (int i = 0; i < reqbuf.count; i++) {
            munmap(buffers[i], reqbuf.length);
        }
        free(buffers);
        close(fd);
        return 1;
    }

    for (int i = 0; i < reqbuf.count; i++) {
        munmap(buffers[i], reqbuf.length);
    }
    free(buffers);
    close(fd);

    return 0;
}

