#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON_PIN 6
#define TILT_DOWN_BUTTON_PIN 7
#define PAN_LEFT_BUTTON_PIN 8
#define PAN_RIGHT_BUTTON_PIN 9

#define PWM_FREQUENCY 50
#define PWM_DUTY_MIN 50
#define PWM_DUTY_MAX 100
#define PWM_DUTY_MID 75
#define PWM_DUTY_STEP 5
#define BUTTON_POLLING_INTERVAL 50

int pan_duty = PWM_DUTY_MID;
int tilt_duty = PWM_DUTY_MID;

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void setup_servos() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pan servo\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for tilt servo\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for pan servo\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for tilt servo\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMdutycycle(PAN_SERVO_PIN, pan_duty) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for pan servo\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMdutycycle(TILT_SERVO_PIN, tilt_duty) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for tilt servo\n");
        exit(EXIT_FAILURE);
    }
}

void setup_buttons() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TILT_UP_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for tilt up button\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TILT_DOWN_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for tilt down button\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PAN_LEFT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pan left button\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PAN_RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pan right button\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(TILT_UP_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for tilt up button\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(TILT_DOWN_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for tilt down button\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(PAN_LEFT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for pan left button\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(PAN_RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for pan right button\n");
        exit(EXIT_FAILURE);
    }
}

void adjust_servo(int *duty, int step) {
    *duty += step;
    if (*duty < PWM_DUTY_MIN) {
        *duty = PWM_DUTY_MIN;
    } else if (*duty > PWM_DUTY_MAX) {
        *duty = PWM_DUTY_MAX;
    }

    if (gpioSetPWMdutycycle(*duty) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, handle_signal);

    setup_servos();
    setup_buttons();

    while (1) {
        if (gpioRead(TILT_UP_BUTTON_PIN) == 0) {
            adjust_servo(&tilt_duty, PWM_DUTY_STEP);
            sleep(BUTTON_POLLING_INTERVAL / 1000);
        }

        if (gpioRead(TILT_DOWN_BUTTON_PIN) == 0) {
            adjust_servo(&tilt_duty, -PWM_DUTY_STEP);
            sleep(BUTTON_POLLING_INTERVAL / 1000);
        }

        if (gpioRead(PAN_LEFT_BUTTON_PIN) == 0) {
            adjust_servo(&pan_duty, -PWM_DUTY_STEP);
            sleep(BUTTON_POLLING_INTERVAL / 1000);
        }

        if (gpioRead(PAN_RIGHT_BUTTON_PIN) == 0) {
            adjust_servo(&pan_duty, PWM_DUTY_STEP);
            sleep(BUTTON_POLLING_INTERVAL / 1000);
        }

        sleep(BUTTON_POLLING_INTERVAL / 1000);
    }

    return 0;
}

