#include <libv4l2.h>
#include <jpeg.h>

#define BUFFER_COUNT 4
#define BUFFER_SIZE 1024 * 1024

static void cleanup(void) {
    if (stream_fd >= 0) {
        v4l2_streamoff last_buffer;
        if (ioctl(stream_fd, VIDIOC_STREAMOFF, &last_buffer) < 0) {
            perror("VIDIOC_STREAMOFF");
        }
        close(stream_fd);
    }
    exit(EXIT_FAILURE);
}

static void handle_sigint(int signum) {
    cleanup();
}

int main() {
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_plane planes[VIDEO_MAX_PLANES];
    struct v4l2_framebuffer framebuf;
    struct jpeg_compress_struct jpeg_compress;
    struct jpeg_error_mgr jpeg_error;
    FILE *jpeg_file;
    int stream_fd;
    int i;

    signal(SIGINT, handle_sigint);

    stream_fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (stream_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    if (ioctl(stream_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        cleanup();
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(stream_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        cleanup();
    }

    for (i = 0; i < BUFFER_COUNT; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(stream_fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            cleanup();
        }

        planes[i].m.offset = buf.m.offset;
        planes[i].length = buf.length;
    }

    memset(&framebuf, 0, sizeof(framebuf));
    framebuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    framebuf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(stream_fd, VIDIOC_STREAMON, &framebuf) < 0) {
        perror("VIDIOC_STREAMON");
        cleanup();
    }

    fd_set readfds;
    struct timeval tv;
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(stream_fd, &readfds);

        if (select(stream_fd + 1, &readfds, NULL, NULL, &tv) < 0) {
            perror("select");
            cleanup();
        }

        if (FD_ISSET(stream_fd, &readfds)) {
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            if (ioctl(stream_fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("VIDIOC_DQBUF");
                cleanup();
            }

            // Convert YUYV to RGB24 and apply blur filter here
            // ...

            // Encode the processed image as JPEG
            jpeg_compress.err = jpeg_std_error(&jpeg_error);
            jpeg_create_compress(&jpeg_compress);
            jpeg_file = fopen("capture_YYYYMMDD_HHMMSS.jpg", "wb");
            if (jpeg_file == NULL) {
                perror("fopen");
                cleanup();
            }
            jpeg_stdio_dest(&jpeg_compress, jpeg_file);
            jpeg_set_defaults(&jpeg_compress);
            jpeg_set_quality(&jpeg_compress, 75, TRUE);
            jpeg_start_compress(&jpeg_compress, TRUE);

            // Write the image data to the JPEG file
            // ...

            jpeg_finish_compress(&jpeg_compress);
            fclose(jpeg_file);
            jpeg_destroy_compress(&jpeg_compress);

            if (ioctl(stream_fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF");
                cleanup();
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

