#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format format;
    struct v4l2_queryctrl queryctrl;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;

    // Open the camera device
    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open camera device");
        return 1;
    }

    // Check if the device exists and can be opened
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query camera capabilities");
        close(fd);
        return 1;
    }

    // Check if the device supports frame size enumeration
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Camera device does not support video capture\n");
        close(fd);
        return 1;
    }

    // Enumerate supported frame sizes
    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_MJPEG; // Example format, adjust as needed

    printf("Supported resolutions:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("  %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
        frmsize.index++;
    }
    if (errno != EINVAL) {
        perror("Failed to enumerate frame sizes");
        close(fd);
        return 1;
    }

    // Enumerate frame intervals for each size
    for (frmsize.index = 0; ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0; frmsize.index++) {
        memset(&frmival, 0, sizeof(frmival));
        frmival.index = 0;
        frmival.pixel_format = V4L2_PIX_FMT_MJPEG; // Example format, adjust as needed
        frmival.width = frmsize.discrete.width;
        frmival.height = frmsize.discrete.height;

        printf("  Frame rates for %dx%d:\n", frmsize.discrete.width, frmsize.discrete.height);
        while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
            printf("    %d/%d\n", frmival.discrete.denominator, frmival.discrete.numerator);
            frmival.index++;
        }
        if (errno != EINVAL) {
            perror("Failed to enumerate frame intervals");
            close(fd);
            return 1;
        }
    }

    // Query autofocus control
    memset(&queryctrl, 0, sizeof(queryctrl));
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) < 0) {
        if (errno == EINVAL) {
            printf("Autofocus control not supported\n");
        } else {
            perror("Failed to query autofocus control");
            close(fd);
            return 1;
        }
    } else {
        printf("Autofocus: %s\n", queryctrl.flags & V4L2_CTRL_FLAG_DISABLED ? "Disabled" : "Enabled");
    }

    close(fd);
    return 0;
}
```

This C program opens the CSI camera device `/dev/video0`, checks its capabilities, enumerates supported frame sizes and frame intervals, and queries the autofocus control. It handles errors and exits with a non-zero status on any fatal error.

