#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_PIN 4
#define TILT_PIN 5
#define UP_PIN 6
#define DOWN_PIN 7
#define LEFT_PIN 8
#define RIGHT_PIN 9

#define PWM_FREQ 50
#define PWM_MIN 1000
#define PWM_MAX 2000
#define PWM_CENTER 1500
#define PWM_STEP 10
#define DELAY_MS 50

volatile int pan_pulse_width = PWM_CENTER;
volatile int tilt_pulse_width = PWM_CENTER;

void handle_signal(int signum) {
    gpioPWM(PAN_PIN, 0);
    gpioPWM(TILT_PIN, 0);
    gpioTerminate();
    exit(signum);
}

void setup_servos() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        exit(EXIT_FAILURE);
    }

    printf("Pin assignments:\n");
    printf("Pan Servo: GPIO%d\n", PAN_PIN);
    printf("Tilt Servo: GPIO%d\n", TILT_PIN);
    printf("Center position: %d µs\n", PWM_CENTER);

    gpioSetMode(PAN_PIN, PI_OUTPUT);
    gpioSetMode(TILT_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(PAN_PIN, PWM_FREQ);
    gpioSetPWMfrequency(TILT_PIN, PWM_FREQ);

    gpioPWM(PAN_PIN, pan_pulse_width);
    gpioPWM(TILT_PIN, tilt_pulse_width);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
}

void handle_button_press(int pin) {
    if (pin == UP_PIN) {
        tilt_pulse_width = (tilt_pulse_width + PWM_STEP > PWM_MAX) ? PWM_MAX : tilt_pulse_width + PWM_STEP;
    } else if (pin == DOWN_PIN) {
        tilt_pulse_width = (tilt_pulse_width - PWM_STEP < PWM_MIN) ? PWM_MIN : tilt_pulse_width - PWM_STEP;
    } else if (pin == LEFT_PIN) {
        pan_pulse_width = (pan_pulse_width - PWM_STEP < PWM_MIN) ? PWM_MIN : pan_pulse_width - PWM_STEP;
    } else if (pin == RIGHT_PIN) {
        pan_pulse_width = (pan_pulse_width + PWM_STEP > PWM_MAX) ? PWM_MAX : pan_pulse_width + PWM_STEP;
    }

    gpioPWM(PAN_PIN, pan_pulse_width);
    gpioPWM(TILT_PIN, tilt_pulse_width);
}

int main() {
    setup_servos();

    while (1) {
        gpioSetMode(UP_PIN, PI_INPUT);
        gpioSetMode(DOWN_PIN, PI_INPUT);
        gpioSetMode(LEFT_PIN, PI_INPUT);
        gpioSetMode(RIGHT_PIN, PI_INPUT);

        gpioSetPullUpDown(UP_PIN, PI_PUD_UP);
        gpioSetPullUpDown(DOWN_PIN, PI_PUD_UP);
        gpioSetPullUpDown(LEFT_PIN, PI_PUD_UP);
        gpioSetPullUpDown(RIGHT_PIN, PI_PUD_UP);

        int up_pressed = gpioRead(UP_PIN) == 0;
        int down_pressed = gpioRead(DOWN_PIN) == 0;
        int left_pressed = gpioRead(LEFT_PIN) == 0;
        int right_pressed = gpioRead(RIGHT_PIN) == 0;

        if (up_pressed) {
            handle_button_press(UP_PIN);
        } else if (down_pressed) {
            handle_button_press(DOWN_PIN);
        } else if (left_pressed) {
            handle_button_press(LEFT_PIN);
        } else if (right_pressed) {
            handle_button_press(RIGHT_PIN);
        }

        usleep(DELAY_MS * 1000);
    }

    return 0;
}

