#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <libjpeg-turbo.h>
#include <curl/curl.h>
#include <dirent.h>
#include <sys/stat.h>

#define PIR_SENSOR_PIN 17
#define DEBOUNCE_TIME 2000 // 2 seconds
#define POLL_INTERVAL 100 // 100 ms
#define JPEG_QUALITY 85

static struct gpiod_line *pir_sensor_line;
static struct gpiod_chip *pir_sensor_chip;
static struct stat motion_captures_dir_stat;
static char *motion_captures_dir = "motion_captures";
static char *filename_template = "motion_capture_%Y-%m-%d_%H-%M-%S.%6N.jpg";
static char filename[256];
static struct timespec last_motion_time;
static struct timespec current_time;
static int motion_detected = 0;
static CURL *curl;
static char *http_endpoint;
static char *http_ip;
static int http_port;

void cleanup_gpiod() {
    if (pir_sensor_line) {
        gpiod_line_free(pir_sensor_line);
        pir_sensor_line = NULL;
    }
    if (pir_sensor_chip) {
        gpiod_chip_free(pir_sensor_chip);
        pir_sensor_chip = NULL;
    }
}

void cleanup_http() {
    if (curl) {
        curl_easy_cleanup(curl);
        curl = NULL;
    }
}

void cleanup_jpeg() {
    jpeg_destroy_decompress(jpeg_decompress_struct);
}

void cleanup_all() {
    cleanup_gpiod();
    cleanup_http();
    cleanup_jpeg();
}

void handle_signal(int signum) {
    cleanup_all();
    exit(signum == SIGINT ? 0 : 1);
}

int init_gpiod() {
    int ret;
    pir_sensor_chip = gpiod_chip_open("/dev/gpiochip0", 0);
    if (!pir_sensor_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    pir_sensor_line = gpiod_line_request_by_name(pir_sensor_chip, "17", "pir_sensor", 0);
    if (!pir_sensor_line) {
        perror("Failed to request GPIO line");
        cleanup_gpiod();
        return -1;
    }

    ret = gpiod_line_set_function(pir_sensor_line, GPIOF_INPUT);
    if (ret < 0) {
        perror("Failed to set GPIO function");
        cleanup_gpiod();
        return -1;
    }

    ret = gpiod_line_set_debounce(pir_sensor_line, DEBOUNCE_TIME);
    if (ret < 0) {
        perror("Failed to set debounce");
        cleanup_gpiod();
        return -1;
    }

    ret = gpiod_line_set_active_low(pir_sensor_line, 1);
    if (ret < 0) {
        perror("Failed to set active low");
        cleanup_gpiod();
        return -1;
    }

    ret = gpiod_line_set_pull_up_down(pir_sensor_line, GPIO_PULL_DOWN);
    if (ret < 0) {
        perror("Failed to set pull down");
        cleanup_gpiod();
        return -1;
    }

    return 0;
}

int init_http(char *ip, int port) {
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize cURL\n");
        return -1;
    }

    http_endpoint = malloc(strlen(ip) + 10);
    if (!http_endpoint) {
        fprintf(stderr, "Failed to allocate memory for HTTP endpoint\n");
        cleanup_http();
        return -1;
    }

    sprintf(http_endpoint, "http://%s:%d/upload", ip, port);

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        return 1;
    }

    http_ip = argv[1];
    http_port = atoi(argv[2]);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpiod() < 0) {
        return 1;
    }

    if (init_http(http_ip, http_port) < 0) {
        cleanup_gpiod();
        return 1;
    }

    if (mkdir(motion_captures_dir, 0755) == -1 && errno != EEXIST) {
        perror("Failed to create motion_captures directory");
        cleanup_all();
        return 1;
    }

    struct jpeg_decompress_struct jpeg_decompress_struct;
    jpeg_create_decompress(&jpeg_decompress_struct);

    while (1) {
        int pir_sensor_value = gpiod_line_get_value(pir_sensor_line);

        if (pir_sensor_value == 0 && !motion_detected) {
            motion_detected = 1;
            motion_detected = 0;
            clock_gettime(CLOCK_REALTIME, &last_motion_time);
        } else if (pir_sensor_value == 1 && motion_detected) {
            clock_gettime(CLOCK_REALTIME, &current_time);
            if (current_time.tv_sec - last_motion_time.tv_sec >= DEBOUNCE_TIME / 1000) {
                motion_detected = 1;
                char *timestamp = gmtime_r(&current_time.tv_sec, NULL);
                strftime(filename, sizeof(filename), filename_template, timestamp);
                filename[sizeof(filename) - 1] = '\0';

                FILE *jpeg_file = fopen(filename, "wb");
                if (!jpeg_file) {
                    perror("Failed to open JPEG file");
                    cleanup_all();
                    return 1;
                }

                if (jpeg_capture_jpeg(jpeg_file, JPEG_QUALITY) < 0) {
                    perror("Failed to capture JPEG");
                    fclose(jpeg_file);
                    cleanup_all();
                    return 1;
                }

                fclose(jpeg_file);

                struct stat jpeg_file_stat;
                if (stat(filename, &jpeg_file_stat) < 0) {
                    perror("Failed to get JPEG file size");
                    cleanup_all();
                    return 1;
                }

                char json_payload[512];
                sprintf(json_payload, "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}", filename, ctime(&current_time.tv_sec), motion_detected, PIR_SENSOR_PIN);

                CURLcode res = curl_easy_setopt(curl, CURLOPT_URL, http_endpoint);
                if (res != CURLE_OK) {
                    fprintf(stderr, "Failed to set URL: %s\n", curl_easy_strerror(res));
                    cleanup_all();
                    return 1;
                }

                res = curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
                if (res != CURLE_OK) {
                    fprintf(stderr, "Failed to set POSTFIELDS: %s\n", curl_easy_strerror(res));
                    cleanup_all();
                    return 1;
                }

                res = curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, strlen(json_payload));
                if (res != CURLE_OK) {
                    fprintf(stderr, "Failed to set POSTFIELDSIZE: %s\n", curl_easy_strerror(res));
                    cleanup_all();
                    return 1;
                }

                res = curl_easy_perform(curl);
                if (res != CURLE_OK) {
                    fprintf(stderr, "Failed to perform HTTP request: %s\n", curl_easy_strerror(res));
                    cleanup_all();
                    return 1;
                }

                res = curl_easy_setopt(curl, CURLOPT_POSTFIELDS, NULL);
                if (res != CURLE_OK) {
                    fprintf(stderr, "Failed to reset POSTFIELDS: %s\n", curl_easy_strerror(res));
                    cleanup_all();
                    return 1;
                }

                motion_detected = 0;
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    cleanup_all();
    return 0;
}

