#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 50 // ms
#define IMG_DIR "/home/pi/images/"
#define LOG_FILE "/home/pi/motion_capture.log"

static gpiod_chip *chip;
static gpiod_line *line;

void cleanup(int signum) {
    if (line) {
        gpiod_line_free(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct timespec start_time, end_time;
    char filename[25];
    char cmd[256];
    FILE *log_file;
    int ret;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return 1;
    }

    // Claim GPIO17 as input with edge-falling detection
    line = gpiod_line_request_any(chip, GPIO_PIN, "motion_sensor", 0, 0, &ret);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        fclose(log_file);
        return 1;
    }

    // Set line to edge-falling detection
    gpiod_line_set_edge(line, GPIO_LINE_BOTH_EDGES);

    // Register cleanup function for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Wait for falling edge with debounce
        gpiod_line_get_value(line);
        clock_gettime(CLOCK_REALTIME, &start_time);
        while (gpiod_line_get_value(line) == 0) {
            clock_gettime(CLOCK_REALTIME, &end_time);
            if (end_time.tv_sec - start_time.tv_sec > DEBOUNCE_TIME / 1000) {
                break;
            }
        }

        // If a falling edge was detected
        if (gpiod_line_get_value(line) == 1) {
            // Generate filename
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%3d.jpg", now_tm);

            // Construct capture command
            snprintf(cmd, sizeof(cmd), "raspistill -o %s%s -w 640 -h 480 -q 85 -t 2000 -n -p", IMG_DIR, filename);

            // Execute capture command
            ret = system(cmd);
            if (ret != 0) {
                fprintf(log_file, "Capture failed: %s\n", cmd);
            } else {
                fprintf(log_file, "Capture successful: %s\n", cmd);
            }
        }
    }

    // Cleanup on exit
    cleanup(0);

    return 0;
}

