#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <signal.h>
#include <linux/videodev2.h>

#define BUFFER_SIZE 1024 * 1024
#define CROP_WIDTH 200
#define CROP_HEIGHT 150

static int fd;
static struct v4l2_format fmt;
static struct v4l2_requestbuffers reqbuf;
static struct v4l2_buffer buf;
static void *buffer;
static int cropped_fd;

void cleanup() {
    if (cropped_fd != -1) {
        close(cropped_fd);
    }
    if (buffer != NULL) {
        munmap(buffer, BUFFER_SIZE);
    }
    if (fd != -1) {
        close(fd);
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &fmt) == -1) {
        perror("VIDIOC_QUERYCAP");
        exit(EXIT_FAILURE);
    }

    if (!(fmt.fmt.pix.flags & V4L2_PIX_FMT_FLAG_COMPRESSED)) {
        printf("Device does not support uncompressed formats.\n");
        exit(EXIT_FAILURE);
    }

    reqbuf.count = 1;
    reqbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbuf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &reqbuf) == -1) {
        perror("VIDIOC_REQBUFS");
        exit(EXIT_FAILURE);
    }

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        exit(EXIT_FAILURE);
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf) == -1) {
        perror("VIDIOC_STREAMON");
        exit(EXIT_FAILURE);
    }

    cropped_fd = open("cropped.yuv", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (cropped_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    fd_set readfds;
    struct timeval tv;
    int ret;

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);
        tv.tv_sec = 2;
        tv.tv_usec = 0;

        ret = select(fd + 1, &readfds, NULL, NULL, &tv);
        if (ret == -1) {
            perror("select");
            exit(EXIT_FAILURE);
        } else if (ret == 0) {
            printf("Timeout occurred.\n");
            continue;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("VIDIOC_DQBUF");
            exit(EXIT_FAILURE);
        }

        if (buf.index != 0 || buf.bytesused != fmt.fmt.pix.sizeimage) {
            printf("Unexpected buffer index or size.\n");
            exit(EXIT_FAILURE);
        }

        if (fmt.fmt.pix.width != 640 || fmt.fmt.pix.height != 480 || fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
            printf("Capture format does not match requested format.\n");
            exit(EXIT_FAILURE);
        }

        int cropped_size = CROP_WIDTH * CROP_HEIGHT * 2;
        char *cropped_buffer = malloc(cropped_size);
        if (cropped_buffer == NULL) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }

        for (int y = 0; y < CROP_HEIGHT; y++) {
            for (int x = 0; x < CROP_WIDTH; x++) {
                int src_index = (y * 640 + x) * 2;
                int dest_index = (y * CROP_WIDTH + x) * 2;
                cropped_buffer[dest_index] = buffer[src_index];
                cropped_buffer[dest_index + 1] = buffer[src_index + 1];
            }
        }

        if (write(cropped_fd, cropped_buffer, cropped_size) != cropped_size) {
            perror("write");
            exit(EXIT_FAILURE);
        }

        free(cropped_buffer);

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            exit(EXIT_FAILURE);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

