#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define PWM_FREQUENCY 50
#define DEGREE_TO_PULSE 10
#define NEUTRAL_ANGLE 90
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define STEP_ANGLE 5
#define DELAY_MS 100

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

void cleanup() {
    gpioServoWrite(PAN_SERVO_PIN, NEUTRAL_ANGLE * DEGREE_TO_PULSE);
    gpioServoWrite(TILT_SERVO_PIN, NEUTRAL_ANGLE * DEGREE_TO_PULSE);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (gpioServoCfg(PAN_SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to configure PWM for pan servo.\n");
        cleanup();
    }

    if (gpioServoCfg(TILT_SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to configure PWM for tilt servo.\n");
        cleanup();
    }

    int pan_angle = NEUTRAL_ANGLE * DEGREE_TO_PULSE;
    int tilt_angle = NEUTRAL_ANGLE * DEGREE_TO_PULSE;

    gpioServoWrite(PAN_SERVO_PIN, pan_angle);
    gpioServoWrite(TILT_SERVO_PIN, tilt_angle);

    while (!stop) {
        char c = getchar();

        switch (c) {
            case 'q':
                stop = 1;
                break;
            case 'w':
                if (pan_angle + STEP_ANGLE * DEGREE_TO_PULSE <= MAX_ANGLE * DEGREE_TO_PULSE) {
                    pan_angle += STEP_ANGLE * DEGREE_TO_PULSE;
                    gpioServoWrite(PAN_SERVO_PIN, pan_angle);
                } else {
                    fprintf(stderr, "Pan angle out of range.\n");
                }
                break;
            case 's':
                if (pan_angle - STEP_ANGLE * DEGREE_TO_PULSE >= MIN_ANGLE * DEGREE_TO_PULSE) {
                    pan_angle -= STEP_ANGLE * DEGREE_TO_PULSE;
                    gpioServoWrite(PAN_SERVO_PIN, pan_angle);
                } else {
                    fprintf(stderr, "Pan angle out of range.\n");
                }
                break;
            case 'a':
                if (tilt_angle + STEP_ANGLE * DEGREE_TO_PULSE <= MAX_ANGLE * DEGREE_TO_PULSE) {
                    tilt_angle += STEP_ANGLE * DEGREE_TO_PULSE;
                    gpioServoWrite(TILT_SERVO_PIN, tilt_angle);
                } else {
                    fprintf(stderr, "Tilt angle out of range.\n");
                }
                break;
            case 'd':
                if (tilt_angle - STEP_ANGLE * DEGREE_TO_PULSE >= MIN_ANGLE * DEGREE_TO_PULSE) {
                    tilt_angle -= STEP_ANGLE * DEGREE_TO_PULSE;
                    gpioServoWrite(TILT_SERVO_PIN, tilt_angle);
                } else {
                    fprintf(stderr, "Tilt angle out of range.\n");
                }
                break;
            default:
                break;
        }

        if (!stop) {
            usleep(DELAY_MS * 1000);
        }
    }

    cleanup();

    return 0;
}

