                    pan_angle += STEP_ANGLE * DEGREE_TO_PULSE;
                    gpioServoWrite(PAN_SERVO_PIN, pan_angle);
                } else {
                    fprintf(stderr, "Pan angle out of range.\n");
                }
                break;
            case 's':
                if (pan_angle - STEP_ANGLE * DEGREE_TO_PULSE >= MIN_ANGLE * DEGREE_TO_PULSE) {
                    pan_angle -= STEP_ANGLE * DEGREE_TO_PULSE;
                    gpioServoWrite(PAN_SERVO_PIN, pan_angle);
                } else {
                    fprintf(stderr, "Pan angle out of range.\n");
                }
                break;
            case 'a':
                if (tilt_angle + STEP_ANGLE * DEGREE_TO_PULSE <= MAX_ANGLE * DEGREE_TO_PULSE) {
                    tilt_angle += STEP_ANGLE * DEGREE_TO_PULSE;
                    gpioServoWrite(TILT_SERVO_PIN, tilt_angle);
                } else {
                    fprintf(stderr, "Tilt angle out of range.\n");
                }
                break;
            case 'd':
                if (tilt_angle - STEP_ANGLE * DEGREE_TO_PULSE >= MIN_ANGLE * DEGREE_TO_PULSE) {
                    tilt_angle -= STEP_ANGLE * DEGREE_TO_PULSE;
                    gpioServoWrite(TILT_SERVO_PIN, tilt_angle);
                } else {
                    fprintf(stderr, "Tilt angle out of range.\n");
                }
                break;
            default:
                break;
        }

        if (!stop) {
            usleep(DELAY_MS * 1000);
        }
    }

    cleanup();

    return 0;
}
