#include <stdint.h>

#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PROC_STAT_FILE "/proc/stat"

static int i2c_fd;
static uint8_t buffer[SSD1306_WIDTH * SSD1306_HEIGHT / 8];

void draw_text(int x, int y, const char *text) {
    int i, j;
    for (i = 0; text[i]; i++) {
        for (j = 0; j < 5; j++) {
            if (text[i] & (1 << (4 - j))) {
                buffer[y * SSD1306_WIDTH / 8 + x + j] |= (1 << (7 - (x % 8)));
            }
        }
        x += 6;
    }
}

void draw_cpu_temp(int x, int y, int temp) {
    char temp_str[10];
    sprintf(temp_str, "CPU Temp: %d C", temp);
    draw_text(x, y, temp_str);
}

void draw_cpu_usage(int x, int y, float usage) {
    char usage_str[10];
    sprintf(usage_str, "CPU Usage: %.1f%%", usage);
    draw_text(x, y + 16, usage_str);
}

void i2c_write(uint8_t reg, uint8_t *data, size_t len) {
    int ret;
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    ret = write(i2c_fd, buf, len + 1);
    if (ret != len + 1) {
        perror("i2c_write");
        exit(EXIT_FAILURE);
    }
}

void display_update() {
    i2c_write(0x40, buffer, SSD1306_WIDTH * SSD1306_HEIGHT / 8);
}

void read_cpu_temp(int *temp) {
    FILE *file = fopen(CPU_TEMP_FILE, "r");
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    if (fscanf(file, "%d", temp) != 1) {
        fprintf(stderr, "Failed to read CPU temperature\n");
        fclose(file);
        exit(EXIT_FAILURE);
    }
    fclose(file);
}

void read_cpu_usage(float *usage) {
    FILE *file = fopen(PROC_STAT_FILE, "r");
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    char line[256];
    if (!fgets(line, sizeof(line), file)) {
        fprintf(stderr, "Failed to read CPU usage\n");
        fclose(file);
        exit(EXIT_FAILURE);
    }
    fclose(file);

    long long total_time = 0, idle_time = 0;
    sscanf(line, "cpu %lld %lld", &total_time, &idle_time);
    *usage = (float)(total_time - idle_time) / total_time * 100.0;
}

void sigint_handler(int signum) {
    printf("\nSIGINT received, cleaning up...\n");
    close(i2c_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);

    i2c_fd = i2c_open(1, SSD1306_I2C_ADDR, 0);
    if (i2c_fd < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int cpu_temp;
        float cpu_usage;

        read_cpu_temp(&cpu_temp);
        read_cpu_usage(&cpu_usage);

        memset(buffer, 0, sizeof(buffer));
        draw_cpu_temp(0, 0, cpu_temp);
        draw_cpu_usage(0, 16, cpu_usage);

        display_update();

        sleep(1);
    }

    close(i2c_fd);
    return 0;
}

