#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

void lcd_init() {
    FILE *file;
    char buffer[256];

    file = fopen("/dev/i2c-"+(char)(LCD_I2C_BUS+48), "w");
    if (!file) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "0x%02X\n", 0x33);
    if (write(fileno(file), buffer, strlen(buffer)) != strlen(buffer)) {
        perror("Failed to write to I2C device");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "0x%02X\n", 0x32);
    if (write(fileno(file), buffer, strlen(buffer)) != strlen(buffer)) {
        perror("Failed to write to I2C device");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "0x%02X\n", 0x28);
    if (write(fileno(file), buffer, strlen(buffer)) != strlen(buffer)) {
        perror("Failed to write to I2C device");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "0x%02X\n", 0x0C);
    if (write(fileno(file), buffer, strlen(buffer)) != strlen(buffer)) {
        perror("Failed to write to I2C device");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "0x%02X\n", 0x06);
    if (write(fileno(file), buffer, strlen(buffer)) != strlen(buffer)) {
        perror("Failed to write to I2C device");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    sprintf(buffer, "0x%02X\n", 0x01);
    if (write(fileno(file), buffer, strlen(buffer)) != strlen(buffer)) {
        perror("Failed to write to I2C device");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fclose(file);
}

void lcd_print(const char *message) {
    FILE *file;
    char buffer[256];

    file = fopen("/dev/i2c-"+(char)(LCD_I2C_BUS+48), "w");
    if (!file) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < strlen(message); i++) {
        sprintf(buffer, "0x%02X\n", message[i]);
        if (write(fileno(file), buffer, strlen(buffer)) != strlen(buffer)) {
            perror("Failed to write to I2C device");
            fclose(file);
            exit(EXIT_FAILURE);
        }
    }

    fclose(file);
}

void update_lcd(float flow_rate, float total_volume) {
    char message[32];
    sprintf(message, "Flow: %.2f L/min  Total: %.2f L", flow_rate, total_volume);
    lcd_print(message);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(WATER_FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        perror("Failed to set GPIO mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(WATER_FLOW_SENSOR_PIN, PI_PUD_UP) < 0) {
        perror("Failed to set GPIO pull-up/down");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    lcd_init();

    float flow_rate = 0.0;
    float total_volume = 0.0;
    unsigned long last_pulse_time = 0;
    unsigned long pulse_count = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        if (gpioRead(WATER_FLOW_SENSOR_PIN) == 0) {
            unsigned long current_time = gpioTick();
            if (current_time - last_pulse_time >= 1000000) { // 1 second
                pulse_count++;
                last_pulse_time = current_time;
            }
        }

        if (gpioTick() - last_pulse_time >= 10000000) { // 10 seconds
            flow_rate = (pulse_count * 60.0) / 7.5; // YF-S201 sensor calibration
            total_volume += flow_rate / 60.0;
            printf("Flow Rate: %.2f L/min  Total Volume: %.2f L\n", flow_rate, total_volume);
            pulse_count = 0;
            update_lcd(flow_rate, total_volume);
        }

        usleep(100000); // Sleep for 100ms
    }

    printf("Stopping...\n");
    gpioTerminate();
    return 0;
}

