#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define GPIO_ANEMOMETER 17
#define ADC_CHANNEL 0
#define SPI_DEV "/dev/spidev0.0"
#define I2C_DEV "/dev/i2c-1"
#define LCD_ADDR 0x27

static gpiod_line *anemometer_line;
static int spi_fd;
static int i2c_fd;

void handle_interrupt(struct gpiod_line *line, struct gpiod_line_event *event) {
    static struct timespec start_time;
    static int pulse_count = 0;
    struct timespec end_time;
    double wind_speed;

    clock_gettime(CLOCK_MONOTONIC, &end_time);

    if (start_time.tv_sec == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);
    }

    if (end_time.tv_sec - start_time.tv_sec >= 0.5) {
        pulse_count++;
        wind_speed = (double)pulse_count * 1.492; // Assuming 1 pulse per 1.492 m/s
        pulse_count = 0;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        update_lcd(wind_speed);
    }
}

void update_lcd(double wind_speed) {
    char buffer[32];
    int ret;

    sprintf(buffer, "Speed: %.2f m/s", wind_speed);
    ret = write(i2c_fd, buffer, strlen(buffer));
    if (ret < 0) {
        perror("Error writing to LCD");
        return;
    }

    sprintf(buffer, "Dir: %d", read_adc());
    ret = write(i2c_fd, buffer, strlen(buffer));
    if (ret < 0) {
        perror("Error writing to LCD");
        return;
    }
}

int read_adc() {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };
    uint8_t adc_data[2];
    int ret;

    tr.tx_buf = (unsigned long)&adc_data[0];
    tr.rx_buf = (unsigned long)&adc_data[1];
    tr.len = 2;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("Error reading ADC");
        return -1;
    }

    return (adc_data[1] << 8) | adc_data[0];
}

void cleanup() {
    gpiod_line_free(anemometer_line);
    close(spi_fd);
    close(i2c_fd);
}

void signal_handler(int signum) {
    cleanup();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    anemometer_line = gpiod_line_request_by_name(chip, "gpio17", "Anemometer", 0);
    if (!anemometer_line) {
        perror("Failed to request anemometer line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_direction_set(anemometer_line, GPIOF_INPUT);
    if (ret) {
        perror("Failed to set anemometer line direction");
        gpiod_line_free(anemometer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_event_request(anemometer_line, handle_interrupt, NULL);
    if (ret) {
        perror("Failed to request anemometer line event");
        gpiod_line_free(anemometer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_free(anemometer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_line_free(anemometer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD_8);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_line_free(anemometer_line);
