void lcd_init() {
    FILE *file = fopen(I2C_BUS, "w");
    if (!file) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (fprintf(file, "0x%02x\n", LCD_ADDR) < 0) {
        perror("Failed to set I2C address");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fclose(file);
}

void lcd_write(const char *message) {
    FILE *file = fopen(I2C_BUS, "w");
    if (!file) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (fprintf(file, "0x%02x\n", LCD_ADDR) < 0) {
        perror("Failed to set I2C address");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    if (fprintf(file, "0x%02x\n", 0x80) < 0) { // Set cursor to first line
        perror("Failed to write to I2C bus");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    if (fprintf(file, "%s\n", message) < 0) {
        perror("Failed to write to I2C bus");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fclose(file);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(17, PI_INPUT) < 0) {
        perror("Failed to set GPIO mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFunc(17, NULL) < 0) {
        perror("Failed to set GPIO alert function");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpioTerminate();
}

int main() {
    signal(SIGTERM, handle_sigterm);
    signal(SIGINT, handle_sigterm);

    setup_gpio();
    lcd_init();

    int pulse_count = 0;
    int last_time = 0;

    while (running) {
        int current_time = time(NULL);
        if (current_time - last_time >= 1) {
            last_time = current_time;
            pulse_count = 0; // Reset pulse count for new interval
        }

        if (gpioTick(17) > 0) {
            pulse_count++;
        }

        if (pulse_count == 0) {
            lcd_write("Flow Rate: 0.00 L/min");
        } else {
            float flow_rate = (float)pulse_count * 7.5 / 60.0; // YF-S201 sensor calibration
            char buffer[20];
            sprintf(buffer, "Flow Rate: %.2f L/min", flow_rate);
            lcd_write(buffer);
        }

        usleep(100000); // Sleep for 100ms
    }

    cleanup();
    return 0;
}

