    signal(SIGTERM, signal_handler);

    while (1) {
        for (int col = 0; col < COLS; col++) {
            if (ioctl(gpio->set, GPIO_SET_VALUE, col + BCM14) < 0) {
                perror("Failed to set column GPIO value");
                cleanup_gpio();
                exit(EXIT_FAILURE);
            }
