#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_PIN_IR_SENSOR 4
#define GPIO_PIN_LED 17
#define FILE_NAME "proximity.log"
#define DEBOUNCE_TIME 100 // ms

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void blink_led(struct gpiod_line *led) {
    if (gpiod_line_set_value(led, 1) < 0) {
        handle_error("Failed to set LED value");
    }
    usleep(100 * 1000); // 100 ms
    if (gpiod_line_set_value(led, 0) < 0) {
        handle_error("Failed to set LED value");
    }
}

static void write_detection_to_file(const char *timestamp) {
    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        handle_error("Failed to open file");
    }
    if (fprintf(file, "%s Object detected\n", timestamp) < 0) {
        handle_error("Failed to write to file");
    }
    fclose(file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *ir_sensor, *led;
    int ret;

    // Open the GPIO chip
    if ((ret = gpiod_chip_open("the library's API call", &chip)) < 0) {
        handle_error("Failed to open GPIO chip");
    }

    // Request the IR sensor line
    if ((ret = gpiod_line_request_any(chip, GPIO_PIN_IR_SENSOR, "IR Sensor", &ir_sensor)) < 0) {
        handle_error("Failed to request IR sensor line");
    }

    // Set the IR sensor line to input
    if ((ret = gpiod_line_direction_input(ir_sensor)) < 0) {
        handle_error("Failed to set IR sensor direction");
    }

    // Request the LED line
    if ((ret = gpiod_line_request_any(chip, GPIO_PIN_LED, "LED", &led)) < 0) {
        handle_error("Failed to request LED line");
    }

    // Set the LED line to output
    if ((ret = gpiod_line_direction_output(led)) < 0) {
        handle_error("Failed to set LED direction");
    }

    // Set the LED line to low initially
    if ((ret = gpiod_line_set_value(led, 0)) < 0) {
        handle_error("Failed to set LED value");
    }

    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    int last_value = 1; // Assume initially HIGH

    while (1) {
        // Read the sensor value
        if ((ret = gpiod_line_get_value(ir_sensor, &last_value)) < 0) {
            handle_error("Failed to read IR sensor value");
        }

        // Check for falling edge
        if (last_value == 0 && last_value != 1) {
            // Object detected
            blink_led(led);

            // Get current time
            clock_gettime(CLOCK_REALTIME, &ts);
            tm = gmtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%FT%T%Ez", tm);

            // Write detection to file
            write_detection_to_file(timestamp);

            // Reset last_value to HIGH
            last_value = 1;
        }

        // Sleep for 100 ms
        usleep(DEBOUNCE_TIME * 1000);
    }

    // Cleanup
    gpiod_line_free(ir_sensor);
    gpiod_line_free(led);
    gpiod_chip_put(chip);

    return 0;
}

