#include <libgpiod.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x60
#define PART_ID 0x60
#define PROXIMITY_REG 0x03
#define AMBIENT_LIGHT_REG 0x04
#define LOG_FILE "biometric_data.log"

static FILE *log_file;
static struct i2c_client *i2c_client;

void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_client) {
        i2c_client_close(i2c_client);
    }
    exit(0);
}

int read_sensor_data(uint8_t reg, uint8_t *data) {
    int ret;
    ret = i2c_smbus_read_byte_data(i2c_client, reg);
    if (ret < 0) {
        perror("i2c_smbus_read_byte_data");
        return -1;
    }
    *data = ret;
    return 0;
}

int write_sensor_data(uint8_t reg, uint8_t data) {
    int ret;
    ret = i2c_smbus_write_byte_data(i2c_client, reg, data);
    if (ret < 0) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }
    return 0;
}

int main() {
    struct i2c_client *client;
    uint8_t part_id;
    uint8_t proximity_data;
    uint8_t ambient_light_data;
    struct timespec ts;

    if (gpiod_init() < 0) {
        perror("gpiod_init");
        return 1;
    }

    if ((i2c_client = i2c_client_new(I2C_BUS, SENSOR_ADDR)) == NULL) {
        fprintf(stderr, "Failed to create I2C client\n");
        return 1;
    }

    if (write_sensor_data(0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        i2c_client_close(i2c_client);
        return 1;
    }

    if (read_sensor_data(0x00, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        i2c_client_close(i2c_client);
        return 1;
    }

    if (part_id != PART_ID) {
        fprintf(stderr, "Incorrect PART_ID, expected 0x%02X, got 0x%02X\n", PART_ID, part_id);
        i2c_client_close(i2c_client);
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        i2c_client_close(i2c_client);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        if (read_sensor_data(PROXIMITY_REG, &proximity_data) < 0 ||
            read_sensor_data(AMBIENT_LIGHT_REG, &ambient_light_data) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.%09ld, %02X, %02X\n",
                ts.tv_sec / 60 / 60 / 24 + 1970,
                (ts.tv_sec / 60 / 60) % 24 + 1,
                (ts.tv_sec / 60) % 60,
                ts.tv_sec % 60,
                (ts.tv_nsec / 1000000000) % 100,
                (ts.tv_nsec / 1000000) % 1000,
                proximity_data,
                ambient_light_data);

        fflush(log_file);
        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    i2c_client_close(i2c_client);
    gpiod_cleanup();

    return 0;
}

