        fprintf(stderr, "Failed to reset sensor\n");
        i2c_client_close(i2c_client);
        return 1;
    }

    if (read_sensor_data(0x00, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        i2c_client_close(i2c_client);
        return 1;
    }

    if (part_id != PART_ID) {
        fprintf(stderr, "Incorrect PART_ID, expected 0x%02X, got 0x%02X\n", PART_ID, part_id);
        i2c_client_close(i2c_client);
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        i2c_client_close(i2c_client);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        if (read_sensor_data(PROXIMITY_REG, &proximity_data) < 0 ||
