#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define MAX_DISTANCE 400 // cm
#define MIN_DISTANCE 2 // cm
#define WATER_THRESHOLD 15 // cm
#define LOG_INTERVAL 60 // seconds

static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (trigger_line) {
        gpiod_line_request_free(trigger_line);
    }
    if (echo_line) {
        gpiod_line_request_free(echo_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum == SIGINT ? 0 : 1);
}

void log_distance(double distance, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Distance: %.2f cm - %s\n", buffer, distance, message);
    fflush(log_file);
}

double measure_distance() {
    struct timespec start, end;
    int echo_level;
    double duration;

    // Set trigger pin high for 10us
    gpiod_line_set_value(trigger_line, 1);
    nanosleep(&start, &end);
    start.tv_sec = 0;
    start.tv_nsec = 10000;
    nanosleep(&start, &end);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo to rise
    echo_level = gpiod_line_get_value(echo_line);
    while (echo_level == 0) {
        echo_level = gpiod_line_get_value(echo_line);
    }

    // Wait for echo to fall
    start = end;
    while (echo_level == 1) {
        echo_level = gpiod_line_get_value(echo_line);
    }

    // Calculate duration
    duration = (end.tv_sec - start.tv_sec) * 1e9 + (end.tv_nsec - start.tv_nsec);
    duration /= 1e6; // Convert to microseconds

    // Calculate distance
    double distance = (duration * 343.0 / 2.0) / 10000.0; // Speed of sound = 343 m/s

    // Check if distance is within valid range
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        log_distance(distance, "Invalid distance reading");
        return -1.0;
    }

    return distance;
}

int main() {
    struct gpiod_line_request *trigger_req;
    struct gpiod_line_request *echo_req;
    double distance;

    // Initialize GPIO
    if (gpiod_chip_open("/dev/gpiochip0", &trigger_req) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }
    if (gpiod_line_request_by_name(trigger_req, "gpio%d", TRIGGER_PIN, &trigger_line) < 0) {
        perror("Failed to request trigger GPIO");
        return 1;
    }
    if (gpiod_line_request_by_name(trigger_req, "gpio%d", ECHO_PIN, &echo_line) < 0) {
        perror("Failed to request echo GPIO");
        return 1;
    }

    // Set trigger pin as output and echo pin as input
    if (gpiod_line_request_set_direction(trigger_line, GPIO_LINE_DIRECTION_OUT) < 0) {
        perror("Failed to set trigger direction");
        return 1;
    }
    if (gpiod_line_request_set_direction(echo_line, GPIO_LINE_DIRECTION_IN) < 0) {
        perror("Failed to set echo direction");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        distance = measure_distance();
        if (distance >= 0) {
            log_distance(distance, "");
            if (distance < WATER_THRESHOLD) {
                log_distance(distance, "Time to water the plant!");
            }
        }
        sleep(LOG_INTERVAL);
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_request_free(trigger_line);
    gpiod_line_request_free(echo_line);
    gpiod_chip_close(trigger_req);

    return 0;
}

