    if (!gpio_line) {
        perror("Failed to request GPIO line by name");
        close(i2c_fd);
        return 1;
    }

    if (configure_gpio() < 0) {
        gpiod_line_release(gpio_line);
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        struct timespec timeout = { .tv_sec = 0, .tv_nsec = TIMEOUT_MS * 1000000 };
        int ret = gpiod_line_wait_for_event(gpio_line, &timeout);
        if (ret < 0) {
            perror("Failed to wait for GPIO event");
            break;
        }

        // Trigger a single distance measurement (code for this would be specific to the VL53L0X sensor)
