#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BUFFER_SIZE 128
#define I2C_BUS "/dev/i2c-1"
#define TDK_CH101_ADDR 0x50
#define TDK_CH101_CMD_TRIGGER 0x00
#define TDK_CH101_CMD_READ 0x01
#define TDK_CH101_CMD_WRITE 0x02
#define TDK_CH101_CMD_READ_RESULT 0x03

static int i2c_fd;
static int log_fd;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    exit(0);
}

void write_i2c(uint8_t cmd, uint8_t data) {
    int bytes_written;
    uint8_t buffer[2] = {cmd, data};

    bytes_written = write(i2c_fd, buffer, 2);
    if (bytes_written != 2) {
        fprintf(stderr, "Error writing to I2C bus\n");
        return;
    }
}

uint8_t read_i2c(uint8_t cmd) {
    uint8_t buffer[2];
    int bytes_read;

    write_i2c(cmd, 0);
    bytes_read = read(i2c_fd, buffer, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C bus\n");
        return 0;
    }

    return buffer[1];
}

void log_reading(const char *timestamp, uint8_t distance_mm) {
    char log_line[BUFFER_SIZE];
    snprintf(log_line, BUFFER_SIZE, "%s, %u\n", timestamp, distance_mm);

    if (write(log_fd, log_line, strlen(log_line)) != strlen(log_line)) {
        fprintf(stderr, "Error writing to log file\n");
    }

    printf("%s\n", log_line);
}

int main() {
    struct sigaction sa;
    struct timespec delay;
    char timestamp[BUFFER_SIZE];
    uint8_t distance_mm;

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TDK_CH101_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_fd = open("distance_log.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        time_t rawtime;
        struct tm *timeinfo;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S, ", timeinfo);

        write_i2c(TDK_CH101_CMD_TRIGGER, 0);
        usleep(50000); // 50 ms delay
        distance_mm = read_i2c(TDK_CH101_CMD_READ_RESULT);

        log_reading(timestamp, distance_mm);

        delay.tv_sec = 0;
        delay.tv_nsec = 200000000; // 200 ms delay
        nanosleep(&delay, NULL);
    }

    close(i2c_fd);
    close(log_fd);

    return 0;
}

