#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define LOG_FILE "obstacle_log.txt"
#define INTERVAL 100 // milliseconds

gpiod_chip *chip;
gpiod_line *sensor1, *sensor2;

void handle_sigint(int signum) {
    if (sensor1) {
        gpiod_line_request_free(sensor1);
    }
    if (sensor2) {
        gpiod_line_request_free(sensor2);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(0);
}

int main() {
    struct timespec ts;
    char buffer[64];
    FILE *log_file;

    // Initialize libgpiod
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO lines for sensors
    if ((sensor1 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_SENSOR1, "sensor1", 0)) == NULL) {
        perror("Failed to request GPIO for sensor1");
        goto cleanup;
    }

    if ((sensor2 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_SENSOR2, "sensor2", 0)) == NULL) {
        perror("Failed to request GPIO for sensor2");
        goto cleanup;
    }

    // Set GPIO lines as inputs
    if (gpiod_line_direction_set(sensor1, GPIOD_LINE_DIRECTION_IN) < 0) {
        perror("Failed to set direction for sensor1");
        goto cleanup;
    }

    if (gpiod_line_direction_set(sensor2, GPIOD_LINE_DIRECTION_IN) < 0) {
        perror("Failed to set direction for sensor2");
        goto cleanup;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        ts.tv_sec = 0;
        ts.tv_nsec = INTERVAL * 1000000; // Convert milliseconds to nanoseconds

        nanosleep(&ts, NULL);

        // Read sensor values
        int sensor1_value = gpiod_line_get_value(sensor1);
        int sensor2_value = gpiod_line_get_value(sensor2);

        // Log values with timestamp
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d\n", buffer, sensor1_value, sensor2_value);

        // Handle read errors
        if (sensor1_value == -1) {
            fprintf(stderr, "Error reading sensor1\n");
        }
        if (sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor2\n");
        }
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (sensor1) {
        gpiod_line_request_free(sensor1);
    }
    if (sensor2) {
        gpiod_line_request_free(sensor2);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }

    return 0;
}

