#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define I2C_ADDR 0x60
#define I2C_BUS 1
#define I2C_RETRY_COUNT 3
#define LOG_FILE "biometric_log.txt"

static int i2c_fd;
static FILE *log_file;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        i2c_close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int read_sensor_data(void) {
    uint8_t data[2];
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        int result = i2c_read_device(i2c_fd, I2C_ADDR, data, 2);
        if (result == 2) {
            return 1; // Success
        } else if (result == -1) {
            retries++;
            sleep(1); // Wait before retrying
        } else {
            return 0; // Error
        }
    }

    return 0; // Failed after retries
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = i2c_open(I2C_BUS, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2c_close(i2c_fd);
        return 1;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        if (read_sensor_data()) {
            fprintf(log_file, "%ld.%09ld: Proximity=%d, Ambient=%d\n",
                    (long)ts.tv_sec, (long)ts.tv_nsec, data[0], data[1]);
        } else {
            fprintf(log_file, "%ld.%09ld: Sensor read failed\n",
                    (long)ts.tv_sec, (long)ts.tv_nsec);
        }

        sleep(0.5); // Sleep for 500ms
    }

    fclose(log_file);
    i2c_close(i2c_fd);

    return 0;
}

