#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x5a // Replace with the actual I2C address of the sensor
#define CMD_FRAME 0x00 // Replace with the actual command frame
#define RESPONSE_SIZE 15
#define HEADER_VALUE 0x01 // Replace with the actual header value
#define DISTANCE_OFFSET 11
#define NUM_SAMPLES 10
#define SAMPLING_INTERVAL 100 // in milliseconds

int i2c_fd;

void handle_sigint(int signum) {
    close(i2c_fd);
    exit(0);
}

int read_sensor() {
    uint8_t cmd_frame[4] = {CMD_FRAME, 0x00, 0x00, 0x00};
    uint8_t response[RESPONSE_SIZE];

    if (write(i2c_fd, cmd_frame, 4) != 4) {
        perror("Failed to write to I2C device");
        return -1;
    }

    usleep(10000); // Wait at least 10 ms

    if (read(i2c_fd, response, RESPONSE_SIZE) != RESPONSE_SIZE) {
        perror("Failed to read from I2C device");
        return -1;
    }

    if (response[0] != HEADER_VALUE) {
        fprintf(stderr, "Invalid header value received\n");
        return -1;
    }

    uint16_t distance = (response[DISTANCE_OFFSET + 1] << 8) | response[DISTANCE_OFFSET];
    return distance;
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen("intrusion_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    uint16_t total_distance = 0;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        int distance = read_sensor();
        if (distance < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            fclose(log_file);
            close(i2c_fd);
            return 1;
        }

        total_distance += distance;
        usleep(SAMPLING_INTERVAL * 1000); // Sleep for 100 ms
    }

    uint16_t average_distance = total_distance / NUM_SAMPLES;
    if (average_distance < 1000) {
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        fprintf(log_file, "%02d:%02d:%02d - Average Distance: %d mm\n",
                timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, average_distance);
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

