#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c-dev.h>

#define I2C_BUS 1
#define VL53L0X_I2C_ADDR 0x29
#define VL53L0X_MODEL_ID_REG 0x00
#define VL53L0X_MODEL_ID_VALUE 0x00000001
#define RESULT_INTERRUPT_STATUS 0x130

static i2c_client_t *i2c_client;

void handle_signal(int signum) {
    if (i2c_client) {
        i2c_close(i2c_client);
    }
    exit(signum);
}

int main() {
    struct timespec timeout = { .tv_sec = 0, .tv_nsec = 100 * 1000 * 1000 };
    char model_id[4];
    int distance;
    struct tm *tm;
    char buffer[32];

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C client
    if ((i2c_client = i2c_open(I2C_BUS, VL53L0X_I2C_ADDR)) < 0) {
        perror("i2c_open");
        return 1;
    }

    // Verify sensor presence
    if (i2c_read_i2c_block_data(i2c_client, VL53L0X_MODEL_ID_REG, 4, model_id) < 0) {
        perror("i2c_read_i2c_block_data");
        i2c_close(i2c_client);
        return 1;
    }

    if (memcmp(model_id, (char[]){0x01, 0x00, 0x00, 0x00}, 4) != 0) {
        fprintf(stderr, "Invalid model ID: %08X\n", *(unsigned int*)model_id);
        i2c_close(i2c_client);
        return 1;
    }

    printf("VL53L0X sensor detected.\n");

    // Main loop
    while (1) {
        // Read distance
        if (i2c_read_i2c_block_data(i2c_client, RESULT_INTERRUPT_STATUS, 2, (char*)&distance) < 0) {
            perror("i2c_read_i2c_block_data");
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
            continue;
        }

        // Print distance
        tm = localtime(&time(NULL));
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm);
        printf("%s Distance: %d mm\n", buffer, distance);

        // Sleep for 500ms
        nanosleep(&timeout, NULL);
    }

    // Cleanup
    i2c_close(i2c_client);
    return 0;
}

