#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x60
#define PROXIMITY_REG 0x00

static volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int read_proximity(int i2c_fd) {
    int proximity_data = 0;
    char buffer[2];

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(i2c_fd, &PROXIMITY_REG, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    proximity_data = (buffer[0] << 8) | buffer[1];

    return proximity_data;
}

int main() {
    int i2c_fd;
    int proximity_data;

    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    while (!stop_flag) {
        proximity_data = read_proximity(i2c_fd);
        if (proximity_data < 0) {
            printf("Error reading proximity data\n");
            continue;
        }

        printf("Proximity data: %d\n", proximity_data);

        usleep(500000); // Sleep for 500 ms
    }

    close(i2c_fd);
    return 0;
}

