#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x5A // MLX75030 I2C address
#define I2C_DEVICE "/dev/i2c-1"
#define I2C_READ_CMD 0x00
#define I2C_WRITE_CMD 0x01
#define I2C_SLAVE 0x0703

void handle_signal(int signum) {
    if (close(i2c_fd) == -1) {
        perror("Failed to close I2C file descriptor");
    }
    exit(0);
}

int main() {
    int i2c_fd = -1;
    char buffer[2];
    int distance;
    struct sigaction sa;

    // Open I2C device file
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device file");
        exit(1);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }

    // Check if the sensor is present
    if (read(i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "Sensor not present at startup\n");
        close(i2c_fd);
        exit(1);
    }

    // Install signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install signal handler");
        close(i2c_fd);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read distance measurement
        if (read(i2c_fd, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read distance measurement\n");
            continue;
        }

        // Convert buffer to distance
        distance = (buffer[0] << 8) | buffer[1];

        // Print distance
        printf("Distance: %d mm\n", distance);

        // Sleep for 500 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 500000000;
        nanosleep(&ts, NULL);
    }

    // Close I2C file descriptor
    close(i2c_fd);

    return 0;
}

