#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OPT3101_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define PERIOD 500 // 500 ms

// Function prototypes
void handle_sigint(int signum);
int read_sensor_data(int fd);

int main() {
    int fd;
    int ret;

    // Register signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C device address
    if (ioctl(fd, I2C_SLAVE, OPT3101_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(fd);
        return 1;
    }

    while (1) {
        ret = read_sensor_data(fd);
        if (ret < 0) {
            perror("Failed to read sensor data");
        }
        sleep(PERIOD / 1000); // Sleep for 500 ms
    }

    // Close I2C bus
    close(fd);
    return 0;
}

void handle_sigint(int signum) {
    printf("\nReceived SIGINT (Ctrl-C), shutting down...\n");
    // Perform any necessary cleanup here if needed
    exit(0);
}

int read_sensor_data(int fd) {
    uint8_t data[3];
    int ret;

    // Read 3 bytes from the sensor (distance, ambient light, error flags)
    ret = read(fd, data, 3);
    if (ret != 3) {
        if (ret < 0) {
            perror("Failed to read sensor data");
        } else {
            fprintf(stderr, "Unexpected read length: %d\n", ret);
        }
        return -1;
    }

    // Assuming the data format is: [distance, ambient light, error flags]
    uint16_t distance = (data[0] << 8) | data[1];
    uint8_t ambient_light = data[2];
    uint8_t error_flags = data[2] & 0x03; // Extract the lower 2 bits for error flags

    printf("Distance: %d mm, Ambient Light: %d, Error Flags: %d\n", distance, ambient_light, error_flags);

    return 0;
}

