        start = gpiod_line_get_ts(echo_line);
        if (gpiod_line_wait_for_edge(echo_line, GPIOD_LINE_EDGE_RISING, ECHO_TIMEOUT) < 0) {
            fprintf(stderr, "Echo rising edge timeout\n");
            return -1;
        }
    }

    // Wait for the echo falling edge
    end = gpiod_line_get_ts(echo_line);
    if (gpiod_line_wait_for_edge(echo_line, GPIOD_LINE_EDGE_FALLING, ECHO_TIMEOUT) < 0) {
        fprintf(stderr, "Echo falling edge timeout\n");
        return -1;
    }

    // Calculate the duration
    duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    // Check for invalid pulse durations
    if (duration <= 0 || duration > MAX_RANGE) {
        fprintf(stderr, "Invalid pulse duration\n");
        return -1;
    }

    // Convert duration to distance (assuming speed of sound is 343 m/s)
    return (duration / 2) / 29; // (duration / 2) / (343 * 1000 / 1000000)
}

int main() {
    struct sigaction sa;
    int distance;

    // Initialize signal handling
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request trigger line
    trigger_line = gpiod_line_request_by_name(chip, "gpio%d", TRIGGER_PIN, "trigger", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!trigger_line) {
        fprintf(stderr, "Failed to request trigger line\n");
        goto cleanup;
    }

    // Request echo line
    echo_line = gpiod_line_request_by_name(chip, "gpio%d", ECHO_PIN, "echo", GPIOD_LINE_DIRECTION_INPUT);
    if (!echo_line) {
        fprintf(stderr, "Failed to request echo line\n");
        goto cleanup;
    }

    // Main loop
    while (1) {
        distance = read_distance();
        if (distance >= 0) {
            time_t now = time(NULL);
            printf("Distance: %d cm at %s\n", distance, ctime(&now));
        }
        sleep(1);
    }

cleanup:
    cleanup(0);
    return 0;
}
