#define UART_DEVICE "/dev/serial0"
#define MAGIC_WORD "\x01\x02\x03\x04\x05\x06\x07\x08"
#define DISTANCE_THRESHOLD 1.0
#define LED_PIN 17
#define ALERT_DURATION 2

static int fd;
static struct gpiod_line *led_line;

void handle_signal(int signum) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_free(led_line);
    }
    close(fd);
    exit(signum);
}

void write_intrusion_log(const char *timestamp, double distance) {
    FILE *log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
