int main() {
    struct termios options;
    struct sigaction sa;
    struct gpiod_chip *chip;
    struct gpiod_line_request_config line_request;
    struct timespec ts;

    // Initialize LED
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line_request.consumer = "intrusion_detection";
    line_request.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    line_request.flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    line_request.value = 0;

    led_line = gpiod_line_request_open(chip, LED_PIN, &line_request);
    if (!led_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize UART
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open UART device");
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    tcgetattr(fd, &options);
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    tcsetattr(fd, TCSANOW, &options);

    // Signal handling
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        char buffer[136];
        int bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            perror("Failed to read from UART");
            handle_signal(0);
        }

        if (bytes_read >= 136 && memcmp(buffer, MAGIC_WORD, 8) == 0) {
            double distance = 0.0;
            for (int i = 0; i < 64; i++) {
                uint16_t bin = (buffer[8 + i * 2] << 8) | buffer[9 + i * 2];
                distance = (double)bin / 1000.0; // Assuming bin value is in millimeters
                if (distance <= DISTANCE_THRESHOLD) {
                    time_t now = time(NULL);
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
                    write_intrusion_log(timestamp, distance);
                    gpiod_line_set_value(led_line, 1);
                    nanosleep(&ts, NULL);
                    gpiod_line_set_value(led_line, 0);
                    break;
                }
            }
        }
    }

    handle_signal(0);
    return 0;
}

