#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_SENSOR 17
#define GPIO_BUZZER 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL 100 // in milliseconds

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line, *buzzer_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (sensor_line) {
        gpiod_line_request_release(sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_request_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    int ret;
    struct gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    struct gpiod_line_request sensor_req = {
        .consumer = "obstacle_detection",
        .consumer_type = GPIOD_LINE_REQUEST_TYPE_DRIVER,
        .flags = flags,
        .line = GPIO_SENSOR,
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };
    struct gpiod_line_request buzzer_req = {
        .consumer = "obstacle_detection",
        .consumer_type = GPIOD_LINE_REQUEST_TYPE_DRIVER,
        .flags = GPIOD_LINE_REQUEST_ACTIVE_HIGH,
        .line = GPIO_BUZZER,
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    chip = gpiod_chip_open(NULL);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return 1;
    }

    sensor_line = gpiod_line_request_alloc(chip, &sensor_req);
    if (!sensor_line) {
        perror("Failed to request sensor line");
        gpiod_chip_put(chip);
        fclose(log_file);
        return 1;
    }

    buzzer_line = gpiod_line_request_alloc(chip, &buzzer_req);
    if (!buzzer_line) {
        perror("Failed to request buzzer line");
        gpiod_line_request_release(sensor_line);
        gpiod_chip_put(chip);
        fclose(log_file);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int prev_state = -1;
    while (1) {
        int current_state;
        ret = gpiod_line_get_value(sensor_line, &current_state);
        if (ret < 0) {
            perror("Failed to read sensor state");
            handle_signal(SIGTERM);
        }

        if (current_state != prev_state) {
            char timestamp[20];
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);

            fprintf(log_file, "%s: State changed to %d\n", timestamp, current_state);
            prev_state = current_state;

            if (current_state == 0) {
                gpiod_line_set_value(buzzer_line, 1);
            } else {
                gpiod_line_set_value(buzzer_line, 0);
            }
        }

        usleep(POLL_INTERVAL * 1000); // Convert milliseconds to microseconds
    }

    return 0;
}

