This C program continuously reads the state of an E18-D80NK IR sensor connected to GPIO 17 on a Raspberry Pi 4 Model B. It activates a buzzer connected to GPIO 18 whenever an obstacle is detected (sensor state is 0) and deactivates it when the obstacle is removed (sensor state is 1). The program logs each state transition with an ISO 8601 timestamp to a file named `obstacle_log.txt`. It handles errors such as chip open failure, line request failure, or read/write errors, and installs handlers for SIGINT and SIGTERM to perform a graceful shutdown that releases all GPIO lines and closes the chip.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x20
#define GPIO_ALERT_PIN 17
#define LOG_FILE "distance_log.txt"
#define MEASURE_INTERVAL 100 // in milliseconds
#define MIN_DISTANCE 10.0 // in centimeters

static gpiod_chip *chip;
static gpiod_line *alert_line;

void handle_signal(int signum) {
    if (alert_line) {
        gpiod_line_request_free(alert_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
    }
    exit(signum);
}

int read_distance() {
    int distance = 0;
    int status;

    status = i2c_smbus_read_byte_data(I2C_BUS, I2C_ADDR, 0x00);
    if (status < 0) {
        fprintf(stderr, "Failed to read distance from sensor\n");
        return -1;
    }

    distance = status;
    return distance;
}

int main() {
    FILE *log_file;
    struct timespec ts;
    int distance;
    int status;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((chip = gpiod_chip_open("/dev/gpiomem")) == NULL) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        return 1;
    }

    if ((alert_line = gpiod_line_request_by_name(chip, "gpio%d", GPIO_ALERT_PIN, "alert", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_put(chip);
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_request_free(alert_line);
        gpiod_chip_put(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        distance = read_distance();
        if (distance < 0) {
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld-%02ld-%02ldT%02ld:%02ld:%02ld.%09ldZ %f\n",
                ts.tv_sec / 60 / 60 / 24 + 1970,
                (ts.tv_sec / 60 / 60) % 24 + 1,
                (ts.tv_sec / 60) % 60,
                ts.tv_sec % 60,
                ts.tv_nsec / 1000000000,
                (ts.tv_nsec / 1000000) % 1000000,
                distance);

        if (distance < MIN_DISTANCE) {
            gpiod_line_set_value(alert_line, 1);
        } else {
            gpiod_line_set_value(alert_line, 0);
        }

        usleep(MEASURE_INTERVAL * 1000);
    }

    fclose(log_file);
    gpiod_line_request_free(alert_line);
    gpiod_chip_put(chip);
    gpioTerminate();

    return 0;
}

