#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define LOG_FILE "distance_log.csv"
#define MAX_DISTANCE 1200
#define MIN_DISTANCE 300

static gpiod_chip *chip;
static gpiod_line *i2c_sda, *i2c_scl;
static FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_sda) {
        gpiod_line_request_free(i2c_sda);
    }
    if (i2c_scl) {
        gpiod_line_request_free(i2c_scl);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum);
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    int distance;
    int ret;

    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/i2c-1");
    if (!chip) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Request I2C lines
    i2c_sda = gpiod_line_request_by_name(chip, "sda", "input");
    if (!i2c_sda) {
        perror("Failed to request SDA line");
        goto error_sda;
    }

    i2c_scl = gpiod_line_request_by_name(chip, "scl", "input");
    if (!i2c_scl) {
        perror("Failed to request SCL line");
        goto error_scl;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto error_file;
    }

    // Write header if file is empty
    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }

    // Main loop
    while (1) {
        // Poll sensor
        ret = i2c_smbus_read_byte_data(I2C_ADDR, 0x00);
        if (ret < 0) {
            perror("Failed to read from sensor");
            continue;
        }

        // Convert raw data to distance
        distance = (ret * 1000) / 256; // Assuming 1000 mm / 256 raw units

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        // Write to log file
        fprintf(log_file, "%s,%d\n", timestamp, distance);

        // Print parking guidance message
        if (distance < MIN_DISTANCE) {
            printf("STOP\n");
        } else if (distance < MAX_DISTANCE) {
            printf("APPROACH\n");
        } else if (distance < 2 * MAX_DISTANCE) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }

        // Sleep for 100 ms
        usleep(100000);
    }

error_file:
    if (i2c_scl) {
        gpiod_line_request_free(i2c_scl);
    }
error_scl:
    if (i2c_sda) {
        gpiod_line_request_free(i2c_sda);
    }
error_sda:
    if (chip) {
        gpiod_chip_put(chip);
    }

    return 0;
}

