#define I2C_BUS "/dev/i2c-1"
#define CH201_ADDR 0x60
#define CH201_REG_CONFIG 0x00
#define CH201_REG_STATUS 0x01
#define CH201_REG_DATA 0x02
#define CH201_REG_LED_FREQ 0x03

#define MAX_RETRIES 3
#define RETRY_DELAY 10

int i2c_fd;
int led_pin = 18;

void handle_signal(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("I2C handle closed.\n");
    printf("Turning off LED.\n");
    // Assuming a GPIO library is used to control the LED
    // Example: gpio_set_value(led_pin, 0);
    exit(0);
}

int i2c_read(int reg, uint8_t *data, int len) {
    int retries = 0;
    int result;
    do {
        result = read(i2c_fd, data, len);
        if (result < 0) {
            printf("I2C read error, retrying...\n");
            sleep(RETRY_DELAY / 1000);
        }
    } while (result < 0 && retries++ < MAX_RETRIES);
    return result;
}

int i2c_write(int reg, const uint8_t *data, int len) {
    int retries = 0;
    int result;
    do {
        result = write(i2c_fd, data, len);
        if (result < 0) {
            printf("I2C write error, retrying...\n");
            sleep(RETRY_DELAY / 1000);
        }
    } while (result < 0 && retries++ < MAX_RETRIES);
    return result;
}

