#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define MLX75030_CMD_START_MEASUREMENT 0x00
#define MLX75030_CMD_READ_DATA 0x01
#define MLX75030_CMD_READ_DATA_END 0x02
#define MLX75030_CMD_READ_DATA_LENGTH 2
#define MLX75030_CMD_WRITE_DATA 0x03
#define MLX75030_CMD_WRITE_DATA_END 0x04
#define MLX75030_CMD_WRITE_DATA_LENGTH 2
#define MLX75030_CMD_WRITE_DATA_TIMEOUT 1000
#define MLX75030_CMD_READ_DATA_TIMEOUT 1000
#define MLX75030_CMD_RETRY_COUNT 3
#define MLX75030_CMD_RETRY_INTERVAL 100

static int i2c_fd;
static struct i2c_client *i2c_client;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (i2c_client) {
        i2c_client_close(i2c_client);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int read_distance(void) {
    int retry_count = MLX75030_CMD_RETRY_COUNT;
    int result = -1;
    while (retry_count > 0) {
        int bytes_read = i2c_smbus_read_i2c_block_data(i2c_fd, MLX75030_CMD_READ_DATA, MLX75030_CMD_READ_DATA_LENGTH, (char *)&result, MLX75030_CMD_READ_DATA_LENGTH);
        if (bytes_read == MLX75030_CMD_READ_DATA_LENGTH) {
            return result;
        }
        retry_count--;
        usleep(MLX75030_CMD_RETRY_INTERVAL * 1000);
    }
    return -1;
}

int write_command(uint8_t command) {
    int retry_count = MLX75030_CMD_RETRY_COUNT;
    while (retry_count > 0) {
        int bytes_written = i2c_smbus_write_byte_data(i2c_fd, command);
        if (bytes_written == 1) {
            return 0;
        }
        retry_count--;
        usleep(MLX75030_CMD_RETRY_INTERVAL * 1000);
    }
    return -1;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = i2c_open(I2C_BUS, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    i2c_client = i2c_client_new_by_name(i2c_fd, "mlx75030");
    if (!i2c_client) {
        perror("Failed to create I2C client");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen("distance_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        i2c_client_close(i2c_client);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (write_command(MLX75030_CMD_START_MEASUREMENT) < 0) {
            fprintf(stderr, "Failed to start measurement\n");
            continue;
        }

        usleep(100000); // 100 ms delay

        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s,%d\n", timestamp, distance);
        fflush(log_file);

        sleep(1); // 1 second interval
    }

    fclose(log_file);
    i2c_client_close(i2c_client);
    close(i2c_fd);

    return 0;
}

