#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 27
#define DEBOUNCE_TIME 50000 // 50ms in microseconds
#define LOG_FILE "proximity_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1, *sensor2;
static FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (sensor1) {
        gpiod_line_request_free(sensor1);
    }
    if (sensor2) {
        gpiod_line_request_free(sensor2);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum == SIGINT ? 0 : 1);
}

void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Sensor %d, %s\n", buffer, sensor_id, event_type);
    fflush(log_file);
}

int main() {
    int ret;
    unsigned long old_state1 = 0, old_state2 = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    sensor1 = gpiod_line_request_by_name(chip, "gpio17", "sensor1", 0);
    if (!sensor1) {
        perror("Failed to request GPIO line for sensor1");
        goto error_sensor1;
    }

    sensor2 = gpiod_line_request_by_name(chip, "gpio27", "sensor2", 0);
    if (!sensor2) {
        perror("Failed to request GPIO line for sensor2");
        goto error_sensor2;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto error_log_file;
    }

    while (1) {
        unsigned long state1, state2;

        ret = gpiod_line_get_value(sensor1, &state1);
        if (ret < 0) {
            perror("Failed to read sensor1 state");
            goto error_read_sensor1;
        }

        ret = gpiod_line_get_value(sensor2, &state2);
        if (ret < 0) {
            perror("Failed to read sensor2 state");
            goto error_read_sensor2;
        }

        if (state1 != old_state1) {
            if (state1 == 0) {
                log_event(1, "DETECTED");
            } else {
                log_event(1, "CLEARED");
            }
            old_state1 = state1;
            usleep(DEBOUNCE_TIME);
        }

        if (state2 != old_state2) {
            if (state2 == 0) {
                log_event(2, "DETECTED");
            } else {
                log_event(2, "CLEARED");
            }
            old_state2 = state2;
            usleep(DEBOUNCE_TIME);
        }

        usleep(10000); // 10ms sleep
    }

error_read_sensor2:
error_read_sensor1:
    if (log_file) {
        fclose(log_file);
    }
error_log_file:
    if (sensor2) {
        gpiod_line_request_free(sensor2);
    }
error_sensor2:
    if (sensor1) {
        gpiod_line_request_free(sensor1);
    }
error_sensor1:
    if (chip) {
        gpiod_chip_put(chip);
    }

    return 1;
}

