#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define TDK_CH_101_ADDR 0x60
#define MEAS_STATUS 0x00
#define MEAS_DATA 0x01

void handle_signal(int signum) {
    close(i2c_fd);
    fclose(csv_file);
    exit(signum);
}

int i2c_write_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, len);

    if (write(fd, buffer, len + 1) != len + 1) {
        perror("i2c_write_read: write failed");
        return -1;
    }

    if (read(fd, buffer, len + 1) != len + 1) {
        perror("i2c_write_read: read failed");
        return -1;
    }

    memcpy(data, buffer + 1, len);
    return 0;
}

int main() {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("main: open failed");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TDK_CH_101_ADDR) < 0) {
        perror("main: ioctl failed");
        close(i2c_fd);
        return 1;
    }

    FILE *csv_file = fopen("distance_log.csv", "w");
    if (csv_file == NULL) {
        perror("main: fopen failed");
        close(i2c_fd);
        return 1;
    }

    fprintf(csv_file, "timestamp,distance_mm\n");

    struct timespec timeout = { .tv_sec = 0, .tv_nsec = 50000000 };
    struct timespec start, end;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        uint8_t meas_status = 0;
        uint8_t meas_data[2];

        clock_gettime(CLOCK_REALTIME, &start);

        while (meas_status != 0x01) {
            if (i2c_write_read(i2c_fd, MEAS_STATUS, &meas_status, 1) < 0) {
                perror("main: i2c_write_read failed");
                continue;
            }

            clock_gettime(CLOCK_REALTIME, &end);
            if (end.tv_sec - start.tv_sec > 0 || (end.tv_sec == start.tv_sec && end.tv_nsec - start.tv_nsec >= 50000000)) {
                fprintf(stderr, "Timeout occurred, errno: %d\n", errno);
                continue;
            }
        }

        if (i2c_write_read(i2c_fd, MEAS_DATA, meas_data, 2) < 0) {
            perror("main: i2c_write_read failed");
            continue;
        }

        uint16_t distance_mm = (meas_data[0] << 8) | meas_data[1];

        char timestamp[20];
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);

        fprintf(csv_file, "%s,%d\n", timestamp, distance_mm);
        fflush(csv_file);

        sleep(0.5);
    }

    fclose(csv_file);
    close(i2c_fd);

    return 0;
}

