#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define I2C_ADDR 0x29
#define I2C_BUS "/dev/i2c-1"
#define ZONE_COUNT 64
#define ZONE_DATA_REG 0x80
#define ZONE_CONFIG_REG 0x00
#define ZONE_CONFIG_8X8 0x01
#define ZONE_CONFIG_ENABLE 0x02
#define ZONE_CONFIG_RESET 0x04
#define ZONE_CONFIG_MEASURE 0x08

void handle_sigint(int signum) {
    printf("\nReceived SIGINT, cleaning up...\n");
    close(i2c_fd);
    exit(0);
}

int i2c_write(int fd, uint8_t reg, uint8_t data) {
    uint8_t buffer[2] = {reg, data};
    ssize_t bytes_written = write(fd, buffer, 2);
    if (bytes_written != 2) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    uint8_t buffer[length + 1];
    buffer[0] = reg;
    ssize_t bytes_read = read(fd, buffer, length + 1);
    if (bytes_read != length + 1) {
        perror("i2c_read");
        return -1;
    }
    memcpy(data, buffer + 1, length);
    return 0;
}

int main() {
    int i2c_fd;
    uint8_t zone_config = ZONE_CONFIG_8X8 | ZONE_CONFIG_ENABLE | ZONE_CONFIG_RESET | ZONE_CONFIG_MEASURE;
    uint8_t zone_data[ZONE_COUNT];

    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write(i2c_fd, ZONE_CONFIG_REG, zone_config) < 0) {
        perror("Failed to write zone configuration");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (i2c_read(i2c_fd, ZONE_DATA_REG, zone_data, ZONE_COUNT) < 0) {
            perror("Failed to read zone data");
            close(i2c_fd);
            return 1;
        }

        for (int i = 0; i < ZONE_COUNT; i++) {
            printf("Zone %d: %d\n", i, zone_data[i]);
        }

        usleep(500000); // Sleep for 500 ms
    }

    close(i2c_fd);
    return 0;
}

