#define MLX75030_I2C_ADDR 0x5A
#define MLX75030_REG_DIST 0x00
#define MLX75030_REG_CONFIG 0x01
#define MLX75030_CONFIG_MODE 0x01
#define MLX75030_CONFIG_RESET 0x02
#define MLX75030_CONFIG_ENABLE 0x04
#define MLX75030_CONFIG_AUTO_RESET 0x08
#define MLX75030_CONFIG_AUTO_ENABLE 0x10
#define MLX75030_CONFIG_AUTO_RESET_ENABLE 0x20
#define MLX75030_CONFIG_AUTO_ENABLE_RESET 0x40
#define MLX75030_CONFIG_AUTO_RESET_ENABLE_ENABLE 0x80

#define MLX75030_CONFIG_DEFAULT (MLX75030_CONFIG_MODE | MLX75030_CONFIG_AUTO_RESET | MLX75030_CONFIG_AUTO_ENABLE | MLX75030_CONFIG_AUTO_RESET_ENABLE | MLX75030_CONFIG_AUTO_ENABLE_RESET | MLX75030_CONFIG_AUTO_RESET_ENABLE_ENABLE)

#define MLX75030_MAX_RETRY 3
#define MLX75030_RETRY_DELAY 10

static i2c_t *i2c_handle = NULL;

void cleanup(void) {
    if (i2c_handle) {
        i2c_close(i2c_handle);
        i2c_handle = NULL;
    }
}

void handle_sigint(int signum) {
    (void)signum;
    cleanup();
    exit(0);
}

int read_distance(void) {
    int retry = 0;
    int distance = 0;
    int result;

    while (retry < MLX75030_MAX_RETRY) {
        result = i2c_read_byte_data(i2c_handle, MLX75030_I2C_ADDR, MLX75030_REG_DIST, &distance);
        if (result == 0) {
            return distance;
        }
        retry++;
        usleep(MLX75030_RETRY_DELAY * 1000);
    }

    fprintf(stderr, "Failed to read distance from MLX75030 sensor after %d retries.\n", MLX75030_MAX_RETRY);
    return -1;
}

int write_config(int config) {
    int retry = 0;
    int result;

    while (retry < MLX75030_MAX_RETRY) {
        result = i2c_write_byte_data(i2c_handle, MLX75030_I2C_ADDR, MLX75030_REG_CONFIG, config);
        if (result == 0) {
            return 0;
        }
        retry++;
        usleep(MLX75030_RETRY_DELAY * 1000);
    }

    fprintf(stderr, "Failed to write configuration to MLX75030 sensor after %d retries.\n", MLX75030_MAX_RETRY);
    return -1;
}

int main(void) {
    struct sigaction sa;
    int config;
    int distance;
    struct timespec ts;

    if (i2c_open("/dev/i2c-1", &i2c_handle) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        cleanup();
        return 1;
    }

    config = MLX75030_CONFIG_DEFAULT;
    if (write_config(config) < 0) {
        fprintf(stderr, "Failed to configure MLX75030 sensor.\n");
        cleanup();
        return 1;
    }

    while (1) {
        ts.tv_sec = 0;
        ts.tv_nsec = 100 * 1000 * 1000; // 100 ms
        nanosleep(&ts, NULL);

        distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm, Timestamp: %ld\n", distance, time(NULL));
        }
    }

    cleanup();
    return 0;
}
