#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define VL53L4CX_I2C_ADDR 0x29
#define VL53L4CX_INTERRUPT_STATUS_REG 0x00
#define VL53L4CX_RANGE_READING_REG 0x00
#define VL53L4CX_RANGE_READING_HIGH_REG 0x01
#define VL53L4CX_RANGE_READING_LOW_REG 0x02

static gpiod_chip *i2c_chip;
static gpiod_line *i2c_line;

void cleanup(void) {
    if (i2c_line) {
        gpiod_line_free(i2c_line);
        i2c_line = NULL;
    }
    if (i2c_chip) {
        gpiod_chip_free(i2c_chip);
        i2c_chip = NULL;
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[32];
    int distance;
    int status;

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C chip
    i2c_chip = gpiod_chip_open("/dev/i2c-1");
    if (!i2c_chip) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return 1;
    }

    // Initialize I2C line
    i2c_line = gpiod_line_request(i2c_chip, "i2c-1", "i2c-1", 0, 0, 0, 0);
    if (!i2c_line) {
        fprintf(stderr, "Failed to request I2C line\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        // Poll interrupt status register
        status = gpiod_line_get_value(i2c_line);
        if (status < 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            continue;
        }

        // If interrupt status bit is not set, skip this cycle
        if (status == 0) {
            continue;
        }

        // Read distance data
        uint8_t high_byte, low_byte;
        status = gpiod_i2c_read(i2c_chip, VL53L4CX_I2C_ADDR, VL53L4CX_RANGE_READING_HIGH_REG, &high_byte, 1);
        if (status < 0) {
            fprintf(stderr, "Failed to read high byte of distance\n");
            continue;
        }

        status = gpiod_i2c_read(i2c_chip, VL53L4CX_I2C_ADDR, VL53L4CX_RANGE_READING_LOW_REG, &low_byte, 1);
        if (status < 0) {
            fprintf(stderr, "Failed to read low byte of distance\n");
            continue;
        }

        // Combine high and low bytes to get distance
        distance = (high_byte << 8) | low_byte;

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.", tm);
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06lu", ts.tv_nsec / 1000);

        // Print distance with timestamp
        printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);

        // Sleep for 500ms
        usleep(500000);
    }

    cleanup();
    return 0;
}

