#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/queue.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define BUZZER_PIN 23
#define QUEUE_PATH "/tmp/distance_queue"
#define QUEUE_MODE 0644
#define QUEUE_FLAGS O_CREAT | O_WRONLY | O_NONBLOCK
#define QUEUE_TIMEOUT 50

static volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

void cleanup(void) {
    if (vl53l1x_handle != NULL) {
        vl53l1x_stop_measurements(vl53l1x_handle);
        vl53l1x_close(vl53l1x_handle);
        vl53l1x_handle = NULL;
    }

    if (queue_fd >= 0) {
        close(queue_fd);
        queue_fd = -1;
    }

    if (gpiod_handle != NULL) {
        gpiod_release_line(gpiod_handle, BUZZER_PIN);
        gpiod_close(gpiod_handle);
        gpiod_handle = NULL;
    }

    if (pigpio_connected) {
        gpioTerminate();
    }
}

int main(void) {
    int queue_fd = -1;
    struct gpiod_line *gpiod_handle = NULL;
    struct vl53l1x_dev *vl53l1x_handle = NULL;
    int distance;

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    if (vl53l1x_init(I2C_BUS, I2C_ADDR, &vl53l1x_handle) < 0) {
        perror("vl53l1x_init");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (vl53l1x_start_ranging(vl53l1x_handle) < 0) {
        perror("vl53l1x_start_ranging");
        cleanup();
        exit(EXIT_FAILURE);
    }

    queue_fd = mq_open(QUEUE_PATH, O_CREAT | O_WRONLY | O_NONBLOCK, QUEUE_MODE, NULL);
    if (queue_fd < 0) {
        perror("mq_open");
        cleanup();
        exit(EXIT_FAILURE);
    }

    gpiod_handle = gpiod_line_request(BUZZER_PIN, "buzzer", GPIOD_LINE_DIRECTION_OUTPUT);
    if (gpiod_handle == NULL) {
        perror("gpiod_line_request");
        cleanup();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        if (vl53l1x_get_distance(vl53l1x_handle, &distance) < 0) {
            perror("vl53l1x_get_distance");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (distance < 100) {
            gpiod_line_set_value(gpiod_handle, 1);
        } else {
            gpiod_line_set_value(gpiod_handle, 0);
        }

        char message[16];
        sprintf(message, "%d\n", distance);
        if (mq_send(queue_fd, message, strlen(message), 0) < 0) {
            perror("mq_send");
            cleanup();
            exit(EXIT_FAILURE);
        }

        usleep(50000); // 50 ms timing budget
    }

    cleanup();
    return 0;
}

