#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define TIMEOUT_US 50000
#define INTERVAL_MS 100
#define SPEED_OF_SOUND 34300 // cm/s

volatile int distance = 0;
volatile int echo_tick = 0;
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_active = 0;

void handle_interrupt(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
    } else {
        echo_end_tick = tick;
        echo_active = 0;
    }
}

void handle_sigint(int signum) {
    gpioWrite(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode.\n");
        goto cleanup;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode.\n");
        goto cleanup;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN mode.\n");
        goto cleanup;
    }

    if (gpioSetAlertFunc(ECHO_PIN, handle_interrupt) < 0) {
        fprintf(stderr, "Failed to set interrupt function for ECHO_PIN.\n");
        goto cleanup;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        gpioWrite(TRIGGER_PIN, PI_LOW);
        usleep(2);
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        usleep(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        if (!echo_active) {
            echo_active = 1;
            echo_start_tick = echo_end_tick = 0;
        }

        while (echo_active && (echo_end_tick == 0)) {
            usleep(1000);
        }

        if (echo_end_tick == 0) {
            fprintf(stderr, "Sensor absent (timeout or no echo).\n");
            continue;
        }

        uint32_t echo_duration = echo_end_tick - echo_start_tick;
        distance = (echo_duration * SPEED_OF_SOUND) / 2 / 10000;

        if (distance < 2 || distance > 400) {
            fprintf(stderr, "Invalid reading (out-of-range).\n");
            continue;
        }

        printf("Distance: %d cm\n", distance);

        if (distance < 30) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }

        usleep(INTERVAL_MS * 1000);
    }

cleanup:
    gpioTerminate();
    return 0;
}

