#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDR 0x29
#define GATE_LOG_FILE "gate_log.txt"
#define OPEN_DISTANCE 20 // cm

static gpiod_chip *chip;
static gpiod_line *servo_line;
static int i2c_fd;

void handle_signal(int signum) {
    if (servo_line) {
        gpiod_line_free(servo_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

void init_gpiod() {
    int err;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    servo_line = gpiod_line_request_by_name(chip, "18", "servo", 0);
    if (!servo_line) {
        perror("Failed to request GPIO line");
        exit(1);
    }

    err = gpiod_line_direction_set(servo_line, GPIOD_LINE_DIRECTION_OUTPUT);
    if (err) {
        perror("Failed to set GPIO direction");
        exit(1);
    }
