#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SAMPLING_INTERVAL 200000 // 200 ms
#define MIN_PULSE_WIDTH 100 // 100 µs
#define MAX_PULSE_WIDTH 30000 // 30,000 µs
#define TIMEOUT_THRESHOLD 60000 // 60 ms

static struct gpiod_chip *chip;
static struct gpiod_line *trig_line, *echo_line;
static struct gpiod_line_consumer *trig_consumer, *echo_consumer;
static FILE *log_file;

void handle_interrupt(struct gpiod_line *line, struct gpiod_line_event *event) {
    static uint32_t rising_tick = 0;
    static uint32_t falling_tick = 0;

    if (event->event == GPIO_LINE_EVENT_RISING_EDGE) {
        rising_tick = event->timestamp;
    } else if (event->event == GPIO_LINE_EVENT_FALLING_EDGE) {
        falling_tick = event->timestamp;

        if (falling_tick < rising_tick) {
            falling_tick += 0xFFFFFFFF; // Handle 32-bit tick wraparound
        }

        uint32_t pulse_width = falling_tick - rising_tick;

        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Warning: Invalid pulse width %u µs. Ignoring.\n", pulse_width);
            return;
        }

        double distance = (pulse_width * 343.0 / 2.0) / 1000000.0; // Speed of sound 343 m/s

        char timestamp[20];
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(log_file, "%s: Distance = %.2f cm\n", timestamp, distance);
        fflush(log_file);
    }
}

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }

    if (trig_consumer) {
        gpiod_line_consumer_put(trig_consumer);
    }

    if (echo_consumer) {
        gpiod_line_consumer_put(echo_consumer);
    }

    if (echo_line) {
        gpiod_line_put(echo_line);
    }

    if (trig_line) {
        gpiod_line_put(trig_line);
    }

    if (chip) {
        gpiod_chip_put(chip);
    }

    exit(0);
}

int main() {
    int err;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return 1;
    }

    // Configure TRIG line
    trig_line = gpiod_line_request(chip, TRIG_PIN, "trig", GPIO_LINE_DIRECTION_OUT);
    if (!trig_line) {
        fprintf(stderr, "Failed to request TRIG line.\n");
        gpiod_chip_put(chip);
        return 1;
    }

    // Configure ECHO line
    echo_line = gpiod_line_request(chip, ECHO_PIN, "echo", GPIO_LINE_DIRECTION_IN);
    if (!echo_line) {
        fprintf(stderr, "Failed to request ECHO line.\n");
        gpiod_line_put(trig_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set ECHO line to pull-down
    err = gpiod_line_set_debounce(echo_line, 0);
    if (err) {
        fprintf(stderr, "Failed to set debounce on ECHO line.\n");
        gpiod_line_put(echo_line);
        gpiod_line_put(trig_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Create consumers for TRIG and ECHO lines
    trig_consumer = gpiod_line_consumer_request(trig_line, "trig_consumer");
    if (!trig_consumer) {
        fprintf(stderr, "Failed to request TRIG consumer.\n");
        gpiod_line_put(echo_line);
        gpiod_line_put(trig_line);
        gpiod_chip_put(chip);
        return 1;
    }

    echo_consumer = gpiod_line_consumer_request(echo_line, "echo_consumer");
    if (!echo_consumer) {
        fprintf(stderr, "Failed to request ECHO consumer.\n");
        gpiod_line_consumer_put(trig_consumer);
        gpiod_line_put(echo_line);
        gpiod_line_put(trig_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Register interrupt callback for ECHO line
    gpiod_line_event_register(echo_line, handle_interrupt, NULL);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpiod_line_consumer_put(echo_consumer);
        gpiod_line_consumer_put(trig_consumer);
        gpiod_line_put(echo_line);
        gpiod_line_put(trig_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Generate 10 µs trigger pulse
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for 200 ms
        usleep(SAMPLING_INTERVAL);
    }

    return 0;
}

