#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define VL53L1X_MODEL_ID 0x29
#define VL53L1X_SHUTDOWN_LINE 23
#define VL53L1X_INT_LINE 24
#define SERVO_PIN 18
#define GATE_OPEN_POS 1.5
#define GATE_CLOSE_POS 0.5
#define LOG_FILE "parking_log.txt"

static int i2c_fd;
static struct gpiod_line *shutdown_line;
static struct gpiod_line *int_line;
static int servo_pin;
static int log_fd;

void handle_signal(int signum) {
    gpiod_line_free(shutdown_line);
    gpiod_line_free(int_line);
    close(i2c_fd);
    close(log_fd);
    exit(signum);
}

int i2c_read(uint8_t reg, uint8_t *data, size_t len) {
    int ret;
    if ((ret = write(i2c_fd, &reg, 1)) != 1) {
        perror("i2c_write");
        return -1;
    }
    if ((ret = read(i2c_fd, data, len)) != len) {
        perror("i2c_read");
        return -1;
    }
    return 0;
}

int i2c_write(uint8_t reg, const uint8_t *data, size_t len) {
    int ret;
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, len);
    if ((ret = write(i2c_fd, buffer, len + 1)) != len + 1) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return -1;
    }
    uint8_t model_id;
    if (i2c_read(0x00, &model_id, 1) < 0 || model_id != VL53L1X_MODEL_ID) {
        perror("read VL53L1X model ID");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int init_gpiod() {
    shutdown_line = gpiod_line_request(VL53L1X_SHUTDOWN_LINE, "shutdown", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!shutdown_line) {
        perror("gpiod_line_request shutdown");
        return -1;
    }
    int_line = gpiod_line_request(VL53L1X_INT_LINE, "interrupt", GPIOD_LINE_DIRECTION_INPUT);
    if (!int_line) {
        perror("gpiod_line_request interrupt");
        gpiod_line_free(shutdown_line);
        return -1;
    }
    return 0;
}

int init_servo() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }
    servo_pin = SERVO_PIN;
    if (gpioSetPWMfrequency(servo_pin, 50) < 0) {
        perror("gpioSetPWMfrequency");
        return -1;
    }
    if (gpioSetPWMrange(servo_pin, 100) < 0) {
        perror("gpioSetPWMrange");
        return -1;
    }
    return 0;
}

int init_logging() {
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open log file");
        return -1;
    }
    return 0;
}

void log_gate_state(int state, double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_fd, "%s - Gate state: %s, Distance: %.2f cm\n", buffer, state == 1 ? "Open" : "Closed", distance);
    fflush(log_fd);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_i2c() < 0 || init_gpiod() < 0 || init_servo() < 0 || init_logging() < 0) {
        handle_signal(1);
    }

    gpiod_line_set_value(shutdown_line, 0); // Enable sensor

    while (1) {
        uint16_t distance;
        if (i2c_read(0x00, (uint8_t*)&distance, 2) < 0) {
            perror("read distance");
            continue;
        }
        distance = (distance >> 3) & 0x3FFF; // Extract distance value

        int gate_state = distance <= 50 ? 1 : 0;
        if (gate_state != (servo_pin == GATE_OPEN_POS ? 1 : 0)) {
            if (gate_state == 1) {
                gpioServo(servo_pin, GATE_OPEN_POS);
            } else {
                gpioServo(servo_pin, GATE_CLOSE_POS);
            }
            log_gate_state(gate_state, distance);
        }

        usleep(100000); // Sleep for 100ms
    }

    handle_signal(0);
    return 0;
}

