        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return -1;
    }
    uint8_t model_id;
    if (i2c_read(0x00, &model_id, 1) < 0 || model_id != VL53L1X_MODEL_ID) {
        perror("read VL53L1X model ID");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int init_gpiod() {
    shutdown_line = gpiod_line_request(VL53L1X_SHUTDOWN_LINE, "shutdown", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!shutdown_line) {
        perror("gpiod_line_request shutdown");
        return -1;
    }
    int_line = gpiod_line_request(VL53L1X_INT_LINE, "interrupt", GPIOD_LINE_DIRECTION_INPUT);
    if (!int_line) {
        perror("gpiod_line_request interrupt");
        gpiod_line_free(shutdown_line);
        return -1;
    }
    return 0;
}

int init_servo() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }
    servo_pin = SERVO_PIN;
    if (gpioSetPWMfrequency(servo_pin, 50) < 0) {
        perror("gpioSetPWMfrequency");
        return -1;
    }
    if (gpioSetPWMrange(servo_pin, 100) < 0) {
        perror("gpioSetPWMrange");
        return -1;
    }
    return 0;
}

int init_logging() {
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open log file");
        return -1;
    }
    return 0;
}

void log_gate_state(int state, double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_fd, "%s - Gate state: %s, Distance: %.2f cm\n", buffer, state == 1 ? "Open" : "Closed", distance);
    fflush(log_fd);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_i2c() < 0 || init_gpiod() < 0 || init_servo() < 0 || init_logging() < 0) {
        handle_signal(1);
    }

    gpiod_line_set_value(shutdown_line, 0); // Enable sensor

    while (1) {
        uint16_t distance;
        if (i2c_read(0x00, (uint8_t*)&distance, 2) < 0) {
            perror("read distance");
            continue;
        }
        distance = (distance >> 3) & 0x3FFF; // Extract distance value

        int gate_state = distance <= 50 ? 1 : 0;
        if (gate_state != (servo_pin == GATE_OPEN_POS ? 1 : 0)) {
            if (gate_state == 1) {
                gpioServo(servo_pin, GATE_OPEN_POS);
            } else {
                gpioServo(servo_pin, GATE_CLOSE_POS);
            }
            log_gate_state(gate_state, distance);
        }

        usleep(100000); // Sleep for 100ms
    }

    handle_signal(0);
    return 0;
}
