This C program continuously polls a VL53L1X time-of-flight sensor on I2C bus 1 every 500 ms. It initializes the sensor with a soft reset, configures its timing budget, and starts ranging. It uses the 16-bit register access functions provided by the sensor's driver to read distance measurements and opens the gate (GPIO 18 HIGH, GPIO 19 LOW) when an object is detected within 20 cm (200 mm) and closes it (GPIO 18 LOW, GPIO 19 HIGH) otherwise, logging each open or close event with an ISO 8601 UTC timestamp to a file named `gate_events.log`. It checks all driver and I2C return codes and handles sensor-absent or bus-error conditions gracefully by logging the error. It also implements SIGINT/SIGTERM signal handling to ensure that on any exit path, the I2C handle is closed, the GPIO pins are reset, the log file is closed, and the appropriate library cleanup API is called.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_SOFT_RESET 0x06
#define VL53L1X_SYSRANGE_START 0x00
#define VL53L1X_SYSRANGE_STATUS 0x13
#define VL53L1X_SYSRANGE_DATA_READY 0x01
#define VL53L1X_SYSRANGE_DATA 0x80
#define VL53L1X_SYSRANGE_DATA_LEN 2

#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18
#define GPIO_TRIGGER 24

#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300

volatile int distance_measurement_required = 0;
volatile int motor_state = 0;

void handle_sigint(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }

    gpioWrite(GPIO_FORWARD, 0);
    gpioWrite(GPIO_BACKWARD, 0);

    if (i2c_close(fd) < 0) {
        fprintf(stderr, "Failed to close I2C bus.\n");
        exit(EXIT_FAILURE);
    }

    if (vl53l1x_api_stop_and_disable_meas(vl53l1x_dev)) {
        fprintf(stderr, "Failed to stop and disable measurement.\n");
        exit(EXIT_FAILURE);
    }

    if (vl53l1x_api_cleanup(vl53l1x_dev)) {
        fprintf(stderr, "Failed to clean up VL53L1X API.\n");
        exit(EXIT_FAILURE);
    }

    exit(EXIT_SUCCESS);
}

void handle_rising_edge(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        distance_measurement_required = 1;
    }
}

int main() {
    int fd;
    uint8_t data[VL53L1X_SYSRANGE_DATA_LEN];
    uint16_t distance;
    int i2c_retries = 0;
    int i2c_retry_delay = 100;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address.\n");
        exit(EXIT_FAILURE);
    }

    if (vl53l1x_api_init(vl53l1x_dev)) {
        fprintf(stderr, "Failed to initialize VL53L1X API.\n");
        exit(EXIT_FAILURE);
    }

    if (vl53l1x_api_soft_reset(vl53l1x_dev)) {
        fprintf(stderr, "Failed to perform soft reset.\n");
        exit(EXIT_FAILURE);
    }

    usleep(1000);

    if (vl53l1x_api_start_ranging(vl53l1x_dev)) {
        fprintf(stderr, "Failed to start measurement.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_FORWARD, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO_FORWARD mode.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_BACKWARD, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO_BACKWARD mode.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_TRIGGER, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO_TRIGGER mode.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetISRFunc(GPIO_TRIGGER, PI_RISING_EDGE, handle_rising_edge, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO_TRIGGER ISR.\n");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        if (distance_measurement_required) {
            distance_measurement_required = 0;

            while (1) {
                if (i2c_read_device(fd, data, VL53L1X_SYSRANGE_DATA_LEN) < 0) {
                    if (i2c_retries < 5) {
                        usleep(i2c_retry_delay * 1000);
                        i2c_retry_delay *= 2;
                        i2c_retries++;
                    } else {
                        fprintf(stderr, "Failed to read distance after multiple retries.\n");
                        exit(EXIT_FAILURE);
                    }
                } else {
                    break;
                }
            }

            distance = (data[0] << 8) | data[1];
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD_LOW) {
                if (motor_state != 1) {
                    motor_state = 1;
                    printf("Motor running forward.\n");
                    gpioWrite(GPIO_FORWARD, 1);
                    gpioWrite(GPIO_BACKWARD, 0);
                }
            } else if (distance > DISTANCE_THRESHOLD_HIGH) {
                if (motor_state != -1) {
                    motor_state = -1;
                    printf("Motor running backward.\n");
                    gpioWrite(GPIO_FORWARD, 0);
                    gpioWrite(GPIO_BACKWARD, 1);
                }
            } else {
                if (motor_state != 0) {
                    motor_state = 0;
                    printf("Motor stopped.\n");
                    gpioWrite(GPIO_FORWARD, 0);
                    gpioWrite(GPIO_BACKWARD, 0);
                }
            }
        }
    }

    return 0;
}

