        fprintf(stderr, "Failed to set GPIO_TRIGGER mode.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetISRFunc(GPIO_TRIGGER, PI_RISING_EDGE, handle_rising_edge, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO_TRIGGER ISR.\n");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        if (distance_measurement_required) {
            distance_measurement_required = 0;

            while (1) {
                if (i2c_read_device(fd, data, VL53L1X_SYSRANGE_DATA_LEN) < 0) {
                    if (i2c_retries < 5) {
                        usleep(i2c_retry_delay * 1000);
                        i2c_retry_delay *= 2;
                        i2c_retries++;
                    } else {
                        fprintf(stderr, "Failed to read distance after multiple retries.\n");
                        exit(EXIT_FAILURE);
                    }
                } else {
                    break;
                }
            }

            distance = (data[0] << 8) | data[1];
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD_LOW) {
                if (motor_state != 1) {
                    motor_state = 1;
                    printf("Motor running forward.\n");
                    gpioWrite(GPIO_FORWARD, 1);
                    gpioWrite(GPIO_BACKWARD, 0);
                }
            } else if (distance > DISTANCE_THRESHOLD_HIGH) {
                if (motor_state != -1) {
                    motor_state = -1;
                    printf("Motor running backward.\n");
                    gpioWrite(GPIO_FORWARD, 0);
                    gpioWrite(GPIO_BACKWARD, 1);
                }
            } else {
                if (motor_state != 0) {
                    motor_state = 0;
                    printf("Motor stopped.\n");
                    gpioWrite(GPIO_FORWARD, 0);
                    gpioWrite(GPIO_BACKWARD, 0);
                }
            }
        }
    }

    return 0;
}
