#define MPR121_REG_CONFIG 0x01
#define MPR121_REG_SOFT_RESET 0x06

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27
#define GPIO_22 22

static int i2c_fd;
static struct gpiod_chip *gpiod_chip;
static struct gpiod_line *gpiod_lines[4];

void handle_signal(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_request_release(gpiod_lines[i]);
    }
    gpiod_chip_put(gpiod_chip);
    close(i2c_fd);
    exit(signum);
}

void setup_gpios() {
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpiod_chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_lines[0] = gpiod_line_request_by_name(gpiod_chip, "gpio17", "bit0", GPIOD_LINE_DIRECTION_OUT);
    gpiod_lines[1] = gpiod_line_request_by_name(gpiod_chip, "gpio18", "bit1", GPIOD_LINE_DIRECTION_OUT);
    gpiod_lines[2] = gpiod_line_request_by_name(gpiod_chip, "gpio27", "bit2", GPIOD_LINE_DIRECTION_OUT);
    gpiod_lines[3] = gpiod_line_request_by_name(gpiod_chip, "gpio22", "bit3", GPIOD_LINE_DIRECTION_OUT);

    if (!gpiod_lines[0] || !gpiod_lines[1] || !gpiod_lines[2] || !gpiod_lines[3]) {
        perror("Failed to request GPIO lines");
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    uint8_t reg_value;
    if (read(i2c_fd, &reg_value, 1) != 1) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &MPR121_REG_SOFT_RESET, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, &reg_value, 1) != 1) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    if (reg_value != MPR121_REG_SOFT_RESET) {
        fprintf(stderr, "MPR121 sensor not present or failed to reset\n");
        exit(EXIT_FAILURE);
    }
}

void drive_leds(uint8_t touch_status) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(gpiod_lines[i], (touch_status >> i) & 1);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpios();
    setup_i2c();

    while (1) {
        uint8_t touch_status;
        if (read(i2c_fd, &touch_status, 1) != 1) {
            perror("Failed to read touch status from I2C device");
            exit(EXIT_FAILURE);
        }

        drive_leds(touch_status);

        time_t now = time(NULL);
        fprintf(stderr, "Timestamp: %s - Touch status: 0x%02X\n", ctime(&now), touch_status);

        usleep(50000); // 50 ms delay
    }

    return 0;
}

