#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>

#define MPR121_I2C_ADDR 0x5A
#define MPR121_DEVICE_ID 0x00
#define MPR121_REG_FFI 0x00
#define MPR121_REG_SFI 0x01
#define MPR121_REG_ESI 0x02
#define MPR121_REG_DEBOUNCE 0x03
#define MPR121_REG_AFE_CONFIG 0x04
#define MPR121_REG_BASELINE_FILTER 0x05
#define MPR121_REG_TOUCH_STATUS 0x06

#define GPIO_BASE 0x3F20C000
#define GPIO_LENGTH 0x400
#define GPIO_EXPORT 0x24
#define GPIO_UNEXPORT 0x20
#define GPIO_SET 0x1C
#define GPIO_CLR 0x28
#define GPIO_SET_BIT 7
#define GPIO_CLR_BIT 10

#define LED_GPIO 27

static volatile unsigned *gpio_base;

void cleanup() {
    if (gpio_base) {
        munmap(gpio_base, GPIO_LENGTH);
    }
    close(i2c_fd);
    unlink("proximity.log");
    exit(0);
}

void handle_signal(int signum) {
    cleanup();
}

int main() {
    int i2c_fd;
    char i2c_device[16];
    char log_file[16];
    struct stat st;
    struct timespec ts;
    int proximity_detected = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    sprintf(i2c_device, "/dev/i2c-%d", 1);
    sprintf(log_file, "proximity.log");

    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    if (i2c_read_device_id(i2c_fd) != 0) {
        perror("Failed to read device ID");
        exit(1);
    }

    if (i2c_write_register(i2c_fd, MPR121_REG_FFI, 0x00) != 0) {
        perror("Failed to write FFI register");
        exit(1);
    }

    if (i2c_write_register(i2c_fd, MPR121_REG_SFI, 0x00) != 0) {
        perror("Failed to write SFI register");
        exit(1);
    }

    if (i2c_write_register(i2c_fd, MPR121_REG_ESI, 0x00) != 0) {
        perror("Failed to write ESI register");
        exit(1);
    }

    if (i2c_write_register(i2c_fd, MPR121_REG_DEBOUNCE, 0x00) != 0) {
        perror("Failed to write debounce register");
        exit(1);
    }

    if (i2c_write_register(i2c_fd, MPR121_REG_AFE_CONFIG, 0x00) != 0) {
        perror("Failed to write AFE configuration register");
        exit(1);
    }

    if (i2c_write_register(i2c_fd, MPR121_REG_BASELINE_FILTER, 0x00) != 0) {
        perror("Failed to write baseline filter register");
        exit(1);
    }

    if (gpio_export(LED_GPIO) < 0) {
        perror("Failed to export GPIO");
        exit(1);
    }

    gpio_base = (volatile unsigned *)mmap(NULL, GPIO_LENGTH, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, GPIO_BASE);
    if (gpio_base == MAP_FAILED) {
        perror("Failed to mmap GPIO");
        exit(1);
    }

    while (1) {
        if (i2c_read_touch_status(i2c_fd)) {
            proximity_detected = 1;
            break;
        }
    }

    if (proximity_detected) {
        printf("Proximity detected!\n");
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(stdout, "Proximity event at %ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);

        if (open(log_file, O_WRONLY | O_CREAT | O_APPEND, 0644) < 0) {
            perror("Failed to open log file");
            exit(1);
        }

        fprintf(stdout, "Proximity event at %ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);
        fflush(stdout);

        gpio_base[GPIO_SET] = 1 << LED_GPIO;
        sleep(1);
        gpio_base[GPIO_CLR] = 1 << LED_GPIO;
    }

    cleanup();

    return 0;
}

int i2c_read_device_id(int fd) {
    uint8_t device_id;
    if (read(fd, &device_id, 1) != 1) {
        return -1;
    }
    if (device_id != MPR121_DEVICE_ID) {
        return -1;
    }
    return 0;
}

int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_touch_status(int fd) {
    uint8_t touch_status;
    if (read(fd, &touch_status, 1) != 1) {
        return -1;
    }
    return touch_status & 0x01;
}

int gpio_export(int gpio) {
    int fd;
    char buf[16];
    sprintf(buf, "%d", gpio);
    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        return -1;
    }
    write(fd, buf, strlen(buf));
    close(fd);
    return 0;
}

