#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"

volatile int echo_start_tick = 0;
volatile int echo_stop_tick = 0;
volatile int echo_pulse_width = 0;

void handle_echo_interrupt(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
    } else {
        echo_stop_tick = tick;
        echo_pulse_width = echo_stop_tick - echo_start_tick;
    }
}

void handle_sigint(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    gpioSetISRFunc(ECHO_PIN, EITHER_EDGE, handle_echo_interrupt, 0);

    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate GPIO\n");
        exit(EXIT_FAILURE);
    }

    fclose(stdout);
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    while (1) {
        gpioWrite(TRIG_PIN, 0);
        usleep(2);
        gpioWrite(TRIG_PIN, 1);
        usleep(10);
        gpioWrite(TRIG_PIN, 0);

        gpioSetISRFunc(ECHO_PIN, EITHER_EDGE, handle_echo_interrupt, 0);

        while (echo_pulse_width == 0) {
            usleep(100);
        }

        if (echo_pulse_width < 58 || echo_pulse_width > 25000) {
            echo_pulse_width = 0;
        } else {
            double distance = (echo_pulse_width / 2) * 0.034 / 1000; // Convert to meters
            time_t rawtime;
            struct tm * timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            fprintf(log_file, "%ld.%06ld: %.2f meters\n", (long)rawtime, (long)(rawtime * 1000000 % 1000000), distance);
        }

        echo_pulse_width = 0;
        usleep(1000000); // Wait for 1 second
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

