#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_PIN 27
#define INTERVAL 100 // milliseconds

static struct gpiod_line *gpiod_line;
static struct i2c_client *i2c_client;

void handle_signal(int signum) {
    if (gpiod_line) {
        gpiod_line_free(gpiod_line);
    }
    if (i2c_client) {
        i2c_client_close(i2c_client);
    }
    closelog();
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct i2c_client *client;
    struct i2c_adapter *adapter;
    struct vl53l1x_t sensor;
    int distance;
    int status;

    // Initialize syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    gpiod_line = gpiod_line_request(chip, GPIO_PIN, "XSHUT",
                                    GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!gpiod_line) {
        syslog(LOG_ERR, "Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize I2C
    adapter = i2c_open(I2C_BUS, 0);
    if (adapter < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        gpiod_line_free(gpiod_line);
        gpiod_chip_close(chip);
        return 1;
    }

    client = i2c_client_new(adapter, I2C_ADDR);
    if (!client) {
        syslog(LOG_ERR, "Failed to create I2C client");
        i2c_close(adapter);
        gpiod_line_free(gpiod_line);
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_client = client;

    // Initialize VL53L1X sensor
    status = vl53l1x_init(&sensor, i2c_client);
    if (status != VL53L1X_ERROR_NONE) {
        syslog(LOG_ERR, "Failed to initialize VL53L1X sensor");
        i2c_client_close(i2c_client);
        i2c_close(adapter);
        gpiod_line_free(gpiod_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set XSHUT pin high (active-low trigger)
    gpiod_line_set_value(gpiod_line, 1);

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        status = vl53l1x_get_distance(&sensor, &distance);
        if (status == VL53L1X_ERROR_NONE) {
            syslog(LOG_INFO, "Distance: %d mm", distance);
        } else {
            syslog(LOG_ERR, "Failed to read distance: %d", status);
        }
        sleep(INTERVAL / 1000);
    }

    // Clean up
    vl53l1x_uninit(&sensor);
    i2c_client_close(i2c_client);
    i2c_close(adapter);
    gpiod_line_free(gpiod_line);
    gpiod_chip_close(chip);
    closelog();

    return 0;
}

