#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define GATE_OPEN_THRESHOLD 20
#define LOG_FILE "gate_log.txt"

static FILE *log_file;
static gpiod_chip *gpiod_chip;
static gpiod_line *gpiod_line;

void handle_signal(int signum) {
    if (gpiod_line) {
        gpiod_line_set_value(gpiod_line, 0);
        gpiod_line_unexport(gpiod_line);
        gpiod_line_unref(gpiod_line);
    }
    if (gpiod_chip) {
        gpiod_chip_unref(gpiod_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int read_distance() {
    int fd;
    char buffer[2];
    int distance;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(fd);
        return -1;
    }

    if (write(fd, "\x80", 1) != 1) {
        perror("Failed to write to sensor");
        close(fd);
        return -1;
    }

    usleep(100000); // Wait for measurement

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from sensor");
        close(fd);
        return -1;
    }

    distance = (buffer[0] << 8) | buffer[1];
    close(fd);

    return distance;
}

void log_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    fprintf(log_file, "%s - %s\n", asctime(timeinfo), message);
    fflush(log_file);
}

int main() {
    int distance;
    int gate_state = 0;

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpiod_chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    gpiod_line = gpiod_line_request(gpiod_chip, GATE_GPIO, "gate", 0, 0);
    if (!gpiod_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_unref(gpiod_chip);
        return 1;
    }

    gpiod_line_set_value(gpiod_line, gate_state);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_unexport(gpiod_line);
        gpiod_line_unref(gpiod_line);
        gpiod_chip_unref(gpiod_chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        distance = read_distance();
        if (distance < 0) {
            log_message("Failed to read distance");
            continue;
        }

        distance /= 10; // Convert mm to cm

        if (distance < GATE_OPEN_THRESHOLD) {
            if (gate_state == 0) {
                gate_state = 1;
                gpiod_line_set_value(gpiod_line, 1);
                log_message("Gate opened at distance: %d cm");
            }
        } else {
            if (gate_state == 1) {
                gate_state = 0;
                gpiod_line_set_value(gpiod_line, 0);
                log_message("Gate closed at distance: %d cm");
            }
        }

        log_message("Distance: %d cm");

        usleep(100000); // Sleep for 100 ms
    }

    return 0;
}

