code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define SAMPLES 5
#define TIMEOUT_MS 30
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400

volatile sig_atomic_t stop = 0;
volatile int pulse_width = 0;
volatile int new_pulse = 0;

void sigint_handler(int signum) {
    stop = 1;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_width = tick;
        new_pulse = 1;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SERVO_PIN mode\n");
        return 1;
    }

    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize servo\n");
        return 1;
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Failed to set echo callback\n");
        return 1;
    }

    FILE *file = fopen("distance_log.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    fprintf(file, "Timestamp,Distance (cm),Angle (deg)\n");

    double distances[SAMPLES] = {0};
    int sample_index = 0;

    while (!stop) {
        if (gpioWrite(TRIGGER_PIN, PI_ON) < 0) {
            fprintf(stderr, "Failed to trigger ultrasonic sensor\n");
            return 1;
        }

        usleep(10000);

        if (gpioWrite(TRIGGER_PIN, PI_OFF) < 0) {
