#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define PROXIMITY_ADDR 0x60 // Default I2C address
#define PROXIMITY_GPIO 27 // GPIO27 (BCM numbering)
#define LOG_FILE "proximity.log"
#define DEFAULT_THRESHOLD 1000

static volatile sig_atomic_t shutdown = 0;
static volatile int proximity_value = 0;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_addr = PROXIMITY_ADDR;

void handle_sigint(int signum) {
    shutdown = 1;
}

void handle_interrupt(int level, uint32_t tick, uint32_t arg) {
    if (shutdown) {
        return;
    }
    proximity_value = read_proximity_value();
    log_proximity_data();
}

int read_proximity_value() {
    int fd;
    char buffer[2];
    int result;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, i2c_addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    result = read(fd, buffer, 2);
    if (result != 2) {
        perror("Failed to read proximity value");
        close(fd);
        return -1;
    }

    close(fd);

    return (buffer[0] << 8) | buffer[1];
}

void log_proximity_data() {
    FILE *log_file;
    char timestamp[20];
    char status[10];

    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (proximity_value <= threshold) {
        strcpy(status, "SAFE");
    } else {
        strcpy(status, "ALERT");
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity_value, status);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int result;

    if (argc > 1 && strcmp(argv[1], "-t") == 0) {
        threshold = atoi(argv[2]);
    }

    if (argc > 2 && strcmp(argv[1], "-a") == 0) {
        i2c_addr = strtol(argv[2], NULL, 0);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_line_request(chip, PROXIMITY_GPIO, "Proximity Interrupt",
                              GPIOD_LINE_DIRECTION_IN, GPIOD_LINE_ACTIVE_HIGH,
                              GPIOD_LINE_OPEN_DRAIN, 0);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_set_edge(line, GPIOD_LINE_BOTH_EDGES);

    result = gpiod_line_request_event(line, handle_interrupt, NULL);
    if (result < 0) {
        fprintf(stderr, "Failed to request event on GPIO line\n");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!shutdown) {
        usleep(100000); // Sleep for 100ms to avoid busy-waiting
    }

    gpiod_line_release(line);
    gpiod_chip_put(chip);
    gpioTerminate();

    return 0;
}

