#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 200
#define MIN_FREQ 200
#define MAX_FREQ 2000

volatile int running = 1;

void handle_signal(int signum) {
    if (running) {
        running = 0;
        gpioPWM(PWM_PIN, 0);
        gpioTerminate();
        exit(0);
    }
}

double calculate_frequency(double distance) {
    double log_min = log10(MIN_FREQ);
    double log_max = log10(MAX_FREQ);
    double log_range = log_max - log_min;
    double distance_range = MAX_DISTANCE - MIN_DISTANCE;

    double log_distance = log10(distance);
    double normalized_distance = (log_distance - log10(MIN_DISTANCE)) / distance_range;

    double frequency = pow(10, log_min + normalized_distance * log_range);
    return frequency;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    double previous_frequency = 0.0;

    while (running) {
        gpioWrite(TRIG_PIN, 0);
        usleep(2);
        gpioWrite(TRIG_PIN, 1);
        usleep(10);
        gpioWrite(TRIG_PIN, 0);

        int echo_start = 0;
        int echo_end = 0;
        int timeout = 0;

        while (gpioRead(ECHO_PIN) == 0 && timeout < 200000) {
            echo_start = gpioTick();
            timeout += 1000;
            usleep(1000);
        }

        while (gpioRead(ECHO_PIN) == 1 && timeout < 200000) {
            echo_end = gpioTick();
            timeout += 1000;
            usleep(1000);
        }

        if (timeout >= 200000) {
            printf("Timeout occurred, using previous frequency: %.2f Hz\n", previous_frequency);
            gpioPWM(PWM_PIN, previous_frequency);
        } else {
            double distance = (echo_end - echo_start) * 0.034 / 2;

            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Distance out of range, using previous frequency: %.2f Hz\n", previous_frequency);
                gpioPWM(PWM_PIN, previous_frequency);
            } else {
                double frequency = calculate_frequency(distance);
                printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
                previous_frequency = frequency;
                gpioPWM(PWM_PIN, frequency);
            }
        }

        usleep(100000); // 100 ms delay
    }

    gpioTerminate();
    return 0;
}

