This C program initializes the pigpio library, sets up the GPIO pins for the HC-SR04 ultrasonic sensor and the PWM output for the speaker. It then enters a loop where it measures the distance using the HC-SR04 sensor, calculates the corresponding frequency based on the distance, and sets the PWM output to generate the audio tone. It handles timeouts and out-of-range distances by preserving the previous frequency. A signal handler is installed to stop the PWM and terminate the program cleanly on SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

#define MIN_DISTANCE 5 // cm
#define MAX_DISTANCE 50 // cm
#define MIN_FREQUENCY 200 // Hz
#define MAX_FREQUENCY 2000 // Hz
#define ECHO_TIMEOUT 100000 // 100 ms

void handle_sigint(int signum) {
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();
    exit(0);
}

double map_distance_to_frequency(double distance) {
    double frequency = (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_FREQUENCY;
    if (frequency < MIN_FREQUENCY) {
        return MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        return MAX_FREQUENCY;
    }
    return frequency;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        goto cleanup;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        goto cleanup;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN mode\n");
        goto cleanup;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        gpioWrite(TRIGGER_PIN, PI_LOW);
        usleep(10);
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        usleep(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        int echo_start = -1;
        int echo_end = -1;
        int timeout = 0;

        while (echo_start == -1 && timeout < ECHO_TIMEOUT) {
            if (gpioRead(ECHO_PIN) == PI_HIGH) {
                echo_start = gpioTick();
            }
            timeout += 10;
            usleep(10);
        }

        if (echo_start == -1) {
            fprintf(stderr, "Echo start timeout\n");
            continue;
        }

        while (echo_end == -1 && timeout < ECHO_TIMEOUT) {
            if (gpioRead(ECHO_PIN) == PI_LOW) {
                echo_end = gpioTick();
            }
            timeout += 10;
            usleep(10);
        }

        if (echo_end == -1) {
            fprintf(stderr, "Echo end timeout\n");
            continue;
        }

        double distance = (echo_end - echo_start) * 0.034 / 2; // cm
        double frequency = map_distance_to_frequency(distance);

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        gpioPWM(BUZZER_PIN, frequency);

        usleep(10000); // 10 ms
    }

cleanup:
    gpioTerminate();
    return 0;
}

