int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *cs_line;
    int spi_fd;
    int distance;
    FILE *log_file;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &0) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &0) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI mode or speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO chip
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line for chip select
    if (gpiod_line_request_any(chip, "CS", GPIOD_LINE_DIRECTION_OUTPUT, &cs_line) < 0) {
        fprintf(stderr, "Failed to request GPIO line for CS\n");
        gpiod_chip_put(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(cs_line);
        gpiod_chip_put(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        distance = read_distance(spi_fd);
        if (distance >= 200 && distance <= 5000) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d\n",
                    now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                    now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, distance);
        }
        usleep(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(cs_line);
    gpiod_chip_put(chip);
    close(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

void handle_signal(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);

    // Close SPI handle
    close(spi_fd);

    // Release GPIO resources
    gpiod_line_release(cs_line);
    gpiod_chip_put(chip);

    // Flush and close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    exit(EXIT_SUCCESS);
}

int read_distance(int spi_fd) {
    uint8_t buffer[BUFFER_SIZE];
