#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x60 // Default I2C address for Si1175
#define BUFFER_SIZE 2
#define LOG_FILE "proximity_log.csv"

// Function to format timestamp in ISO-8601
char* format_timestamp(char* buffer, size_t size) {
    time_t rawtime;
    struct tm * timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, size, "%Y-%m-%dT%H:%M:%S", timeinfo);
    return buffer;
}

// Function to read ambient light value from Si1175
uint16_t read_als_visible(int fd) {
    uint8_t buffer[BUFFER_SIZE];
    if (read(fd, buffer, BUFFER_SIZE) != BUFFER_SIZE) {
        perror("Error reading from I2C device");
        return 0;
    }
    return (buffer[0] << 8) | buffer[1];
}

// Function to write to Si1175
int write_to_sensor(int fd, uint8_t reg, uint8_t data) {
    uint8_t buffer[2] = {reg, data};
    if (write(fd, buffer, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize I2C communication
int init_i2c(const char* device_file) {
    int fd = open(device_file, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to log the ambient light value
void log_als_visible(int fd, FILE* log_file) {
    char timestamp[20];
    uint16_t als_visible = read_als_visible(fd);
    if (als_visible == 0) {
        fprintf(log_file, "%s,0\n", timestamp);
    } else {
        fprintf(log_file, "%s,%u\n", timestamp, als_visible);
    }
}

// Signal handler to clean up on SIGINT or SIGTERM
void cleanup(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    close(i2c_fd);
    fclose(log_file);
    exit(signum);
}

int main() {
    const char* i2c_device_file = "/dev/i2c-1"; // Assuming I2C bus 1
    int i2c_fd = init_i2c(i2c_device_file);
    if (i2c_fd < 0) {
        return 1;
    }

    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "timestamp,als_visible\n");

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        log_als_visible(i2c_fd, log_file);
        sleep(5);
    }

    return 0;
}

