#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_ADDR 0x60
#define I2C_DEV "/dev/i2c-1"
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 10
#define SAMPLING_INTERVAL 500
#define LOG_FILE "si1120_log.txt"

#define ALS_REGISTER 0x0F
#define PROX_REGISTER 0x10
#define PART_ID_REGISTER 0x00
#define PART_ID_EXPECTED 0x53

int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        if (write(fd, &reg, 1) != 1 || write(fd, &value, 1) != 1) {
            if (retries < I2C_RETRY_COUNT - 1) {
                sleep(I2C_RETRY_DELAY / 1000);
            }
            retries++;
        } else {
            return 0;
        }
    }
    perror("Failed to write to I2C device");
    return -1;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    int retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        if (write(fd, &reg, 1) != 1 || read(fd, data, length) != length) {
            if (retries < I2C_RETRY_COUNT - 1) {
                sleep(I2C_RETRY_DELAY / 1000);
            }
            retries++;
        } else {
            return 0;
        }
    }
    perror("Failed to read from I2C device");
    return -1;
}

int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Failed to close I2C device");
        return -1;
    }
    return 0;
}

int si1120_init(int fd) {
    uint8_t part_id;
    if (i2c_read(fd, PART_ID_REGISTER, &part_id, 1) != 0 || part_id != PART_ID_EXPECTED) {
        perror("Failed to verify Si1120 part ID");
        return -1;
    }
    return 0;
}

int main() {
    int fd = i2c_open(I2C_DEV);
    if (fd < 0) {
        return 1;
    }

    if (si1120_init(fd) != 0) {
        i2c_close(fd);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
