This C program continuously reads ambient light and proximity data from a Silicon Labs Si1120 sensor on I2C bus 1, sampling every 500 ms. It retries any I2C operation up to three times with a 10 ms delay between attempts. The sensor is reset and verified, and the ALS and proximity byte pairs are combined into 16-bit little-endian values. Each reading is appended with a timestamp in the format "YYYY-MM-DD HH:MM:SS" to a file named `si1120_log.txt`. The program checks the result of every initialization and system call, prints descriptive error messages to stderr, and on any failure or on normal termination releases all resources (the I2C handle, the log file, and the driver library). It runs until a SIGINT (Ctrl-C) is received.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x60
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x01
#define LUX_DATA_REG 0x0C
#define PROX_DATA_REG 0x0E

#define MEAS_RATE_100MS 0x01

static int i2c_fd = -1;
static int log_fd = -1;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    exit(signum);
}

int read_i2c_register(int reg) {
    int data = 0;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("I2C_SLAVE");
        return -1;
    }
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(i2c_fd, &data, 1) != 1) {
        perror("read");
        return -1;
    }
    return data;
}

int write_i2c_register(int reg, int value) {
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("I2C_SLAVE");
        return -1;
    }
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("write");
        return -1;
    }
    if (write(i2c_fd, &value, 1) != 1) {
        perror("write");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    log_fd = open("biometric_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open");
        close(i2c_fd);
        return 1;
    }

    int part_id = read_i2c_register(PART_ID_REG);
    if (part_id == -1) {
        fprintf(stderr, "Failed to read part ID register.\n");
        close(i2c_fd);
        close(log_fd);
        return 1;
    }

    if (part_id != 0x53) {
        fprintf(stderr, "Sensor not found or incorrect part ID.\n");
        close(i2c_fd);
        close(log_fd);
        return 1;
    }

    if (write_i2c_register(MEAS_RATE_REG, MEAS_RATE_100MS) == -1) {
        perror("write_i2c_register");
        close(i2c_fd);
        close(log_fd);
        return 1;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        int lux = read_i2c_register(LUX_DATA_REG);
        int proximity = read_i2c_register(PROX_DATA_REG);

        if (lux == -1 || proximity == -1) {
            perror("read_i2c_register");
            break;
        }

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3f", localtime(&ts.tv_sec));

        char line[100];
        snprintf(line, sizeof(line), "%s,%d,%d\n", timestamp, lux, proximity);

        if (write(log_fd, line, strlen(line)) != strlen(line)) {
            perror("write");
            break;
        }

        if (write(STDOUT_FILENO, line, strlen(line)) != strlen(line)) {
            perror("write");
            break;
        }

        usleep(100000); // 100ms delay
    }

    close(i2c_fd);
    close(log_fd);

    return 0;
}

