void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (proximity_log_fd >= 0) {
        fclose(proximity_log_fd);
    }
    exit(signum);
}

int read_i2c_register(int reg) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = read(i2c_fd, &reg, 1);
        if (result == 1) {
            return reg;
        }
        retries++;
        sleep(1);
    }

    fprintf(stderr, "Failed to read I2C register after %d retries\n", MAX_RETRIES);
    return -1;
}

