#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define SPEED_OF_SOUND 34300 // cm/s
#define MIN_DISTANCE 20 // cm

volatile sig_atomic_t running = 1;

void handle_interrupt(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;

    if (level == 0) {
        start_tick = tick;
    } else {
        uint32_t duration = tick - start_tick;
        uint32_t distance = (duration * SPEED_OF_SOUND) / 2000000; // cm

        printf("Distance: %u cm\n", distance);

        if (distance < MIN_DISTANCE) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }
    }
}

void sigint_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        goto cleanup;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        goto cleanup;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN mode\n");
        goto cleanup;
    }

    if (gpioSetAlertFunc(ECHO_PIN, handle_interrupt) < 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        goto cleanup;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        gpioWrite(TRIGGER_PIN, 0);
        usleep(2);
        gpioWrite(TRIGGER_PIN, 1);
        usleep(10);
        gpioWrite(TRIGGER_PIN, 0);

        sleep(1);
    }

cleanup:
    gpioTerminate();
    return 0;
}

