#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define MAX_DISTANCE 200.0
#define MIN_DISTANCE 20.0
#define MAX_ANGLE 180.0
#define MIN_ANGLE 0.0

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

double calculate_distance(int echo_pin) {
    gpioSetMode(echo_pin, PI_INPUT);
    gpioSetPullUpDown(echo_pin, PI_PUD_DOWN);

    double duration = 0.0;
    int start_time = 0;
    int end_time = 0;

    gpioWrite(TRIGGER_PIN, PI_LOW);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    start_time = gpioGetTick(echo_pin);

    while (gpioRead(echo_pin) == PI_LOW && !stop) {
        if (gpioGetTick(echo_pin) - start_time > 20000) {
            return -1.0; // Timeout
        }
    }

    end_time = gpioGetTick(echo_pin);

    duration = (double)(end_time - start_time) / 1000000.0;

    return duration * 34300.0 / 2.0; // Speed of sound in cm/s
}

double calculate_angle(double distance) {
    double angle = 0.0;

    if (distance >= MAX_DISTANCE) {
        angle = MIN_ANGLE;
    } else if (distance <= MIN_DISTANCE) {
        angle = MAX_ANGLE;
    } else {
        angle = MIN_ANGLE + ((MAX_ANGLE - MIN_ANGLE) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
    }

    return angle;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    signal(SIGINT, handle_sigint);

    while (!stop) {
        double distance = calculate_distance(ECHO_PIN);

        if (distance >= 0.0) {
            double angle = calculate_angle(distance);
            gpioServo(SERVO_PIN, (int)(angle * 10.0 + 500));
            printf("Distance: %.2f cm, Angle: %.2f°\n", distance, angle);
        } else {
            printf("Sensor error or timeout\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    gpioTerminate();
    return 0;
}

