#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_DEFAULT_ADDR 0x29
#define TIMING_BUDGET_REG 0x0000
#define RANGE_STATUS_REG 0x0014
#define RANGE_DATA_REG 0x0014
#define PWM_PIN 18
#define PWM_FREQ 50
#define PWM_MAX_RANGE 2000
#define PWM_MIN_RANGE 1000
#define DISTANCE_THRESHOLD_FAR 250
#define DISTANCE_THRESHOLD_CLOSE 200

int i2c_fd;
int pwm_fd;
FILE *log_file;

void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (pwm_fd >= 0) {
        close(pwm_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int i2c_write(uint8_t reg, uint16_t value) {
    uint8_t buffer[3];
    buffer[0] = reg & 0xFF;
    buffer[1] = (value >> 8) & 0xFF;
    buffer[2] = value & 0xFF;
    return write(i2c_fd, buffer, 3);
}

int i2c_read(uint8_t reg, uint16_t *value) {
    uint8_t buffer[3];
    int bytes_read = read(i2c_fd, buffer, 3);
    if (bytes_read != 3) {
        return -1;
    }
    *value = (buffer[1] << 8) | buffer[2];
    return 0;
}

void setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_DEFAULT_ADDR) < 0) {
        perror("Failed to acquire exclusive access to I2C bus");
        exit(1);
    }

    uint16_t model_id;
    if (i2c_read(0x00, &model_id) < 0) {
        perror("Failed to read model ID");
        exit(1);
    }

    if (model_id != 0x5678) {
        fprintf(stderr, "Invalid model ID: 0x%04X\n", model_id);
        exit(1);
    }

    uint16_t timing_budget = 0x0000;
    if (i2c_write(TIMING_BUDGET_REG, timing_budget) < 0) {
        perror("Failed to write timing budget");
        exit(1);
    }
}

void setup_pwm() {
    char pwm_pin_path[10];
    sprintf(pwm_pin_path, "/sys/class/pwm/pwmchip0/export");
    FILE *export_file = fopen(pwm_pin_path, "w");
    if (!export_file) {
        perror("Failed to export PWM pin");
        exit(1);
    }
    fclose(export_file);

    sprintf(pwm_pin_path, "/sys/class/pwm/pwmchip0/pwm%d/period", PWM_PIN);
    FILE *period_file = fopen(pwm_pin_path, "w");
    if (!period_file) {
