#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_ANGLE 0.0
#define MAX_ANGLE 180.0

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

double distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_ANGLE;
    }
}

void handle_sigint(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    gpioServoWrite(SERVO_PIN, SERVO_MIN_PULSE);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    while (1) {
        gpioWrite(TRIGGER_PIN, LOW);
        usleep(2);
        gpioWrite(TRIGGER_PIN, HIGH);
        usleep(10);
        gpioWrite(TRIGGER_PIN, LOW);

        int start = gpioGetTick(ECHO_PIN);
        int end = start;
        int timeout = 50000; // 50 ms

        while (gpioRead(ECHO_PIN) == 0 && (end - start) < timeout) {
            end = gpioGetTick(ECHO_PIN);
        }

        if ((end - start) >= timeout) {
            printf("Timeout: Distance = -1.0 cm, Angle = %f°\n", MIN_ANGLE);
            continue;
        }

        double duration = (double)(end - start) / 1000000.0;
        double distance = (duration * 34300.0) / 2.0; // Speed of sound is approximately 343 m/s

        double angle = distance_to_angle(distance);
        int pulse_width = (int)((angle / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) + SERVO_MIN_PULSE);

        if (pulse_width < SERVO_MIN_PULSE || pulse_width > SERVO_MAX_PULSE) {
            fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
            continue;
        }

        gpioServoWrite(SERVO_PIN, pulse_width);
        printf("Distance = %.2f cm, Angle = %.2f°\n", distance, angle);

        usleep(100000); // 100 ms pause
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

