#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libi2c.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x40
#define CONFIG_REG 0xF3
#define TEMP_HUMIDITY_REG 0xF5
#define READ_DELAY_MS 10
#define LOG_INTERVAL_S 2

static volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int i2c_open(void) {
    int fd = i2c_open(I2C_BUS, 0);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return fd;
}

int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int ret = i2c_smbus_write_byte_data(fd, reg, value);
    if (ret < 0) {
        perror("Failed to write to I2C register");
        return -1;
    }
    return 0;
}

int i2c_read_register(int fd, uint8_t reg, uint8_t *data, size_t length) {
    int ret = i2c_smbus_read_i2c_block_data(fd, reg, data, length);
    if (ret < 0) {
        perror("Failed to read from I2C register");
        return -1;
    }
    return 0;
}

void read_sensor(int fd) {
    uint8_t config_data = 0x00;
    uint8_t read_data[2];

    // Write CONFIG register
    if (i2c_write_register(fd, CONFIG_REG, config_data) < 0) {
        return;
    }

    // Wait for conversion
    usleep(READ_DELAY_MS * 1000);

    // Write TEMP_HUMIDITY_REG
    if (i2c_write_register(fd, TEMP_HUMIDITY_REG, 0x00) < 0) {
        return;
    }

    // Wait for conversion
    usleep(READ_DELAY_MS * 1000);

    // Read TEMP_HUMIDITY_REG
    if (i2c_read_register(fd, TEMP_HUMIDITY_REG, read_data, 2) < 0) {
        return;
    }

    // Log the read data
    printf("Temperature: %d, Humidity: %d\n", read_data[0], read_data[1]);
}

int main() {
    int fd = i2c_open();
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        read_sensor(fd);
        sleep(LOG_INTERVAL_S);
    }

    // Cleanup
    i2c_close(fd);
    return EXIT_SUCCESS;
}

