This C program interfaces with a Silicon Labs Si7005 humidity and temperature sensor on I2C bus 1. It initializes the I2C bus, verifies successful initialization, and then repeatedly reads the sensor data every 2 seconds. It checks for errors during I2C read and write operations and attempts recovery by closing and reopening the I2C handle. The program also handles SIGINT to perform a graceful shutdown, closing the I2C handle and terminating the driver library.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WHO_AM_I 0x75
#define ACCEL_DATA 0x3B
#define GYRO_DATA 0x43
#define TEMP_DATA 0x41

#define ACCEL_DATA_LEN 14

static void handle_signal(int signum) {
    printf("\nReceived signal %d, shutting down...\n", signum);
    gpiod_i2c_close(i2c_handle);
    exit(0);
}

int main() {
    struct gpiod_i2c_handle *i2c_handle = NULL;
    uint8_t who_am_i_data[1];
    uint8_t accel_data[ACCEL_DATA_LEN];
    int16_t accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z;

    // Initialize signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    if (gpiod_i2c_open(I2C_BUS, &i2c_handle) < 0) {
        perror("gpiod_i2c_open");
        return 1;
    }

    // Verify sensor presence
    if (gpiod_i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, WHO_AM_I, 1, who_am_i_data) < 0) {
        perror("gpiod_i2c_read_i2c_block_data (WHO_AM_I)");
        gpiod_i2c_close(i2c_handle);
        return 1;
    }

    if (who_am_i_data[0] != 0x68) {
        printf("Sensor not found or incorrect WHO_AM_I value.\n");
        gpiod_i2c_close(i2c_handle);
        return 1;
    }

    printf("Sensor found, starting data logging...\n");

    while (1) {
        // Read accelerometer data
        if (gpiod_i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, ACCEL_DATA, ACCEL_DATA_LEN, accel_data) < 0) {
            perror("gpiod_i2c_read_i2c_block_data (ACCEL_DATA)");
            continue;
        }

        // Parse accelerometer data
        accel_x = (int16_t)((accel_data[0] << 8) | accel_data[1]);
        accel_y = (int16_t)((accel_data[2] << 8) | accel_data[3]);
        accel_z = (int16_t)((accel_data[4] << 8) | accel_data[5]);

        // Read temperature data
        if (gpiod_i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, TEMP_DATA, 2, accel_data) < 0) {
            perror("gpiod_i2c_read_i2c_block_data (TEMP_DATA)");
            continue;
        }

        // Parse temperature data
        temp = (int16_t)((accel_data[0] << 8) | accel_data[1]);

        // Read gyroscope data
        if (gpiod_i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, GYRO_DATA, ACCEL_DATA_LEN, accel_data) < 0) {
            perror("gpiod_i2c_read_i2c_block_data (GYRO_DATA)");
            continue;
        }

        // Parse gyroscope data
        gyro_x = (int16_t)((accel_data[0] << 8) | accel_data[1]);
        gyro_y = (int16_t)((accel_data[2] << 8) | accel_data[3]);
        gyro_z = (int16_t)((accel_data[4] << 8) | accel_data[5]);

        // Print data
        printf("Accelerometer: X=%d, Y=%d, Z=%d, Temperature=%d, Gyroscope: X=%d, Y=%d, Z=%d\n",
               accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        // Sleep for 100ms
        usleep(100000);
    }

    // Cleanup
    gpiod_i2c_close(i2c_handle);

    return 0;
}

