    if (who_am_i_data[0] != 0x68) {
        printf("Sensor not found or incorrect WHO_AM_I value.\n");
        gpiod_i2c_close(i2c_handle);
        return 1;
    }

    printf("Sensor found, starting data logging...\n");

    while (1) {
        // Read accelerometer data
        if (gpiod_i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, ACCEL_DATA, ACCEL_DATA_LEN, accel_data) < 0) {
            perror("gpiod_i2c_read_i2c_block_data (ACCEL_DATA)");
            continue;
        }

        // Parse accelerometer data
        accel_x = (int16_t)((accel_data[0] << 8) | accel_data[1]);
        accel_y = (int16_t)((accel_data[2] << 8) | accel_data[3]);
        accel_z = (int16_t)((accel_data[4] << 8) | accel_data[5]);

        // Read temperature data
        if (gpiod_i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, TEMP_DATA, 2, accel_data) < 0) {
            perror("gpiod_i2c_read_i2c_block_data (TEMP_DATA)");
            continue;
        }

        // Parse temperature data
        temp = (int16_t)((accel_data[0] << 8) | accel_data[1]);

        // Read gyroscope data
        if (gpiod_i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, GYRO_DATA, ACCEL_DATA_LEN, accel_data) < 0) {
            perror("gpiod_i2c_read_i2c_block_data (GYRO_DATA)");
            continue;
        }

        // Parse gyroscope data
        gyro_x = (int16_t)((accel_data[0] << 8) | accel_data[1]);
        gyro_y = (int16_t)((accel_data[2] << 8) | accel_data[3]);
        gyro_z = (int16_t)((accel_data[4] << 8) | accel_data[5]);

        // Print data
        printf("Accelerometer: X=%d, Y=%d, Z=%d, Temperature=%d, Gyroscope: X=%d, Y=%d, Z=%d\n",
               accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        // Sleep for 100ms
        usleep(100000);
    }

    // Cleanup
    gpiod_i2c_close(i2c_handle);

    return 0;
}
