#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libi2c.h>

#define SHT40_ADDR 0x44
#define SHT40_MEASURE_CMD 0xF3
#define SHT40_MEASURE_DELAY 10
#define SHT40_DATA_LEN 6
#define SHT40_TEMP_MSB 0
#define SHT40_TEMP_LSB 1
#define SHT40_HUM_MSB 3
#define SHT40_HUM_LSB 4
#define SHT40_CRC_TEMP 2
#define SHT40_CRC_HUM 5

#define CRC8_POLY 0x07

static int i2c_handle = -1;

void handle_signal(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    exit(signum == SIGINT ? 0 : 1);
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(uint8_t *data) {
    int ret = i2c_read_device(i2c_handle, SHT40_ADDR, data, SHT40_DATA_LEN);
    if (ret != SHT40_DATA_LEN) {
        fprintf(stderr, "Error reading sensor data: %d\n", ret);
        return -1;
    }

    uint8_t crc_temp = crc8(&data[SHT40_TEMP_MSB], 2);
    uint8_t crc_hum = crc8(&data[SHT40_HUM_MSB], 2);

    if (crc_temp != data[SHT40_CRC_TEMP] || crc_hum != data[SHT40_CRC_HUM]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_handle = i2c_open(1, 0);
    if (i2c_handle == -1) {
        perror("Failed to open I2C bus");
        return 1;
    }

    while (1) {
        uint8_t data[SHT40_DATA_LEN];
        int ret = i2c_write_device(i2c_handle, SHT40_ADDR, &SHT40_MEASURE_CMD, 1);
        if (ret != 1) {
            fprintf(stderr, "Error writing command: %d\n", ret);
            continue;
        }

        usleep(SHT40_MEASURE_DELAY * 1000);

        ret = read_sensor_data(data);
        if (ret == 0) {
            float temperature = (data[SHT40_TEMP_MSB] << 8) | data[SHT40_TEMP_LSB];
            float humidity = (data[SHT40_HUM_MSB] << 8) | data[SHT40_HUM_LSB];
            printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature / 100.0, humidity / 100.0);
        }

        sleep(5);
    }

    return 0;
}

