#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define MLX90614_DEFAULT_ADDR 0x5A
#define TEMP_LOG_FILE "temperature_log.csv"

// Function to read temperature from the sensor
int read_temperature(int fd) {
    int ambient_temp, object_temp;
    char buffer[2];

    // Read ambient temperature
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading ambient temperature");
        return -1;
    }
    ambient_temp = (buffer[0] << 8) | buffer[1];

    // Read object temperature
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading object temperature");
        return -1;
    }
    object_temp = (buffer[0] << 8) | buffer[1];

    // Convert to Celsius
    ambient_temp = (ambient_temp * 0.02) - 273.15;
    object_temp = (object_temp * 0.02) - 273.15;

    return ambient_temp;
}

// Function to handle SIGINT
void handle_sigint(int signum) {
    printf("\nCaught SIGINT, cleaning up...\n");
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct timespec ts;
    char timestamp[20];
    int ambient_temp;

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_DEFAULT_ADDR) < 0) {
        perror("Failed to set I2C device address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(TEMP_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Register SIGINT handler
    signal(SIGINT, handle_sigint);

    // Main loop
    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Read temperature
        ambient_temp = read_temperature(i2c_fd);
        if (ambient_temp == -1) {
            continue; // Skip this iteration if read fails
        }

        // Write to log file
        fprintf(log_file, "%s,%.2f\n", timestamp, ambient_temp);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close resources
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

