#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x40
#define TEMP_LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define PERIOD 5000 // 5 seconds

// Function prototypes
void handle_signal(int signum);
int read_temperature(int fd);
void log_temperature(const char *filename, const char *message);

int main() {
    int fd;
    char buffer[16];
    char timestamp[32];
    struct timespec ts;
    struct sigaction sa;

    // Open I2C bus
    fd = i2c_open(I2C_BUS, 0);
    if (fd < 0) {
        log_temperature(ERROR_LOG_FILE, "Failed to open I2C bus");
        return 1;
    }

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        int temp = read_temperature(fd);
        if (temp < 0) {
            log_temperature(ERROR_LOG_FILE, "Failed to read temperature");
        } else {
            char message[64];
            snprintf(message, sizeof(message), "%s: %d C", timestamp, temp);
            log_temperature(TEMP_LOG_FILE, message);
        }

        usleep(PERIOD * 1000); // Sleep for 5 seconds
    }

    // Close I2C bus
    i2c_close(fd);

    return 0;
}

void handle_signal(int signum) {
    // Perform cleanup
    printf("Received signal %d, cleaning up...\n", signum);
    // (No additional cleanup needed in this example)
    exit(0);
}

int read_temperature(int fd) {
    int result = i2c_smbus_read_byte_data(fd, 0x00);
    if (result < 0) {
        return -1;
    }

    // Assuming the sensor returns temperature in 0.1°C increments
    return result * 0.1;
}

void log_temperature(const char *filename, const char *message) {
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s\n", message);
    fclose(file);
}

