#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define SDP810_I2C_ADDR 0x40
#define SDP810_CMD_CONT_MEAS 0x00
#define SDP810_MEAS_DATA_LEN 9
#define SDP810_MEAS_INTERVAL 1000 // 1 ms
#define SDP810_CRC_POLY 0x07
#define SDP810_CRC_INIT 0x00

int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

uint8_t calculate_crc8(uint8_t *data, size_t len) {
    uint8_t crc = SDP810_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void read_sensor_data(uint8_t *data) {
    if (read(i2c_fd, data, SDP810_MEAS_DATA_LEN) != SDP810_MEAS_DATA_LEN) {
        perror("Error reading sensor data");
        exit(EXIT_FAILURE);
    }
}

void validate_crc8(uint8_t *data) {
    uint8_t calculated_crc = calculate_crc8(data, SDP810_MEAS_DATA_LEN - 1);
    uint8_t received_crc = data[SDP810_MEAS_DATA_LEN - 1];
    if (calculated_crc != received_crc) {
        fprintf(stderr, "CRC-8 validation failed\n");
        exit(EXIT_FAILURE);
    }
}

void convert_and_log_data(uint8_t *data) {
    uint16_t pressure_raw = (data[0] << 8) | data[1];
    uint16_t temp_raw = (data[3] << 8) | data[4];
    uint16_t pressure_scale = (data[5] << 8) | data[6];
    uint16_t temp_scale = (data[7] << 8) | data[8];

    double pressure = (double)pressure_raw / pressure_scale;
    double temperature = (double)temp_raw / temp_scale;

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *file = fopen("pressure_log.csv", "a");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    if (fseek(file, 0, SEEK_END) != 0) {
        perror("Error seeking in file");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,Pressure (Pa),Temperature (°C)\n");
    }

    fprintf(file, "%s,%f,%f\n", buffer, pressure, temperature);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    char i2c_device[10];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", 1);

    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t cmd = SDP810_CMD_CONT_MEAS;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Error writing command to sensor");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t data[SDP810_MEAS_DATA_LEN];

