        perror("Error seeking in file");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    if (ftell(file) == 0) {
        fprintf(file, "Timestamp,Pressure (Pa),Temperature (°C)\n");
    }

    fprintf(file, "%s,%f,%f\n", buffer, pressure, temperature);
    fclose(file);
