int write_i2c(int fd, uint8_t addr, uint8_t *data, size_t len) {
    int ret = -1;
    do {
        ret = write(fd, data, len);
        if (ret == -1) {
            log_error_and_retry(fd, "write_i2c");
        }
    } while (ret == -1);
    return ret;
}

