    if (gpiod_chip_open("/dev/gpiomem", &chip) < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "2", &sda_line, GPIOD_LINE_DIRECTION_OUTPUT, "SDA") < 0) {
        fprintf(stderr, "Failed to request SDA line\n");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "3", &scl_line, GPIOD_LINE_DIRECTION_OUTPUT, "SCL") < 0) {
        fprintf(stderr, "Failed to request SCL line\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open_i2c("/dev/i2c-1");

    // Open log file
    log_fd = open_log_file(SHT40_LOG_FILE);

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signals;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Write command to sensor
        if (write_i2c(i2c_fd, SHT40_ADDR, cmd, 1) != 1) {
            continue;
        }

        // Wait for measurement
        nanosleep(&ts, NULL);

        // Read result from sensor
        if (read_i2c(i2c_fd, SHT40_ADDR, result, SHT40_RESULT_LEN) != SHT40_RESULT_LEN) {
            continue;
        }

        // Validate CRCs
        if (crc8(result, 5) != result[5] || crc8(result + 2, 4) != result[6]) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Log temperature and humidity
        double temperature = (result[0] << 8 | result[1]) * 0.02;
        double humidity = (result[2] << 8 | result[3]) * 0.04;
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(log_fd, "%s: Temperature = %.2f°C, Humidity = %.2f%%\n", timestamp, temperature, humidity);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Cleanup
    close_fd(i2c_fd, "I2C file descriptor");
    close_fd(log_fd, "Log file descriptor");
    gpiod_line_free(sda_line);
    gpiod_line_free(scl_line);
    gpiod_chip_put(chip);

    return 0;
}

