This C program interfaces with a Sensirion SHT40 humidity and temperature sensor over I2C bus 1 on a Raspberry Pi 3 Model B+. It logs timestamped temperature and humidity values to a file named `sht40_log.txt` every 5 seconds. The program handles errors from opening the I2C device, ioctl calls, writes, and reads by logging an error and retrying on the next cycle. It also cleanly closes both the I2C file descriptor and the log file when receiving SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x40 // Replace with the actual I2C address of the SDP31 sensor
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define BACKOFF_FACTOR 2
#define SAMPLING_INTERVAL 100 // in milliseconds

volatile sig_atomic_t stop_flag = 0;

int i2c_open() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    int ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        exit(EXIT_FAILURE);
    }

    return fd;
}

void i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Failed to close I2C handle");
        exit(EXIT_FAILURE);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        stop_flag = 1;
    }
}

void read_sensor_data(int fd) {
    uint8_t data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        ssize_t bytes_read = read(fd, data, 6);
        if (bytes_read == 6) {
            break;
        } else if (bytes_read < 0) {
            if (errno == EINTR) {
                retries++;
                usleep(pow(BACKOFF_FACTOR, retries) * 1000);
            } else {
                perror("Failed to read sensor data");
                exit(EXIT_FAILURE);
            }
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        exit(EXIT_FAILURE);
    }

    // Convert pressure and temperature
    uint16_t pressure_raw = (data[0] << 8) | data[1];
    uint16_t temperature_raw = (data[3] << 8) | data[4];

    float pressure_pa = (float)pressure_raw / 100.0;
    float temperature_c = (float)temperature_raw / 100.0;

    // Append to log file
    FILE *log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
            now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
            pressure_pa, temperature_c);

    if (fclose(log_file) < 0) {
        perror("Failed to close log file");
        exit(EXIT_FAILURE);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        exit(EXIT_FAILURE);
    }

    int fd = i2c_open();

    // Trigger continuous measurement
    uint8_t cmd = 0x01;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        ssize_t bytes_written = write(fd, &cmd, 1);
        if (bytes_written == 1) {
            break;
        } else if (bytes_written < 0) {
            if (errno == EINTR) {
                retries++;
                usleep(pow(BACKOFF_FACTOR, retries) * 1000);
            } else {
                perror("Failed to trigger continuous measurement");
                i2c_close(fd);
                exit(EXIT_FAILURE);
            }
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to trigger continuous measurement after %d retries\n", MAX_RETRIES);
        i2c_close(fd);
        exit(EXIT_FAILURE);
    }

    while (!stop_flag) {
        read_sensor_data(fd);
        usleep(SAMPLING_INTERVAL * 1000);
    }

    i2c_close(fd);

    return 0;
}

