int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        exit(EXIT_FAILURE);
    }

    int fd = i2c_open();

    // Trigger continuous measurement
    uint8_t cmd = 0x01;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        ssize_t bytes_written = write(fd, &cmd, 1);
        if (bytes_written == 1) {
            break;
        } else if (bytes_written < 0) {
            if (errno == EINTR) {
                retries++;
                usleep(pow(BACKOFF_FACTOR, retries) * 1000);
            } else {
                perror("Failed to trigger continuous measurement");
                i2c_close(fd);
                exit(EXIT_FAILURE);
            }
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to trigger continuous measurement after %d retries\n", MAX_RETRIES);
        i2c_close(fd);
        exit(EXIT_FAILURE);
    }

    while (!stop_flag) {
        read_sensor_data(fd);
        usleep(SAMPLING_INTERVAL * 1000);
    }

    i2c_close(fd);

    return 0;
}
