#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define STS30_DEFAULT_ADDR 0x40
#define MEASUREMENT_CMD 0x00
#define MEASUREMENT_WAIT_MS 15
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG "error_log.txt"

int i2c_file_descriptor;

void handle_sigint(int signum) {
    printf("Received SIGINT, performing graceful shutdown...\n");
    close(i2c_file_descriptor);
    fclose(stdout);
    fclose(stderr);
    exit(0);
}

int i2c_write(uint8_t addr, uint8_t cmd) {
    int bytes_written;
    uint8_t buffer[1] = {cmd};

    bytes_written = write(i2c_file_descriptor, buffer, 1);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int i2c_read(uint8_t addr, uint8_t *buffer, int length) {
    int bytes_read;

    bytes_read = read(i2c_file_descriptor, buffer, length);
    if (bytes_read != length) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

uint8_t crc8_polynomial = 0x07;

uint8_t crc8_checksum(uint8_t *data, int length) {
    uint8_t crc = 0xFF;
    int i, j;

    for (i = 0; i < length; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ crc8_polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

int main() {
    struct sigaction sa;
    struct timespec ts;
    uint8_t buffer[3];
    uint8_t crc;
    FILE *log_file, *error_log;
    int i2c_result;

    i2c_file_descriptor = open(I2C_BUS, O_RDWR);
    if (i2c_file_descriptor < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, STS30_DEFAULT_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C device address: %s\n", strerror(errno));
        close(i2c_file_descriptor);
        return 1;
    }

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_file_descriptor);
        return 1;
    }

    error_log = fopen(ERROR_LOG, "a");
    if (!error_log) {
        fprintf(stderr, "Error opening error log file: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_file_descriptor);
        return 1;
    }

    while (1) {
        i2c_result = i2c_write(STS30_DEFAULT_ADDR, MEASUREMENT_CMD);
        if (i2c_result < 0) {
            fprintf(error_log, "Error writing measurement command: %s\n", strerror(errno));
            continue;
        }

        usleep(MEASUREMENT_WAIT_MS * 1000);

        i2c_result = i2c_read(STS30_DEFAULT_ADDR, buffer, 3);
        if (i2c_result < 0) {
            fprintf(error_log, "Error reading temperature data: %s\n", strerror(errno));
            continue;
        }

        crc = crc8_checksum(buffer, 2);
        if (crc != buffer[2]) {
            fprintf(error_log, "CRC mismatch: expected 0x%02X, got 0x%02X\n", buffer[2], crc);
            continue;
        }

        ts.tv_sec = time(NULL);
        ts.tv_nsec = 0;
        fprintf(log_file, "%s %02X%02X\n", ctime(&ts.tv_sec), buffer[0], buffer[1]);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    fclose(error_log);
    close(i2c_file_descriptor);

    return 0;
}

