#define MEAS_DELAY 8500 // 8.5 ms

// CRC-8 polynomial and initial value
#define CRC_POLY 0x31
#define CRC_INIT 0x00

// CRC-8 calculation function
uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read and validate data from SHT40
int read_and_validate(int fd) {
    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        fprintf(stderr, "Error reading data from SHT40\n");
        return -1;
    }

    uint8_t temp_crc = data[2];
    uint8_t rh_crc = data[5];

    uint8_t temp_crc_calc = crc8(data, 2);
    uint8_t rh_crc_calc = crc8(data + 3, 3);

    if (temp_crc != temp_crc_calc || rh_crc != rh_crc_calc) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Temperature and humidity values are in 16-bit format
    int16_t temp = (data[0] << 8) | data[1];
    int16_t rh = (data[3] << 8) | data[4];

    // Log the temperature and humidity
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
    fprintf(stderr, "%s: Temperature: %d, Humidity: %d\n", timestamp, temp, rh);

    return 0;
}

int main() {
    int fd;
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    int log_fd;
    if ((log_fd = open("sht40_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    while (1) {
        if (write(fd, &MEAS_CMD, 1) != 1) {
            perror("Failed to write measurement command");
            continue;
        }

        usleep(MEAS_DELAY);

        if (read_and_validate(fd) < 0) {
            continue;
        }

        sleep(5); // Wait 5 seconds before next measurement
    }

    // Cleanup
    close(log_fd);
    close(fd);

    return 0;
}

