#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_ADDR 0x40 // Replace with the actual I2C address of the SDP800-500Pa sensor
#define CMD_CONT_MEAS 0x00 // Command for continuous measurement
#define CMD_PRESSURE_TEMP 0x01 // Command to read pressure and temperature
#define CMD_PRESSURE 0x02 // Command to read pressure only
#define CMD_TEMPERATURE 0x03 // Command to read temperature only
#define CMD_STATUS 0x04 // Command to read status

#define PRESSURE_MSB 0
#define PRESSURE_LSB 2
#define PRESSURE_CRC 4
#define TEMP_MSB 5
#define TEMP_LSB 7
#define TEMP_CRC 9

#define POLYNOMIAL 0x07 // CRC-8 polynomial
#define INIT_VALUE 0x00 // Initial value for CRC-8

int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    return fd;
}

int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Failed to close I2C device");
        return -1;
    }
    return 0;
}

int i2c_write(int fd, uint8_t addr, uint8_t cmd) {
    int ret = write(fd, &cmd, 1);
    if (ret < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t addr, uint8_t *data, size_t len) {
    int ret = read(fd, data, len);
    if (ret < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = INIT_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int fd = i2c_open("/dev/i2c-1");
    if (fd < 0) {
        return 1;
    }

    uint8_t cmd = CMD_CONT_MEAS;
    if (i2c_write(fd, I2C_ADDR, cmd) < 0) {
        i2c_close(fd);
        return 1;
    }

    FILE *file = fopen("airflow_data.txt", "a");
    if (!file) {
        perror("Failed to open file");
        i2c_close(fd);
        return 1;
    }

    while (1) {
        uint8_t data[10];
        if (i2c_read(fd, I2C_ADDR, data, sizeof(data)) < 0) {
            fclose(file);
            i2c_close(fd);
            return 1;
        }

        uint16_t pressure_raw = (data[PRESSURE_MSB] << 8) | data[PRESSURE_LSB];
        uint16_t temp_raw = (data[TEMP_MSB] << 8) | data[TEMP_LSB];

        uint8_t pressure_crc = crc8(&data[PRESSURE_MSB], 2);
        uint8_t temp_crc = crc8(&data[TEMP_MSB], 2);

        if (pressure_crc != data[PRESSURE_CRC] || temp_crc != data[TEMP_CRC]) {
            fprintf(file, "CRC error\n");
            continue;
        }

        double pressure = (double)pressure_raw / 1000.0; // Assuming 1000 counts per pascal
        double temperature = (double)temp_raw / 100.0; // Assuming 100 counts per degree Celsius

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);

        usleep(1000); // Wait 1 ms before next read
    }

    fclose(file);
    i2c_close(fd);
    return 0;
}

