#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SI7021_ADDR 0x40
#define TEMP_REG 0xE3
#define HUMID_REG 0xE5
#define BUFFER_SIZE 60
#define FAN_GPIO 18
#define FAN_ON_TEMP 28.0
#define FAN_OFF_TEMP 27.0

typedef struct {
    float temperature;
    time_t timestamp;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int fan_state = 0;

void handle_sigint(int signum) {
    if (fan_state) {
        gpiod_line_set_value(fan_line, 0);
        fan_state = 0;
    }
    i2c_close(i2c_handle);
    pigpio_stop();
    exit(0);
}

int read_temperature(void) {
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        result = i2c_read_byte_data(i2c_handle, TEMP_REG);
        if (result != -1) {
            break;
        }
        retries--;
        usleep(10000); // 10 ms delay
    }

    if (result == -1) {
        printf("Failed to read temperature after 3 retries.\n");
        return -1;
    }

    return result;
}

void update_buffer(float temperature, time_t timestamp) {
    buffer[buffer_head].temperature = temperature;
    buffer[buffer_head].timestamp = timestamp;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    if (buffer_head == buffer_tail) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }
}

void print_buffer() {
    for (int i = buffer_tail; i != buffer_head; i = (i + 1) % BUFFER_SIZE) {
        printf("Temperature: %.2f°C, Timestamp: %s\n", buffer[i].temperature, ctime(&buffer[i].timestamp));
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    gpiod_line *fan_line = gpiod_line_request(FAN_GPIO, "Fan Control", 0, 0, 0);
    if (!fan_line) {
        fprintf(stderr, "Failed to request GPIO line for fan control.\n");
        return 1;
    }

    int i2c_handle = i2c_open(1, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        return 1;
    }

    while (1) {
        int temperature_value = read_temperature();
        if (temperature_value == -1) {
            continue;
        }

        float temperature = (temperature_value >> 4) * 0.0625;
        time_t timestamp = time(NULL);

        update_buffer(temperature, timestamp);
        printf("Temperature: %.2f°C, Timestamp: %s\n", temperature, ctime(&timestamp));

        if (temperature > FAN_ON_TEMP && fan_state == 0) {
            gpiod_line_set_value(fan_line, 1);
            fan_state = 1;
        } else if (temperature < FAN_OFF_TEMP && fan_state == 1) {
            gpiod_line_set_value(fan_line, 0);
            fan_state = 0;
        }

        sleep(2);
    }

    gpiod_line_free(fan_line);
    i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

