#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SCD40_ADDR 0x40
#define SCD40_CMD_START_MEASUREMENT 0x01
#define SCD40_CMD_STOP_MEASUREMENT 0x00
#define SCD40_CMD_READ_DATA 0x04
#define SCD40_CMD_CRC_INIT 0x00
#define SCD40_CMD_CRC_POLYNOMIAL 0x07

#define SCD40_DATA_LENGTH 9
#define SCD40_DATA_OFFSET 1

#define SCD40_CO2_OFFSET 0
#define SCD40_TEMP_OFFSET 2
#define SCD40_HUMIDITY_OFFSET 4

#define SCD40_CRC_OFFSET 6

#define SCD40_CRC_POLYNOMIAL 0x07

#define SCD40_RETRY_COUNT 3

static int i2c_fd;
static struct gpiod_line *light_pin;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        int ret = i2c_smbus_write_byte_data(i2c_fd, SCD40_ADDR, SCD40_CMD_STOP_MEASUREMENT);
        if (ret < 0) {
            fprintf(stderr, "Failed to stop measurement: %s\n", strerror(errno));
        }
        close(i2c_fd);
    }

    if (light_pin) {
