#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define BUFFER_SIZE 20
#define LED_PIN 17
#define CO2_THRESHOLD 1000

struct sensor_reading {
    int co2;
    float temperature;
    float humidity;
};

struct sensor_reading readings[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void handle_signal(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    close(i2c_file);
    gpiod_release(led_pin);
    gpiod_close(i2c_file);
    exit(0);
}

int validate_crc8(uint8_t data[2], uint8_t crc) {
    uint8_t calculated_crc = 0;
    for (int i = 0; i < 2; i++) {
        calculated_crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (calculated_crc & 0x80) {
                calculated_crc = (calculated_crc << 1) ^ 0x07;
            } else {
                calculated_crc <<= 1;
            }
        }
    }
    return crc == calculated_crc;
}

int read_sensor_data() {
    uint8_t data[3];
    int bytes_read = read(i2c_file, data, 3);
    if (bytes_read != 3) {
        perror("Error reading from I2C bus");
        return -1;
    }

    if (!validate_crc8(data, data[2])) {
        printf("CRC-8 check failed\n");
        return -1;
    }

    struct sensor_reading reading;
    reading.co2 = (data[0] << 8) | data[1];
    reading.temperature = (float)data[1] / 10.0;
    reading.humidity = (float)data[2] / 10.0;

    readings[buffer_head] = reading;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    printf("CO2: %d ppm, Temperature: %.1f°C, Humidity: %.1f%%\n", reading.co2, reading.temperature, reading.humidity);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        return 1;
    }

    gpiod_chip *chip = gpiod_chip_open_by_name("pigpiod");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    gpiod_line *led_pin_line = gpiod_line_request_any(chip, "LED", LED_PIN, 0, 0, 0);
    if (!led_pin_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line *led_pin = gpiod_line_get_line(led_pin_line);
    if (!led_pin) {
        perror("Failed to get GPIO line");
        gpiod_line_release(led_pin_line);
        gpiod_chip_close(chip);
        return 1;
    }

    int i2c_file = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(led_pin_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_file);
        gpiod_line_release(led_pin_line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (read_sensor_data() < 0) {
            continue;
        }

        if (readings[buffer_tail].co2 > CO2_THRESHOLD) {
            gpiod_line_set_value(led_pin, 1);
        } else {
            gpiod_line_set_value(led_pin, 0);
        }

        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        sleep(5);
    }

    return 0;
}

