#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define SAMPLING_INTERVAL 5000000 // 5 seconds in microseconds
#define TIMEOUT 50000 // 50 ms timeout in microseconds

gpiod_chip *chip;
gpiod_line *line;
FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_put(line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum == SIGINT ? 0 : 1);
}

double calculate_temperature(uint64_t high_time, uint64_t low_time) {
    if (low_time == 0) {
        return 0.0; // Guard against division by zero
    }
    double duty_cycle = (double)high_time / (high_time + low_time);
    double temperature = (duty_cycle * 190.0) - 40.0; // TMP05 formula
    if (temperature < -40.0 || temperature > 150.0) {
        return -1.0; // Flag as error
    }
    return temperature;
}

int main() {
    struct timespec start_time, end_time;
    uint64_t high_time = 0, low_time = 0;
    int consecutive_errors = 0;

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request_any(chip, GPIO_PIN, "TMP05_sensor", &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    if ((log_file = fopen("temperature_log.txt", "a")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        gpiod_line_set_edge(line, GPIO_LINE_BOTH_EDGES);

        if (gpiod_line_get_value(line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (gpiod_line_get_value(line) == 1) {
                clock_gettime(CLOCK_MONOTONIC, &end_time);
                if (end_time.tv_sec - start_time.tv_sec > TIMEOUT / 1000000) {
                    break;
                }
            }
            high_time = (end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000;
        }

        if (gpiod_line_get_value(line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (gpiod_line_get_value(line) == 0) {
                clock_gettime(CLOCK_MONOTONIC, &end_time);
                if (end_time.tv_sec - start_time.tv_sec > TIMEOUT / 1000000) {
                    break;
                }
            }
            low_time = (end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000;
        }

        double temperature = calculate_temperature(high_time, low_time);

        if (temperature == -1.0) {
            consecutive_errors++;
            if (consecutive_errors >= 3) {
                fprintf(log_file, "%s: SENSOR MALFUNCTION\n", ctime(&time(NULL)));
                consecutive_errors = 0;
            }
        } else {
            consecutive_errors = 0;
            fprintf(log_file, "%s: %.2f\n", ctime(&time(NULL)), temperature);
        }

        usleep(SAMPLING_INTERVAL);
    }

    fclose(log_file);
    gpiod_line_put(line);
    gpiod_chip_put(chip);

    return 0;
}

