            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (gpiod_line_get_value(line) == 0) {
                clock_gettime(CLOCK_MONOTONIC, &end_time);
                if (end_time.tv_sec - start_time.tv_sec > TIMEOUT / 1000000) {
                    break;
                }
            }
            low_time = (end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000;
        }

        double temperature = calculate_temperature(high_time, low_time);

        if (temperature == -1.0) {
            consecutive_errors++;
            if (consecutive_errors >= 3) {
                fprintf(log_file, "%s: SENSOR MALFUNCTION\n", ctime(&time(NULL)));
                consecutive_errors = 0;
            }
        } else {
            consecutive_errors = 0;
            fprintf(log_file, "%s: %.2f\n", ctime(&time(NULL)), temperature);
        }

        usleep(SAMPLING_INTERVAL);
    }

    fclose(log_file);
    gpiod_line_put(line);
    gpiod_chip_put(chip);

    return 0;
}
```

This C program reads temperature from an Analog Devices TMP05 digital temperature sensor by polling its PWM-style output on GPIO4 (BCM, physical pin 7). It measures the high-pulse width and total cycle width with a busy-wait loop using microsecond-resolution timestamps obtained from the `clock_gettime()` API. The program samples once every 5 seconds and applies a 50 ms timeout on each edge wait. It verifies that the driver library initializes correctly and that the log file "temperature_log.txt" opens in append mode. It computes the temperature while guarding against division by zero if the low-time (TL) is zero, flags any reading outside the valid range of –40 °C to +150 °C as an error, and after three consecutive failures writes a "SENSOR MALFUNCTION" entry to the log. It also logs each valid reading together with an ISO-8601 timestamp. The program handles SIGINT and SIGTERM to perform a clean shutdown by closing the file and releasing the driver library resources.

