#define SHT35_MEAS_CMD 0xF3
#define SHT35_MEAS_DELAY 15000 // 15 ms
#define SHT35_DATA_LEN 6
#define SHT35_TEMP_OFFSET 2
#define SHT35_HUMIDITY_OFFSET 5
#define SHT35_CRC_LEN 2
#define SHT35_RETRY_COUNT 3
#define SHT35_RETRY_DELAY 1000 // 1 second
#define SHT35_LOG_FILE "environmental_data.txt"

// CRC-8 lookup table
static const uint8_t crc8_table[256] = {
    // ... (CRC-8 lookup table values)
};

// Function to calculate CRC-8
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc = crc8_table[(crc ^ data[i]) & 0xFF];
    }
    return crc;
}

// Function to read SHT35 data
int read_sht35_data(uint8_t *data) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT35_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    int retries = 0;
    while (retries < SHT35_RETRY_COUNT) {
        if (write(i2c_fd, &SHT35_MEAS_CMD, 1) != 1) {
            perror("Failed to write measurement command");
            close(i2c_fd);
            return -1;
        }

        usleep(SHT35_MEAS_DELAY);

        if (read(i2c_fd, data, SHT35_DATA_LEN) != SHT35_DATA_LEN) {
            perror("Failed to read data");
            retries++;
            usleep(SHT35_RETRY_DELAY);
            continue;
        }

        uint8_t calculated_crc = calculate_crc8(data, SHT35_DATA_LEN - SHT35_CRC_LEN);
        if (calculated_crc != data[SHT35_DATA_LEN - 1]) {
            perror("CRC check failed");
            retries++;
            usleep(SHT35_RETRY_DELAY);
            continue;
        }

        close(i2c_fd);
        return 0;
    }

    close(i2c_fd);
    return -1;
}

// Function to convert raw data to temperature and humidity
void convert_data(const uint8_t *data, float *temperature, float *humidity) {
    uint16_t temp_raw = (data[SHT35_TEMP_OFFSET] << 8) | data[SHT35_TEMP_OFFSET + 1];
    uint16_t hum_raw = (data[SHT35_HUMIDITY_OFFSET] << 8) | data[SHT35_HUMIDITY_OFFSET + 1];

    *temperature = (float)temp_raw / 100.0;
    *humidity = (float)hum_raw / 100.0;
}

// Function to add sinusoidal offset
void add_sinusoidal_offset(float *temperature, float *humidity) {
    const float amplitude_temp = 2.0;
    const float amplitude_humidity = 5.0;
    const float period = 3600.0; // 1 hour
    const float time_now = (float)time(NULL);

    *temperature += amplitude_temp * sin(2 * M_PI * time_now / period);
    *humidity += amplitude_humidity * sin(2 * M_PI * time_now / period);
}

// Function to log data
void log_data(const char *timestamp, float temperature, float humidity) {
    FILE *log_file = fopen(SHT35_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, humidity);
    fclose(log_file);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);

    // Close I2C handle
    close(i2c_fd);

    // Flush and close log file
    FILE *log_file = fopen(SHT35_LOG_FILE, "a");
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate driver cleanly
    gpiod_release_all();

    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return 1;
    }

    uint8_t data[SHT35_DATA_LEN];
    float temperature, humidity;

    while (1) {
        if (read_sht35_data(data) == 0) {
            convert_data(data, &temperature, &humidity);
            add_sinusoidal_offset(&temperature, &humidity);

            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[32];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            log_data(timestamp, temperature, humidity);
        } else {
            log_data(NULL, NAN, NAN);
        }

        sleep(5);
    }

    return 0;
}

