#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDR 0x40
#define CMD_CONT_MEAS 0x00
#define CONV_TIME 45 // in milliseconds
#define DATA_SIZE 9
#define CRC_POLY 0x07
#define CRC_INIT 0x00

int i2c_fd;

// Function to calculate CRC-8
uint8_t calculate_crc(uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(uint8_t *data) {
    int bytes_read = 0;
    while (bytes_read < DATA_SIZE) {
        int result = read(i2c_fd, data + bytes_read, DATA_SIZE - bytes_read);
        if (result < 0) {
            perror("Error reading from I2C bus");
            return -1;
        }
        bytes_read += result;
    }
    return 0;
}

// Function to validate CRCs
int validate_crcs(uint8_t *data) {
    for (int i = 0; i < 3; i++) {
        uint8_t calculated_crc = calculate_crc(data + (i * 9), 8);
        if (calculated_crc != data[i * 9 + 8]) {
            return -1;
        }
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
void convert_data(uint8_t *data, float *pressure, float *temperature) {
    int16_t pressure_raw = (data[0] << 8) | data[1];
    int16_t temperature_raw = (data[2] << 8) | data[3];
    float scale_factor = (data[4] << 8) | data[5];

    *pressure = (pressure_raw * 100.0) / scale_factor;
    *temperature = (temperature_raw * 100.0) / 256.0;
}

int main() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    FILE *file = fopen("airflow.csv", "w");
    if (!file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    uint8_t data[DATA_SIZE];
    while (1) {
        write(i2c_fd, &CMD_CONT_MEAS, 1);
        usleep(CONV_TIME * 1000);

        if (read_sensor_data(data) < 0 || validate_crcs(data) < 0) {
            fprintf(stderr, "Sensor data error\n");
            continue;
        }

        float pressure, temperature;
        convert_data(data, &pressure, &temperature);

        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
                pressure, temperature);

        fflush(file);
        usleep(1000000); // Sleep for 1 second
    }

    fclose(file);
    close(i2c_fd);
    return 0;
}

