#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define SHT35_ADDR 0x44
#define SHT35_MEAS_CMD 0xF3
#define SHT35_MEAS_WAIT 15
#define SHT35_DATA_LEN 6
#define SHT35_CRC_POLY 0x31
#define SHT35_CRC_INIT 0x00

#define FILE_NAME "environment.csv"

static int i2c_handle = -1;
static FILE *file = NULL;

void handle_signal(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (file != NULL) {
        fclose(file);
    }
    exit(signum);
}

int read_sensor() {
    uint8_t cmd = SHT35_MEAS_CMD;
    uint8_t data[SHT35_DATA_LEN];
    uint8_t crc;
    uint8_t calculated_crc;

    // Send measurement command
    if (i2c_write(i2c_handle, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to write measurement command to sensor.\n");
        return -1;
    }

    // Wait for measurement to complete
    usleep(SHT35_MEAS_WAIT * 1000);

    // Read data
    if (i2c_read(i2c_handle, data, SHT35_DATA_LEN) != SHT35_DATA_LEN) {
        fprintf(stderr, "Failed to read data from sensor.\n");
        return -1;
    }

    // Calculate CRC-8
    calculated_crc = 0;
    for (int i = 0; i < SHT35_DATA_LEN - 1; i++) {
        calculated_crc = (calculated_crc << 1) ^ ((calculated_crc & 0x80) ? SHT35_CRC_POLY : 0);
        calculated_crc ^= data[i];
    }

    // Validate CRC
    crc = data[SHT35_DATA_LEN - 1];
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1;
    }

    // Process data
    int16_t temperature = (data[0] << 8) | data[1];
    int16_t humidity = (data[2] << 8) | data[3];

    // Log data
    fprintf(file, "%s,%d,%d\n", ctime(&time(NULL)), temperature / 10, humidity / 10);

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install signal handler");
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2c_open(1, SHT35_ADDR, 0);
    if (i2c_handle == -1) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open file
    file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("Failed to open file");
        i2c_close(i2c_handle);
        return 1;
    }

    // Check if file is empty or doesn't have a header
    if (fseek(file, 0, SEEK_END) == 0 && ftell(file) == 0) {
        fprintf(file, "Timestamp,Temperature (C),Humidity (%)\n");
    }

    // Main loop
    while (1) {
        if (read_sensor() == -1) {
            break;
        }
        sleep(5);
    }

    // Cleanup
    fclose(file);
    i2c_close(i2c_handle);

    return 0;
}

