#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define TIMEOUT_MS 100
#define LOG_INTERVAL_S 5
#define CRC_POLYNOMIAL 0x07
#define CRC_INITIAL 0x00

int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_sensor(uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[len + 1];
    int ret;

    buf[0] = reg;
    ret = write(i2c_fd, buf, len + 1);
    if (ret != len + 1) {
        perror("write");
        return -1;
    }

    ret = read(i2c_fd, buf, len + 1);
    if (ret != len + 1) {
        perror("read");
        return -1;
    }

    if (buf[0] != 0x40) {
        fprintf(stderr, "NACK received\n");
        return -1;
    }

    memcpy(data, buf + 1, len);
    return 0;
}

uint8_t calculate_crc(uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen("environment.log", "w");
    if (!log_file) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");

    while (1) {
        uint8_t temp_data[3], hum_data[3];
        uint8_t temp_crc, hum_crc;
        time_t now;
        struct tm *tm_info;

        if (read_sensor(0xF3, temp_data, 3) < 0) {
            fprintf(stderr, "ERROR: Temperature read failed\n");
            continue;
        }

        temp_crc = calculate_crc(temp_data, 2);
        if (temp_crc != temp_data[2]) {
            fprintf(stderr, "ERROR: Temperature CRC check failed\n");
            continue;
        }

        if (read_sensor(0xF5, hum_data, 3) < 0) {
            fprintf(stderr, "ERROR: Humidity read failed\n");
            continue;
        }

        hum_crc = calculate_crc(hum_data, 2);
        if (hum_crc != hum_data[2]) {
            fprintf(stderr, "ERROR: Humidity CRC check failed\n");
            continue;
        }

        now = time(NULL);
        tm_info = localtime(&now);

        fprintf(log_file, "%s,%d,%d\n", asctime(tm_info), (temp_data[0] << 8) | temp_data[1], (hum_data[0] << 8) | hum_data[1]);

        sleep(LOG_INTERVAL_S);
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

