        perror("Failed to acquire I2C device");
        close(i2c_fd);
        return 1;
    }

    if (write(i2c_fd, &CMD_INIT, 1) != 1) {
        perror("Failed to write initialization command");
        close(i2c_fd);
        return 1;
    }

    file_fd = fopen(FILE_NAME, "wb");
