        perror("Failed to open file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint8_t data[PRESSURE_TEMP_DATA_SIZE];
        if (write(i2c_fd, &CMD_CONT, 1) != 1) {
            perror("Failed to write continuous measurement command");
            break;
        }

        if (read(i2c_fd, data, PRESSURE_TEMP_DATA_SIZE) != PRESSURE_TEMP_DATA_SIZE) {
            perror("Failed to read pressure and temperature data");
            break;
