        usleep(PRESSURE_TEMP_CONVERSION_TIME);

        uint8_t pressure_crc = data[2];
        uint8_t temp_crc = data[5];

        uint16_t pressure_raw = (data[0] << 8) | data[1];
        uint16_t temp_raw = (data[3] << 8) | data[4];

        uint8_t pressure_calculated_crc = 0;
        uint8_t temp_calculated_crc = 0;

        for (int i = 0; i < 2; i++) {
            pressure_calculated_crc ^= data[i];
            temp_calculated_crc ^= data[i + 3];
        }

        if (pressure_calculated_crc != pressure_crc || temp_calculated_crc != temp_crc) {
            fprintf(stderr, "CRC error\n");
            break;
        }

        float pressure = (float)pressure_raw / 1000.0;
        float temperature = (float)temp_raw / 1000.0;

        if (fwrite(&pressure, sizeof(float), 1, file_fd) != 1 ||
            fwrite(&temperature, sizeof(float), 1, file_fd) != 1) {
            perror("Failed to write data to file");
            break;
        }

        sleep(1);
    }

    fclose(file_fd);
    close(i2c_fd);

    return 0;
}

