This C program reads differential pressure and temperature from a Sensirion SDP810-500Pa sensor on I2C bus 1, validates the CRC-8 for both pressure and temperature raw values, converts the raw data to floating-point pressure (Pa) and temperature (°C), and logs each sample once per second to a binary file named `airflow.dat`. It checks driver initialization, I2C opening, command write and read results, handles sensor-absent and bus-error conditions, and implements signal handling for SIGINT and SIGTERM to perform a graceful shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define CONVERSION_TIME 45 // in milliseconds
#define LOG_FILE "pressure_log.txt"

// CRC-8 polynomial
#define POLYNOMIAL 0x07

// Function to calculate CRC-8
uint8_t calculate_crc8(uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read 9 bytes from the sensor
int read_pressure(uint8_t *buffer) {
    int fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (fd < 0) {
        perror("i2c_open");
        return -1;
    }

    // Send continuous measurement command
    if (i2c_write_device(fd, "\x00", 1) < 0) {
        perror("i2c_write_device");
        i2c_close(fd);
        return -1;
    }

    // Wait for conversion time
    usleep(CONVERSION_TIME * 1000);

    // Read 9 bytes
    if (i2c_read_device(fd, buffer, 9) != 9) {
        perror("i2c_read_device");
        i2c_close(fd);
        return -1;
    }

    i2c_close(fd);
    return 0;
}

// Function to validate CRC-8
int validate_crc8(uint8_t *data, size_t length) {
    uint8_t calculated_crc = calculate_crc8(data, length - 1);
    uint8_t received_crc = data[length - 1];
    return calculated_crc == received_crc;
}

// Function to log pressure reading
void log_pressure(uint8_t *buffer) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    struct tm *time_info;
    time_t raw_time;
    time(&raw_time);
    time_info = localtime(&raw_time);

    fprintf(log_file, "%02d:%02d:%02d ", time_info->tm_hour, time_info->tm_min, time_info->tm_sec);

    uint32_t pressure = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
    fprintf(log_file, "%u Pa\n", pressure);

    fclose(log_file);
}

// Signal handler
void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);

    // Close I2C handle
    int fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (fd >= 0) {
        i2c_close(fd);
    }

    // Close log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t buffer[9];

    while (1) {
        if (read_pressure(buffer) < 0) {
            printf("Failed to read pressure data.\n");
            continue;
        }

        if (!validate_crc8(buffer, 9)) {
            printf("CRC-8 validation failed.\n");
            continue;
        }

        log_pressure(buffer);

        sleep(5); // Wait 5 seconds before next reading
    }

    return 0;
}

