#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x38
#define LOG_FILE "environmental_data.txt"

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int read_pressure_temperature(FILE *log_file) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    int ret;

    // Initialize I2C
    chip = gpiod_chip_open_by_name("i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    // Request I2C line
    line = gpiod_line_request_by_name(chip, "i2c-1", &flags, "LPS33HW");
    if (!line) {
        fprintf(stderr, "Failed to request I2C line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    // Read pressure and temperature
    uint8_t data[2];
    ret = gpiod_line_write(line, &I2C_ADDR, 1, data, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read pressure and temperature\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Log data
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];
    time(&rawtime);
    timeinfo = localtime_r(&rawtime, timeinfo);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, Pressure: %d.%d hPa, Temperature: %d.%d °C\n", buffer, data[0], data[1], data[2], data[3]);
    fflush(log_file);

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

int main() {
    FILE *log_file;
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (!stop_flag) {
        if (read_pressure_temperature(log_file) < 0) {
            continue;
        }
        sleep(1);
    }

    // Cleanup
    fclose(log_file);
    return 0;
}

