#define BUFFER_SIZE 10
#define LED_PIN 17 // GPIO17 (BCM)
#define AVG_THRESHOLD 28.0

static struct gpiod_line *led_line;
static int i2c_handle;
static float buffer[BUFFER_SIZE];
static int buffer_index = 0;

void cleanup() {
    if (led_line) {
        gpiod_line_free(led_line);
        led_line = NULL;
    }
    if (i2c_handle >= 0) {
        close(i2c_handle);
        i2c_handle = -1;
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(signum == SIGINT ? 0 : 1);
}

float read_temperature() {
    uint8_t data[2];
    int bytes_read;

    bytes_read = i2c_smbus_read_i2c_block_data(i2c_handle, I2C_ADDR, 0, data, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read temperature from STLM75\n");
        return 0.0;
    }

    float temperature = (data[0] << 8) | data[1];
    temperature /= 16.0; // Convert to °C

    return temperature;
}

void update_average(float temperature) {
    buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }

    float average = sum / BUFFER_SIZE;

    if (average > AVG_THRESHOLD) {
        gpiod_line_set_value(led_line, 1);
    } else {
        gpiod_line_set_value(led_line, 0);
    }
}

