#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_ADDR 0x40
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define SAMPLING_INTERVAL 5000 // 5 seconds

// Function prototypes
void handle_signal(int signum);
void write_log_entry(const char *timestamp, int co2, int temperature, int humidity);
int read_sensor_data(int *co2, int *temperature, int *humidity);

int main() {
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int co2, temperature, humidity;
    int i2c_handle = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_handle < 0) {
        perror("Failed to open I2C bus");
        fclose(log_file);
        return 1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_handle);
        fclose(log_file);
        return 1;
    }

    while (1) {
        if (read_sensor_data(&co2, &temperature, &humidity) < 0) {
            fprintf(log_file, "Error reading sensor data\n");
            continue;
        }

        char timestamp[20];
        time_t now = time(NULL);
        struct tm *now_tm = gmtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", now_tm);

        write_log_entry(timestamp, co2, temperature, humidity);

        if (co2 < 800) {
            printf("Ventilation: OFF\n");
        } else if (co2 < 1200) {
            printf("Ventilation: LOW\n");
        } else {
            printf("Ventilation: HIGH\n");
        }

        sleep(SAMPLING_INTERVAL / 1000);
    }

    close(i2c_handle);
    fclose(log_file);
    return 0;
}

void handle_signal(int signum) {
    printf("Received signal %d, stopping measurement\n", signum);
    close(i2c_handle);
    fclose(log_file);
    exit(0);
}

void write_log_entry(const char *timestamp, int co2, int temperature, int humidity) {
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

int read_sensor_data(int *co2, int *temperature, int *humidity) {
    uint8_t buffer[3];
