static void cleanup(int signum) {
    gpiod_release(i2c_dev);
    exit(signum == SIGINT || signum == SIGTERM ? 0 : 1);
}

static int read_sensor(void) {
    int ret;
    uint8_t data[9];

    ret = gpiod_i2c_read(i2c_dev, I2C_ADDR, 0x00, data, 9);
    if (ret < 0) {
        fprintf(stderr, "Error reading sensor: %s\n", gpiod_strerror(ret));
        return -1;
    }

    // Verify CRC-8 for pressure, temperature, and scale-factor words
    uint8_t pressure_crc = data[2];
    uint8_t temp_crc = data[5];
    uint8_t scale_factor_crc = data[8];

    uint16_t pressure = (data[0] << 8) | data[1];
    uint16_t temperature = (data[3] << 8) | data[4];
    uint16_t scale_factor = (data[6] << 8) | data[7];

    uint8_t calc_pressure_crc = 0;
    uint8_t calc_temp_crc = 0;
    uint8_t calc_scale_factor_crc = 0;

    for (int i = 0; i < 2; i++) {
        calc_pressure_crc ^= pressure & 0xFF;
        pressure >>= 8;
    }

    for (int i = 0; i < 2; i++) {
        calc_temp_crc ^= temperature & 0xFF;
        temperature >>= 8;
    }

    for (int i = 0; i < 2; i++) {
        calc_scale_factor_crc ^= scale_factor & 0xFF;
        scale_factor >>= 8;
    }

    if (pressure_crc != calc_pressure_crc || temp_crc != calc_temp_crc || scale_factor_crc != calc_scale_factor_crc) {
        fprintf(stderr, "CRC-8 verification failed.\n");
        return -1;
    }

    // Print the reading with a timestamp
    printf("Timestamp: %ld, Pressure: %d, Temperature: %d, Scale-Factor: %d\n", (long)time(NULL), pressure, temperature, scale_factor);

    return 0;
}

