    struct gpiod_i2c_device *i2c_dev;
    int ret = gpiod_i2c_open("/dev/i2c-1", &i2c_dev);
    if (ret < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", gpiod_strerror(ret));
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        if (read_sensor() < 0) {
            cleanup(0);
        }
        sleep(interval / 1000);
    }

    return 0;
}

