#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libi2c.h>

#define SDP810_I2C_ADDR 0x40
#define SDP810_REG_PRESSURE 0x00
#define SDP810_REG_TEMPERATURE 0x04
#define SDP810_REG_CRC 0x08
#define SDP810_REG_STATUS 0x0A

#define SDP810_CMD_READ 0x80
#define SDP810_CMD_WRITE 0x00

#define SDP810_POLYNOMIAL 0x31
#define SDP810_INITIAL_VALUE 0x00

static int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        i2c_close(i2c_fd);
    }
    exit(signum);
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SDP810_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data() {
    uint8_t data[9];
    int bytes_read = i2c_read_device(i2c_fd, SDP810_I2C_ADDR, SDP810_REG_PRESSURE, data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Failed to read sensor data: %d bytes read\n", bytes_read);
        return -1;
    }

    uint8_t crc_pressure = calculate_crc8(data, 3);
    uint8_t crc_temperature = calculate_crc8(data + 3, 3);
    uint8_t crc_status = calculate_crc8(data + 6, 3);

    if (crc_pressure != data[2] || crc_temperature != data[5] || crc_status != data[8]) {
        fprintf(stderr, "CRC mismatch detected\n");
        return -1;
    }

    // Log the results to stdout
    printf("Pressure: %d, Temperature: %d\n", data[0], data[3]);

    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = i2c_open(1, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    while (1) {
        if (read_sensor_data() < 0) {
            break;
        }
        usleep(1000000); // Sleep for 1 second
    }

    i2c_close(i2c_fd);
    return 0;
}

