#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_TEMP_CMD 0x00
#define I2C_HUMIDITY_CMD 0x01
#define I2C_DATA_REG 0x00
#define I2C_DATA_LEN 2
#define I2C_DELAY_MS 20
#define LOG_INTERVAL_S 5

static int i2c_fd = -1;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_sensor_data(int *temperature, int *humidity) {
    int ret;
    char data[I2C_DATA_LEN];

    // Start conversion
    ret = write(i2c_fd, &I2C_TEMP_CMD, 1);
    if (ret != 1) {
        perror("Failed to write temperature command");
        return -1;
    }

    ret = write(i2c_fd, &I2C_HUMIDITY_CMD, 1);
    if (ret != 1) {
        perror("Failed to write humidity command");
        return -1;
    }

    // Wait for conversion
    usleep(I2C_DELAY_MS * 1000);

    // Read temperature and humidity
    ret = read(i2c_fd, data, I2C_DATA_LEN);
    if (ret != I2C_DATA_LEN) {
        perror("Failed to read sensor data");
        return -1;
    }

    *temperature = (data[0] << 8) | data[1];
    *humidity = (data[2] << 8) | data[3];

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sda, *scl;
    int ret;

    // Initialize I2C
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize GPIO lines
    chip = gpiod_chip_open("/dev/gpiomem");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    sda = gpiod_line_request(chip, "2", "sda", GPIOD_LINE_DIRECTION_OUT_ALT0);
    if (!sda) {
        perror("Failed to request SDA line");
        gpiod_chip_put(chip);
        close(i2c_fd);
        return 1;
    }

    scl = gpiod_line_request(chip, "3", "scl", GPIOD_LINE_DIRECTION_OUT_ALT0);
    if (!scl) {
        perror("Failed to request SCL line");
        gpiod_line_free(sda);
        gpiod_chip_put(chip);
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        int temperature, humidity;

        if (read_sensor_data(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   (float)temperature / 100.0, (float)humidity / 100.0);
        }

        sleep(LOG_INTERVAL_S);
    }

    // Cleanup
    gpiod_line_free(scl);
    gpiod_line_free(sda);
    gpiod_chip_put(chip);
    close(i2c_fd);

    return 0;
}

