#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define MLX90833_I2C_ADDR 0x77
#define MLX90833_PRESSURE_REG 0x00
#define MLX90833_PRESSURE_LSB 0x01
#define MLX90833_PRESSURE_MSB 0x02

static struct gpiod_chip *i2c_chip;
static struct gpiod_line *sda_line, *scl_line;

static void cleanup(int signum) {
    if (sda_line) {
        gpiod_line_free(sda_line);
    }
    if (scl_line) {
        gpiod_line_free(scl_line);
    }
    if (i2c_chip) {
        gpiod_chip_put(i2c_chip);
    }
    exit(signum == SIGINT ? 0 : 1);
}

static int read_pressure(void) {
    int result = 0;
    uint8_t lsb, msb;

    // Read the least significant byte (LSB)
    if (i2c_smbus_read_byte_data(MLX90833_I2C_ADDR, MLX90833_PRESSURE_LSB, &lsb) < 0) {
        perror("Failed to read pressure LSB");
        return -1;
    }

    // Read the most significant byte (MSB)
    if (i2c_smbus_read_byte_data(MLX90833_I2C_ADDR, MLX90833_PRESSURE_MSB, &msb) < 0) {
        perror("Failed to read pressure MSB");
        return -1;
    }

    // Combine the bytes to form the pressure value
    result = (msb << 8) | lsb;

    return result;
}

int main(void) {
    struct timespec sleep_duration = {0, 500000}; // 500 ms
    struct timespec start_time = {0, 0};
    struct timespec end_time = {0, 0};
    int pressure_value;

    // Initialize libgpiod
    if (gpiod_chip_open("i2c-1", &i2c_chip) < 0) {
        perror("Failed to open i2c-1");
        return 1;
    }

    // Get the SDA and SCL lines
    if (gpiod_line_request_by_name(i2c_chip, "sda", &sda_line, NULL) < 0) {
        perror("Failed to request SDA line");
        goto error_sda;
    }
    if (gpiod_line_request_by_name(i2c_chip, "scl", &scl_line, NULL) < 0) {
        perror("Failed to request SCL line");
        goto error_scl;
    }

    // Set the lines to output mode
    if (gpiod_line_direction_set(sda_line, GPIOF_OUT) < 0) {
        perror("Failed to set SDA line direction");
        goto error_direction_sda;
    }
    if (gpiod_line_direction_set(scl_line, GPIOF_OUT) < 0) {
        perror("Failed to set SCL line direction");
        goto error_direction_scl;
    }

    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (1) {
        clock_gettime(CLOCK_REALTIME, &start_time);

        // Read pressure
        pressure_value = read_pressure();
        if (pressure_value < 0) {
            fprintf(stderr, "Failed to read pressure\n");
            continue;
        }

        // Log pressure value with timestamp
        clock_gettime(CLOCK_REALTIME, &end_time);
        printf("Pressure: %d Pa @ %ld.%09ld\n", pressure_value, (long)end_time.tv_sec, (long)end_time.tv_nsec);

        // Sleep for 500 ms
        nanosleep(&sleep_duration, NULL);
    }

    // Cleanup
    cleanup(0);

    return 0;

error_direction_scl:
    gpiod_line_direction_set(sda_line, GPIOF_OUT);
error_direction_sda:
    gpiod_line_free(scl_line);
error_scl:
    gpiod_line_free(sda_line);
error_sda:
    gpiod_chip_put(i2c_chip);
    return 1;
}

