#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define I2C_ADDR 0x77
#define I2C_DEV "/dev/i2c-1"
#define I2C_CMD_MEASURE 0x1F
#define I2C_CMD_READ 0x1D
#define I2C_CMD_PRESSURE 0x00
#define I2C_CMD_TEMPERATURE 0x01
#define I2C_CMD_STATUS 0x02
#define I2C_CMD_CALIBRATION 0x03
#define I2C_CMD_CALIBRATION_DATA 0x04
#define I2C_CMD_CALIBRATION_DATA_LEN 16

#define DEFAULT_PRESSURE 101325.00
#define DEFAULT_TEMPERATURE 25.00

static volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int main() {
    struct i2c_client *client;
    int fd;
    char buffer[2];
    char calibration_data[I2C_CMD_CALIBRATION_DATA_LEN];
    int i;
    double pressure, temperature;
    struct tm *tm;
    time_t now;

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    fd = i2c_open(I2C_DEV, 0);
    if (fd < 0) {
        perror("i2c_open");
        return EXIT_FAILURE;
    }

    // Initialize I2C client
    client = i2c_client_new(fd, I2C_ADDR);
    if (!client) {
        perror("i2c_client_new");
        i2c_close(fd);
        return EXIT_FAILURE;
    }

    // Trigger measurement
    buffer[0] = I2C_CMD_MEASURE;
    if (i2c_smbus_write_byte_data(client, I2C_CMD_MEASURE, buffer[0]) < 0) {
        perror("i2c_smbus_write_byte_data");
        i2c_client_free(client);
        i2c_close(fd);
        return EXIT_FAILURE;
    }

    // Wait for measurement
    usleep(7000);

    while (!stop_flag) {
        now = time(NULL);
        tm = localtime(&now);

        // Read pressure
        if (i2c_smbus_read_i2c_block_data(client, I2C_CMD_PRESSURE, calibration_data, I2C_CMD_CALIBRATION_DATA_LEN) < 0) {
            perror("i2c_smbus_read_i2c_block_data");
            continue;
        }

        // Check for sensor-absent condition
        for (i = 0; i < I2C_CMD_CALIBRATION_DATA_LEN; i++) {
            if (calibration_data[i] != DEFAULT_PRESSURE) {
                break;
            }
        }
        if (i == I2C_CMD_CALIBRATION_DATA_LEN) {
            fprintf(stderr, "Sensor absent condition detected.\n");
            continue;
        }

        // Calculate pressure
        pressure = (double)calibration_data[0] * 256 + (double)calibration_data[1];

        // Read temperature
        if (i2c_smbus_read_i2c_block_data(client, I2C_CMD_TEMPERATURE, calibration_data, I2C_CMD_CALIBRATION_DATA_LEN) < 0) {
            perror("i2c_smbus_read_i2c_block_data");
            continue;
        }

        // Check for sensor-absent condition
        for (i = 0; i < I2C_CMD_CALIBRATION_DATA_LEN; i++) {
            if (calibration_data[i] != DEFAULT_TEMPERATURE) {
                break;
            }
        }
        if (i == I2C_CMD_CALIBRATION_DATA_LEN) {
            fprintf(stderr, "Sensor absent condition detected.\n");
            continue;
        }

        // Calculate temperature
        temperature = (double)calibration_data[0] * 256 + (double)calibration_data[1];

        // Print results
        printf("%04d-%02d-%02dT%02d:%02d:%02d - Temperature: %.2f C, Pressure: %.2f Pa\n",
               tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec,
               temperature, pressure);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    i2c_client_free(client);
    i2c_close(fd);

    return EXIT_SUCCESS;
}

