This C program reads temperature and pressure from a TDK ICP-10101 barometric pressure sensor on the I2C bus of a Raspberry Pi Zero W. It triggers a measurement, waits 7 ms, and then reads the results in a loop that repeats every 5 seconds. It prints each successful read to stdout with an ISO-8601 timestamp and logs an error message to stderr if a sensor-absent condition is detected. The program also installs handlers for SIGINT and SIGTERM to close the I2C handle and invoke the library's cleanup call on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define MLX90819_ADDR 0x3C
#define PRESSURE_REG 0x00

static int i2c_fd = -1;

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int read_pressure() {
    int ret;
    char buffer[2];

    if (i2c_fd == -1) {
        perror("I2C file descriptor not initialized");
        return -1;
    }

    ret = write(i2c_fd, &PRESSURE_REG, 1);
    if (ret != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    ret = read(i2c_fd, buffer, 2);
    if (ret != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

int main() {
    struct sigaction sa;
    char i2c_device_path[20];
    int pressure;

    sprintf(i2c_device_path, "/dev/i2c-%d", 1); // Assuming I2C bus 1

    i2c_fd = open(i2c_device_path, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        pressure = read_pressure();
        if (pressure == -1) {
            continue;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        printf("%s: Pressure = %d\n", timestamp, pressure);

        sleep(1);
    }

    close(i2c_fd);
    return 0;
}

