#include <signal.h>

#define I2C_ADDR 0x40 // Replace with the actual I2C address of the sensor
#define I2C_DEV "/dev/i2c-1" // Replace with the actual I2C device file
#define LOG_FILE "airflow_log.csv"

// CRC-8 polynomial and initial value
#define POLYNOMIAL 0x31
#define INITIAL_VALUE 0x00

// Function to calculate CRC-8
uint8_t calculate_crc8(uint8_t *data, size_t length) {
    uint8_t crc = INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read differential pressure from the sensor
int read_pressure(uint8_t *pressure_data) {
    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    // Trigger the sensor
    if (write(fd, "\x00", 1) != 1) {
        perror("Failed to write trigger command");
        close(fd);
        return -1;
    }

    // Wait at least 8 ms
    usleep(8000);

    // Read the response
    if (read(fd, pressure_data, 3) != 3) {
        perror("Failed to read pressure data");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to log the pressure value
void log_pressure(uint8_t pressure_data[3]) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    if (access(LOG_FILE, F_OK) == -1) {
        fprintf(file, "Timestamp,Pressure\n");
    }

    fprintf(file, "%s,%02X%02X\n", buffer, pressure_data[0], pressure_data[1]);
    fclose(file);
}

// Signal handler to clean up resources
void cleanup(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    // Add any cleanup code here if necessary
    exit(signum);
}

int main() {
    uint8_t pressure_data[3];

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Check if the log file exists
    if (access(LOG_FILE, F_OK) == -1) {
        FILE *file = fopen(LOG_FILE, "w");
        if (file == NULL) {
            perror("Failed to create log file");
            return 1;
        }
        fclose(file);
    }

    while (1) {
        if (read_pressure(pressure_data) == 0) {
            uint8_t calculated_crc = calculate_crc8(pressure_data, 2);
            if (pressure_data[2] == calculated_crc) {
                log_pressure(pressure_data);
            } else {
                fprintf(stderr, "CRC-8 verification failed\n");
            }
        }
    }

    return 0;
}

