This C program continuously reads the differential pressure from a Sensirion SDP800-500Pa sensor on the I2C bus, verifies the CRC-8 for each measurement, and logs the timestamped pressure value to a file named `airflow_log.csv`. It handles errors on every I2C call, detects and handles sensor-absent or bus-error conditions, and ensures that all resources are cleanly released on normal termination as well as on receipt of SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define MLX90821_I2C_ADDR 0x3C
#define MLX90821_REG_PRESSURE 0x00
#define MLX90821_REG_STATUS 0x01

#define SAFE_TIRE_MIN 200
#define SAFE_TIRE_MAX 250

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (line) {
        gpiod_line_free(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    exit(signum);
}

int read_pressure() {
    int ret;
    uint8_t status;
    uint16_t pressure;

    ret = i2c_smbus_read_byte_data(i2c_fd, MLX90821_REG_STATUS);
    if (ret < 0) {
        fprintf(stderr, "Failed to read status register.\n");
        return -1;
    }
    status = ret;

    if (!(status & 0x01)) {
        fprintf(stderr, "Sensor not ready.\n");
        return -1;
    }

    ret = i2c_smbus_read_word_data(i2c_fd, MLX90821_REG_PRESSURE);
    if (ret < 0) {
        fprintf(stderr, "Failed to read pressure.\n");
        return -1;
    }
    pressure = ret;

    return pressure;
}

int main() {
    int ret;
    FILE *log_file;
    char log_filename[] = "pressure_log.csv";
    char header[] = "timestamp,pressure_kPa\n";
    struct timespec ts;
    int pressure;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C chip.\n");
        return 1;
    }

    line = gpiod_line_request(chip, "GPIO_LINE_NAME", GPIOD_LINE_DIRECTION_OUT, 0);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line.\n");
        gpiod_chip_put(chip);
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpiod_line_free(line);
        gpiod_chip_put(chip);
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, MLX90821_I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address.\n");
        close(i2c_fd);
        gpiod_line_free(line);
        gpiod_chip_put(chip);
        return 1;
    }

    log_file = fopen(log_filename, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        close(i2c_fd);
        gpiod_line_free(line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, header);
    }

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        pressure = read_pressure();

        if (pressure < 0) {
            if (i2c_fd != -1) {
                close(i2c_fd);
                i2c_fd = -1;
            }
            if (line) {
                gpiod_line_free(line);
                line = NULL;
            }
            if (chip) {
                gpiod_chip_put(chip);
                chip = NULL;
            }
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to reopen I2C bus.\n");
                continue;
            }
            ret = ioctl(i2c_fd, I2C_SLAVE, MLX90821_I2C_ADDR);
            if (ret < 0) {
                fprintf(stderr, "Failed to set I2C slave address after reopen.\n");
                continue;
            }
        }

        if (pressure < SAFE_TIRE_MIN || pressure > SAFE_TIRE_MAX) {
            fprintf(stderr, "Warning: Pressure %d kPa is outside safe range (%d-%d kPa).\n", pressure, SAFE_TIRE_MIN, SAFE_TIRE_MAX);
        }

        fprintf(log_file, "%ld,%d\n", ts.tv_sec, pressure);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    gpiod_line_free(line);
    gpiod_chip_put(chip);
    close(i2c_fd);

    return 0;
}

