#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define FILE_NAME "pressure_log.txt"
#define MAX_TICKS 271
#define MIN_TICKS 12
#define SYNC_TICKS 56
#define BUFFER_SIZE 1024

static struct gpiod_line *gpiod_line;

void cleanup(int signum) {
    if (gpiod_line) {
        gpiod_line_free(gpiod_line);
    }
    exit(signum);
}

int read_pressure_sensor() {
    int ticks[4];
    int i, sum = 0;
    int status_nibble, data_nibble, checksum_nibble;

    // Read synchronization pulse
    ticks[0] = gpiod_line_get_value(gpiod_line);
    if (ticks[0] != SYNC_TICKS) {
        fprintf(stderr, "Error: Invalid synchronization pulse width\n");
        return -1;
    }

    // Read status nibble
    ticks[1] = gpiod_line_get_value(gpiod_line);
    if (ticks[1] < MIN_TICKS || ticks[1] > MAX_TICKS) {
        fprintf(stderr, "Error: Invalid status nibble pulse width\n");
        return -1;
    }
    status_nibble = ticks[1];

    // Read data nibbles
    for (i = 0; i < 3; i++) {
        ticks[i + 2] = gpiod_line_get_value(gpiod_line);
        if (ticks[i + 2] < MIN_TICKS || ticks[i + 2] > MAX_TICKS) {
            fprintf(stderr, "Error: Invalid data nibble pulse width\n");
            return -1;
        }
        data_nibble = ticks[i + 2];
        sum += data_nibble;
    }

    // Read checksum nibble
    ticks[5] = gpiod_line_get_value(gpiod_line);
    if (ticks[5] < MIN_TICKS || ticks[5] > MAX_TICKS) {
        fprintf(stderr, "Error: Invalid checksum nibble pulse width\n");
        return -1;
    }
    checksum_nibble = ticks[5];

    // Check checksum
    if (sum != checksum_nibble) {
        fprintf(stderr, "Error: Checksum mismatch\n");
        return -1;
    }

    // Calculate pressure
    int pressure = (status_nibble << 8) | (data_nibble << 4) | (data_nibble >> 4);

    // Log reading
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[BUFFER_SIZE];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S, Pressure: %d.00 Pa\n", timeinfo, pressure);
    FILE *file = fopen(FILE_NAME, "a");
    if (file) {
        fprintf(file, buffer);
        fclose(file);
    } else {
        fprintf(stderr, "Error: Unable to open file for logging\n");
        return -1;
    }

    return pressure;
}

int main() {
    struct gpiod_line_request request;
    struct gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    gpiod_line = gpiod_line_request_by_name(NULL, "gpio4", &request, flags);
    if (!gpiod_line) {
        fprintf(stderr, "Error: Unable to request GPIO line\n");
        return -1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        int pressure = read_pressure_sensor();
        if (pressure == -1) {
            continue;
        }
        usleep(3000); // 3 µs tick time
    }

    cleanup(0);
    return 0;
}

