#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define TMP117_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_CONFIG 0x01
#define TMP117_REG_ID 0x02

#define TMP117_ID 0x10

#define I2C_FILE "/dev/i2c-1"
#define FILE_NAME "greenhouse_temps.dat"

static int i2c_fd = -1;
static FILE *file = NULL;

void handle_signal(int signum) {
    if (file) {
        fclose(file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(signum);
}

float read_temperature() {
    uint8_t data[2];
    int ret;

    ret = read(i2c_fd, data, 2);
    if (ret != 2) {
        fprintf(stderr, "Failed to read temperature data from TMP117\n");
        return -1.0f;
    }

    float temperature = (data[0] << 8) | data[1];
    temperature /= 16.0f;

    return temperature;
}

int verify_sensor_id() {
    uint8_t id;
    int ret;

    ret = read(i2c_fd, &id, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to read ID from TMP117\n");
        return -1;
    }

    if (id != TMP117_ID) {
        fprintf(stderr, "Invalid TMP117 ID: expected 0x%02X, got 0x%02X\n", TMP117_ID, id);
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_FILE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (verify_sensor_id() == -1) {
        close(i2c_fd);
        return 1;
    }

    file = fopen(FILE_NAME, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        float temperature = read_temperature();
        if (temperature != -1.0f) {
            float *temp_ptr = (float *)&temperature;
            fwrite(temp_ptr, sizeof(float), 1, file);
        }
        sleep(60);
    }

    fclose(file);
    close(i2c_fd);

    return 0;
}

