#define SHT40_ADDR 0x44
#define SHT40_CMD_MEASURE 0xF3
#define SHT40_CMD_READ 0xF5
#define SHT40_CMD_READ_TEMP 0xF6
#define SHT40_CMD_READ_HUMIDITY 0xF7
#define SHT40_CMD_READ_STATUS 0xF3

#define CRC_POLYNOMIAL 0x07
#define CRC_INITIAL_VALUE 0xFF

static int i2c_handle;
static FILE *log_file;

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int crc8(unsigned char *data, int length) {
    int crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc & 0xFF;
}

int read_sensor_data(unsigned char *data) {
    int result = i2c_smbus_read_i2c_block_data(i2c_handle, SHT40_ADDR, SHT40_CMD_READ, 6, data);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    int temp_crc = crc8(data, 3);
    int hum_crc = crc8(data + 3, 3);

    if (temp_crc != data[2] || hum_crc != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_handle = i2c_open("/dev/i2c-1", 0);
    if (i2c_handle == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2c_close(i2c_handle);
        return 1;
    }

    while (1) {
        unsigned char data[6];
        if (read_sensor_data(data) == 0) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - Temp: %d.%02d, Humidity: %d.%02d\n",
                    tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                    tm->tm_hour, tm->tm_min, tm->tm_sec,
                    (data[0] << 8) | data[1], (data[2] << 4) | (data[3] >> 4),
                    (data[4] << 8) | data[5], (data[6] << 4) | (data[7] >> 4));
            fflush(log_file);
        }
        usleep(5000000); // Sleep for 5 seconds
    }

    fclose(log_file);
    i2c_close(i2c_handle);
    return 0;
}

