#include <errno.h>

#define TMP117_ADDR 0x48
#define BUFFER_SIZE 10
#define SAMPLE_INTERVAL 5000 // 5 seconds

int i2c_fd;
int temperature_buffer[BUFFER_SIZE];
int buffer_head = 0;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        write_buffer_to_file();
        close(i2c_fd);
    }
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int init_i2c() {
    char device_path[20];
    snprintf(device_path, sizeof(device_path), "/dev/i2c-%d", 1);

    i2c_fd = open(device_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to acquire TMP117 I2C bus access");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_temperature() {
    uint8_t data[2];
    ssize_t bytes_read = read(i2c_fd, data, 2);

    if (bytes_read != 2) {
        if (bytes_read < 0) {
            perror("Failed to read temperature data");
        } else {
            fprintf(stderr, "Incomplete read: %zd bytes read\n", bytes_read);
        }
        return -1;
    }

    int temperature = (data[0] << 8) | data[1];
    temperature >>= 4; // Shift right to get the temperature value

    temperature_buffer[buffer_head] = temperature;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    return temperature;
}

void write_buffer_to_file() {
    FILE *file = fopen("temperature_log.dat", "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_head + i) % BUFFER_SIZE;
        if (fwrite(&temperature_buffer[index], sizeof(int), 1, file) != 1) {
            perror("Failed to write to file");
        }
    }

    fclose(file);
}

int main() {
    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int temperature = read_temperature();
        if (temperature >= 0) {
            printf("Temperature: %d°C\n", temperature);
        }
        sleep(SAMPLE_INTERVAL / 1000);
    }

    return EXIT_SUCCESS;
}

