#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define SHTC3_ADDR 0x40
#define SHTC3_REG_TEMP 0x00
#define SHTC3_REG_HUM 0x01
#define SHTC3_REG_CONFIG 0x02
#define SHTC3_REG_STATUS 0x03
#define SHTC3_REG_CRC 0x04

#define SHTC3_CONFIG_MEASURE 0x01
#define SHTC3_CONFIG_HOLD 0x02
#define SHTC3_CONFIG_ONE_SHOT 0x04

#define SHTC3_STATUS_MEASURE_DONE 0x01
#define SHTC3_STATUS_ERROR 0x02

#define SHTC3_CRC_POLYNOMIAL 0x07

#define SHTC3_TEMP_MIN -40.0
#define SHTC3_TEMP_MAX 125.0
#define SHTC3_HUM_MIN 0.0
#define SHTC3_HUM_MAX 100.0

#define SHTC3_I2C_PATH "/dev/i2c-1"

static int shtc3_fd;

void handle_sigint(int signum) {
    if (shtc3_fd != -1) {
        close(shtc3_fd);
    }
    exit(0);
}

int shtc3_init() {
    shtc3_fd = open(SHTC3_I2C_PATH, O_RDWR);
    if (shtc3_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(shtc3_fd, I2C_SLAVE, SHTC3_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(shtc3_fd);
        return -1;
    }

    return 0;
}

void shtc3_cleanup() {
    if (shtc3_fd != -1) {
        close(shtc3_fd);
    }
}

int shtc3_read_temperature_humidity() {
    uint8_t data[4];
    int ret;

    // Write configuration register
    data[0] = SHTC3_CONFIG_MEASURE | SHTC3_CONFIG_ONE_SHOT;
    ret = write(shtc3_fd, data, 1);
    if (ret != 1) {
        perror("Failed to write configuration register");
        return -1;
    }

    // Wait for measurement to complete
    usleep(12400);

    // Read temperature and humidity registers
    ret = read(shtc3_fd, data, 4);
    if (ret != 4) {
        perror("Failed to read temperature and humidity registers");
        return -1;
    }

    // Validate CRC
    uint8_t crc = data[3];
    uint8_t calculated_crc = 0;
    for (int i = 0; i < 3; i++) {
        calculated_crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (calculated_crc & 0x80) {
                calculated_crc = (calculated_crc << 1) ^ SHTC3_CRC_POLYNOMIAL;
            } else {
                calculated_crc <<= 1;
            }
        }
    }

    if (crc != calculated_crc) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract temperature and humidity
    int16_t temp = (data[0] << 8) | data[1];
    int16_t hum = (data[2] << 8) | data[3];

    // Validate temperature and humidity
    if (temp < (int16_t)(SHTC3_TEMP_MIN * 100) || temp > (int16_t)(SHTC3_TEMP_MAX * 100) ||
        hum < (int16_t)(SHTC3_HUM_MIN * 100) || hum > (int16_t)(SHTC3_HUM_MAX * 100)) {
        fprintf(stderr, "Temperature or humidity out of range\n");
        return -1;
    }

    // Convert to Celsius and percentage
    double temperature = (double)temp / 100.0;
    double humidity = (double)hum / 100.0;

    // Log to file
    FILE *log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
            temperature, humidity);

    fclose(log_file);

    // Print to stdout
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    if (shtc3_init() < 0) {
        return 1;
    }

    while (1) {
        if (shtc3_read_temperature_humidity() < 0) {
            continue;
        }

        sleep(5);
    }

    shtc3_cleanup();
    return 0;
}

