#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define FILE_NAME "mag_temp_log.csv"

// Function prototypes
void handle_sigint(int signum);
int read_sensor(int i2c_fd, float *speed, float *temperature);
void write_log(const char *header, float speed, float temperature);

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd;
    float speed, temperature;
    FILE *log_file;

    // Initialize I2C
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize GPIO for SIGINT handling
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    line = gpiod_line_request(chip, 2, "SIGINT", 0);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        close(i2c_fd);
        return 1;
    }

    // Set up SIGINT handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(FILE_NAME, "a+");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        close(i2c_fd);
        return 1;
    }

    // Write header if file is empty
    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "Speed,Temperature\n");
