        sleep(1);
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_put(chip);
    close(i2c_fd);

    return 0;
}

void handle_sigint(int signum) {
    // Cleanup resources
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_put(chip);
    close(i2c_fd);

    // Exit program
    exit(0);
}

