#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_ADDR 0x28 // Honeywell HAFUHH0025PA3 I2C address
#define BUFFER_SIZE 4 // 4 bytes for 14-bit flow and 12-bit temperature

static gpiod_chip *chip;
static gpiod_line *sda, *scl;
static gpiod_i2c *i2c;

void cleanup(int signum) {
    if (i2c) {
        gpiod_i2c_close(i2c);
    }
    if (sda) {
        gpiod_line_free(sda);
    }
    if (scl) {
        gpiod_line_free(scl);
    }
    if (chip) {
        gpiod_chip_free(chip);
    }
    fclose(stdout); // Close the log file
    exit(0);
}

int main() {
    FILE *log_file = fopen("flow_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/i2c-1");
    if (!chip) {
        perror("Failed to open I2C chip");
        return 1;
    }

    sda = gpiod_line_request(chip, "sda", "flow_sensor_sda", 1, 0);
    if (!sda) {
        perror("Failed to request SDA line");
        goto error_sda;
    }

    scl = gpiod_line_request(chip, "scl", "flow_sensor_scl", 1, 0);
    if (!scl) {
        perror("Failed to request SCL line");
        goto error_scl;
    }

    i2c = gpiod_i2c_open(chip, sda, scl, I2C_ADDR);
    if (!i2c) {
        perror("Failed to open I2C bus");
        goto error_i2c;
    }

    while (1) {
        uint8_t buffer[BUFFER_SIZE];
        int result = gpiod_i2c_read(i2c, buffer, BUFFER_SIZE);
        if (result < 0) {
            perror("I2C read error");
            gpiod_i2c_close(i2c);
            i2c = gpiod_i2c_open(chip, sda, scl, I2C_ADDR);
            if (!i2c) {
                perror("Failed to re-initialize I2C handle");
                continue;
            }
        }

        uint16_t flow_value = (buffer[0] << 8) | buffer[1];
        uint16_t temp_value = (buffer[2] << 4) | (buffer[3] >> 4);

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %d SLPM %d°C\n",
                timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
                flow_value, temp_value);

        fflush(log_file);
        usleep(1000000); // Sleep for 1 second
    }

    cleanup(0); // This will never be reached, but required for cleanup

error_i2c:
    gpiod_line_free(scl);
error_scl:
    gpiod_line_free(sda);
error_sda:
    gpiod_chip_free(chip);
    fclose(log_file);
    return 1;
}

