#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define GPIO_DIRECTION_OUT 0
#define GPIO_DIRECTION_IN 1
#define GPIO_LEVEL_LOW 0
#define GPIO_LEVEL_HIGH 1
#define DHT11_TIMEOUT_MS 1000
#define DHT11_DATA_INTERVAL_S 2

static struct gpiod_line *gpiod_line;
static FILE *file;

void handle_signal(int signum) {
    if (gpiod_line) {
        gpiod_line_free(gpiod_line);
    }
    if (file) {
        fclose(file);
    }
    exit(signum);
}

void read_dht11() {
    int i, j, bit, data[5];
    unsigned long start_time, end_time, elapsed_time;
    int timeout = 0;

    // Start signal
    gpiod_line_direction_set(gpiod_line, GPIO_DIRECTION_OUT);
    gpiod_line_set_value(gpiod_line, GPIO_LEVEL_LOW);
    start_time = gpiod_line_get_value(gpiod_line);
    while (gpiod_line_get_value(gpiod_line) == GPIO_LEVEL_LOW && (end_time - start_time) < DHT11_TIMEOUT_MS * 1000) {
        usleep(1000);
        end_time = gpiod_line_get_value(gpiod_line);
    }
    if ((end_time - start_time) >= DHT11_TIMEOUT_MS * 1000) {
        timeout = 1;
        fprintf(file, "%s: Timeout on start signal\n", ctime(&time(NULL)));
    }

    gpiod_line_set_value(gpiod_line, GPIO_LEVEL_HIGH);
    start_time = gpiod_line_get_value(gpiod_line);
    while (gpiod_line_get_value(gpiod_line) == GPIO_LEVEL_HIGH && (end_time - start_time) < DHT11_TIMEOUT_MS * 1000) {
        usleep(1000);
        end_time = gpiod_line_get_value(gpiod_line);
    }
    if ((end_time - start_time) >= DHT11_TIMEOUT_MS * 1000) {
        timeout = 1;
        fprintf(file, "%s: Timeout on response\n", ctime(&time(NULL)));
    }

    gpiod_line_direction_set(gpiod_line, GPIO_DIRECTION_IN);
    for (i = 0; i < 40; i++) {
        start_time = gpiod_line_get_value(gpiod_line);
        while (gpiod_line_get_value(gpiod_line) == GPIO_LEVEL_LOW && (end_time - start_time) < DHT11_TIMEOUT_MS * 1000) {
            usleep(1000);
            end_time = gpiod_line_get_value(gpiod_line);
        }
        if ((end_time - start_time) >= DHT11_TIMEOUT_MS * 1000) {
            timeout = 1;
            fprintf(file, "%s: Timeout on data bit %d\n", ctime(&time(NULL)), i);
            break;
        }

        start_time = gpiod_line_get_value(gpiod_line);
        while (gpiod_line_get_value(gpiod_line) == GPIO_LEVEL_HIGH && (end_time - start_time) < DHT11_TIMEOUT_MS * 1000) {
            usleep(1000);
            end_time = gpiod_line_get_value(gpiod_line);
        }
        if ((end_time - start_time) >= DHT11_TIMEOUT_MS * 1000) {
            timeout = 1;
            fprintf(file, "%s: Timeout on data bit %d\n", ctime(&time(NULL)), i);
            break;
        }

        bit = (end_time - start_time) < 26000;
        data[i / 8] = (data[i / 8] << 1) | bit;
    }

    if (timeout) {
        return;
    }

    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        fprintf(file, "%s: Checksum failure\n", ctime(&time(NULL)));
        return;
    }

    fprintf(file, "%s: Humidity: %d.%d, Temperature: %d.%d\n", ctime(&time(NULL)), data[0], data[1], data[2], data[3]);
}

int main() {
    struct gpiod_line_request_config config;
    struct gpiod_line_request *request;

    gpiod_line = gpiod_line_request_by_name(NULL, "gpio%d", GPIO_PIN, &config);
    if (!gpiod_line) {
        perror("Failed to request GPIO line");
        return 1;
    }

    file = fopen("dht11_readings.txt", "a");
    if (!file) {
        perror("Failed to open file");
        gpiod_line_free(gpiod_line);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_dht11();
        sleep(DHT11_DATA_INTERVAL_S);
    }

    return 0;
}

