#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define SHT31D_ADDR 0x44
#define SHT31D_MEASURE_CMD 0xF3
#define SHT31D_MEASURE_WAIT 15
#define SHT31D_MEASURE_INTERVAL 5000
#define SHT31D_DATA_LEN 6
#define SHT31D_TEMP_MSB 0x00
#define SHT31D_TEMP_LSB 0x01
#define SHT31D_HUM_MSB 0x02
#define SHT31D_HUM_LSB 0x03
#define SHT31D_CRC_TEMP 0x04
#define SHT31D_CRC_HUM 0x05

static int i2c_fd = -1;
static int log_fd = -1;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != -1) {
        fclose(log_fd);
    }
    exit(signum);
}

int i2c_transaction(uint8_t cmd, uint8_t *data, uint8_t len, uint8_t retries) {
    int i;
    for (i = 0; i < retries; i++) {
        if (write(i2c_fd, &cmd, 1) != 1) {
            return -1;
        }
        if (read(i2c_fd, data, len) != len) {
            return -1;
        }
        return 0;
    }
    return -1;
}

uint8_t crc8_calculate(uint8_t *data, uint8_t len) {
    uint8_t crc = 0;
    uint8_t i, j;
    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0xD5;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sa;
