        close(i2c_fd);
    }
    if (log_fd != -1) {
        fclose(log_fd);
    }
    exit(signum);
}

int i2c_transaction(uint8_t cmd, uint8_t *data, uint8_t len, uint8_t retries) {
    int i;
    for (i = 0; i < retries; i++) {
        if (write(i2c_fd, &cmd, 1) != 1) {
            return -1;
        }
        if (read(i2c_fd, data, len) != len) {
            return -1;
        }
        return 0;
    }
    return -1;
}

uint8_t crc8_calculate(uint8_t *data, uint8_t len) {
    uint8_t crc = 0;
    uint8_t i, j;
    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0xD5;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

