#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define MLX90824_I2C_ADDR 0x77
#define MLX90824_REG_PRESSURE 0x00
#define MLX90824_REG_TEMPERATURE 0x01
#define MLX90824_REG_STATUS 0x07

#define MLX90824_STATUS_ERROR 0x01

static void cleanup(void) {
    gpiod_close(i2c_handle);
    fclose(log_file);
    mlx90824_cleanup();
}

static void handle_signal(int signum) {
    cleanup();
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *i2c_handle;
    FILE *log_file;
    char timestamp[20];
    int pressure, temperature, status;

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    chip = gpiod_chip_open("/dev/i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    i2c_handle = gpiod_line_request(chip, "i2c-1", GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!i2c_handle) {
        fprintf(stderr, "Failed to request I2C line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(i2c_handle);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    if (mlx90824_init() != MLX90824_SUCCESS) {
        fprintf(stderr, "Failed to initialize sensor\n");
        fclose(log_file);
        gpiod_line_release(i2c_handle);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read pressure
        if (mlx90824_read_pressure(MLX90824_I2C_ADDR, MLX90824_REG_PRESSURE, &pressure) != MLX90824_SUCCESS) {
            fprintf(stderr, "Failed to read pressure\n");
            continue;
        }

        // Read temperature
        if (mlx90824_read_temperature(MLX90824_I2C_ADDR, MLX90824_REG_TEMPERATURE, &temperature) != MLX90824_SUCCESS) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        // Read status
        if (mlx90824_read_status(MLX90824_I2C_ADDR, MLX90824_REG_STATUS, &status) != MLX90824_SUCCESS) {
            fprintf(stderr, "Failed to read status\n");
            continue;
        }

        // Check for errors
        if (status & MLX90824_STATUS_ERROR) {
            fprintf(stderr, "Sensor error detected\n");
            continue;
        }

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log data
        fprintf(log_file, "%s, Pressure: %d, Temperature: %d\n", timestamp, pressure, temperature);
        fflush(log_file);

        // Sleep for 2 seconds
        sleep(2);
    }

    // Cleanup on exit
    cleanup();

    return EXIT_SUCCESS;
}

