#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_ADDR 0x48
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 26.0

static int fan_pin = 18; // BCM GPIO pin for the fan
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static float running_average = 0.0;
static int fan_state = 0;

void handle_signal(int signum) {
    if (fan_state) {
        gpiod_line_set_value(fan_pin, 0);
        fan_state = 0;
    }
    close(i2c_file);
    gpiod_cleanup();
    exit(signum);
}

int read_temperature() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C interface");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access/talk to slave");
        close(fd);
        return -1;
    }

    uint8_t data[2];
    ssize_t bytes_read = read(fd, data, 2);
    if (bytes_read != 2) {
        perror("Failed to read temperature data");
        close(fd);
        return -1;
    }

    close(fd);

    float temperature = (data[0] << 8) | data[1];
    temperature /= 16.0;

    return temperature;
}

void update_average(float new_temp) {
    running_average = (running_average * (BUFFER_SIZE - 1) + new_temp) / BUFFER_SIZE;
}

void control_fan() {
    if (running_average > TEMP_THRESHOLD_ON && fan_state == 0) {
        gpiod_line_set_value(fan_pin, 1);
        fan_state = 1;
    } else if (running_average < TEMP_THRESHOLD_OFF && fan_state == 1) {
        gpiod_line_set_value(fan_pin, 0);
        fan_state = 0;
    }
}

int main() {
    if (gpiod_init() < 0) {
        perror("Failed to initialize gpiod");
        return 1;
    }

    gpiod_line_handle *fan_line = gpiod_line_request(fan_pin, "Fan Control", 0, 0);
    if (!fan_line) {
        perror("Failed to request GPIO line");
        gpiod_cleanup();
        return 1;
    }

    if (gpiod_line_set_value(fan_line, 0) < 0) {
        perror("Failed to set initial fan state");
        gpiod_line_free(fan_line);
        gpiod_cleanup();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        float temp = read_temperature();
        if (temp >= 0) {
            temperature_buffer[buffer_index] = temp;
            update_average(temp);
            control_fan();
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temp, running_average);
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        }
        sleep(1);
    }

    gpiod_line_free(fan_line);
    gpiod_cleanup();
    return 0;
}

