        if (ret != DATA_LEN) {
            fprintf(stderr, "Failed to read data from sensor\n");
            continue;
        }

        uint8_t calculated_crc = crc8(data, DATA_LEN - 1);
        if (calculated_crc != data[DATA_LEN - 1]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        double differential_pressure = (data[1] << 8) | data[0];
        double temperature = (data[3] << 8) | data[2];

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s,%f,%f\n", timestamp, differential_pressure, temperature);

        if (differential_pressure > 5.0) {
            fprintf(stderr, "Warning: Differential pressure exceeds 5.0 Pa\n");
        }

        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    i2c_close(i2c_handle);

    return 0;
}

