#define LOW 0

static int i2c_fd;
static struct gpiod_chip *gpiod_chip;
static struct gpiod_line *gpiod_line;

void handle_signal(int signum) {
    if (gpiod_line) {
        gpiod_line_set_value(gpiod_line, LOW);
        gpiod_line_free(gpiod_line);
    }
    if (gpiod_chip) {
        gpiod_chip_put(gpiod_chip);
    }
    close(i2c_fd);
    exit(signum);
}

int read_temperature() {
    int ret;
    char buf[2];

    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("Error reading temperature");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

int main() {
    struct sigaction sa;
    int temperature;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting signal handler");
        return 1;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpiod_chip) {
        perror("Error opening GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpiod_line = gpiod_line_request_any(gpiod_chip, "LED", LED_GPIO,
                                       GPIOD_LINE_DIRECTION_OUTPUT);
    if (!gpiod_line) {
        perror("Error requesting GPIO line");
        gpiod_chip_put(gpiod_chip);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        temperature = read_temperature();
        if (temperature < 0) {
            continue;
        }

        printf("Temperature: %d°C\n", temperature);

        if (temperature > 28) {
            gpiod_line_set_value(gpiod_line, HIGH);
        } else if (temperature < 27) {
            gpiod_line_set_value(gpiod_line, LOW);
        }

        sleep(1);
    }

    return 0;
}

