#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_ADDR 0x40
#define I2C_SPEED 100000
#define I2C_CMD_MEASURE 0x40
#define I2C_CMD_READ 0x41
#define I2C_CMD_WRITE 0x42
#define I2C_CMD_CONFIG 0x43
#define I2C_CMD_STATUS 0x44
#define I2C_CMD_CALIBRATION 0x45

#define CRC_POLYNOMIAL 0x07
#define CRC_INIT 0x00

static struct i2c_client *i2c_client;
static struct i2c_client *i2c_client_open(void) {
    struct i2c_client *client = i2c_client_new_from_name("i2c-1");
    if (!client) {
        perror("Failed to create i2c client");
        exit(EXIT_FAILURE);
    }
    if (i2c_client_set_slave(client, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        i2c_client_free(client);
        exit(EXIT_FAILURE);
    }
    if (i2c_client_set_speed(client, I2C_SPEED) < 0) {
        perror("Failed to set I2C speed");
        i2c_client_free(client);
        exit(EXIT_FAILURE);
    }
    return client;
}

static void i2c_client_close(struct i2c_client *client) {
    if (client) {
        i2c_client_free(client);
    }
}

static int i2c_read(struct i2c_client *client, uint8_t cmd, uint8_t *data, size_t len) {
    int ret;
    if (i2c_client_write(client, &cmd, 1) < 0) {
        perror("Failed to write I2C command");
        return -1;
    }
    usleep(45000); // Wait at least 45ms
    ret = i2c_client_read(client, data, len);
    if (ret < 0) {
        perror("Failed to read I2C data");
        return -1;
    }
    return ret;
}

static uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void handle_signal(int signum) {
    i2c_client_close(i2c_client);
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install signal handler");
        exit(EXIT_FAILURE);
    }

    i2c_client = i2c_client_open();

    FILE *file = fopen("flow_data.txt", "w");
    if (!file) {
        perror("Failed to open file");
        i2c_client_close(i2c_client);
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint8_t data[9];
        if (i2c_read(i2c_client, I2C_CMD_READ, data, 9) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        uint8_t crc_dp = crc8(data, 2);
        uint8_t crc_temp = crc8(data + 2, 2);
        uint8_t crc_scale = crc8(data + 4, 3);

        if (crc_dp != data[2] || crc_temp != data[4] || crc_scale != data[7]) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(file, "%s - Differential Pressure: %02X%02X, Temperature: %02X%02X, Scale-Factor: %02X%02X%02X\n",
                timestamp, data[0], data[1], data[2], data[3], data[4], data[5], data[6]);
    }

    fclose(file);
    i2c_client_close(i2c_client);
    return EXIT_SUCCESS;
}

