#define I2C_TIMEOUT 1000
#define LOG_FILE "environment.log"

int i2c_fd;
int retries = 0;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (freopen(LOG_FILE, "a", stdout) == NULL) {
        perror("Failed to reopen log file");
    }
    exit(signum);
}

void init_i2c() {
    i2c_fd = i2c_open(1, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    int retries = 0;
    while (retries < RETRY_COUNT) {
        int cmd = 0xF3; // Read ID or Firmware Revision
        int data[2];
        int result = i2c_smbus_read_i2c_block_data(i2c_fd, cmd, 2, data);
        if (result == 2) {
            if (data[0] == 0x10 && data[1] == 0x44) {
                printf("Si7021 sensor detected.\n");
                break;
            } else {
                printf("Si7021 sensor not detected. Retrying...\n");
            }
        } else {
            printf("Failed to read sensor ID. Retrying...\n");
        }
        retries++;
        sleep(1);
    }

    if (retries == RETRY_COUNT) {
        printf("Si7021 sensor not detected after retries.\n");
        exit(1);
    }
}

void read_sensor_data() {
    int retries = 0;
    while (retries < RETRY_COUNT) {
        int cmd = 0xF4; // Measure Relative Humidity, No Master Hold
        int data[2];
        int result = i2c_smbus_read_i2c_block_data(i2c_fd, cmd, 2, data);
        if (result == 2) {
            int humidity = (data[0] << 8) | data[1];
            retries = 0; // Reset retries since we got valid data
            break;
        } else {
            printf("Failed to read humidity. Retrying...\n");
        }
        retries++;
        sleep(1);
    }

    if (retries == RETRY_COUNT) {
        printf("Failed to read humidity after retries.\n");
        exit(1);
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        int cmd = 0xF5; // Measure Temperature, No Master Hold
        int data[2];
        int result = i2c_smbus_read_i2c_block_data(i2c_fd, cmd, 2, data);
        if (result == 2) {
            int temperature = (data[0] << 8) | data[1];
            retries = 0; // Reset retries since we got valid data
            break;
        } else {
            printf("Failed to read temperature. Retrying...\n");
        }
        retries++;
        sleep(1);
    }

    if (retries == RETRY_COUNT) {
        printf("Failed to read temperature after retries.\n");
        exit(1);
    }

    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

    printf("%s, %d, %d\n", timestamp, temperature, humidity);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }
    fprintf(log_file, "%s, %d, %d\n", timestamp, temperature, humidity);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();

    while (1) {
        read_sensor_data();
        sleep(60);
    }

    return 0;
}

