#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define STS40_ADDR 0x40
#define STS40_CMD_READ_TEMP 0x00
#define STS40_CMD_WRITE_CONFIG 0x01
#define STS40_CONFIG_RATE_10MS 0x01

#define CRC8_POLYNOMIAL 0x07

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != -1) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    char buffer[3];
    unsigned char crc8;
    unsigned char data[2];
    struct tm *tm_info;
    time_t rawtime;

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Infinite loop
    while (1) {
        // Write configuration command
        if (write(i2c_fd, &STS40_CMD_WRITE_CONFIG, 1) != 1) {
            perror("Failed to write configuration command");
            continue;
        }

        // Write configuration data
        if (write(i2c_fd, &STS40_CONFIG_RATE_10MS, 1) != 1) {
            perror("Failed to write configuration data");
            continue;
        }

        // Read temperature
        if (read(i2c_fd, buffer, 3) != 3) {
            perror("Failed to read temperature");
            continue;
        }

        // Extract data and CRC8
        data[0] = buffer[0];
        data[1] = buffer[1];
        crc8 = buffer[2];

        // Verify CRC8
        unsigned char calculated_crc8 = 0;
        for (int i = 0; i < 2; i++) {
            calculated_crc8 ^= data[i];
            for (int j = 0; j < 8; j++) {
                if (calculated_crc8 & 0x80) {
                    calculated_crc8 = (calculated_crc8 << 1) ^ CRC8_POLYNOMIAL;
                } else {
                    calculated_crc8 <<= 1;
                }
            }
        }

        if (crc8 != calculated_crc8) {
            fprintf(stderr, "CRC8 mismatch\n");
            continue;
        }

        // Log temperature reading
        rawtime = time(NULL);
        tm_info = localtime(&rawtime);
        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d.%03d %.2f\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                tm_info->tm_usec / 1000, (data[0] * 256 + data[1]) / 100.0);

        // Wait 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return 0;
}
