#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define SDP810_I2C_ADDR 0x40
#define SDP810_REG_PRESSURE 0x00
#define SDP810_REG_TEMPERATURE 0x04
#define SDP810_REG_SCALE_FACTOR 0x08
#define SDP810_RESULT_SIZE 9
#define SDP810_CRC_POLY 0x07
#define SDP810_CRC_INIT 0x00

// CRC-8 function
uint8_t crc8(uint8_t *data, size_t length) {
    uint8_t crc = SDP810_CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_fd, uint8_t *data) {
    int bytes_read = i2c_read(i2c_fd, SDP810_I2C_ADDR, SDP810_REG_PRESSURE, data, SDP810_RESULT_SIZE);
    if (bytes_read != SDP810_RESULT_SIZE) {
        return -1;
    }

    // Validate CRCs
    uint8_t pressure_crc = crc8(data, 2);
    uint8_t temperature_crc = crc8(data + 3, 2);
    uint8_t scale_factor_crc = crc8(data + 6, 3);

    if (pressure_crc != data[2] || temperature_crc != data[5] || scale_factor_crc != data[8]) {
        return -1;
    }

    return 0;
}

// Function to handle SIGINT (Ctrl+C)
void handle_sigint(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    i2c_close(i2c_fd);
    fclose(log_file);
    i2c_cleanup();
    exit(0);
}

int main() {
    int i2c_fd = i2c_open("/dev/i2c-1", 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    FILE *log_file = fopen("hvac_pressure_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2c_close(i2c_fd);
        return 1;
    }

    struct sigaction sigint_action;
    sigint_action.sa_handler = handle_sigint;
    sigemptyset(&sigint_action.sa_mask);
    sigint_action.sa_flags = 0;
    sigaction(SIGINT, &sigint_action, NULL);

    while (1) {
        uint8_t data[SDP810_RESULT_SIZE];
        if (read_sensor_data(i2c_fd, data) == 0) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

            int16_t pressure = (data[0] << 8) | data[1];
            int16_t temperature = (data[3] << 8) | data[4];

            fprintf(log_file, "%s, %d, %d\n", timestamp, pressure, temperature);
            fflush(log_file);
        } else {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
            fprintf(log_file, "%s, Error\n", timestamp);
            fflush(log_file);
        }

        usleep(50000); // Wait at least 50ms
        sleep(1); // Wait for 1 second
    }

    fclose(log_file);
    i2c_close(i2c_fd);
    i2c_cleanup();

    return 0;
}

