#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define BUFFER_SIZE 100
#define I2C_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define CSV_FILE "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG "/var/log/scd40_error.log"

typedef struct {
    int co2;
    float temperature;
    float humidity;
    time_t timestamp;
} SensorData;

pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t buffer_not_empty = PTHREAD_COND_INITIALIZER;
pthread_cond_t buffer_not_full = PTHREAD_COND_INITIALIZER;

SensorData buffer[BUFFER_SIZE];
int head = 0;
int tail = 0;
volatile sig_atomic_t running = 1;

void *read_sensor(void *arg) {
    int i2c_fd = i2c_open(I2C_DEV, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return NULL;
    }

    unsigned char cmd_start_measurement = 0x01;
    unsigned char cmd_stop_measurement = 0x00;

    i2c_smbus_write_byte_data(i2c_fd, I2C_ADDR, cmd_start_measurement);
    sleep(1); // Wait at least one second after starting measurement

    while (running) {
        unsigned char data[7];
        int bytes_read = i2c_smbus_read_i2c_block_data(i2c_fd, I2C_ADDR, 0, data, 7);
        if (bytes_read != 7) {
            fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
            continue;
        }

        if (data[6] != 0x55) { // CRC-8 check
            fprintf(stderr, "CRC-8 check failed at %s\n", ctime(&data[5]));
            continue;
        }

        time_t timestamp = data[5];
        int co2 = (data[0] << 8) | data[1];
        float temperature = (data[2] << 8) | data[3];
        float humidity = (data[4] << 8) | data[5];

        pthread_mutex_lock(&buffer_mutex);
        buffer[head] = (SensorData){co2, temperature, humidity, timestamp};
        head = (head + 1) % BUFFER_SIZE;
        pthread_cond_signal(&buffer_not_empty);
        pthread_mutex_unlock(&buffer_mutex);

        sleep(5);
    }

    i2c_smbus_write_byte_data(i2c_fd, I2C_ADDR, cmd_stop_measurement);
    i2c_close(i2c_fd);
    return NULL;
}

void *log_data(void *arg) {
    FILE *csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return NULL;
    }

    while (running) {
        pthread_mutex_lock(&buffer_mutex);
        while (tail == head) {
            pthread_cond_wait(&buffer_not_empty, &buffer_mutex);
        }

        fprintf(csv_file, "%d,%f,%f,%ld\n", buffer[tail].co2, buffer[tail].temperature, buffer[tail].humidity, (long)buffer[tail].timestamp);
        tail = (tail + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        sleep(60);
    }

    fclose(csv_file);
    return NULL;
}

void handle_sigint(int signum) {
    running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    pthread_t read_thread, log_thread;

    if (pthread_create(&read_thread, NULL, read_sensor, NULL) != 0) {
        perror("Failed to create read thread");
        return 1;
    }

    if (pthread_create(&log_thread, NULL, log_data, NULL) != 0) {
        perror("Failed to create log thread");
        return 1;
    }

    pthread_join(read_thread, NULL);
    pthread_join(log_thread, NULL);

    return 0;
}

