#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define LOG_FILE "sdp810_log.txt"

// CRC-8 polynomial and initial value
#define CRC_POLY 0x07
#define CRC_INIT 0x00

// Function to calculate CRC-8
uint8_t calculate_crc8(uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(uint8_t *data, size_t length) {
    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    ssize_t bytes_read = read(fd, data, length);
    if (bytes_read != length) {
        perror("Failed to read data from sensor");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to log data to file
void log_data(const char *timestamp, double pressure_Pa, double temperature_C) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_Pa, temperature_C);
    fclose(log_file);
}

// Signal handler for SIGINT
void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    // Close I2C handle and release resources
    // (Assuming there's a function to do this)
    // close_i2c_handle();

    // Close log file
    fclose(fopen(LOG_FILE, "a"));

    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        uint8_t data[9];
        if (read_sensor_data(data, 9) < 0) {
            continue; // Handle error and continue
        }

        // Extract pressure, temperature, and scale factor
        uint16_t pressure = (data[0] << 8) | data[1];
        uint16_t temperature = (data[3] << 8) | data[4];
        uint16_t scale_factor = (data[6] << 8) | data[7];

        // Validate CRCs
        uint8_t crc_pressure = calculate_crc8(data, 2);
        uint8_t crc_temperature = calculate_crc8(data + 3, 2);
        uint8_t crc_scale_factor = calculate_crc8(data + 6, 2);

        if (crc_pressure != data[2] || crc_temperature != data[5] || crc_scale_factor != data[8]) {
            printf("CRC validation failed, skipping this sample.\n");
            continue; // Handle CRC failure and continue
        }

        // Convert to physical units
        double pressure_Pa = (double)pressure * 0.01;
        double temperature_C = (double)temperature / 100.0;

        // Log data
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        log_data(timestamp, pressure_Pa, temperature_C);

        // Wait for 1 second before next sample
        sleep(1);
    }

    fclose(log_file);
    return 0;
}

