static int gpioline;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpioline >= 0) {
        int ret = gpioline_request(gpioline, LOW);
        if (ret < 0) {
            perror("Failed to release GPIO line");
        }
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access/talk to slave");
        close(i2c_fd);
        return 1;
    }

    gpioline = gpioline_request(GPIO_PIN, GPIO_BCM);
    if (gpioline < 0) {
        perror("Failed to request GPIO line");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint8_t data[6];
        ssize_t bytes_read = read(i2c_fd, data, 6);
        if (bytes_read != 6) {
            perror("Failed to read from sensor");
            continue;
        }

        // Verify CRC (simplified example, actual CRC check would be more complex)
        if (data[5] != (data[0] + data[1] + data[2] + data[3])) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        // Convert pressure bytes to Pa
        uint16_t pressure = (data[0] << 8) | data[1];
        if (pressure < 95000) {
            pressure_low = true;
        } else {
            pressure_low = false;
        }

        if (pressure_low) {
            // Blink at 5 Hz
            for (int i = 0; i < 5; i++) {
                gpioline_write(gpioline, HIGH);
                usleep(100000);
                gpioline_write(gpioline, LOW);
                usleep(100000);
            }
        } else {
            // Blink at 1 Hz
            gpioline_write(gpioline, HIGH);
            usleep(500000);
            gpioline_write(gpioline, LOW);
            usleep(500000);
        }

        usleep(20000); // 20 ms delay
    }

    return 0;
}

