#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define MLX90614_I2C_ADDR 0x5A
#define MLX90614_AMBIENT_TEMP_ADDR 0x07
#define MLX90614_OBJECT_TEMP_ADDR 0x0B
#define MLX90614_FAN_CONTROL_ADDR 0x0C
#define MLX90614_FAN_CONTROL_ON 0x01
#define MLX90614_FAN_CONTROL_OFF 0x00
#define MLX90614_FAN_CONTROL_HYS_HIGH 30
#define MLX90614_FAN_CONTROL_HYS_LOW 28

static int i2c_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *fan_line;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (fan_line) {
        gpiod_line_request_release(fan_line);
        fan_line = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    exit(signum);
}

int read_temperature(uint8_t addr, uint16_t *value) {
    int retries = 3;
    while (retries > 0) {
        if (i2c_smbus_read_word_data(i2c_fd, addr) == 0) {
            *value = 0;
            return 0;
        }
        if (i2c_smbus_read_word_data(i2c_fd, addr) == -1) {
            retries--;
            usleep(10000);
        } else {
            *value = i2c_smbus_read_word_data(i2c_fd, addr);
            return 0;
        }
    }
    return -1;
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[32];
    uint16_t ambient_temp, object_temp;
    int fan_state = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((chip = gpiod_chip_open("/dev/gpiomem")) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    if ((fan_line = gpiod_line_request(chip, "18", "fan", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        perror("gpiod_line_request");
        gpiod_chip_put(chip);
        return 1;
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        gpiod_line_request_release(fan_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_I2C_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpiod_line_request_release(fan_line);
        gpiod_chip_put(chip);
        return 1;
    }

    FILE *log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        gpiod_line_request_release(fan_line);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        if (read_temperature(MLX90614_AMBIENT_TEMP_ADDR, &ambient_temp) == 0 &&
            read_temperature(MLX90614_OBJECT_TEMP_ADDR, &object_temp) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            tm = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_file, "%s - Ambient: %d°C, Object: %d°C\n", timestamp, ambient_temp, object_temp);
            fflush(log_file);

            if (object_temp > MLX90614_FAN_CONTROL_HYS_HIGH) {
                if (fan_state == 0) {
                    gpiod_line_set_value(fan_line, 1);
                    fan_state = 1;
                }
            } else if (object_temp < MLX90614_FAN_CONTROL_HYS_LOW) {
                if (fan_state == 1) {
                    gpiod_line_set_value(fan_line, 0);
                    fan_state = 0;
                }
            }
        }

        usleep(2000000); // Sleep for 2 seconds
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_line_request_release(fan_line);
    gpiod_chip_put(chip);

    return 0;
}

