#include <arpa/inet.h>
#include <netinet/in.h>
#include <netdb.h>
#include <pthread.h>

#define SHT40_ADDR 0x44
#define SHT40_MEASURE_CMD 0xF3
#define SHT40_DATA_REG 0xF6
