#define TMP102_ADDR 0x48
#define TMP102_REG_CONFIG 0x01
#define TMP102_REG_MEASURE 0x00
#define TMP102_REG_TEMP 0x00

#define FILE_NAME "temperature_log.csv"

static volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int read_temperature(int i2c_handle) {
    uint8_t config_reg = 0x00;
    uint8_t temp_reg = 0x00;
    int16_t temperature = 0;

    // Set the configuration register to start a measurement
    if (i2c_smbus_write_byte_data(i2c_handle, TMP102_ADDR, TMP102_REG_CONFIG, config_reg) < 0) {
        perror("Failed to write to TMP102 configuration register");
        return -1;
    }

    // Wait for the measurement to complete
    usleep(100000);

    // Read the temperature register
    if (i2c_smbus_read_byte_data(i2c_handle, TMP102_ADDR, TMP102_REG_TEMP) < 0) {
        perror("Failed to read temperature from TMP102");
        return -1;
    }

    // Combine the two bytes into a 16-bit integer
    temperature = (int16_t)((temp_reg << 8) | temp_reg);

    // Convert the raw temperature to Celsius
    temperature = (temperature * 0.0625) - 50;

    return temperature;
}

int main() {
    int i2c_handle = -1;
    FILE *file = NULL;
    int temperature = 0;
    struct tm *time_info;
    char timestamp[20];

    // Initialize the I2C bus
    i2c_handle = i2c_open(1, 0);
    if (i2c_handle < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Open the file for appending
    file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("Failed to open file for writing");
        i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    // Install the SIGINT handler
    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        // Read the temperature
        temperature = read_temperature(i2c_handle);
        if (temperature >= 0) {
            // Get the current time
            time_info = localtime(&time(NULL));
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", time_info);

            // Write the timestamp and temperature to the file
            fprintf(file, "%s%f\n", timestamp, temperature);
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(file);
    i2c_close(i2c_handle);

    return EXIT_SUCCESS;
}

