#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC2010_ADDR 0x40
#define MEASUREMENT_CONFIG 0x01
#define TEMP_MSB 0x02
#define TEMP_LSB 0x03
#define HUMIDITY_MSB 0x04
#define HUMIDITY_LSB 0x05
#define MAX_RETRIES 3
#define TIMEOUT_MS 500

volatile sig_atomic_t shutdown_flag = 0;

int i2c_open() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    int ret = ioctl(fd, I2C_SLAVE, HDC2010_ADDR);
    if (ret < 0) {
        perror("Failed to acquire HDC2010 address");
        close(fd);
        return -1;
    }

    return fd;
}

void i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Failed to close I2C bus");
    }
}

int read_register(int fd, uint8_t reg, uint8_t *data) {
    int retries = 0;
    int ret;

    do {
        ret = write(fd, &reg, 1);
        if (ret != 1) {
            perror("Failed to write to register");
            return -1;
        }

        ret = read(fd, data, 1);
        if (ret != 1) {
            if (retries < MAX_RETRIES) {
                retries++;
                continue;
            } else {
                perror("Failed to read from register");
                return -1;
            }
        }
    } while (shutdown_flag);

    return 0;
}

int read_temp_humidity(int fd, uint16_t *temp, uint16_t *humidity) {
    uint8_t temp_data[2];
    uint8_t humidity_data[2];

    if (read_register(fd, MEASUREMENT_CONFIG, NULL) < 0) {
        return -1;
    }

    if (read_register(fd, TEMP_MSB, temp_data) < 0 ||
        read_register(fd, TEMP_LSB, temp_data + 1) < 0) {
        return -1;
    }

    *temp = (temp_data[0] << 8) | temp_data[1];

    if (read_register(fd, HUMIDITY_MSB, humidity_data) < 0 ||
        read_register(fd, HUMIDITY_LSB, humidity_data + 1) < 0) {
        return -1;
    }

    *humidity = (humidity_data[0] << 8) | humidity_data[1];

    return 0;
}

void signal_handler(int signum) {
    shutdown_flag = 1;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = i2c_open();
    if (fd < 0) {
        return 1;
    }

    uint16_t temp, humidity;

    while (!shutdown_flag) {
        if (read_temp_humidity(fd, &temp, &humidity) < 0) {
            printf("Failed to read temperature and humidity\n");
            continue;
        }

        printf("Temperature: %d, Humidity: %d\n", temp, humidity);

        usleep(5000000); // Sleep for 5 seconds
    }

    i2c_close(fd);

    return 0;
}

