#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libi2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define PRESSURE_REG 0x00
#define TEMP_REG 0x04
#define CRC_REG 0x06
#define POLYNOMIAL 0x07
#define INIT_VALUE 0x00
#define PRESSURE_MSB 0x00
#define PRESSURE_LSB 0x01
#define TEMP_MSB 0x02
#define TEMP_LSB 0x03
#define CRC_PRESSURE 0x04
#define CRC_TEMP 0x05
#define BUFFER_SIZE 6
#define PERIOD 500
#define WAIT_TIME 45

static volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

uint8_t crc8(uint8_t *data, size_t length) {
    uint8_t crc = INIT_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct i2c_client *client;
    int result;

    signal(SIGINT, handle_sigint);

    client = i2c_client_new(I2C_BUS, I2C_ADDR);
    if (!client) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    while (!stop) {
        uint8_t buffer[BUFFER_SIZE];

        result = i2c_smbus_read_i2c_block_data(client, PRESSURE_REG, buffer, BUFFER_SIZE);
        if (result < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            i2c_client_close(client);
            return 1;
        }

        uint16_t pressure = (buffer[PRESSURE_MSB] << 8) | buffer[PRESSURE_LSB];
        uint16_t temperature = (buffer[TEMP_MSB] << 8) | buffer[TEMP_LSB];
        uint8_t crc_pressure = crc8(buffer, 2);
        uint8_t crc_temp = crc8(buffer + 2, 2);

        if (crc_pressure != buffer[CRC_PRESSURE] || crc_temp != buffer[CRC_TEMP]) {
            fprintf(stderr, "CRC check failed\n");
            i2c_client_close(client);
            return 1;
        }

        printf("Pressure: %d, Temperature: %d\n", pressure, temperature);

        usleep(WAIT_TIME * 1000);
        usleep((PERIOD - WAIT_TIME) * 1000);
    }

    i2c_client_close(client);
    return 0;
}

