#include <linux/spi/spidev.h>
#include <pigpio.h>

#define TARGET_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"

#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS_CE0 0
#define SPI_CS_CE1 1

#define GPIO_RELAY 17

#define MAX_PROFILE_LINES 100

typedef struct {
    int time_seconds;
    int target_temp_celsius;
} ProfileEntry;

ProfileEntry profile[MAX_PROFILE_LINES];
int profile_size = 0;

int spi_fd;
int spi_cs;

void load_profile() {
    FILE *file = fopen(TARGET_FILE, "r");
    if (!file) {
        perror("Failed to open profile file");
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (profile_size >= MAX_PROFILE_LINES) {
            fprintf(stderr, "Profile file contains too many entries\n");
            exit(EXIT_FAILURE);
        }

        if (sscanf(line, "%d,%d", &profile[profile_size].time_seconds, &profile[profile_size].target_temp_celsius) != 2) {
            fprintf(stderr, "Invalid profile entry: %s\n", line);
            exit(EXIT_FAILURE);
        }

        profile_size++;
    }

    fclose(file);
}

int read_temperature() {
    uint8_t data[2];
    int ret;

    ret = spi_read(spi_fd, data, 2, spi_cs);
    if (ret != 2) {
        perror("Failed to read temperature from MAX6675");
        exit(EXIT_FAILURE);
    }

    int temperature = (data[1] << 8) | data[0];
    if (temperature == 0xFFFF) {
        fprintf(stderr, "Sensor absent or error reading temperature\n");
        exit(EXIT_FAILURE);
    }

    return temperature;
}

void write_log(int temperature) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%d,%d\n", profile[profile_size - 1].time_seconds, temperature);
    fclose(log_file);
}

void pid_control(int current_temp, int target_temp) {
    // Implement PID control logic here
    // For simplicity, we'll just set the relay duty cycle based on the difference
    int duty_cycle = (target_temp - current_temp) * 100 / 255; // Assuming 0-255 range for duty cycle
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioWrite(GPIO_RELAY, duty_cycle);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to read SPI speed");
        exit(EXIT_FAILURE);
    }

    spi_cs = SPI_CS_CE0; // Use CE0 for SPI communication

    load_profile();

    int current_temp;
    while (1) {
        current_temp = read_temperature();
        write_log(current_temp);

        if (profile_size > 0) {
            pid_control(current_temp, profile[profile_size - 1].target_temp_celsius);
        }

        sleep(1);
    }

    close(spi_fd);
    gpioTerminate();

    return 0;
}

