#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <libgpiod.h>

#define TEMP_SENSOR_FILE "/sys/bus/w1/devices/28-000006666666/w1_slave"
#define LOG_FILE "greenhouse.log"
#define PWM_FREQUENCY 50
#define PWM_DUTY_MAX 100

static struct gpiod_line *temp_sensor_line;
static struct gpiod_line *relay_line;
static struct gpiod_line *pwm_line;
static struct gpiod_pwm *pwm;
static FILE *log_file;

static void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (pwm) {
        gpiod_pwm_disable(pwm);
        gpiod_pwm_free(pwm);
    }
    if (temp_sensor_line) {
        gpiod_line_free(temp_sensor_line);
    }
    if (relay_line) {
        gpiod_line_free(relay_line);
    }
    if (pwm_line) {
        gpiod_line_free(pwm_line);
    }
    exit(signum);
}

static int read_temperature() {
    char temp_file[256];
    FILE *temp_file_handle;
    int temperature = 0;

    sprintf(temp_file, "%s/w1_slave", TEMP_SENSOR_FILE);
    temp_file_handle = fopen(temp_file, "r");
    if (!temp_file_handle) {
        perror("Failed to open temperature sensor file");
        return -1;
    }

    char line[128];
    while (fgets(line, sizeof(line), temp_file_handle)) {
        if (strstr(line, "YES")) {
            char *temp_str = strstr(line, "t=");
            if (temp_str) {
                temperature = atoi(temp_str + 2);
                temperature /= 1000; // Convert to Celsius
            }
        }
    }

    fclose(temp_file_handle);
    return temperature;
}

static int compute_pid_output(int setpoint, int temperature, double Kp, double Ki, double Kd) {
    static int prev_error = 0;
    static int integral = 0;
    int error = setpoint - temperature;
    int derivative = error - prev_error;
    integral += error;
    int output = Kp * error + Ki * integral + Kd * derivative;
    prev_error = error;
    return output;
}

static void log_data(int temperature, int setpoint, int pid_output, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %d\n", buffer, temperature, setpoint, pid_output, duty_cycle);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    int setpoint = atoi(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    struct gpiod_chip *chip;
    struct gpiod_line_request request;

    chip = gpiod_chip_open_by_name("gpio");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    request.consumer = "greenhouse_pid";
    request.flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    request.value = 0;
    temp_sensor_line = gpiod_line_request_by_name(chip, "4", &request);
    if (!temp_sensor_line) {
        perror("Failed to request GPIO4 for temperature sensor");
        gpiod_chip_close(chip);
        return 1;
    }

    request.flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    request.value = 0;
    relay_line = gpiod_line_request_by_name(chip, "17", &request);
    if (!relay_line) {
        perror("Failed to request GPIO17 for relay");
        gpiod_line_free(temp_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    request.flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    request.value = 0;
    pwm_line = gpiod_line_request_by_name(chip, "18", &request);
    if (!pwm_line) {
        perror("Failed to request GPIO18 for PWM");
        gpiod_line_free(temp_sensor_line);
        gpiod_line_free(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_pwm_config pwm_config;
    pwm_config.polarity = GPIOD_PWM_POLARITY_NORMAL;
    pwm_config.enable_active = GPIOD_PWM_ENABLE_ACTIVE_HIGH;
    pwm_config.period = 1000000 / PWM_FREQUENCY; // 1000000 / 50 = 20000
    pwm = gpiod_pwm_request(chip, pwm_line, "greenhouse_pid", &pwm_config);
    if (!pwm) {
        perror("Failed to request PWM");
        gpiod_line_free(temp_sensor_line);
        gpiod_line_free(relay_line);
        gpiod_line_free(pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_pwm_free(pwm);
        gpiod_line_free(temp_sensor_line);
        gpiod_line_free(relay_line);
        gpiod_line_free(pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int temperature = read_temperature();
        if (temperature < 0) {
            perror("Failed to read temperature");
            continue;
        }

        int pid_output = compute_pid_output(setpoint, temperature, Kp, Ki, Kd);
        int duty_cycle = (pid_output > 0) ? (pid_output * PWM_DUTY_MAX / 100) : 0;

        gpiod_line_set_value(relay_line, (pid_output > 0));
        gpiod_pwm_set_duty_ns(pwm, duty_cycle * (1000000 / PWM_FREQUENCY));

        log_data(temperature, setpoint, pid_output, duty_cycle);

        sleep(5);
    }

    return 0;
}

