#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define AHT20_ADDR 0x77
#define HUMIDITY_REG 0x01
#define STATUS_REG 0x00
#define RETRY_LIMIT 3
#define RETRY_DELAY 10
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60
#define HUMIDITY_THRESHOLD_LOW 55
#define POLL_INTERVAL 5000

static int humidity_fd = -1;
static struct gpiod_line *dehumidifier_line = NULL;

void handle_signal(int signum) {
    if (dehumidifier_line) {
        gpiod_line_set_value(dehumidifier_line, 0);
        gpiod_line_free(dehumidifier_line);
    }
    if (humidity_fd != -1) {
        close(humidity_fd);
    }
    exit(0);
}

int read_humidity() {
    int retries = 0;
    int humidity = 0;
    uint8_t status = 0;

    while (retries < RETRY_LIMIT) {
        if (write(humidity_fd, &HUMIDITY_REG, 1) != 1) {
            retries++;
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        usleep(80 * 1000);

        if (read(humidity_fd, &status, 1) != 1 || read(humidity_fd, &humidity, 1) != 1) {
            retries++;
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        if ((status & 0x01) && !(status & 0x02)) {
            break;
        }

        retries++;
        usleep(RETRY_DELAY * 1000);
    }

    if (retries == RETRY_LIMIT) {
        fprintf(stderr, "Failed to read humidity from AHT20 sensor.\n");
        return -1;
    }

    return humidity;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    humidity_fd = open("/dev/i2c-1", O_RDWR);
    if (humidity_fd == -1) {
        perror("open");
        return 1;
    }

    if (ioctl(humidity_fd, I2C_SLAVE, AHT20_ADDR) == -1) {
        perror("ioctl");
        close(humidity_fd);
        return 1;
    }

    dehumidifier_line = gpiod_line_request(DEHUMIDIFIER_GPIO, "dehumidifier", "Dehumidifier control", 0);
    if (!dehumidifier_line) {
        perror("gpiod_line_request");
        close(humidity_fd);
        return 1;
    }

    gpiod_line_set_consumer(dehumidifier_line);
    gpiod_line_set_direction(dehumidifier_line, GPIOF_OUT);

