void handle_sigint_sigterm(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);

    if (http_sock != -1) {
        close(http_sock);
        http_sock = -1;
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    exit(0);
}

int read_i2c_data(uint8_t reg, uint8_t *data, size_t len) {
    int ret;

    if (i2c_fd == -1) {
