        return -1;
    }

    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        syslog(LOG_ERR, "Failed to write to I2C bus");
        return -1;
    }

    ret = read(i2c_fd, data, len);
    if (ret != len) {
        syslog(LOG_ERR, "Failed to read from I2C bus");
        return -1;
    }

    return 0;
}

