        syslog(LOG_ERR, "getaddrinfo: %s", gai_strerror(rv));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if ((http_sock = socket(p->ai_family, p->ai_socktype, p->ai_protocol)) == -1) {
            continue;
        }

        if (connect(http_sock, p->ai_addr, p->ai_addrlen) == -1) {
            close(http_sock);
            http_sock = -1;
            continue;
        }

        break;
    }

    if (p == NULL) {
        syslog(LOG_ERR, "Failed to connect to server");
        return -1;
    }

    freeaddrinfo(res);

    if (send(http_sock, json, strlen(json), 0) == -1) {
        syslog(LOG_ERR, "Failed to send HTTP POST request");
        close(http_sock);
        http_sock = -1;
        return -1;
    }

    close(http_sock);
    http_sock = -1;

    return 0;
}

