#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x77
#define BMP280_CHIP_ID 0x58
#define BMP280_PRESSURE_REG 0x34
#define BMP280_TEMP_REG 0x2E
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CTRL_MEAS_PRESSURE 0x3F
#define BMP280_CTRL_MEAS_TEMP 0x27
#define BMP280_PRESSURE_OFFSET 0x34
#define BMP280_TEMP_OFFSET 0x2E
#define BMP280_PRESSURE_COEFF_ADDR 0x88
#define BMP280_TEMP_COEFF_ADDR 0xA1
#define BMP280_PRESSURE_COEFF_LEN 24
#define BMP280_TEMP_COEFF_LEN 16
#define BMP280_PRESSURE_MIN 980
#define BMP280_PRESSURE_MAX 1020
#define BMP280_I2C_DEV "/dev/i2c-1"

typedef struct {
    int16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_coeffs_t;

int bmp280_read_reg(int file_desc, uint8_t reg, uint8_t *data) {
    int ret = 0;
    ret = read(file_desc, data, 1);
    return ret;
}

int bmp280_write_reg(int file_desc, uint8_t reg, uint8_t data) {
    int ret = 0;
    ret = write(file_desc, &data, 1);
    return ret;
}

int bmp280_read_coeffs(int file_desc, bmp280_coeffs_t *coeffs) {
    uint8_t data[24];
    int ret = 0;

    ret = read(file_desc, data, 24);
    if (ret != 24) {
        return -1;
    }

    coeffs->dig_T1 = (int16_t)((data[0] << 8) | data[1]);
    coeffs->dig_T2 = (int16_t)((data[2] << 8) | data[3]);
    coeffs->dig_T3 = (int16_t)((data[4] << 8) | data[5]);
    coeffs->dig_P1 = (uint16_t)((data[6] << 8) | data[7]);
    coeffs->dig_P2 = (int16_t)((data[8] << 8) | data[9]);
    coeffs->dig_P3 = (int16_t)((data[10] << 8) | data[11]);
    coeffs->dig_P4 = (int16_t)((data[12] << 8) | data[13]);
    coeffs->dig_P5 = (int16_t)((data[14] << 8) | data[15]);
    coeffs->dig_P6 = (int16_t)((data[16] << 8) | data[17]);
    coeffs->dig_P7 = (int16_t)((data[18] << 8) | data[19]);
    coeffs->dig_P8 = (int16_t)((data[20] << 8) | data[21]);
    coeffs->dig_P9 = (int16_t)((data[22] << 8) | data[23]);

    return 0;
}

int bmp280_read_pressure(int file_desc, bmp280_coeffs_t *coeffs, float *pressure) {
    uint8_t data[3];
    int ret = 0;

    ret = bmp280_write_reg(file_desc, BMP280_CTRL_MEAS_REG, BMP280_CTRL_MEAS_PRESSURE);
    if (ret != 0) {
        return -1;
    }

    usleep(10000); // Wait for conversion completion

    ret = bmp280_read_reg(file_desc, BMP280_PRESSURE_REG, data);
    if (ret != 3) {
        return -1;
    }

    *pressure = ((data[0] << 12) | (data[1] << 4) | (data[2] >> 4)) / 100.0;

    return 0;
}

int bmp280_read_temperature(int file_desc, bmp280_coeffs_t *coeffs, float *temperature) {
    uint8_t data[3];
    int ret = 0;

    ret = bmp280_write_reg(file_desc, BMP280_CTRL_MEAS_REG, BMP280_CTRL_MEAS_TEMP);
    if (ret != 0) {
        return -1;
    }

    usleep(10000); // Wait for conversion completion

    ret = bmp280_read_reg(file_desc, BMP280_TEMP_REG, data);
    if (ret != 3) {
        return -1;
    }

    *temperature = ((data[0] << 12) | (data[1] << 4) | (data[2] >> 4)) / 100.0;

    return 0;
}

void handle_signal(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    // Close I2C handle and invoke library's call() function
    // (Assuming a function named `bmp280_close` exists)
    // bmp280_close();
    exit(signum);
}

int main() {
    int file_desc = -1;
    bmp280_coeffs_t coeffs;
    float pressure = 0.0;
    float temperature = 0.0;
    FILE *log_file = NULL;
    struct timespec ts;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    for (int retry = 0; retry < 3; retry++) {
        file_desc = open(BMP280_I2C_DEV, O_RDWR);
        if (file_desc < 0) {
            perror("Failed to open I2C device");
            continue;
        }

        if (ioctl(file_desc, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            close(file_desc);
            continue;
        }

        uint8_t chip_id;
        if (bmp280_read_reg(file_desc, 0xD0, &chip_id) != 0 || chip_id != BMP280_CHIP_ID) {
            perror("Failed to verify chip ID");
            close(file_desc);
            continue;
        }

        if (bmp280_read_coeffs(file_desc, &coeffs) != 0) {
            perror("Failed to read coefficients");
            close(file_desc);
            continue;
        }

        break;
    }

    if (file_desc < 0) {
        perror("Failed to open I2C device after retries");
        fclose(log_file);
        return 1;
    }

    while (1) {
        if (bmp280_read_pressure(file_desc, &coeffs, &pressure) != 0) {
            perror("Failed to read pressure");
            close(file_desc);
            fclose(log_file);
            return 1;
        }

        if (pressure < BMP280_PRESSURE_MIN || pressure > BMP280_PRESSURE_MAX) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld: %.2f hPa\n", (long)ts.tv_sec, (long)ts.tv_nsec, pressure);
        }

        usleep(2000000); // Sleep for 2 seconds
    }

    close(file_desc);
    fclose(log_file);

    return 0;
}

