#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR  0x40
#define PIR_GPIO   17

static const char *log_filename = "sensor_data.csv";

static void handle_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

static void handle_i2c_error(const char *msg) {
    fprintf(stderr, "I2C error: %s\n", msg);
}

static void handle_gpiod_error(const char *msg) {
    fprintf(stderr, "GPIO error: %s\n", msg);
}

static void handle_exit(int signum) {
    if (gpiod_chip) {
        gpiod_chip_release(gpiod_chip);
    }
    if (gpiod_line) {
        gpiod_line_release(gpiod_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main(void) {
    struct tm *tm;
    time_t now;
    char timestamp[20];
    FILE *log_file = NULL;
    int i2c_retry = 0;
    int pir_state = 0;

    if (gpioInitialise() < 0) {
        handle_gpiod_error("Failed to initialize GPIO");
    }

    gpiod_chip = gpiod_chip_open("/dev/gpiochip4", 0);
    if (!gpiod_chip) {
        handle_gpiod_error("Failed to open GPIO chip");
    }

    gpiod_line = gpiod_line_request(gpiod_chip, PIR_GPIO, "PIR", 0, GPIOD_LINE_DIRECTION_INPUT);
    if (!gpiod_line) {
        handle_gpiod_error("Failed to request GPIO line");
    }

    if (gpiod_line_get_value(gpiod_line) == 0) {
        pir_state = 1;
    }

    while (1) {
        now = time(NULL);
        tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        if (tm->tm_hour == 0 && tm->tm_min == 0 && tm->tm_sec == 0) {
            if (log_file) {
                fclose(log_file);
            }
            log_file = fopen(log_filename, "w");
            if (!log_file) {
                handle_error("Failed to open log file");
            }
            fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
        }

        if (log_file) {
            fprintf(log_file, "%s,", timestamp);

            for (i2c_retry = 0; i2c_retry < 3; i2c_retry++) {
                if (i2c_smbus_read_byte_data(TMP117_ADDR, 0x00) >= 0) {
                    break;
                }
                usleep(10000);
            }
            if (i2c_retry == 3) {
                handle_i2c_error("Failed to read from TMP117");
            }

            for (i2c_retry = 0; i2c_retry < 3; i2c_retry++) {
                if (i2c_smbus_read_byte_data(AHT20_ADDR, 0x00) >= 0) {
                    break;
                }
                usleep(10000);
            }
            if (i2c_retry == 3) {
                handle_i2c_error("Failed to read from AHT20");
            }

            fprintf(log_file, "%d,%d,%d\n", /* TMP117 and AHT20 values here */, pir_state);
        }

        usleep(1000000); // Sleep for 1 second

        if (gpiod_line_get_value(gpiod_line) != pir_state) {
            pir_state = gpiod_line_get_value(gpiod_line);
        }
    }

    handle_exit(0);

    return 0;
}

