#define RAIN_SENSOR_PIN 17
#define ENA_PIN 22
#define IN1_PIN 23
#define IN2_PIN 24

static struct gpiod_chip *chip;
static struct gpiod_line *rain_sensor_line, *ena_line, *in1_line, *in2_line;

void handle_signal(int signum) {
    if (rain_sensor_line) {
        gpiod_line_request_release(rain_sensor_line);
    }
    if (ena_line) {
        gpiod_line_request_release(ena_line);
    }
    if (in1_line) {
        gpiod_line_request_release(in1_line);
    }
    if (in2_line) {
        gpiod_line_request_release(in2_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum);
}

void log_event(const char *event, int status) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (status == 0) {
        printf("%s: %s\n", buffer, event);
    } else {
        printf("%s: %s (Error: %d)\n", buffer, event, status);
    }
}

int main() {
    int status;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_event("GPIO chip open failed", -1);
        return 1;
    }

    rain_sensor_line = gpiod_line_request_by_name(chip, "17", "rain_sensor", 0);
    if (!rain_sensor_line) {
        log_event("Rain sensor line request failed", -1);
        goto error_exit;
    }

    ena_line = gpiod_line_request_by_name(chip, "22", "ena", 0);
    if (!ena_line) {
        log_event("ENA line request failed", -1);
        goto error_exit;
    }

    in1_line = gpiod_line_request_by_name(chip, "23", "in1", 0);
    if (!in1_line) {
        log_event("IN1 line request failed", -1);
        goto error_exit;
    }

    in2_line = gpiod_line_request_by_name(chip, "24", "in2", 0);
    if (!in2_line) {
        log_event("IN2 line request failed", -1);
        goto error_exit;
    }

    while (1) {
        status = gpiod_line_get_value(rain_sensor_line);
        if (status < 0) {
            log_event("Rain sensor read failed", status);
            continue;
        }

        if (status == 0) { // Rain detected
            log_event("Rain detected", 0);

            status = gpiod_line_set_value(ena_line, 1);
            if (status < 0) {
                log_event("ENA set failed", status);
                continue;
            }

            status = gpiod_line_set_value(in1_line, 1);
            if (status < 0) {
                log_event("IN1 set failed", status);
                continue;
            }

            status = gpiod_line_set_value(in2_line, 0);
            if (status < 0) {
                log_event("IN2 set failed", status);
                continue;
            }

            log_event("Motor started", 0);
            sleep(5); // Run motor for 5 seconds

            status = gpiod_line_set_value(ena_line, 0);
            if (status < 0) {
                log_event("ENA stop failed", status);
                continue;
            }

            log_event("Motor stopped", 0);
        }

        sleep(2); // Poll every 2 seconds
    }

error_exit:
    if (rain_sensor_line) {
        gpiod_line_request_release(rain_sensor_line);
    }
    if (ena_line) {
        gpiod_line_request_release(ena_line);
    }
    if (in1_line) {
        gpiod_line_request_release(in1_line);
    }
    if (in2_line) {
        gpiod_line_request_release(in2_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }

    return 0;
}

