This C program continuously monitors a YL-83 rain sensor connected to GPIO17 (active-low) on a Raspberry Pi 5. It polls the sensor every 2 seconds and, upon detecting rain, commands an L298N motor driver to close a window by driving the motor forward for exactly 5 seconds using ENA on GPIO22, IN1 on GPIO23, and IN2 on GPIO24. It logs each event, including motor start and stop, and any error conditions, with a timestamp. The program installs SIGINT and SIGTERM handlers to ensure the motor is safely stopped and all GPIO lines are released upon program termination.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define RED_GPIO 17
#define GREEN_GPIO 22
#define BLUE_GPIO 27

#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE_MAX 255

static int cpu_load_prev = 0;
static int cpu_load_current = 0;

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    gpioSetPWMfrequency(RED_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_GPIO, PWM_FREQUENCY);

    gpioPWM(RED_GPIO, 0);
    gpioPWM(GREEN_GPIO, 0);
    gpioPWM(BLUE_GPIO, 0);

    gpioTerminate();
    exit(0);
}

void read_cpu_load() {
    FILE *file = fopen("/proc/stat", "r");
    if (!file) {
        perror("Failed to open /proc/stat");
        exit(1);
    }

    char line[256];
    fgets(line, sizeof(line), file);
    fclose(file);

    char *token = strtok(line, " ");
    int user = atoi(token);
    token = strtok(NULL, " ");
    int nice = atoi(token);
    token = strtok(NULL, " ");
    int system = atoi(token);
    token = strtok(NULL, " ");
    int idle = atoi(token);
    token = strtok(NULL, " ");
    int iowait = atoi(token);

    cpu_load_current = (user + nice + system + iowait) * 100 / (user + nice + system + idle + iowait);
}

void set_led_color() {
    int red_duty = (cpu_load_current * PWM_DUTY_CYCLE_MAX) / 100;
    int green_duty = (100 - cpu_load_current) * PWM_DUTY_CYCLE_MAX / 100;

    if (red_duty > PWM_DUTY_CYCLE_MAX) {
        red_duty = PWM_DUTY_CYCLE_MAX;
    }

    if (green_duty > PWM_DUTY_CYCLE_MAX) {
        green_duty = PWM_DUTY_CYCLE_MAX;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    gpioSetPWMfrequency(RED_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_GPIO, PWM_FREQUENCY);

    gpioPWM(RED_GPIO, red_duty);
    gpioPWM(GREEN_GPIO, green_duty);
    gpioPWM(BLUE_GPIO, 0);

    gpioTerminate();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    while (1) {
        read_cpu_load();
        set_led_color();
        usleep(500000); // Sleep for 500 ms
    }

    return 0;
}

