#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <libi2c-dev.h>

#define BMP280_I2C_ADDR 0x77
#define BMP280_REG_CONTROL_H 0xF4
#define BMP280_REG_DATA 0xF7
#define BMP280_REG_PRESSURE 0xFA
#define BMP280_REG_TEMPERATURE 0xFA

#define JSON_BUFFER_SIZE 64

static int i2c_fd = -1;
static int sock_fd = -1;
static struct sockaddr_in server_addr;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (sock_fd != -1) {
        close(sock_fd);
    }
    exit(signum);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int read_sensor_data(int *temperature, int *pressure) {
    int status;
    uint8_t data[3];

    // Start measurement
    status = i2c_smbus_write_byte_data(i2c_fd, BMP280_REG_CONTROL_H, 0x27);
    if (status < 0) {
        perror("i2c_smbus_write_byte_data");
        return -1;
    }

    // Wait for measurement to complete
    usleep(500000);

    // Read temperature and pressure
    status = i2c_smbus_read_i2c_block_data(i2c_fd, BMP280_REG_DATA, 3, data);
    if (status < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        return -1;
    }

    *temperature = (data[0] << 8) | data[1];
    *pressure = (data[2] << 8) | data[3];

    return 0;
}

int main() {
    int temperature, pressure;
    char json_buffer[JSON_BUFFER_SIZE];
    struct i2c_smbus_ioctl_data i2c_data;

    setup_signal_handlers();

    // Open I2C device
    i2c_fd = i2c_open("/dev/i2c-1", 0);
    if (i2c_fd < 0) {
        perror("i2c_open");
        return 1;
    }

    // Open UDP socket
    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        perror("socket");
        close(i2c_fd);
        return 1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    inet_pton(AF_INET, "192.168.1.100", &server_addr.sin_addr);

    while (1) {
        if (read_sensor_data(&temperature, &pressure) < 0) {
            continue;
        }

        snprintf(json_buffer, JSON_BUFFER_SIZE, "{\"temperature\":%d,\"pressure\":%d}", temperature, pressure);

        if (sendto(sock_fd, json_buffer, strlen(json_buffer), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            perror("sendto");
        }

        sleep(5);
    }

    close(sock_fd);
    close(i2c_fd);

    return 0;
}

