#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define BUFFER_SIZE 20
#define TEMP_THRESHOLD_1 25
#define TEMP_THRESHOLD_2 40
#define TEMP_THRESHOLD_3 60
#define PWM_FREQ 1000
#define PWM_DUTY_MAX 255

typedef struct {
    time_t timestamp;
    int temperature;
    int duty_cycle;
} BufferEntry;

BufferEntry buffer[BUFFER_SIZE];
int buffer_head = 0;

void handle_sigint(int signum) {
    gpiod_chip_unexport(chip);
    pigpio_stop();
    printf("Received SIGINT, stopping PWM and closing SPI interface.\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Timestamp: %ld, Temperature: %d, Duty Cycle: %d\n",
               buffer[i].timestamp, buffer[i].temperature, buffer[i].duty_cycle);
    }
    exit(0);
}

int spi_transfer(int channel, uint8_t *tx_buf, uint8_t *rx_buf, int length) {
    int result = pigpio_spi_write(channel, tx_buf, rx_buf, length);
    if (result < 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }
    return 0;
}

int read_temperature() {
    uint8_t tx_buf[2] = {0x00, 0x00};
    uint8_t rx_buf[2];

    if (spi_transfer(0, tx_buf, rx_buf, 2) < 0) {
        return -1;
    }

    int temperature = (rx_buf[0] << 8) | rx_buf[1];
    if (temperature < 0) {
        fprintf(stderr, "MAX31855 fault detected.\n");
        return -1;
    }

    return temperature;
}

int compute_duty_cycle(int temperature) {
    if (temperature <= TEMP_THRESHOLD_1) {
        return 0;
    } else if (temperature <= TEMP_THRESHOLD_2) {
        return (temperature - TEMP_THRESHOLD_1) * PWM_DUTY_MAX / (TEMP_THRESHOLD_2 - TEMP_THRESHOLD_1);
    } else if (temperature <= TEMP_THRESHOLD_3) {
        return 50 + (temperature - TEMP_THRESHOLD_2) * (PWM_DUTY_MAX - 50) / (TEMP_THRESHOLD_3 - TEMP_THRESHOLD_2);
    } else {
        return PWM_DUTY_MAX;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiomem");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return 1;
    }

    gpiod_line *pwm_line = gpiod_line_request(chip, "18", "fan_pwm", 0, 0);
    if (!pwm_line) {
        fprintf(stderr, "Failed to request GPIO18 for PWM.\n");
        gpiod_chip_unexport(chip);
        return 1;
    }

    if (pigpio_start() < 0) {
        fprintf(stderr, "Failed to start pigpio.\n");
        gpiod_line_release(pwm_line);
        gpiod_chip_unexport(chip);
        return 1;
    }

    if (pigpio_set_PWM_frequency(18, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency.\n");
        pigpio_stop();
        gpiod_line_release(pwm_line);
        gpiod_chip_unexport(chip);
        return 1;
    }

    while (1) {
        int temperature = read_temperature();
        if (temperature >= 0) {
            int duty_cycle = compute_duty_cycle(temperature);
            buffer[buffer_head].timestamp = time(NULL);
            buffer[buffer_head].temperature = temperature;
            buffer[buffer_head].duty_cycle = duty_cycle;
            buffer_head = (buffer_head + 1) % BUFFER_SIZE;

            if (pigpio_set_PWM_dutycycle(18, duty_cycle) < 0) {
                fprintf(stderr, "Failed to set PWM duty cycle.\n");
            }
        }

        sleep(1);
    }

    gpiod_line_release(pwm_line);
    gpiod_chip_unexport(chip);
    pigpio_stop();

    return 0;
}

