#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_TEMP 0xF6
#define BMP180_REG_PRESSURE 0xF6
#define BMP180_REG_STATUS 0xF3
#define BMP180_OSS_3 0x03

int g_logging = 0;
int g_gpio_fd = -1;
int g_i2c_fd = -1;

void handle_sigint(int signum) {
    if (g_i2c_fd != -1) {
        close(g_i2c_fd);
    }
    if (g_gpio_fd != -1) {
        gpiod_line_release(g_gpio_fd);
        close(g_gpio_fd);
    }
    exit(0);
}

int read_i2c_register(int fd, uint8_t reg, uint8_t *data, int len) {
    int ret = 0;
    uint8_t buf[len + 1];

    buf[0] = reg;
    ret = write(fd, buf, len + 1);
    if (ret != len + 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    ret = read(fd, data, len);
    if (ret != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

int write_i2c_register(int fd, uint8_t reg, uint8_t *data, int len) {
    int ret = 0;
    uint8_t buf[len + 1];

    buf[0] = reg;
    memcpy(buf + 1, data, len);
    ret = write(fd, buf, len + 1);
    if (ret != len + 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

int read_calibration_data(int fd, int *ac1, int *ac2, int *ac3, int *ac4, int *ac5, int *ac6, int *b1, int *b2, int *mb, int *mc, int *md) {
    uint8_t data[15];

    if (read_i2c_register(fd, BMP180_REG_CAL_AC1, data, 15) < 0) {
        return -1;
    }

    *ac1 = (data[0] << 8) | data[1];
    *ac2 = (data[2] << 8) | data[3];
    *ac3 = (data[4] << 8) | data[5];
    *ac4 = (data[6] << 8) | data[7];
    *ac5 = (data[8] << 8) | data[9];
    *ac6 = (data[10] << 8) | data[11];
    *b1 = (data[12] << 8) | data[13];
    *b2 = (data[14] << 8) | data[15];
    *mb = (data[16] << 8) | data[17];
    *mc = (data[18] << 8) | data[19];
    *md = (data[20] << 8) | data[21];

    return 0;
}

int read_temperature(int fd, int oss) {
    uint8_t data[3];

    if (write_i2c_register(fd, BMP180_REG_CONTROL, &oss, 1) < 0) {
        return -1;
    }

    usleep(5 + (4 << oss));

    if (read_i2c_register(fd, BMP180_REG_TEMP, data, 3) < 0) {
        return -1;
    }

    int raw_temp = (data[0] << 8) | data[1];
    int x1 = ((raw_temp >> 3) - (int)BMP180_AC6 * 2) * (int)BMP180_AC5 >> 15;
    int x2 = ((int)BMP180_MC << 11) / (x1 + (int)BMP180_MD);
    int b5 = x1 + x2;
    int temp = (b5 + 8) >> 4;

    return temp;
}

int read_pressure(int fd, int oss) {
    uint8_t data[3];

    if (write_i2c_register(fd, BMP180_REG_CONTROL, &oss, 1) < 0) {
        return -1;
    }

    usleep(5 + (4 << oss));

    if (read_i2c_register(fd, BMP180_REG_PRESSURE, data, 3) < 0) {
        return -1;
    }

    int raw_pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    int x1 = ((int)BMP180_AC5 * (b5 >> 8) - (int)BMP180_MC * 2048) >> 11;
    int x2 = ((int)BMP180_MD * (b5 >> 12) * (b5 >> 12)) >> 12;
    int x3 = x1 + x2;
    int b3 = (((int)BMP180_AC1 * 4 + x3) << oss) + 2 >> 2;
    int b6 = b5 - b3;
    int x1 = (b2 * (b6 * b6 >> 12)) >> 11;
    int x2 = (int)BMP180_AC2 * b6 >> 11;
    int x3 = x1 + x2;
    int b4 = ((int)BMP180_AC3 * b6 >> 13) + (int)BMP180_AC4 * 2048;
    int b7 = (uint32_t)b6 * b6 >> 15;
    int p = (b7 * (uint32_t)BMP180_AC1) >> 14;
    int x1 = (p * p >> 12) * (p * p >> 12);
    int x1 = (x1 * 3038 >> 16) + (p * 2) * 2;
    int x2 = (-7357 * p >> 16);
    int pressure = (p + x1 + x2 + 3791) >> 4;

    return pressure;
}

int main() {
    int ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md;
    int temperature, pressure;
    char timestamp[20];
    FILE *log_file;

    if (gpioInitialise() < 0) {
