int read_i2c_register(int fd, uint8_t reg, uint8_t *data, int len) {
    int ret = 0;
    uint8_t buf[len + 1];

    buf[0] = reg;
    ret = write(fd, buf, len + 1);
    if (ret != len + 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    ret = read(fd, data, len);
    if (ret != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

int write_i2c_register(int fd, uint8_t reg, uint8_t *data, int len) {
    int ret = 0;
    uint8_t buf[len + 1];

    buf[0] = reg;
    memcpy(buf + 1, data, len);
    ret = write(fd, buf, len + 1);
    if (ret != len + 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

int read_calibration_data(int fd, int *ac1, int *ac2, int *ac3, int *ac4, int *ac5, int *ac6, int *b1, int *b2, int *mb, int *mc, int *md) {
    uint8_t data[15];

    if (read_i2c_register(fd, BMP180_REG_CAL_AC1, data, 15) < 0) {
