    }

    *ac1 = (data[0] << 8) | data[1];
    *ac2 = (data[2] << 8) | data[3];
    *ac3 = (data[4] << 8) | data[5];
    *ac4 = (data[6] << 8) | data[7];
    *ac5 = (data[8] << 8) | data[9];
