#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CS_GPIO 8

#define MAX31865_ADDR 0x48
#define MAX31865_REG_FAULT 0x00
#define MAX31865_REG_TEMP 0x01

#define MAX31865_RTD_MODE 0x01
#define MAX31865_BIAS_ON 0x02

#define MAX31865_FAULT_SENSOR_ABSENT 0x01
#define MAX31865_FAULT_READ_ERROR 0x02

#define CALLENDAR_VAN_DUSEN_A 3.9083e-3
#define CALLENDAR_VAN_DUSEN_B -5.775e-7
#define CALLENDAR_VAN_DUSEN_C -4.183e-12

static int spi_fd;
static int log_fd;

void handle_signal(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fd >= 0) {
        fclose(log_fd);
    }
    exit(signum);
}

int read_temperature() {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long) &MAX31865_ADDR,
        .rx_buf = (unsigned long) &MAX31865_REG_TEMP,
        .len = 2,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI read failed");
        return -1;
    }

    int fault_status = *(unsigned char *) &MAX31865_REG_FAULT;
    if (fault_status & MAX31865_FAULT_SENSOR_ABSENT) {
        fprintf(stderr, "Sensor absent condition detected\n");
        return -1;
    }
    if (fault_status & MAX31865_FAULT_READ_ERROR) {
        fprintf(stderr, "Read error detected\n");
        return -1;
    }

    int temp_msb = *(unsigned char *) &MAX31865_REG_TEMP;
    int temp_lsb = *(unsigned char *) &MAX31865_REG_TEMP + 1;
    int temperature = (temp_msb << 8) | temp_lsb;

    double t = temperature / 100.0;
    double r = 100.0 * (1.0 + CALLENDAR_VAN_DUSEN_A * t + CALLENDAR_VAN_DUSEN_B * t * t + CALLENDAR_VAN_DUSEN_C * t * t * t);
    double temp_celsius = (r - 100.0) / (CALLENDAR_VAN_DUSEN_A + 2 * CALLENDAR_VAN_DUSEN_B * t + 3 * CALLENDAR_VAN_DUSEN_C * t * t);

    return (int) temp_celsius;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to configure SPI device");
        close(spi_fd);
        return 1;
    }

    log_fd = fopen("rtd_log.csv", "w");
    if (log_fd == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    fprintf(log_fd, "Timestamp,Temperature\n");

    while (1) {
        int temperature = read_temperature();
        if (temperature >= 0) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            fprintf(log_fd, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
                    now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                    now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, temperature);
        }
        usleep(5000000); // Sleep for 5 seconds
    }

    fclose(log_fd);
    close(spi_fd);
    return 0;
}

