#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <time.h>

#define BMP180_I2C_ADDR 0x77
#define BUFFER_SIZE 120 // 60 seconds * 2 samples per second
#define BMP180_SAMPLE_INTERVAL 50 // 50 ms

struct pressure_sample {
    time_t timestamp;
    int pressure;
};

struct pressure_sample buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void handle_sigint(int signum) {
    gpiod_release(gpiobuf);
    close(i2c_fd);
    gpio_reset(24);
    pigpiod_stop();
    exit(0);
}

int read_pressure(int i2c_fd) {
    uint8_t data[3];
    int result = i2c_smbus_read_i2c_block_data(i2c_fd, BMP180_I2C_ADDR, 0xF4, data, 3);
    if (result < 0) {
        fprintf(stderr, "Error reading pressure from BMP180\n");
        return -1;
    }

    int pressure = (data[0] << 8) | data[1];
    return pressure;
}

void update_buffer(int pressure) {
    time_t now = time(NULL);
    buffer[buffer_head].timestamp = now;
    buffer[buffer_head].pressure = pressure;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    if (buffer_head == buffer_tail) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }
}

double compute_rolling_average() {
    int sum = 0;
    int count = 0;
    for (int i = buffer_tail; i != buffer_head; i = (i + 1) % BUFFER_SIZE) {
        sum += buffer[i].pressure;
        count++;
    }
    return (double)sum / count;
}

int main() {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiomem");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpiod_line *gpiobuf = gpiod_line_request(chip, "24", "Alert", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!gpiobuf) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        gpiod_line_release(gpiobuf);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int pressure = read_pressure(i2c_fd);
        if (pressure < 0) {
            continue;
        }

        update_buffer(pressure);

        double avg_pressure = compute_rolling_average();
        if (abs(pressure - avg_pressure) > 5) {
            printf("Alert: Current pressure %d hPa deviates by more than 5 hPa from the average %.2f hPa\n", pressure, avg_pressure);
            gpiod_line_set_value(gpiobuf, 1);
        } else {
            gpiod_line_set_value(gpiobuf, 0);
        }

        usleep(BMP180_SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

