#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define FAN_FREQ 25000
#define FAN_DUTY_MIN 0
#define FAN_DUTY_MAX 255
#define TEMP_MIN 40
#define TEMP_MAX 70
#define LOG_INTERVAL 5
#define LOG_FILE "fan_log.txt"

void handle_signal(int signum) {
    if (gpioPWM(FAN_GPIO, FAN_DUTY_MIN) < 0) {
        fprintf(stderr, "Failed to stop PWM on GPIO%d\n", FAN_GPIO);
    }
    if (fclose(fopen(LOG_FILE, "a")) != 0) {
        fprintf(stderr, "Failed to close log file\n");
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        fclose(log_file);
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, FAN_FREQ) < 0) {
        perror("Failed to set PWM frequency");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        char temp_str[10];
        FILE *temp_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
        if (temp_file == NULL) {
            perror("Failed to open temperature file");
            continue;
        }

        if (fgets(temp_str, sizeof(temp_str), temp_file) == NULL) {
            perror("Failed to read temperature");
            fclose(temp_file);
            continue;
        }

        fclose(temp_file);

        int temp = atoi(temp_str);
        int duty_cycle = (temp - TEMP_MIN) * (FAN_DUTY_MAX - FAN_DUTY_MIN) / (TEMP_MAX - TEMP_MIN);
        duty_cycle = (duty_cycle < FAN_DUTY_MIN) ? FAN_DUTY_MIN : (duty_cycle > FAN_DUTY_MAX) ? FAN_DUTY_MAX : duty_cycle;

        if (gpioPWM(FAN_GPIO, duty_cycle) < 0) {
            perror("Failed to set PWM duty cycle");
            continue;
        }

        char timestamp[32];
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s, Temperature: %d°C, Duty Cycle: %d%%\n", timestamp, temp, duty_cycle);
        fflush(log_file);

        sleep(LOG_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

