#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LM75_ADDR 0x48
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0

struct temperature_data {
    double temperature;
    pthread_mutex_t mutex;
    int buffer[BUFFER_SIZE];
    int head;
    int tail;
    double running_average;
};

static struct temperature_data data;

void *read_temperature_thread(void *arg) {
    int fd;
    char buffer[2];
    int i2c_result;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        i2c_result = read(fd, buffer, 2);
        if (i2c_result != 2) {
            perror("Failed to read temperature from LM75");
            close(fd);
            exit(EXIT_FAILURE);
        }

        pthread_mutex_lock(&data.mutex);
        data.buffer[data.head] = (buffer[0] << 8) | buffer[1];
        data.head = (data.head + 1) % BUFFER_SIZE;
        if (data.head == data.tail) {
            data.tail = (data.tail + 1) % BUFFER_SIZE;
        }
        pthread_mutex_unlock(&data.mutex);

        usleep(1000000); // Sleep for 1 second
    }

    close(fd);
    return NULL;
}

void *drive_led_thread(void *arg) {
    struct gpiod_line *line;
    int result;

    line = gpiod_line_request(18, "LED", 0);
    if (!line) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    result = gpiod_line_direction_set(line, GPIOF_OUT);
    if (result < 0) {
        perror("Failed to set GPIO direction");
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    while (1) {
        pthread_mutex_lock(&data.mutex);
        if (data.running_average > TEMP_THRESHOLD) {
            result = gpiod_line_value_set(line, 1);
        } else {
            result = gpiod_line_value_set(line, 0);
        }
        pthread_mutex_unlock(&data.mutex);

        if (result < 0) {
            perror("Failed to set GPIO value");
            gpiod_line_free(line);
            exit(EXIT_FAILURE);
        }

        usleep(1000000); // Sleep for 1 second
    }

    gpiod_line_free(line);
    return NULL;
}

void update_running_average() {
    double sum = 0.0;
    int i;

    pthread_mutex_lock(&data.mutex);
    for (i = 0; i < BUFFER_SIZE; i++) {
        sum += data.buffer[i];
    }
    data.running_average = sum / BUFFER_SIZE;
    pthread_mutex_unlock(&data.mutex);
}

void cleanup() {
    pthread_mutex_destroy(&data.mutex);
    gpiod_line_free(data.line);
    close(data.fd);
}

void handle_sigint(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    pthread_t read_thread, led_thread;

    if (pthread_mutex_init(&data.mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&read_thread, NULL, read_temperature_thread, NULL) != 0) {
        perror("Failed to create read thread");
        pthread_mutex_destroy(&data.mutex);
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&led_thread, NULL, drive_led_thread, NULL) != 0) {
        perror("Failed to create LED thread");
        pthread_mutex_destroy(&data.mutex);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        update_running_average();
        sleep(1);
    }

    cleanup();
    pthread_join(read_thread, NULL);
    pthread_join(led_thread, NULL);

    return EXIT_SUCCESS;
}

