#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <json-c/json.h>

#define TARGET_TEMP 25.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define PWM_FREQUENCY 1000
#define PWM_DUTY_RANGE 1000
#define SPI_MODE 1
#define SPI_SPEED 500000
#define SPI_CS 0
#define SPI_CHANNEL 0
#define MAX31865_ADDR 0x48
#define MAX31865_READ_REG 0x00
#define MAX31865_FAULT_REG 0x01
#define MAX31865_TEMP_REG 0x02
#define MAX31865_REF_REG 0x03
#define MAX31865_MAX_TEMP 80.0

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

double read_temperature() {
    uint8_t buffer[4];
    int result = spiRead(SPI_CHANNEL, MAX31865_ADDR, MAX31865_READ_REG, 4, buffer);
    if (result != 4) {
        fprintf(stderr, "Failed to read temperature from MAX31865\n");
        return -1.0;
    }

    uint16_t temp_reg = (buffer[0] << 8) | buffer[1];
    uint8_t fault_reg = buffer[2];

    if (fault_reg & 0x01) {
        fprintf(stderr, "MAX31865 fault detected\n");
        return -1.0;
    }

    double temperature = (double)temp_reg / 4.0;
    return temperature;
}

void pid_control(double target_temp, double Kp, double Ki, double Kd, double *duty_cycle) {
    static double prev_error = 0.0;
    static double integral = 0.0;
    double current_temp = read_temperature();

    if (current_temp < 0.0) {
        fprintf(stderr, "Failed to read temperature\n");
        return;
    }

    double error = target_temp - current_temp;
    integral += error;
    double derivative = error - prev_error;

    *duty_cycle = Kp * error + Ki * integral + Kd * derivative;
    *duty_cycle = (*duty_cycle > 0.0) ? *duty_cycle : 0.0;
    *duty_cycle = (*duty_cycle < 100.0) ? *duty_cycle : 100.0;

    prev_error = error;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    json_object *json_config = json_tokener_parse_ex(json_tokener_new(), "config.json");
    if (!json_config) {
        fprintf(stderr, "Failed to parse JSON configuration file\n");
        return 1;
    }

    json_object *target_temp_obj = json_object_object_get(json_config, "target_temp");
    if (target_temp_obj) {
        TARGET_TEMP = json_object_get_double(target_temp_obj);
    }

    json_object *Kp_obj = json_object_object_get(json_config, "Kp");
    if (Kp_obj) {
        Kp = json_object_get_double(Kp_obj);
    }

    json_object *Ki_obj = json_object_object_get(json_config, "Ki");
    if (Ki_obj) {
        Ki = json_object_get_double(Ki_obj);
    }

    json_object *Kd_obj = json_object_object_get(json_config, "Kd");
    if (Kd_obj) {
        Kd = json_object_get_double(Kd_obj);
    }

    json_object_put(json_config);

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_CS) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    if (gpioSetPWMfrequency(18, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    double duty_cycle = 0.0;
    pid_control(TARGET_TEMP, Kp, Ki, Kd, &duty_cycle);
    gpioSetPWMdutycycle(18, duty_cycle * PWM_DUTY_RANGE / 100.0);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        pid_control(TARGET_TEMP, Kp, Ki, Kd, &duty_cycle);
        if (duty_cycle > 0.0) {
            gpioSetPWMdutycycle(18, duty_cycle * PWM_DUTY_RANGE / 100.0);
        } else {
            gpioSetPWMdutycycle(18, 0.0);
        }

        sleep(1);
    }

    gpioSetPWMdutycycle(18, 0.0);
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

