#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TARGET_TEMP 25.0
#define MAX_DUTY_CYCLE 80
#define SPI_SPEED 2000000
#define SPI_CS GPIO_LINE_ACTIVE_LOW
#define SPI_MISO GPIO_LINE_ACTIVE_LOW
#define SPI_MOSI GPIO_LINE_ACTIVE_LOW
#define SPI_CLK GPIO_LINE_ACTIVE_LOW
#define GPIO_HEATER 17

static gpiod_chip *chip;
static gpiod_line *cs_line, *miso_line, *mosi_line, *sclk_line, *heater_line;
static gpiod_spi *spi;
static FILE *log_file;

void handle_signal(int signum) {
    gpiod_line_set_value(heater_line, 0);
    gpiod_spi_close(spi);
    fclose(log_file);
    gpiod_chip_put(chip);
    exit(signum);
}

void read_temperature() {
    int16_t raw_temp;
    int error;

    error = gpiod_spi_transfer(spi, &raw_temp, 2, 0);
    if (error != 0) {
        fprintf(log_file, "SPI read failure at %s\n", ctime(&time(NULL)));
        gpiod_line_set_value(heater_line, 0);
        return;
    }

    if (raw_temp < 0) {
        fprintf(log_file, "MAX31855 fault condition at %s\n", ctime(&time(NULL)));
        gpiod_line_set_value(heater_line, 0);
        return;
    }

    double temperature = (double)raw_temp * 0.25;
    fprintf(log_file, "%s,%.1f\n", ctime(&time(NULL)), temperature);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiomem");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    cs_line = gpiod_line_request_by_name(chip, "8", "CS", GPIO_LINE_ACTIVE_LOW);
    miso_line = gpiod_line_request_by_name(chip, "9", "MISO", GPIO_LINE_ACTIVE_LOW);
    mosi_line = gpiod_line_request_by_name(chip, "10", "MOSI", GPIO_LINE_ACTIVE_LOW);
    sclk_line = gpiod_line_request_by_name(chip, "11", "SCLK", GPIO_LINE_ACTIVE_LOW);
    heater_line = gpiod_line_request_by_name(chip, "17", "HEATER", GPIO_LINE_ACTIVE_LOW);

    if (!cs_line || !miso_line || !mosi_line || !sclk_line || !heater_line) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    spi = gpiod_spi_open(chip, 0, SPI_SPEED, SPI_CS);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI interface\n");
        gpiod_line_free(cs_line);
        gpiod_line_free(miso_line);
        gpiod_line_free(mosi_line);
        gpiod_line_free(sclk_line);
        gpiod_line_free(heater_line);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    log_file = fopen("heater_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
