int main() {
    int fd;
    char temp_str[10];
    int temp;
    int red_duty = 255, green_duty = 255, blue_duty = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((fd = open("/sys/class/thermal/thermal_zone0/temp", O_RDONLY)) < 0) {
        perror("Failed to open temperature file");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        if (read(fd, temp_str, sizeof(temp_str)) != sizeof(temp_str) - 1) {
            if (ferror(fd)) {
                perror("Failed to read temperature");
                continue;
            }
        }

        temp = atoi(temp_str);

        if (temp < 40000) {
            red_duty = 255;
            green_duty = 255;
            blue_duty = 0;
        } else if (temp < 60000) {
            red_duty = 255;
            green_duty = 0;
            blue_duty = 255;
        } else {
            red_duty = 0;
            green_duty = 255;
            blue_duty = 0;
        }

        if (gpioPWM(17, red_duty) < 0) {
            fprintf(stderr, "Failed to set PWM for Red\n");
            return 1;
        }
        if (gpioPWM(18, green_duty) < 0) {
            fprintf(stderr, "Failed to set PWM for Green\n");
            return 1;
        }
        if (gpioPWM(27, blue_duty) < 0) {
            fprintf(stderr, "Failed to set PWM for Blue\n");
            return 1;
        }

        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temp, red_duty, green_duty, blue_duty);

        usleep(500000); // 0.5 seconds
    }

    close(fd);
    gpioTerminate();

    return 0;
}

