#define DHT22_CMD 0x00

static int retry_count = 0;

void cleanup(int signum) {
    if (gpiod_line_get_value(line) == 1) {
        gpiod_line_set_value(line, 0);
    }
    gpiod_line_free(line);
    gpiod_chip_free(chip);
    curl_global_cleanup();
    exit(0);
