int read_dht22(int *humidity, int *temperature) {
    int fd = open(DHT22_DATA_LINE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open 1-wire bus");
        return -1;
    }

    int ret = ioctl(fd, 0x40, &DHT22_ADDR);
    if (ret < 0) {
        perror("Failed to set DHT22 address");
        close(fd);
        return -1;
    }

    ret = write(fd, &DHT22_CMD, 1);
    if (ret < 0) {
        perror("Failed to write command to DHT22");
        close(fd);
        return -1;
    }

    usleep(1000); // Wait for 1 ms

    uint8_t data[5];
    ret = read(fd, data, 5);
    if (ret != 5) {
        perror("Failed to read DHT22 data");
        close(fd);
        return -1;
    }

    close(fd);

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum mismatch\n");
        return -1;
    }

    *humidity = (data[0] << 8) | data[1];
    *temperature = (data[2] << 8) | data[3];

    return 0;
}

