        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "gpio4", &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_free(chip);
        return 1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    CURL *curl;
    CURLcode res;
    char payload[100];

    while (retry_count < MAX_RETRIES) {
        int humidity, temperature;
        if (read_dht22(&humidity, &temperature) == 0) {
            snprintf(payload, sizeof(payload), "{\"humidity\":%d,\"temperature\":%d}", humidity, temperature);

            curl = curl_easy_init();
            if (curl) {
                curl_easy_setopt(curl, CURLOPT_URL, "http://yourserver.com/api/humidity");
                curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
                curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, strlen(payload));
                curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);

                res = curl_easy_perform(curl);
                if (res != CURLE_OK) {
                    fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                } else {
                    retry_count = MAX_RETRIES; // Successful post, exit loop
                }

                curl_easy_cleanup(curl);
            }
        } else {
            retry_count++;
            sleep(1); // Wait before retrying
        }
    }

    cleanup(0); // Clean up resources
    return 0;
}

