#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_TEMP 0xF6
#define BMP180_REG_PRESS 0xF6
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define OSS 3
#define DEBOUNCE_TIME 200000

static int i2c_fd;
static int logging_enabled = 0;
static struct gpiod_line *button_line;
static struct gpiod_line *interrupt_line;
static struct gpiod_chip *button_chip;
static struct gpiod_chip *interrupt_chip;
static unsigned long last_interrupt_time = 0;

void handle_interrupt(int line, struct gpiod_line *line_gpiod, void *data) {
    unsigned long now = gpiod_get_value(line_gpiod);
    if (now == 0 && (gpiod_get_value(button_line) == 0)) {
        if (gpiod_get_value(interrupt_line) == 0) {
            if (time(NULL) - last_interrupt_time >= DEBOUNCE_TIME / 1000000) {
                logging_enabled = !logging_enabled;
                if (logging_enabled) {
                    printf("Logging enabled.\n");
                } else {
                    printf("Logging disabled.\n");
                }
            }
            last_interrupt_time = time(NULL);
        }
    }
}

void cleanup() {
    gpiod_line_free(button_line);
    gpiod_line_free(interrupt_line);
    gpiod_chip_put(button_chip);
    gpiod_chip_put(interrupt_chip);
    close(i2c_fd);
    exit(0);
}

void handle_sigint(int signum) {
    cleanup();
}

int read_i2c_reg(int reg) {
    int ret;
    char buf[2];

    ret = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (ret < 0) {
        perror("i2c_smbus_read_byte_data");
        cleanup();
        return -1;
    }
    return ret;
}

int write_i2c_reg(int reg, int value) {
    int ret;

    ret = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (ret < 0) {
        perror("i2c_smbus_write_byte_data");
        cleanup();
        return -1;
    }
    return 0;
}

int main() {
    int ret;
    int calibration_data[11];
    int pressure;
    struct timespec delay;
    FILE *log_file;

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl");
        return 1;
    }

    if ((button_chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    if ((button_line = gpiod_line_request_by_name(button_chip, "4", "button", GPIOD_LINE_DIRECTION_IN)) == NULL) {
        perror("gpiod_line_request_by_name");
        return 1;
    }

    if ((interrupt_chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    if ((interrupt_line = gpiod_line_request_by_name(interrupt_chip, "4", "interrupt", GPIOD_LINE_DIRECTION_IN)) == NULL) {
        perror("gpiod_line_request_by_name");
        return 1;
    }

    gpiod_line_set_debounce(interrupt_line, DEBOUNCE_TIME);
    gpiod_line_set_edge(interrupt_line, GPIOD_LINE_BOTH_EDGES);
    gpiod_line_set_consumer(interrupt_line, "BMP180_interrupt");
    gpiod_line_set_debounce(button_line, DEBOUNCE_TIME);
    gpiod_line_set_consumer(button_line, "BMP180_button");

    gpiod_line_add_event_handler(interrupt_line, handle_interrupt, NULL);

    for (int i = 0; i < 11; i++) {
        calibration_data[i] = read_i2c_reg(BMP180_REG_CAL_AC1 + i * 2);
        if (calibration_data[i] < 0) {
            fprintf(stderr, "Failed to read calibration data.\n");
            cleanup();
            return 1;
        }
    }

    write_i2c_reg(BMP180_REG_CONTROL, OSS << 6 | 0x27);

    signal(SIGINT, handle_sigint);

    while (1) {
        if (logging_enabled) {
            write_i2c_reg(BMP180_REG_CONTROL, OSS << 6 | 0x34);
            usleep(26000);
            pressure = read_i2c_reg(BMP180_REG_PRESS);
            if (pressure < 0) {
                fprintf(stderr, "Failed to read pressure.\n");
                cleanup();
                return 1;
            }

            log_file = fopen("pressure_log.txt", "a");
            if (log_file == NULL) {
                perror("fopen");
                cleanup();
                return 1;
            }

            time_t now = time(NULL);
