#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libi2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define MAX_RETRIES 3
#define FLOW_LOG_FILE "flow_log.txt"

static int i2c_fd;
static int retries;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        i2c_close(i2c_fd);
    }
    exit(signum);
}

int read_sensor(int sensor_id) {
    int data[3];
    int crc_calculated, crc_received;

    for (retries = 0; retries < MAX_RETRIES; retries++) {
        if (i2c_read_i2c_block_data(i2c_fd, I2C_ADDR, sensor_id, data, 3) < 0) {
            if (retries < MAX_RETRIES - 1) {
                printf("I2C error reading sensor %d, retrying...\n", sensor_id);
                sleep(1);
            }
            continue;
        }

        crc_calculated = (data[0] << 8) | data[1];
        crc_received = data[2];

        if (crc_calculated == crc_received) {
            return 1; // Valid reading
        }

        printf("CRC check failed for sensor %d, retrying...\n", sensor_id);
    }

    return 0; // CRC check failed after retries
}

int main() {
    struct sigaction sa;
    struct timespec ts;
    char timestamp[20];
    char log_entry[50];

    if ((i2c_fd = i2c_open(I2C_BUS, 0)) < 0) {
        perror("i2c_open");
        return 1;
    }

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", now_tm);

        if (read_sensor(0)) {
            sprintf(log_entry, "%s,flow1,", timestamp);
            FILE *log_file = fopen(FLOW_LOG_FILE, "a");
            if (log_file) {
                fprintf(log_file, "%s", log_entry);
                fclose(log_file);
            }
        }

        if (read_sensor(1)) {
            sprintf(log_entry, "%s,flow2", timestamp);
            FILE *log_file = fopen(FLOW_LOG_FILE, "a");
            if (log_file) {
                fprintf(log_file, "%s", log_entry);
                fclose(log_file);
            }
        }

        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    return 0;
}

