#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_A 17
#define GPIO_B 18
#define FILE_NAME "encoder_log.txt"

static gpiod_chip *chip;
static gpiod_line *line_a, *line_b;
static FILE *log_file;

static int state = 0;
static int prev_state = 0;
static double angle = 0.0;

void cleanup(int signum) {
    if (line_a) {
        gpiod_line_free(line_a);
        line_a = NULL;
    }
    if (line_b) {
        gpiod_line_free(line_b);
        line_b = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(signum);
}

void handle_interrupt(int signum) {
    cleanup(signum);
}

void update_angle(int new_state) {
    int diff = new_state - prev_state;
    switch (diff) {
        case 1:
        case -3:
            angle += 90.0;
            break;
        case 3:
        case -1:
            angle -= 90.0;
            break;
    }
    angle = fmod(angle + 360.0, 360.0);
    prev_state = new_state;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_interrupt;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line_a = gpiod_line_request_any(chip, "A", GPIO_A, 0);
    if (!line_a) {
        perror("Failed to request GPIO line A");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    line_b = gpiod_line_request_any(chip, "B", GPIO_B, 0);
    if (!line_b) {
        perror("Failed to request GPIO line B");
        gpiod_line_free(line_a);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_direction_set(line_a, GPIO_LINE_DIRECTION_OUTPUT);
    gpiod_line_direction_set(line_b, GPIO_LINE_DIRECTION_OUTPUT);

    gpiod_line_set_value(line_a, 1);
    gpiod_line_set_value(line_b, 1);

    gpiod_line_request_pull_up_down(line_a, GPIO_LINE_PULL_UP);
    gpiod_line_request_pull_up_down(line_b, GPIO_LINE_PULL_UP);

    log_file = fopen(FILE_NAME, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_free(line_b);
        gpiod_line_free(line_a);
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    while (1) {
        int state_a = gpiod_line_get_value(line_a);
        int state_b = gpiod_line_get_value(line_b);
        int new_state = (state_a << 1) | state_b;

        if (new_state != prev_state) {
            update_angle(new_state);
            fprintf(log_file, "Angle: %.2f degrees\n", angle);
            fflush(log_file);
        }

        usleep(10000); // Adjust sleep time as needed
    }

    cleanup(0);
    return 0;
}

