#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define LED_GPIO 17
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"

static int i2c_fd;
static struct gpiod_line *led_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (led_line) {
        gpiod_line_request_release(led_line);
        gpiod_chip_put(led_line->chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct i2c_rdwr_ioctl_data msg;
    struct i2c_msg msg_read[1];
    struct i2c_msg msg_write[1];
    uint8_t data[2];
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;
    struct timespec ts;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C device");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "ADPD144RI_LED";
    config.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    config.flags = GPIOD_LINE_ACTIVE_HIGH;

    led_line = gpiod_line_request_from_chip(chip, LED_GPIO, &config);
    if (!led_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_request_release(led_line);
        gpiod_chip_put(chip);
        close(i2c_fd);
        return 1;
    }

    fprintf(log_file, "timestamp,red,ir\n");

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);

        msg_read[0].addr = I2C_ADDR;
        msg_read[0].flags = I2C_M_RD;
        msg_read[0].len = 2;
        msg_read[0].buf = data;

        msg.msgs = msg_read;
        msg.nmsgs = 1;

        if (ioctl(i2c_fd, I2C_RDWR, &msg) < 0) {
            perror("Failed to read from I2C device");
            continue;
        }

        uint16_t red = (data[0] << 8) | data[1];
        uint16_t ir = (data[2] << 8) | data[3];

        gpiod_line_set_value(led_line, ir > THRESHOLD);

        fprintf(log_file, "%ld,%d,%d\n", ts.tv_sec, red, ir);

        fflush(log_file);
        usleep(100000); // 100 ms
    }

    return 0;
}

