#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int pulse_count = 0;

void *isr_thread(void *arg) {
    struct gpiod_line *line;
    struct gpiod_line_request *req;
    struct gpiod_line_consumer *consumer;
    int ret;

    ret = gpiod_line_request_alloc(GPIO_PIN, "RPM_Sensor", &req);
    if (ret < 0) {
        perror("gpiod_line_request_alloc");
        exit(EXIT_FAILURE);
    }

    req->consumer = &consumer;
    req->consumer->name = "RPM_Sensor";
    req->consumer->consumer_id = 0;
    req->consumer->flags = GPIOD_LINE_CONSUMER_FLAG_NOPULL;
    req->consumer->callbacks.event = NULL;
    req->consumer->callbacks.event_private = NULL;
    req->consumer->callbacks.poll = NULL;
    req->consumer->callbacks.poll_private = NULL;
    req->consumer->callbacks.release = NULL;
    req->consumer->callbacks.release_private = NULL;

    ret = gpiod_line_request_apply(req);
    if (ret < 0) {
        perror("gpiod_line_request_apply");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_get(GPIO_PIN, &line);
    if (ret < 0) {
        perror("gpiod_line_get");
        exit(EXIT_FAILURE);
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        if (gpiod_line_get_value(line) == 1) {
            pthread_mutex_lock(&mutex);
            pulse_count++;
            pthread_mutex_unlock(&mutex);
        }
    }

    gpiod_line_free(line);
    gpiod_line_request_free(req);
    return NULL;
}

void log_rpm(double rpm) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld: %.2f RPM\n", (long)ts.tv_sec, (long)ts.tv_nsec, rpm);
    fflush(log_file);
    fclose(log_file);
}

void signal_handler(int signum) {
    pthread_mutex_lock(&mutex);
    pthread_mutex_unlock(&mutex);
    gpiod_line_request_free(NULL);
    fclose(NULL);
    pthread_mutex_destroy(&mutex);
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    pthread_t isr_thread_id;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    pthread_create(&isr_thread_id, NULL, isr_thread, NULL);

    while (1) {
        struct timespec start, end;
        clock_gettime(CLOCK_REALTIME, &start);

        pthread_mutex_lock(&mutex);
        int count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&mutex);

        clock_gettime(CLOCK_REALTIME, &end);
        double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;

        if (elapsed_time >= 1.0) {
            double rpm = (count / elapsed_time) * 60.0;
            log_rpm(rpm);
        }

        usleep(100000); // Sleep for 100ms
    }

    pthread_join(isr_thread_id, NULL);
    return 0;
}

