#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>

#define I2C_ADDR 0x38 // ADPD144RI I2C address
#define LED_GPIO 17
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"

int i2c_fd;
int led_fd;

void cleanup() {
    if (led_fd != -1) {
        close(led_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    remove(LOG_FILE); // Remove log file on cleanup
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int read_sensor() {
    int infrared_reading;
    char buffer[2];

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C bus");
        cleanup();
        exit(1);
    }

    // Assuming the infrared reading is stored in the first byte
    infrared_reading = (int)buffer[0];

    return infrared_reading;
}

void log_reading(int infrared_reading) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        exit(1);
    }

    fprintf(log_file, "%s,%d\n", buffer, infrared_reading);
    fclose(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting up signal handlers");
        exit(1);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Error opening I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Error setting I2C slave address");
        cleanup();
        exit(1);
    }

    led_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (led_fd == -1) {
        perror("Error opening GPIO17");
        cleanup();
        exit(1);
    }

    while (1) {
        int infrared_reading = read_sensor();
        log_reading(infrared_reading);

        if (infrared_reading > THRESHOLD) {
            write(led_fd, "1", 1); // Turn on LED
        } else {
            write(led_fd, "0", 1); // Turn off LED
        }

        usleep(100000); // Sleep for 100ms
    }

    cleanup();
    return 0;
}

