    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO17 (OUT) as input
    line_out = gpiod_line_request_by_name(chip, "gpio%d", GPIO_OUT, "audio_input", 0);
    if (!line_out) {
        perror("Failed to request GPIO17 as input");
        goto cleanup;
    }
    ret = gpiod_line_direction_set(line_out, GPIO_LINE_DIRECTION_IN);
    if (ret) {
        perror("Failed to set direction for GPIO17");
        goto cleanup;
    }

    // Request GPIO18 (GAIN) as output and set to LOW (60dB gain)
    line_gain = gpiod_line_request_by_name(chip, "gpio%d", GPIO_GAIN, "gain_select", GPIO_LINE_DIRECTION_OUT);
    if (!line_gain) {
        perror("Failed to request GPIO18 as output");
        goto cleanup;
    }
    ret = gpiod_line_set_value(line_gain, 0);
    if (ret) {
        perror("Failed to set GPIO18 to LOW");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Print startup message
    printf("Audio logging started. Press Ctrl+C to stop.\n");

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        ts.tv_sec = 0;
        ts.tv_nsec = 10000000; // 10ms
        nanosleep(&ts, NULL);

        unsigned int current_level = gpiod_line_get_value(line_out);
        if (current_level != last_level) {
            char timestamp[20];
            time_t rawtime;
            struct tm *timeinfo;

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s %d\n", timestamp, current_level);
            printf("Detected peak sound event at %s\n", timestamp);

            last_level = current_level;
        }
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    return EXIT_FAILURE;
}

