#define GPIO_PIN 17
#define TTP223_TAMPER "ttp223_tamper"
#define DELAY_MS 100
#define ALERT_THRESHOLD_S 5

static struct gpiod_line *line;
static struct timespec start_time;

void cleanup(void) {
    if (line) {
        gpiod_line_request_release(line);
        free(line);
    }
    exit(EXIT_SUCCESS);
}

void handle_signal(int signum) {
    cleanup();
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;
    int ret;

    // Initialize libgpiod
    if ((ret = gpiod_chip_open(NULL, &chip)) < 0) {
        fprintf(stderr, "Failed to open libgpiod: %s\n", strerror(ret));
        exit(EXIT_FAILURE);
    }

    // Request GPIO line
    req = gpiod_line_request_alloc(chip, GPIO_PIN, TTP223_TAMPER,
                                  GPIOD_LINE_DIRECTION_INPUT, 0);
    if (!req) {
        fprintf(stderr, "Failed to allocate line request\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_get(req);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line: %s\n",
                gpiod_line_request_get_error(req));
        gpiod_line_request_free(req);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        int value;

        // Read GPIO value
        if ((ret = gpiod_line_get_value(line, &value)) < 0) {
            fprintf(stderr, "Failed to read GPIO value: %s\n",
                    gpiod_line_get_error(line));
            cleanup();
        }

        // Check for touch event
        if (value == 1) {
            if (start_time.tv_sec == 0) {
                start_time = timespec_now();
            }

            struct timespec now = timespec_now();
            if (timespec_diff(&now, &start_time) >= ALERT_THRESHOLD_S) {
                printf("Intrusion alert!\n");
                start_time = timespec_now();
            }
        } else {
            start_time = (struct timespec){0, 0};
        }

        // Sleep for 100ms
        usleep(DELAY_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

