#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_DO 4 // Flame sensor digital output
#define GPIO_PWM 18 // PWM output for fan
#define DEBOUNCE_TIME 50 // Debounce time in milliseconds
#define PWM_FREQ 100 // PWM frequency in Hz
#define LOG_FILE "flame_log.txt"

static gpiod_chip *chip;
static gpiod_line *flame_sensor;
static gpiod_line *fan_pwm;
static FILE *log_file;

void handle_signal(int signum) {
    if (fan_pwm) {
        gpiod_line_request_free(fan_pwm);
        fan_pwm = NULL;
    }
    if (flame_sensor) {
        gpiod_line_request_free(flame_sensor);
        flame_sensor = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct timespec start_time;
    struct timespec flame_start_time;
    struct timespec flame_end_time;
    struct timespec end_time;
    int sensor_value;
    int debounce_count = 0;
    int sensor_absent_timeout = 0;

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    flame_sensor = gpiod_line_request_by_name(chip, "gpio4", "flame_sensor", 0);
    if (!flame_sensor) {
        perror("Failed to request flame sensor GPIO");
        gpiod_chip_put(chip);
        return 1;
    }

    fan_pwm = gpiod_line_request_by_name(chip, "gpio18", "fan_pwm", 0);
    if (!fan_pwm) {
        perror("Failed to request PWM GPIO");
        gpiod_line_request_free(flame_sensor);
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_direction_set(flame_sensor, GPIO_LINE_DIRECTION_INPUT) < 0) {
        perror("Failed to set flame sensor direction");
        gpiod_line_request_free(fan_pwm);
        gpiod_line_request_free(flame_sensor);
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_direction_set(fan_pwm, GPIO_LINE_DIRECTION_OUTPUT) < 0) {
        perror("Failed to set PWM direction");
        gpiod_line_request_free(fan_pwm);
        gpiod_line_request_free(flame_sensor);
        gpiod_chip_put(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_request_free(fan_pwm);
        gpiod_line_request_free(flame_sensor);
        gpiod_chip_put(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    clock_gettime(CLOCK_REALTIME, &start_time);

    while (1) {
        if (gpiod_line_get_value(flame_sensor) < 0) {
            perror("Failed to read flame sensor");
            break;
        }

        sensor_value = gpiod_line_get_value(flame_sensor);

        if (sensor_value == 0) {
            debounce_count++;
            if (debounce_count >= DEBOUNCE_TIME) {
                debounce_count = 0;
                if (gpiod_line_set_value(fan_pwm, 1) < 0) {
                    perror("Failed to set PWM value");
                    break;
                }
                clock_gettime(CLOCK_REALTIME, &flame_start_time);
                fprintf(log_file, "Flame detected at %s\n", ctime(&flame_start_time.tv_sec));
            }
        } else {
            debounce_count = 0;
            if (gpiod_line_set_value(fan_pwm, 0) < 0) {
                perror("Failed to set PWM value");
                break;
            }
            if (sensor_absent_timeout >= DEBOUNCE_TIME) {
                sensor_absent_timeout = 0;
                fprintf(log_file, "Sensor absent at %s\n", ctime(&start_time.tv_sec));
            }
        }

        usleep(50000); // Sleep for 50 ms
        sensor_absent_timeout++;
    }

    clock_gettime(CLOCK_REALTIME, &end_time);
    fprintf(log_file, "Program terminated at %s\n", ctime(&end_time.tv_sec));
    fclose(log_file);

    return 0;
}

