#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define MAGIC_NUMBER 0x4144
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_TRIGGER 23
#define GPIO_DATA_READY 24
#define FRAME_SIZE 32768
#define FRAME_PERIOD 100

struct config {
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t num_chirps;
    uint32_t num_samples;
};

static struct config radar_config = {
    .start_freq = 77000000000,
    .end_freq = 79000000000,
    .num_chirps = 64,
    .num_samples = 256
};

static int spi_fd;
static struct gpiod_line *trigger_line;
static struct gpiod_line *data_ready_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (trigger_line) {
        gpiod_line_free(trigger_line);
    }
    if (data_ready_line) {
        gpiod_line_free(data_ready_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    int ret;
    uint8_t buffer[FRAME_SIZE];
    uint64_t timestamp;
    uint32_t frame_number = 0;

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open spi");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_RD_MODE");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_RD_MAX_SPEED_HZ");
        return 1;
    }

    trigger_line = gpiod_line_request(GPIO_TRIGGER, "trigger", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!trigger_line) {
        perror("gpiod_line_request trigger");
        return 1;
    }

    data_ready_line = gpiod_line_request(GPIO_DATA_READY, "data_ready", GPIOD_LINE_DIRECTION_INPUT);
    if (!data_ready_line) {
        perror("gpiod_line_request data_ready");
        return 1;
    }

    log_file = fopen("radar_data.bin", "wb");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    fwrite(&MAGIC_NUMBER, sizeof(uint32_t), 1, log_file);
    timestamp = time(NULL);
    fwrite(&timestamp, sizeof(uint64_t), 1, log_file);
    fwrite(&radar_config, sizeof(struct config), 1, log_file);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(100);
        gpiod_line_set_value(trigger_line, 0);

        while (gpiod_line_get_value(data_ready_line) == 0) {
            usleep(100);
        }

        ret = spi_read(spi_fd, buffer, FRAME_SIZE);
        if (ret != FRAME_SIZE) {
            perror("spi_read");
            return 1;
        }

        timestamp = time(NULL);
        fwrite(&timestamp, sizeof(uint64_t), 1, log_file);
        fwrite(&frame_number, sizeof(uint32_t), 1, log_file);
        fwrite(buffer, FRAME_SIZE, 1, log_file);

        frame_number++;
        usleep(FRAME_PERIOD * 1000);
    }

    return 0;
}

