        gpiod_line_put(line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

static void log_flame_state(const char *state) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    if (fprintf(log_file, "%s %s\n", timestamp, state) < 0) {
        perror("Failed to write to log file");
    }
}

int main() {
    int prev_state = -1;
    int current_state;

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    if (gpiod_line_request_any(chip, "flame_sensor", GPIO_PIN, &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO direction to input
    if (gpiod_line_direction_input(line) < 0) {
        perror("Failed to set GPIO direction to input");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen(FILE_NAME, "a")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read current state
        if (gpiod_line_get_value(line, &current_state) < 0) {
            perror("Failed to read GPIO value");
            break;
        }

        // Check for state change
        if (prev_state != -1 && current_state != prev_state) {
            const char *state = current_state ? "flame_detected" : "flame_cleared";
            log_flame_state(state);
        }

        prev_state = current_state;

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_put(line);
    gpiod_chip_put(chip);

    return EXIT_SUCCESS;
}

