#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define OPT3001_ADDR 0x40
#define OPT3001_REG_CONFIG 0x00
#define OPT3001_REG_DATA 0x01
#define OPT3001_CONFIG_CONT_MODE 0x01
#define OPT3001_CONFIG_AUTO_FS 0x02

#define MAX_RETRIES 5
#define RETRY_DELAY 1000 // 1 second

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int i2c_write(uint8_t reg, uint8_t data) {
    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        result = write(i2c_fd, &data, 1);
        if (result == 1) {
            break;
        }

        retries++;
        usleep(RETRY_DELAY);
    }

    return result;
}

int i2c_read(uint8_t reg, uint8_t *data) {
    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        result = read(i2c_fd, data, 1);
        if (result == 1) {
            break;
        }

        retries++;
        usleep(RETRY_DELAY);
    }

    return result;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = i2c_open(1, OPT3001_ADDR);
    if (i2c_fd == -1) {
        perror("i2c_open");
        return EXIT_FAILURE;
    }

    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t config = OPT3001_CONFIG_CONT_MODE | OPT3001_CONFIG_AUTO_FS;
    if (i2c_write(OPT3001_REG_CONFIG, config) != 1) {
        fprintf(stderr, "Failed to configure sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t data[2];
        if (i2c_read(OPT3001_REG_DATA, data) != 1) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_now);

        fprintf(log_file, "%s %02X%02X\n", timestamp, data[0], data[1]);
        fflush(log_file);

        usleep(100000); // 100 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

