#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;
    char buffer[32];
    struct timespec delay = {0, 100000000}; // 1 second delay

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    if ((chip = gpiod_chip_open("/dev/gpiomem")) == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line 17 (BCM) as input with pull-up
    if ((line = gpiod_line_request(chip, 17, "flame_detect", 0, GPIOD_LINE_DIRECTION_IN, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_TYPE_INPUT, GPIOD_LINE_PULL_UP)) == NULL) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        // Read the value from the GPIO line
        if (gpiod_line_get_value(line, &value) < 0) {
            perror("Failed to read GPIO value");
            gpiod_line_release(line);
            gpiod_chip_put(chip);
            return EXIT_FAILURE;
        }

        // Format the timestamp
        time_t rawtime;
        struct tm * timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the status
        if (value == 0) {
            printf("%s Flame Detected: YES\n", buffer);
        } else {
            printf("%s Flame Detected: NO\n", buffer);
        }

        // Sleep for 1 second
        nanosleep(&delay, NULL);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_put(chip);

    return EXIT_SUCCESS;
}

