#include <pigpio.h>

#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        stop = 1;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(LEFT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for left pin.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CENTER_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for center pin.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RIGHT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for right pin.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int left_state = gpioRead(LEFT_PIN);
        int center_state = gpioRead(CENTER_PIN);
        int right_state = gpioRead(RIGHT_PIN);

        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        usleep(50000);
    }

    gpioTerminate();
    return 0;
}

