#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TTP226_CHIP_NAME "/dev/ttp226"
#define GPIO_PINS {2, 3, 4, 5, 6, 7, 8, 9}
#define NUM_PINS 8

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_PINS];

void handle_sigint(int signum) {
    for (int i = 0; i < NUM_PINS; i++) {
        gpiod_line_request_release(lines[i]);
    }
    gpiod_chip_put(chip);
    exit(0);
}

void print_state(const char *timestamp, const int *state) {
    printf("%s: ", timestamp);
    for (int i = 0; i < NUM_PINS; i++) {
        printf("%d", state[i]);
    }
    printf("\n");
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    int state[NUM_PINS];

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the TTP226 chip
    chip = gpiod_chip_open(TTP226_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open TTP226 chip: %s\n", gpiod_error_string(errno));
        return 1;
    }

    // Request GPIO lines
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_line_request_any(chip, GPIO_PINS[i], "TTP226_OUT", GPIOD_LINE_DIRECTION_OUT);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_PINS[i], gpiod_error_string(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_request_release(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
    }

    // Poll and print state
    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        for (int i = 0; i < NUM_PINS; i++) {
            state[i] = gpiod_line_get_value(lines[i]);
        }

        print_state(timestamp, state);

        usleep(100000); // Sleep for 100 ms
    }

    // Cleanup on exit
    for (int i = 0; i < NUM_PINS; i++) {
        gpiod_line_request_release(lines[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

