#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_PINS 8
#define PIN_START 2
#define PIN_END (PIN_START + NUM_PINS - 1)
#define SAMPLE_INTERVAL 100000 // 100 ms

void handle_signal(int signum) {
    printf("\nReceived signal %d, exiting cleanly...\n", signum);
    gpioTerminate();
    exit(signum);
}

void print_sensor_state(int *sensor_state) {
    for (int i = 0; i < NUM_PINS; i++) {
        printf("CH%d=%d ", i + 1, sensor_state[i]);
    }
    printf("\n");
}

int main() {
    int sensor_state[NUM_PINS];
    int pin_numbers[NUM_PINS];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Set up GPIO pins
    for (int i = 0; i < NUM_PINS; i++) {
        pin_numbers[i] = PIN_START + i;
        if (gpioSetMode(pin_numbers[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input.\n", pin_numbers[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(pin_numbers[i], PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set GPIO %d pull-down resistor.\n", pin_numbers[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_PINS; i++) {
            sensor_state[i] = gpioRead(pin_numbers[i]);
        }
        print_sensor_state(sensor_state);
        usleep(SAMPLE_INTERVAL);
    }

    // This point is never reached, but if it were, we'd clean up here.
    return 0;
}

