#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_SENSOR1 4
#define GPIO_SENSOR2 5
#define DELAY_MS 500

static struct gpiod_line *sensor1, *sensor2;

void cleanup(int signum) {
    if (sensor1) {
        gpiod_line_request_release(sensor1);
        free(sensor1);
    }
    if (sensor2) {
        gpiod_line_request_release(sensor2);
        free(sensor2);
    }
    gpiod_chip_put(sensor1->chip);
    gpiod_chip_put(sensor2->chip);
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;

    // Initialize libgpiod
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO4 for sensor1
    if ((req = gpiod_line_request_by_name(chip, "gpio%d", GPIO_SENSOR1)) == NULL) {
        perror("Failed to request GPIO4");
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }
    req->consumer = "hall_effect";
    req->flags = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    req->consumer_gpios = 1;
    req->consumer_gpios[0] = GPIO_SENSOR1;
    req->consumer_gpios_len = 1;
    req->consumer_gpios_flags[0] = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    req->consumer_gpios_flags_len = 1;
    if ((sensor1 = gpiod_line_request_apply(req)) == NULL) {
        perror("Failed to apply GPIO4 request");
        gpiod_line_request_release(req);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO5 for sensor2
    if ((req = gpiod_line_request_by_name(chip, "gpio%d", GPIO_SENSOR2)) == NULL) {
        perror("Failed to request GPIO5");
        gpiod_line_request_release(req);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }
    req->consumer = "hall_effect";
    req->flags = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    req->consumer_gpios = 1;
    req->consumer_gpios[0] = GPIO_SENSOR2;
    req->consumer_gpios_len = 1;
    req->consumer_gpios_flags[0] = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    req->consumer_gpios_flags_len = 1;
    if ((sensor2 = gpiod_line_request_apply(req)) == NULL) {
        perror("Failed to apply GPIO5 request");
        gpiod_line_request_release(req);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up SIGINT handler");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int sensor1_state = gpiod_line_get_value(sensor1);
        int sensor2_state = gpiod_line_get_value(sensor2);

        printf("Sensor 1: %s, Sensor 2: %s\n", sensor1_state ? "LOW" : "HIGH", sensor2_state ? "LOW" : "HIGH");

        usleep(DELAY_MS * 1000);
    }

    return EXIT_SUCCESS;
}

