#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define NUM_PINS 8
#define POLL_INTERVAL 50 // in milliseconds

static struct gpiod_line *lines[NUM_PINS];

void handle_sigint(int signum) {
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_request_release(lines[i]);
        }
    }
    gpiod_chip_put(lines[0]->chip);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;
    struct gpiod_line_consumer *consumer;
    struct timespec ts;
    char timestamp[20];
    int channel_states[NUM_PINS];

    // Initialize signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the GPIO chip
    if (gpiod_chip_open("/dev/gpiomem", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request lines
    for (int i = 0; i < NUM_PINS; i++) {
        req = gpiod_line_request_alloc(chip, GPIO_PINS[i], "touch_sensor", 0, &consumer);
        if (!req) {
            perror("Failed to allocate line request");
            goto cleanup;
        }

        req->consumer = consumer;
        req->consumer_ctx = NULL;
        req->flags = GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request_apply(req) < 0) {
            perror("Failed to apply line request");
            goto cleanup;
        }

        lines[i] = gpiod_line_request_get_line(req);
        if (!lines[i]) {
            perror("Failed to get line");
            goto cleanup;
        }
    }

    // Main loop
    while (1) {
        // Read sensor states
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_get_value(lines[i]) < 0) {
                perror("Failed to read line value");
                goto cleanup;
            }
            channel_states[i] = gpiod_line_get_value(lines[i]);
        }

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

        // Print CSV line
        printf("%s,", timestamp);
        for (int i = 0; i < NUM_PINS; i++) {
            printf("%d", channel_states[i]);
            if (i < NUM_PINS - 1) {
                printf(",");
            }
        }
        printf("\n");

        // Sleep for 50ms
        usleep(POLL_INTERVAL * 1000);
    }

cleanup:
    // Cleanup
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_request_release(lines[i]);
        }
    }
    gpiod_chip_put(chip);

    return 0;
}

