This C program reads an 8-channel TTP226 capacitive touch sensor array connected to the specified GPIO pins on a Raspberry Pi 4 Model B. It configures each line as an input with bias disabled, polls the state of all channels every 50 ms, and writes a CSV line to the console containing an ISO-8601 timestamp followed by the eight channel states. It checks every driver call for failure, handles situations where the library cannot open the device or request any of the lines, installs a SIGINT handler for graceful shutdown, and ensures that every line request and the chip resource are properly released on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define DELAY_MS 100

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pin
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    // Print startup banner
    printf("Tilt Sensor Polling Program\n");

    int prev_state = -1;

    while (!stop) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state == prev_state) {
            continue;
        }

        prev_state = current_state;

        if (current_state == 0) {
            printf("Tilted\n");
        } else {
            printf("Not Tilted\n");
        }

        fflush(stdout);

        usleep(DELAY_MS * 1000);
    }

    // Cleanup
    gpioTerminate();

    return EXIT_SUCCESS;
}

