#define UV_INDEX_REG 0x06
#define ALS_VISIBLE_REG 0x0C

static int i2c_fd = -1;
static FILE *log_file = NULL;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int read_sensor_data() {
    char buffer[2];
    int bytes_read;

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    bytes_read = read(i2c_fd, buffer, 2);
    if (bytes_read != 2) {
        perror("Failed to read sensor data");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

int main() {
    struct sigaction sa;
    struct timespec ts;
    char timestamp[20];
    int uv_index, als_visible;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Read UV index
        uv_index = read_sensor_data();
        if (uv_index < 0) {
            continue;
        }

        // Read ALS visible
        als_visible = read_sensor_data();
        if (als_visible < 0) {
            continue;
        }

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        // Print to console
        printf("Timestamp: %s, UV Index: %d, ALS Visible: %d\n", timestamp, uv_index, als_visible);

        // Append to log file
        fprintf(log_file, "%s, %d, %d\n", timestamp, uv_index, als_visible);

        // Sleep for 1 second
        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    return 0;
}

