#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdbool.h>

#define I2C_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define LOG_FILE "flow_log.txt"
#define GPIO_ALARM 17

// CRC-8 polynomial and initial value for Sensirion SLF3S-0600F
#define CRC_POLY 0x07
#define CRC_INIT 0xFF

// Function to calculate CRC-8
uint8_t crc8(uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow rate from sensor
bool read_flow_rate(int i2c_fd, uint8_t *flow_rate) {
    uint8_t buffer[4];
    if (read(i2c_fd, buffer, 4) != 4) {
        fprintf(stderr, "Error reading from I2C device\n");
        return false;
    }

    uint8_t crc = crc8(buffer, 3);
    if (crc != buffer[3]) {
        fprintf(stderr, "CRC check failed\n");
        return false;
    }

    *flow_rate = (buffer[0] << 8) | buffer[1];
    return true;
}

// Function to handle SIGINT and SIGTERM
void handle_signal(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    // Release GPIO line
    system("echo 0 > /sys/class/gpio/gpio17/value");
    // Close I2C file descriptor
    close(i2c_fd);
    // Close log file
    fclose(log_file);
    exit(0);
}

int main() {
    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Start sensors
    write(i2c_fd, "\x01", 1);
    usleep(100000); // Wait 100 ms

    while (true) {
        uint8_t flow_rate1 = 0, flow_rate2 = 0;
        bool valid_read1 = read_flow_rate(i2c_fd, &flow_rate1);
        bool valid_read2 = read_flow_rate(i2c_fd, &flow_rate2);

        if (valid_read1 && valid_read2) {
            double avg_flow_rate = (flow_rate1 + flow_rate2) / 2.0;
            fprintf(log_file, "%.2f\n", avg_flow_rate);
            fflush(log_file);

            // Drive alarm based on average flow rate
            if (avg_flow_rate < 0.5) {
                system("echo 1 > /sys/class/gpio/gpio17/value");
            } else {
                system("echo 0 > /sys/class/gpio/gpio17/value");
            }
        }

        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

