#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define BUFFER_SIZE 100
#define BUFFER_INDEX 0
#define DEBOUNCE_TIME 50 // ms

struct detection {
    time_t timestamp;
    int detected;
};

struct detection buffer[BUFFER_SIZE];

int buffer_index = 0;

void handle_sigint(int signum) {
    printf("\nReceived SIGINT, releasing resources and dumping buffer...\n");

    // Dump buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Timestamp: %s, Detected: %d\n", ctime(&buffer[i].timestamp), buffer[i].detected);
    }

    // Release resources
    gpiod_chip_put(chip);
    gpiod_line_put(line);

    exit(0);
}

int main() {
    struct gpiod_line *line;
    struct gpiod_chip *chip;
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Get GPIO line
    line = gpiod_line_request_any(chip, "input", "obstacle_sensor", 0);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_put(chip);
        return 1;
    }

    // Set GPIO line to input with pull-up
    ret = gpiod_line_direction_set(line, GPIO_LINE_DIRECTION_IN);
    if (ret) {
        fprintf(stderr, "Failed to set GPIO direction\n");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    ret = gpiod_line_set_value(line, 1); // Enable pull-up
    if (ret) {
        fprintf(stderr, "Failed to set GPIO value\n");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        struct timespec ts = { .tv_sec = 0, .tv_nsec = DEBOUNCE_TIME * 1000000 };
        nanosleep(&ts, NULL);

        int value = gpiod_line_get_value(line);
        if (value == 0) { // Obstacle detected
            buffer[buffer_index].detected = 1;
            buffer[buffer_index].timestamp = time(NULL);
            printf("Obstacle detected at %s\n", ctime(&buffer[buffer_index].timestamp));
        } else {
            buffer[buffer_index].detected = 0;
        }

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    }

    // Cleanup
    gpiod_line_put(line);
    gpiod_chip_put(chip);

    return 0;
}

