#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_DEV "/dev/i2c-1"
#define SENSOR_ADDR 0x20
#define SENSOR_MODE_REG 0x00
#define SENSOR_DATA_REG 0x01
#define SENSOR_DATA_LEN 3
#define CSV_FILE "fan_health.csv"
#define TIMEOUT_SEC 1
#define POLL_INTERVAL_MS 500

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *sda, *scl;

void handle_sigint_sigterm(int signum) {
    gpiod_line_free(sda);
    gpiod_line_free(scl);
    gpiod_chip_put(chip);
    close(i2c_fd);
    exit(signum);
}

int i2c_write(uint8_t reg, uint8_t data) {
    int ret;
    uint8_t buf[2] = {reg, data};
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t reg, uint8_t *data) {
    int ret;
    uint8_t buf[2] = {reg, 0};
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    ret = read(i2c_fd, data, SENSOR_DATA_LEN);
    if (ret != SENSOR_DATA_LEN) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint_sigterm;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "2", "sda", GPIOD_LINE_DIRECTION_OUTPUT, &sda) < 0) {
        perror("Failed to request GPIO2 for SDA");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "3", "scl", GPIOD_LINE_DIRECTION_OUTPUT, &scl) < 0) {
        perror("Failed to request GPIO3 for SCL");
        return 1;
    }

    if (gpiod_line_set_value(sda, 0) < 0) {
        perror("Failed to set SDA line value");
        return 1;
    }

    if (gpiod_line_set_value(scl, 0) < 0) {
        perror("Failed to set SCL line value");
        return 1;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    if (i2c_write(SENSOR_MODE_REG, 0x01) < 0) {
        perror("Failed to set sensor mode");
        return 1;
    }

    struct timespec timeout;
    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_nsec = 0;

    while (1) {
        if (i2c_read(SENSOR_DATA_REG, (uint8_t *) &data) < 0) {
            continue;
        }

        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&now.tv_sec));

        FILE *csv_file = fopen(CSV_FILE, "a");
        if (csv_file == NULL) {
            perror("Failed to open CSV file");
            return 1;
        }

        if (fseek(csv_file, 0, SEEK_END) != 0) {
            perror("Failed to seek to end of CSV file");
            fclose(csv_file);
            return 1;
        }

        if (ftell(csv_file) == 0) {
            fprintf(csv_file, "Timestamp,X,Y,Z\n");
        }

        fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, data[0], data[1], data[2]);
        fclose(csv_file);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpiod_line_free(sda);
    gpiod_line_free(scl);
    gpiod_chip_put(chip);
    close(i2c_fd);

    return 0;
}
```

This code sets up the GPIO lines for SDA and SCL, opens the I2C device, sets the sensor mode, and then enters a loop where it reads the sensor data every 500 milliseconds, appending the timestamp and data to a CSV file. It handles errors by retrying on I2C read/write failures and exits cleanly on SIGINT or SIGTERM.

