#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_OUT_PIN 23
#define SENSOR2_OUT_PIN 24
#define LED_PIN 25

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_OUT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR1_OUT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR2_OUT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR2_OUT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int sensor1_value = gpioRead(SENSOR1_OUT_PIN);
        int sensor2_value = gpioRead(SENSOR2_OUT_PIN);

        if (sensor1_value == 0 || sensor2_value == 0) {
            if (gpioWrite(LED_PIN, PI_ON) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
            }
        } else {
            if (gpioWrite(LED_PIN, PI_OFF) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
            }
        }

        usleep(100000); // Sleep for 100 ms
    }

    if (gpioWrite(LED_PIN, PI_OFF) < 0) {
        fprintf(stderr, "Failed to turn off LED before exit\n");
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

