#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define STALL_LOG_FILE "stall_log.txt"
#define STALL_TIMEOUT 2 // seconds

static struct gpiod_line *sensor1, *sensor2;
static time_t last_stall_time = 0;

void handle_signal(int signum) {
    if (sensor1) {
        gpiod_line_request_free(sensor1);
    }
    if (sensor2) {
        gpiod_line_request_free(sensor2);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int read_sensor(struct gpiod_line *line) {
    int value;
    if (gpiod_line_get_value(line, &value) < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }
    return value;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req1, *req2;
    struct gpiod_line_consumer *consumer;
    struct timespec stall_start;
    FILE *log_file;

    // Initialize libgpiod
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request GPIO lines
    if ((req1 = gpiod_line_request_alloc(chip, GPIO_SENSOR1, "sensor1", 0)) == NULL) {
        perror("gpiod_line_request_alloc");
        goto error_exit;
    }
    if ((req2 = gpiod_line_request_alloc(chip, GPIO_SENSOR2, "sensor2", 0)) == NULL) {
        perror("gpiod_line_request_alloc");
        goto error_exit;
    }

    // Set up sensor lines
    if ((sensor1 = gpiod_line_request_get_line(req1)) == NULL) {
        perror("gpiod_line_request_get_line");
        goto error_exit;
    }
    if ((sensor2 = gpiod_line_request_get_line(req2)) == NULL) {
        perror("gpiod_line_request_get_line");
        goto error_exit;
    }

    // Set up consumer
    if ((consumer = gpiod_line_consumer_alloc(req1, "sensor1_consumer")) == NULL) {
        perror("gpiod_line_consumer_alloc");
        goto error_exit;
    }
    if ((consumer = gpiod_line_consumer_alloc(req2, "sensor2_consumer")) == NULL) {
        perror("gpiod_line_consumer_alloc");
        goto error_exit;
    }

    // Open log file
    if ((log_file = fopen(STALL_LOG_FILE, "a")) == NULL) {
        perror("fopen");
        goto error_exit;
    }

    // Register signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int sensor1_value = read_sensor(sensor1);
        int sensor2_value = read_sensor(sensor2);

        if (sensor1_value < 0 || sensor2_value < 0) {
            continue;
        }

        if (sensor1_value == 0 && sensor2_value == 0) {
            if (clock_gettime(CLOCK_REALTIME, &stall_start) < 0) {
                perror("clock_gettime");
                continue;
            }

            if (last_stall_time == 0 || (stall_start.tv_sec - last_stall_time) >= STALL_TIMEOUT) {
                char timestamp[32];
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                fprintf(log_file, "%s: Stall detected\n", timestamp);
                fflush(log_file);
                last_stall_time = now;
            }
        } else {
            last_stall_time = 0;
        }

        usleep(100000); // Sleep for 100ms
    }

error_exit:
    if (log_file) {
        fclose(log_file);
    }
    if (sensor1) {
        gpiod_line_request_free(sensor1);
    }
    if (sensor2) {
        gpiod_line_request_free(sensor2);
    }
    gpiod_chip_close(chip);
    return 1;
}

