#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define I2C_BUS 1
#define TMAG5170_ADDR 0x3C
#define TMAG5170_REG_CTRL1 0x00
#define TMAG5170_REG_CTRL2 0x01
#define TMAG5170_REG_DATA 0x02
#define TMAG5170_CTRL1_CONT_MODE 0x01
#define TMAG5170_CTRL1_ALL_AXES 0x06
#define TMAG5170_CTRL2_RANGE_50MT 0x00

FILE *csv_file;
i2c_t *i2c_handle;

void handle_signal(int signum) {
    if (csv_file) {
        fclose(csv_file);
    }
    if (i2c_handle) {
        i2c_close(i2c_handle);
    }
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = i2c_open(I2C_BUS, TMAG5170_ADDR);
    if (i2c_handle == NULL) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    uint8_t ctrl1 = TMAG5170_CTRL1_CONT_MODE | TMAG5170_CTRL1_ALL_AXES;
    uint8_t ctrl2 = TMAG5170_CTRL2_RANGE_50MT;

    if (i2c_write_device(i2c_handle, TMAG5170_REG_CTRL1, &ctrl1, 1) < 0) {
        fprintf(stderr, "Failed to write to CTRL1 register\n");
        i2c_close(i2c_handle);
        return 1;
    }

    if (i2c_write_device(i2c_handle, TMAG5170_REG_CTRL2, &ctrl2, 1) < 0) {
        fprintf(stderr, "Failed to write to CTRL2 register\n");
        i2c_close(i2c_handle);
        return 1;
    }

    csv_file = fopen("magnetic_log.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        i2c_close(i2c_handle);
        return 1;
    }

    if (fseek(csv_file, 0, SEEK_END) != 0) {
        fprintf(stderr, "Failed to seek to end of CSV file\n");
        fclose(csv_file);
        i2c_close(i2c_handle);
        return 1;
    }

    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    while (1) {
        uint8_t data[6];
        if (i2c_read_device(i2c_handle, TMAG5170_REG_DATA, data, 6) != 6) {
            fprintf(stderr, "Failed to read data from sensor\n");
            continue;
        }

        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(csv_file, "%s,%d,%d,%d\n", buffer, data[0], data[1], data[2]);

        fflush(csv_file);
        usleep(100000); // 100 ms
    }

    fclose(csv_file);
    i2c_close(i2c_handle);

    return 0;
}

