    printf("ALERT: Water detected\n");

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s ALERT: Water detected\n", timestamp);
        fclose(log_file);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
