        return 1;
    }

    if (gpiod_line_request_by_name(chip, "gpio23", "water_sensor", 0, &line) < 0) {
        log_error("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_set_consumer(line, "water_sensor") < 0) {
        log_error("Failed to set consumer for GPIO line");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_set_edge(line, GPIOD_LINE_BOTH_EDGES) < 0) {
        log_error("Failed to set edge for GPIO line");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        int value;
        if (gpiod_line_get_value(line, &value) < 0) {
            log_error("Failed to read GPIO line");
            sleep(RETRY_INTERVAL);
            continue;
        }

        if (value == 1) {
            log_alert();
        }

        sleep(ALERT_INTERVAL);
    }

    gpiod_line_put(line);
    gpiod_chip_put(chip);

    return 0;
}

