#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
volatile int rpm = 0;

void handle_interrupt(int signum) {
    gpiod_set_edge(sensor_gpiod, GPIOD_BOTH_EDGES);
    gpiod_disable_irq(sensor_gpiod);
    fclose(log_file);
    gpiod_cleanup(sensor_gpiod);
    exit(signum);
}

void count_pulses(void *data) {
    int current_count = pulse_count;
    pulse_count = 0;
    rpm = (current_count * 60) / 1; // Assuming 1 pulse per revolution
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
    fprintf(log_file, "%s %d\n", timestamp, rpm);
    fflush(log_file);
    printf("%s %d\n", timestamp, rpm);
}

int main() {
    struct gpiod_chip *sensor_gpiod = NULL;
    struct gpiod_line *sensor_line = NULL;
    FILE *log_file = NULL;

    // Initialize GPIO
    sensor_gpiod = gpiod_chip_open_by_name("gpio");
    if (!sensor_gpiod) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO line
    sensor_line = gpiod_line_request(sensor_gpiod, GPIO_PIN, "RPM Sensor", 0, GPIOD_LINE_DIRECTION_IN, GPIOD_LINE_ACTIVE_HIGH, GPIOD_LINE_OPEN_DRAIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_put(sensor_gpiod);
        return 1;
    }

    // Enable internal pull-up resistor
    if (gpiod_line_set_function(sensor_line, GPIOD_LINE_FUNCTION_PULL_UP) < 0) {
        fprintf(stderr, "Failed to enable pull-up resistor\n");
        gpiod_line_release(sensor_line);
        gpiod_chip_put(sensor_gpiod);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(sensor_line);
        gpiod_chip_put(sensor_gpiod);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_interrupt;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Configure GPIO for interrupts
    gpiod_set_edge(sensor_line, GPIOD_RISING_EDGE);
    gpiod_enable_irq(sensor_line, count_pulses, NULL);

    // Main loop
    while (1) {
        sleep(1);
    }

    // Cleanup
    gpiod_disable_irq(sensor_line);
    gpiod_line_release(sensor_line);
    gpiod_chip_put(sensor_gpiod);
    fclose(log_file);

    return 0;
}

