#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define GPIO_A 17
#define GPIO_B 27
#define LOG_FILE "rotation_log.txt"

typedef enum {
    STATE_00,
    STATE_01,
    STATE_10,
    STATE_11
} QuadratureState;

QuadratureState prev_state = STATE_00;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void *isr_thread(void *arg) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret;

    chip = gpiod_chip_open_by_name("gpio");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    line_a = gpiod_line_request_by_name(chip, "gpio%d", GPIO_A, "sensor_a", 0);
    if (!line_a) {
        perror("gpiod_line_request_by_name");
        goto error_a;
    }

    line_b = gpiod_line_request_by_name(chip, "gpio%d", GPIO_B, "sensor_b", 0);
    if (!line_b) {
        perror("gpiod_line_request_by_name");
        goto error_b;
    }

    gpiod_line_set_edge(line_a, GPIOD_LINE_BOTH_EDGES);
    gpiod_line_set_edge(line_b, GPIOD_LINE_BOTH_EDGES);

    while (1) {
        int value_a = gpiod_line_get_value(line_a);
        int value_b = gpiod_line_get_value(line_b);

        QuadratureState curr_state = (value_a << 1) | value_b;

        pthread_mutex_lock(&mutex);
        if (prev_state != curr_state) {
            prev_state = curr_state;
            pthread_cond_signal(&cond);
        }
        pthread_mutex_unlock(&mutex);

        usleep(1000); // Sleep for 1 ms
    }

error_b:
    gpiod_line_free(line_b);
error_a:
    gpiod_line_free(line_a);
    gpiod_chip_put(chip);
    return NULL;
}

void *main_thread(void *arg) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    while (1) {
        pthread_mutex_lock(&mutex);
        while (prev_state == STATE_00) {
            pthread_cond_wait(&cond, &mutex);
        }

        char direction[10];
        if (prev_state == STATE_01) {
            strcpy(direction, "clockwise");
        } else if (prev_state == STATE_10) {
            strcpy(direction, "counter-clockwise");
        }

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%03d %s\n",
                ts.tv_sec / 3600 / 24, (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60,
                ts.tv_sec % 60, (ts.tv_nsec / 1000000) % 1000, (ts.tv_nsec / 1000) % 1000,
                direction);

        prev_state = STATE_00;
        pthread_mutex_unlock(&mutex);

        clock_gettime(CLOCK_REALTIME, &ts);
    }

    fclose(log_file);
    return NULL;
}

void signal_handler(int signum) {
    pthread_mutex_lock(&mutex);
    prev_state = STATE_00;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);

    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    pthread_t isr_thread_id, main_thread_id;

    pthread_create(&isr_thread_id, NULL, isr_thread, NULL);
    pthread_create(&main_thread_id, NULL, main_thread, NULL);

    pthread_join(isr_thread_id, NULL);
    pthread_join(main_thread_id, NULL);

    return 0;
}

