This C program sets up two Melexis MLX90217 unipolar Hall-effect sensors on GPIO17 and GPIO27 of a Raspberry Pi Zero W, using the libgpiod library for interrupt handling. It logs the direction of rotation (clockwise or counter-clockwise) with millisecond-precision timestamps to a file named `rotation_log.txt`. The program uses a mutex to protect shared state between the ISR and the main thread, and it installs a signal handler for SIGINT and SIGTERM to perform a graceful shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO_SENSOR 23
#define GPIO_LED 18
#define TOUCH_INTERVAL 50 // ms

static gpiod_chip *chip;
static gpiod_line *sensor_line;
static gpiod_line *led_line;

void handle_signal(int signum) {
    syslog(LOG_INFO, "Received signal %d, performing graceful shutdown...", signum);

    // Turn off the LED
    gpiod_line_set_value(led_line, 0);

    // Release resources
    gpiod_line_put(sensor_line);
    gpiod_line_put(led_line);
    gpiod_chip_put(chip);

    exit(0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting touch sensor monitoring...");

    // Open the GPIO chip
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", gpiod_error_string(errno));
        return 1;
    }

    // Request the input line for the sensor
    if ((sensor_line = gpiod_line_request_any(chip, "sensor", GPIO_SENSOR, 0)) == NULL) {
        syslog(LOG_ERR, "Failed to request sensor line: %s", gpiod_error_string(errno));
        goto error_sensor_line;
    }

    // Request the output line for the LED
    if ((led_line = gpiod_line_request_any(chip, "led", GPIO_LED, GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        syslog(LOG_ERR, "Failed to request LED line: %s", gpiod_error_string(errno));
        goto error_led_line;
    }

    // Set the LED to off initially
    gpiod_line_set_value(led_line, 0);

    while (1) {
        // Poll the sensor
        int value = gpiod_line_get_value(sensor_line);

        if (value == 1) {
            syslog(LOG_INFO, "Sensor touched, turning on LED...");
            gpiod_line_set_value(led_line, 1);
        } else {
            syslog(LOG_INFO, "Sensor not touched, turning off LED...");
            gpiod_line_set_value(led_line, 0);
        }

        usleep(TOUCH_INTERVAL * 1000); // Sleep for 50 ms
    }

error_led_line:
    gpiod_line_put(sensor_line);
error_sensor_line:
    gpiod_chip_put(chip);

    closelog();
    return 1;
}

