            goto cleanup_event;
        }

        // Debounce
        usleep(DEBOUNCE_TIME * 1000);

        // Toggle LED
        err = gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
        if (err) {
            fprintf(stderr, "Failed to toggle LED\n");
            goto cleanup_event;
        }

cleanup_event:
        gpiod_line_event_free(event);
    }

cleanup_led_line:
    if (led_line) {
        gpiod_line_free(led_line);
        led_line = NULL;
    }

cleanup_out_line:
    if (out_line) {
        gpiod_line_free(out_line);
        out_line = NULL;
    }

cleanup_chip:
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }

    return 0;
}

