#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define NUM_ENTRIES 100
#define DEBOUNCE_MS 50

typedef struct {
    int pin;
    time_t timestamp;
    int state;
} TouchEvent;

TouchEvent log_buffer[NUM_ENTRIES];
int log_head = 0;
int log_tail = 0;
int overflow_count = 0;

void handle_signal(int signum) {
    gpiod_line_request_free(sensor1);
    gpiod_line_request_free(sensor2);
    gpiod_line_request_free(led1);
    gpiod_line_request_free(led2);
    printf("Shutdown: ");
    for (int i = 0; i < NUM_ENTRIES; i++) {
        printf("(%d, %ld, %d) ", log_buffer[i].pin, log_buffer[i].timestamp, log_buffer[i].state);
    }
    printf("\nOverflow count: %d\n", overflow_count);
    exit(0);
}

void log_touch_event(int pin, int state) {
    if (log_head == log_tail) {
        overflow_count++;
        return;
    }
    log_buffer[log_head].pin = pin;
    log_buffer[log_head].timestamp = time(NULL);
    log_buffer[log_head].state = state;
    log_head = (log_head + 1) % NUM_ENTRIES;
}

int main() {
    gpiod_chip *chip;
    gpiod_line *sensor1, *sensor2, *led1, *led2;

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "gpio4", "sensor1", GPIOD_LINE_DIRECTION_IN, &sensor1) < 0) {
        perror("Failed to request sensor1");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "gpio17", "sensor2", GPIOD_LINE_DIRECTION_IN, &sensor2) < 0) {
        perror("Failed to request sensor2");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "gpio27", "led1", GPIOD_LINE_DIRECTION_OUT, &led1) < 0) {
        perror("Failed to request led1");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "gpio22", "led2", GPIOD_LINE_DIRECTION_OUT, &led2) < 0) {
        perror("Failed to request led2");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int sensor1_state = gpiod_line_get_value(sensor1);
        int sensor2_state = gpiod_line_get_value(sensor2);

        if (sensor1_state != gpiod_line_get_value(sensor1)) {
            log_touch_event(4, sensor1_state);
            gpiod_line_set_value(led1, sensor1_state);
        }

        if (sensor2_state != gpiod_line_get_value(sensor2)) {
            log_touch_event(17, sensor2_state);
            gpiod_line_set_value(led2, sensor2_state);
        }

        usleep(DEBOUNCE_MS * 1000);
    }

    return 0;
}

