#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define DEBOUNCE_TIME 5 // ms
#define GPIO17 17
#define GPIO18 18
#define LOG_FILE "shaft_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static FILE *log_file;

static void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (line1) {
        gpiod_line_free(line1);
    }
    if (line2) {
        gpiod_line_free(line2);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

static void log_transition(int sensor1_state, int sensor2_state) {
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

    fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fflush(log_file);
}

static void monitor_transitions() {
    int sensor1_state = gpiod_line_get_value(line1);
    int sensor2_state = gpiod_line_get_value(line2);

    while (1) {
        int new_sensor1_state = gpiod_line_get_value(line1);
        int new_sensor2_state = gpiod_line_get_value(line2);

        if (new_sensor1_state != sensor1_state || new_sensor2_state != sensor2_state) {
            usleep(DEBOUNCE_TIME * 1000); // Debounce
            new_sensor1_state = gpiod_line_get_value(line1);
            new_sensor2_state = gpiod_line_get_value(line2);

            if (new_sensor1_state != sensor1_state || new_sensor2_state != sensor2_state) {
                log_transition(new_sensor1_state, new_sensor2_state);
                sensor1_state = new_sensor1_state;
                sensor2_state = new_sensor2_state;
            }
        }
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpio");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line1 = gpiod_line_request_by_name(chip, "gpio17", "sensor1", 0, 0);
    if (!line1) {
        perror("Failed to request GPIO17");
        goto error_line1;
    }

    line2 = gpiod_line_request_by_name(chip, "gpio18", "sensor2", 0, 0);
    if (!line2) {
        perror("Failed to request GPIO18");
        goto error_line2;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto error_file;
    }

    gpiod_line_set_edge(line1, GPIOD_LINE_BOTH_EDGES);
    gpiod_line_set_edge(line2, GPIOD_LINE_BOTH_EDGES);

    monitor_transitions();

error_file:
    if (line2) {
        gpiod_line_free(line2);
    }
error_line2:
    if (line1) {
        gpiod_line_free(line1);
    }
error_line1:
    if (chip) {
        gpiod_chip_put(chip);
    }

    return EXIT_SUCCESS;
}

