#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_T1 17
#define GPIO_T2 18
#define GPIO_ALARM 27
#define LOG_FILE "bridge_integrity.log"
#define TOLERANCE_MS 2000

static gpiod_chip *chip;
static gpiod_line *sensor1, *sensor2, *alarm;
static FILE *log_file;

void handle_signal(int signum) {
    gpiod_line_set_value(alarm, 0);
    fclose(log_file);
    gpiod_line_put(sensor1);
    gpiod_line_put(sensor2);
    gpiod_line_put(alarm);
    gpiod_chip_put(chip);
    exit(signum);
}

void log_event(const char *event, int sensor) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s - Sensor %d\n", buffer, event, sensor);
    fflush(log_file);
}

int main() {
    int sensor1_value, sensor2_value;
    int alarm_active = 0;
    struct timespec start_time;

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if ((sensor1 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_T1, "sensor1", 0)) == NULL) {
        perror("Failed to request sensor1 line");
        goto cleanup;
    }

    if ((sensor2 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_T2, "sensor2", 0)) == NULL) {
        perror("Failed to request sensor2 line");
        goto cleanup;
    }

    if ((alarm = gpiod_line_request_by_name(chip, "gpio%d", GPIO_ALARM, "alarm", 0)) == NULL) {
        perror("Failed to request alarm line");
        goto cleanup;
    }

    if (gpiod_line_set_value(sensor1, 1) < 0) {
        perror("Failed to set pull-down resistor for sensor1");
        goto cleanup;
    }

    if (gpiod_line_set_value(sensor2, 1) < 0) {
        perror("Failed to set pull-down resistor for sensor2");
        goto cleanup;
    }

    if (gpiod_line_set_value(alarm, 0) < 0) {
        perror("Failed to initialize alarm");
        goto cleanup;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        goto cleanup;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        sensor1_value = gpiod_line_get_value(sensor1);
        sensor2_value = gpiod_line_get_value(sensor2);

        if (sensor1_value == 1 || sensor2_value == 1) {
            if (!alarm_active) {
                alarm_active = 1;
                log_event("Tilt Start", sensor1_value == 1 ? 1 : 2);
                clock_gettime(CLOCK_REALTIME, &start_time);
            }

            if (alarm_active) {
                struct timespec current_time;
                clock_gettime(CLOCK_REALTIME, &current_time);
                if (current_time.tv_sec - start_time.tv_sec >= TOLERANCE_MS / 1000000) {
                    gpiod_line_set_value(alarm, 1);
                    log_event("Threshold Exceeded", sensor1_value == 1 ? 1 : 2);
                }
            }
        } else {
            if (alarm_active) {
                alarm_active = 0;
                gpiod_line_set_value(alarm, 0);
                log_event("Tilt End", 0);
            }
        }

        usleep(100000); // 100 ms
    }

cleanup:
    if (log_file) fclose(log_file);
    if (alarm) gpiod_line_put(alarm);
    if (sensor2) gpiod_line_put(sensor2);
    if (sensor1) gpiod_line_put(sensor1);
    if (chip) gpiod_chip_put(chip);

    return 0;
}

