This C program continuously monitors two digital tilt sensors connected to GPIO17 and GPIO18 on a Raspberry Pi Zero W. It logs events to a file named `bridge_integrity.log` and activates an alarm (GPIO27) if either sensor reads HIGH continuously for more than 2 seconds. The alarm is deactivated when both sensors return to LOW. The program handles errors during initialization and cleanup, and it gracefully handles SIGINT and SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x30
#define CTRL1 0x00
#define CTRL2 0x01
#define DATA 0x02
#define THRESHOLD 500
#define LED_GPIO 17
#define LED_ON 1
#define LED_OFF 0

int i2c_fd;
int log_fd;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    exit(0);
}

int read_sensor_data(int retries) {
    int data[2];
    int result = -1;

    for (int i = 0; i < retries; i++) {
        if (write(i2c_fd, &CTRL1, 1) != 1) {
            perror("Failed to write to CTRL1");
            continue;
        }

        if (read(i2c_fd, &data, 2) != 2) {
            perror("Failed to read data");
            continue;
        }

        int magnitude = (int)sqrt(data[0] * data[0] + data[1] * data[1]);
        if (magnitude > THRESHOLD) {
            result = magnitude;
            break;
        }
    }

    return result;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    int init_retries = 3;
    int init_result = -1;
    for (int i = 0; i < init_retries; i++) {
        if (write(i2c_fd, &CTRL1, 1) != 1) {
            perror("Failed to write to CTRL1 during initialization");
            continue;
        }

        if (read(i2c_fd, &init_result, 1) != 1) {
            perror("Failed to read CTRL1 during initialization");
            continue;
        }

        if (init_result & 0x01) {
            break;
        }
    }

    if (init_result < 0) {
        perror("Failed to initialize sensor");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fd = open("seismic_events.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int peak_magnitude = read_sensor_data(3);
        if (peak_magnitude > THRESHOLD) {
            char timestamp[20];
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);

            char log_msg[100];
            snprintf(log_msg, sizeof(log_msg), "%s - Peak magnitude: %d\n", timestamp, peak_magnitude);
            write(log_fd, log_msg, strlen(log_msg));

            // Turn on LED
            int led_fd = open("/sys/class/gpio/gpio%d/value", O_WRONLY);
            if (led_fd >= 0) {
                write(led_fd, &LED_ON, 1);
                close(led_fd);
                sleep(1);

                led_fd = open("/sys/class/gpio/gpio%d/value", O_WRONLY);
                if (led_fd >= 0) {
                    write(led_fd, &LED_OFF, 1);
                    close(led_fd);
                }
            }
        }

        usleep(100000); // Sleep for 100 ms
    }

    close(i2c_fd);
    close(log_fd);
    return 0;
}

