#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define NUM_SENSORS 4
#define GPIO_PINS {4, 17, 27, 22}
#define LED_PIN 18
#define POLL_INTERVAL 50 // in milliseconds

gpiod_chip *chip;
gpiod_line *sensor_lines[NUM_SENSORS];
gpiod_line *led_line;

void handle_signal(int signum) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_request_free(sensor_lines[i]);
    }
    gpiod_line_request_free(led_line);
    gpiod_chip_put(chip);
    exit(signum);
}

int main() {
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO lines for sensors and LED
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_line_request_by_name(chip, "gpio%d", GPIO_PINS[i], "sensor", 0);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to request sensor GPIO line %d\n", GPIO_PINS[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(sensor_lines[j]);
            }
            gpiod_chip_put(chip);
            return EXIT_FAILURE;
        }
        ret = gpiod_line_direction_set(sensor_lines[i], GPIOD_LINE_DIRECTION_IN);
        if (ret) {
            fprintf(stderr, "Failed to set direction for sensor GPIO line %d\n", GPIO_PINS[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(sensor_lines[j]);
            }
            gpiod_chip_put(chip);
            return EXIT_FAILURE;
        }
    }

    led_line = gpiod_line_request_by_name(chip, "gpio%d", LED_PIN, "led", 0);
    if (!led_line) {
        fprintf(stderr, "Failed to request LED GPIO line %d\n", LED_PIN);
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_request_free(sensor_lines[i]);
        }
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_direction_set(led_line, GPIOD_LINE_DIRECTION_OUT);
    if (ret) {
        fprintf(stderr, "Failed to set direction for LED GPIO line %d\n", LED_PIN);
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_request_free(sensor_lines[i]);
        }
        gpiod_line_request_free(led_line);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handling
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        int any_sensor_active = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value;
            ret = gpiod_line_get_value(sensor_lines[i], &value);
            if (ret) {
                fprintf(stderr, "Failed to read sensor GPIO line %d\n", GPIO_PINS[i]);
                handle_signal(EXIT_FAILURE);
            }
            if (value == 0) { // Active-low, 0 indicates detection
                any_sensor_active = 1;
                break;
            }
        }

        if (any_sensor_active) {
            ret = gpiod_line_set_value(led_line, 1); // Turn LED ON
        } else {
            ret = gpiod_line_set_value(led_line, 0); // Turn LED OFF
        }
        if (ret) {
            fprintf(stderr, "Failed to set LED GPIO line %d\n", LED_PIN);
            handle_signal(EXIT_FAILURE);
        }

        usleep(POLL_INTERVAL * 1000); // Sleep for 50ms
    }

    return EXIT_SUCCESS;
