This C program reads obstacle detection data from four Keywish KY-032 Infrared Obstacle Avoidance sensors connected to GPIO4, GPIO17, GPIO27, and GPIO22 (BCM numbering) on a Raspberry Pi 5. It drives an LED on GPIO18 (BCM) to indicate when any sensor detects an object. The program polls the sensors every 50ms without using blocking delays, handles GPIO initialization errors, and cleanly releases all GPIO resources when receiving a SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <syslog.h>

#define NUM_SENSORS 5
#define DEBOUNCE_TIME 50 // ms

volatile sig_atomic_t terminate = 0;

void handle_signal(int signum) {
    terminate = 1;
}

void log_event(const char *msg) {
    syslog(LOG_USER | LOG_INFO, "%s", msg);
}

void log_error(const char *msg) {
    syslog(LOG_USER | LOG_ERR, "%s", msg);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_SENSORS];
    int i, ret;

    // Initialize syslog
    openlog("flame_monitor", LOG_PID, LOG_USER);
    log_event("Flame monitor started");

    // Open the GPIO chip
    if ((ret = gpiod_chip_open(NULL, &chip)) < 0) {
        log_error("Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    // Request lines for each sensor
    for (i = 0; i < NUM_SENSORS; i++) {
        int pin = (i == 0) ? 2 : ((i == 1) ? 3 : ((i == 2) ? 4 : ((i == 3) ? 17 : 27)));
        if ((ret = gpiod_line_request(chip, pin, "Sensor %d", &lines[i], NULL, 0)) < 0) {
            log_error("Failed to request GPIO line %d", pin);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (!terminate) {
        for (i = 0; i < NUM_SENSORS; i++) {
            if ((ret = gpiod_line_get_value(lines[i])) < 0) {
                log_error("Failed to read GPIO line %d", lines[i]->line.pin);
                continue;
            }

            if (ret == 0) { // HIGH to LOW transition detected
                usleep(DEBOUNCE_TIME * 1000); // Debounce
                if ((ret = gpiod_line_get_value(lines[i])) < 0) {
                    log_error("Failed to read GPIO line %d", lines[i]->line.pin);
                    continue;
                }

                if (ret == 0) { // Confirmed LOW
                    time_t now = time(NULL);
                    struct tm *tm = gmtime(&now);
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

                    FILE *log_file = fopen("/var/log/flame_events.log", "a");
                    if (log_file == NULL) {
                        log_error("Failed to open log file");
                        continue;
                    }

                    flock(fileno(log_file), LOCK_EX);
                    fprintf(log_file, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, i + 1, lines[i]->line.pin);
                    fflush(log_file);
                    fclose(log_file);
                }
            }
        }

        sleep(1); // Poll every second
    }

    // Cleanup
    for (i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    closelog();

    log_event("Flame monitor terminated");
    return EXIT_SUCCESS;
}

