#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define NUM_PINS 8
#define GPIO_PINS {5, 6, 13, 19, 26, 12, 16, 20}
#define GPIO_DIRECTION_OUT 0
#define GPIO_DIRECTION_IN 1
#define GPIO_VALUE_HIGH 1
#define GPIO_VALUE_LOW 0
#define TOUCH_DETECTED "detected"
#define TOUCH_RELEASED "released"
#define ERROR_MSG_LEN 128

static void handle_error(const char *msg, int errnum) {
    char error_msg[ERROR_MSG_LEN];
    snprintf(error_msg, ERROR_MSG_LEN, "%s: %s (errno: %d)", msg, strerror(errnum), errnum);
    fprintf(stderr, "%s\n", error_msg);
    exit(EXIT_FAILURE);
}

static void cleanup_and_exit(gpiod_chip *chip, gpiod_line *lines[], int exit_status) {
    for (int i = 0; i < NUM_PINS; i++) {
        gpiod_line_request_free(lines[i]);
    }
    gpiod_chip_put(chip);
    exit(exit_status);
}

static void handle_sigint(int signum) {
    cleanup_and_exit(chip, lines, EXIT_SUCCESS);
}

int main() {
    gpiod_chip *chip = NULL;
    gpiod_line *lines[NUM_PINS];
    int prev_states[NUM_PINS] = {0};
    int current_states[NUM_PINS] = {0};
    struct timespec ts;

    signal(SIGINT, handle_sigint);

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        handle_error("Failed to open GPIO chip", errno);
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_bulk(chip, GPIO_PINS[i], GPIO_DIRECTION_OUT, "TTP226 Touch Sensor", &lines[i], 1) < 0) {
            handle_error("Failed to request GPIO line", errno);
        }
    }

    while (1) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], GPIO_VALUE_HIGH) < 0) {
                handle_error("Failed to set GPIO line value", errno);
            }
            if (gpiod_line_get_value(lines[i], &current_states[i]) < 0) {
                handle_error("Failed to get GPIO line value", errno);
            }
            if (gpiod_line_set_value(lines[i], GPIO_VALUE_LOW) < 0) {
                handle_error("Failed to set GPIO line value", errno);
            }
        }

        clock_gettime(CLOCK_REALTIME, &ts);

        for (int i = 0; i < NUM_PINS; i++) {
            if (current_states[i] != prev_states[i]) {
                printf("%04d-%02d-%02dT%02d:%02d:%02d.%06ld: Pin %d %s\n",
                       ts.tv_sec / 60 / 60 / 24 + 1970,
                       (ts.tv_sec / 60 / 60) % 24 + 1,
                       (ts.tv_sec / 60) % 60 + 1,
                       (ts.tv_sec / 60) % 60 + 1,
                       ts.tv_sec % 60 + 1,
                       ts.tv_nsec / 1000000,
                       i,
                       current_states[i] ? TOUCH_DETECTED : TOUCH_RELEASED);
                prev_states[i] = current_states[i];
            }
        }

        usleep(50000); // Sleep for 50 ms
    }

    cleanup_and_exit(chip, lines, EXIT_SUCCESS);

    return EXIT_SUCCESS;
}

