#define ALERT_LED_PIN 17
#define DEBOUNCE_TIME 50 // ms
#define LOG_FILE "touch_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_CHANNELS];
static struct gpiod_line *led_line;

static void handle_signal(int signum) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_free(led_line);
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_free(lines[i]);
        }
    }

    gpiod_chip_put(chip);

    exit(signum == SIGINT ? 0 : 1);
}

static void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S – Channel %d Touched", timeinfo);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return;
    }

    if (fputs(buffer, file) == EOF) {
        fprintf(stderr, "Failed to write to log file.\n");
    }

    fclose(file);
}

int main() {
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return 1;
    }

    // Initialize lines for touch channels
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_line_request_by_name(chip, gpiod_line_get_name(chip, CHANNEL_PINS[i]), "touch_channel", 0, 0);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line for touch channel %d.\n", i + 1);
            return 1;
        }

        gpiod_line_set_debounce(lines[i], DEBOUNCE_TIME);
        gpiod_line_set_consumer(lines[i], "touch_sensor");
        gpiod_line_set_direction(lines[i], GPIO_LINE_DIRECTION_IN);
        gpiod_line_set_active_low(lines[i], 1);
    }

    // Initialize LED line
    led_line = gpiod_line_request_by_name(chip, gpiod_line_get_name(chip, ALERT_LED_PIN), "alert_led", 0, 0);
    if (!led_line) {
        fprintf(stderr, "Failed to request GPIO line for alert LED.\n");
        return 1;
    }

    gpiod_line_set_consumer(led_line, "alert_led");
    gpiod_line_set_direction(led_line, GPIO_LINE_DIRECTION_OUT);

    // Install signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value == 0) { // Channel touched
                if (gpiod_line_get_value(led_line) == 0) {
                    gpiod_line_set_value(led_line, 1);
                }
                log_touch_event(i + 1);
            } else { // Channel released
                if (gpiod_line_get_value(led_line) == 1) {
                    gpiod_line_set_value(led_line, 0);
                }
            }
        }

        usleep(DEBOUNCE_TIME * 1000); // Sleep for debounce time
    }

    return 0;
}

