#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OPT3001_ADDR 0x40
#define OPT3001_REG_CONFIG 0x00
#define OPT3001_REG_DATA 0x01

#define LUX_DATA_FILE "light_data.txt"

static int i2c_fd = -1;
static FILE *log_file = NULL;

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int i2c_write(uint8_t reg, uint16_t data) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = data & 0xFF;
    buf[2] = (data >> 8) & 0xFF;

    if (write(i2c_fd, buf, 3) != 3) {
        perror("i2c_write");
        return -1;
    }

    usleep(100000); // Wait 100ms

    return 0;
}

int i2c_read(uint8_t reg, uint16_t *data) {
    uint8_t buf[3];
    if (read(i2c_fd, buf, 3) != 3) {
        perror("i2c_read");
        return -1;
    }

    *data = (buf[1] << 8) | buf[2];

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) == -1) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LUX_DATA_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint16_t lux_data = 0;

        if (i2c_write(OPT3001_REG_CONFIG, 0x00) == -1) {
            continue;
        }

        if (i2c_read(OPT3001_REG_DATA, &lux_data) == -1) {
            continue;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S, ", now_tm);

        printf("%s%.2f\n", timestamp, (double)lux_data / 100.0);
        fprintf(log_file, "%s%.2f\n", timestamp, (double)lux_data / 100.0);
        fflush(log_file);

        sleep(1);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    close(i2c_fd);

    return 0;
}

