#define GPIO_SENSOR 4
#define GPIO_ALERT 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL 500

static gpiod_chip *chip;
static gpiod_line *sensor_line, *alert_line;
static FILE *log_file;

void cleanup(void) {
    if (sensor_line) {
        gpiod_line_request_release(sensor_line);
        free(sensor_line);
    }
    if (alert_line) {
        gpiod_line_request_release(alert_line);
        free(alert_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
        free(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    sensor_line = gpiod_line_request_by_name(chip, "gpio4", "sensor", 0);
    if (!sensor_line) {
        fprintf(stderr, "Failed to request sensor line\n");
        cleanup();
        return 1;
    }

    alert_line = gpiod_line_request_by_name(chip, "gpio17", "alert", 0);
    if (!alert_line) {
        fprintf(stderr, "Failed to request alert line\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    gpiod_line_direction_set(sensor_line, GPIO_LINE_DIRECTION_INPUT);
    gpiod_line_direction_set(alert_line, GPIO_LINE_DIRECTION_OUTPUT);

    while (1) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (sensor_value == 0) {
            gpiod_line_set_value(alert_line, 1);
            fprintf(log_file, "%s: Flame detected, alert set HIGH\n", timestamp);
            usleep(1000000); // Sleep for 1 second
            gpiod_line_set_value(alert_line, 0);
            fprintf(log_file, "%s: Flame detected, alert set LOW\n", timestamp);
        } else {
            fprintf(log_file, "%s: No flame detected\n", timestamp);
        }

        fflush(log_file);
        usleep(POLL_INTERVAL * 1000); // Sleep for 500 ms
    }

    cleanup();
    return 0;
}

