#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL 50
#define LOG_FILE "touch_log.txt"

static struct gpiod_line *gpiod_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (gpiod_line) {
        gpiod_line_request_free(gpiod_line);
        gpiod_line = NULL;
    }

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main() {
    struct gpiod_line_request *request;
    struct gpiod_line_consumer *consumer;
    struct gpiod_line_consumer_config config;
    struct timespec ts;
    int prev_state = 0;

    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return EXIT_FAILURE;
    }

    // Initialize GPIO line
    gpiod_line = gpiod_line_request_by_name(NULL, "gpio%d", GPIO_PIN, &request);
    if (!gpiod_line) {
        fprintf(stderr, "Failed to request GPIO line: %d\n", GPIO_PIN);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Configure GPIO line
    memset(&config, 0, sizeof(config));
    config.consumer_type = GPIOD_LINE_CONSUMER_ACTIVE_LOW;
    config.debounce_ns = DEBOUNCE_INTERVAL * 1000000;
    config.pull_up_down = GPIOD_LINE_PULL_DOWN;
    config.consumer = &consumer;

    if (gpiod_line_request_set_config(gpiod_line, &config) < 0) {
        fprintf(stderr, "Failed to set GPIO line configuration: %d\n", GPIO_PIN);
        gpiod_line_request_free(gpiod_line);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int current_state = gpiod_line_get_value(gpiod_line);

        if (current_state != prev_state) {
            char timestamp[20];
            time_t rawtime;
            struct tm *timeinfo;

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (current_state) {
                fprintf(log_file, "%s: Touch Detected\n", timestamp);
            } else {
                fprintf(log_file, "%s: Touch Released\n", timestamp);
            }

            fflush(log_file);
            prev_state = current_state;
        }

        usleep(DEBOUNCE_INTERVAL * 1000);
    }

    // Cleanup
    gpiod_line_request_free(gpiod_line);
    fclose(log_file);

    return EXIT_SUCCESS;
}

