#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SLF3S_ADDR 0x40
#define SLF3S_CMD 0x00
#define SLF3S_DATA 0x01
#define SLF3S_CRC_POLY 0x07
#define SLF3S_FLOW_RATE_MAX 100.0
#define SLF3S_FLOW_RATE_MIN 0.0

int i2c_fd;
FILE *log_file;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int i2c_read(int addr, int cmd, uint8_t *data, int length) {
    int ret;
    uint8_t buffer[length];

    ret = ioctl(i2c_fd, I2C_SLAVE, addr);
    if (ret < 0) {
        perror("I2C_SLAVE");
        return -1;
    }

    ret = write(i2c_fd, &cmd, 1);
    if (ret != 1) {
        perror("write");
        return -1;
    }

    ret = read(i2c_fd, buffer, length);
    if (ret != length) {
        perror("read");
        return -1;
    }

    memcpy(data, buffer, length);
    return 0;
}

uint8_t crc8(uint8_t *data, int length) {
    uint8_t crc = 0;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SLF3S_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

double convert_flow_rate(int16_t flow_value) {
    return (double)flow_value / 100.0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    log_file = fopen("cooling_log.csv", "a");
    if (!log_file) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    if (fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n") == 0) {
        perror("fprintf");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint8_t data[3];
        int16_t flow_value;
        uint8_t crc;
        double flow_rate;
        char status[10];

        usleep(2000); // Wait 2 ms before first read

        if (i2c_read(SLF3S_ADDR, SLF3S_CMD, data, 3) < 0) {
            fprintf(log_file, "ERROR\n");
            continue;
        }

        flow_value = (data[0] << 8) | data[1];
        crc = data[2];

        if (crc8(data, 2) != crc) {
            strcpy(status, "CRC Error");
        } else if (flow_value < (int16_t)SLF3S_FLOW_RATE_MIN * 100 || flow_value > (int16_t)SLF3S_FLOW_RATE_MAX * 100) {
            strcpy(status, "INVALID");
        } else {
            flow_rate = convert_flow_rate(flow_value);
            strcpy(status, "OK");
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        if (fprintf(log_file, "%s,%f,%s\n", timestamp, flow_rate, status) == 0) {
            perror("fprintf");
            fclose(log_file);
            close(i2c_fd);
            return 1;
        }

        sleep(1); // Sample once per second
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

