#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define LOG_FILE "path_log.csv"

static struct gpiod_chip *chip;
static struct gpiod_line *left_sensor, *middle_sensor, *right_sensor;
static FILE *log_file;

void cleanup(int signum) {
    if (left_sensor) {
        gpiod_line_request_release(left_sensor);
        free(left_sensor);
    }
    if (middle_sensor) {
        gpiod_line_request_release(middle_sensor);
        free(middle_sensor);
    }
    if (right_sensor) {
        gpiod_line_request_release(right_sensor);
        free(right_sensor);
    }
    if (chip) {
        gpiod_chip_put(chip);
        free(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request_config config;
    char timestamp_str[20];
    int left_value, middle_value, right_value;

    // Initialize signal handler
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open GPIO chip
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines for sensors
    memset(&config, 0, sizeof(config));
    config.consumer = "ObstacleAvoidanceSensor";
    config.request_type = GPIOD_LINE_REQUEST_INPUT;

    if ((left_sensor = gpiod_line_request_by_name(chip, "gpio%d", LEFT_SENSOR_PIN, &config)) == NULL) {
        perror("Failed to request left sensor line");
        goto cleanup;
    }

    if ((middle_sensor = gpiod_line_request_by_name(chip, "gpio%d", MIDDLE_SENSOR_PIN, &config)) == NULL) {
        perror("Failed to request middle sensor line");
        goto cleanup;
    }

    if ((right_sensor = gpiod_line_request_by_name(chip, "gpio%d", RIGHT_SENSOR_PIN, &config)) == NULL) {
        perror("Failed to request right sensor line");
        goto cleanup;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Write header to log file
    fprintf(log_file, "timestamp,left,middle,right\n");

    // Main loop
    while (1) {
        // Read sensor values
        left_value = gpiod_line_get_value(left_sensor);
        middle_value = gpiod_line_get_value(middle_sensor);
        right_value = gpiod_line_get_value(right_sensor);

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", now_tm);

        // Write to log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp_str, left_value, middle_value, right_value);

        // Sleep for 50ms
        usleep(50000);
    }

cleanup:
    cleanup(0);

    return EXIT_SUCCESS;
}

