#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "/dev/gpiochip4"
#define GPIO_TOUCH 23
#define GPIO_LED 24
#define LOG_FILE "touch_log.txt"

static gpiod_chip *chip;
static gpiod_line *touch_line;
static gpiod_line *led_line;
static FILE *log_file;

void cleanup(void) {
    if (touch_line) {
        gpiod_line_free(touch_line);
        touch_line = NULL;
    }
    if (led_line) {
        gpiod_line_free(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main(void) {
    int ret;
    struct timespec timeout = { .tv_sec = 1 };
    struct timespec now;
    char timestamp[20];
    char log_line[100];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((chip = gpiod_chip_open(GPIO_CHIP, 0)) == NULL) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    if ((touch_line = gpiod_line_request_any(chip, GPIO_TOUCH, "touch_sensor", 0, &ret)) == NULL) {
        perror("gpiod_line_request_any");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if ((led_line = gpiod_line_request_any(chip, GPIO_LED, "led", 0, &ret)) == NULL) {
        perror("gpiod_line_request_any");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        cleanup();
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_edge(touch_line, GPIO_LINE_BOTH_EDGES);
    gpiod_line_set_value(led_line, 0);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now.tv_sec));

        if (gpiod_line_get_value(touch_line) == 1) {
            gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
            snprintf(log_line, sizeof(log_line), "%s: Touch detected, LED state: %d\n", timestamp, gpiod_line_get_value(led_line));
            if (fputs(log_line, log_file) == EOF) {
                perror("fputs");
                cleanup();
                exit(EXIT_FAILURE);
            }
        }

        if (gpiod_line_poll_event(touch_line, &timeout, &now) < 0) {
            perror("gpiod_line_poll_event");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

