#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "alert_log.txt"
#define BUZZER_ON gpiod_line_set_value(buzzer_line, 1)
#define BUZZER_OFF gpiod_line_set_value(buzzer_line, 0)

static gpiod_chip *chip;
static gpiod_line *flame_sensor_line;
static gpiod_line *buzzer_line;
static FILE *log_file;

void handle_signal(int signum) {
    BUZZER_OFF;
    gpiod_line_request_free(flame_sensor_line);
    gpiod_line_request_free(buzzer_line);
    gpiod_chip_put(chip);
    fclose(log_file);
    exit(0);
}

void log_flame_detected(const char *message) {
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }

    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    fprintf(log_file, "%s %d-%02d-%02d %02d:%02d:%02d: %s\n",
            asctime(now_tm), now / (365 * 24 * 60 * 60),
            (now / (24 * 60 * 60)) % 365, (now / (60 * 60)) % 24,
            (now / 60) % 60, now % 60, message);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        exit(1);
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set SIGTERM handler");
        exit(1);
    }

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    if ((flame_sensor_line = gpiod_line_request_by_name(chip, "gpio17", "flame_sensor")) == NULL) {
        perror("Failed to request flame sensor line");
        gpiod_chip_put(chip);
        exit(1);
    }

    if ((buzzer_line = gpiod_line_request_by_name(chip, "gpio18", "buzzer")) == NULL) {
        perror("Failed to request buzzer line");
        gpiod_line_request_free(flame_sensor_line);
        gpiod_chip_put(chip);
        exit(1);
    }

    if (gpiod_line_direction_output(flame_sensor_line) == -1) {
        perror("Failed to set flame sensor line direction");
        gpiod_line_request_free(flame_sensor_line);
        gpiod_line_request_free(buzzer_line);
        gpiod_chip_put(chip);
        exit(1);
    }

    if (gpiod_line_direction_output(buzzer_line) == -1) {
        perror("Failed to set buzzer line direction");
        gpiod_line_request_free(flame_sensor_line);
        gpiod_line_request_free(buzzer_line);
        gpiod_chip_put(chip);
        exit(1);
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_request_free(flame_sensor_line);
        gpiod_line_request_free(buzzer_line);
        gpiod_chip_put(chip);
        exit(1);
    }

    log_flame_detected("System started");

    int prev_sensor_state = 1; // Assume no flame initially
    int buzzer_active = 0;

    while (1) {
        int sensor_state = gpiod_line_get_value(flame_sensor_line);

        if (sensor_state != prev_sensor_state) {
            if (sensor_state == 0) { // Flame detected (LOW)
                if (!buzzer_active) {
                    log_flame_detected("FLAME DETECTED");
                    BUZZER_ON;
                    buzzer_active = 1;
                }
            } else { // Flame not detected (HIGH)
                if (buzzer_active) {
                    BUZZER_OFF;
                    buzzer_active = 0;
                }
            }
        }

        prev_sensor_state = sensor_state;
        usleep(100000); // Sleep for 100 ms
    }

    log_flame_detected("System stopped");
    fclose(log_file);
    gpiod_line_request_free(flame_sensor_line);
    gpiod_line_request_free(buzzer_line);
    gpiod_chip_put(chip);

    return 0;
}

