This C program implements a flame detection safety system using the Keyes KY-026 Flame Sensor and an active buzzer on a Raspberry Pi 3 Model B+. It polls the flame sensor every 100 ms, checks for a HIGH-to-LOW transition (indicating flame detection), logs a timestamped message to `alert_log.txt`, and activates the buzzer for 2 seconds. It handles errors, SIGINT, and SIGTERM signals, and ensures proper cleanup on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_TOUCH 4
#define GPIO_LED 17
#define DEBOUNCE_TIME 200 // in milliseconds

static gpiod_chip *chip;
static gpiod_line *touch_line;
static gpiod_line *led_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (gpiod_line_request_release(touch_line) < 0) {
        fprintf(stderr, "Failed to release touch line.\n");
    }
    if (gpiod_line_request_release(led_line) < 0) {
        fprintf(stderr, "Failed to release LED line.\n");
    }
    if (gpiod_chip_put(chip) < 0) {
        fprintf(stderr, "Failed to put chip.\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct timespec ts;
    struct timespec ts_debounce;
    int ret;

    // Initialize libgpiod
    if ((ret = gpiod_chip_open(NULL, &chip)) < 0) {
        fprintf(stderr, "Failed to open gpiod chip: %s\n", gpiod_error_to_string(ret));
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    if ((ret = gpiod_line_request_by_name(chip, "gpio%d", GPIO_TOUCH, "touch", &touch_line, NULL)) < 0) {
        fprintf(stderr, "Failed to request touch line: %s\n", gpiod_error_to_string(ret));
        goto cleanup;
    }

    if ((ret = gpiod_line_request_by_name(chip, "gpio%d", GPIO_LED, "led", &led_line, NULL)) < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", gpiod_error_to_string(ret));
        goto cleanup;
    }

    // Set GPIO lines direction
    if ((ret = gpiod_line_direction_set(touch_line, GPIO_LINE_DIRECTION_INPUT)) < 0) {
        fprintf(stderr, "Failed to set touch line direction: %s\n", gpiod_error_to_string(ret));
        goto cleanup;
    }

    if ((ret = gpiod_line_direction_set(led_line, GPIO_LINE_DIRECTION_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set LED line direction: %s\n", gpiod_error_to_string(ret));
        goto cleanup;
    }

    // Open log file
    if ((log_file = fopen("touch_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return EXIT_FAILURE;
    }

    // Set up signal handling
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read touch sensor
        if ((ret = gpiod_line_get_value(touch_line)) < 0) {
            fprintf(stderr, "Failed to read touch line: %s\n", gpiod_error_to_string(ret));
            continue;
        }

        if (ret == 1) { // Rising edge detected
            ts.tv_sec = time(NULL);
            ts.tv_nsec = 0;

            // Debounce
            ts_debounce.tv_sec = DEBOUNCE_TIME / 1000;
            ts_debounce.tv_nsec = (DEBOUNCE_TIME % 1000) * 1000000;
