#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_SENSOR1 4
#define GPIO_SENSOR2 17
#define GPIO_SENSOR3 27
#define LOG_FILE "magnet_log.txt"

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signum) {
    printf("Received signal %d, performing clean shutdown...\n", signum);
    gpiod_chip_put(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[3];
    FILE *log_file;
    int state[3];
    int i;

    // Initialize the libgpiod chip
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Open lines for each sensor
    for (i = 0; i < 3; i++) {
        if ((lines[i] = gpiod_line_request_any(chip, 1, "sensor", 0)) == NULL) {
            perror("Failed to request GPIO line");
            return 1;
        }

        // Configure each pin as input with internal pull-up
        if (gpiod_line_direction_input(lines[i]) ||
            gpiod_line_set_value(lines[i], 1)) {
            perror("Failed to configure GPIO line");
            return 1;
        }
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Record initial state
    for (i = 0; i < 3; i++) {
        state[i] = gpiod_line_get_value(lines[i]);
    }

    // Main loop to poll sensors
    while (1) {
        for (i = 0; i < 3; i++) {
            int current_state = gpiod_line_get_value(lines[i]);

            // Check for state change
            if (current_state != state[i]) {
                char timestamp[20];
                time_t rawtime;
                struct tm *timeinfo;

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

                fprintf(log_file, "%s Sensor%d: %s\n", timestamp, i + 1, current_state ? "magnet-removed" : "magnet-present");
                state[i] = current_state;
            }
        }

        usleep(100000); // Sleep for 100ms
    }

    // Clean up
    for (i = 0; i < 3; i++) {
        gpiod_line_free(lines[i]);
    }
    gpiod_chip_put(chip);
    fclose(log_file);

    return 0;
}

