    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int read_sensor_data() {
    int ret;
    uint8_t buffer[2];

    ret = i2c_read_device(i2c_handle, I2C_ADDR, buffer, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", ret);
        return -1;
    }

    uint16_t part_id = (buffer[0] << 8) | buffer[1];
    if (part_id != PART_ID) {
        fprintf(stderr, "Invalid PART_ID: expected 0x%04X, got 0x%04X\n", PART_ID, part_id);
        return -1;
    }

    ret = i2c_read_device(i2c_handle, I2C_ADDR, buffer, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", ret);
        return -1;
    }

    uint16_t hw_rev = (buffer[0] << 8) | buffer[1];
    if (hw_rev != HW_REV) {
        fprintf(stderr, "Invalid HW_REV: expected 0x%02X, got 0x%02X\n", HW_REV, hw_rev);
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_handle = i2c_open(I2C_BUS, 0);
    if (i2c_handle == -1) {
        perror("i2c_open");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        i2c_close(i2c_handle);
        return 1;
    }

    while (1) {
        if (read_sensor_data() == 0) {
            int bpm = 0;
            for (int i = 0; i < NUM_SAMPLES; i++) {
                samples[i] = (rand() % 100) + 1; // Replace with actual sensor reading
                bpm += samples[i];
            }
            bpm /= NUM_SAMPLES;

            if (bpm >= BPM_MIN && bpm <= BPM_MAX) {
                time_t now = time(NULL);
                struct tm *now_tm = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", now_tm);
                fprintf(log_file, "%s%d\n", timestamp, bpm);
                fflush(log_file);
            }
        }

        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    i2c_close(i2c_handle);
    return 0;
}

