static gpiod_line *line;
static FILE *log_file;

static void handle_signal(int signum) {
    if (line) {
        gpiod_line_request_release(line);
        gpiod_chip_put(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

static void check_error(int result, const char *description) {
    if (result < 0) {
        fprintf(stderr, "Error %d: %s\n", result, description);
        handle_signal(EXIT_FAILURE);
    }
}

int main() {
    struct timespec last_event_time = {0, 0};
    int last_state = 1; // Assuming initial state is HIGH (no flame)

    // Initialize signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    check_error(log_file == NULL, "Failed to open log file");

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpio");
    check_error(chip == NULL, "Failed to open GPIO chip");

    // Request GPIO line
    line = gpiod_line_request_by_name(chip, "17", "flame_sensor", 0, 0);
    check_error(line == NULL, "Failed to request GPIO line");

    // Set line to input with pull-up
    gpiod_line_direction_set(line, GPIO_LINE_DIRECTION_INPUT);
    gpiod_line_set_debounce(line, 100000); // 100ms debounce
    gpiod_line_set_pull(line, GPIO_LINE_PULL_UP);

    while (1) {
        int current_state = gpiod_line_get_value(line);

        if (current_state != last_state) {
            if (current_state == 0 && (time(NULL) - last_event_time.tv_sec) > 0) {
                printf("FLAME DETECTED\n");
                fprintf(log_file, "%ld: FLAME DETECTED\n", time(NULL));
                fflush(log_file);
                last_event_time = time(NULL);
            }
            last_state = current_state;
        }

        usleep(100000); // Sleep for 100ms
    }

    // Cleanup on exit
    handle_signal(0);

    return 0;
}

