#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define SENSOR_PINS {5, 6, 7, 8, 9, 10, 11, 12}
#define OUTPUT_PINS {17, 24}
#define NUM_CHANNELS 8
#define NUM_OUTPUT_PINS 2
#define STABILIZATION_DELAY 200
#define POLL_INTERVAL 10

static gpiod_chip *chip;
static gpiod_line *sensor_lines[NUM_CHANNELS];
static gpiod_line *output_lines[NUM_OUTPUT_PINS];
static FILE *log_file;

void handle_signal(int signum) {
    for (int i = 0; i < NUM_OUTPUT_PINS; i++) {
        gpiod_line_set_value(output_lines[i], 0);
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_request_free(sensor_lines[i]);
    }
    for (int i = 0; i < NUM_OUTPUT_PINS; i++) {
        gpiod_line_request_free(output_lines[i]);
    }
    gpiod_chip_put(chip);
    fclose(log_file);
    exit(0);
}

int main() {
    int counter = 0;
    int sensor_value;
    char timestamp[20];
    struct tm *time_info;

    // Initialize GPIO chip
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        exit(1);
    }

    // Request sensor lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if ((sensor_lines[i] = gpiod_line_request_by_name(chip, "gpio%d", SENSOR_PINS[i], "sensor", 0)) == NULL) {
            perror("gpiod_line_request_by_name");
            exit(1);
        }
        if (gpiod_line_direction_output(sensor_lines[i]) < 0) {
            perror("gpiod_line_direction_output");
            exit(1);
        }
        if (gpiod_line_set_value(sensor_lines[i], 0) < 0) {
            perror("gpiod_line_set_value");
            exit(1);
        }
    }

    // Request output lines
    for (int i = 0; i < NUM_OUTPUT_PINS; i++) {
        if ((output_lines[i] = gpiod_line_request_by_name(chip, "gpio%d", OUTPUT_PINS[i], "output", 0)) == NULL) {
            perror("gpiod_line_request_by_name");
            exit(1);
        }
        if (gpiod_line_direction_output(output_lines[i]) < 0) {
            perror("gpiod_line_direction_output");
            exit(1);
        }
    }

    // Open log file
    if ((log_file = fopen("touch_log.txt", "a")) == NULL) {
        perror("fopen");
        fprintf(stderr, "Failed to open log file, continuing with stdout output.\n");
    }

    // Stabilization delay
    sleep(STABILIZATION_DELAY / 1000);

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            sensor_value = gpiod_line_get_value(sensor_lines[i]);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor line %d: %s\n", i + 1, strerror(errno));
                continue;
            }

            if (sensor_value == 1) {
                counter = (counter + 1) % 256;
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);

                if (log_file) {
                    time_info = gmtime(&time(NULL));
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", time_info);
                    fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, i + 1, counter);
                }

                for (int j = 0; j < NUM_OUTPUT_PINS; j++) {
                    if (gpiod_line_set_value(output_lines[j], (counter >> (NUM_OUTPUT_PINS - 1 - j)) & 1) < 0) {
                        fprintf(stderr, "Error writing to output line %d: %s\n", OUTPUT_PINS[j], strerror(errno));
                    }
                }
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    // Cleanup on exit
    handle_signal(0);

    return 0;
}

