#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PINS {17, 18, 27, 22}
#define NUM_SENSORS 4
#define FILE_NAME "tracking_log.csv"
#define WRITE_INTERVAL 100 // in milliseconds

gpiod_chip *chip;
gpiod_line *lines[NUM_SENSORS];

void handle_signal(int signum) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_request_free(lines[i]);
    }
    gpiod_chip_put(chip);
    exit(signum);
}

void write_to_file(const char *timestamp, int sensor_values[NUM_SENSORS]) {
    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    if (fseek(file, 0, SEEK_END) != 0) {
        perror("Failed to seek to end of file");
        fclose(file);
        return;
    }

    if (fprintf(file, "%s,%d,%d,%d,%d\n", timestamp, sensor_values[0], sensor_values[1], sensor_values[2], sensor_values[3]) < 0) {
        perror("Failed to write to file");
    }

    if (fclose(file) != 0) {
        perror("Failed to close file");
    }
}

int main() {
    struct timespec ts;
    char timestamp[20];
    int sensor_values[NUM_SENSORS];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_by_name(chip, "gpio%d", GPIO_PINS[i], "sensor", GPIOD_LINE_DIRECTION_IN, 0, &lines[i]) < 0) {
            perror("Failed to request GPIO line");
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
    }

    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("Failed to open file");
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_request_free(lines[i]);
        }
        gpiod_chip_put(chip);
        return 1;
    }

    if (fprintf(file, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
        perror("Failed to write header to file");
        fclose(file);
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_request_free(lines[i]);
        }
        gpiod_chip_put(chip);
        return 1;
    }

    if (fclose(file) != 0) {
        perror("Failed to close file");
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_request_free(lines[i]);
        }
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (gpiod_line_get_value(lines[i]) < 0) {
                perror("Failed to read GPIO line");
                sensor_values[i] = -1; // Mark as error
            } else {
                sensor_values[i] = gpiod_line_get_value(lines[i]);
            }
        }

        write_to_file(timestamp, sensor_values);

        usleep(WRITE_INTERVAL * 1000); // Sleep for 100ms
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_request_free(lines[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

