#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 100
#define LOG_FILE "/var/log/tilt_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static time_t last_read_time[2] = {0, 0};
static int last_state[2] = {0, 0};

void handle_signal(int signum) {
    if (line1) {
        gpiod_line_request_free(line1);
        line1 = NULL;
    }
    if (line2) {
        gpiod_line_request_free(line2);
        line2 = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    fclose(fopen(LOG_FILE, "a")); // Close the log file
    exit(signum);
}

void log_event(int sensor, int state) {
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", now_tm);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%sSensor %d tilted\n", timestamp, sensor);
    fclose(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install signal handlers");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line1 = gpiod_line_request_by_name(chip, "gpio17", "tilt_sensor1",
                                      GPIOD_LINE_DIRECTION_INPUT,
                                      GPIOD_LINE_ACTIVE_LOW | GPIOD_LINE_OPEN_DRAIN | GPIOD_LINE_ACTIVE_LOW | GPIOD_LINE_PULL_UP);
    if (!line1) {
        fprintf(stderr, "Failed to request line for sensor 1\n");
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_line_request_by_name(chip, "gpio18", "tilt_sensor2",
                                      GPIOD_LINE_DIRECTION_INPUT,
                                      GPIOD_LINE_ACTIVE_LOW | GPIOD_LINE_OPEN_DRAIN | GPIOD_LINE_ACTIVE_LOW | GPIOD_LINE_PULL_UP);
    if (!line2) {
        fprintf(stderr, "Failed to request line for sensor 2\n");
        gpiod_line_request_free(line1);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int state1 = gpiod_line_get_value(line1);
        int state2 = gpiod_line_get_value(line2);

        if (state1 != last_state[0] && (time(NULL) - last_read_time[0]) > DEBOUNCE_MS) {
            last_read_time[0] = time(NULL);
            if (state1 == 0) {
                log_event(1, state1);
            }
            last_state[0] = state1;
        }

        if (state2 != last_state[1] && (time(NULL) - last_read_time[1]) > DEBOUNCE_MS) {
            last_read_time[1] = time(NULL);
            if (state2 == 0) {
                log_event(2, state2);
            }
            last_state[1] = state2;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

