        if (state2 != last_state[1] && (time(NULL) - last_read_time[1]) > DEBOUNCE_MS) {
            last_read_time[1] = time(NULL);
            if (state2 == 0) {
                log_event(2, state2);
            }
            last_state[1] = state2;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}
