    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;
    struct gpiod_line_consumer *consumer;
    struct gpiod_line_consumer_request *consumer_req;
    struct gpiod_line_consumer_request_type consumer_req_type;

