    }

    if (gpiod_line_request_get(req) < 0) {
        perror("Failed to get line request for sensor2");
        goto error_request_sensor2;
    }

    sensor2 = gpiod_line_request_get_line(req);
    if (!sensor2) {
        perror("Failed to get line for sensor2");
        goto error_line_sensor2;
    }

    req = gpiod_line_request_alloc(chip, GPIO_LED, "led", 0);
