This C program reads reflectance data from two TCRT5000 IR obstacle-avoidance sensor modules connected to GPIO17 and GPIO27 on a Raspberry Pi 3 Model B+. It drives an LED on GPIO22, turning it high only when both sensors read 0 (indicating an obstacle). The program polls both sensors every 100 ms, logs each sample to a file named `obstacle_log.csv`, and handles errors and resource releases gracefully on SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

volatile sig_atomic_t stop_sampling = 0;

void handle_sigint(int signum) {
    stop_sampling = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_in, *line_out;
    struct gpiod_line_request request;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Initialize GPIO chip
    if ((chip = gpiod_chip_open("/dev/gpiomem")) == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO4 as input
    memset(&request, 0, sizeof(request));
    request.consumer = "sample_microphone";
    request.request_type = GPIO_REQUEST_INPUT;
    request.flags = GPIO_ACTIVE_LOW;
    request.consumer_gpios = "4";
    if ((line_in = gpiod_line_request_by_name(chip, "4", &request)) == NULL) {
        perror("Failed to request GPIO4 as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO17 as output
    memset(&request, 0, sizeof(request));
    request.consumer = "control_led";
    request.request_type = GPIO_REQUEST_OUTPUT;
    request.flags = GPIO_ACTIVE_LOW;
    request.consumer_gpios = "17";
    if ((line_out = gpiod_line_request_by_name(chip, "17", &request)) == NULL) {
        perror("Failed to request GPIO17 as output");
        gpiod_line_free(line_in);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    // Sampling loop
    while (!stop_sampling) {
        int value;
        if (gpiod_line_get_value(line_in, &value) < 0) {
            perror("Failed to read GPIO4 value");
            gpiod_line_free(line_in);
            gpiod_line_free(line_out);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (value == 1) { // HIGH reading (sound peak)
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("%ld.%06ld\n", (long)ts.tv_sec, (long)ts.tv_nsec / 1000);

            // Turn on LED for 100ms
            if (gpiod_line_set_value(line_out, 0) < 0) {
                perror("Failed to set GPIO17 value");
                gpiod_line_free(line_in);
                gpiod_line_free(line_out);
                gpiod_chip_close(chip);
                return EXIT_FAILURE;
            }
            usleep(100000); // 100ms delay

            // Turn off LED
            if (gpiod_line_set_value(line_out, 1) < 0) {
                perror("Failed to set GPIO17 value");
                gpiod_line_free(line_in);
                gpiod_line_free(line_out);
                gpiod_chip_close(chip);
                return EXIT_FAILURE;
            }
        }

        // Sleep for 125us (8kHz sampling rate)
        usleep(125);
    }

    // Clean up
    gpiod_line_free(line_in);
    gpiod_line_free(line_out);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

