#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

static struct gpiod_line *left_sensor, *center_sensor, *right_sensor;

void cleanup(void) {
    if (left_sensor) {
        gpiod_line_request_release(left_sensor);
        free(left_sensor);
    }
    if (center_sensor) {
        gpiod_line_request_release(center_sensor);
        free(center_sensor);
    }
    if (right_sensor) {
        gpiod_line_request_release(right_sensor);
        free(right_sensor);
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize libgpiod
    if ((ret = gpiod_chip_open(NULL, &chip)) < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    req = gpiod_line_request_by_name(chip, "gpio%d", LEFT_SENSOR_PIN, "left_sensor", 0);
    if (!req) {
        perror("gpiod_line_request_by_name (left)");
        goto cleanup_and_exit;
    }
    left_sensor = gpiod_line_request_get(req);
    if (!left_sensor) {
        perror("gpiod_line_request_get (left)");
        goto cleanup_and_exit;
    }

    req = gpiod_line_request_by_name(chip, "gpio%d", CENTER_SENSOR_PIN, "center_sensor", 0);
    if (!req) {
        perror("gpiod_line_request_by_name (center)");
        goto cleanup_and_exit;
    }
    center_sensor = gpiod_line_request_get(req);
    if (!center_sensor) {
        perror("gpiod_line_request_get (center)");
        goto cleanup_and_exit;
    }

    req = gpiod_line_request_by_name(chip, "gpio%d", RIGHT_SENSOR_PIN, "right_sensor", 0);
    if (!req) {
        perror("gpiod_line_request_by_name (right)");
        goto cleanup_and_exit;
    }
    right_sensor = gpiod_line_request_get(req);
    if (!right_sensor) {
        perror("gpiod_line_request_get (right)");
        goto cleanup_and_exit;
    }

    // Configure GPIO lines as active-low inputs with internal pull-up resistors
    if ((ret = gpiod_line_set_function(left_sensor, GPIOF_INPUT_ACTIVE_LOW)) < 0) {
        perror("gpiod_line_set_function (left)");
        goto cleanup_and_exit;
    }
    if ((ret = gpiod_line_set_function(center_sensor, GPIOF_INPUT_ACTIVE_LOW)) < 0) {
        perror("gpiod_line_set_function (center)");
        goto cleanup_and_exit;
    }
    if ((ret = gpiod_line_set_function(right_sensor, GPIOF_INPUT_ACTIVE_LOW)) < 0) {
        perror("gpiod_line_set_function (right)");
        goto cleanup_and_exit;
    }

    while (1) {
        int left_state = gpiod_line_get_value(left_sensor);
        int center_state = gpiod_line_get_value(center_sensor);
        int right_state = gpiod_line_get_value(right_sensor);

        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        usleep(100000); // Sleep for 100 ms
    }

cleanup_and_exit:
    cleanup();
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

