#define ALS_ADDR 0x60
#define ALS_REG_LSB 0x00
#define ALS_REG_MSB 0x01
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int read_als_sensor(int fd) {
    unsigned char lsb, msb;
    int raw_value;

    if (read(fd, &lsb, 1) != 1) {
        perror("Error reading LSB register");
        return -1;
    }

    if (read(fd, &msb, 1) != 1) {
        perror("Error reading MSB register");
        return -1;
    }

    raw_value = (msb << 8) | lsb;
    return raw_value;
}

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data msg;
    struct i2c_msg msg_array[2];

    signal(SIGINT, handle_sigint);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ALS_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(fd);
        return 1;
    }

    msg_array[0].addr = ALS_ADDR;
    msg_array[0].flags = 0;
    msg_array[0].len = 1;
    msg_array[0].buf = &ALS_REG_LSB;

    msg_array[1].addr = ALS_ADDR;
    msg_array[1].flags = 0;
    msg_array[1].len = 2;
    msg_array[1].buf = malloc(2);

    msg.msgs = msg_array;
    msg.nmsgs = 2;

    while (!stop_flag) {
        if (ioctl(fd, I2C_RDWR, &msg) < 0) {
            perror("Error during I2C transaction");
            free(msg_array[1].buf);
            close(fd);
            return 1;
        }

        int raw_value = read_als_sensor(fd);
        if (raw_value < 0) {
            free(msg_array[1].buf);
            close(fd);
            return 1;
        }

        printf("ALS Raw Value: %d\n", raw_value);

        free(msg_array[1].buf);
        msg_array[1].buf = malloc(2);

        usleep(100000); // 100 ms delay
    }

    free(msg_array[1].buf);
    close(fd);
    return 0;
}

