#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_LEFT 2
#define GPIO_MIDDLE 3
#define GPIO_RIGHT 4
#define POLL_INTERVAL 100 // in milliseconds

static struct gpiod_line *lines[3];

void cleanup(int signum) {
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_request_release(lines[i]);
            gpiod_line_get_release(lines[i]);
            gpiod_line_open_release(lines[i]);
        }
    }
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Initialize libgpiod
    ret = gpiod_chip_open("/dev/gpiochip0", &chip);
    if (ret < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Open and request GPIO lines
    for (int i = 0; i < 3; i++) {
        ret = gpiod_line_open(chip, i, &line);
        if (ret < 0) {
            perror("gpiod_line_open");
            goto cleanup;
        }

        ret = gpiod_line_get(line);
        if (ret < 0) {
            perror("gpiod_line_get");
            goto cleanup;
        }

        ret = gpiod_line_request(line, "sensor_line", GPIOD_LINE_DIRECTION_IN);
        if (ret < 0) {
            perror("gpiod_line_request");
            goto cleanup;
        }

        lines[i] = line;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        char output[10];
        output[0] = 'L';
        output[1] = (lines[0]->value == 0) ? '0' : '1';
        output[2] = ' ';
        output[3] = 'M';
        output[4] = (lines[1]->value == 0) ? '0' : '1';
        output[5] = ' ';
        output[6] = 'R';
        output[7] = (lines[2]->value == 0) ? '0' : '1';
        output[8] = '\n';
        output[9] = '\0';

        printf("%s", output);

        usleep(POLL_INTERVAL * 1000); // Sleep for 100ms
    }

cleanup:
    // Cleanup
    cleanup(0);

    return EXIT_SUCCESS;
}

