#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_TP1 5
#define GPIO_TP2 6
#define GPIO_TP3 13
#define GPIO_TP4 19
#define GPIO_TP5 26
#define GPIO_TP6 12
#define GPIO_TP7 16
#define GPIO_TP8 20

static struct gpiod_line *lines[8];
static struct gpiod_chip *chip;

void handle_signal(int signum) {
    for (int i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_request_release(lines[i]);
        }
    }
    gpiod_chip_put(chip);
    exit(signum);
}

int main() {
    struct timespec start_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiomem");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_line_request_by_name(chip, "gpio%d", i + GPIO_TP1, 0);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request line GPIO%d\n", i + GPIO_TP1);
            for (int j = 0; j < i; j++) {
                gpiod_line_request_release(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
    }

    while (1) {
        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        int values[8];
        for (int i = 0; i < 8; i++) {
            int result = gpiod_line_get_value(lines[i]);
            if (result < 0) {
                fprintf(stderr, "Failed to read line GPIO%d\n", i + GPIO_TP1);
                for (int j = 0; j < i; j++) {
                    gpiod_line_request_release(lines[j]);
                }
                gpiod_chip_put(chip);
                return 1;
            }
            values[i] = result;
        }

        printf("%.3fs ", elapsed_time);
        for (int i = 0; i < 8; i++) {
            printf("CH%d=%d ", i + 1, values[i]);
        }
        printf("\n");

        usleep(200000); // 200 ms
    }

    for (int i = 0; i < 8; i++) {
        gpiod_line_request_release(lines[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

