#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define NUM_STEPS 50
#define INTERVAL 5000000 // 5 seconds in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *lines[3];
static struct gpiod_pwm *pwms[3];

void handle_signal(int signum) {
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_request_release(lines[i]);
            free(lines[i]);
        }
        if (pwms[i]) {
            gpiod_pwm_free(pwms[i]);
            free(pwms[i]);
        }
    }
    gpiod_chip_free(chip);
    closelog();
    exit(signum);
}

void setup_logging() {
    openlog("led_fade", LOG_PID, LOG_USER);
}

void setup_gpiod() {
    int ret;

    chip = gpiod_chip_open("/dev/gpiomem");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(1);
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_line_request(chip, i + GPIO_RED, "led_fade",
                                      GPIOD_LINE_DIRECTION_OUTPUT);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to request GPIO line %d", i + GPIO_RED);
            exit(1);
        }

        pwms[i] = gpiod_pwm_request(chip, i + GPIO_RED, "led_fade", PWM_FREQ,
                                   PWM_RANGE);
        if (!pwms[i]) {
            syslog(LOG_ERR, "Failed to request PWM for GPIO %d", i + GPIO_RED);
            exit(1);
        }

        gpiod_line_free(lines[i]);
        free(lines[i]);
    }
}

void fade_led(int start_color, int end_color) {
    int step_size = (end_color - start_color) / NUM_STEPS;
    int current_color = start_color;

    for (int i = 0; i < NUM_STEPS; i++) {
        gpiod_pwm_set_duty_cycle(pwms[0], current_color);
        gpiod_pwm_set_duty_cycle(pwms[1], current_color);
        gpiod_pwm_set_duty_cycle(pwms[2], current_color);

        current_color += step_size;
        if (current_color > PWM_RANGE) {
            current_color = PWM_RANGE;
        }

        usleep(INTERVAL / NUM_STEPS);
    }
}

int main() {
    setup_logging();
    setup_gpiod();

    srand(open("/dev/urandom", O_RDONLY, 0) ? 0 : 1);

    while (1) {
        int start_color = rand() % PWM_RANGE;
        int end_color = rand() % PWM_RANGE;

        fade_led(start_color, end_color);
    }

    return 0;
}

