#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>

#define BH1750_ADDR 0x23
#define BH1750_MEAS_CONT_HIGH_RES 0x20
#define BH1750_MEAS_CONT_LOW_RES 0x10
#define BH1750_MEAS_SINGLE_HIGH_RES 0x30
#define BH1750_MEAS_SINGLE_LOW_RES 0x20

#define GPIO_BASE "/dev/gpiomem"
#define GPIO_CLK 18
#define GPIO_DATA 19

#define PWM_CLK 0x0020C000
#define PWM_DATA 0x0020C004
#define PWM_RANGE 0x0020C008
#define PWM_DATA_LEN 0x0020C00C

#define WS2812_FREQ 8000000
#define WS2812_DATA_LEN 24

volatile unsigned *gpio_base;
volatile unsigned *pwm_base;

void cleanup() {
    if (gpio_base) {
        munmap(gpio_base, 0x400000);
    }
    if (pwm_base) {
        munmap(pwm_base, 0x400000);
    }
    exit(0);
}

void handle_signal(int signum) {
    cleanup();
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, uint8_t len) {
    int ret;
    uint8_t buf[len + 1];

    buf[0] = reg;
    ret = write(fd, buf, len + 1);
    if (ret != len + 1) {
        return -1;
    }

    ret = read(fd, data, len);
    if (ret != len) {
        return -1;
    }

    return 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, uint8_t len) {
    int ret;
    uint8_t buf[len + 1];

    buf[0] = reg;
    memcpy(buf + 1, data, len);
    ret = write(fd, buf, len + 1);
    if (ret != len + 1) {
        return -1;
    }

    return 0;
}

void set_led_brightness(int brightness) {
    uint32_t data = 0;
    int i;

    for (i = 0; i < 10; i++) {
        data |= (brightness << (i * 8));
    }

    pwm_base[PWM_DATA_LEN] = WS2812_DATA_LEN;
    pwm_base[PWM_DATA] = data;
}

int main() {
    int fd;
    uint8_t lux_data[2];
    uint16_t lux;
    int brightness;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    gpio_base = mmap(NULL, 0x400000, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (gpio_base == MAP_FAILED) {
        perror("Failed to mmap GPIO");
        close(fd);
        return 1;
    }

    pwm_base = mmap(NULL, 0x400000, PROT_READ | PROT_WRITE, MAP_SHARED, fd, PWM_CLK);
    if (pwm_base == MAP_FAILED) {
        perror("Failed to mmap PWM");
        munmap(gpio_base, 0x400000);
        close(fd);
        return 1;
    }

    pwm_base[PWM_RANGE] = WS2812_FREQ / 2;
    pwm_base[PWM_CLK] = 1;

    while (1) {
        if (i2c_write(fd, BH1750_MEAS_CONT_HIGH_RES, NULL, 0) < 0) {
            perror("Failed to start BH1750 measurement");
            continue;
        }

        usleep(180000);

        if (i2c_read(fd, 0x00, lux_data, 2) < 0) {
            perror("Failed to read BH1750 data");
            continue;
        }

        lux = (lux_data[0] << 8) | lux_data[1];
        brightness = (lux > 10000) ? 255 : (int)(255 * log10(lux + 1) / log10(10000 + 1));

        set_led_brightness(brightness);

        usleep(1000000);
    }

    cleanup();
    return 0;
}

