#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define BH1750_ADDR 0x23
#define BH1750_MEAS_CONT 0x00
#define BH1750_MEAS_ONCE 0x01
#define BH1750_MEAS_MODE 0x0F
#define BH1750_MEAS_MODE_CONT 0x00
#define BH1750_MEAS_MODE_ONCE 0x01
#define BH1750_MEAS_MODE_LOW_RES 0x02
#define BH1750_MEAS_MODE_HIGH_RES 0x03
#define BH1750_MEAS_MODE_EXT_LOW_RES 0x04
#define BH1750_MEAS_MODE_EXT_HIGH_RES 0x05
#define BH1750_MEAS_MODE_EXT_ULTRA_HIGH_RES 0x06
#define BH1750_MEAS_MODE_EXT_ULTRA_HIGH_RES_2 0x07

#define LED_COUNT 32
#define LED_DATA_SIZE (LED_COUNT * 4)

int i2c_fd;
int spi_fd;

void handle_signal(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_bh1750(void) {
    int ret;
    uint8_t data[2];

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if ((ret = read(i2c_fd, data, 2)) != 2) {
        perror("Failed to read BH1750 data");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

void set_led_brightness(int brightness) {
    uint8_t spi_data[LED_DATA_SIZE + 8];
    int i;

    memset(spi_data, 0, sizeof(spi_data));

    spi_data[0] = 0x00; // Start frame
    spi_data[1] = 0x00;
    spi_data[2] = 0x00;
    spi_data[3] = 0x00;

    for (i = 0; i < LED_COUNT; i++) {
        spi_data[4 + (i * 4)] = 0x00; // Blue
        spi_data[5 + (i * 4)] = 0x00; // Green
        spi_data[6 + (i * 4)] = 0x00; // Red
        spi_data[7 + (i * 4)] = brightness; // Brightness
    }

    spi_data[LED_DATA_SIZE + 0] = 0x00; // End frame
    spi_data[LED_DATA_SIZE + 1] = 0x00;
    spi_data[LED_DATA_SIZE + 2] = 0x00;
    spi_data[LED_DATA_SIZE + 3] = 0x00;

    if (write(spi_fd, spi_data, sizeof(spi_data)) != sizeof(spi_data)) {
        perror("Failed to write to SPI");
    }
}

int main(void) {
    struct spi_ioc_transfer spi_transfer;
    struct i2c_smbus_ioctl_data i2c_data;
    int ret;

    signal(SIGINT, handle_signal);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE_0) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_8) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS_8) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &1000000) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &1000000) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (ioctl(i2c_fd, I2C_SMBUS, I2C_SMBUS_WRITE, BH1750_ADDR, BH1750_MEAS_CONT, 0, 0) < 0) {
            perror("Failed to initiate BH1750 measurement");
            break;
        }

        usleep(120000); // Wait 120ms

        int brightness = read_bh1750();
        if (brightness < 0) {
            break;
        }

        set_led_brightness(brightness / 100); // Scale brightness
    }

    close(spi_fd);
    close(i2c_fd);

    return 0;
}

