#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x60
#define LUX_REG 0x00
#define GAMMA_SCALE 0.001
#define MAX_BRIGHTNESS 255
#define GPIO_PIN 18
#define GPIO_DIR "/sys/class/gpio/gpio%d/direction"
#define GPIO_VAL "/sys/class/gpio/gpio%d/value"

int i2c_fd;
int lux_reading;
int brightness;

void handle_signal(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    write_gpio(GPIO_PIN, 0); // Turn off LED strip
    close(i2c_fd); // Close I2C file descriptor
    exit(signum);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_i2c() {
    char i2c_file[20];
    sprintf(i2c_file, "/dev/i2c-%d", 1); // Assuming I2C bus 1
    i2c_fd = open(i2c_file, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int read_lux() {
    int retries = 3;
    while (retries > 0) {
        if (write(i2c_fd, &LUX_REG, 1) != 1) {
            perror("Failed to write to I2C device");
            sleep(0.1);
            continue;
        }
        if (read(i2c_fd, &lux_reading, 1) != 1) {
            perror("Failed to read from I2C device");
            sleep(0.1);
            continue;
        }
        return lux_reading;
    }
    fprintf(stderr, "Failed to read LUX value after %d retries\n", retries);
    return -1;
}

void write_gpio(int pin, int value) {
    char direction[20];
    char value_str[20];
    sprintf(direction, GPIO_DIR, pin);
    sprintf(value_str, GPIO_VAL, pin);

    FILE *dir_file = fopen(direction, "w");
    if (dir_file == NULL) {
        perror("Failed to open GPIO direction file");
        return;
    }
    fprintf(dir_file, "out");
    fclose(dir_file);

    FILE *val_file = fopen(value_str, "w");
    if (val_file == NULL) {
        perror("Failed to open GPIO value file");
        return;
    }
    fprintf(val_file, "%d", value);
    fclose(val_file);
}

int main() {
    setup_signal_handlers();

    if (open_i2c() < 0) {
        return 1;
    }

    write_gpio(GPIO_PIN, 0); // Initialize LED strip off

    while (1) {
        if (read_lux() < 0) {
            continue;
        }

        brightness = (int)(lux_reading * GAMMA_SCALE);
        brightness = (brightness > MAX_BRIGHTNESS) ? MAX_BRIGHTNESS : brightness;

        printf("Lux: %d, Brightness: %d\n", lux_reading, brightness);

        write_gpio(GPIO_PIN, brightness); // Drive LED strip

        usleep(200000); // 200 ms pause
    }

    close(i2c_fd);
    return 0;
}

