#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define FLAMESENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

static gpiod_line *flame_sensor_line;
static gpiod_line *buzzer_line;
static gpiod_line *led_line;

void handle_signal(int signum) {
    if (flame_sensor_line) {
        gpiod_line_request_release(flame_sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_request_release(buzzer_line);
    }
    if (led_line) {
        gpiod_line_request_release(led_line);
    }
    exit(signum);
}

void startup_self_test() {
    int flame_detected = 0;
    for (int i = 0; i < 5; i++) {
        gpiod_line_set_value(flame_sensor_line, 1); // Set to input
        usleep(100000); // 100ms delay
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value == 0) {
            flame_detected = 1;
            break;
        }
    }

    if (flame_detected) {
        printf("Error: Flame detected during startup self-test.\n");
        for (int i = 0; i < 5; i++) {
            gpiod_line_set_value(led_line, 1); // Turn LED on
            usleep(100000); // 100ms delay
            gpiod_line_set_value(led_line, 0); // Turn LED off
            usleep(100000); // 100ms delay
        }
        for (int i = 0; i < 3; i++) {
            gpiod_line_set_value(buzzer_line, 1); // Turn buzzer on
            usleep(200000); // 200ms delay
            gpiod_line_set_value(buzzer_line, 0); // Turn buzzer off
            usleep(200000); // 200ms delay
            gpiod_line_set_value(buzzer_line, 1); // Turn buzzer on
            usleep(600000); // 600ms delay
            gpiod_line_set_value(buzzer_line, 0); // Turn buzzer off
            usleep(200000); // 200ms delay
        }
        exit(1);
    }

    printf("Startup self-test successful.\n");
    for (int i = 0; i < 2; i++) {
        gpiod_line_set_value(led_line, 1); // Turn LED on
        usleep(500000); // 500ms delay
        gpiod_line_set_value(led_line, 0); // Turn LED off
        usleep(500000); // 500ms delay
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    flame_sensor_line = gpiod_line_request_by_name(chip, "gpio4", "flame_sensor", 0);
    if (!flame_sensor_line) {
        perror("Failed to request flame sensor line");
        exit(1);
    }

    buzzer_line = gpiod_line_request_by_name(chip, "gpio17", "buzzer", 0);
    if (!buzzer_line) {
        perror("Failed to request buzzer line");
        exit(1);
    }

    led_line = gpiod_line_request_by_name(chip, "gpio18", "led", 0);
    if (!led_line) {
        perror("Failed to request LED line");
        exit(1);
    }

