#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x23
#define BUFFER_SIZE 60
#define MAX_LUX 1000
#define GPIO_PIN 17

int i2c_fd;
int lux_buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int lux_sum = 0;
int lux_avg = 0;
int last_lux = 0;

void read_lux() {
    int lux;
    char cmd[3] = {0x00, 0x01, 0x00};
    char data[2];

    if (write(i2c_fd, cmd, 3) != 3) {
        perror("Error writing to I2C device");
        return;
    }

    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return;
    }

    lux = (data[0] << 8) | data[1];

    if (lux > MAX_LUX) {
        lux = MAX_LUX;
    }

    lux_buffer[buffer_head] = lux;
    lux_sum += lux;
    lux_sum -= lux_buffer[buffer_tail];
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    lux_avg = lux_sum / BUFFER_SIZE;
    last_lux = lux;
}

void blink_led(int lux) {
    int freq = (lux + MAX_LUX) / 2;
    int period = 1000000 / freq;
    int on_time = period / 2;

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return;
    }

    if (ioctl(i2c_fd, I2C_SMBUS, I2C_SMBUS_WRITE, 0x00, 0x00, 0) < 0) {
        perror("Error writing to I2C device");
        return;
    }

    for (int i = 0; i < 1000; i++) {
        usleep(on_time);
        if (ioctl(i2c_fd, I2C_SMBUS, I2C_SMBUS_WRITE, 0x00, 0x00, 0) < 0) {
            perror("Error writing to I2C device");
            return;
        }
        usleep(period - on_time);
        if (ioctl(i2c_fd, I2C_SMBUS, I2C_SMBUS_WRITE, 0x00, 0x00, 0) < 0) {
            perror("Error writing to I2C device");
            return;
        }
    }
}

void cleanup() {
    close(i2c_fd);
    printf("Program terminated.\n");
    exit(0);
}

void handle_sigint(int signum) {
    cleanup();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return 1;
    }

    while (1) {
        read_lux();
        blink_led(lux_avg);
        printf("Lux: %d, Average Lux: %d\n", last_lux, lux_avg);
        sleep(1);
    }

    cleanup();
    return 0;
}

