#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEGMENT_MAP { 0b11000000, 0b11111001, 0b10100100, 0b10110000, 0b10011001, 0b10010010, 0b10000010, 0b11111000, 0b10000000, 0b10010000 }

void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        gpioWrite(DATA_PIN, (data & 0x80) ? 1 : 0);
        gpioWrite(CLOCK_PIN, 1);
        data <<= 1;
        gpioDelay(1); // Small delay to ensure proper timing
        gpioWrite(CLOCK_PIN, 0);
    }
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1);
    gpioWrite(LATCH_PIN, 0);
}

void blink_digit(unsigned char digit) {
    while (1) {
        shift_out(SEGMENT_MAP[digit]);
        gpioDelay(500000); // 500 ms on
        shift_out(0); // Clear display
        gpioDelay(500000); // 500 ms off
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set DATA_PIN as output\n");
        goto cleanup;
    }

    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CLOCK_PIN as output\n");
        goto cleanup;
    }

    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LATCH_PIN as output\n");
        goto cleanup;
    }

    blink_digit(5); // Blink the digit '5'

cleanup:
    gpioTerminate();
    return 0;
}

