#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>

static gpiod_chip *chip;
static gpiod_line *led_line;
static gpiod_line *button_line;

void blink_led() {
    gpiod_line_set_value(led_line, 1); // Turn LED on
    gpiod_call(led_line, 1000000000, NULL); // Wait 1 second
    gpiod_line_set_value(led_line, 0); // Turn LED off
    gpiod_call(led_line, 1000000000, NULL); // Wait 1 second
}

void handle_button_press(int signum) {
    gpiod_line_set_value(led_line, 0); // Turn LED off
    printf("Button pressed, terminating program.\n");
    gpiod_line_request_release(button_line);
    gpiod_line_request_release(led_line);
    gpiod_chip_put(chip);
    exit(0);
}

int main() {
    int err;

    // Open GPIO chip 0
    chip = gpiod_chip_open(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip 0\n");
        return 1;
    }

    // Request LED line as output, initially set low
    led_line = gpiod_line_request(chip, "gpio17", GPIOD_LINE_DIRECTION_OUT, 0);
    if (!led_line) {
        fprintf(stderr, "Failed to request LED line\n");
        gpiod_chip_put(chip);
        return 1;
    }

    // Request button line as input with pull-up and edge detection
    button_line = gpiod_line_request(chip, "gpio18", GPIOD_LINE_DIRECTION_IN, 0);
    if (!button_line) {
        fprintf(stderr, "Failed to request button line\n");
        gpiod_line_request_release(led_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set button line to pull-up and edge detection
    gpiod_line_set_edge(button_line, GPIOD_LINE_BOTH_EDGES);
    gpiod_line_set_debounce(button_line, 1000000); // 1 ms debounce

    // Set up signal handler for button press
    struct sigaction sa;
    sa.sa_handler = handle_button_press;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Start blinking LED
    while (1) {
        blink_led();
    }

    // This point is never reached, but if it were, it would clean up
    gpiod_line_request_release(button_line);
    gpiod_line_request_release(led_line);
    gpiod_chip_put(chip);

    return 0;
}

