#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5
#define ON_DELAY 750
#define OFF_DELAY 750

void handle_sigint(int signum) {
    printf("Received SIGINT, turning off LED and cleaning up...\n");
    gpioWrite(LED_PIN, PI_OUTPUT_LOW);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    printf("Initializing GPIO pin %d as output...\n", LED_PIN);
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        printf("LED ON\n");
        fflush(stdout);
        gpioWrite(LED_PIN, PI_OUTPUT_HIGH);
        gpioDelay(ON_DELAY);

        printf("LED OFF\n");
        fflush(stdout);
        gpioWrite(LED_PIN, PI_OUTPUT_LOW);
        gpioDelay(OFF_DELAY);
    }

    return EXIT_SUCCESS;
}

