        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        printf("LED ON\n");
        fflush(stdout);
        gpioWrite(LED_PIN, PI_OUTPUT_HIGH);
        gpioDelay(ON_DELAY);

        printf("LED OFF\n");
        fflush(stdout);
        gpioWrite(LED_PIN, PI_OUTPUT_LOW);
        gpioDelay(OFF_DELAY);
    }

    return EXIT_SUCCESS;
}
