#include <libgpiod.h>

#define PWM_FREQUENCY 100 // Hz
#define PWM_PERIOD (1000000 / PWM_FREQUENCY) // microseconds
#define PWM_ON_TIME (PWM_PERIOD * 50 / 100) // 50% duty cycle

gpiod_chip *chip;
gpiod_line *red_line, *green_line, *blue_line;

void cleanup_and_exit(int signum) {
    if (red_line) {
        gpiod_line_request_release(red_line);
        free(red_line);
    }
    if (green_line) {
        gpiod_line_request_release(green_line);
        free(green_line);
    }
    if (blue_line) {
        gpiod_line_request_release(blue_line);
        free(blue_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
        free(chip);
    }
    exit(signum);
}

void drive_rgb_led() {
    int red_intensity, green_intensity, blue_intensity;
    struct timespec sleep_time;

    srand(time(NULL));

    while (1) {
        red_intensity = rand() % 101;
        green_intensity = rand() % 101;
        blue_intensity = rand() % 101;

        for (int i = 0; i < PWM_PERIOD; i += PWM_ON_TIME) {
            gpiod_line_set_value(red_line, (i < PWM_ON_TIME * red_intensity / 100));
            gpiod_line_set_value(green_line, (i < PWM_ON_TIME * green_intensity / 100));
            gpiod_line_set_value(blue_line, (i < PWM_ON_TIME * blue_intensity / 100));

            sleep_time.tv_sec = 0;
            sleep_time.tv_nsec = (i * 1000);
            clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);
        }

        sleep(1); // Wait 1 second before changing colors again
    }
}

int main() {
    int err;

    signal(SIGINT, cleanup_and_exit);

    chip = gpiod_chip_open("/dev/gpiomem");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    red_line = gpiod_line_request_by_name(chip, "24", "red_led", 0);
    if (!red_line) {
        fprintf(stderr, "Failed to request GPIO 24 for red LED\n");
        gpiod_chip_put(chip);
        return 1;
    }

    green_line = gpiod_line_request_by_name(chip, "23", "green_led", 0);
    if (!green_line) {
        fprintf(stderr, "Failed to request GPIO 23 for green LED\n");
        gpiod_line_request_release(red_line);
        gpiod_chip_put(chip);
        return 1;
    }

    blue_line = gpiod_line_request_by_name(chip, "18", "blue_led", 0);
    if (!blue_line) {
        fprintf(stderr, "Failed to request GPIO 18 for blue LED\n");
        gpiod_line_request_release(red_line);
        gpiod_line_request_release(green_line);
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_direction_set(red_line, GPIOF_OUT);
    gpiod_line_direction_set(green_line, GPIOF_OUT);
    gpiod_line_direction_set(blue_line, GPIOF_OUT);

    drive_rgb_led();

    return 0;
}

