#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>

#define LSM303DLHC_ADDR 0x1E
#define I2C_BUS "/dev/i2c-1"
#define IMPACT_THRESHOLD 2.0
#define GPIO_PIN 17
#define LOG_FILE "impact_log.txt"

static struct gpiod_line *gpio_line;
static struct i2c_client *i2c_client;
static FILE *log_file;

void handle_signal(int signum) {
    if (gpio_line) {
        gpiod_line_free(gpio_line);
    }
    if (i2c_client) {
        i2c_client_close(i2c_client);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int read_accelerometer(int *x, int *y, int *z) {
    int status;
    char buffer[6];

    status = i2c_smbus_read_i2c_block_data(i2c_client, 0x28, buffer, 6);
    if (status < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        return -1;
    }

    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];

    return 0;
}

double compute_g_force_magnitude(int x, int y, int z) {
    return sqrt(x * x + y * y + z * z) / 256.0;
}

int main(int argc, char *argv[]) {
    int x, y, z;
    double g_force;
    double threshold = IMPACT_THRESHOLD;
    struct timespec ts;

    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    if (gpiod_line_request(GPIO_PIN, "Impact Interrupt", &gpio_line, GPIOD_LINE_DIRECTION_OUT) < 0) {
        perror("gpiod_line_request");
        return 1;
    }

    if ((i2c_client = i2c_open(I2C_BUS, LSM303DLHC_ADDR)) < 0) {
        perror("i2c_open");
        gpiod_line_free(gpio_line);
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("fopen");
        i2c_client_close(i2c_client);
        gpiod_line_free(gpio_line);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (read_accelerometer(&x, &y, &z) < 0) {
            continue;
        }

        g_force = compute_g_force_magnitude(x, y, z);

        if (g_force > threshold) {
            gpiod_line_set_value(gpio_line, 1);
            nanosleep(&ts, NULL);
            ts.tv_sec = 0;
            ts.tv_nsec = 50000000; // 50 ms
            nanosleep(&ts, NULL);
            gpiod_line_set_value(gpio_line, 0);

            fprintf(log_file, "Impact detected at %.2f G at %ld.%09ld\n", g_force, ts.tv_sec, ts.tv_nsec);
        }

        nanosleep(&ts, NULL);
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 100 ms
    }

    return 0;
}

