#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD188BI_ADDR 0x50
#define ALS_LSB 0x00
#define ALS_MSB 0x01
#define RED_LSB 0x02
#define RED_MSB 0x03
#define GREEN_LSB 0x04
#define GREEN_MSB 0x05
#define BLUE_LSB 0x06
#define BLUE_MSB 0x07
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_DUTY_MAX 1023

int i2c_fd;
int led_fd;

void handle_signal(int signum) {
    if (led_fd >= 0) {
        printf("Turning off LED\n");
        close(led_fd);
    }
    if (i2c_fd >= 0) {
        printf("Closing I2C handle\n");
        close(i2c_fd);
    }
    exit(signum == SIGINT ? 0 : 1);
}

void setup_signal_handling() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int read_i2c_register(uint8_t reg) {
    uint8_t data;
    int ret = read(i2c_fd, &data, 1);
    if (ret != 1) {
        perror("Failed to read from I2C");
        return -1;
    }
    return data;
}

uint16_t read_als_value() {
    uint8_t lsb = read_i2c_register(ALS_LSB);
    uint8_t msb = read_i2c_register(ALS_MSB);
    return (msb << 8) | lsb;
}

uint16_t read_color_value(uint8_t reg) {
    uint8_t lsb = read_i2c_register(reg);
    uint8_t msb = read_i2c_register(reg + 1);
    return (msb << 8) | lsb;
}

void setup_led() {
    char path[32];
    sprintf(path, "/sys/class/gpio/gpio%d/value", LED_GPIO);
    led_fd = open(path, O_WRONLY);
    if (led_fd < 0) {
        perror("Failed to open LED GPIO");
        exit(1);
    }
}

void set_led_brightness(int brightness) {
    char duty_cycle[10];
    sprintf(duty_cycle, "%d", brightness);
    write(led_fd, duty_cycle, strlen(duty_cycle));
}

int main() {
    setup_signal_handling();

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD188BI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }

    setup_led();

    FILE *csv_file = fopen("color_log.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
