#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define FXOS8700CQ_I2C_ADDR 0x1E
#define FXOS8700CQ_WHO_AM_I 0x0A
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_CTRL_REG4 0x30
#define FXOS8700CQ_DATA_X_LSB 0x3B
#define FXOS8700CQ_DATA_Y_LSB 0x3D
#define FXOS8700CQ_DATA_Z_LSB 0x3F

#define IMPACT_THRESHOLD 1.5

static int i2c_handle;

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    exit(0);
}

int read_i2c_byte(int handle, uint8_t reg) {
    uint8_t data;
    int ret = i2c_read_byte_data(handle, reg, &data);
    if (ret < 0) {
        fprintf(stderr, "Error reading byte from register 0x%02X\n", reg);
    }
    return ret;
}

int read_i2c_word(int handle, uint8_t reg) {
    uint8_t data[2];
    int ret = i2c_read_i2c_block_data(handle, reg, 2, data);
    if (ret < 0) {
        fprintf(stderr, "Error reading word from register 0x%02X\n", reg);
    }
    return (data[0] << 8) | data[1];
}

void write_i2c_byte(int handle, uint8_t reg, uint8_t value) {
    int ret = i2c_write_byte_data(handle, reg, value);
    if (ret < 0) {
        fprintf(stderr, "Error writing byte to register 0x%02X\n", reg);
    }
}

void write_i2c_word(int handle, uint8_t reg, uint16_t value) {
    uint8_t data[2] = {(uint8_t)(value >> 8), (uint8_t)(value & 0xFF)};
    int ret = i2c_write_i2c_block_data(handle, reg, 2, data);
    if (ret < 0) {
        fprintf(stderr, "Error writing word to register 0x%02X\n", reg);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_handle = i2c_open(1, FXOS8700CQ_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    uint8_t who_am_i = read_i2c_byte(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i != 0x3A) {
        fprintf(stderr, "FXOS8700CQ not found, WHO_AM_I mismatch\n");
        i2c_close(i2c_handle);
        return 1;
    }

    write_i2c_byte(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00); // Standby mode
    write_i2c_byte(i2c_handle, FXOS8700CQ_CTRL_REG4, 0x00); // ±2g range
    write_i2c_byte(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x0F); // 200Hz output data rate

    FILE *log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(i2c_handle);
        return 1;
    }

    while (1) {
        uint8_t data[6];
        int ret = i2c_read_i2c_block_data(i2c_handle, FXOS8700CQ_DATA_X_LSB, 6, data);
        if (ret < 0) {
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        double magnitude = sqrt(x * x + y * y + z * z);

        if (magnitude > IMPACT_THRESHOLD) {
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
        }

        usleep(50000); // 50ms delay
    }

    fclose(log_file);
    i2c_close(i2c_handle);

    return 0;
}

