#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define GYRO_ADDR 0x6B
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define OUT_X_L 0x28
#define OUT_Y_L 0x2A
#define OUT_Z_L 0x2C
#define SAMPLE_RATE 100
#define LOG_FILE "gyro_log.txt"
#define ALERT_THRESHOLD 50

int i2c_fd;
int log_fd;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != -1) {
        fclose(log_fd);
    }
    exit(signum);
}

int read_byte(int reg) {
    int data;
    if (read(i2c_fd, &data, 1) != 1) {
        perror("read");
        return -1;
    }
    return data;
}

int write_byte(int reg, int value) {
    if (write(i2c_fd, &value, 1) != 1) {
        perror("write");
        return -1;
    }
    return 0;
}

int calibrate_gyro() {
    int x_offset = 0, y_offset = 0, z_offset = 0;
    for (int i = 0; i < SAMPLE_RATE; i++) {
        int x = read_byte(OUT_X_L) | (read_byte(OUT_X_H) << 8);
        int y = read_byte(OUT_Y_L) | (read_byte(OUT_Y_H) << 8);
        int z = read_byte(OUT_Z_L) | (read_byte(OUT_Z_H) << 8);
        x_offset += x;
        y_offset += y;
        z_offset += z;
        usleep(50000); // 50 ms delay
    }
    x_offset /= SAMPLE_RATE;
    y_offset /= SAMPLE_RATE;
    z_offset /= SAMPLE_RATE;
    printf("Calibration offsets: X=%d, Y=%d, Z=%d\n", x_offset, y_offset, z_offset);
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(i2c_fd);
        return 1;
    }

    int who_am_i = read_byte(WHO_AM_I);
    if (who_am_i != 0x68) {
        printf("GY-50 L3G4200D not found\n");
        close(i2c_fd);
        return 1;
    }

    calibrate_gyro();

    log_fd = fopen(LOG_FILE, "a");
    if (log_fd == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        int x = read_byte(OUT_X_L) | (read_byte(OUT_X_H) << 8);
        int y = read_byte(OUT_Y_L) | (read_byte(OUT_Y_H) << 8);
        int z = read_byte(OUT_Z_L) | (read_byte(OUT_Z_H) << 8);

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);

        fprintf(log_fd, "%s, X=%d, Y=%d, Z=%d\n", timestamp, x, y, z);
        fflush(log_fd);

        if (x > ALERT_THRESHOLD || x < -ALERT_THRESHOLD ||
            y > ALERT_THRESHOLD || y < -ALERT_THRESHOLD ||
            z > ALERT_THRESHOLD || z < -ALERT_THRESHOLD) {
            fprintf(stderr, "Alert: Axis exceeded threshold\n");
            fprintf(log_fd, "%s, ALERT: Axis exceeded threshold\n", timestamp);
            fflush(log_fd);
        }

        usleep(50000); // 50 ms delay
    }

    fclose(log_fd);
    close(i2c_fd);
    return 0;
}

