#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define ADXL345_DEVID 0x0D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 3
#define ADXL345_DATAZ0 4
#define LED_GPIO 17
#define LOG_FILE "accel_log.txt"

static struct gpiod_line *led_line;
static FILE *log_file;

void handle_signal(int signum) {
    gpiod_line_free(led_line);
    fclose(log_file);
    exit(signum);
}

int read_acceleration(int *x, int *y, int *z) {
    int status;
    uint8_t data[6];

    status = i2c_read_device(I2C_BUS, ADXL345_ADDR, ADXL345_DATAX0, data, 6);
    if (status != 0) {
        return -1;
    }

    *x = (data[0] << 8) | data[1];
    *y = (data[2] << 8) | data[3];
    *z = (data[4] << 8) | data[5];

    return 0;
}

int main() {
    int x, y, z;
    int status;
    struct timespec sleep_time;
    struct timespec start_time;
    struct timespec end_time;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpiod_line_request(LED_GPIO, "led", GPIOD_LINE_DIRECTION_OUTPUT, &led_line) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (i2c_read_device(I2C_BUS, ADXL345_ADDR, ADXL345_DEVID, &status, 1) != 0 || status != ADXL345_DEVID) {
        fprintf(stderr, "Failed to verify ADXL345 device ID\n");
        return 1;
    }

    while (1) {
        if (read_acceleration(&x, &y, &z) < 0) {
            continue;
        }

        double g_x = (double)x / 256.0;
        double g_y = (double)y / 256.0;
        double g_z = (double)z / 256.0;

        if (abs(g_x) > 2.0 || abs(g_y) > 2.0 || abs(g_z) > 2.0) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        time(&start_time);
        fprintf(log_file, "%.3f,%.3f,%.3f\n", g_x, g_y, g_z);
        time(&end_time);

        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 ms

        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

