#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define LSM303DLHC_ADDRESS 0x1E
#define I2C_BUS 1
#define SAMPLING_INTERVAL 100 // in milliseconds

// Function prototypes
void handle_signal(int signum);
void log_data(const char *filename, double heading, double ax, double ay, double az, double mx, double my, double mz);

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct i2c_client *client;
    struct i2c_msg msg[2];
    struct i2c_block_transfer block;
    int ret;
    double heading, ax, ay, az, mx, my, mz;
    char filename[] = "compass_log.txt";
    FILE *file;

    // Initialize GPIOn
    chip = gpiod_chip_open("/dev/i2c-1");
    if (!chip) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open I2C client
    client = i2c_client_new(chip, LSM303DLHC_ADDRESS, I2C_BUS);
    if (!client) {
        perror("Failed to open I2C client");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open file for logging
    file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        i2c_client_close(client);
        gpiod_chip_close(chip);
        return 1;
    }

    // Write CSV header if file is new
    if (fseek(file, 0, SEEK_END) == 0 && ftell(file) == 0) {
        fprintf(file, "Timestamp,Heading,Ax,Ay,Az,Mx,My,Mz\n");
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read accelerometer data
        block.addr = 0x28;
        block.len = 6;
        block.buf = &ax;
        ret = i2c_smbus_read_i2c_block_data(client, &block);
        if (ret < 0) {
            perror("Failed to read accelerometer data");
            break;
        }

        // Read magnetometer data
        block.addr = 0x08;
        block.len = 6;
        block.buf = &mx;
        ret = i2c_smbus_read_i2c_block_data(client, &block);
        if (ret < 0) {
            perror("Failed to read magnetometer data");
            break;
        }

        // Compute tilt-compensated heading
        // (This is a simplified example; actual computation would be more complex)
        heading = atan2(ay, ax) * 180.0 / M_PI;

        // Log data
        log_data(filename, heading, ax, ay, az, mx, my, mz);

        // Sleep for the sampling interval
        usleep(SAMPLING_INTERVAL * 1000);
    }

    // Cleanup
    fclose(file);
    i2c_client_close(client);
    gpiod_chip_close(chip);

    return 0;
}

void handle_signal(int signum) {
    // Perform graceful shutdown
    // (In this example, we just exit the main loop)
    exit(0);
}

void log_data(const char *filename, double heading, double ax, double ay, double az, double mx, double my, double mz) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%f,%f,%f,%f,%f,%f,%f\n", buffer, heading, ax, ay, az, mx, my, mz);
    fclose(file);
}

