#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define VL6180X_I2C_ADDR 0x29
#define VL6180X_RANGE_HIGH 0x00
#define VL6180X_RANGE_LOW  0x01

#define BUFFER_SIZE 2

int i2c_file_descriptor;

void handle_sigint(int signum) {
    close(i2c_file_descriptor);
    exit(0);
}

int init_i2c() {
    char device_path[20];
    sprintf(device_path, "/dev/i2c-%d", 1);

    i2c_file_descriptor = open(device_path, O_RDWR);
    if (i2c_file_descriptor < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_file_descriptor, I2C_SLAVE, VL6180X_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_file_descriptor);
        return -1;
    }

    return 0;
}

int read_distance() {
    uint8_t buffer[BUFFER_SIZE];
    int bytes_read;

    bytes_read = read(i2c_file_descriptor, buffer, BUFFER_SIZE);
    if (bytes_read != BUFFER_SIZE) {
        perror("Failed to read distance from sensor");
        return -1;
    }

    return (buffer[VL6180X_RANGE_HIGH] << 8) | buffer[VL6180X_RANGE_LOW];
}

int main() {
    int distance;
    FILE *log_file;

    signal(SIGINT, handle_sigint);

    if (init_i2c() < 0) {
        return 1;
    }

    log_file = fopen("distance_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_file_descriptor);
        return 1;
    }

    while (1) {
        distance = read_distance();
        if (distance < 0) {
            init_i2c();
            continue;
        }

        if (distance < 100) {
            fprintf(log_file, "DOOR_OPEN\n");
        } else {
            fprintf(log_file, "DOOR_CLOSED\n");
        }

        fprintf(log_file, "%d\n", distance);
        fflush(log_file);

        usleep(100000); // Sleep for 100 ms
    }

    fclose(log_file);
    close(i2c_file_descriptor);

    return 0;
}

