#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x40
#define SENSOR2_ADDR 0x41
#define SAMPLE_INTERVAL 10 // 10 ms
#define LOG_FILE "audio_log.dat"

// Function prototypes
void handle_sigint(int signum);
int read_sensor_sample(int i2c_handle, uint8_t addr);

int main() {
    struct i2c_device *i2c_handle1 = NULL;
    struct i2c_device *i2c_handle2 = NULL;
    FILE *log_file = NULL;

    // Initialize signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus
    i2c_handle1 = i2c_open(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 == NULL) {
        fprintf(stderr, "Failed to open I2C bus for sensor 1.\n");
        return 1;
    }

    i2c_handle2 = i2c_open(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 == NULL) {
        fprintf(stderr, "Failed to open I2C bus for sensor 2.\n");
        i2c_close(i2c_handle1);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2c_close(i2c_handle1);
        i2c_close(i2c_handle2);
        return 1;
    }

    // Main loop
    while (1) {
        int sample1 = read_sensor_sample(i2c_handle1, SENSOR1_ADDR);
        int sample2 = read_sensor_sample(i2c_handle2, SENSOR2_ADDR);

        if (sample1 != -1 && sample2 != -1) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);

            fprintf(log_file, "%ld,%ld,%d,%d,%.6f\n",
                    ts.tv_sec, ts.tv_nsec / 1000000, sample1, sample2,
                    (double)(sample1 - sample2) / 1000000.0);
        }

        usleep(SAMPLE_INTERVAL * 1000); // Sleep for 10 ms
    }

    // Cleanup
    fclose(log_file);
    i2c_close(i2c_handle1);
    i2c_close(i2c_handle2);

    return 0;
}

void handle_sigint(int signum) {
    // Cleanup resources
    fclose(log_file);
    i2c_close(i2c_handle1);
    i2c_close(i2c_handle2);

    // Terminate driver library
    exit(0);
}

int read_sensor_sample(int i2c_handle, uint8_t addr) {
    uint8_t buffer[2];
    int bytes_read = i2c_read_device(i2c_handle, addr, buffer, 2);

    if (bytes_read != 2) {
        return -1; // Error reading from sensor
    }

    // Convert 16-bit signed sample
    int16_t sample = (int16_t)((buffer[0] << 8) | buffer[1]);

    return sample;
}

