            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);

            fprintf(log_file, "%ld,%ld,%d,%d,%.6f\n",
                    ts.tv_sec, ts.tv_nsec / 1000000, sample1, sample2,
                    (double)(sample1 - sample2) / 1000000.0);
        }

        usleep(SAMPLE_INTERVAL * 1000); // Sleep for 10 ms
    }

    // Cleanup
    fclose(log_file);
    i2c_close(i2c_handle1);
    i2c_close(i2c_handle2);

    return 0;
}

void handle_sigint(int signum) {
    // Cleanup resources
    fclose(log_file);
    i2c_close(i2c_handle1);
    i2c_close(i2c_handle2);

    // Terminate driver library
    exit(0);
}

int read_sensor_sample(int i2c_handle, uint8_t addr) {
    uint8_t buffer[2];
    int bytes_read = i2c_read_device(i2c_handle, addr, buffer, 2);

    if (bytes_read != 2) {
        return -1; // Error reading from sensor
    }

    // Convert 16-bit signed sample
    int16_t sample = (int16_t)((buffer[0] << 8) | buffer[1]);

    return sample;
}
