static volatile sig_atomic_t running = 1;

void cleanup() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (spi_cs_line) {
        gpiod_line_free(spi_cs_line);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    running = 0;
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup();
    }
}

int read_imu_data(uint16_t command, uint16_t *data) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long) &command,
        .rx_buf = (unsigned long) data,
        .len = 2,
        .delay_usecs = STALL_TIME,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 16,
        .cs_change = 1,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        perror("SPI read error");
        return ret;
    }

    return 0;
}

