    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction error");
        return 1;
    }

    if (gpiod_open("/dev/gpiomem", &spi_cs_line) < 0) {
        perror("gpiod_open error");
        return 1;
    }

    if (gpiod_line_request(spi_cs_line, "SPI_CS", GPIOF_OUTPUT_HIGH) < 0) {
        perror("gpiod_line_request error");
        return 1;
    }

    if ((spi_fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("SPI open error");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI ioctl error");
        return 1;
    }

    csv_file = fopen("imu_data.csv", "w");
    if (!csv_file) {
        perror("fopen error");
        return 1;
    }

    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    while (running) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        uint64_t timestamp = tv.tv_sec * 1000 + tv.tv_usec / 1000;

        uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        uint16_t command = 0x0000; // MSB is 0, followed by 7-bit register address

        if (read_imu_data(command, &gyro_x) < 0 ||
            read_imu_data(command, &gyro_y) < 0 ||
            read_imu_data(command, &gyro_z) < 0 ||
            read_imu_data(command, &accel_x) < 0 ||
            read_imu_data(command, &accel_y) < 0 ||
            read_imu_data(command, &accel_z) < 0) {
            continue;
        }

        double gyro_x_deg = gyro_x * GYRO_SENSITIVITY;
        double gyro_y_deg = gyro_y * GYRO_SENSITIVITY;
        double gyro_z_deg = gyro_z * GYRO_SENSITIVITY;

        double accel_x_g = accel_x * ACCEL_SENSITIVITY;
        double accel_y_g = accel_y * ACCEL_SENSITIVITY;
        double accel_z_g = accel_z * ACCEL_SENSITIVITY;

        fprintf(csv_file, "%llu,%f,%f,%f,%f,%f,%f\n", timestamp, gyro_x_deg, gyro_y_deg, gyro_z_deg, accel_x_g, accel_y_g, accel_z_g);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

