void cleanup(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
        printf("SPI device file closed.\n");
    }
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(0)) < 0) {
        perror("Failed to release SPI device");
    }
    printf("Clean exit.\n");
    exit(0);
}

int main() {
    struct spi_ioc_transfer spi_transfer;
    uint8_t reg_addr = 0x00; // Example register address
    uint16_t data;
    double gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

