    // Open SPI device
    if ((spi_fd = open(SPI_DEV_PATH, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and max speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        goto error_close_spi;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        goto error_close_spi;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        perror("Failed to set SPI max speed");
        goto error_close_spi;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        perror("Failed to read SPI max speed");
        goto error_close_spi;
    }

    // Main loop
    while (1) {
        // Prepare SPI transfer
        memset(&spi_transfer, 0, sizeof(spi_transfer));
        spi_transfer.tx_buf = (unsigned long) &reg_addr;
        spi_transfer.rx_buf = (unsigned long) &data;
        spi_transfer.len = 2; // 16-bit transfer
        spi_transfer.delay_usecs = 0;
        spi_transfer.speed_hz = SPI_MAX_SPEED_HZ;
        spi_transfer.bits_per_word = 16;

        // Perform SPI transfer
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed SPI transfer");
            goto error_close_spi;
        }

        // Convert data to physical units
        gyro_x = (double)data * GYRO_SCALE;
        gyro_y = (double)data * GYRO_SCALE;
        gyro_z = (double)data * GYRO_SCALE;
        accel_x = (double)data * ACC_SCALE;
        accel_y = (double)data * ACC_SCALE;
        accel_z = (double)data * ACC_SCALE;

        // Log values
        printf("Gyro X: %.2f, Gyro Y: %.2f, Gyro Z: %.2f, Accel X: %.2f, Accel Y: %.2f, Accel Z: %.2f\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

