#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_CE0 8
#define GYRO_SCALE 0.05 // deg/sec per LSB
#define ACC_SCALE 0.00025 // g per LSB
#define READ_INTERVAL 100 // ms

static struct gpiod_line *ce0_line;
static int spi_fd;

void handle_sigint(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (ce0_line) {
        gpiod_line_free(ce0_line);
    }
    exit(0);
}

int main() {
    int ret;
    uint16_t data[6];
    uint8_t reg_addr = 0x00; // Example register address, replace with actual register addresses

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up CE0 line
    if ((ret = gpiod_line_request(GPIO_CE0, "CE0", GPIOD_LINE_DIRECTION_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", gpiod_line_strerror(ret));
        return 1;
    }
    ce0_line = gpiod_line_get(ret);

    // Open SPI channel
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI mode or speed\n");
        return 1;
    }

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        // Read gyroscope and accelerometer data
        for (int i = 0; i < 6; i++) {
            reg_addr |= (1 << 15); // Set bit 15 for read command
            if (write(spi_fd, &reg_addr, 2) != 2) {
                fprintf(stderr, "Failed to write register address\n");
                return 1;
            }
            usleep(40); // Stall time
            if (read(spi_fd, &data[i], 2) != 2) {
                fprintf(stderr, "Failed to read data\n");
                return 1;
            }
            reg_addr &= ~(1 << 15); // Clear bit 15 for dummy value
            if (write(spi_fd, &reg_addr, 2) != 2) {
                fprintf(stderr, "Failed to write dummy value\n");
                return 1;
            }
        }

        // Scale and print data
        printf("Gyro x: %f, Gyro y: %f, Gyro z: %f, Accel x: %f, Accel y: %f, Accel z: %f\n",
               (float)data[0] * GYRO_SCALE,
