    }
    exit(0);
}

int read_imu_data(int *accel_x, int *accel_y, int *accel_z, int *gyro_x, int *gyro_y, int *gyro_z) {
    int retries = 0;
    int result;

    do {
        result = read(i2c_fd, accel_x, 6);
        if (result == -1) {
            if (retries < MAX_RETRIES) {
                retries++;
                usleep(50000); // Sleep for 50 ms
            } else {
                return -1;
            }
        }
    } while (result == -1);

    if (result != 6) {
        return -1;
    }

    result = read(i2c_fd, gyro_x, 6);
    if (result == -1) {
        return -1;
    }

    if (result != 6) {
        return -1;
    }

    return 0;
}

int main() {
    int accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    int who_am_i;

    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, IMU_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(i2c_fd);
        return 1;
    }

    if (read(i2c_fd, &who_am_i, 1) != 1 || who_am_i != 0x68) {
        fprintf(stderr, "Sensor not found or incorrect address\n");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (read_imu_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("Accelerometer: %d %d %d\n", accel_x, accel_y, accel_z);
            printf("Gyroscope: %d %d %d\n", gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read IMU data\n");
        }

        usleep(50000); // Sleep for 50 ms
    }

    close(i2c_fd);
    return 0;
}

