#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define I2C_ADDR 0x53
#define I2C_DEV "/dev/i2c-1"
#define LED_GPIO 17
#define SCALE_FACTOR 256
#define THRESHOLD 2.5
#define LOG_FILE "impact_log.txt"

int i2c_fd;
int led_fd;
FILE *log_file;

void handle_signal(int signum) {
    if (log_file) fclose(log_file);
    if (led_fd != -1) close(led_fd);
    if (i2c_fd != -1) close(i2c_fd);
    exit(signum);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_i2c_device() {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access/talk to slave");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int open_led_gpio() {
    char path[32];
    sprintf(path, "/sys/class/gpio/gpio%d/value", LED_GPIO);
    led_fd = open(path, O_WRONLY);
    if (led_fd < 0) {
        perror("Failed to open LED GPIO");
        return -1;
    }
    return 0;
}

int open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

void turn_on_led() {
    if (write(led_fd, "1", 1) != 1) {
        perror("Failed to turn on LED");
    }
}

void turn_off_led() {
    if (write(led_fd, "0", 1) != 1) {
        perror("Failed to turn off LED");
    }
}

int read_i2c_register(uint8_t reg) {
    uint8_t data;
    if (read(i2c_fd, &data, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return data;
}

int verify_device_id() {
    uint8_t device_id = read_i2c_register(0x00);
    if (device_id != 0xE5) {
        fprintf(stderr, "Invalid device ID: expected 0xE5, got 0x%02X\n", device_id);
        return -1;
    }
    return 0;
}

int read_acceleration_data() {
    uint8_t data[6];
    if (read(i2c_fd, data, 6) != 6) {
        perror("Failed to read acceleration data");
        return -1;
    }
    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];
    double magnitude = sqrt(x * x + y * y + z * z) / SCALE_FACTOR;
    if (magnitude > THRESHOLD) {
        turn_on_led();
        usleep(500000); // 500 ms
        turn_off_led();
        fprintf(log_file, "%s %.3f %d %d %d\n", ctime(&time(NULL)), magnitude, x, y, z);
    }
    return 0;
}

int main() {
    setup_signal_handlers();

    if (open_i2c_device() < 0) {
        return EXIT_FAILURE;
    }

    if (verify_device_id() < 0) {
        return EXIT_FAILURE;
    }

    if (open_led_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (open_log_file() < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_acceleration_data() < 0) {
            return EXIT_FAILURE;
        }
        usleep(10000); // 10 ms
    }

    return EXIT_SUCCESS;
}

