#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define I2C_DATA_LEN 12
#define I2C_DATA_ACC 6
#define I2C_DATA_GYRO 6
#define I2C_FREQ 100000 // 100 kHz
#define I2C_TIMEOUT 1000 // 1 second
#define LOG_FILE "imu_log.csv"

static int i2c_fd;
static FILE *log_file;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        i2c_close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    struct timespec ts;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg msg[2];
    uint8_t data[I2C_DATA_LEN];
    char timestamp[32];

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS, 0);
    if (i2c_fd < 0) {
        perror("i2c_open");
        return 1;
    }

    // Set I2C frequency
    if (i2c_set_freq(i2c_fd, I2C_FREQ) < 0) {
        perror("i2c_set_freq");
        i2c_close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        i2c_close(i2c_fd);
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Configure I2C messages
    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = I2C_DATA_LEN;
    msg[0].buf = data;

    msg[1].addr = I2C_ADDR;
    msg[1].flags = I2C_M_RD;
    msg[1].len = I2C_DATA_LEN;
    msg[1].buf = data;

    i2c_data.msgs = msg;
    i2c_data.nmsgs = 2;

    // Main loop
    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        if (i2c_transfer(i2c_fd, &i2c_data) < 0) {
            perror("i2c_transfer");
            continue;
        }

        fprintf(log_file, "%s, ", timestamp);
        for (int i = 0; i < I2C_DATA_ACC; i++) {
            fprintf(log_file, "%d, ", (int)data[i]);
        }
        for (int i = I2C_DATA_ACC; i < I2C_DATA_LEN; i++) {
            fprintf(log_file, "%d, ", (int)data[i]);
        }
        fprintf(log_file, "\n");

        usleep(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    i2c_close(i2c_fd);

    return 0;
}

