#include <signal.h>
#include <time.h>

#include <linux/i2c-dev.h>

#define I2C_DEV "/dev/i2c-1"
#define TMAG5273_ADDR 0x3C
#define TMAG5273_REG_X 0x00
#define TMAG5273_REG_Y 0x01
#define TMAG5273_REG_Z 0x02

#define CSV_FILE "magnetic_field_log.csv"

static int i2c_fd = -1;
static FILE *csv_file = NULL;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }

    exit(signum);
}

