    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) == -1) {
        perror("ioctl");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (fseek(csv_file, 0, SEEK_END) == -1) {
        perror("fseek");
        fclose(csv_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    while (1) {
        char buffer[3];
        int x, y, z;

        if (read(i2c_fd, buffer, 1) != 1) {
            perror("read");
            continue;
        }

        if (read(i2c_fd, buffer, 1) != 1) {
            perror("read");
            continue;
        }

        if (read(i2c_fd, buffer, 1) != 1) {
            perror("read");
            continue;
        }

        x = (buffer[0] << 8) | buffer[1];
        y = (buffer[2] << 8) | buffer[3];
        z = (buffer[4] << 8) | buffer[5];

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(csv_file, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, x, y, z);

        fflush(csv_file);

        sleep(1);
    }

    fclose(csv_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
