#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_DEV_ID 0x53
#define ADXL345_STANDBY_MODE 0x00
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_INT_SOURCE 0x32
#define ADXL345_FIFO_CTL 0x38
#define ADXL345_FIFO_STATUS 0x39
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36

#define GPIO_PIN 17
#define EVENT_FILE "/sys/class/gpio/gpio17/value"

static int i2c_fd;
static int event_fd;
static struct gpiod_line *gpiod_line;
static FILE *csv_file;

void handle_interrupt(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received SIGINT or SIGTERM, cleaning up...\n");

        // Disable interrupts
        write_i2c(ADXL345_INT_SOURCE, 0x00);

        // Close I2C file descriptor
        close(i2c_fd);

        // Release GPIO line
        gpiod_line_release(gpiod_line);

        // Close sensor device
        fclose(csv_file);

        exit(0);
    }
}

int write_i2c(uint8_t reg, uint8_t value) {
    int ret;

    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("Error writing register address");
        return -1;
    }

    ret = write(i2c_fd, &value, 1);
    if (ret != 1) {
        perror("Error writing register value");
        return -1;
    }

    return 0;
}

int read_i2c(uint8_t reg, uint8_t *value) {
    int ret;

    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("Error writing register address");
        return -1;
    }

    ret = read(i2c_fd, value, 1);
    if (ret != 1) {
        perror("Error reading register value");
        return -1;
    }

    return 0;
}

int main() {
    uint8_t device_id;
    uint8_t data[6];
    struct timespec ts;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return -1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    // Set ADXL345 to standby mode
    write_i2c(ADXL345_DATA_FORMAT, ADXL345_STANDBY_MODE);

    // Verify device ID
    if (read_i2c(ADXL345_DEV_ID, &device_id) < 0 || device_id != ADXL345_DEV_ID) {
        printf("ADXL345 not found or device ID mismatch\n");
        return -1;
    }

    // Initialize GPIO line
    gpiod_line = gpiod_line_request(GPIO_PIN, "ADXL345_INT1", GPIOD_LINE_DIRECTION_IN);
    if (!gpiod_line) {
        perror("Failed to request GPIO line");
        return -1;
    }

    // Open event file
    event_fd = open(EVENT_FILE, O_RDONLY);
    if (event_fd < 0) {
        perror("Failed to open event file");
        return -1;
    }

    // Create CSV log file
    csv_file = fopen("freefall_log.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV log file");
        return -1;
    }

    // Write header row
    fprintf(csv_file, "Timestamp,X,Y,Z\n");

    // Set up signal handlers
    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    // Main loop
    while (1) {
        int bytes_read;

        // Poll for events
        bytes_read = read(event_fd, &data, 6);
        if (bytes_read < 0) {
            perror("Error reading from event file");
            break;
        }

        // Convert timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3f", localtime(&ts.tv_sec));

        // Write data to CSV file
        fprintf(csv_file, "%s,%02X,%02X,%02X\n", timestamp, data[0], data[1], data[2]);
        fflush(csv_file);
    }

    // Clean up
    handle_interrupt(SIGINT);

    return 0;
}

