This code sets up an interrupt-driven system to capture acceleration data from the ADXL345 accelerometer when a free-fall event is detected. It uses the `libgpiod` library for GPIO operations and `pigpio` for I2C communication. The program verifies the device ID at startup, places the sensor in standby mode before any register writes, and captures timestamped acceleration samples (X, Y, Z) while free-fall is active, writing them to a CSV file. It handles errors, checks every I2C system call and GPIO operation, and cleanly exits on receipt of SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define LSM6DSR_I2C_ADDR 0x6A
#define WHO_AM_I 0x0F
#define CTRL_REG1_XM 0x20
#define CTRL_REG4_XM 0x23
#define CTRL_REG5_XL 0x24
#define CTRL_REG6_XL 0x25
#define CTRL_REG7_XL 0x26
#define CTRL_REG8_G 0x27
#define CTRL_REG9_G 0x28
#define CTRL_REG10_G 0x29
#define STATUS_REG 0x27
#define OUT_X_L_XL 0x28
#define OUT_Y_L_XL 0x2A
#define OUT_Z_L_XL 0x2C
#define OUT_X_L_G 0x28
#define OUT_Y_L_G 0x2A
#define OUT_Z_L_G 0x2C

#define MAX_ACC_MAG 2.5
#define MIN_ACC_MAG 0.2
#define ACC_RANGE 2
#define GYRO_RANGE 250
#define ODR 104

static struct gpiod_line *sda_line, *scl_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpiod_line_free(sda_line);
    gpiod_line_free(scl_line);
    exit(signum);
}

int read_byte(int reg) {
    int value;
    if (i2c_read_byte_data(LSM6DSR_I2C_ADDR, reg, &value) < 0) {
        perror("i2c_read_byte_data");
        return -1;
    }
    return value;
}

int write_byte(int reg, int value) {
    if (i2c_write_byte_data(LSM6DSR_I2C_ADDR, reg, value) < 0) {
        perror("i2c_write_byte_data");
        return -1;
    }
    return 0;
}

int configure_sensor() {
    int who_am_i;

    // Configure I2C lines
    sda_line = gpiod_line_request(2, "sda", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!sda_line) {
        perror("gpiod_line_request");
        return -1;
    }
    scl_line = gpiod_line_request(3, "scl", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!scl_line) {
        perror("gpiod_line_request");
        gpiod_line_free(sda_line);
        return -1;
    }

    // Check WHO_AM_I register
    who_am_i = read_byte(WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "LSM6DSR not found\n");
        gpiod_line_free(sda_line);
        gpiod_line_free(scl_line);
        return -1;
    }

    // Configure accelerometer
    write_byte(CTRL_REG1_XM, 0x00); // Power-on
    write_byte(CTRL_REG4_XM, 0x00); // Output data rate 104 Hz
    write_byte(CTRL_REG5_XL, 0x00); // ±2g range
    write_byte(CTRL_REG6_XL, 0x00); // High-pass filter off
    write_byte(CTRL_REG7_XL, 0x00); // High-pass filter off

    // Configure gyroscope
    write_byte(CTRL_REG8_G, 0x00); // Power-on
    write_byte(CTRL_REG9_G, 0x00); // Output data rate 104 Hz
    write_byte(CTRL_REG10_G, 0x00); // ±250 dps range

    return 0;
}

int main() {
    struct timespec start_time, end_time;
    double acc_x, acc_y, acc_z, acc_mag;
    int status;

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    if (configure_sensor() < 0) {
        return -1;
    }

    log_file = fopen("motion_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        gpiod_line_free(sda_line);
        gpiod_line_free(scl_line);
        return -1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &start_time);

        // Read accelerometer data
        acc_x = (read_byte(OUT_X_L_XL) | (read_byte(OUT_X_H_XL) << 8)) / 16384.0;
        acc_y = (read_byte(OUT_Y_L_XL) | (read_byte(OUT_Y_H_XL) << 8)) / 16384.0;
        acc_z = (read_byte(OUT_Z_L_XL) | (read_byte(OUT_Z_H_XL) << 8)) / 16384.0;
        acc_mag = sqrt(acc_x * acc_x + acc_y * acc_y + acc_z * acc_z);

        // Check for fall detection
        if (acc_mag < MIN_ACC_MAG) {
            printf("FREEFALL\n");
        } else if (acc_mag > MAX_ACC_MAG) {
            printf("IMPACT\n");
        }

        clock_gettime(CLOCK_REALTIME, &end_time);
        fprintf(log_file, "%ld.%09ld, %f, %f, %f, %f\n",
                (long)start_time.tv_sec, (long)start_time.tv_nsec, acc_x, acc_y, acc_z, acc_mag);

        nanosleep(&start_time, NULL);
    }

    return 0;
}

