#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEV "/dev/spidev0.0"
#define WHO_AM_I_REG 0x00
#define GYRO_RATE_REG 0x14
#define SCALE_FACTOR 0.0305
#define INTERVAL 10 // 10 ms

static int spi_fd;
static FILE *log_file;

void handle_sigint(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int spi_transfer(uint8_t cmd, uint8_t *data, uint8_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)data,
        .rx_buf = (unsigned long)data,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

int verify_who_am_i() {
    uint8_t data[2] = {WHO_AM_I_REG | 0x80, 0};
    if (spi_transfer(0, data, 2) < 0) {
        return -1;
    }
    if (data[1] != 0x66) {
        fprintf(stderr, "WHO_AM_I register verification failed\n");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &3) < 0 || // SPI mode 3 (CPOL=1, CPHA=1)
        ioctl(spi_fd, SPI_IOC_RD_MODE, &3) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &8) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &1000000) < 0 || // 1 MHz
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &1000000) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    fprintf(log_file, "Timestamp,Angular_Rate\n");

    if (verify_who_am_i() < 0) {
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    while (1) {
        uint8_t data[3] = {GYRO_RATE_REG | 0x80, 0, 0};
        if (spi_transfer(0, data, 2) < 0) {
            break;
        }

        uint16_t raw_value = (data[1] << 8) | data[2];
        double angular_rate = raw_value * SCALE_FACTOR;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%f\n", timestamp, angular_rate);

        usleep(INTERVAL * 1000); // Sleep for 10 ms
    }

    fclose(log_file);
    close(spi_fd);

    return 0;
}

