        retry_count++;
        if (retry_count < MAX_RETRY) {
            sleep(1);
        }
    }

    if (retry_count == MAX_RETRY) {
        fprintf(stderr, "Failed to verify WHO_AM_I register after %d retries.\n", MAX_RETRY);
        i2c_client_free(client);
        gpiod_close(fd);
        return 1;
