#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"

volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for flame sensor.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor for flame sensor.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!exit_flag) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value.\n");
            fprintf(log_file, "YYYY-MM-DD HH:MM:SS – Error reading sensor.\n");
            fflush(log_file);
            continue;
        }

        char timestamp[20];
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (sensor_value == 0) {
            printf("FLAME DETECTED!\n");
            fprintf(log_file, "%s – Flame detected: YES\n", timestamp);
        } else {
            fprintf(log_file, "%s – Flame detected: NO\n", timestamp);
        }

        fflush(log_file);

        usleep(500000); // Sleep for 500 ms
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

