#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_17 17
#define GPIO_27 27
#define LOG_FILE "conveyor_log.txt"
#define INTERVAL 50 // milliseconds

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (line1) {
        gpiod_line_free(line1);
    }
    if (line2) {
        gpiod_line_free(line2);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct gpiod_line_request_config config;
    struct gpiod_line_request *request;
    struct gpiod_line_consumer *consumer;
    struct gpiod_line_consumer_config consumer_config;
    struct gpiod_line_consumer_request *consumer_request;
    struct gpiod_line_consumer_value *value;
    struct timespec ts;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO17
    memset(&config, 0, sizeof(config));
    config.consumer = "HallSensor1";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_NOPULL;
    config.bias = GPIOD_LINE_BIAS_PULL_UP;
    request = gpiod_line_request_open(chip, GPIO_17, &config);
    if (!request) {
        perror("Failed to request GPIO17");
        gpiod_chip_put(chip);
        return 1;
    }
    line1 = gpiod_line_get(request);
    if (!line1) {
        perror("Failed to get GPIO17 line");
        gpiod_line_request_put(request);
        gpiod_chip_put(chip);
        return 1;
    }

    // Request GPIO27
    memset(&config, 0, sizeof(config));
    config.consumer = "HallSensor2";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_NOPULL;
    config.bias = GPIOD_LINE_BIAS_PULL_UP;
    request = gpiod_line_request_open(chip, GPIO_27, &config);
    if (!request) {
        perror("Failed to request GPIO27");
        gpiod_line_request_put(request);
        gpiod_line_free(line1);
        gpiod_chip_put(chip);
        return 1;
    }
    line2 = gpiod_line_get(request);
    if (!line2) {
        perror("Failed to get GPIO27 line");
        gpiod_line_request_put(request);
        gpiod_line_free(line1);
        gpiod_chip_put(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_free(line2);
        gpiod_line_free(line1);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        value = gpiod_line_get_value(line1);
        if (!value) {
            perror("Failed to get value for GPIO17");
            break;
        }
        fprintf(log_file, "%ld.%03ld: GPIO17 = %d\n", ts.tv_sec, ts.tv_nsec / 1000000, value->value);
        gpiod_line_consumer_value_put(value);

        value = gpiod_line_get_value(line2);
        if (!value) {
            perror("Failed to get value for GPIO27");
            break;
        }
        fprintf(log_file, "%ld.%03ld: GPIO27 = %d\n", ts.tv_sec, ts.tv_nsec / 1000000, value->value);
        gpiod_line_consumer_value_put(value);

        if (value->value == 1 && gpiod_line_get_value(line2)->value == 1) {
            printf("Conveyor halted.\n");
        }

        usleep(INTERVAL * 1000); // Sleep for 50ms
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_free(line2);
    gpiod_line_free(line1);
    gpiod_chip_put(chip);

    return 0;
}

