#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define MMA8452Q_ADDR 0x1C
#define MMA8452Q_WHO_AM_I 0x0D
#define MMA8452Q_CTRL_REG1 0x2A
#define MMA8452Q_DATA_X_MSB 0x01
#define MMA8452Q_DATA_X_LSB 0x02
#define MMA8452Q_DATA_Y_MSB 0x03
#define MMA8452Q_DATA_Y_LSB 0x04
#define MMA8452Q_DATA_Z_MSB 0x05
#define MMA8452Q_DATA_Z_LSB 0x06

#define DATA_RATE_100HZ 0x00

static int i2c_fd;
static FILE *log_file;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    char i2c_device[16];
    sprintf(i2c_device, "/dev/i2c-%d", 1);

    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        close(i2c_fd);
        return 1;
    }

    if (who_am_i != 0x1A) {
        fprintf(stderr, "Invalid WHO_AM_I value: 0x%02X\n", who_am_i);
        close(i2c_fd);
        return 1;
    }

    uint8_t ctrl_reg1;
    if (read(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to read CTRL_REG1 register");
        close(i2c_fd);
        return 1;
    }

    ctrl_reg1 &= ~0x01; // Set to standby mode
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to write to CTRL_REG1 register");
        close(i2c_fd);
        return 1;
    }

    ctrl_reg1 = DATA_RATE_100HZ; // Set data rate to 100Hz
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to write to CTRL_REG1 register");
        close(i2c_fd);
        return 1;
    }

    ctrl_reg1 |= 0x01; // Enable active mode
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to write to CTRL_REG1 register");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("fall_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        uint8_t data[6];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read data registers");
            continue;
        }

        int16_t x = ((data[0] << 8) | data[1]) >> 4;
        int16_t y = ((data[2] << 8) | data[3]) >> 4;
        int16_t z = ((data[4] << 8) | data[5]) >> 4;

        double tilt = atan2(sqrt(x * x + y * y), z) * 180.0 / M_PI;

        if (tilt > 45.0) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %d %d %d\n",
                    now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                    now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, x, y, z);
            fflush(log_file);
        }

        usleep(10000); // 10ms loop interval
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

