#define LIS3MDL_ADDRESS 0x18
#define LIS3MDL_REG_WHO_AM_I 0x0F
#define LIS3MDL_REG_CTRL_REG1 0x20
#define LIS3MDL_REG_OUT_X_L 0x28
#define LIS3MDL_REG_OUT_Y_L 0x2A
#define LIS3MDL_REG_OUT_Z_L 0x2C

#define MAGNETIC_LOG_FILE "magnetic_log.txt"
#define MAGNETIC_FIELD_THRESHOLD 800.0

int i2c_fd;
int log_fd;

void handle_signal(int signum) {
    if (log_fd != -1) {
        fclose(log_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_i2c_register(uint8_t reg, uint8_t *data, size_t length) {
    int ret;
    do {
        ret = write(i2c_fd, &reg, 1);
        if (ret != 1) {
            perror("Error writing to I2C device");
            return -1;
        }
