        perror("Failed to read SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_transfer.bits_per_word) < 0) {
        perror("Failed to set bits per word");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &spi_transfer.bits_per_word) < 0) {
        perror("Failed to read bits per word");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_transfer.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &spi_transfer.speed_hz) < 0) {
        perror("Failed to read SPI speed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &spi_transfer.lsb_first) < 0) {
        perror("Failed to set LSB first");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_LSB_FIRST, &spi_transfer.lsb_first) < 0) {
        perror("Failed to read LSB first");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CS_LE, &spi_transfer.cs_change) < 0) {
        perror("Failed to set CS change");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_CS_LE, &spi_transfer.cs_change) < 0) {
        perror("Failed to read CS change");
        exit(EXIT_FAILURE);
    }
