void spi_reset() {
    unsigned char reset_value = 0x01;
    int ret;

    spi_transfer.tx_buf = (unsigned long)&reset_value;
    spi_transfer.rx_buf = (unsigned long)NULL;
    spi_transfer.len = 1;

    for (int i = 0; i < retry_count; i++) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
        if (ret < 1) {
            perror("SPI reset failed");
            continue;
        }
        break;
    }

    if (i == retry_count) {
        perror("SPI reset failed after retries");
        exit(EXIT_FAILURE);
    }

    usleep(1000);
}

