    while (1) {
        spi_transfer.tx_buf = (unsigned long)NULL;
        spi_transfer.rx_buf = (unsigned long)&power_ctrl_value;
        spi_transfer.len = 1;

        for (int i = 0; i < retry_count; i++) {
            ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
            if (ret < 1) {
                perror("SPI status read failed");
                continue;
            }
            break;
        }

        if (i == retry_count) {
            perror("SPI status read failed after retries");
            exit(EXIT_FAILURE);
        }

        if (power_ctrl_value & STABLE_BIT) {
            break;
        }

        usleep(1000);
    }

    power_ctrl_value |= RUN_BIT;

    spi_transfer.tx_buf = (unsigned long)&power_ctrl_value;
    spi_transfer.rx_buf = (unsigned long)NULL;
    spi_transfer.len = 1;

    for (int i = 0; i < retry_count; i++) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
        if (ret < 1) {
            perror("SPI RUN bit set failed");
