    spi_transfer.len = 1;

    for (int i = 0; i < retry_count; i++) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
        if (ret < 1) {
            perror("SPI PARTID read failed");
            continue;
        }
        break;
    }

    if (i == retry_count) {
        perror("SPI PARTID read failed after retries");
        exit(EXIT_FAILURE);
    }

    if (partid_value != PARTID) {
        fprintf(stderr, "Invalid PARTID value: 0x%04X\n", partid_value);
        exit(EXIT_FAILURE);
    }
}

void spi_read_data() {
    unsigned char data[6];
    int ret;

    spi_transfer.tx_buf = (unsigned long)NULL;
    spi_transfer.rx_buf = (unsigned long)data;
    spi_transfer.len = 6;

    for (int i = 0; i < retry_count; i++) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
        if (ret < 1) {
            perror("SPI data read failed");
            continue;
        }
        break;
    }

    if (i == retry_count) {
        perror("SPI data read failed after retries");
        exit(EXIT_FAILURE);
    }

    int x = (data[0] << 8) | data[1];
    int y = (data[2] << 8) | data[3];
    int z = (data[4] << 8) | data[5];

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%02d:%02d:%02d - X: %d, Y: %d, Z: %d\n",
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
            x, y, z);

    fclose(log_file);
}

void graceful_shutdown(int signum) {
    close(spi_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, graceful_shutdown);
    signal(SIGTERM, graceful_shutdown);

    spi_init();
    spi_reset();
    spi_power_control();
    spi_verify_sensor();

    while (1) {
        spi_read_data();
        usleep(100000);
    }

    return 0;
}

