int main() {
    struct timespec delay = {0, 10000000}; // 10ms delay
    struct timespec start, end;
    struct tm *tm_info;
    char timestamp[32];
    int16_t gyro_data[3], accel_data[3];
    uint8_t buffer[3];
    int ret;

    if (gpiod_line_request(SPI_CE0_GPIO, "SPI_CE0", GPIOD_LINE_DIRECTION_OUTPUT, 0) < 0) {
        perror("gpiod_line_request");
        return 1;
    }
    spi_ce0 = gpiod_line_get(SPI_CE0_GPIO);

    if (pigpio_start() < 0) {
        perror("pigpio_start");
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_RD_MODE");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("SPI_IOC_RD_BITS_PER_WORD");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_RD_MAX_SPEED_HZ");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    signal(SIGINT, handle_sigint);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &start);

        buffer[0] = 0x80; // MSB set for address byte
        buffer[1] = 0x00; // Dummy byte

        ret = spi_write_read(spi_fd, buffer, 3, buffer);
        if (ret < 0) {
            perror("spi_write_read");
            continue;
        }

        gyro_data[0] = (int16_t)((buffer[2] << 8) | buffer[3]);
        gyro_data[1] = (int16_t)((buffer[4] << 8) | buffer[5]);
        gyro_data[2] = (int16_t)((buffer[6] << 8) | buffer[7]);

        buffer[0] = 0x80; // MSB set for address byte
        buffer[1] = 0x00; // Dummy byte

        ret = spi_write_read(spi_fd, buffer, 3, buffer);
        if (ret < 0) {
            perror("spi_write_read");
            continue;
        }

        accel_data[0] = (int16_t)((buffer[2] << 8) | buffer[3]);
        accel_data[1] = (int16_t)((buffer[4] << 8) | buffer[5]);
        accel_data[2] = (int16_t)((buffer[6] << 8) | buffer[7]);

        clock_gettime(CLOCK_REALTIME, &end);

        double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
        if (elapsed_time < 0.01) {
            nanosleep(&delay, NULL);
        }

        tm_info = localtime(&start.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%f,%f,%f,%f,%f,%f\n", timestamp,
                gyro_data[0] * GYRO_SCALE, gyro_data[1] * GYRO_SCALE, gyro_data[2] * GYRO_SCALE,
                accel_data[0] * ACC_SCALE, accel_data[1] * ACC_SCALE, accel_data[2] * ACC_SCALE);
    }

    return 0;
}

