#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_17 17
#define GPIO_27 27
#define INTERVAL 100 // 100 ms

static struct gpiod_line *lines[2];

void cleanup(void) {
    for (int i = 0; i < 2; i++) {
        if (lines[i]) {
            gpiod_line_free(lines[i]);
        }
    }
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;
    struct gpiod_line_request *request;
    struct gpiod_line_bulk_read_config bulk_read_config;
    struct gpiod_line_bulk_read_result *result;
    unsigned int values[2];
    int ret;

    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Initialize libgpiod
    if ((ret = gpiod_chip_open(NULL, &chip)) < 0) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Configure GPIO lines
    memset(&config, 0, sizeof(config));
    config.consumer = "obstacle_avoidance";
    config.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    config.flags = GPIOD_LINE_REQUEST_ACTIVE_LOW;

    for (int i = 0; i < 2; i++) {
        switch (i) {
            case 0:
                config.line = GPIO_17;
                break;
            case 1:
                config.line = GPIO_27;
                break;
        }

        if ((ret = gpiod_line_request_alloc(chip, &config, &request)) < 0) {
            perror("gpiod_line_request_alloc");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if ((ret = gpiod_line_request_apply(request)) < 0) {
            perror("gpiod_line_request_apply");
            gpiod_line_request_free(request);
            cleanup();
            exit(EXIT_FAILURE);
        }

        lines[i] = gpiod_line_request_get_line(request);
    }

    // Configure bulk read
    memset(&bulk_read_config, 0, sizeof(bulk_read_config));
    bulk_read_config.lines = lines;
    bulk_read_config.count = 2;

    while (1) {
        if ((ret = gpiod_line_bulk_read(lines, 2, &result)) < 0) {
            perror("gpiod_line_bulk_read");
            cleanup();
            exit(EXIT_FAILURE);
        }

        memcpy(values, result->values, sizeof(values));
        gpiod_line_bulk_read_result_free(result);

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);

        printf("Timestamp: %02d:%02d:%02d Sensor 1: %d Sensor 2: %d\n",
               timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
               values[0], values[1]);

        usleep(INTERVAL * 1000); // Sleep for 100 ms
    }

    cleanup();
    return 0;
}

