#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_CS_GPIO 8 // BCM GPIO8
#define SCALE_FACTOR 0.02 // 0.02 deg/sec per LSB
#define LOG_INTERVAL 100 // 100 ms

static volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

int main() {
    int spi_fd;
    struct spi_ioc_transfer spi_transfer[2];
    uint8_t spi_data[4];
    double x_rate, y_rate, z_rate;

    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI mode or speed");
        close(spi_fd);
        return 1;
    }

    // Configure SPI transfers
    memset(spi_transfer, 0, sizeof(spi_transfer));
    spi_transfer[0].tx_buf = (unsigned long)spi_data;
    spi_transfer[0].len = 1;
    spi_transfer[0].delay_usecs = 0;
