#define FXOS8700_ADDR 0x1E
#define FXOS8700_ID_REG 0x0D
#define FXOS8700_ID_VALUE 0x3A

#define I2C_BUS 1
#define I2C_DEV FXOS8700_ADDR

#define ACCEL_DATA_REG 0x32
#define MAG_DATA_REG 0x3C

#define ACCEL_DATA_LEN 6
#define MAG_DATA_LEN 6

#define ACCEL_DATA_SIZE 12
#define MAG_DATA_SIZE 12

#define ACCEL_DATA_OFFSET 0
#define MAG_DATA_OFFSET 6

#define ACCEL_X_OFFSET 0
#define ACCEL_Y_OFFSET 2
#define ACCEL_Z_OFFSET 4

#define MAG_X_OFFSET 0
#define MAG_Y_OFFSET 2
#define MAG_Z_OFFSET 4

#define ACCEL_DATA_MASK 0x0FFF
#define MAG_DATA_MASK 0x0FFF

int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_i2c_reg(uint8_t reg, uint8_t *data, size_t len) {
    int ret;
    do {
        ret = i2c_read_device(i2c_fd, I2C_DEV, reg, data, len);
    } while (ret < 0 && errno == EINTR);
    return ret;
}

int write_i2c_reg(uint8_t reg, const uint8_t *data, size_t len) {
    int ret;
    do {
        ret = i2c_write_device(i2c_fd, I2C_DEV, reg, data, len);
    } while (ret < 0 && errno == EINTR);
    return ret;
}

int main() {
    uint8_t id_reg_data[1];
    uint8_t combined_data[ACCEL_DATA_SIZE + MAG_DATA_SIZE];
    uint16_t accel_x, accel_y, accel_z;
    uint16_t mag_x, mag_y, mag_z;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = i2c_open(I2C_BUS, 0);
    if (i2c_fd < 0) {
        perror("i2c_open");
        return EXIT_FAILURE;
    }

    // Check if device is present
    if (read_i2c_reg(FXOS8700_ID_REG, id_reg_data, 1) < 0) {
        perror("i2c_read_device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (id_reg_data[0] != FXOS8700_ID_VALUE) {
        fprintf(stderr, "FXOS8700 not found.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize sensor (example: enable accelerometer and magnetometer)
    uint8_t enable_reg_data[1] = {0x07}; // Enable accelerometer and magnetometer
    if (write_i2c_reg(0x2A, enable_reg_data, 1) < 0) {
        perror("i2c_write_device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read combined data
        if (read_i2c_reg(ACCEL_DATA_REG, combined_data, ACCEL_DATA_SIZE + MAG_DATA_SIZE) < 0) {
            perror("i2c_read_device");
            continue;
        }

        // Extract accelerometer data
        accel_x = ((combined_data[ACCEL_DATA_OFFSET + ACCEL_X_OFFSET] << 8) | combined_data[ACCEL_DATA_OFFSET + ACCEL_X_OFFSET + 1]) & ACCEL_DATA_MASK;
        accel_y = ((combined_data[ACCEL_DATA_OFFSET + ACCEL_Y_OFFSET] << 8) | combined_data[ACCEL_DATA_OFFSET + ACCEL_Y_OFFSET + 1]) & ACCEL_DATA_MASK;
        accel_z = ((combined_data[ACCEL_DATA_OFFSET + ACCEL_Z_OFFSET] << 8) | combined_data[ACCEL_DATA_OFFSET + ACCEL_Z_OFFSET + 1]) & ACCEL_DATA_MASK;

        // Extract magnetometer data
        mag_x = ((combined_data[MAG_DATA_OFFSET + MAG_X_OFFSET] << 8) | combined_data[MAG_DATA_OFFSET + MAG_X_OFFSET + 1]) & MAG_DATA_MASK;
        mag_y = ((combined_data[MAG_DATA_OFFSET + MAG_Y_OFFSET] << 8) | combined_data[MAG_DATA_OFFSET + MAG_Y_OFFSET + 1]) & MAG_DATA_MASK;
        mag_z = ((combined_data[MAG_DATA_OFFSET + MAG_Z_OFFSET] << 8) | combined_data[MAG_DATA_OFFSET + MAG_Z_OFFSET + 1]) & MAG_DATA_MASK;

        // Print data
        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        printf("Mag: X=%d, Y=%d, Z=%d\n", mag_x, mag_y, mag_z);

        usleep(100000); // 100 ms delay
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

