#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAY0 1
#define ADXL345_REG_DATAZ0 2
#define TILT_THRESHOLD 30.0
#define SAMPLING_INTERVAL 100 // in milliseconds

int i2c_fd;

int open_i2c_device() {
    char filename[100];
    sprintf(filename, "/dev/i2c-%d", 1); // Assuming I2C bus 1
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

void close_i2c_device() {
    close(i2c_fd);
}

int read_accelerometer_data(int *x, int *y, int *z) {
    uint8_t data[6];
    if (read(i2c_fd, data, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }
    *x = (data[0] | (data[1] << 8)) >> 4;
    *y = (data[2] | (data[3] << 8)) >> 4;
    *z = (data[4] | (data[5] << 8)) >> 4;
    return 0;
}

double calculate_tilt_angle(int x, int y, int z) {
    double tilt_angle = atan2(sqrt(x * x + y * y), z) * 180.0 / M_PI;
    return tilt_angle;
}

void log_tilt_event(double tilt_angle) {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *file = fopen("/var/log/tilt_events.log", "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s: Tilt angle exceeded %f degrees\n", buffer, tilt_angle);
    fclose(file);
}

int main() {
    int x, y, z;
    double tilt_angle;

    if (open_i2c_device() < 0) {
        return 1;
    }

    signal(SIGINT, [](int signum) {
        close_i2c_device();
        exit(0);
