#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define WINDOW_TIME 5000
#define SAMPLING_INTERVAL 1
#define ALERT_THRESHOLD 100

static int threshold;
static struct gpiod_line *line;

void handle_signal(int signum) {
    if (line) {
        gpiod_line_request_release(line);
    }
    exit(signum == SIGINT ? EXIT_SUCCESS : EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Invalid threshold. Please provide a positive integer.\n");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip;
    struct gpiod_line_request *req;

    chip = gpiod_chip_open_by_name("gpio");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return EXIT_FAILURE;
    }

    req = gpiod_line_request_open(chip, GPIO_PIN, "sensor_monitor", 0, GPIOD_LINE_DIRECTION_IN);
    if (!req) {
        fprintf(stderr, "Failed to request GPIO line.\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line = gpiod_line_request_get_line(req);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line.\n");
        gpiod_line_request_release(req);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int high_count = 0;
        struct timespec start, end;
        clock_gettime(CLOCK_REALTIME, &start);

        while (1) {
            int value = gpiod_line_get_value(line);
            if (value < 0) {
                fprintf(stderr, "Failed to read GPIO value.\n");
                gpiod_line_request_release(req);
                gpiod_chip_close(chip);
                return EXIT_FAILURE;
            }
            if (value == 1) {
                high_count++;
            }
            usleep(SAMPLING_INTERVAL * 1000);

            clock_gettime(CLOCK_REALTIME, &end);
            if (end.tv_sec - start.tv_sec >= WINDOW_TIME / 1000) {
                break;
            }
        }

        if (high_count > threshold) {
            printf("ALERT\n");
        } else {
            printf("Status: %d high readings\n", high_count);
        }

        sleep(1);
    }

    gpiod_line_request_release(req);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

