#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_A 17
#define GPIO_B 27
#define SECURITY_CODE_LENGTH 6
#define SECURITY_CODE_MIN 100000
#define SECURITY_CODE_MAX 999999

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
}

void generate_security_code(char *code) {
    srand(time(NULL));
    sprintf(code, "%06d", (rand() % (SECURITY_CODE_MAX - SECURITY_CODE_MIN + 1)) + SECURITY_CODE_MIN);
}

void log_access(const char *timestamp, const char *code) {
    FILE *log_file = fopen("access_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%s\n", timestamp, code);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_a, *line_b;
    char security_code[SECURITY_CODE_LENGTH + 1];
    char user_input[SECURITY_CODE_LENGTH + 1];
    char timestamp[20];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if ((line_a = gpiod_line_request_any(chip, "GPIO%d", GPIO_A, GPIOD_LINE_DIRECTION_OUT)) == NULL) {
        perror("Failed to request GPIO line A");
        goto error_exit;
    }

    if ((line_b = gpiod_line_request_any(chip, "GPIO%d", GPIO_B, GPIOD_LINE_DIRECTION_OUT)) == NULL) {
        perror("Failed to request GPIO line B");
        goto error_exit;
    }

    if (gpiod_line_set_value(line_a, 0) < 0) {
        perror("Failed to set GPIO A to LOW");
        goto error_exit;
    }

    if (gpiod_line_set_value(line_b, 0) < 0) {
        perror("Failed to set GPIO B to LOW");
        goto error_exit;
    }

    while (!exit_flag) {
        generate_security_code(security_code);
        printf("Generated security code: %s\n", security_code);

        printf("Enter security code: ");
        if (fgets(user_input, sizeof(user_input), stdin) == NULL) {
            perror("Failed to read user input");
            continue;
        }

        user_input[strcspn(user_input, "\n")] = '\0'; // Remove newline character

        if (strcmp(user_input, security_code) == 0) {
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            log_access(timestamp, security_code);
            printf("Access granted\n");
        } else {
            printf("Access denied\n");
        }

        sleep(5);

        if (gpiod_line_set_value(line_a, 0) < 0) {
            perror("Failed to set GPIO A to LOW");
            goto error_exit;
        }

        if (gpiod_line_set_value(line_b, 0) < 0) {
            perror("Failed to set GPIO B to LOW");
            goto error_exit;
        }
    }

    gpiod_line_free(line_b);
    gpiod_line_free(line_a);
    gpiod_chip_put(chip);

    return 0;

error_exit:
    gpiod_line_free(line_b);
    gpiod_line_free(line_a);
    gpiod_chip_put(chip);
    return 1;
}

