#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define BH1750_ADDR 0x23
#define BH1750_MEAS_CONT 0x00
#define BH1750_MEAS_CONT_HIGH_RES 0x01
#define BH1750_MEAS_CONT_LOW_RES 0x00
#define BH1750_MEAS_CONT_MED_RES 0x02
#define BH1750_MEAS_CONT_HIGH_RES_MED_RES 0x03

#define MAX_CONVERSION_TIME 180
#define LOG_INTERVAL 5000

static gpiod_chip *chip;
static gpiod_line *sda_line;
static gpiod_line *scl_line;
static FILE *log_file;

void cleanup(int signal) {
    if (log_file) {
        fclose(log_file);
    }
    if (scl_line) {
        gpiod_line_free(scl_line);
    }
    if (sda_line) {
        gpiod_line_free(sda_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(0);
}

int main() {
    struct timespec start_time;
    struct timespec end_time;
    int lux_value;
    int i2c_status;
    char timestamp[20];

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open("/dev/i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    sda_line = gpiod_line_request_by_name(chip, "sda", "I2C_SDA");
    if (!sda_line) {
        fprintf(stderr, "Failed to request SDA line\n");
        goto error_sda;
    }

    scl_line = gpiod_line_request_by_name(chip, "scl", "I2C_SCL");
    if (!scl_line) {
        fprintf(stderr, "Failed to request SCL line\n");
        goto error_scl;
    }

    log_file = fopen("light_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto error_log;
    }

    while (1) {
        gpiod_line_set_value(sda_line, 0);
        gpiod_line_set_value(scl_line, 0);

        i2c_status = gpiod_i2c_write_byte(chip, BH1750_ADDR, BH1750_MEAS_CONT_HIGH_RES);
        if (i2c_status < 0) {
            fprintf(stderr, "Failed to write to BH1750 sensor\n");
            goto error_i2c;
        }

        usleep(MAX_CONVERSION_TIME * 1000);

        i2c_status = gpiod_i2c_read_byte(chip, BH1750_ADDR);
        if (i2c_status < 0) {
            fprintf(stderr, "Failed to read from BH1750 sensor\n");
            goto error_i2c;
        }

        i2c_status = gpiod_i2c_read_byte(chip, BH1750_ADDR);
        if (i2c_status < 0) {
            fprintf(stderr, "Failed to read from BH1750 sensor\n");
            goto error_i2c;
        }

        i2c_status = gpiod_i2c_read_byte(chip, BH1750_ADDR);
        if (i2c_status < 0) {
            fprintf(stderr, "Failed to read from BH1750 sensor\n");
            goto error_i2c;
        }

        i2c_status = gpiod_i2c_read_byte(chip, BH1750_ADDR);
        if (i2c_status < 0) {
            fprintf(stderr, "Failed to read from BH1750 sensor\n");
            goto error_i2c;
        }

        lux_value = (i2c_status << 8) | i2c_status;

        time(&start_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start_time));
        fprintf(log_file, "Timestamp: %s, Lux: %d\n", timestamp, lux_value);
        fflush(log_file);

        usleep(LOG_INTERVAL * 1000);
    }

error_i2c:
    fclose(log_file);
error_log:
    gpiod_line_free(scl_line);
error_scl:
    gpiod_line_free(sda_line);
error_sda:
    gpiod_chip_put(chip);
    return 1;
}

