            fprintf(stderr, "Failed to read from BH1750 sensor\n");
            goto error_i2c;
        }

        i2c_status = gpiod_i2c_read_byte(chip, BH1750_ADDR);
        if (i2c_status < 0) {
            fprintf(stderr, "Failed to read from BH1750 sensor\n");
            goto error_i2c;
        }

        lux_value = (i2c_status << 8) | i2c_status;

        time(&start_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start_time));
        fprintf(log_file, "Timestamp: %s, Lux: %d\n", timestamp, lux_value);
        fflush(log_file);

        usleep(LOG_INTERVAL * 1000);
    }

