#define PWM_PIN 18
#define I2C_BUS 1
#define SAMPLE_INTERVAL 20 // in milliseconds
#define PLAYBACK_DURATION 5000 // in milliseconds

int sockfd;
struct sockaddr_in server_addr;
mpr121_t *mpr121;

void handle_signal(int signum) {
    if (mpr121) {
        mpr121_stop_pwm(mpr121, PWM_PIN);
        mpr121_close(mpr121);
    }
    close(sockfd);
    exit(signum);
}

int main() {
    int i2c_fd;
    int ret;
    char buffer[BUFFER_SIZE];
    char *secret_start = "MOTION_DETECTED:";
    char *secret_end = SECRET;
    int secret_len = strlen(SECRET);
    int client_len;
    struct sockaddr_in client_addr;
    int bytes_read;
    FILE *log_file;

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize MPR121
    mpr121 = mpr121_init(I2C_BUS);
    if (!mpr121) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = mpr121_get_i2c_fd(mpr121);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        mpr121_close(mpr121);
        return 1;
    }

    // Configure MPR121
    ret = mpr121_soft_reset(mpr121);
    if (ret < 0) {
        fprintf(stderr, "Failed to perform soft reset on MPR121\n");
        mpr121_close(mpr121);
        return 1;
    }

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Failed to create socket\n");
        mpr121_close(mpr121);
        return 1;
    }

