    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    server_addr.sin_addr.s_addr = INADDR_ANY;
    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket\n");
        close(sockfd);
        mpr121_close(mpr121);
        return 1;
    }

    // Listen for connections
    if (listen(sockfd, 5) < 0) {
        fprintf(stderr, "Failed to listen on socket\n");
        close(sockfd);
        mpr121_close(mpr121);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(sockfd);
        mpr121_close(mpr121);
        return 1;
    }

    // Accept connection
    client_len = sizeof(client_addr);
    int connfd = accept(sockfd, (struct sockaddr *)&client_addr, &client_len);
    if (connfd < 0) {
        fprintf(stderr, "Failed to accept connection\n");
        fclose(log_file);
        close(sockfd);
        mpr121_close(mpr121);
        return 1;
    }

    // Read message from client
    bytes_read = recv(connfd, buffer, BUFFER_SIZE, 0);
    if (bytes_read < 0) {
        fprintf(stderr, "Failed to read from socket\n");
        fclose(log_file);
        close(connfd);
        close(sockfd);
        mpr121_close(mpr121);
        return 1;
    }

    // Check for authentication
    if (strncmp(buffer, secret_start, strlen(secret_start)) != 0 ||
        strncmp(buffer + strlen(secret_start), secret_end, secret_len) != 0) {
        fprintf(stderr, "Invalid authentication message\n");
        fclose(log_file);
        close(connfd);
        close(sockfd);
        mpr121_close(mpr121);
        return 1;
    }

    // Start PWM playback
    mpr121_start_pwm(mpr121, PWM_PIN, 1000); // Start PWM at 1000 Hz

    // Log frequencies and sample touch values
    int start_time = time(NULL);
    while (time(NULL) - start_time < PLAYBACK_DURATION / 1000) {
        int touch_value = mpr121_get_touch_value(mpr121, 0); // Assuming electrode 0
        if (touch_value >= 0) {
            int frequency = touch_value * 100; // Example mapping
            fprintf(log_file, "%d\n", frequency);
        }
        usleep(SAMPLE_INTERVAL * 1000); // Sleep for 20 ms
    }

    // Stop PWM playback
    mpr121_stop_pwm(mpr121, PWM_PIN);

    // Clean up
    fclose(log_file);
    close(connfd);
    close(sockfd);
    mpr121_close(mpr121);

    return 0;
}

