#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define LSM303DLHC_ADDRESS 0x1E
#define LSM303DLHC_DATA_REG 0x03
#define LSM303DLHC_DATA_LEN 6
#define LED_GPIO 17
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE_MAX 100

int i2c_fd;
int pwm_handle;

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void handle_i2c_error(const char *msg) {
    fprintf(stderr, "%s: I2C error, skipping sample\n", msg);
}

void read_sensor_data(unsigned char *data) {
    ssize_t bytes_read = read(i2c_fd, data, LSM303DLHC_DATA_LEN);
    if (bytes_read != LSM303DLHC_DATA_LEN) {
        handle_i2c_error("Failed to read sensor data");
        return;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        handle_error("Failed to initialize pigpio");
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        handle_error("Failed to open I2C bus");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDRESS) < 0) {
        handle_error("Failed to set I2C slave address");
    }

    pwm_handle = pigpio_pwm_start(LED_GPIO, PWM_FREQUENCY, 0);
    if (pwm_handle < 0) {
        handle_error("Failed to start PWM on GPIO");
    }

    while (1) {
        unsigned char data[LSM303DLHC_DATA_LEN];
        read_sensor_data(data);

        int z_axis_magnitude = (data[4] << 8) | data[5];
        int duty_cycle = (z_axis_magnitude * PWM_DUTY_CYCLE_MAX) / 32768;
        if (duty_cycle > PWM_DUTY_CYCLE_MAX) {
            duty_cycle = PWM_DUTY_CYCLE_MAX;
        }

        pigpio_pwm_dutycycle(pwm_handle, duty_cycle);

        usleep(100000); // Sleep for 100 ms
    }

    pigpio_pwm_stop(pwm_handle);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

