#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libi2c.h>

#define I2C_ADDR 0x1E
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL 500 // in milliseconds

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int main() {
    int i2c_fd;
    int result;
    uint8_t buffer[BUFFER_SIZE * 3];
    int32_t raw_samples[BUFFER_SIZE][3];
    int32_t avg_offsets[3] = {0, 0, 0};
    int32_t corrected_samples[3];
    int sample_count = 0;

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus 1
    i2c_fd = i2c_open(1, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    while (!stop_flag) {
        // Read raw magnetic field data
        result = i2c_read_i2c_block_data(i2c_fd, 0x03, buffer, BUFFER_SIZE * 3);
        if (result < 0) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            continue;
        }

        // Convert raw data to 32-bit integers
        for (int i = 0; i < BUFFER_SIZE; i++) {
            raw_samples[i][0] = (int32_t)((buffer[i * 3 + 0] << 8) | buffer[i * 3 + 1]);
            raw_samples[i][1] = (int32_t)((buffer[i * 3 + 2] << 8) | buffer[i * 3 + 3]);
            raw_samples[i][2] = (int32_t)((buffer[i * 3 + 4] << 8) | buffer[i * 3 + 5]);
        }

        // Compute running average for hard-iron offsets
        for (int i = 0; i < 3; i++) {
            avg_offsets[i] = (avg_offsets[i] * (sample_count - 1) + raw_samples[sample_count % BUFFER_SIZE][i]) / sample_count;
        }

        // Apply offsets to new raw readings
        corrected_samples[0] = raw_samples[sample_count % BUFFER_SIZE][0] - avg_offsets[0];
        corrected_samples[1] = raw_samples[sample_count % BUFFER_SIZE][1] - avg_offsets[1];
        corrected_samples[2] = raw_samples[sample_count % BUFFER_SIZE][2] - avg_offsets[2];

        // Print corrected samples
        printf("X: %d, Y: %d, Z: %d\n", corrected_samples[0], corrected_samples[1], corrected_samples[2]);

        // Increment sample count
        sample_count++;

        // Sleep for 500 ms
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    i2c_close(i2c_fd);

    return 0;
}

