#include <stdint.h>

#define LSM303D_I2C_ADDR 0x1E
#define LSM303D_WHO_AM_I 0x0F
#define LSM303D_CTRL_REG1 0x20
#define LSM303D_OUT_X_L_A 0x28
#define LSM303D_OUT_Y_L_A 0x2A
#define LSM303D_OUT_Z_L_A 0x2C

#define BUFFER_SIZE 64
#define SAMPLE_INTERVAL 10 // ms
#define INT1_GPIO 23
#define INT1_PIN 16
#define INT1_THRESHOLD 2000 // mg
#define INT1_DURATION 0 // zero duration for immediate triggering

struct sample {
    uint16_t x;
    uint16_t y;
    uint16_t z;
};

struct sample buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

int i2c_read(int fd, uint8_t reg, uint8_t *data, int len) {
    int ret;
    if ((ret = write(fd, &reg, 1)) < 0) {
        perror("i2c_read: write");
        return ret;
    }
    if ((ret = read(fd, data, len)) < 0) {
        perror("i2c_read: read");
        return ret;
    }
    return ret;
}

int i2c_write(int fd, uint8_t reg, const uint8_t *data, int len) {
    int ret;
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if ((ret = write(fd, buf, len + 1)) < 0) {
        perror("i2c_write: write");
        return ret;
    }
    return ret;
}

void read_accelerometer(int fd) {
    uint8_t data[6];
    if (i2c_read(fd, LSM303D_OUT_X_L_A, data, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
