#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO17 17
#define GPIO27 27

static struct gpiod_line *lines[2];

void cleanup(int signum) {
    for (int i = 0; i < 2; i++) {
        if (lines[i]) {
            gpiod_line_request_release(lines[i]);
            free(lines[i]);
        }
    }
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;
    struct timespec delay = { .tv_sec = 0, .tv_nsec = 500000000 }; // 500ms delay

    // Initialize libgpiod
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Request GPIO17
    req = gpiod_line_request_alloc(chip, GPIO17, "Solenoid1", 0);
    if (!req) {
        perror("gpiod_line_request_alloc");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    req->consumer = "Solenoid1";
    req->flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req->value = 0; // Set to LOW initially

    if (gpiod_line_request(req, &lines[0]) < 0) {
        perror("gpiod_line_request");
        gpiod_line_request_free(req);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request GPIO27
    req = gpiod_line_request_alloc(chip, GPIO27, "Solenoid2", 0);
    if (!req) {
        perror("gpiod_line_request_alloc");
        gpiod_line_request_release(lines[0]);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    req->consumer = "Solenoid2";
    req->flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req->value = 0; // Set to LOW initially

    if (gpiod_line_request(req, &lines[1]) < 0) {
        perror("gpiod_line_request");
        gpiod_line_request_release(lines[0]);
        gpiod_line_request_free(req);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Install signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    int active_line = 0;
    while (1) {
        if (gpiod_line_set_value(lines[active_line], 1) < 0) {
            perror("gpiod_line_set_value");
            cleanup(EXIT_FAILURE);
        }
        nanosleep(&delay, NULL);
        if (gpiod_line_set_value(lines[active_line], 0) < 0) {
            perror("gpiod_line_set_value");
            cleanup(EXIT_FAILURE);
        }
        active_line = (active_line + 1) % 2;
    }

    // Cleanup on exit
    cleanup(EXIT_SUCCESS);

    return 0;
}

