#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define BUFFER_SIZE 10
#define TIMEOUT_MS 5000

char buffer[BUFFER_SIZE];
int buffer_index = 0;

void handle_signal(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
    }
    gpioWrite(17, 0);
    gpioWrite(27, 0);
    if (serialOpen("/dev/serial0", 9600, 0, 0) < 0) {
        fprintf(stderr, "Failed to close serial0\n");
    }
    if (serialOpen("/dev/serial1", 9600, 0, 0) < 0) {
        fprintf(stderr, "Failed to close serial1\n");
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    if (serialOpen("/dev/serial0", 9600, 0, 0) < 0) {
        fprintf(stderr, "Failed to open serial0\n");
        gpioTerminate();
        return 1;
    }

    if (serialOpen("/dev/serial1", 9600, 0, 0) < 0) {
        fprintf(stderr, "Failed to open serial1\n");
        serialClose(0);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        char code1[CODE_LENGTH + 1];
        char code2[CODE_LENGTH + 1];
        int read_count1 = 0, read_count2 = 0;

        for (int i = 0; i < BUFFER_SIZE; i++) {
            buffer[i] = '\0';
        }
        buffer_index = 0;

        while (read_count1 < CODE_LENGTH || read_count2 < CODE_LENGTH) {
            int result1 = serialRead(0, buffer + buffer_index, 1, TIMEOUT_MS);
            int result2 = serialRead(1, buffer + buffer_index, 1, TIMEOUT_MS);

            if (result1 < 0) {
                fprintf(stderr, "Read timeout on serial0\n");
                break;
            }
            if (result2 < 0) {
                fprintf(stderr, "Read timeout on serial1\n");
                break;
            }

            char c = buffer[buffer_index];
            if (c >= '0' && c <= '9') {
                if (read_count1 < CODE_LENGTH) {
                    code1[read_count1++] = c;
                }
                if (read_count2 < CODE_LENGTH) {
                    code2[read_count2++] = c;
                }
            } else {
                buffer_index = 0;
                read_count1 = 0;
                read_count2 = 0;
            }

            buffer_index++;
        }

        if (read_count1 == CODE_LENGTH && read_count2 == CODE_LENGTH) {
            code1[CODE_LENGTH] = '\0';
            code2[CODE_LENGTH] = '\0';

            if (memcmp(code1, EXPECTED_CODE, CODE_LENGTH) == 0 &&
                memcmp(code2, EXPECTED_CODE, CODE_LENGTH) == 0) {
                if (gpioWrite(17, 1) < 0) {
                    fprintf(stderr, "Failed to set GPIO17 HIGH\n");
                }
                if (gpioWrite(27, 1) < 0) {
                    fprintf(stderr, "Failed to set GPIO27 HIGH\n");
                }
                sleep(2);
                if (gpioWrite(17, 0) < 0) {
                    fprintf(stderr, "Failed to set GPIO17 LOW\n");
                }
                if (gpioWrite(27, 0) < 0) {
                    fprintf(stderr, "Failed to set GPIO27 LOW\n");
                }
            }
        }
    }

    return 0;
}

