#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define PIR_GPIO 4
#define RELAY_GPIO 17
#define POLL_INTERVAL 50 // in milliseconds
#define FAILSAFE_TIMEOUT 10000 // in milliseconds

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line, *relay_line;

void handle_signal(int signum) {
    if (pir_line) {
        gpiod_line_request_release(pir_line);
    }
    if (relay_line) {
        gpiod_line_request_release(relay_line);
    }
    gpiod_chip_put(chip);
    closelog();
    exit(signum == SIGINT ? 0 : 1);
}

void log_event(const char *event, int line) {
    syslog(LOG_INFO, "%s: GPIO%d", event, line);
}

void handle_motion(void) {
    struct timespec ts;
    ts.tv_sec = 1;
    ts.tv_nsec = 0;

    gpiod_line_set_value(relay_line, 1);
    log_event("Relay ON", RELAY_GPIO);

    nanosleep(&ts, NULL);

    gpiod_line_set_value(relay_line, 0);
    log_event("Relay OFF", RELAY_GPIO);
}

void check_failsafe(void) {
    struct timespec ts;
    ts.tv_sec = FAILSAFE_TIMEOUT / 1000;
    ts.tv_nsec = (FAILSAFE_TIMEOUT % 1000) * 1000000;

    nanosleep(&ts, NULL);

    if (gpiod_line_get_value(pir_line)) {
        gpiod_line_set_value(relay_line, 0);
        log_event("Relay OFF (Failsafe)", RELAY_GPIO);
        syslog(LOG_WARNING, "Potential malfunction detected. Relay deactivated.");
        syslog(LOG_INFO, "Shutdown initiated.");
    }
}

