#define GPIO_RELAY1 4
#define GPIO_RELAY2 17
#define GPIO_RELAY3 27
#define GPIO_RELAY4 22

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

void init_gpios(struct gpiod_chip *chip) {
    struct gpiod_line *lines[4];
    int i;

    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_line_request(chip, (i == 0) ? GPIO_RELAY1 : (i == 1) ? GPIO_RELAY2 : (i == 2) ? GPIO_RELAY3 : GPIO_RELAY4, "irrigation_system", GPIOD_LINE_DIRECTION_OUT);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "Failed to request GPIO line %d", (i == 0) ? GPIO_RELAY1 : (i == 1) ? GPIO_RELAY2 : (i == 2) ? GPIO_RELAY3 : GPIO_RELAY4);
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO line %d to HIGH", (i == 0) ? GPIO_RELAY1 : (i == 1) ? GPIO_RELAY2 : (i == 2) ? GPIO_RELAY3 : GPIO_RELAY4);
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpios(struct gpiod_chip *chip, struct gpiod_line *lines[]) {
    int i;

    for (i = 0; i < 4; i++) {
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO line %d to HIGH during cleanup", (i == 0) ? GPIO_RELAY1 : (i == 1) ? GPIO_RELAY2 : (i == 2) ? GPIO_RELAY3 : GPIO_RELAY4);
        }
        gpiod_line_free(lines[i]);
    }
    gpiod_chip_put(chip);
}

void log_state_change(int relay_num, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    syslog(LOG_INFO, "irrigation_system: Relay %d %s", relay_num, state ? "ON" : "OFF");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[4];
    int relay_index = 0;
    int state = 0;

    openlog("irrigation_system", LOG_PID, LOG_USER);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiomem");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    init_gpios(chip);

    while (!stop_flag) {
        log_state_change(relay_index + 1, state);
        gpiod_line_set_value(lines[relay_index], state);

        sleep(300); // 5 minutes

        state = !state;
        log_state_change(relay_index + 1, state);
        gpiod_line_set_value(lines[relay_index], state);

        sleep(60); // 1 minute pause

        relay_index = (relay_index + 1) % 4;
    }

    cleanup_gpios(chip, lines);
    closelog();

    return EXIT_SUCCESS;
}

