#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define BUFFER_SIZE 100
#define I2C_ADDR 0x68
#define I2C_DEV "/dev/i2c-1"
#define I2C_FREQ 100000 // 100 kHz
#define I2C_TIMEOUT 1000 // 1 second

typedef struct {
    int fd;
    int buffer[BUFFER_SIZE][3];
    int head;
    int tail;
} mpu6050_data;

void handle_signal(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    // Clean up resources here
    exit(0);
}

int init_i2c(mpu6050_data *data) {
    data->fd = open(I2C_DEV, O_RDWR);
    if (data->fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(data->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(data->fd);
        return -1;
    }

    return 0;
}

int read_acceleration(mpu6050_data *data) {
    int result = 0;
    int x, y, z;

    // Read X, Y, Z acceleration data
    if (read(data->fd, &x, 2) != 2 || read(data->fd, &y, 2) != 2 || read(data->fd, &z, 2) != 2) {
        perror("Failed to read acceleration data");
        return -1;
    }

    // Store data in circular buffer
    data->buffer[data->head][0] = x;
    data->buffer[data->head][1] = y;
    data->buffer[data->head][2] = z;

    data->head = (data->head + 1) % BUFFER_SIZE;

    return 0;
}

int main() {
    mpu6050_data data;
    struct sigaction sa;
    struct itimerval timer;

    // Initialize signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    if (init_i2c(&data) < 0) {
        return 1;
    }

    // Initialize circular buffer
    data.head = 0;
    data.tail = 0;

    // Set up timer to sample at 100 Hz
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = 10000; // 10 ms
    timer.it_interval = timer.it_value;
    setitimer(ITIMER_REAL, &timer, NULL);

    // Main loop
    while (1) {
        if (read_acceleration(&data) < 0) {
            break;
        }
    }

    // Clean up resources
    close(data.fd);

    return 0;
}

