#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO18 18
#define GPIO23 23
#define GPIO24 24
#define GPIO25 25

static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];

void handle_signal(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_request_release(lines[i]);
    }
    gpiod_chip_put(chip);
    exit(signum);
}

int main() {
    struct gpiod_chip_params params;
    struct gpiod_line_request_params line_request_params[4];
    struct timespec start_time[4];
    int i;

    // Initialize libgpiod
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    for (i = 0; i < 4; i++) {
        line_request_params[i].consumer = "Relay Toggler";
        line_request_params[i].request_type = GPIOD_LINE_REQUEST_OUTPUT;
        line_request_params[i].flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        line_request_params[i].line = i + GPIO18;

        if (gpiod_line_request_alloc(chip, &line_request_params[i], &lines[i]) < 0) {
            perror("Failed to request GPIO line");
            for (int j = 0; j < i; j++) {
                gpiod_line_request_release(lines[j]);
            }
            gpiod_chip_put(chip);
            return EXIT_FAILURE;
        }
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Start toggling relays
    while (1) {
        for (i = 0; i < 4; i++) {
            clock_gettime(CLOCK_MONOTONIC, &start_time[i]);
            while (1) {
                struct timespec now;
                clock_gettime(CLOCK_MONOTONIC, &now);
                if (now.tv_sec - start_time[i].tv_sec >= (i + 2)) {
                    break;
                }
                gpiod_line_set_value(lines[i], !gpiod_line_get_value(lines[i]));
            }
        }
    }

    // Cleanup on exit
    for (i = 0; i < 4; i++) {
        gpiod_line_request_release(lines[i]);
    }
    gpiod_chip_put(chip);

    return EXIT_SUCCESS;
}

