void handle_signal(int signum) {
    if (gpiod_line_request_release(relay_line) < 0) {
        perror("Failed to release relay line");
    }
    if (gpiod_line_request_release(sound_sensor_line) < 0) {
        perror("Failed to release sound sensor line");
    }
    if (gpiod_chip_free(chip) < 0) {
        perror("Failed to free GPIO chip");
    }
