}

int main() {
    FILE *log_file;
    struct timespec current_time;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request sound sensor line
    sound_sensor_line = gpiod_line_request_by_name(chip, "gpio%d", GPIO_SOUND_SENSOR, "Sound Sensor", 0);
    if (!sound_sensor_line) {
        perror("Failed to request sound sensor line");
        goto error_sound_sensor;
    }

    // Request relay line
    relay_line = gpiod_line_request_by_name(chip, "gpio%d", GPIO_RELAY, "Relay", 0);
    if (!relay_line) {
        perror("Failed to request relay line");
        goto error_relay;
