#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <math.h>

#define BUFFER_SIZE 100
#define GYRO_ADDR 0x68
#define CTRL_REG1 0x20
#define FIFO_EN 0x40
#define FIFO_CTRL_REG 0x24
#define FIFO_COUNT_H 0x72
#define FIFO_DATA 0x74
#define FIFO_READ_LEN 14

typedef struct {
    float x, y, z;
} GyroData;

GyroData buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_count = 0;

void read_gyro_data(int fd) {
    char data[FIFO_READ_LEN];
    int bytes_read = read(fd, data, FIFO_READ_LEN);
    if (bytes_read != FIFO_READ_LEN) {
        perror("Error reading from I2C device");
        return;
    }

    buffer[buffer_head].x = (data[0] << 8) | data[1];
    buffer[buffer_head].y = (data[2] << 8) | data[3];
    buffer[buffer_head].z = (data[4] << 8) | data[5];

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    buffer_count = (buffer_count + 1) % BUFFER_SIZE;

    float magnitude = sqrt(buffer[buffer_tail].x * buffer[buffer_tail].x +
                           buffer[buffer_tail].y * buffer[buffer_tail].y +
                           buffer[buffer_tail].z * buffer[buffer_tail].z);

    if (magnitude > 50.0) {
        printf("Angular velocity exceeds 50.0 degrees/second: %.2f\n", magnitude);
    }

    buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
}

void handle_sigint(int signum) {
    printf("\nGracefully shutting down...\n");
    close(fd);
    exit(0);
}

int main() {
    int fd;
    struct sigaction sa;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to select I2C device");
        close(fd);
        return 1;
    }

    char reg_data[2] = {0x00, 0x00};
    reg_data[0] = CTRL_REG1 | FIFO_EN;
    if (write(fd, reg_data, 2) != 2) {
        perror("Failed to write to I2C device");
        close(fd);
        return 1;
    }

    reg_data[0] = FIFO_CTRL_REG;
    reg_data[1] = 0x04;
    if (write(fd, reg_data, 2) != 2) {
        perror("Failed to write to I2C device");
        close(fd);
        return 1;
    }

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        close(fd);
        return 1;
    }

    while (1) {
        read_gyro_data(fd);
        usleep(100000); // Sleep for 100ms
    }

    close(fd);
    return 0;
}

