#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>

#define UART_DEVICE "/dev/serial0"
#define UART_SPEED B9600
#define TXD_GPIO 14
#define RXD_GPIO 15
#define COMMAND_SEQUENCE "\x7B\x01\x00\x00\x00\x00\x00\x00\x00"
#define RESPONSE_LENGTH 9
#define SAMPLE_INTERVAL 5000 // 5 seconds
#define TIMEOUT_INTERVAL 1000 // 1 second

int fd;
struct termios options;

void handle_signal(int signum) {
    if (fd != -1) {
        tcflush(fd, TCIOFLUSH);
        close(fd);
    }
    exit(signum);
}

int read_response(char *buffer, int timeout_ms) {
    struct timeval start, end;
    fd_set readfds;
    int bytes_read = 0;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    gettimeofday(&start, NULL);

    while (bytes_read < RESPONSE_LENGTH && (timeout_ms == 0 || (gettimeofday(&end, NULL) && (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec - start.tv_usec) / 1000 < timeout_ms))) {
        select(fd + 1, &readfds, NULL, NULL, NULL);
        if (FD_ISSET(fd, &readfds)) {
            int result = read(fd, buffer + bytes_read, RESPONSE_LENGTH - bytes_read);
            if (result < 0) {
                perror("read");
                return -1;
            }
            bytes_read += result;
        }
    }

    return bytes_read;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    if (tcgetattr(fd, &options) == -1) {
        perror("tcgetattr");
        close(fd);
        return 1;
    }

    cfsetispeed(&options, UART_SPEED);
    cfsetospeed(&options, UART_SPEED);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;

    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG | IEXTEN);
    options.c_oflag &= ~OPOST;

    if (tcsetattr(fd, TCSANOW, &options) == -1) {
        perror("tcsetattr");
        close(fd);
        return 1;
    }

    FILE *co2_log = fopen("co2_log.json", "a");
    FILE *co2_error = fopen("co2_error.log", "a");

    if (co2_log == NULL || co2_error == NULL) {
        perror("fopen");
        close(fd);
        return 1;
    }

    while (1) {
        char command[RESPONSE_LENGTH + 1];
        char response[RESPONSE_LENGTH + 1];

        strcpy(command, COMMAND_SEQUENCE);
        command[RESPONSE_LENGTH] = '\0';

        if (write(fd, command, RESPONSE_LENGTH) != RESPONSE_LENGTH) {
            perror("write");
            continue;
        }

        int bytes_read = read_response(response, TIMEOUT_INTERVAL);
        if (bytes_read != RESPONSE_LENGTH) {
            fprintf(co2_error, "Error: Incomplete response (%d bytes read)\n", bytes_read);
            continue;
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);
        long long timestamp = tv.tv_sec * 1000000 + tv.tv_usec;

        int ppm = (response[1] << 8) | response[2];
        int error_flag = (response[3] != 0);

        if (error_flag) {
            fprintf(co2_error, "Error: Checksum mismatch at %lld\n", timestamp);
            continue;
        }

        fprintf(co2_log, "{\"timestamp\":%lld,\"ppm\":%d,\"error\":%d}\n", timestamp, ppm, error_flag);
        fflush(co2_log);

        printf("{\"timestamp\":%lld,\"ppm\":%d,\"error\":%d}\n", timestamp, ppm, error_flag);

        sleep(SAMPLE_INTERVAL / 1000);
    }

    fclose(co2_log);
    fclose(co2_error);
    close(fd);

    return 0;
}

