int i2c_fd;
int red_gpio = 17;
int green_gpio = 27;
int blue_gpio = 22;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (remove(LOG_FILE) == 0) {
        printf("Log file removed.\n");
    }
    exit(signum);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_i2c_bus() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int read_lux() {
    uint8_t cmd[2] = {0x00, 0x00};
    uint8_t data[2];

    cmd[0] = 0x00; // Start measurement
    if (write(i2c_fd, cmd, 1) != 1) {
        perror("Failed to write to BH1750");
        return -1;
    }

    usleep(120000); // Wait at least 120ms

    cmd[0] = 0x00; // Read measurement
    if (write(i2c_fd, cmd, 1) != 1) {
        perror("Failed to write to BH1750");
        return -1;
    }

    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }

    int lux = (data[0] << 8) | data[1];
    return lux;
}

int main() {
    setup_signal_handlers();

    if (open_i2c_bus() < 0) {
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        int lux = read_lux();
        if (lux < 0) {
            fprintf(log_file, "Error reading lux value.\n");
            continue;
        }

        int red_state = 0, green_state = 0, blue_state = 0;

        if (lux < 50) {
            red_state = 1;
        } else if (lux >= 50 && lux < 150) {
            green_state = 1;
        } else if (lux >= 150 && lux < 300) {
            blue_state = 1;
        } else {
            red_state = 1;
            green_state = 1;
            blue_state = 1;
        }

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

        fprintf(log_file, "%s, Lux: %d, Red: %d, Green: %d, Blue: %d\n", timestamp, lux, red_state, green_state, blue_state);

        fflush(log_file);
        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

