#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_DUTY_RANGE 255

#define MOTOR_A_DISTANCE 50
#define MOTOR_B_DISTANCE 50

void cleanup() {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioTerminate();
    exit(0);
}

void handle_signal(int signum) {
    cleanup();
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <motor_a_distance> <motor_b_distance>\n", argv[0]);
        return 1;
    }

    int motor_a_distance = atoi(argv[1]);
    int motor_b_distance = atoi(argv[2]);

    if (motor_a_distance < 10 || motor_a_distance > 100 || motor_b_distance < 10 || motor_b_distance > 100) {
        fprintf(stderr, "Distance values must be in the range 10-100 cm.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    while (1) {
        int duty_cycle_a = (motor_a_distance - 10) * PWM_DUTY_RANGE / 90;
        int duty_cycle_b = (motor_b_distance - 10) * PWM_DUTY_RANGE / 90;

        if (gpioWrite(MOTOR_A_IN1, 1) < 0 || gpioWrite(MOTOR_B_IN3, 1) < 0) {
            fprintf(stderr, "Failed to set IN1 or IN3 high.\n");
            cleanup();
        }

        if (gpioPWM(MOTOR_A_IN2, duty_cycle_a) < 0 || gpioPWM(MOTOR_B_IN4, duty_cycle_b) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle.\n");
            cleanup();
        }

        usleep(100000); // Sleep for 100 ms

        if (gpioWrite(MOTOR_A_IN1, 0) < 0 || gpioWrite(MOTOR_B_IN3, 0) < 0) {
            fprintf(stderr, "Failed to set IN1 or IN3 low.\n");
            cleanup();
        }

        if (gpioPWM(MOTOR_A_IN2, 0) < 0 || gpioPWM(MOTOR_B_IN4, 0) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle to 0.\n");
            cleanup();
        }
    }

    cleanup();
    return 0;
}

