        gpioWrite(GPIO_IN2, LOW);
        gpioWrite(GPIO_IN3, HIGH);
        gpioWrite(GPIO_IN4, LOW);
        usleep(STEP_DELAY);

        gpioWrite(GPIO_IN1, LOW);
        gpioWrite(GPIO_IN2, HIGH);
        gpioWrite(GPIO_IN3, HIGH);
        gpioWrite(GPIO_IN4, LOW);
        usleep(STEP_DELAY);

        gpioWrite(GPIO_IN1, LOW);
        gpioWrite(GPIO_IN2, HIGH);
        gpioWrite(GPIO_IN3, LOW);
        gpioWrite(GPIO_IN4, HIGH);
        usleep(STEP_DELAY);

        gpioWrite(GPIO_IN1, HIGH);
        gpioWrite(GPIO_IN2, HIGH);
        gpioWrite(GPIO_IN3, LOW);
        gpioWrite(GPIO_IN4, HIGH);
        usleep(STEP_DELAY);
    }
}

void stepper_counterclockwise() {
    for (int i = 0; i < STEP_COUNT; i++) {
        gpioWrite(GPIO_IN1, HIGH);
        gpioWrite(GPIO_IN2, LOW);
        gpioWrite(GPIO_IN3, LOW);
        gpioWrite(GPIO_IN4, HIGH);
        usleep(STEP_DELAY);

        gpioWrite(GPIO_IN1, LOW);
        gpioWrite(GPIO_IN2, HIGH);
        gpioWrite(GPIO_IN3, LOW);
        gpioWrite(GPIO_IN4, HIGH);
        usleep(STEP_DELAY);

        gpioWrite(GPIO_IN1, LOW);
        gpioWrite(GPIO_IN2, HIGH);
        gpioWrite(GPIO_IN3, HIGH);
        gpioWrite(GPIO_IN4, LOW);
        usleep(STEP_DELAY);

        gpioWrite(GPIO_IN1, HIGH);
        gpioWrite(GPIO_IN2, HIGH);
        gpioWrite(GPIO_IN3, HIGH);
        gpioWrite(GPIO_IN4, LOW);
        usleep(STEP_DELAY);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LOCK, PI_INPUT) < 0 ||
        gpioSetMode(GPIO_UNLOCK, PI_INPUT) < 0 ||
        gpioSetMode(GPIO_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_LOCK, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(GPIO_UNLOCK, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistors\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        if (gpioRead(GPIO_LOCK) == 0) {
            printf("Locking...\n");
            stepper_clockwise();
            printf("Locked.\n");
            gpioDelay(100); // Debounce delay
        }

        if (gpioRead(GPIO_UNLOCK) == 0) {
            printf("Unlocking...\n");
            stepper_counterclockwise();
            printf("Unlocked.\n");
            gpioDelay(100); // Debounce delay
        }
    }

    printf("Exiting...\n");
    gpioTerminate();
    return 0;
}
