#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define SCHEDULE_FILE "lighting_schedule.txt"
#define NUM_RELAYS 4
#define RELAY_PINS[] {4, 17, 27, 22}
#define FADE_DURATION 1800 // 30 minutes in seconds
#define FADE_STEPS 1800 // 100Hz PWM, 1800 steps for 30 minutes
#define PWM_FREQUENCY 100000 // 100Hz

gpiod_chip *chip;
gpiod_line *relays[NUM_RELAYS];

void handle_signal(int signum) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(relays[i], 0);
    }
    gpiod_chip_put(chip);
    exit(signum);
}

void fade_lamp(int relay_index, int target_value) {
    int current_value = gpiod_line_get_value(relays[relay_index]);
    int step = (target_value - current_value) / FADE_STEPS;

    for (int i = 0; i < FADE_STEPS; i++) {
        gpiod_line_set_value(relays[relay_index], current_value);
        usleep(1000000 / PWM_FREQUENCY); // 1/100Hz = 10ms
        current_value += step;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if ((relays[i] = gpiod_line_request_by_name(chip, "gpio%d", RELAY_PINS[i], "relay", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
            perror("gpiod_line_request_by_name");
            for (int j = 0; j < i; j++) {
                gpiod_line_release(relays[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
    }

    FILE *schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        perror("fopen");
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_release(relays[i]);
        }
        gpiod_chip_put(chip);
        return 1;
    }

    char line[128];
    while (fgets(line, sizeof(line), schedule_file)) {
        char time_str[9], relay_str[3], state_str[4];
        sscanf(line, "%9s,%2s,%3s", time_str, relay_str, state_str);

        int relay_index = atoi(relay_str) - 1;
        if (relay_index < 0 || relay_index >= NUM_RELAYS) {
            fprintf(stderr, "Invalid relay number: %s\n", relay_str);
            continue;
        }

        int target_value = (strcmp(state_str, "on") == 0) ? 1 : 0;

        struct tm *time_info = localtime(&time);
        int current_hour = time_info->tm_hour;
        int current_minute = time_info->tm_min;
        int current_second = time_info->tm_sec;

        int target_hour = atoi(time_str);
        int target_minute = atoi(time_str + 3);
        int target_second = atoi(time_str + 6);

        if (current_hour < target_hour || (current_hour == target_hour && current_minute < target_minute) || (current_hour == target_hour && current_minute == target_minute && current_second < target_second)) {
            fade_lamp(relay_index, target_value);
        }
    }

    fclose(schedule_file);
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(relays[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

