#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DISTANCE 10 // Minimum distance in cm
#define MAX_DISTANCE 400 // Maximum distance in cm
#define MIN_FREQUENCY 200 // Minimum buzzer frequency in Hz
#define MAX_FREQUENCY 4000 // Maximum buzzer frequency in Hz
#define MEASUREMENT_RATE 50 // Measurement rate in Hz
#define MIN_INTERVAL 10000 // Minimum interval between measurements in microseconds

void cleanup(int signum) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(EXIT_FAILURE);
    }

    gpioWrite(BUZZER_PIN, PI_OUTPUT);
    gpioPWM(BUZZER_PIN, 0);

    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    signal(SIGINT, cleanup);

    while (1) {
        gpioWrite(TRIGGER_PIN, PI_LOW);
        usleep(10);
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        usleep(10);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        int echo_start = gpioGetTick(ECHO_PIN);
        if (echo_start == 0) {
            fprintf(stderr, "Failed to read echo start\n");
            continue;
        }

        int echo_end = gpioWaitForTick(ECHO_PIN, echo_start + 3000000); // Timeout after 3 seconds
        if (echo_end == 0) {
            fprintf(stderr, "Echo timeout\n");
            continue;
        }

        int duration = echo_end - echo_start;
        if (duration == 0) {
            fprintf(stderr, "Failed to read echo end\n");
            continue;
        }

        int distance = (duration / 58) / 2; // Convert to cm
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance reading\n");
            continue;
        }

        int frequency = (MAX_FREQUENCY - MIN_FREQUENCY) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_FREQUENCY;
        frequency = (frequency < MIN_FREQUENCY) ? MIN_FREQUENCY : (frequency > MAX_FREQUENCY) ? MAX_FREQUENCY : frequency;

        gpioPWM(BUZZER_PIN, frequency);

        usleep(1000000 / MEASUREMENT_RATE - duration);
        if (usleep(MIN_INTERVAL - (1000000 / MEASUREMENT_RATE - duration)) < 0) {
            fprintf(stderr, "Failed to enforce minimum interval\n");
        }
    }

    cleanup(0); // This line is never reached, but required for cleanup

    return EXIT_SUCCESS;
}

