#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pigpio.h>

#define FREQUENCY 1000
#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27

void cleanup(void) {
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

void handle_interrupt(int signum) {
    cleanup();
    exit(signum);
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
