#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <signal.h>

#include <libi2c-dev.h>

#define I2C_ADDR 0x68
#define GYRO_DATA_REG 0x43
#define GYRO_RATE 100 // 100 ms

void handle_signal(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    close(i2c_fd);
    fclose(log_file);
    exit(signum);
}

int main() {
    int i2c_fd;
    int ret;
    char buffer[14];
    struct i2c_rdwr_ioctl_data msg;
    struct i2c_msg msg_read[1];
    struct i2c_msg msg_write[1];
    struct i2c_rdwr_ioctl_data *msg_data;
    struct stat st;
    FILE *log_file;
    struct timespec ts;

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C device address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Infinite loop to read data
    while (1) {
        // Prepare read message
        msg_read[0].addr = I2C_ADDR;
        msg_read[0].flags = 0;
        msg_read[0].len = 14;
        msg_read[0].buf = buffer;

        // Prepare write message
        msg_write[0].addr = I2C_ADDR;
        msg_write[0].flags = 0;
        msg_write[0].len = 1;
        msg_write[0].buf = &GYRO_DATA_REG;

        // Combine read and write messages
        msg.msgs = msg_read;
        msg.nmsgs = 1;
        msg_data = &msg;

        // Perform I2C read/write
        ret = ioctl(i2c_fd, I2C_RDWR, &msg_data);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            break;
        }

        // Parse data
        int x = (buffer[0] << 8) | buffer[1];
        int y = (buffer[2] << 8) | buffer[3];
        int z = (buffer[4] << 8) | buffer[5];

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write to log file
        fprintf(log_file, "%ld.%09ld %d %d %d\n", (long)ts.tv_sec, (long)ts.tv_nsec, x, y, z);

        // Sleep for 100 ms
        usleep(GYRO_RATE * 1000);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

