#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_INTERVAL 50000  // 50 ms in microseconds

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

void play_melody(int melody[], int length) {
    for (int i = 0; i < length; i++) {
        if (stop_flag) {
            break;
        }
        gpioPWM(BUZZER_PIN, 50);  // 50% duty cycle
        gpioPWMfrequency(BUZZER_PIN, melody[i]);
        usleep(1000000 / melody[i]);  // Play note for 1 second
        gpioPWM(BUZZER_PIN, 0);  // Stop PWM
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set button pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on button pin\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(BUTTON_PIN, NULL, DEBOUNCE_INTERVAL) < 0) {
        fprintf(stderr, "Failed to set alert function for button pin\n");
        gpioTerminate();
        return 1;
    }

    const int melody[] = {440, 523, 659, 784, 988};  // Example melody frequencies
    int melody_length = sizeof(melody) / sizeof(melody[0]);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        if (gpioRead(BUTTON_PIN) == 0) {
            play_melody(melody, melody_length);
        }
        usleep(DEBOUNCE_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

