#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT 1000

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
}

void log_event(const char *filename, int value) {
    FILE *log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", filename);
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s %d\n", buffer, value);
    fflush(log_file);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int timeout = DEFAULT_TIMEOUT;
    if (argc > 1) {
        timeout = atoi(argv[1]);
        if (timeout <= 0) {
            fprintf(stderr, "Invalid timeout value: %s\n", argv[1]);
            return 1;
        }
    }

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_consumer *consumer;

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request_any(chip, GPIO_PIN, "VibrationSensor", &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_consumer(line, &consumer) < 0) {
        perror("Failed to set consumer for GPIO line");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_edge(line, GPIOD_LINE_BOTH_EDGES) < 0) {
        perror("Failed to set edge detection for GPIO line");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    int events[WINDOW_SIZE];
    int event_count = 0;
    int high_count = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!exit_flag) {
        int value = gpiod_line_get_value(line);
        log_event("vibration_events.log", value);

        events[event_count] = value;
        event_count = (event_count + 1) % WINDOW_SIZE;

        if (value == 1) {
            high_count++;
        } else {
            high_count = 0;
        }

        if (high_count >= 3) {
            time_t rawtime;
            struct tm *timeinfo;
            char buffer[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

            printf("EARTHQUAKE ALERT at %s\n", buffer);
            high_count = 0;
        }

        usleep(timeout * 1000);
    }

    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return 0;
}

