#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_TOUCH 4
#define GPIO_RELAY 17
#define DEBOUNCE_TIME 200 // in milliseconds

static gpiod_chip *chip;
static gpiod_line *touch_line;
static gpiod_line *relay_line;
static time_t last_touch_time = 0;
static int relay_state = 0;

void log_state_change(const char *state) {
    FILE *file = fopen("relay_log.json", "a");
    if (!file) {
        perror("Failed to open relay_log.json");
        exit(EXIT_FAILURE);
    }

    struct tm *time_info;
    time_t current_time = time(NULL);
    time_info = localtime(&current_time);

    fprintf(file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", asctime(time_info), state);
    fclose(file);
}

void touch_callback(struct gpiod_line *line, struct gpiod_line_event *event) {
    if (event->value == 1) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_touch_time) >= DEBOUNCE_TIME / 1000.0) {
            last_touch_time = current_time;
            relay_state = !relay_state;

            gpiod_line_set_value(relay_line, relay_state);
            log_state_change(relay_state ? "ON" : "OFF");
        }
    }
}

void cleanup() {
    gpiod_line_free(touch_line);
    gpiod_line_free(relay_line);
    gpiod_chip_put(chip);
}

void sigint_handler(int signum) {
    relay_state = 0;
    gpiod_line_set_value(relay_line, relay_state);
    log_state_change("OFF");
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_by_name(chip, "gpio4", &touch_line, "touch_line", 0, 0) < 0) {
        perror("Failed to request touch line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_by_name(chip, "gpio17", &relay_line, "relay_line", 0, 0) < 0) {
        perror("Failed to request relay line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_debounce(touch_line, DEBOUNCE_TIME);
    gpiod_line_set_edge_both(touch_line);
    gpiod_line_set_value(touch_line, 0);
    gpiod_line_set_value(relay_line, relay_state);

    gpiod_line_event_handler_add(touch_line, touch_callback, NULL);

    signal(SIGINT, sigint_handler);

    while (1) {
        sleep(1);
    }

    return 0;
}

