void handle_signal(int signum) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_request_free(lines[i]);
    }
    gpiod_chip_put(chip);
    fclose(log_file);
    fprintf(stderr, "Received signal %d, exiting cleanly.\n", signum);
    exit(0);
}

void activate_relays(int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], 0);
            sleep(RELAY_ON_TIME);
            gpiod_line_set_value(lines[i], 1);
            sleep(SLEEP_BETWEEN_RELAYS);
        }
        fprintf(log_file, "%s, Relay %d, Moisture Level: %d\n", ctime(&time(NULL)), i + 1, moisture_level);
        fflush(log_file);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_put(chip);
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_by_name(chip, "gpio%d", GPIOD_LINE_DIRECTION_OUTPUT, &lines[i]) < 0) {
            perror("Failed to request GPIO line");
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(lines[j]);
            }
            gpiod_chip_put(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
        gpiod_line_set_value(lines[i], 1);
    }

    while (1) {
        int moisture_level = rand() % 101;
        printf("Moisture Level: %d\n", moisture_level);
        activate_relays(moisture_level);
        sleep(10);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_request_free(lines[i]);
    }
    gpiod_chip_put(chip);
    fclose(log_file);

    return 0;
}

