#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <libgpiod.h>

#define NUM_ANGLES 5
#define NUM_TRIES 3
#define BACKOFF_MS 100
#define WATERING_DELAY_S 5
#define SERVO_OPEN_ANGLE 1500
#define SERVO_CLOSE_ANGLE 500

volatile sig_atomic_t stop_requested = 0;

void handle_signal(int signum) {
    stop_requested = 1;
}

int set_servo_angle(struct gpiod_line *line, int angle) {
    int ret;
    for (int i = 0; i < NUM_TRIES; i++) {
        ret = gpiod_line_set_function(line, GPIOD_LINE_FUNCTION_PWM);
        if (ret < 0) {
            if (i < NUM_TRIES - 1) {
                usleep(BACKOFF_MS * 1000);
            } else {
                fprintf(stderr, "Failed to set line function to PWM\n");
                return -1;
            }
        } else {
            break;
        }
    }

    for (int i = 0; i < NUM_TRIES; i++) {
        ret = gpiod_line_set_value(line, angle);
        if (ret < 0) {
            if (i < NUM_TRIES - 1) {
                usleep(BACKOFF_MS * 1000);
            } else {
                fprintf(stderr, "Failed to set servo angle\n");
                return -1;
            }
        } else {
            break;
        }
    }

    return 0;
}

void cleanup_servos(struct gpiod_line *valve, struct gpiod_line *nozzle) {
    gpiod_line_set_value(valve, SERVO_CLOSE_ANGLE);
    gpiod_line_set_function(valve, GPIOD_LINE_FUNCTION_OUTPUT);
    gpiod_line_set_value(valve, 0);

    gpiod_line_set_function(nozzle, GPIOD_LINE_FUNCTION_OUTPUT);
    gpiod_line_set_value(nozzle, 0);

    gpiod_line_free(valve);
    gpiod_line_free(nozzle);
}

int main() {
    struct gpiod_line *valve, *nozzle;
    int ret;

    struct gpiod_chip *chip;
    chip = gpiod_chip_open(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    valve = gpiod_line_request_by_name(chip, "17", "valve", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!valve) {
        fprintf(stderr, "Failed to request valve GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    nozzle = gpiod_line_request_by_name(chip, "18", "nozzle", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!nozzle) {
        fprintf(stderr, "Failed to request nozzle GPIO line\n");
        gpiod_line_free(valve);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int moisture_values[] = {20, 40, 60, 80, 100};
    int moisture_index = 0;

    while (!stop_requested) {
        int moisture = moisture_values[moisture_index];
        moisture_index = (moisture_index + 1) % sizeof(moisture_values) / sizeof(moisture_values[0]);

        if (moisture < 50) {
            if (set_servo_angle(valve, SERVO_OPEN_ANGLE) < 0) {
                fprintf(stderr, "Failed to open valve\n");
                cleanup_servos(valve, nozzle);
                return 1;
            }

            for (int i = 0; i < NUM_ANGLES; i++) {
                int angle = (i * 45) + 500;
                if (set_servo_angle(nozzle, angle) < 0) {
                    fprintf(stderr, "Failed to set nozzle angle to %d degrees\n", angle / 100);
                }
                sleep(2);
            }

            sleep(5);

            if (set_servo_angle(valve, SERVO_CLOSE_ANGLE) < 0) {
                fprintf(stderr, "Failed to close valve\n");
            }

            sleep(WATERING_DELAY_S);
        } else {
            sleep(WATERING_DELAY_S);
        }
    }

    cleanup_servos(valve, nozzle);
    gpiod_chip_close(chip);

    return 0;
}

