#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c.h>

#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDR 0x68
#define SAMPLE_RATE 100000000 / 10 // 10 Hz
#define GYRO_DATA_REG 0x43
#define GYRO_DATA_LEN 6

static int i2c_fd;
static FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_gyro_data(int *x, int *y, int *z) {
    char buffer[GYRO_DATA_LEN];
    ssize_t bytes_read = read(i2c_fd, buffer, GYRO_DATA_LEN);
    if (bytes_read != GYRO_DATA_LEN) {
        perror("Failed to read gyro data");
        return -1;
    }
    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handlers");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    int x, y, z;
    while (1) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d, %d\n",
                    now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                    now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, x, y, z);
        }
        usleep(SAMPLE_RATE);
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

