#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1_PIN 4
#define IN2_PIN 17
#define IN3_PIN 27
#define IN4_PIN 22
#define LOCK_PIN 24
#define UNLOCK_PIN 23

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

void rotate_motor(int steps, int direction) {
    int i;
    for (i = 0; i < steps && !stop; i++) {
        switch (direction) {
            case 1: // Clockwise
                gpioWrite(IN1_PIN, 1);
                gpioWrite(IN2_PIN, 0);
                gpioWrite(IN3_PIN, 1);
                gpioWrite(IN4_PIN, 0);
                break;
            case -1: // Counter-clockwise
                gpioWrite(IN1_PIN, 0);
                gpioWrite(IN2_PIN, 1);
                gpioWrite(IN3_PIN, 0);
                gpioWrite(IN4_PIN, 1);
                break;
        }
        gpioDelay(3000); // 3ms delay
        gpioWrite(IN1_PIN, 0);
        gpioWrite(IN2_PIN, 0);
        gpioWrite(IN3_PIN, 0);
        gpioWrite(IN4_PIN, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(LOCK_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_PIN, PI_PUD_UP);
    gpioSetMode(UNLOCK_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_PIN, PI_PUD_UP);

    signal(SIGINT, handle_sigint);

    while (!stop) {
        if (gpioRead(LOCK_PIN) == 0) {
            printf("Lock pressed\n");
            rotate_motor(512, 1);
        }
        if (gpioRead(UNLOCK_PIN) == 0) {
            printf("Unlock pressed\n");
            rotate_motor(512, -1);
        }
        gpioDelay(100); // Debounce delay
    }

    gpioWrite(IN1_PIN, 0);
    gpioWrite(IN2_PIN, 0);
    gpioWrite(IN3_PIN, 0);
    gpioWrite(IN4_PIN, 0);

    gpioTerminate();
    return 0;
}

