#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_DEFAULT_ADDR 0x29
#define RELAY_GPIO 18
#define POLL_INTERVAL 100 // ms

static gpiod_chip *gpiod_chip;
static gpiod_line *relay_line;
static int i2c_fd;

void handle_sigint(int signum) {
    if (gpiod_line_set_value(relay_line, 0) < 0) {
        fprintf(stderr, "Failed to set relay pin low: %s\n", gpiod_line_get_last_error(relay_line));
    }
    if (gpiod_line_unexport(relay_line) < 0) {
        fprintf(stderr, "Failed to unexport relay line: %s\n", gpiod_line_get_last_error(relay_line));
    }
    if (gpiod_chip_put(gpiod_chip) < 0) {
        fprintf(stderr, "Failed to put gpiod chip: %s\n", gpiod_chip_get_last_error(gpiod_chip));
    }
    if (close(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C file descriptor: %s\n", strerror(errno));
    }
    exit(1);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpiod_chip) {
        fprintf(stderr, "Failed to open gpiod chip: %s\n", gpiod_chip_get_last_error(gpiod_chip));
        return 1;
    }

    relay_line = gpiod_line_request_by_name(gpiod_chip, "gpio%d", RELAY_GPIO, "Relay", "output", NULL);
    if (!relay_line) {
        fprintf(stderr, "Failed to request relay line: %s\n", gpiod_line_get_last_error(relay_line));
        gpiod_chip_put(gpiod_chip);
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpiod_line_unexport(relay_line);
        gpiod_chip_put(gpiod_chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_DEFAULT_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_line_unexport(relay_line);
        gpiod_chip_put(gpiod_chip);
        return 1;
    }

    while (1) {
        int distance = 0; // Placeholder for actual distance reading logic
        // Read distance from VL53L1X sensor here

        if (distance <= 50) {
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                fprintf(stderr, "Failed to set relay pin high: %s\n", gpiod_line_get_last_error(relay_line));
            }
        } else {
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                fprintf(stderr, "Failed to set relay pin low: %s\n", gpiod_line_get_last_error(relay_line));
            }
        }

        printf("Distance: %d cm\n", distance);

        usleep(POLL_INTERVAL * 1000); // Convert ms to us
    }

    return 0;
}

