#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x68 // Default I2C address for the MPU-6050
#define BUFFER_SIZE 14 // Size of the buffer to read data from the sensor

// Function prototypes
void handle_signal(int signum);
int read_gyro_data(int file_descriptor);

int main() {
    int file_descriptor;
    char buffer[BUFFER_SIZE];
    int bytes_read;

    // Open the I2C bus
    file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (file_descriptor < 0) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C device address
    if (ioctl(file_descriptor, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file_descriptor);
        exit(EXIT_FAILURE);
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop to read and print gyro data
    while (1) {
        bytes_read = read_gyro_data(file_descriptor);
        if (bytes_read < 0) {
            perror("Failed to read gyro data");
            break;
        }

        // Print the data
