#define GPIO_HIGH 0
#define GPIO_LOW 1
#define WATERING_LOG_FILE "watering_log.txt"
#define WATERING_INTERVAL 86400 // 24 hours in seconds
#define WATERING_CYCLE_INTERVAL 60 // 1 minute in seconds

gpiod_chip *chip;
gpiod_line *lines[GPIO_LINE_COUNT];

void handle_signal(int signum) {
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_request_free(lines[i]);
    }
    gpiod_chip_put(chip);
    exit(signum);
}

int main() {
    struct timespec start_time;
    struct tm *time_info;
    char buffer[32];

    // Open the GPIO chip
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO lines
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        if ((lines[i] = gpiod_line_request(chip, GPIO_LINES[i], "Watering Relay %d", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
            perror("Failed to request GPIO line");
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }

        // Set initial state to HIGH (inactive)
        if (gpiod_line_set_value(lines[i], GPIO_HIGH) < 0) {
            perror("Failed to set GPIO line value");
            for (int j = 0; j < i; j++) {
                gpiod_line_request_free(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Log start time of the cycle
        time(&start_time);
        time_info = localtime(&start_time);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", time_info);
        FILE *log_file = fopen(WATERING_LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            for (int i = 0; i < GPIO_LINE_COUNT; i++) {
                gpiod_line_request_free(lines[i]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
        if (fprintf(log_file, "%s\n", buffer) < 0) {
            perror("Failed to write to log file");
            fclose(log_file);
            for (int i = 0; i < GPIO_LINE_COUNT; i++) {
                gpiod_line_request_free(lines[i]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
        fclose(log_file);

        // Activate each relay in turn
        for (int i = 0; i < GPIO_LINE_COUNT; i++) {
            if (gpiod_line_set_value(lines[i], GPIO_LOW) < 0) {
                perror("Failed to set GPIO line value");
                for (int j = 0; j < i; j++) {
                    gpiod_line_request_free(lines[j]);
                }
                gpiod_chip_put(chip);
                return 1;
            }
            sleep(WATERING_CYCLE_INTERVAL);
            if (gpiod_line_set_value(lines[i], GPIO_HIGH) < 0) {
                perror("Failed to set GPIO line value");
                for (int j = 0; j < i; j++) {
                    gpiod_line_request_free(lines[j]);
                }
                gpiod_chip_put(chip);
                return 1;
            }
        }

        // Wait for the next cycle
        sleep(WATERING_INTERVAL - (GPIO_LINE_COUNT * WATERING_CYCLE_INTERVAL));
    }

    // Cleanup on exit
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_request_free(lines[i]);
    }
    gpiod_chip_put(chip);

    return 0;
}

