#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PINS {17, 18, 27, 22}
#define NUM_PINS 4
#define PWM_FREQUENCY 1000
#define MAX_DUTY_CYCLE 255
#define LOG_FILE "smart_lighting.log"

gpiod_chip *chip;
gpiod_line *lines[NUM_PINS];

void cleanup(int signum) {
    for (int i = 0; i < NUM_PINS; i++) {
        gpiod_line_free(lines[i]);
    }
    gpiod_chip_put(chip);
    printf("Cleaned up resources and exited.\n");
    exit(0);
}

int main() {
    FILE *log_file;
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return 1;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_line_request(chip, GPIO_PINS[i], "smart_lighting", 0, GPIOD_LINE_DIRECTION_OUTPUT);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PINS[i]);
            cleanup(0);
        }

        if (gpiod_line_set_function(lines[i], GPIOD_LINE_FUNCTION_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO line %d function to output\n", GPIO_PINS[i]);
            cleanup(0);
        }
    }

    for (int duty_cycle = 0; duty_cycle <= MAX_DUTY_CYCLE; duty_cycle++) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], duty_cycle) < 0) {
                fprintf(stderr, "Failed to set GPIO line %d duty cycle\n", GPIO_PINS[i]);
                cleanup(0);
            }
        }

        fprintf(log_file, "Time: %ld, Duty Cycle: %d\n", time(NULL), duty_cycle);
        fflush(log_file);
        usleep(1000000 / PWM_FREQUENCY); // Sleep for 1/PWM_FREQUENCY seconds
    }

    fclose(log_file);
    cleanup(0);

    return 0;
}

