#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68
#define BUFFER_SIZE 100
#define LED_GPIO 17
#define SAMPLE_RATE 20 // Hz
#define SAMPLE_PERIOD (1000 / SAMPLE_RATE) // ms
#define MAX_RETRIES 3

typedef struct {
    int timestamp;
    int x;
    int y;
    int z;
} GyroData;

GyroData buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_full = 0;

int i2c_fd;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("Received signal %d, cleaning up...\n", signum);
    exit(0);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_gyro_data(GyroData *data) {
    char buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read(i2c_fd, buffer, 6) != 6) {
            if (retries < MAX_RETRIES - 1) {
                retries++;
                continue;
            } else {
                perror("Failed to read gyro data");
                return -1;
            }
        }

        data->x = (buffer[0] << 8) | buffer[1];
        data->y = (buffer[2] << 8) | buffer[3];
        data->z = (buffer[4] << 8) | buffer[5];

        return 0;
    }

    return -1;
}

void update_led(int x, int y, int z) {
    int threshold = 250;
    int led_state = (abs(x) > threshold || abs(y) > threshold || abs(z) > threshold) ? 1 : 0;

    if (led_state != 0) {
        printf("LED ON: |X| = %d, |Y| = %d, |Z| = %d\n", abs(x), abs(y), abs(z));
    } else {
        printf("LED OFF: |X| = %d, |Y| = %d, |Z| = %d\n", abs(x), abs(y), abs(z));
    }

    // Assuming a function to set GPIO state
    set_gpio_state(LED_GPIO, led_state);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() < 0) {
        return 1;
    }

    while (1) {
        GyroData data;
        if (read_gyro_data(&data) < 0) {
            continue;
        }

        data.timestamp = time(NULL);

        buffer[buffer_head] = data;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;

        if (buffer_head == buffer_tail) {
            buffer_full = 1;
        }

        update_led(data.x, data.y, data.z);

        usleep(SAMPLE_PERIOD * 1000);
    }

    close(i2c_fd);
    return 0;
}

