#include <stdint.h>
#include <time.h>
#include <libgpiod.h>

#define BUFFER_SIZE 64
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define SPI_CS_GPIO 8
#define LED_GPIO 17
#define THRESHOLD 200

typedef struct {
    uint32_t timestamp;
    int16_t x, y, z;
} Sample;

Sample buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

int spi_fd;
struct gpiod_line *spi_cs_line;
struct gpiod_line *led_line;

void handle_sigint(int signum) {
    gpiod_line_free(spi_cs_line);
    gpiod_line_free(led_line);
    close(spi_fd);
    exit(0);
}

void blink_led() {
    gpiod_line_set_value(led_line, 1);
    usleep(500000);
    gpiod_line_set_value(led_line, 0);
    usleep(500000);
}

int read_sensor() {
    uint8_t data[6];
    int ret;

    ret = gpiod_line_export(SPI_CS_GPIO, "spi_cs");
    if (ret < 0) {
        perror("gpiod_line_export");
        return -1;
    }

    ret = gpiod_line_request(spi_cs_line, "spi_cs", GPIOD_LINE_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("gpiod_line_request");
        return -1;
    }

    ret = gpiod_line_set_value(spi_cs_line, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }

    ret = spi_read(spi_fd, data, 6);
    if (ret < 0) {
        perror("spi_read");
        return -1;
    }

    gpiod_line_set_value(spi_cs_line, 1);

    if (ret != 6) {
        fprintf(stderr, "Invalid data read from sensor\n");
        return -1;
    }

    buffer[buffer_head].x = (int16_t)((data[0] << 8) | data[1]);
    buffer[buffer_head].y = (int16_t)((data[2] << 8) | data[3]);
    buffer[buffer_head].z = (int16_t)((data[4] << 8) | data[5]);
    buffer[buffer_head].timestamp = time(NULL);

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    if (buffer_head == buffer_tail) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }

    if (buffer[buffer_head].x > THRESHOLD || buffer[buffer_head].x < -THRESHOLD ||
        buffer[buffer_head].y > THRESHOLD || buffer[buffer_head].y < -THRESHOLD ||
        buffer[buffer_head].z > THRESHOLD || buffer[buffer_head].z < -THRESHOLD) {
        blink_led();
    }

    return 0;
}

int main() {
    struct sigaction sa;
    int ret;

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("ioctl SPI_IOC_RD_MODE");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("ioctl SPI_IOC_RD_MAX_SPEED_HZ");
        return 1;
    }

    spi_cs_line = gpiod_line_request_by_name("spi_cs", "spi_cs", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!spi_cs_line) {
        perror("gpiod_line_request_by_name");
        return 1;
    }

    led_line = gpiod_line_request_by_name("led", "led", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!led_line) {
        perror("gpiod_line_request_by_name");
        return 1;
    }

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        if (read_sensor() < 0) {
            break;
        }
        usleep(100000); // 100 ms delay
    }

    printf("Timestamp,X,Y,Z\n");
    for (int i = buffer_tail; i != buffer_head; i = (i + 1) % BUFFER_SIZE) {
        printf("%u,%d,%d,%d\n", buffer[i].timestamp, buffer[i].x, buffer[i].y, buffer[i].z);
    }

    return 0;
}

