#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <mpu6050.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define LED_PIN 21
#define SAMPLE_INTERVAL 100 // in milliseconds

static struct gpiod_line *led_line;
static struct mpu6050 *mpu;
static FILE *log_file;

void cleanup(int signum) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_free(led_line);
    }

    if (mpu) {
        mpu6050_close(mpu);
    }

    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;
    int err;

    // Initialize LED GPIO
    err = gpiod_chip_open_by_name("gpio", 0, &chip);
    if (err < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    req = gpiod_line_request_new(chip, LED_PIN, "tilt_led", 0, 0, 0);
    if (!req) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    led_line = gpiod_line_request_get_line(req);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_line_request_put(req);
        gpiod_chip_put(chip);
        return 1;
    }

    // Initialize I2C bus
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_free(led_line);
        gpiod_line_request_put(req);
        gpiod_chip_put(chip);
        return 1;
    }

