    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_free(led_line);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int read_sensor(int *ambient_light, int *proximity) {
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        if (write(i2c_fd, "\x00", 1) != 1) {
            return -1;
        }

        if (read(i2c_fd, ambient_light, 2) != 2) {
            return -1;
        }

        if (read(i2c_fd, proximity, 2) != 2) {
            return -1;
        }

        *ambient_light = (*ambient_light << 8) | *proximity;
        result = 0;
        break;

        usleep(10000); // 10 ms delay
        retries--;
    }

    return result;
}

