#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define ALERT_PIN 17
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_DURATION 2000 // 2 seconds in milliseconds
#define MIN_DURATION 500 // 500 milliseconds

static struct gpiod_line *sensor1_line = NULL;
static struct gpiod_line *sensor2_line = NULL;
static struct gpiod_line *alert_line = NULL;
static FILE *log_file = NULL;

static void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_free(alert_line);
    }
    if (sensor1_line) {
        gpiod_line_free(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_free(sensor2_line);
    }
    exit(signum);
}

static void sensor_callback(struct gpiod_line *line, enum gpiod_line_status status, void *data) {
    static struct timespec start_time;
    static struct timespec end_time;
    static int sensor1_state = 0;
    static int sensor2_state = 0;
    static int alert_triggered = 0;

    if (status == GPIOD_LINE_STATUS_HIGH) {
        if (line == sensor1_line) {
            sensor1_state = 1;
        } else if (line == sensor2_line) {
            sensor2_state = 1;
        }

        if (sensor1_state && sensor2_state) {
            if (!alert_triggered) {
                alert_triggered = 1;
                start_time = gpiod_get_current_time();
            }
        } else {
            alert_triggered = 0;
        }
    } else {
        if (line == sensor1_line) {
            sensor1_state = 0;
        } else if (line == sensor2_line) {
            sensor2_state = 0;
        }
    }

    if (sensor1_state && sensor2_state && alert_triggered) {
        end_time = gpiod_get_current_time();
        if (end_time.tv_sec * 1000 + end_time.tv_nsec / 1000000 - start_time.tv_sec * 1000 - start_time.tv_nsec / 1000000 >= MIN_DURATION) {
            gpiod_line_set_value(alert_line, 1);
            usleep(ALERT_DURATION * 1000); // Sleep for 2 seconds
            gpiod_line_set_value(alert_line, 0);

            char timestamp[20];
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);

            fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
            fflush(log_file);
        }
    }
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request request;

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if ((log_file = fopen("seismic_events.txt", "a")) == NULL) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return 1;
    }

    memset(&request, 0, sizeof(request));
    request.consumer = "Seismic Sensor";
    request.consumer_user = getuid();
    request.flags = GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if ((sensor1_line = gpiod_line_request_by_name(chip, "gpio23", &request)) == NULL) {
        perror("Failed to request sensor1 line");
        goto cleanup;
    }

    if ((sensor2_line = gpiod_line_request_by_name(chip, "gpio24", &request)) == NULL) {
        perror("Failed to request sensor2 line");
        goto cleanup;
    }

    if ((alert_line = gpiod_line_request_by_name(chip, "gpio17", &request)) == NULL) {
        perror("Failed to request alert line");
        goto cleanup;
    }

