    gpiod_line_set_edge(sensor2_line, GPIOD_LINE_BOTH_EDGES);

    gpiod_line_add_callback(sensor1_line, sensor_callback, NULL);
    gpiod_line_add_callback(sensor2_line, sensor_callback, NULL);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        sleep(1);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_free(alert_line);
    }
    if (sensor1_line) {
        gpiod_line_free(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_free(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

