#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define THRESHOLD 20.0

struct reading {
    double rate;
    struct timespec timestamp;
};

struct reading buffer[BUFFER_SIZE];
int head = 0;
int tail = 0;
int buffer_full = 0;

void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_chip_put(chip);
        pigpio_stop();
        exit(0);
    }
}

int spi_transfer(uint8_t *tx, uint8_t *rx, uint8_t length) {
    int ret = pigpio_spi_write(0, tx, rx, length);
    if (ret != length) {
        fprintf(stderr, "SPI transfer error: %d\n", ret);
        return -1;
    }
    return 0;
}

int read_gyro_x(uint8_t *data) {
    uint8_t tx[2] = {0x00, 0x00}; // Address for X-axis rate register
    tx[1] |= 0x80; // Set MSB to 1 for read

    if (spi_transfer(tx, data, 2) < 0) {
        return -1;
    }

    return 0;
}

void update_buffer(double rate) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    buffer[head].rate = rate;
    buffer[head].timestamp = now;

    head = (head + 1) % BUFFER_SIZE;
    if (head == tail) {
        buffer_full = 1;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    if (gpiod_line_request_any(chip, "17", &led_line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request GPIO line for LED\n");
        gpiod_chip_put(chip);
        return 1;
    }

    if (pigpio_start() < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        gpiod_line_release(led_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Failed to set LED off\n");
        gpiod_line_release(led_line);
        gpiod_chip_put(chip);
        pigpio_stop();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        uint8_t data[2];
        if (read_gyro_x(data) < 0) {
            continue;
        }

        double rate = (data[0] << 8) | data[1];
        update_buffer(rate);

        if (rate > THRESHOLD) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Failed to set LED on\n");
            }
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to set LED off\n");
            }
        }

        usleep(100000); // Sleep for 100ms
    }

    gpiod_line_release(led_line);
    gpiod_chip_put(chip);
    pigpio_stop();

    return 0;
}

