#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_LAMPS 3
#define PWM_FREQUENCY 100
#define PWM_DUTY_CYCLE_MAX 255

int lamp_gpios[NUM_LAMPS] = {17, 18, 27};
int lamp_pwm_channels[NUM_LAMPS];
int total_duration;

void handle_signal(int signum) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        gpioPWM(lamp_gpios[i], 0);
    }
    for (int i = 0; i < NUM_LAMPS; i++) {
        gpioPWMStop(lamp_pwm_channels[i]);
    }
    exit(signum);
}

void fade_lamp(int lamp_index, int duration) {
    int start_duty = PWM_DUTY_CYCLE_MAX;
    int end_duty = 0;
    int step = (start_duty - end_duty) / duration;

    printf("Fading lamp %d from %d%% to 0%% over %d seconds...\n", lamp_index + 1, start_duty * 100 / PWM_DUTY_CYCLE_MAX, duration);

    for (int duty = start_duty; duty >= end_duty; duty -= step) {
        gpioPWM(lamp_gpios[lamp_index], duty);
        usleep(1000000 / PWM_FREQUENCY);
    }

    printf("Lamp %d faded to 0%%\n", lamp_index + 1);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_in_seconds>\n", argv[0]);
        return 1;
    }

    total_duration = atoi(argv[1]);
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Invalid duration. Please enter a value between 1 and 3600 seconds.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    for (int i = 0; i < NUM_LAMPS; i++) {
        lamp_pwm_channels[i] = i;
        if (gpioSetMode(lamp_gpios[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output.\n", lamp_gpios[i]);
            return 1;
        }
        if (gpioSetPWMfrequency(lamp_gpios[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d.\n", lamp_gpios[i]);
            return 1;
        }
        if (gpioPWM(lamp_gpios[i], PWM_DUTY_CYCLE_MAX) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d.\n", lamp_gpios[i]);
            return 1;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Starting sunset sequence over %d seconds...\n", total_duration);

    int duration_per_lamp = total_duration / NUM_LAMPS;
    for (int i = 0; i < NUM_LAMPS; i++) {
        fade_lamp(i, duration_per_lamp);
    }

    printf("Sunset sequence completed.\n");

    for (int i = 0; i < NUM_LAMPS; i++) {
        gpioPWMStop(lamp_gpios[i]);
    }

    gpioTerminate();

    return 0;
}

