#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_PIN 17
#define DEBOUNCE_DELAY 100 // ms
#define TOUCH_INTERVAL 10 // ms

static gpiod_line *gpio_pin;
static FILE *log_file;

void handle_signal(int signum) {
    if (gpio_pin) {
        gpiod_line_release(gpio_pin);
        free(gpio_pin);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

void log_error(const char *msg) {
    time_t now;
    struct tm *now_tm;
    char timestamp[32];

    time(&now);
    now_tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

    fprintf(log_file, "%s - %s\n", timestamp, msg);
    fflush(log_file);
}

int main() {
    int fd;
    char buf[2];
    struct i2c_rdwr_ioctl_data msg;
    struct i2c_msg msg_buf[2];
    struct i2c_rdwr_ioctl_data *i2c_data;
    struct gpiod_line_request_flags flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    struct gpiod_line_request req;
    struct gpiod_line_consumer consumer;
    struct gpiod_line_consumer_request_flags flags_consumer = GPIOD_LINE_CONSUMER_REQUEST_ACTIVE_LOW;
    struct gpiod_line_consumer_request req_consumer;
    struct timespec ts;
    struct timespec ts_debounce;
    int ret;

    log_file = fopen("touch_relay.log", "w");
    if (!log_file) {
        log_error("Failed to open log file.");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus.");
        fclose(log_file);
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPR121_ADDR) < 0) {
