#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define LOG_FILE "flame_log.txt"
#define DELAY_MS 50

static gpiod_chip *chip;
static gpiod_line *flame_sensor, *buzzer, *led;
static FILE *log_file;

void handle_signal(int signum) {
    if (flame_sensor) {
        gpiod_line_request_release(flame_sensor);
    }
    if (buzzer) {
        gpiod_line_request_release(buzzer);
    }
    if (led) {
        gpiod_line_request_release(led);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    int flame_count = 0;
    int sensor_value;
    struct timespec ts;

    // Initialize libgpiod
    if ((chip = gpiod_chip_open("/dev/gpiomem")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO lines
    if ((flame_sensor = gpiod_line_request_by_name(chip, "gpio%d", FLAME_SENSOR_PIN, "flame_sensor", 0)) == NULL) {
        perror("Failed to request flame sensor GPIO");
        goto error_flame_sensor;
    }

    if ((buzzer = gpiod_line_request_by_name(chip, "gpio%d", BUZZER_PIN, "buzzer", 0)) == NULL) {
        perror("Failed to request buzzer GPIO");
        goto error_buzzer;
    }

    if ((led = gpiod_line_request_by_name(chip, "gpio%d", LED_PIN, "led", 0)) == NULL) {
        perror("Failed to request LED GPIO");
        goto error_led;
    }

    // Set direction and initial value
    if (gpiod_line_direction_set(flame_sensor, GPIOD_LINE_DIRECTION_IN) < 0) {
        perror("Failed to set direction for flame sensor GPIO");
        goto error_direction;
    }

    if (gpiod_line_value_set(flame_sensor, 1) < 0) {
        perror("Failed to set initial value for flame sensor GPIO");
        goto error_value;
    }

    if (gpiod_line_direction_set(buzzer, GPIOD_LINE_DIRECTION_OUT) < 0) {
        perror("Failed to set direction for buzzer GPIO");
        goto error_direction;
    }

    if (gpiod_line_direction_set(led, GPIOD_LINE_DIRECTION_OUT) < 0) {
        perror("Failed to set direction for LED GPIO");
        goto error_direction;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        goto error_log_file;
    }

    // Register signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        if (gpiod_line_get_value(flame_sensor) == 0) {
            flame_count++;
            if (flame_count >= 3) {
                flame_count = 0;
                gpiod_line_value_set(buzzer, 1);
                gpiod_line_value_set(led, 1);

                // Log flame detection
                clock_gettime(CLOCK_REALTIME, &ts);
                fprintf(log_file, "%ld.%09ld: Flame Detected\n", (long)ts.tv_sec, (long)ts.tv_nsec);
                fflush(log_file);
            }
        } else {
            flame_count = 0;
            gpiod_line_value_set(buzzer, 0);
            gpiod_line_value_set(led, 0);
        }

        usleep(DELAY_MS * 1000);
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_request_release(led);
    gpiod_line_request_release(buzzer);
    gpiod_line_request_release(flame_sensor);
    gpiod_chip_close(chip);

    return 0;

error_log_file:
    gpiod_line_request_release(led);
error_direction:
    gpiod_line_request_release(buzzer);
error_value:
    gpiod_line_request_release(flame_sensor);
error_led:
    gpiod_line_request_release(buzzer);
error_buzzer:
    gpiod_line_request_release(flame_sensor);
error_flame_sensor:
    gpiod_chip_close(chip);
    return 1;
}

