#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN_1 17
#define GPIO_PIN_2 27
#define DISPENSE_INTERVAL 1000
#define HALF_INTERVAL (DISPENSE_INTERVAL / 2)
#define LOG_FILE "dispense_log.txt"

static gpiod_chip *chip;
static gpiod_line *line1, *line2;
static FILE *log_file;

void handle_sigint(int signum) {
    if (line1) {
        gpiod_line_request_unexport(line1);
        gpiod_line_free(line1);
        line1 = NULL;
    }
    if (line2) {
        gpiod_line_request_unexport(line2);
        gpiod_line_free(line2);
        line2 = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(0);
}

int init_gpiod() {
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line1 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_PIN_1, "dispense_solenoid1", 0);
    if (!line1) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PIN_1);
        gpiod_chip_put(chip);
        chip = NULL;
        return -1;
    }

    line2 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_PIN_2, "dispense_solenoid2", 0);
    if (!line2) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PIN_2);
        gpiod_line_request_unexport(line1);
        gpiod_line_free(line1);
        gpiod_chip_put(chip);
        chip = NULL;
        return -1;
    }

    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);

    return 0;
}

int open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

void log_dispense_event(int solenoid_pin, int duration) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Solenoid %d - Duration: %d ms\n", buffer, solenoid_pin, duration);
}

int main() {
    struct timespec ts;
    int ret;

    signal(SIGINT, handle_sigint);

    if (init_gpiod() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (open_log_file() != 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        gpiod_line_set_value(line1, 1);
        log_dispense_event(GPIO_PIN_1, HALF_INTERVAL);
        ts.tv_sec = HALF_INTERVAL / 1000;
        ts.tv_nsec = (HALF_INTERVAL % 1000) * 1000000;
        nanosleep(&ts, NULL);

        gpiod_line_set_value(line1, 0);
        gpiod_line_set_value(line2, 1);
        log_dispense_event(GPIO_PIN_2, HALF_INTERVAL);
        ts.tv_sec = HALF_INTERVAL / 1000;
        ts.tv_nsec = (HALF_INTERVAL % 1000) * 1000000;
        nanosleep(&ts, NULL);

        gpiod_line_set_value(line2, 0);
    }

    return 0;
}

