#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY 50

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for touch sensor\n");
        goto cleanup;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay\n");
        goto cleanup;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor for touch sensor\n");
        goto cleanup;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
            if (gpioWrite(RELAY_PIN, 1) < 0) {
                fprintf(stderr, "Failed to toggle relay\n");
            }
            usleep(DEBOUNCE_DELAY * 1000); // Convert ms to us
        } else {
            if (gpioWrite(RELAY_PIN, 0) < 0) {
                fprintf(stderr, "Failed to toggle relay\n");
            }
            usleep(DEBOUNCE_DELAY * 1000); // Convert ms to us
        }
    }

cleanup:
    gpioTerminate();
    return EXIT_SUCCESS;
}

