#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

#define ALSA_DEVICE "default"
#define ALSA_RATE 8000
#define ALSA_FORMAT SND_PCM_FORMAT_S16_LE
#define ALSA_CHANNELS 1
#define ALSA_PERIOD_SIZE 1024
#define ALSA_BUFFER_TIME 10 // 10 ms
#define ALSA_BUFFER_TIME_US (ALSA_BUFFER_TIME * 1000)
#define ALSA_AVAILABLE 1

#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27

#define DEFAULT_SENSITIVITY 1.0

static snd_pcm_t *alsa_handle = NULL;
static float sensitivity = DEFAULT_SENSITIVITY;

void cleanup(int signum) {
    if (alsa_handle) {
        snd_pcm_drain(alsa_handle);
        snd_pcm_close(alsa_handle);
        alsa_handle = NULL;
    }
    if (pigpio_connected()) {
        pigpio_stop();
    }
    exit(signum);
}

void handle_signal(int signum) {
    cleanup(signum);
}

void setup_alsa() {
    int err;
    snd_pcm_hw_params_t *hw_params;
    snd_pcm_sw_params_t *sw_params;

    if ((err = snd_pcm_open(&alsa_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Failed to open ALSA device: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_malloc(&hw_params)) < 0) {
        fprintf(stderr, "Failed to allocate hardware parameters: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_sw_params_malloc(&sw_params)) < 0) {
        fprintf(stderr, "Failed to allocate software parameters: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_any(alsa_handle, hw_params)) < 0) {
        fprintf(stderr, "Failed to initialize hardware parameters: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_set_access(alsa_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Failed to set access: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_set_format(alsa_handle, hw_params, ALSA_FORMAT)) < 0) {
        fprintf(stderr, "Failed to set format: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_set_channels(alsa_handle, hw_params, ALSA_CHANNELS)) < 0) {
        fprintf(stderr, "Failed to set channels: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_set_rate_near(alsa_handle, hw_params, &ALSA_RATE, NULL)) < 0) {
        fprintf(stderr, "Failed to set rate: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params(alsa_handle, hw_params)) < 0) {
        fprintf(stderr, "Failed to set hardware parameters: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_sw_params_current(alsa_handle, sw_params)) < 0) {
        fprintf(stderr, "Failed to get software parameters: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_sw_params_set_start_threshold(alsa_handle, sw_params, ALSA_BUFFER_TIME_US)) < 0) {
        fprintf(stderr, "Failed to set start threshold: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_sw_params(alsa_handle, sw_params)) < 0) {
        fprintf(stderr, "Failed to set software parameters: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_prepare(alsa_handle)) < 0) {
        fprintf(stderr, "Failed to prepare ALSA handle: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_sw_params_set_avail_min(alsa_handle, sw_params, ALSA_PERIOD_SIZE)) < 0) {
        fprintf(stderr, "Failed to set available minimum: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_sw_params(alsa_handle, sw_params)) < 0) {
        fprintf(stderr, "Failed to set software parameters: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_prepare(alsa_handle)) < 0) {
        fprintf(stderr, "Failed to prepare ALSA handle: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    printf("ALSA initialized successfully.\n");
}

void setup_pigpio() {
    if (pigpio_connected() == 0) {
        if (gpioInitialise() < 0) {
            fprintf(stderr, "Failed to initialize pigpio.\n");
            exit(EXIT_FAILURE);
        }
        printf("pigpio initialized successfully.\n");
    }
}

void setup_signals() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void compute_rms(short *buffer, int frames) {
    double sum = 0.0;
    for (int i = 0; i < frames; i++) {
        sum += buffer[i] * buffer[i];
    }
    double rms = sqrt(sum / frames);
    double scaled_rms = rms * sensitivity;
    int r = (int)(255 * scaled_rms);
    int g = (int)(255 * (1.0 - scaled_rms));
    int b = 0;

    if (r > 255) r = 255;
    if (g > 255) g = 255;
    if (b > 255) b = 255;

    printf("RMS: %f, RGB: (%d, %d, %d)\n", rms, r, g, b);

    pigpio_set_PWM_dutycycle(GPIO_RED, r);
    pigpio_set_PWM_dutycycle(GPIO_GREEN, g);
    pigpio_set_PWM_dutycycle(GPIO_BLUE, b);
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0.0) {
            fprintf(stderr, "Invalid sensitivity value.\n");
            exit(EXIT_FAILURE);
        }
    }

    setup_signals();

    if (ALSA_AVAILABLE) {
        setup_alsa();
    } else {
        printf("ALSA not available, simulating audio input.\n");
    }

    setup_pigpio();

    short buffer[ALSA_PERIOD_SIZE];
    int frames_read;

    while (1) {
        if (ALSA_AVAILABLE) {
            if ((frames_read = snd_pcm_readi(alsa_handle, buffer, ALSA_PERIOD_SIZE)) < 0) {
                if (frames_read == -EPIPE) {
                    printf("Buffer overrun (EPIPE), recovering...\n");
                    snd_pcm_prepare(alsa_handle);
                } else if (frames_read == -ESTRPIPE) {
                    printf("Suspended state (ESTRPIPE), resuming...\n");
                    snd_pcm_resume(alsa_handle);
                } else {
                    fprintf(stderr, "Failed to read from ALSA: %s\n", snd_strerror(frames_read));
                    exit(EXIT_FAILURE);
                }
            } else {
                compute_rms(buffer, frames_read);
            }
        } else {
            // Simulate audio input with a sine wave
            double t = 0.0;
            for (int i = 0; i < ALSA_PERIOD_SIZE; i++) {
                buffer[i] = (short)(32767 * sin(2 * M_PI * 1000 * t));
                t += 1.0 / ALSA_RATE;
            }
            compute_rms(buffer, ALSA_PERIOD_SIZE);
        }

        usleep(ALSA_BUFFER_TIME_US);
    }

    cleanup(0);
    return 0;
}

