    uint8_t value = TCS34725_WTIME_154MS;
    if (write(i2c_fd, &command, 1) != 1 || write(i2c_fd, &value, 1) != 1) {
        perror("Failed to set integration time");
        close(i2c_fd);
        return 1;
    }

    csv_file = fopen("color_data.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    fprintf(csv_file, "Timestamp,C,R,G,B\n");

    while (1) {
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        int c = read_sensor_data();
        int r = read_sensor_data();

        if (c < 0 || r < 0) {
            fprintf(csv_file, "%ld,0,0,0,0\n", now);
        } else {
            fprintf(csv_file, "%ld,%d,%d,0,0\n", now, c, r);
        }

        usleep(500000);
    }

    fclose(csv_file);
    close(i2c_fd);

    return 0;
}

