#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>

#define RELAY1_PIN 11
#define RELAY2_PIN 13
#define RELAY3_PIN 15
#define RELAY4_PIN 17

#define SUNRISE_DURATION 3600 // 1 hour in seconds
#define DAYTIME_DURATION 21600 // 6 hours in seconds
#define SUNSET_DURATION 3600 // 1 hour in seconds
#define NIGHTTIME_DURATION 51840 // 14.4 hours in seconds

#define MAX_DUTY_CYCLE 100

static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];

void handle_signal(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_request_release(lines[i]);
    }
    gpiod_chip_put(chip);
    exit(signum);
}

void simulate_sunrise_and_sunset() {
    int duty_cycle = 0;
    int current_time = 0;

    while (1) {
        // Sunrise phase
        for (duty_cycle = 0; duty_cycle <= MAX_DUTY_CYCLE; duty_cycle++) {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(lines[i], !duty_cycle);
            }
            usleep(1000000 / 60); // 60 Hz
            current_time += 1000000 / 60;
            if (current_time >= SUNRISE_DURATION) {
                break;
            }
        }

        // Daytime phase
        for (int i = 0; i < 4; i++) {
            gpiod_line_set_value(lines[i], 0);
        }
        sleep(DAYTIME_DURATION / 1000);
        current_time += DAYTIME_DURATION;

        // Sunset phase
        for (duty_cycle = MAX_DUTY_CYCLE; duty_cycle >= 0; duty_cycle--) {
            for (int i = 0; i < 4; i++) {
                gpiod_line_set_value(lines[i], !duty_cycle);
            }
            usleep(1000000 / 60); // 60 Hz
            current_time += 1000000 / 60;
            if (current_time >= SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION) {
                break;
            }
        }

        // Nighttime phase
        for (int i = 0; i < 4; i++) {
            gpiod_line_set_value(lines[i], 1);
        }
        sleep(NIGHTTIME_DURATION / 1000);
        current_time += NIGHTTIME_DURATION;
    }
}

int main() {
    struct gpiod_line_request req;
    struct gpiod_line_consumer consumer;

    chip = gpiod_chip_open_by_name("gpio");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    memset(&req, 0, sizeof(req));
    memset(&consumer, 0, sizeof(consumer));

    for (int i = 0; i < 4; i++) {
        req.consumer = &consumer;
        req.consumer_name = "SunriseSunset";
        req.flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        req.line_name = gpiod_line_name(chip, i + 11);

        lines[i] = gpiod_line_request(chip, &req);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line %d\n", i + 11);
            for (int j = 0; j < i; j++) {
                gpiod_line_request_release(lines[j]);
            }
            gpiod_chip_put(chip);
            return 1;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    simulate_sunrise_and_sunset();

    return 0;
}

