#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define GPIO_PIN 17
#define DEBOUNCE_INTERVAL 200 // in milliseconds
#define VIDEO_CAPTURE_DURATION 5 // in seconds
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static struct gpiod_line *sensor_line;
static int log_fd;

void handle_sigint(int signum) {
    if (sensor_line) {
        gpiod_line_free(sensor_line);
        sensor_line = NULL;
    }
    if (log_fd != -1) {
        close(log_fd);
        log_fd = -1;
    }
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct timespec last_trigger_time = {0, 0};
    char filename[20];
    char command[100];

    // Initialize signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize GPIO chip
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO line
    memset(&request, 0, sizeof(request));
    request.consumer = "motion_detector";
    request.consumer_user = "motion_detector";
    request.request = GPIOD_LINE_REQUEST_ACTIVE_LOW;
    request.flags = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    request.line.consumer_gpios = 1;
    request.line.gpios = &GPIO_PIN;

    if (gpiod_line_request_by_handle(chip, &request) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }
    sensor_line = request.line.line;

    while (1) {
        int value;
        struct timespec current_time;

        // Read sensor value
        if (gpiod_line_get_value(sensor_line, &value) < 0) {
            perror("Failed to read sensor value");
            continue;
        }

        // Check for motion event
        if (value == 0) {
            clock_gettime(CLOCK_REALTIME, &current_time);
            if (current_time.tv_sec - last_trigger_time.tv_sec >= DEBOUNCE_INTERVAL / 1000) {
                // Log motion event
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&current_time.tv_sec));
                if (write(log_fd, timestamp, strlen(timestamp)) < 0) {
                    perror("Failed to write to log file");
                } else {
                    printf("Motion detected at %s\n", timestamp);
                }

                // Start video capture
                time_t now = time(NULL);
                struct tm *now_tm = localtime(&now);
                strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", now_tm);
                sprintf(command, "raspivid -o %s%s -t %d", VIDEO_DIR, filename, VIDEO_CAPTURE_DURATION * 1000);
                if (system(command) != 0) {
                    perror("Failed to execute raspivid");
                } else {
                    printf("Video capture saved as %s%s\n", VIDEO_DIR, filename);
                }

                last_trigger_time = current_time;
            }
        }

        // Sleep for a short period
        usleep(100000); // 100 ms
    }

    // Cleanup
    if (sensor_line) {
        gpiod_line_free(sensor_line);
        sensor_line = NULL;
    }
    if (log_fd != -1) {
        close(log_fd);
        log_fd = -1;
    }
    gpiod_chip_close(chip);

    return 0;
}

