#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDR 0x68
#define GYRO_REG_CONFIG 0x1A
#define GYRO_REG_TEMP 0x41
#define GYRO_REG_XOUT_H 0x3B
#define GYRO_REG_YOUT_H 0x3D
#define GYRO_REG_ZOUT_H 0x3F

#define MAX_RETRIES 3

int i2c_fd;
FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_gyro_data(int *x, int *y, int *z) {
    char buffer[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read(i2c_fd, buffer, 3) != 3) {
            retries++;
            continue;
        }

        *x = (buffer[0] << 8) | buffer[1];
        *y = (buffer[1] << 8) | buffer[2];
        *z = (buffer[2] << 8) | buffer[0];

        return 0;
    }

    return -1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to acquire bus access/talk to slave");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long long timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        int x, y, z;
        if (read_gyro_data(&x, &y, &z) == -1) {
            fprintf(stderr, "Failed to read gyro data, retrying...\n");
            continue;
        }

        fprintf(log_file, "%lld,%d,%d,%d\n", timestamp, x, y, z);

        usleep(10000); // 10 ms sleep
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

