#include <libgpiod.h>

#define GPIO_ZONE_1 4
#define GPIO_ZONE_2 17
#define GPIO_ZONE_3 27
#define GPIO_ZONE_4 22

#define LOG_FILE "irrigation_log.txt"

gpiod_chip *chip;
gpiod_line *lines[4];

void handle_signal(int signum) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], 1);
    }
    fclose(stdout);
    gpiod_chip_put(chip);
    exit(signum);
}

int main() {
    signal(SIGINT, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_put(chip);
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_line_request(chip, i + GPIO_ZONE_1, "Zone %d Relay", GPIOD_LINE_DIRECTION_OUTPUT, 0);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request GPIO line for Zone %d\n", i + 1);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            fclose(log_file);
            gpiod_chip_put(chip);
            return 1;
        }
    }

    srand(time(NULL));

    while (1) {
        int moisture_value = rand() % 100;
        fprintf(log_file, "Moisture: %d\n", moisture_value);

        for (int i = 0; i < 4; i++) {
            int relay_state = (moisture_value < 30) ? 0 : 1;
            gpiod_line_set_value(lines[i], relay_state);
            fprintf(log_file, "Zone %d Relay: %s\n", i + 1, relay_state ? "OFF" : "ON");
        }

        fprintf(log_file, "Timestamp: %s\n", ctime(&time(NULL)));
        fprintf(log_file, "\n");

        fflush(log_file);
        usleep(5000000); // Sleep for 5 seconds
    }

    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    fclose(log_file);
    gpiod_chip_put(chip);

    return 0;
}

