#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_ADDR 0x53
#define FREE_FALL_THRESHOLD 0.2
#define FREE_FALL_DURATION 0.5
#define ALARM_GPIO 27
#define LOG_FILE "freefall.log"

static struct gpiod_line *alarm_line;
static FILE *log_file;

void handle_sigint(int signum) {
    gpiod_line_set_value(alarm_line, 0);
    gpiod_line_free(alarm_line);
    fclose(log_file);
    exit(0);
}

int read_accelerometer() {
    int x, y, z;
    int result = i2c_smbus_read_byte_data(I2C_ADDR, 0x32);
    if (result < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    result = i2c_smbus_read_byte_data(I2C_ADDR, 0x34);
    if (result < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    x = (result & 0x0F) << 8;
    result = i2c_smbus_read_byte_data(I2C_ADDR, 0x35);
    if (result < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    x |= result;

    result = i2c_smbus_read_byte_data(I2C_ADDR, 0x36);
    if (result < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    y = (result & 0x0F) << 8;
    result = i2c_smbus_read_byte_data(I2C_ADDR, 0x37);
    if (result < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    y |= result;

    result = i2c_smbus_read_byte_data(I2C_ADDR, 0x38);
    if (result < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    z = (result & 0x0F) << 8;
    result = i2c_smbus_read_byte_data(I2C_ADDR, 0x39);
    if (result < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    z |= result;

    // Convert raw data to g
    x = (x * 0.00390625);
    y = (y * 0.00390625);
    z = (z * 0.00390625);

    return (abs(x) < FREE_FALL_THRESHOLD && abs(y) < FREE_FALL_THRESHOLD && abs(z) < FREE_FALL_THRESHOLD);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpiod_chip_open("/dev/gpiochip0", &alarm_line) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request(alarm_line, ALARM_GPIO, "Alarm", GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    if (gpiod_line_set_value(alarm_line, 0) < 0) {
        perror("Failed to set GPIO line value");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        if (read_accelerometer()) {
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %.3f, %.3f, %.3f\n",
                    timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                    timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
                    x, y, z);

            gpiod_line_set_value(alarm_line, 1);
            sleep(5);
            gpiod_line_set_value(alarm_line, 0);
        }

        sleep(1);
    }

    fclose(log_file);
    gpiod_line_free(alarm_line);
    return 0;
}

