#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE_US 23200
#define TIMEOUT_US 100000
#define FILE_NAME "distance_log.txt"

struct measurement {
    uint32_t timestamp_ns;
    uint32_t distance_cm;
};

struct measurement_data {
    struct measurement measurement;
    pthread_mutex_t mutex;
};

static struct gpiod_line *trig_line;
static struct gpiod_line *echo_line;
static struct measurement_data measurement_data;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void handle_sigint(int signum) {
    running = 0;
}

void echo_rising_edge_callback(struct gpiod_line *line, void *data) {
    struct measurement_data *measurement_data = data;
    pthread_mutex_lock(&measurement_data->mutex);
    measurement_data->measurement.timestamp_ns = gpiod_get_counter(trig_line);
    pthread_mutex_unlock(&measurement_data->mutex);
}

