#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define LIS3DH_I2C_ADDR 0x18
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Z_L 0x2C

#define FREE_FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5

#define BUZZER_GPIO 17

static int i2c_fd = -1;
static int retry_count = 0;

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int read_accelerometer(int *x, int *y, int *z) {
    int retries = 0;
    int result = -1;

    while (retries < 3) {
        if (read(i2c_fd, x, 1) != 1 ||
            read(i2c_fd, y, 1) != 1 ||
            read(i2c_fd, z, 1) != 1) {
            retries++;
            continue;
        }

        *x = *x | (*y << 8);
        *y = *y | (*z << 8);
        *z = *z | (*x << 8);

        result = 0;
        break;
    }

    return result;
}

double calculate_magnitude(int x, int y, int z) {
    return sqrt(x * x + y * y + z * z);
}

int main(int argc, char *argv[]) {
    int x, y, z;
    double magnitude;
    int free_fall_threshold = FREE_FALL_THRESHOLD;
    int impact_threshold = IMPACT_THRESHOLD;

    if (argc > 1) {
        free_fall_threshold = atof(argv[1]);
    }

    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    signal(SIGINT, handle_sigint);

    char i2c_device[10];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", 1);

    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LIS3DH_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(1);
    }

    while (1) {
        if (read_accelerometer(&x, &y, &z) != 0) {
            perror("Failed to read accelerometer data");
            continue;
        }

        magnitude = calculate_magnitude(x, y, z);

        if (magnitude < free_fall_threshold) {
            printf("Free fall detected (magnitude: %.2f g)\n", magnitude);
        } else if (magnitude > impact_threshold) {
            printf("Impact detected (magnitude: %.2f g)\n", magnitude);

            // Activate buzzer for 1 second
            int fd = open("/sys/class/gpio/gpio%d/value", O_WRONLY);
            if (fd >= 0) {
                write(fd, "1", 1);
                sleep(1);
                write(fd, "0", 1);
                close(fd);
            } else {
                perror("Failed to open buzzer GPIO");
            }
        }

        usleep(100000); // Sleep for 100ms
    }

    return 0;
}

