#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

#define STEP_DELAY 1000 // 1000 microseconds
#define STEPS_PER_REV 2048
#define GEAR_RATIO 64
#define SQUARE_SIDE 50 // 50 mm

void stop_motors() {
    gpioWrite(MOTOR1_IN1, LOW);
    gpioWrite(MOTOR1_IN2, LOW);
    gpioWrite(MOTOR1_IN3, LOW);
    gpioWrite(MOTOR1_IN4, LOW);

    gpioWrite(MOTOR2_IN1, LOW);
    gpioWrite(MOTOR2_IN2, LOW);
    gpioWrite(MOTOR2_IN3, LOW);
    gpioWrite(MOTOR2_IN4, LOW);
}

void handle_sigint(int signum) {
    stop_motors();
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(MOTOR1_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN4, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    int steps_per_side = (int)((SQUARE_SIDE * STEPS_PER_REV) / (2 * M_PI * GEAR_RATIO));

    for (int i = 0; i < 4; i++) {
        if (i == 0) {
            gpioWrite(MOTOR1_IN1, HIGH);
            gpioWrite(MOTOR1_IN2, LOW);
            gpioWrite(MOTOR2_IN1, HIGH);
            gpioWrite(MOTOR2_IN2, LOW);
        } else if (i == 1) {
            gpioWrite(MOTOR1_IN2, HIGH);
            gpioWrite(MOTOR1_IN1, LOW);
            gpioWrite(MOTOR2_IN2, HIGH);
            gpioWrite(MOTOR2_IN1, LOW);
        } else if (i == 2) {
            gpioWrite(MOTOR1_IN3, HIGH);
            gpioWrite(MOTOR1_IN4, LOW);
            gpioWrite(MOTOR2_IN3, HIGH);
            gpioWrite(MOTOR2_IN4, LOW);
        } else if (i == 3) {
            gpioWrite(MOTOR1_IN4, HIGH);
            gpioWrite(MOTOR1_IN3, LOW);
            gpioWrite(MOTOR2_IN4, HIGH);
            gpioWrite(MOTOR2_IN3, LOW);
        }

        for (int j = 0; j < steps_per_side; j++) {
            gpioDelay(STEP_DELAY);
        }
    }

    stop_motors();
    gpioTerminate();

    return 0;
}

