#define LIS3DH_I2C_ADDR 0x18 // Default I2C address
#define LIS3DH_REG_CTRL_REG1 0x20
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_RANGE_2G 0x00
#define LIS3DH_ODR_100HZ 0x07
#define LIS3DH_DATA_RATE_100HZ 0x07
#define LIS3DH_HIGH_RES_MODE 0x00
#define LIS3DH_LEFT_JUSTIFIED 0x00
#define LIS3DH_CTRL_REG1_CONFIG (LIS3DH_RANGE_2G | LIS3DH_ODR_100HZ | LIS3DH_DATA_RATE_100HZ | LIS3DH_HIGH_RES_MODE | LIS3DH_LEFT_JUSTIFIED)

#define DEFAULT_THRESHOLD 2.0
#define LOG_FILE "/var/log/high_acceleration.log"

static int i2c_fd = -1;
static double threshold = DEFAULT_THRESHOLD;

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int configure_sensor(int i2c_addr) {
    int result = 0;

    if (i2c_fd == -1) {
        return -1;
    }

    result = i2c_smbus_write_byte_data(i2c_fd, LIS3DH_REG_CTRL_REG1, LIS3DH_CTRL_REG1_CONFIG);
    if (result != 0) {
        fprintf(stderr, "Failed to configure sensor.\n");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_accelerometer(int i2c_addr) {
    int result = 0;
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;
    int16_t x, y, z;

    if (i2c_fd == -1) {
        return -1;
    }

    result = i2c_smbus_read_byte_data(i2c_fd, LIS3DH_REG_OUT_X_L);
    if (result != 0) {
        return -1;
    }
    x_l = result;

    result = i2c_smbus_read_byte_data(i2c_fd, LIS3DH_REG_OUT_X_H);
    if (result != 0) {
        return -1;
    }
    x_h = result;

    result = i2c_smbus_read_byte_data(i2c_fd, LIS3DH_REG_OUT_Y_L);
