#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define BUFFER_SIZE 5
#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

gpiod_chip *chip;
gpiod_line *left_sensor, *center_sensor, *right_sensor, *alert_pin;

int buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void handle_signal(int signum) {
    if (left_sensor) gpiod_line_free(left_sensor);
    if (center_sensor) gpiod_line_free(center_sensor);
    if (right_sensor) gpiod_line_free(right_sensor);
    if (alert_pin) gpiod_line_free(alert_pin);
    gpiod_chip_put(chip);
    exit(signum);
}

void read_sensors() {
    int left_value = gpiod_line_get_value(left_sensor);
    int center_value = gpiod_line_get_value(center_sensor);
    int right_value = gpiod_line_get_value(right_sensor);

    buffer[buffer_head] = left_value;
    buffer[buffer_head + 1] = center_value;
    buffer[buffer_head + 2] = right_value;

    printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

    buffer_head = (buffer_head + 3) % BUFFER_SIZE;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    left_sensor = gpiod_line_request(chip, LEFT_SENSOR_PIN, "left_sensor", 0, 0);
    if (!left_sensor) {
        fprintf(stderr, "Failed to request left sensor line\n");
        goto error_exit;
    }

    center_sensor = gpiod_line_request(chip, CENTER_SENSOR_PIN, "center_sensor", 0, 0);
    if (!center_sensor) {
        fprintf(stderr, "Failed to request center sensor line\n");
        goto error_exit;
    }

    right_sensor = gpiod_line_request(chip, RIGHT_SENSOR_PIN, "right_sensor", 0, 0);
    if (!right_sensor) {
        fprintf(stderr, "Failed to request right sensor line\n");
        goto error_exit;
    }

    alert_pin = gpiod_line_request(chip, ALERT_PIN, "alert_pin", 0, 0);
    if (!alert_pin) {
        fprintf(stderr, "Failed to request alert pin line\n");
        goto error_exit;
    }

    while (1) {
        read_sensors();

        int center_line_count = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (buffer[buffer_tail + i] == 1) {
                center_line_count++;
            }
        }

        if (center_line_count == BUFFER_SIZE) {
            gpiod_line_set_value(alert_pin, 1);
            sleep(2);
            gpiod_line_set_value(alert_pin, 0);
        } else {
            if (buffer[buffer_tail] == 0) {
                // Move forward
                move_forward();
            } else if (buffer[buffer_tail + 1] == 0) {
                // Turn left
                turn_left();
            } else if (buffer[buffer_tail + 2] == 0) {
                // Turn right
                turn_right();
            } else {
                // Stop
                stop();
            }
        }

        buffer_tail = (buffer_tail + 3) % BUFFER_SIZE;
        usleep(10000); // 10 ms delay
    }

error_exit:
    if (left_sensor) gpiod_line_free(left_sensor);
    if (center_sensor) gpiod_line_free(center_sensor);
    if (right_sensor) gpiod_line_free(right_sensor);
    if (alert_pin) gpiod_line_free(alert_pin);
    gpiod_chip_put(chip);

    return 0;
}

