#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define GPIO_PIN 17
#define THRESHOLD 5.0
#define POLL_ATTEMPTS 50
#define POLL_INTERVAL 100 // in milliseconds

static struct gpiod_line *gpiod_line;
static struct i2c_client *i2c_client;

void handle_sigint(int signum) {
    if (gpiod_line) {
        gpiod_line_set_value(gpiod_line, 0);
        gpiod_line_free(gpiod_line);
    }
    if (i2c_client) {
        i2c_client_close(i2c_client);
    }
    fprintf(stderr, "Shutdown signal received. Exiting.\n");
    exit(0);
}

int main() {
    struct i2c_client *client;
    struct gpiod_line *line;
    int ret;
    int poll_count = 0;
    int relay_state = 0;
    double magnetic_field;
    char timestamp[20];

    // Initialize signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize I2C client
    client = i2c_client_new(I2C_BUS, I2C_ADDR);
    if (!client) {
        fprintf(stderr, "Failed to initialize I2C client.\n");
        exit(1);
    }

    // Initialize GPIO line
    line = gpiod_line_request(GPIO_PIN, "Relay", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line.\n");
        i2c_client_close(client);
        exit(1);
    }

    // Open I2C client
    ret = i2c_client_open(client);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C client.\n");
        gpiod_line_free(line);
        exit(1);
    }

    while (1) {
        // Read magnetic field
        ret = i2c_smbus_read_byte_data(client, 0x00); // Assuming the sensor's read register is 0x00
        if (ret < 0) {
            fprintf(stderr, "Failed to read magnetic field. Retrying...\n");
            gpiod_line_set_value(line, 0);
            continue;
        }

        // Convert raw data to magnetic field (example conversion, replace with actual sensor conversion)
        magnetic_field = (double)ret * 0.1; // Example conversion, replace with actual sensor conversion

        // Log magnetic field reading
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(stdout, "%s: Magnetic field = %.2f mT\n", timestamp, magnetic_field);

        // Check if relay should be activated
        if (magnetic_field > THRESHOLD) {
            if (relay_state == 0) {
                gpiod_line_set_value(line, 1);
                relay_state = 1;
                fprintf(stdout, "%s: Relay activated (field > %.2f mT)\n", timestamp, THRESHOLD);
            }
        } else {
            if (relay_state == 1) {
                gpiod_line_set_value(line, 0);
                relay_state = 0;
                fprintf(stdout, "%s: Relay deactivated (field <= %.2f mT)\n", timestamp, THRESHOLD);
            }
        }

        // Poll for register clear
        while (poll_count < POLL_ATTEMPTS) {
            ret = i2c_smbus_read_byte_data(client, 0x00); // Assuming the sensor's read register is 0x00
            if (ret < 0) {
                fprintf(stderr, "Failed to read magnetic field. Retrying...\n");
                gpiod_line_set_value(line, 0);
                continue;
            }

            if (ret == 0) {
                break;
            }

            poll_count++;
            usleep(100000); // Sleep for 100 ms
        }

        if (poll_count == POLL_ATTEMPTS) {
            fprintf(stderr, "%s: Timeout error while polling register clear. Skipping cycle.\n", timestamp);
        }

        poll_count = 0;
        usleep(100000); // Sleep for 100 ms
    }

    // Cleanup
    if (gpiod_line) {
        gpiod_line_set_value(gpiod_line, 0);
        gpiod_line_free(gpiod_line);
    }
    if (i2c_client) {
        i2c_client_close(i2c_client);
    }

    return 0;
}

