#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <libgpiod.h>

#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

gpiod_chip *chip;
gpiod_line *line;

void handle_signal(int signum) {
    gpiod_line_set_value(line, 0); // Turn off the relay
    gpiod_line_free(line);
    gpiod_chip_put(chip);
    exit(signum);
}

void log_event(const char *event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    fprintf(log_file, "%s - %s\n", asctime(timeinfo), event);
    fclose(log_file);
}

int main() {
    int sockfd, newsockfd, clientlen;
    struct sockaddr_in serv_addr, cli_addr;
    char buffer[BUFFER_SIZE];
    int n;

    // Initialize GPIO
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request_by_name(chip, "18", "relay", GPIOD_LINE_DIRECTION_OUTPUT, 0, &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        gpiod_line_free(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Bind socket
    bzero((char *) &serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("Failed to bind socket");
        close(sockfd);
        gpiod_line_free(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Listen for connections
    listen(sockfd, 5);

    while (1) {
        clientlen = sizeof(cli_addr);
        newsockfd = accept(sockfd, (struct sockaddr *) &cli_addr, &clientlen);
        if (newsockfd < 0) {
            perror("Failed to accept connection");
            close(sockfd);
            gpiod_line_free(line);
            gpiod_chip_put(chip);
            return 1;
        }

        n = read(newsockfd, buffer, BUFFER_SIZE - 1);
        if (n < 0) {
            perror("Failed to read from socket");
            close(newsockfd);
            close(sockfd);
            gpiod_line_free(line);
            gpiod_chip_put(chip);
            return 1;
        }

        buffer[n] = '\0';
        char *command = strtok(buffer, " \n");
        if (command == NULL) {
            log_event("Invalid command");
            continue;
        }

        if (strcasecmp(command, "ON") == 0) {
            gpiod_line_set_value(line, 1);
            log_event("Relay activated");
        } else if (strcasecmp(command, "OFF") == 0) {
            gpiod_line_set_value(line, 0);
            log_event("Relay deactivated");
        } else {
            log_event("Invalid command");
        }

        close(newsockfd);
    }

    // Clean up
    close(sockfd);
    gpiod_line_free(line);
    gpiod_chip_put(chip);

    return 0;
}

