#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x40
#define SENSOR2_ADDR 0x41
#define GPIO_PIN 18
#define GPIO_DIRECTION_OUT 0
#define GPIO_VALUE_HIGH 1
#define GPIO_VALUE_LOW 0
#define FLOW_RATE_THRESHOLD 5.0
#define POLL_INTERVAL 100 // 100 ms

static int i2c_fd1, i2c_fd2;
static struct gpiod_line *gpio_line;

void handle_signal(int signum) {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, GPIO_VALUE_LOW);
        gpiod_line_free(gpio_line);
    }

    if (i2c_fd1 >= 0) {
        close(i2c_fd1);
    }

    if (i2c_fd2 >= 0) {
        close(i2c_fd2);
    }

    printf("Shutdown triggered by signal %d\n", signum);
    exit(0);
}

int crc8(const unsigned char *data, size_t length) {
    int crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >> 1) ^ 0x07;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int i2c_fd, int sensor_addr) {
    unsigned char buffer[4];
    int bytes_read = read(i2c_fd, buffer, sizeof(buffer));
    if (bytes_read != sizeof(buffer)) {
        fprintf(stderr, "Error reading from sensor %d\n", sensor_addr);
        return -1;
    }

    int crc = crc8(buffer, 3);
    if (crc != buffer[3]) {
        fprintf(stderr, "CRC check failed for sensor %d\n", sensor_addr);
        return -1;
    }

    float flow_rate = (buffer[0] << 8) | buffer[1];
    flow_rate /= 100.0; // Convert to ml/min

    char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s %d: %.1f ml/min\n", timestamp, sensor_addr, flow_rate);
    fflush(stdout);

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd1 = open(I2C_BUS, O_RDWR);
    if (i2c_fd1 < 0) {
        perror("Failed to open I2C bus 1");
        return 1;
    }

    if (ioctl(i2c_fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        perror("Failed to set I2C address for sensor 1");
        close(i2c_fd1);
        return 1;
    }

    i2c_fd2 = open(I2C_BUS, O_RDWR);
    if (i2c_fd2 < 0) {
        perror("Failed to open I2C bus 1");
        close(i2c_fd1);
        return 1;
    }

    if (ioctl(i2c_fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        perror("Failed to set I2C address for sensor 2");
        close(i2c_fd1);
        close(i2c_fd2);
        return 1;
    }

    gpiod_line_consumer_t consumer = {
        .name = "Flow Sensor Relay",
        .consumer = "Flow Sensor Control",
    };

    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    gpiod_line_request_flags_t request_flags = {
        .direction = flags,
    };

    gpio_line = gpiod_line_request(GPIO_PIN, &consumer, &request_flags);
    if (!gpio_line) {
        perror("Failed to request GPIO line");
        close(i2c_fd1);
        close(i2c_fd2);
        return 1;
    }

    gpiod_line_set_value(gpio_line, GPIO_VALUE_LOW);

    while (1) {
        if (read_sensor(i2c_fd1, SENSOR1_ADDR) < 0 || read_sensor(i2c_fd2, SENSOR2_ADDR) < 0) {
            continue;
        }

        float flow_rate1, flow_rate2;
        read_sensor(i2c_fd1, SENSOR1_ADDR);
        read_sensor(i2c_fd2, SENSOR2_ADDR);

        if (flow_rate1 < FLOW_RATE_THRESHOLD || flow_rate2 < FLOW_RATE_THRESHOLD) {
            gpiod_line_set_value(gpio_line, GPIO_VALUE_HIGH);
        } else {
            gpiod_line_set_value(gpio_line, GPIO_VALUE_LOW);
        }

        usleep(POLL_INTERVAL * 1000); // Sleep for 100 ms
    }

    return 0;
}

