    gpiod_set_value(gpiod_get_line(GPIO_IN1), 0);
    gpiod_set_value(gpiod_get_line(GPIO_IN2), 0);

    // Cleanup
    gpiod_line_request_free(sensor_line);
    gpiod_line_request_free(ena_line);
    gpiod_line_request_free(in1_line);
    gpiod_line_request_free(in2_line);

    closelog();
    exit(signum == SIGINT ? 0 : 1);
}

int main() {
    struct gpiod_line *sensor_line, *ena_line, *in1_line, *in2_line;
    int ret;

    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "rain_window: Starting...");

    // Setup GPIO lines
    sensor_line = gpiod_line_request(GPIO_SENSOR, "sensor", GPIOD_LINE_DIRECTION_INPUT, 0);
    if (!sensor_line) {
        syslog(LOG_ERR, "rain_window: Failed to request sensor GPIO line.");
        return 1;
    }

    ena_line = gpiod_line_request(GPIO_ENA, "ena", GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!ena_line) {
        syslog(LOG_ERR, "rain_window: Failed to request ENA GPIO line.");
        return 1;
    }

    in1_line = gpiod_line_request(GPIO_IN1, "in1", GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!in1_line) {
        syslog(LOG_ERR, "rain_window: Failed to request IN1 GPIO line.");
        return 1;
    }

    in2_line = gpiod_line_request(GPIO_IN2, "in2", GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!in2_line) {
        syslog(LOG_ERR, "rain_window: Failed to request IN2 GPIO line.");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        int current_state = gpiod_get_value(sensor_line);

        if (current_state != sensor_state) {
            sensor_state = current_state;

            if (current_state == 0) { // Rising edge detected (dry to wet)
                dry_count = 0;

                syslog(LOG_INFO, "rain_window: Rain detected, starting motor.");

                // Start motor
                gpiod_set_value(ena_line, 1);
                gpiod_set_value(in1_line, 1);
                gpiod_set_value(in2_line, 0);

                syslog(LOG_INFO, "rain_window: Motor started.");

                // Wait for 5 seconds
                usleep(5000000);

                // Stop motor
                gpiod_set_value(ena_line, 0);
                gpiod_set_value(in1_line, 0);
                gpiod_set_value(in2_line, 0);

                syslog(LOG_INFO, "rain_window: Motor stopped.");
            } else { // Falling edge detected (wet to dry)
                dry_count++;

                if (dry_count >= 3) {
                    syslog(LOG_INFO, "rain_window: Sensor dry for 3 consecutive polls, resetting dry_count.");
                    dry_count = 0;
                }
            }
        }

        // Poll every 200ms
        usleep(200000);
    }

    // Cleanup and exit
    handle_signal(0);

    return 0;
}
