#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            if (gpioServo(SERVO_PIN, 2000) < 0) {
                fprintf(stderr, "Failed to lock servo\n");
                return EXIT_FAILURE;
            }
            printf("Locking...\n");
            while (gpioRead(LOCK_BUTTON_PIN) == 0) {
                usleep(10000); // Debounce delay
            }
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            if (gpioServo(SERVO_PIN, 1000) < 0) {
                fprintf(stderr, "Failed to unlock servo\n");
                return EXIT_FAILURE;
            }
            printf("Unlocking...\n");
            while (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                usleep(10000); // Debounce delay
            }
        }

        usleep(10000); // Small sleep to keep CPU usage low
    }

    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Failed to stop servo\n");
        return EXIT_FAILURE;
    }

    printf("Shutting down...\n");
    gpioTerminate();

    return EXIT_SUCCESS;
}

