#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PIR 4
#define GPIO_LED 17
#define POLL_INTERVAL 100 // in milliseconds
#define LED_ON_TIME 60 // in seconds

static gpiod_chip *chip;
static gpiod_line *pir_line, *led_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (led_line) {
        gpiod_line_request_free(led_line);
        led_line = NULL;
    }
    if (pir_line) {
        gpiod_line_request_free(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 ||
        sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    if ((pir_line = gpiod_line_request_by_name(chip, "gpio4", "pir_sensor", 0)) == NULL) {
        perror("gpiod_line_request_by_name");
        goto cleanup_chip;
    }

    if ((led_line = gpiod_line_request_by_name(chip, "gpio17", "led_floodlight", 0)) == NULL) {
        perror("gpiod_line_request_by_name");
        goto cleanup_pir;
    }

    if (gpiod_line_direction_set(pir_line, GPIO_LINE_DIRECTION_INPUT) < 0) {
        perror("gpiod_line_direction_set");
        goto cleanup_led;
    }

    if (gpiod_line_direction_set(led_line, GPIO_LINE_DIRECTION_OUTPUT) < 0) {
        perror("gpiod_line_direction_set");
        goto cleanup_pir;
    }

    if ((log_file = fopen("security_log.txt", "a")) == NULL) {
        perror("fopen");
        goto cleanup_led;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&ts.tv_sec));

        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            perror("gpiod_line_get_value");
            goto cleanup_file;
        }

        if (pir_value == 1) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup_file;
            }

            struct timespec start_time, end_time;
            clock_gettime(CLOCK_REALTIME, &start_time);

            sleep(LED_ON_TIME);

            clock_gettime(CLOCK_REALTIME, &end_time);

            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup_file;
            }

            double duration = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

            char duration_str[32];
            sprintf(duration_str, "%.2f", duration);

            if (fprintf(log_file, "%s: LED activated\n", timestamp) < 0 ||
                fprintf(log_file, "%s: LED deactivated (duration: %s seconds)\n", timestamp, duration_str) < 0) {
                perror("fprintf");
                goto cleanup_file;
            }

            if (fclose(log_file) == EOF) {
                perror("fclose");
                goto cleanup_file;
            }

            log_file = fopen("security_log.txt", "a");
            if (log_file == NULL) {
                perror("fopen");
                goto cleanup_file;
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

cleanup_file:
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

cleanup_led:
    if (led_line) {
        gpiod_line_request_free(led_line);
        led_line = NULL;
    }

cleanup_pir:
    if (pir_line) {
        gpiod_line_request_free(pir_line);
        pir_line = NULL;
    }

cleanup_chip:
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }

    return 0;
}

