#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPR121_I2C_ADDR 0x5A
#define GPIO_PIN 17
#define DEBOUNCE_TIME 200

int relay_fd = -1;
int i2c_fd = -1;

void handle_signal(int signum) {
    if (relay_fd != -1) {
        printf("Turning off relay on signal %d\n", signum);
        if (write(relay_fd, "0", 1) < 0) {
            perror("Failed to turn off relay");
        }
        close(relay_fd);
        relay_fd = -1;
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(signum);
}

void init_relay() {
    char relay_path[32];
    sprintf(relay_path, "/sys/class/gpio/gpio%d/value", GPIO_PIN);

    relay_fd = open(relay_path, O_WRONLY);
    if (relay_fd < 0) {
        perror("Failed to open relay GPIO");
        exit(EXIT_FAILURE);
    }

    if (write(relay_fd, "0", 1) < 0) {
        perror("Failed to turn off relay");
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    char i2c_path[32];
    sprintf(i2c_path, "/dev/i2c-%d", 1);

    i2c_fd = open(i2c_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void mpr121_init() {
    uint8_t data[2];

    // Soft reset
    data[0] = 0x00;
    data[1] = 0x00;
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to perform soft reset");
        exit(EXIT_FAILURE);
    }

    // Baseline filtering configuration
    data[0] = 0x01;
    data[1] = 0x00; // MHD, NHD, NCL, FDL values as documented
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to configure baseline filtering");
        exit(EXIT_FAILURE);
    }

    // Debounce configuration
    data[0] = 0x02;
    data[1] = 0x00; // Debounce value as documented
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to configure debounce");
        exit(EXIT_FAILURE);
    }

    // FFI, SFI, CDT configuration
    data[0] = 0x03;
    data[1] = 0x00; // FFI, SFI, CDT values as documented
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to configure FFI, SFI, CDT");
        exit(EXIT_FAILURE);
    }

    // Auto-config range
    data[0] = 0x04;
    data[1] = 0x00; // Auto-config range as documented
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to configure auto-config range");
        exit(EXIT_FAILURE);
    }

    // Enable exactly 12 electrodes
    data[0] = 0x05;
    data[1] = 0x0F; // Enable electrodes 0-11
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to enable electrodes");
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_relay();
    init_i2c();
    mpr121_init();

    printf("MPR121 initialized and relay turned off.\n");

    while (1) {
        uint8_t data[2];
        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read from MPR121");
            exit(EXIT_FAILURE);
        }

        if ((data[0] & 0x01) != 0) { // Check for rising edge on electrode 0
            printf("Rising edge detected on electrode 0\n");
            usleep(DEBOUNCE_TIME * 1000); // Debounce
            if ((data[0] & 0x01) != 0) { // Check again to confirm
                printf("Toggling relay\n");
                if (write(relay_fd, "1", 1) < 0) {
                    perror("Failed to turn on relay");
                }
                usleep(DEBOUNCE_TIME * 1000); // Debounce
                if (write(relay_fd, "0", 1) < 0) {
                    perror("Failed to turn off relay");
                }
            }
        }
    }

    return 0;
}

