        exit(EXIT_FAILURE);
    }

    // FFI, SFI, CDT configuration
    data[0] = 0x03;
    data[1] = 0x00; // FFI, SFI, CDT values as documented
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to configure FFI, SFI, CDT");
        exit(EXIT_FAILURE);
    }

    // Auto-config range
    data[0] = 0x04;
    data[1] = 0x00; // Auto-config range as documented
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to configure auto-config range");
        exit(EXIT_FAILURE);
    }

    // Enable exactly 12 electrodes
    data[0] = 0x05;
    data[1] = 0x0F; // Enable electrodes 0-11
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to enable electrodes");
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_relay();
    init_i2c();
    mpr121_init();

    printf("MPR121 initialized and relay turned off.\n");

    while (1) {
        uint8_t data[2];
        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read from MPR121");
            exit(EXIT_FAILURE);
        }

        if ((data[0] & 0x01) != 0) { // Check for rising edge on electrode 0
            printf("Rising edge detected on electrode 0\n");
            usleep(DEBOUNCE_TIME * 1000); // Debounce
            if ((data[0] & 0x01) != 0) { // Check again to confirm
                printf("Toggling relay\n");
                if (write(relay_fd, "1", 1) < 0) {
                    perror("Failed to turn on relay");
                }
                usleep(DEBOUNCE_TIME * 1000); // Debounce
                if (write(relay_fd, "0", 1) < 0) {
                    perror("Failed to turn off relay");
                }
            }
        }
    }

    return 0;
}
