#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <time.h>
#include <libgpiod.h>
#include <stdarg.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "security.log"

static gpiod_chip *chip;
static gpiod_line *servo_line, *pir_line;
static int sockfd;

void log_event(const char *format, ...) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    va_list args;
    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    syslog(LOG_USER, "%s %s", asctime(timeinfo), buffer);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", asctime(timeinfo), buffer);
        fclose(log_file);
    } else {
        syslog(LOG_ERR, "Failed to open log file: %s", LOG_FILE);
    }
}

void handle_signal(int signum) {
    if (servo_line) {
        gpiod_line_request_free(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_request_free(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (sockfd > 0) {
        close(sockfd);
        sockfd = -1;
    }
    log_event("Received signal %d, shutting down gracefully.", signum);
    exit(signum == SIGINT ? 0 : 1);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void setup_gpiod() {
    int err;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_event("Failed to open GPIO chip: %s", gpiod_error_string(errno));
        exit(1);
    }

    servo_line = gpiod_line_request_by_name(chip, "gpio%d", SERVO_PIN, "servo", 0);
    if (!servo_line) {
        log_event("Failed to request servo line: %s", gpiod_error_string(errno));
        exit(1);
    }

    pir_line = gpiod_line_request_by_name(chip, "gpio%d", PIR_PIN, "pir", 0);
    if (!pir_line) {
        log_event("Failed to request PIR line: %s", gpiod_error_string(errno));
        exit(1);
    }

    err = gpiod_line_direction_set(servo_line, GPIO_LINE_DIRECTION_OUTPUT);
    if (err) {
        log_event("Failed to set servo line direction: %s", gpiod_error_string(err));
        exit(1);
    }

    err = gpiod_line_direction_set(pir_line, GPIO_LINE_DIRECTION_INPUT);
    if (err) {
        log_event("Failed to set PIR line direction: %s", gpiod_error_string(err));
        exit(1);
    }
}

void setup_socket() {
    struct sockaddr_in server_addr;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        log_event("Failed to create socket: %s", strerror(errno));
        exit(1);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        log_event("Failed to bind socket: %s", strerror(errno));
        exit(1);
    }

    if (listen(sockfd, 5) < 0) {
        log_event("Failed to listen on socket: %s", strerror(errno));
        exit(1);
    }
}

void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    while ((bytes_read = read(client_fd, buffer, BUFFER_SIZE - 1)) > 0) {
        buffer[bytes_read] = '\0';
        log_event("Received command: %s", buffer);

        if (strcmp(buffer, "PIR") == 0) {
            int pir_value = gpiod_line_get_value(pir_line);
            char response[10];
            sprintf(response, "PIR:%d", pir_value);
            write(client_fd, response, strlen(response));
            log_event("Sent response: %s", response);
        } else if (sscanf(buffer, "servo %d", &servo_line->value) == 1) {
            gpiod_line_set_value(servo_line, servo_line->value);
            log_event("Set servo angle to %d", servo_line->value);
        } else {
            log_event("Invalid command: %s", buffer);
        }
    }

    if (bytes_read < 0) {
        log_event("Error reading from client: %s", strerror(errno));
    }

    close(client_fd);
}

int main() {
    int client_fd;

    setup_signal_handlers();
    setup_gpiod();
    setup_socket();

    while (1) {
        client_fd = accept(sockfd, NULL, NULL);
        if (client_fd < 0) {
            log_event("Failed to accept connection: %s", strerror(errno));
            continue;
        }

        handle_client(client_fd);
    }

    return 0;
}

