#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libi2c-dev.h>

#define I2C_ADDR 0x23
#define RELAY_PIN 23
#define LOG_FILE "grow_log.txt"
#define DELAY_MS 120
#define SAMPLING_INTERVAL 2000

static i2c_client_t *i2c_client;
static FILE *log_file;

void handle_signal(int signum) {
    if (i2c_client) {
        i2c_close(i2c_client);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int read_lux() {
    uint8_t cmd[2] = {0x00, 0x01};
    uint8_t lux[2];
    int ret;

    ret = i2c_smbus_write_i2c_block_data(i2c_client, I2C_ADDR, 0x00, cmd, 2);
    if (ret < 0) {
        fprintf(stderr, "Error writing to BH1750 sensor: %s\n", strerror(errno));
        return -1;
    }

    usleep(DELAY_MS * 1000);

    ret = i2c_smbus_read_i2c_block_data(i2c_client, I2C_ADDR, 0x00, lux, 2);
    if (ret < 0) {
        fprintf(stderr, "Error reading from BH1750 sensor: %s\n", strerror(errno));
        return -1;
    }

    return (lux[0] << 8) | lux[1];
}

void control_relay(int lux) {
    int ret;

    ret = i2c_smbus_write_byte(i2c_client, I2C_ADDR, 0x01);
    if (ret < 0) {
        fprintf(stderr, "Error writing to relay: %s\n", strerror(errno));
        return;
    }

    if (lux < 150) {
        ret = i2c_smbus_write_byte(i2c_client, I2C_ADDR, 0x00);
        if (ret < 0) {
            fprintf(stderr, "Error writing to relay: %s\n", strerror(errno));
        }
    } else {
        ret = i2c_smbus_write_byte(i2c_client, I2C_ADDR, 0x01);
        if (ret < 0) {
            fprintf(stderr, "Error writing to relay: %s\n", strerror(errno));
        }
    }
}

int main() {
    struct timespec ts;
    int lux;

    setup_signal_handlers();

    i2c_client = i2c_open(1, 0);
    if (i2c_client < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2c_close(i2c_client);
        return 1;
    }

    while (1) {
        lux = read_lux();
        if (lux < 0) {
            continue;
        }

        ts.tv_sec = time(NULL);
        ts.tv_nsec = 0;
        fprintf(log_file, "%ld.%09ld: %d lux\n", ts.tv_sec, ts.tv_nsec, lux);
        fflush(log_file);

        control_relay(lux);

        sleep(SAMPLING_INTERVAL / 1000);
    }

    return 0;
}

