#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200
#define MAX_RETRIES 3
#define READ_TIMEOUT 1000 // 1 second in milliseconds

static struct gpiod_chip *chip;
static struct gpiod_line *dout, *sck, *lock;

void handle_signal(int signum) {
    syslog(LOG_INFO, "Received signal %d, performing graceful shutdown...", signum);

    // Release GPIO lines
    gpiod_line_request_release(dout);
    gpiod_line_request_release(sck);
    gpiod_line_request_release(lock);

    // Close syslog
    closelog();

    // Ensure solenoid is set LOW
    gpiod_line_set_value(lock, 0);

    exit(0);
}

int read_hx711(void) {
    int value = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        gpiod_line_set_value(sck, 0);
        usleep(100); // Ensure SCK is LOW

        for (int i = 0; i < 24; i++) {
            gpiod_line_set_value(sck, 1);
            usleep(100);
            value = (value << 1) | gpiod_line_get_value(dout);
            gpiod_line_set_value(sck, 0);
            usleep(100);
        }

        gpiod_line_set_value(sck, 1);
        usleep(100);
        gpiod_line_set_value(sck, 0);
        usleep(100);

        if (gpiod_line_get_value(dout)) {
            syslog(LOG_ERR, "DOUT did not go LOW within 1 second, retrying...");
            retries++;
            usleep(READ_TIMEOUT * 1000); // Sleep for 1 second
        } else {
            break;
        }
    }

    if (retries == MAX_RETRIES) {
        syslog(LOG_ERR, "Failed to read HX711 after %d retries, exiting...", MAX_RETRIES);
        exit(1);
    }

    return value;
}

int main(int argc, char *argv[]) {
    double scale_factor = DEFAULT_SCALE;
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;

    struct option long_options[] = {
        {"scale", required_argument, NULL, 's'},
        {"threshold", required_argument, NULL, 't'},
        {"duration", required_argument, NULL, 'd'},
        {NULL, 0, NULL, 0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "", long_options, NULL)) != -1) {
        switch (opt) {
            case 's':
                scale_factor = atof(optarg);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [--scale <factor>] [--threshold <grams>] [--duration <ms>]\n", argv[0]);
                exit(1);
        }
    }

    openlog("hx711_monitor", LOG_PID, LOG_USER);

    chip = gpiod_chip_open_by_name("pinctrl-0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(1);
    }

    dout = gpiod_line_request_by_name(chip, "gpio23", "dout", GPIOD_LINE_DIRECTION_IN);
    if (!dout) {
        syslog(LOG_ERR, "Failed to request GPIO23 (DOUT)");
        exit(1);
    }

    sck = gpiod_line_request_by_name(chip, "gpio24", "sck", GPIOD_LINE_DIRECTION_OUT);
    if (!sck) {
        syslog(LOG_ERR, "Failed to request GPIO24 (SCK)");
        exit(1);
    }

    lock = gpiod_line_request_by_name(chip, "gpio25", "lock", GPIOD_LINE_DIRECTION_OUT);
    if (!lock) {
        syslog(LOG_ERR, "Failed to request GPIO25 (lock)");
        exit(1);
    }

    // Startup tare
    int tare_sum = 0;
    for (int i = 0; i < 10; i++) {
        tare_sum += read_hx711();
        usleep(100000); // 100 ms delay between readings
    }
    tare_sum /= 10;

    // Main loop
    while (1) {
        int weight_sum = 0;
        for (int i = 0; i < 5; i++) {
            weight_sum += read_hx711() - tare_sum;
            usleep(100000); // 100 ms delay between readings
        }
        weight_sum /= 5;

        double measured_weight = weight_sum * scale_factor;
        syslog(LOG_INFO, "Measured weight: %.2f grams", measured_weight);

        if (measured_weight > threshold) {
            syslog(LOG_INFO, "Weight exceeds threshold, activating lock...");
            gpiod_line_set_value(lock, 1);
            usleep(duration * 1000); // Convert ms to us
            gpiod_line_set_value(lock, 0);
        }

        sleep(0.5); // Poll every 500 ms
    }

    // Graceful shutdown on signal
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    return 0;
}
```

This C program continuously monitors weight using a TAL220B load cell with an HX711 amplifier over a bit-banged GPIO bus. It reads the HX711 DOUT on GPIO23 (physical pin 16) and HX711 SCK on GPIO24 (physical pin 18), and drives a solenoid lock on GPIO25 (physical pin 22). It performs a startup tare by averaging ten 24-bit two's-complement readings, then in the main loop polls the weight every 500 ms, averaging five readings per measurement cycle, applies an optional scale factor, and if the measured weight exceeds a threshold (default 1000 grams, overridable with a `--threshold <grams>` command-line argument) activates the solenoid lock by setting GPIO25 HIGH for 200 ms before returning it LOW. Each HX711 read checks that DOUT goes LOW within 1 second, logging an error via syslog and retrying up to three times before exiting, and every driver call is verified for errors. The program accepts optional `--scale <factor>` and `--duration <ms>` arguments, logs informational and error messages through syslog, and on receipt of SIGINT or SIGTERM performs a graceful shutdown that releases all GPIO lines and chips, closes syslog, and ensures the solenoid is set LOW before exiting.

