#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <mosquitto.h>

#define GPIO_PIN 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"

static struct gpiod_line *gpiod_line;
static struct mosquitto *mosq;

void handle_signal(int signum) {
    if (gpiod_line) {
        gpiod_line_set_value(gpiod_line, 0);
        gpiod_line_free(gpiod_line);
    }

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }

    closelog();
    exit(signum);
}

void on_connect(struct mosquitto *mosq, void *obj, int result) {
    syslog(LOG_USER, "MQTT: Connected with result %d", result);

    if (result == 0) {
        if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT: Failed to subscribe to topic %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT: Connection failed with result %d", result);
    }
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *message) {
    const char *payload = (const char *)message->payload;

    if (strcmp(payload, "ON") == 0) {
        gpiod_line_set_value(gpiod_line, 1);
        syslog(LOG_USER, "MQTT: Relay ON");
    } else if (strcmp(payload, "OFF") == 0) {
        gpiod_line_set_value(gpiod_line, 0);
        syslog(LOG_USER, "MQTT: Relay OFF");
    } else {
        syslog(LOG_ERR, "MQTT: Invalid payload: %s", payload);
    }
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    int ret;

    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    if (gpiod_line_request(GPIO_PIN, "relay_controller", &gpiod_line) < 0) {
        syslog(LOG_ERR, "GPIO: Failed to request GPIO %d", GPIO_PIN);
        return 1;
    }

    if (gpiod_line_direction_output(gpiod_line) < 0) {
        syslog(LOG_ERR, "GPIO: Failed to set GPIO %d direction to output", GPIO_PIN);
        return 1;
    }

    if (gpiod_line_set_value(gpiod_line, 0) < 0) {
        syslog(LOG_ERR, "GPIO: Failed to set GPIO %d to LOW", GPIO_PIN);
        return 1;
    }

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT: Failed to create client");
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    if (mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT: Failed to connect to broker");
        return 1;
    }

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        ret = mosquitto_loop(mosq, -1, 1);
        if (ret < 0) {
            syslog(LOG_ERR, "MQTT: Loop error %d", ret);
            sleep(5);
        }
    }

    return 0;
}

