#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23
#define ENC_A_PHASE_A_PIN 4
#define ENC_A_PHASE_B_PIN 5
#define ENC_B_PHASE_A_PIN 6
#define ENC_B_PHASE_B_PIN 12

#define TARGET_RPM 50
#define PWM_FREQUENCY 10000
#define PWM_DUTY_CYCLE_MAX 255
#define CONTROL_LOOP_INTERVAL 100 // ms
#define STALL_DETECTION_TIMEOUT 2000 // ms

volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
volatile int last_encoder_a_ticks = 0;
volatile int last_encoder_b_ticks = 0;
volatile int stall_detection_timer = 0;

void handle_interrupt(int gpio, int level, uint32_t tick) {
    if (gpio == ENC_A_PHASE_A_PIN || gpio == ENC_A_PHASE_B_PIN) {
        encoder_a_ticks++;
    } else if (gpio == ENC_B_PHASE_A_PIN || gpio == ENC_B_PHASE_B_PIN) {
        encoder_b_ticks++;
    }
}

void calculate_rpm(int *rpm, int *ticks) {
    int ticks_diff = *ticks - *last_ticks;
    *last_ticks = *ticks;

    if (ticks_diff > 0) {
        *rpm = (ticks_diff * 60 * 1000) / (CONTROL_LOOP_INTERVAL * 64);
    } else {
        *rpm = 0;
    }
}

void control_loop() {
    int motor_a_rpm, motor_b_rpm;
    int motor_a_duty_cycle, motor_b_duty_cycle;

    calculate_rpm(&motor_a_rpm, &encoder_a_ticks);
    calculate_rpm(&motor_b_rpm, &encoder_b_ticks);

    if (motor_a_rpm < TARGET_RPM) {
        motor_a_duty_cycle = (TARGET_RPM - motor_a_rpm) * PWM_DUTY_CYCLE_MAX / TARGET_RPM;
    } else {
        motor_a_duty_cycle = 0;
    }

    if (motor_b_rpm < TARGET_RPM) {
        motor_b_duty_cycle = (TARGET_RPM - motor_b_rpm) * PWM_DUTY_CYCLE_MAX / TARGET_RPM;
    } else {
        motor_b_duty_cycle = 0;
    }

    motor_a_duty_cycle = (motor_a_duty_cycle > PWM_DUTY_CYCLE_MAX) ? PWM_DUTY_CYCLE_MAX : motor_a_duty_cycle;
    motor_b_duty_cycle = (motor_b_duty_cycle > PWM_DUTY_CYCLE_MAX) ? PWM_DUTY_CYCLE_MAX : motor_b_duty_cycle;

    printf("Motor A RPM: %d, Duty Cycle: %d\n", motor_a_rpm, motor_a_duty_cycle);
    printf("Motor B RPM: %d, Duty Cycle: %d\n", motor_b_rpm, motor_b_duty_cycle);

    gpioPWM(MOTOR_A_PWM_PIN, motor_a_duty_cycle);
    gpioPWM(MOTOR_B_PWM_PIN, motor_b_duty_cycle);

    if (motor_a_duty_cycle > 0 || motor_b_duty_cycle > 0) {
        stall_detection_timer = 0;
    } else {
        stall_detection_timer++;
    }

    if (stall_detection_timer > STALL_DETECTION_TIMEOUT / CONTROL_LOOP_INTERVAL) {
        printf("Warning: Motor stall detected!\n");
    }
}

void cleanup() {
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);
    gpioTerminate();
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
