#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define LUX_HYS 10
#define RELAY_GPIO 17
#define LOG_FILE "chicken_coop_log.txt"

static int i2c_fd;
static struct gpiod_line *relay_line;
static FILE *log_file;
static int last_lux = 0;
static int relay_state = 0;

void handle_signal(int signum) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_free(relay_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int read_lux() {
    char cmd[10];
    char response[10];
    int lux;

    sprintf(cmd, "00");
    write(i2c_fd, cmd, 2);
    usleep(180000); // Wait 180ms

    sprintf(cmd, "01");
    write(i2c_fd, cmd, 2);
    usleep(180000); // Wait 180ms

    read(i2c_fd, response, 2);
    lux = (response[0] << 8) | response[1];

    return lux;
}

void log_reading(int lux, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S: Lux = %d, Relay = %s\n", timeinfo, lux, relay_state ? "ON" : "OFF");
    fputs(buffer, log_file);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    int lux;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        return 1;
    }

    if (!(relay_line = gpiod_line_request_by_name(RELAY_GPIO, "relay", GPIOD_LINE_DIRECTION_OUTPUT))) {
        perror("Failed to request GPIO line");
        close(i2c_fd);
        return 1;
    }

    if (!(log_file = fopen(LOG_FILE, "a"))) {
        perror("Failed to open log file");
        gpiod_line_free(relay_line);
        close(i2c_fd);
        return 1;
    }

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        lux = read_lux();

        if (lux < LUX_THRESHOLD_DUSK - LUX_HYS && relay_state == 0) {
            gpiod_line_set_value(relay_line, 1);
            relay_state = 1;
            log_reading(lux, relay_state);
        } else if (lux > LUX_THRESHOLD_DAWN + LUX_HYS && relay_state == 1) {
            gpiod_line_set_value(relay_line, 0);
            relay_state = 0;
            log_reading(lux, relay_state);
        } else {
            log_reading(lux, relay_state);
        }

        last_lux = lux;
        sleep(5);
    }

    return 0;
}

