#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_TOUCH 4
#define GPIO_RELAY 17
#define DEBOUNCE_DELAY 50
#define SLEEP_INTERVAL 10

static gpiod_chip *chip;
static gpiod_line *touch_line, *relay_line;

void handle_sigint(int signum) {
    if (gpiod_line_request_release(touch_line) < 0) {
        fprintf(stderr, "Failed to release touch line.\n");
    }
    if (gpiod_line_request_release(relay_line) < 0) {
        fprintf(stderr, "Failed to release relay line.\n");
    }
    if (gpiod_chip_put(chip) < 0) {
        fprintf(stderr, "Failed to put chip.\n");
    }
    fprintf(stderr, "Exiting due to SIGINT.\n");
    exit(EXIT_FAILURE);
}

int main() {
    int ret;
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    bool relay_state = false;

    signal(SIGINT, handle_sigint);

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return EXIT_FAILURE;
    }

    if ((touch_line = gpiod_line_request_by_name(chip, "gpio%d", GPIO_TOUCH, "touch", GPIOD_LINE_DIRECTION_IN)) == NULL) {
        fprintf(stderr, "Failed to request touch line.\n");
        goto error_exit;
    }

    if ((relay_line = gpiod_line_request_by_name(chip, "gpio%d", GPIO_RELAY, "relay", GPIOD_LINE_DIRECTION_OUT)) == NULL) {
        fprintf(stderr, "Failed to request relay line.\n");
        goto error_exit;
    }

    if (gpiod_line_set_value(relay_line, relay_state) < 0) {
        fprintf(stderr, "Failed to set initial relay state.\n");
        goto error_exit;
    }

    while (1) {
        if (gpiod_line_get_value(touch_line) == 1) {
            usleep(DEBOUNCE_DELAY * 1000);
            if (gpiod_line_get_value(touch_line) == 1) {
                relay_state = !relay_state;
                if (gpiod_line_set_value(relay_line, relay_state) < 0) {
                    fprintf(stderr, "Failed to set relay state.\n");
                } else {
                    time(&ts.tv_sec);
                    ts.tv_nsec = 0;
                    tm = localtime(&ts.tv_sec);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
                    printf("%s Relay %s\n", timestamp, relay_state ? "ON" : "OFF");
                }
            }
        }
        usleep(SLEEP_INTERVAL * 1000);
    }

error_exit:
    if (gpiod_line_request_release(touch_line) < 0) {
        fprintf(stderr, "Failed to release touch line.\n");
    }
    if (gpiod_line_request_release(relay_line) < 0) {
        fprintf(stderr, "Failed to release relay line.\n");
    }
    if (gpiod_chip_put(chip) < 0) {
        fprintf(stderr, "Failed to put chip.\n");
    }
    return EXIT_FAILURE;
}

