            usleep(DEBOUNCE_DELAY * 1000);
            if (gpiod_line_get_value(touch_line) == 1) {
                relay_state = !relay_state;
                if (gpiod_line_set_value(relay_line, relay_state) < 0) {
                    fprintf(stderr, "Failed to set relay state.\n");
                } else {
                    time(&ts.tv_sec);
                    ts.tv_nsec = 0;
                    tm = localtime(&ts.tv_sec);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
                    printf("%s Relay %s\n", timestamp, relay_state ? "ON" : "OFF");
                }
            }
        }
        usleep(SLEEP_INTERVAL * 1000);
    }

