#define FLOW_THRESHOLD_OPEN 5.0
#define FLOW_THRESHOLD_CLOSE 4.5

pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

int pulse_count = 0;
int solenoid_state = 1; // HIGH by default

void handle_sigint_sigterm(int signum) {
    printf("Received signal %d: SIGINT or SIGTERM\n", signum);

    // Return solenoid to safe open state
    gpiod_line_set_value(solenoid_line, 1);

    // Close log file
    fclose(log_file);

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Cleanup GPIO library
    gpiod_chip_put(chip);

    exit(1);
}

void *isr_thread(void *arg) {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = DEBOUNCE_TIMEOUT;

    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);

        nanosleep(&ts, NULL);
    }
}

void *sampling_thread(void *arg) {
    struct timespec ts;
    ts.tv_sec = 1;
    ts.tv_nsec = 0;

    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double flow_rate = (double)current_pulse_count * 60.0 / 7.5; // LPM calculation

        if (flow_rate > FLOW_THRESHOLD_OPEN && solenoid_state == 1) {
            gpiod_line_set_value(solenoid_line, 0);
            solenoid_state = 0;
            fprintf(log_file, "Flow rate exceeded %.1f LPM at %s, solenoid closed\n", FLOW_THRESHOLD_OPEN, ctime(&current_time));
        } else if (flow_rate < FLOW_THRESHOLD_CLOSE && solenoid_state == 0) {
            gpiod_line_set_value(solenoid_line, 1);
            solenoid_state = 1;
            fprintf(log_file, "Flow rate dropped below %.1f LPM at %s, solenoid opened\n", FLOW_THRESHOLD_CLOSE, ctime(&current_time));
        }

        fprintf(log_file, "Flow rate: %.1f LPM at %s\n", flow_rate, ctime(&current_time));

        nanosleep(&ts, NULL);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *solenoid_line;
    FILE *log_file;
    struct timespec current_time;

    // Initialize GPIO library
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

