        gpiod_line_put(sensor_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set sensor line to input
    if (gpiod_line_direction_input(sensor_line) < 0) {
        perror("Failed to set sensor line direction to input");
        gpiod_line_put(solenoid_line);
        gpiod_line_put(sensor_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set solenoid line to output and open by default
    if (gpiod_line_direction_output(solenoid_line) < 0) {
        perror("Failed to set solenoid line direction to output");
        gpiod_line_put(sensor_line);
        gpiod_chip_put(chip);
        return 1;
    }
    if (gpiod_line_set_value(solenoid_line, 1) < 0) {
        perror("Failed to set solenoid line value");
        gpiod_line_put(sensor_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_put(solenoid_line);
        gpiod_line_put(sensor_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_sigint_sigterm;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Start ISR thread
    pthread_t isr_thread_id;
    if (pthread_create(&isr_thread_id, NULL, isr_thread, NULL) != 0) {
        perror("Failed to create ISR thread");
        fclose(log_file);
        gpiod_line_put(solenoid_line);
        gpiod_line_put(sensor_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Start sampling thread
    pthread_t sampling_thread_id;
    if (pthread_create(&sampling_thread_id, NULL, sampling_thread, NULL) != 0) {
        perror("Failed to create sampling thread");
        fclose(log_file);
        gpiod_line_put(solenoid_line);
        gpiod_line_put(sensor_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Main loop (not needed in this case)
    while (1) {
        nanosleep(&current_time, NULL);
    }

    return 0;
}

