            nanosleep(&ts, NULL);
            ts.tv_sec += debounce_ms / 1000;
            ts.tv_nsec += (debounce_ms % 1000) * 1000000;
            if (ts.tv_nsec >= 1000000000) {
                ts.tv_sec++;
                ts.tv_nsec -= 1000000000;
            }
        }
    }
}

