#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define INITIAL_ANGLE 90
#define DEGREE_STEP 10
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define PWM_FREQUENCY 50

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int signum) {
    stop_flag = 1;
}

void set_servo_angle(int angle) {
    int pulse_width = (angle * 10) + 500;
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        exit(EXIT_FAILURE);
    }

    if (gpioPWM(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Failed to set PWM pulse width\n");
        exit(EXIT_FAILURE);
    }

    printf("Servo angle set to %d°\n", angle);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    set_servo_angle(INITIAL_ANGLE);

    signal(SIGINT, handle_sigint);

    printf("Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    while (!stop_flag) {
        char c;
        if (read(STDIN_FILENO, &c, 1) != 1) {
            fprintf(stderr, "Failed to read input\n");
            break;
        }

        switch (c) {
            case '+':
                set_servo_angle(INITIAL_ANGLE + DEGREE_STEP);
                break;
            case '-':
                set_servo_angle(INITIAL_ANGLE - DEGREE_STEP);
                break;
            case 'q':
            case 'Q':
                stop_flag = 1;
                break;
            default:
                break;
        }
    }

    if (gpioPWM(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Failed to stop PWM\n");
        exit(EXIT_FAILURE);
    }

    gpioTerminate();

    return 0;
}

