#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define INTERVAL_SEC 5
#define LOG_FILE "motor_rpm.log"

static struct gpiod_line *gpiod_line;
static FILE *log_file;

static void handle_signal(int signum) {
    if (gpiod_line) {
        gpiod_line_free(gpiod_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum == SIGINT ? 0 : 1);
}

static void write_log(const char *timestamp, double rpm) {
    fprintf(log_file, "%s,%f\n", timestamp, rpm);
    fflush(log_file);
}

static void handle_event(struct gpiod_line *line, struct gpiod_event *event) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (end.tv_sec - start.tv_sec >= DEBOUNCE_MS / 1000) {
            break;
        }
        usleep(100); // Sleep for 100 microseconds
    }

    if (end.tv_sec - start.tv_sec < DEBOUNCE_MS / 1000) {
        return; // Event was too close, ignore it
    }

    gpiod_event_free(event);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct timespec start, end;
    double rpm = 0.0;
    int pulse_count = 0;

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    memset(&request, 0, sizeof(request));
    request.consumer = "motor_rpm_monitor";
    request.consumer_type = GPIOD_LINE_CONSUMER_USER;
    request.flags = GPIOD_LINE_ACTIVE_LOW | GPIOD_LINE_OPEN_DRAIN | GPIOD_LINE_ACTIVE_LOW;
    request.line_consumer = &handle_event;
    request.line_consumer_data = NULL;
    request.event_flags = GPIOD_EVENT_RISING_EDGE;
    request.debounce_ms = DEBOUNCE_MS;

    if (gpiod_line_request_by_name(chip, GPIO_PIN, &request) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line = request.line;

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_free(gpiod_line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &start);

        while (1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if (end.tv_sec - start.tv_sec >= INTERVAL_SEC) {
                break;
            }
            usleep(100); // Sleep for 100 microseconds
        }

        rpm = (double)pulse_count * 60.0 / (end.tv_sec - start.tv_sec);
        printf("Current RPM: %.2f\n", rpm);

        char timestamp[20];
        struct tm *tm_info;
        time_t rawtime = time(NULL);
        tm_info = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        write_log(timestamp, rpm);
        pulse_count = 0;
    }

    return 0;
}

