#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(4, PI_INPUT); // Set GPIO4 as input for TTP223 sensor
    gpioSetMode(17, PI_OUTPUT); // Set GPIO17 as output for relay

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sensor_state = 0;
    int relay_state = 0;
    time_t last_toggle_time = 0;
    time_t continuous_high_time = 0;

    while (!exit_flag) {
        int current_state = gpioRead(4);

        if (current_state != sensor_state) {
            sensor_state = current_state;

            if (sensor_state == 1) {
                continuous_high_time = time(NULL);
            } else {
                continuous_high_time = 0;
            }

            if (sensor_state == 1 && time(NULL) - last_toggle_time >= 10) {
                relay_state = 0;
                gpioWrite(17, relay_state);
                last_toggle_time = time(NULL);
            } else if (sensor_state == 1 && time(NULL) - last_toggle_time < 10) {
                relay_state = !relay_state;
                gpioWrite(17, relay_state);
                last_toggle_time = time(NULL);
            }
        }

        if (time(NULL) - last_toggle_time >= 50) {
            last_toggle_time = time(NULL);
        }

        if (gpioCall(PI_BAD_GPIO) == PI_BAD_GPIO) {
            fprintf(stderr, "Error: Invalid GPIO\n");
            exit(EXIT_FAILURE);
        }

        usleep(50000); // Sleep for 50ms
    }

    relay_state = 0;
    gpioWrite(17, relay_state);
    gpioTerminate();

    return EXIT_SUCCESS;
}

