#define TARGET_FLOW_RATE_ARG "-t"
#define TARGET_FLOW_RATE_DEFAULT 10.0
#define PWM_PIN 18
#define ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24
#define CONTROL_INTERVAL_MS 100
#define Kp 1.0
#define MAX_DUTY_CYCLE 255

volatile int flow_count = 0;
volatile double flow_rate = 0.0;
volatile int running = 1;

void handle_sigint(int signum) {
    running = 0;
}

void handle_sigterm(int signum) {
    running = 0;
}

void flow_sensor_isr(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        flow_count++;
    }
}

double calculate_flow_rate() {
    static uint64_t last_time = 0;
    uint64_t now = pigpio_time_ms();
    if (now - last_time >= CONTROL_INTERVAL_MS) {
        double flow_rate_per_second = (double)flow_count * 1000.0 / CONTROL_INTERVAL_MS;
        flow_rate = flow_rate_per_second * 0.0045; // Convert pulses/s to L/min
        flow_count = 0;
        last_time = now;
    }
    return flow_rate;
}

int main(int argc, char *argv[]) {
    double target_flow_rate = TARGET_FLOW_RATE_DEFAULT;
    int duty_cycle = 0;
    FILE *log_file = NULL;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], TARGET_FLOW_RATE_ARG) == 0) {
            if (i + 1 < argc) {
                target_flow_rate = atof(argv[i + 1]);
                if (target_flow_rate <= 0) {
                    fprintf(stderr, "Invalid target flow rate.\n");
                    return 1;
                }
            } else {
                fprintf(stderr, "Missing target flow rate value after '%s'.\n", TARGET_FLOW_RATE_ARG);
                return 1;
            }
        }
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin mode.\n");
        return 1;
    }

    if (gpioSetMode(ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set enable pin mode.\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode.\n");
        return 1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set flow sensor pin pull-up/down.\n");
        return 1;
    }

    if (gpioSetISRFunc(FLOW_SENSOR_PIN, EITHER_EDGE, &flow_sensor_isr) < 0) {
        fprintf(stderr, "Failed to set flow sensor ISR.\n");
        return 1;
    }

    if ((log_file = fopen("flow_log.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    fprintf(log_file, "timestamp_ms,flow_rate,valve_position\n");

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (running) {
        double current_flow_rate = calculate_flow_rate();
        duty_cycle = (int)((target_flow_rate - current_flow_rate) * Kp);
        duty_cycle = (duty_cycle < 0) ? 0 : (duty_cycle > MAX_DUTY_CYCLE) ? MAX_DUTY_CYCLE : duty_cycle;

        if (gpioPWM(PWM_PIN, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle.\n");
            running = 0;
        }

        if (gpioWrite(ENABLE_PIN, 1) < 0) {
            fprintf(stderr, "Failed to set enable pin.\n");
            running = 0;
        }

        fprintf(log_file, "%llu,%f,%d\n", (unsigned long long)pigpio_time_ms(), current_flow_rate, duty_cycle);

        usleep(CONTROL_INTERVAL_MS * 1000);
    }

    if (gpioPWM(PWM_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to zero.\n");
    }

    if (gpioWrite(ENABLE_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set enable pin low.\n");
    }

    if (fclose(log_file) != 0) {
        fprintf(stderr, "Failed to close log file.\n");
    }

    gpioTerminate();

    return 0;
}

