#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <pigpio.h>

#define TAG_SIZE 10
#define TAG_VALUE "\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0A"
#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define BUTTON_GPIO 22
#define SPI_CHANNEL 0
#define SPI_FREQ 100000
#define SPI_TIMEOUT 1000
#define DEBOUNCE_TIME 50
#define LOCK_TIME 5000

FILE *log_file;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpioWrite(LOCK_1_GPIO, PI_ON);
    gpioWrite(LOCK_2_GPIO, PI_ON);
    spiStop();
    exit(signum);
}

void log_access_attempt(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s\n", buffer, message);
    fflush(log_file);
}

int main() {
    int spi_fd;
    int button_state;
    uint8_t tag[TAG_SIZE];
    int retries = 0;

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_FREQ, SPI_MODE_0)) < 0) {
        perror("spiOpen");
        return 1;
    }

    if ((log_file = fopen("/var/log/door_access.log", "a")) == NULL) {
        perror("fopen");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetMode(LOCK_1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK_2_GPIO, PI_OUTPUT);
    gpioWrite(LOCK_1_GPIO, PI_ON);
    gpioWrite(LOCK_2_GPIO, PI_ON);

    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    while (1) {
        retries = 0;

        while (retries < 4) {
            if (spiRead(spi_fd, tag, TAG_SIZE) < 0) {
                log_access_attempt("RFID read failure");
                retries++;
                usleep(100000); // 100ms sleep
            } else if (memcmp(tag, TAG_VALUE, TAG_SIZE) == 0) {
                log_access_attempt("Valid tag detected");
                break;
            } else if (memcmp(tag, "\0", TAG_SIZE) == 0) {
                log_access_attempt("No tag present");
                break;
            } else {
                log_access_attempt("Invalid tag");
                retries++;
                usleep(100000); // 100ms sleep
            }
        }

        if (retries < 4) {
            button_state = gpioRead(BUTTON_GPIO);
            if (button_state == 0) {
                usleep(DEBOUNCE_TIME * 1000); // 50ms debounce
                button_state = gpioRead(BUTTON_GPIO);
                if (button_state == 0) {
                    log_access_attempt("Button pressed");
                    gpioWrite(LOCK_1_GPIO, PI_OFF);
                    gpioWrite(LOCK_2_GPIO, PI_OFF);
                    sleep(LOCK_TIME / 1000); // 5 seconds
                    gpioWrite(LOCK_1_GPIO, PI_ON);
                    gpioWrite(LOCK_2_GPIO, PI_ON);
                }
            }
        }
    }

    return 0;
}

