#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENC1_A 5
#define ENC1_B 6
#define ENC2_A 26
#define ENC2_B 19

#define PID_SAMPLE_TIME 100 // ms
#define TARGET_RPM 60
#define PWM_FREQUENCY 100 // Hz

#define MAX_PWM_DUTY_CYCLE 100

#define P 0.1
#define I 0.01
#define D 0.05

#define MAX_ERROR 1000

struct motor_data {
    struct gpiod_line *ena;
    struct gpiod_line *in1;
    struct gpiod_line *in2;
    int encoder_count;
    int prev_encoder_count;
    int error;
    int integral;
    int derivative;
    int pwm_duty_cycle;
};

struct motor_data motor1, motor2;

pthread_mutex_t motor1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t motor2_mutex = PTHREAD_MUTEX_INITIALIZER;

void *motor1_thread(void *arg) {
    while (1) {
        pthread_mutex_lock(&motor1_mutex);
        motor1.encoder_count = gpiod_line_get_value(motor1.in1);
        motor1.error = TARGET_RPM - motor1.encoder_count;
        motor1.integral += motor1.error;
        motor1.derivative = motor1.error - motor1.prev_encoder_count;
        motor1.prev_encoder_count = motor1.encoder_count;
        motor1.pwm_duty_cycle = (int)((P * motor1.error) + (I * motor1.integral) + (D * motor1.derivative));
        motor1.pwm_duty_cycle = (motor1.pwm_duty_cycle > MAX_PWM_DUTY_CYCLE) ? MAX_PWM_DUTY_CYCLE : motor1.pwm_duty_cycle;
        gpiod_line_set_value(motor1.ena, 1);
        gpiod_line_set_value(motor1.in1, 1);
        gpiod_line_set_value(motor1.in2, 0);
        pthread_mutex_unlock(&motor1_mutex);
        usleep(PID_SAMPLE_TIME * 1000);
    }
    return NULL;
}

void *motor2_thread(void *arg) {
    while (1) {
        pthread_mutex_lock(&motor2_mutex);
        motor2.encoder_count = gpiod_line_get_value(motor2.in3);
        motor2.error = TARGET_RPM - motor2.encoder_count;
        motor2.integral += motor2.error;
        motor2.derivative = motor2.error - motor2.prev_encoder_count;
        motor2.prev_encoder_count = motor2.encoder_count;
        motor2.pwm_duty_cycle = (int)((P * motor2.error) + (I * motor2.integral) + (D * motor2.derivative));
        motor2.pwm_duty_cycle = (motor2.pwm_duty_cycle > MAX_PWM_DUTY_CYCLE) ? MAX_PWM_DUTY_CYCLE : motor2.pwm_duty_cycle;
        gpiod_line_set_value(motor2.enb, 1);
        gpiod_line_set_value(motor2.in3, 1);
        gpiod_line_set_value(motor2.in4, 0);
        pthread_mutex_unlock(&motor2_mutex);
        usleep(PID_SAMPLE_TIME * 1000);
    }
    return NULL;
}

void cleanup_gpiod(void) {
    gpiod_line_free(motor1.ena);
    gpiod_line_free(motor1.in1);
    gpiod_line_free(motor1.in2);
    gpiod_line_free(motor2.enb);
    gpiod_line_free(motor2.in3);
    gpiod_line_free(motor2.in4);
}

void cleanup_file(FILE *file) {
    if (file) {
        fclose(file);
    }
}

void handle_signal(int signum) {
    cleanup_gpiod();
    cleanup_file(log_file);
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[6];
    FILE *log_file;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    lines[0] = gpiod_line_request(chip, MOTOR1_ENA, "Motor1_ENA", 0);
    lines[1] = gpiod_line_request(chip, MOTOR1_IN1, "Motor1_IN1", 0);
    lines[2] = gpiod_line_request(chip, MOTOR1_IN2, "Motor1_IN2", 0);
    lines[3] = gpiod_line_request(chip, MOTOR2_ENB, "Motor2_ENB", 0);
    lines[4] = gpiod_line_request(chip, MOTOR2_IN3, "Motor2_IN3", 0);
    lines[5] = gpiod_line_request(chip, MOTOR2_IN4, "Motor2_IN4", 0);

    for (int i = 0; i < 6; i++) {
        if (!lines[i]) {
            perror("Failed to request GPIO line");
            cleanup_gpiod();
            return 1;
        }
    }

    motor1.ena = lines[0];
    motor1.in1 = lines[1];
    motor1.in2 = lines[2];
    motor2.enb = lines[3];
    motor2.in3 = lines[4];
    motor2.in4 = lines[5];

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_gpiod();
        return 1;
    }

    fprintf(log_file, "Motor1_Speed,Motor1_P,Motor1_I,Motor1_D,Motor1_PWM,Motor2_Speed,Motor2_P,Motor2_I,Motor2_D,Motor2_PWM\n");

    pthread_t motor1_thread_id, motor2_thread_id;

    if (pthread_create(&motor1_thread_id, NULL, motor1_thread, NULL) != 0) {
        perror("Failed to create motor1 thread");
        cleanup_gpiod();
        cleanup_file(log_file);
        return 1;
