#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENC1_A 5
#define ENC1_B 6
#define ENC2_A 26
#define ENC2_B 19

#define PID_SAMPLE_TIME 100 // ms
#define TARGET_RPM 60
#define PWM_FREQUENCY 100 // Hz

#define MAX_PWM_DUTY_CYCLE 100

#define P 0.1
#define I 0.01
#define D 0.05

#define MAX_ERROR 1000

struct motor_data {
    struct gpiod_line *ena;
    struct gpiod_line *in1;
    struct gpiod_line *in2;
    int encoder_count;
    int prev_encoder_count;
    int error;
    int integral;
    int derivative;
    int pwm_duty_cycle;
};

struct motor_data motor1, motor2;

pthread_mutex_t motor1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t motor2_mutex = PTHREAD_MUTEX_INITIALIZER;

void *motor1_thread(void *arg) {
    while (1) {
        pthread_mutex_lock(&motor1_mutex);
        motor1.encoder_count = gpiod_line_get_value(motor1.in1);
        motor1.error = TARGET_RPM - motor1.encoder_count;
        motor1.integral += motor1.error;
        motor1.derivative = motor1.error - motor1.prev_encoder_count;
        motor1.prev_encoder_count = motor1.encoder_count;
        motor1.pwm_duty_cycle = (int)((P * motor1.error) + (I * motor1.integral) + (D * motor1.derivative));
        motor1.pwm_duty_cycle = (motor1.pwm_duty_cycle > MAX_PWM_DUTY_CYCLE) ? MAX_PWM_DUTY_CYCLE : motor1.pwm_duty_cycle;
        gpiod_line_set_value(motor1.ena, 1);
        gpiod_line_set_value(motor1.in1, 1);
        gpiod_line_set_value(motor1.in2, 0);
        pthread_mutex_unlock(&motor1_mutex);
        usleep(PID_SAMPLE_TIME * 1000);
    }
    return NULL;
}

void *motor2_thread(void *arg) {
    while (1) {
        pthread_mutex_lock(&motor2_mutex);
        motor2.encoder_count = gpiod_line_get_value(motor2.in3);
        motor2.error = TARGET_RPM - motor2.encoder_count;
        motor2.integral += motor2.error;
        motor2.derivative = motor2.error - motor2.prev_encoder_count;
        motor2.prev_encoder_count = motor2.encoder_count;
        motor2.pwm_duty_cycle = (int)((P * motor2.error) + (I * motor2.integral) + (D * motor2.derivative));
        motor2.pwm_duty_cycle = (motor2.pwm_duty_cycle > MAX_PWM_DUTY_CYCLE) ? MAX_PWM_DUTY_CYCLE : motor2.pwm_duty_cycle;
        gpiod_line_set_value(motor2.enb, 1);
        gpiod_line_set_value(motor2.in3, 1);
        gpiod_line_set_value(motor2.in4, 0);
        pthread_mutex_unlock(&motor2_mutex);
        usleep(PID_SAMPLE_TIME * 1000);
    }
    return NULL;
}

