    gpiod_line_free(motor1.ena);
    gpiod_line_free(motor1.in1);
    gpiod_line_free(motor1.in2);
    gpiod_line_free(motor2.enb);
    gpiod_line_free(motor2.in3);
    gpiod_line_free(motor2.in4);
}

void cleanup_file(FILE *file) {
    if (file) {
        fclose(file);
    }
}

void handle_signal(int signum) {
    cleanup_gpiod();
    cleanup_file(log_file);
    exit(signum);
}

