    lines[1] = gpiod_line_request(chip, MOTOR1_IN1, "Motor1_IN1", 0);
    lines[2] = gpiod_line_request(chip, MOTOR1_IN2, "Motor1_IN2", 0);
    lines[3] = gpiod_line_request(chip, MOTOR2_ENB, "Motor2_ENB", 0);
    lines[4] = gpiod_line_request(chip, MOTOR2_IN3, "Motor2_IN3", 0);
    lines[5] = gpiod_line_request(chip, MOTOR2_IN4, "Motor2_IN4", 0);

    for (int i = 0; i < 6; i++) {
        if (!lines[i]) {
            perror("Failed to request GPIO line");
            cleanup_gpiod();
            return 1;
        }
    }

    motor1.ena = lines[0];
    motor1.in1 = lines[1];
    motor1.in2 = lines[2];
    motor2.enb = lines[3];
    motor2.in3 = lines[4];
    motor2.in4 = lines[5];

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
