#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define MPR121_I2C_ADDR 0x5A
#define MPR121_SOFT_RESET 0x00
#define MPR121_CONFIG 0x01
#define MPR121_THRESH_LOW 0x02
#define MPR121_THRESH_HIGH 0x03
#define MPR121_RUN_MODE 0x04
#define MPR121_DATA 0x05
#define MPR121_DATA_LEN 12
#define GPIO_RELAY 17
#define LOG_FILE "relay_log.txt"

static gpiod_chip *chip;
static gpiod_line *relay_line;

void handle_sigint(int signum) {
    gpiod_line_set_value(relay_line, 0);
    gpiod_line_free(relay_line);
    gpiod_chip_put(chip);
    fclose(stdout);
    exit(0);
}

int main() {
    int i2c_fd;
    int ret;
    char data[MPR121_DATA_LEN];
    struct timespec ts;
    struct tm *tm_info;
    FILE *log_file;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiomem");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiod chip\n");
        return 1;
    }

    relay_line = gpiod_line_request_by_name(chip, "gpio%d", GPIO_RELAY, "Relay", 0);
    if (!relay_line) {
        fprintf(stderr, "Failed to request relay GPIO line\n");
        gpiod_chip_put(chip);
        return 1;
    }

    gpiod_line_set_value(relay_line, 0);

    signal(SIGINT, handle_sigint);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_free(relay_line);
        gpiod_chip_put(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpiod_line_free(relay_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Perform MPR121 initialization sequence
    ret = write(i2c_fd, &MPR121_SOFT_RESET, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to perform soft reset\n");
        close(i2c_fd);
        gpiod_line_free(relay_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Configure filtering parameters (example values)
    uint8_t config_data = 0x00;
    ret = write(i2c_fd, &config_data, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to configure filtering parameters\n");
        close(i2c_fd);
        gpiod_line_free(relay_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set touch and release thresholds (example values)
    uint8_t thresh_low_data = 0x00;
    uint8_t thresh_high_data = 0x00;
    for (i = 0; i < MPR121_DATA_LEN; i++) {
        ret = write(i2c_fd, &thresh_low_data, 1);
        if (ret != 1) {
            fprintf(stderr, "Failed to set touch threshold\n");
            close(i2c_fd);
            gpiod_line_free(relay_line);
            gpiod_chip_put(chip);
            return 1;
        }
        ret = write(i2c_fd, &thresh_high_data, 1);
        if (ret != 1) {
            fprintf(stderr, "Failed to set release threshold\n");
            close(i2c_fd);
            gpiod_line_free(relay_line);
            gpiod_chip_put(chip);
            return 1;
        }
    }

    // Enable run mode
    ret = write(i2c_fd, &MPR121_RUN_MODE, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to enable run mode\n");
        close(i2c_fd);
        gpiod_line_free(relay_line);
        gpiod_chip_put(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpiod_line_free(relay_line);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        ret = read(i2c_fd, data, MPR121_DATA_LEN);
        if (ret != MPR121_DATA_LEN) {
            fprintf(stderr, "Failed to read data from sensor\n");
            break;
        }

        int relay_state = 0;
        for (i = 0; i < MPR121_DATA_LEN; i++) {
            if (data[i] > 0) {
                relay_state = 1;
                break;
            }
        }

        if (relay_state != gpiod_line_get_value(relay_line)) {
            gpiod_line_set_value(relay_line, relay_state);
            clock_gettime(CLOCK_REALTIME, &ts);
            tm_info = localtime(&ts.tv_sec);
            fprintf(log_file, "%02d:%02d:%02d Relay state: %d\n",
                    tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, relay_state);
        }

        usleep(50000); // 50 ms delay
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_line_free(relay_line);
    gpiod_chip_put(chip);
    gpioTerminate();

    return 0;
}

