#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_VALVE1 17
#define GPIO_VALVE2 18
#define VALVE_ON 1
#define VALVE_OFF 0

static gpiod_chip *chip;
static gpiod_line *valve1, *valve2;
static FILE *log_file;

void handle_signal(int signum) {
    if (valve1) {
        gpiod_line_request_free(valve1);
        valve1 = NULL;
    }
    if (valve2) {
        gpiod_line_request_free(valve2);
        valve2 = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    exit(signum);
}

void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s\n", buffer, event);
    fflush(log_file);
}

int main() {
    int err;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    valve1 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_VALVE1, "valve1", 0);
    if (!valve1) {
        fprintf(stderr, "Failed to request GPIO line for Valve 1\n");
        gpiod_chip_put(chip);
        return 1;
    }

    valve2 = gpiod_line_request_by_name(chip, "gpio%d", GPIO_VALVE2, "valve2", 0);
    if (!valve2) {
        fprintf(stderr, "Failed to request GPIO line for Valve 2\n");
        gpiod_line_request_free(valve1);
        gpiod_chip_put(chip);
        return 1;
    }

    log_file = fopen("valve_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_request_free(valve1);
        gpiod_line_request_free(valve2);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        gpiod_line_set_value(valve1, VALVE_ON);
        log_event("Valve 1 activated");
        usleep(500 * 1000); // 500 ms
        gpiod_line_set_value(valve1, VALVE_OFF);
        log_event("Valve 1 deactivated");
        sleep(5); // 5 seconds

        gpiod_line_set_value(valve2, VALVE_ON);
        log_event("Valve 2 activated");
        usleep(1000 * 1000); // 1000 ms
        gpiod_line_set_value(valve2, VALVE_OFF);
        log_event("Valve 2 deactivated");
        sleep(10); // 10 seconds
    }

