#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_PATH "/sys/class/gpio/gpio17"
#define GPIO_VALUE "value"

#define TOUCH_THRESHOLD 100
#define RELEASE_THRESHOLD 50
#define FILTER_VALUE 0x00
#define CHARGE_TIME 0x00
#define ELECTRODE_CURRENT 0x00

int relay_fd = -1;
int i2c_fd = -1;

void handle_signal(int signum) {
    if (relay_fd != -1) {
        write_file(GPIO_PATH, GPIO_VALUE, "0");
        close(relay_fd);
        relay_fd = -1;
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    exit(signum);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_i2c_device() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire MPR121 I2C device");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int open_relay_gpio() {
    if (access(GPIO_PATH, F_OK) != 0) {
        printf("GPIO17 not found, creating...\n");
        if (access(GPIO_PATH, F_OK) != 0) {
            printf("Failed to create GPIO17\n");
            return -1;
        }
    }

    relay_fd = open(GPIO_PATH, O_WRONLY);
    if (relay_fd < 0) {
        perror("Failed to open GPIO17");
        return -1;
    }

    return 0;
}

int write_file(const char *path, const char *file, const char *value) {
    char buffer[1024];
    snprintf(buffer, sizeof(buffer), "%s/%s", path, file);

    FILE *fp = fopen(buffer, "w");
    if (fp == NULL) {
        perror("Failed to open file for writing");
        return -1;
    }

    if (fprintf(fp, "%s", value) < 0) {
        perror("Failed to write to file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    setup_signal_handlers();

    if (open_i2c_device() < 0) {
        return 1;
    }

    if (open_relay_gpio() < 0) {
        return 1;
    }

    // Initialize MPR121
    uint8_t reg_data = 0x00;
    if (write_i2c(MPR121_ADDR, 0x00, &reg_data, 1) < 0) {
        goto cleanup;
    }

    // Configure thresholds
    reg_data = TOUCH_THRESHOLD;
    if (write_i2c(MPR121_ADDR, 0x01, &reg_data, 1) < 0) {
        goto cleanup;
    }

    reg_data = RELEASE_THRESHOLD;
    if (write_i2c(MPR121_ADDR, 0x02, &reg_data, 1) < 0) {
        goto cleanup;
    }

    // Set filter and charge time
    reg_data = FILTER_VALUE;
    if (write_i2c(MPR121_ADDR, 0x03, &reg_data, 1) < 0) {
        goto cleanup;
    }

