    if (write_i2c(MPR121_ADDR, 0x04, &reg_data, 1) < 0) {
        goto cleanup;
    }

    // Set electrode current
    reg_data = ELECTRODE_CURRENT;
    if (write_i2c(MPR121_ADDR, 0x05, &reg_data, 1) < 0) {
        goto cleanup;
    }

    // Switch to run mode
    reg_data = 0x00;
    if (write_i2c(MPR121_ADDR, 0x06, &reg_data, 1) < 0) {
        goto cleanup;
    }

    // Stabilization delay
    usleep(100000);

    int relay_state = 0;
    while (1) {
        uint8_t touch_status[12];
        if (read_i2c(MPR121_ADDR, 0x07, touch_status, 12) < 0) {
            continue;
        }

        int touched = 0;
        for (int i = 0; i < 12; i++) {
            if (touch_status[i] > 0) {
                touched = 1;
                break;
            }
        }

        if (touched) {
            relay_state = !relay_state;
            if (write_file(GPIO_PATH, GPIO_VALUE, relay_state ? "1" : "0") < 0) {
                continue;
            }

