        }

        usleep(100000);
    }

cleanup:
    if (relay_fd != -1) {
        close(relay_fd);
        relay_fd = -1;
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    return 0;
}

int write_i2c(uint8_t addr, uint8_t reg, uint8_t *data, uint8_t len) {
    int ret = 0;
    uint8_t buffer[len + 2];

    buffer[0] = reg;
    memcpy(buffer + 1, data, len);

    ret = write(i2c_fd, buffer, len + 1);
    if (ret < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }

    return 0;
}

int read_i2c(uint8_t addr, uint8_t reg, uint8_t *data, uint8_t len) {
    int ret = 0;
    uint8_t buffer[len + 1];

    buffer[0] = reg;
    ret = write(i2c_fd, buffer, 1);
    if (ret < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }

    ret = read(i2c_fd, data, len);
    if (ret < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

