#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PIR 17
#define GPIO_RELAY 18
#define LOG_FILE "door_events.log"
#define DEBOUNCE_TIME 50000 // 50 ms
#define LOCK_TIME 500000 // 500 ms
#define RATE_LIMIT_TIME 2000000 // 2 seconds

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line, *relay_line;
static FILE *log_file;
static struct timespec last_event_time;

void handle_sigint(int signum) {
    gpiod_line_request_free(pir_line);
    gpiod_line_request_free(relay_line);
    gpiod_chip_put(chip);
    fclose(log_file);
    exit(0);
}

void write_log(const char *event_type) {
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
    fprintf(log_file, "%s - %s\n", timestamp, event_type);
    fflush(log_file);
}

int main() {
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    pir_line = gpiod_line_request_by_name(chip, "gpio%d", GPIO_PIR, "pir_sensor", 0);
    if (!pir_line) {
        fprintf(stderr, "Failed to request PIR sensor GPIO line\n");
        gpiod_chip_put(chip);
        return 1;
    }

    relay_line = gpiod_line_request_by_name(chip, "gpio%d", GPIO_RELAY, "relay", GPIO_LINE_DIRECTION_OUTPUT);
    if (!relay_line) {
        fprintf(stderr, "Failed to request relay GPIO line\n");
        gpiod_line_request_free(pir_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set PIR sensor as input with pull-down
    gpiod_line_direction_set(pir_line, GPIO_LINE_DIRECTION_INPUT);
    gpiod_line_set_debounce(pir_line, DEBOUNCE_TIME);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_request_free(pir_line);
        gpiod_line_request_free(relay_line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    int prev_state = 0;
    while (1) {
        int current_state = gpiod_line_get_value(pir_line);
        if (current_state != prev_state) {
            if (current_state == 1) {
                // Rising edge detected
                if (time(NULL) - last_event_time.tv_sec >= RATE_LIMIT_TIME / 1000) {
                    write_log("Motion detected");
                    gpiod_line_set_value(relay_line, 1);
                    nanosleep(&last_event_time, NULL);
                    gpiod_line_set_value(relay_line, 0);
                    last_event_time.tv_sec = time(NULL);
                    last_event_time.tv_nsec = 0;
                } else {
                    write_log("Rate limited");
                }
            }
            prev_state = current_state;
        }
        nanosleep(&last_event_time, NULL);
    }

    // Cleanup on normal termination or signal
    handle_sigint(0);

    return 0;
}

