#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_STEPS_MIN 5
#define NUM_STEPS_MAX 15
#define DUTY_CYCLE_MIN 0
#define DUTY_CYCLE_MAX 255
#define STEP_DURATION_MIN 50
#define STEP_DURATION_MAX 200

volatile sig_atomic_t shutdown = 0;

void handle_sigint(int signum) {
    shutdown = 1;
}

void generate_pattern(int motor1_pin, int motor2_pin) {
    int num_steps = NUM_STEPS_MIN + rand() % (NUM_STEPS_MAX - NUM_STEPS_MIN + 1);
    int *duty_cycles = malloc(num_steps * sizeof(int));
    int *durations = malloc(num_steps * sizeof(int));

    if (duty_cycles == NULL || durations == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_steps; i++) {
        duty_cycles[i] = DUTY_CYCLE_MIN + rand() % (DUTY_CYCLE_MAX - DUTY_CYCLE_MIN + 1);
        durations[i] = STEP_DURATION_MIN + rand() % (STEP_DURATION_MAX - STEP_DURATION_MIN + 1);
    }

    for (int i = 0; i < num_steps; i++) {
        if (gpioPWM(motor1_pin, duty_cycles[i]) < 0 ||
            gpioPWM(motor2_pin, duty_cycles[i]) < 0) {
            perror("Failed to set PWM duty cycle");
            exit(EXIT_FAILURE);
        }

        usleep(durations[i] * 1000);
    }

    free(duty_cycles);
    free(durations);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(17, PI_OUTPUT) < 0 ||
        gpioSetMode(27, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    srand(time(NULL));

    while (!shutdown) {
        generate_pattern(17, 27);
    }

    gpioPWM(17, 0);
    gpioPWM(27, 0);

    gpioTerminate();

    return 0;
}

