        duty_cycles[i] = DUTY_CYCLE_MIN + rand() % (DUTY_CYCLE_MAX - DUTY_CYCLE_MIN + 1);
        durations[i] = STEP_DURATION_MIN + rand() % (STEP_DURATION_MAX - STEP_DURATION_MIN + 1);
    }

    for (int i = 0; i < num_steps; i++) {
        if (gpioPWM(motor1_pin, duty_cycles[i]) < 0 ||
            gpioPWM(motor2_pin, duty_cycles[i]) < 0) {
            perror("Failed to set PWM duty cycle");
            exit(EXIT_FAILURE);
        }

        usleep(durations[i] * 1000);
    }

    free(duty_cycles);
    free(durations);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(17, PI_OUTPUT) < 0 ||
        gpioSetMode(27, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    srand(time(NULL));

    while (!shutdown) {
        generate_pattern(17, 27);
    }

    gpioPWM(17, 0);
    gpioPWM(27, 0);

    gpioTerminate();

    return 0;
}
