#define GPIO_DATA 4
#define GPIO_CLOCK 17
#define GPIO_LOCK 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define CALIBRATION_THRESHOLD 10.0
#define CALIBRATION_COUNT 100
#define READ_INTERVAL 500
#define READ_TIMEOUT 500

static struct gpiod_line *data_line, *clock_line, *lock_line;
static double scale_factor = 1.0;
static double offset = 0.0;

void handle_sigint(int signum) {
    gpiod_line_request_free(data_line);
    gpiod_line_request_free(clock_line);
    gpiod_line_request_free(lock_line);
    fclose(fopen(LOG_FILE, "a"));
    fclose(fopen(CALIBRATION_FILE, "w"));
    exit(0);
}

void read_calibration() {
    FILE *calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        return;
    }

    char line[256];
    if (fgets(line, sizeof(line), calibration_file)) {
        sscanf(line, "%lf %lf", &scale_factor, &offset);
    }

    fclose(calibration_file);
}

void write_calibration() {
    FILE *calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        return;
    }

    fprintf(calibration_file, "%lf %lf\n", scale_factor, offset);
    fclose(calibration_file);
}

void startup_calibration() {
    double sum = 0.0;
    for (int i = 0; i < CALIBRATION_COUNT; i++) {
        usleep(READ_INTERVAL * 1000);
        sum += gpiod_line_get_value(data_line);
    }
    offset = sum / CALIBRATION_COUNT;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;

    chip = gpiod_chip_open_by_name("gpio");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    req = gpiod_line_request_open(chip, "gpio%d", GPIO_DATA, "data",
                                  GPIOD_LINE_DIRECTION_IN, NULL);
    if (req == NULL) {
        perror("Failed to request GPIO data line");
        gpiod_chip_close(chip);
        return 1;
    }
    data_line = gpiod_line_request_get_line(req);

    req = gpiod_line_request_open(chip, "gpio%d", GPIO_CLOCK, "clock",
                                  GPIOD_LINE_DIRECTION_OUT, NULL);
    if (req == NULL) {
        perror("Failed to request GPIO clock line");
        gpiod_line_request_free(req);
        gpiod_chip_close(chip);
        return 1;
    }
    clock_line = gpiod_line_request_get_line(req);

    req = gpiod_line_request_open(chip, "gpio%d", GPIO_LOCK, "lock",
                                  GPIOD_LINE_DIRECTION_OUT, NULL);
    if (req == NULL) {
        perror("Failed to request GPIO lock line");
        gpiod_line_request_free(req);
        gpiod_line_request_free(req);
        gpiod_chip_close(chip);
        return 1;
    }
    lock_line = gpiod_line_request_get_line(req);

    read_calibration();
    startup_calibration();

    signal(SIGINT, handle_sigint);

    while (1) {
        struct timespec timeout = { .tv_sec = READ_TIMEOUT / 1000, .tv_nsec = (READ_TIMEOUT % 1000) * 1000000 };
        int result = gpiod_line_get_value_timed(data_line, &timeout);
        if (result == -ETIMEDOUT) {
            continue;
        }

        double weight = (gpiod_line_get_value(data_line) - offset) * scale_factor;
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            continue;
        }

        fprintf(log_file, "%s: %.2f kg\n", timestamp, weight);
        fclose(log_file);

        if (weight > CALIBRATION_THRESHOLD) {
            gpiod_line_set_value(lock_line, 1);
        } else {
            gpiod_line_set_value(lock_line, 0);
        }

        usleep(READ_INTERVAL * 1000);
    }

    handle_sigint(0);
    return 0;
}

