        .flags = GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    struct gpiod_line_request in1_req = {
        .consumer = "window_control",
        .consumer_user_data = "in1",
        .flags = GPIOD_LINE_REQUEST_ACTIVE_HIGH | GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };

