        .flags = GPIOD_LINE_REQUEST_ACTIVE_HIGH | GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };

    struct gpiod_line_request pwm_req = {
        .consumer = "window_control",
        .consumer_user_data = "pwm",
        .flags = GPIOD_LINE_REQUEST_ACTIVE_HIGH | GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };

    int sensor_readings[DEBOUNCE_COUNT];
    int rain_detected = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    sensor_line = gpiod_line_request_get(GPIO_PIN_SENSOR, &sensor_req);
    if (!sensor_line) {
        fprintf(stderr, "Failed to request sensor GPIO\n");
        return 1;
    }

    in1_line = gpiod_line_request_get(GPIO_PIN_IN1, &in1_req);
    if (!in1_line) {
        fprintf(stderr, "Failed to request IN1 GPIO\n");
        gpiod_line_request_free(sensor_line);
        return 2;
    }

    in2_line = gpiod_line_request_get(GPIO_PIN_IN2, &in2_req);
    if (!in2_line) {
        fprintf(stderr, "Failed to request IN2 GPIO\n");
        gpiod_line_request_free(sensor_line);
        gpiod_line_request_free(in1_line);
        return 3;
