        gpiod_line_request_free(sensor_line);
        gpiod_line_request_free(in1_line);
        gpiod_line_request_free(in2_line);
        return 4;
    }

    while (1) {
        int i;
        int low_count = 0;

        for (i = 0; i < DEBOUNCE_COUNT; i++) {
            sensor_readings[i] = read_sensor();
            if (sensor_readings[i] < 0) {
                break;
            }
            if (sensor_readings[i] == 0) {
                low_count++;
            }
            usleep(DEBOUNCE_INTERVAL * 1000);
