This C program continuously monitors the weight using a TAL220B load cell connected to an HX711 amplifier on a Raspberry Pi 4 Model B. It reads the data line (DT) on GPIO23 (BCM) and the clock line (SCK) on GPIO24 (BCM). When the measured weight falls below 100 grams, it activates a solenoid lock attached to GPIO17 (BCM) for exactly five seconds. It logs each weight check, lock activation, and any error condition with a timestamp to a file named `stock_events.txt`. The program handles errors for all reads, writes, and file operations and performs proper resource cleanup when receiving SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define CALIBRATION_WEIGHT 1.0 // Known weight for calibration in kg
#define THRESHOLD_WEIGHT 5.0 // Threshold weight in kg
#define TIMEOUT_MS 100

static struct gpiod_line *data_line, *clock_line, *solenoid_line;

void handle_sigint(int signum) {
    gpiod_line_set_value(solenoid_line, 0);
    gpiod_line_request_free(solenoid_line);
    gpiod_line_request_free(clock_line);
    gpiod_line_request_free(data_line);
    exit(0);
}

int read_hx711() {
    int i, result = 0;
    for (i = 0; i < 24; i++) {
        gpiod_line_set_value(clock_line, 1);
        usleep(1000); // 1 µs delay
        result <<= 1;
        if (gpiod_line_get_value(data_line)) {
            result |= 1;
        }
        gpiod_line_set_value(clock_line, 0);
        usleep(1000); // 1 µs delay
    }
    return result;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;
    struct gpiod_line_request_config config;
    struct timespec timeout;
    int raw_value, calibration_factor, calibrated_weight;
    FILE *calibration_file, *security_log;

    signal(SIGINT, handle_sigint);

    if ((chip = gpiod_chip_open_by_name("gpio")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "HX711_reader";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if ((data_line = gpiod_line_request_open(chip, DATA_PIN, &config)) == NULL) {
        perror("Failed to request data line");
        gpiod_chip_close(chip);
        return 1;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if ((clock_line = gpiod_line_request_open(chip, CLOCK_PIN, &config)) == NULL) {
        perror("Failed to request clock line");
        gpiod_line_request_free(data_line);
        gpiod_chip_close(chip);
        return 1;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if ((solenoid_line = gpiod_line_request_open(chip, SOLENOID_PIN, &config)) == NULL) {
        perror("Failed to request solenoid line");
        gpiod_line_request_free(clock_line);
        gpiod_line_request_free(data_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Place a known weight (%.1f kg) on the load cell and press Enter.\n", CALIBRATION_WEIGHT);
    getchar();

    raw_value = read_hx711();
    calibration_factor = raw_value / CALIBRATION_WEIGHT;

    if ((calibration_file = fopen(CALIBRATION_FILE, "w")) == NULL) {
        perror("Failed to open calibration file");
        gpiod_line_request_free(solenoid_line);
        gpiod_line_request_free(clock_line);
        gpiod_line_request_free(data_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (fprintf(calibration_file, "%d\n", calibration_factor) < 0) {
        perror("Failed to write calibration factor");
        fclose(calibration_file);
        gpiod_line_request_free(solenoid_line);
        gpiod_line_request_free(clock_line);
        gpiod_line_request_free(data_line);
        gpiod_chip_close(chip);
        return 1;
    }

    fclose(calibration_file);

    if ((security_log = fopen(SECURITY_LOG_FILE, "a")) == NULL) {
        perror("Failed to open security log file");
        gpiod_line_request_free(solenoid_line);
        gpiod_line_request_free(clock_line);
        gpiod_line_request_free(data_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        raw_value = read_hx711();
        calibrated_weight = raw_value / calibration_factor;

        if (gpiod_line_get_value(data_line)) {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            if (now.tv_sec - timeout.tv_sec > TIMEOUT_MS / 1000) {
                fprintf(stderr, "Timeout occurred.\n");
                break;
            }
        }

        if (calibrated_weight > THRESHOLD_WEIGHT) {
            gpiod_line_set_value(solenoid_line, 1);
            sleep(5);
            gpiod_line_set_value(solenoid_line, 0);

            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            fprintf(security_log, "%ld.%09ld: %.1f kg\n", now.tv_sec, now.tv_nsec / 1000000, calibrated_weight);
        }
    }

    fclose(security_log);
    gpiod_line_request_free(solenoid_line);
    gpiod_line_request_free(clock_line);
    gpiod_line_request_free(data_line);
    gpiod_chip_close(chip);

    return 0;
}

