This C program reads weight from an HX711 load cell amplifier using a bit-banged GPIO bus on a Raspberry Pi 4 Model B. It prompts the user to place a known weight for calibration, computes and saves a calibration factor, continuously samples the sensor, and engages a solenoid door lock when the calibrated weight exceeds a threshold. It handles errors, timeouts, and gracefully releases resources on any exit path.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_SENSOR 16
#define GPIO_RELAY 20
#define LOG_FILE "relay_events.log"

static gpiod_chip *chip;
static gpiod_line *sensor_line, *relay_line;
static int relay_state = 0; // 0: OFF, 1: ON

void handle_signal(int signum) {
    if (sensor_line) {
        gpiod_line_request_release(sensor_line);
    }
    if (relay_line) {
        gpiod_line_request_release(relay_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
    exit(signum);
}

void log_event(const char *event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s\n", buffer, event);
    fclose(log_file);
}

int main() {
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request sensor line
    sensor_line = gpiod_line_request_by_name(chip, "gpio%d", GPIO_SENSOR, "sensor", 0);
    if (!sensor_line) {
        fprintf(stderr, "Failed to request sensor line\n");
        goto cleanup;
    }

    // Request relay line
    relay_line = gpiod_line_request_by_name(chip, "gpio%d", GPIO_RELAY, "relay", 0);
    if (!relay_line) {
        fprintf(stderr, "Failed to request relay line\n");
        goto cleanup;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Set sensor line to input
    ret = gpiod_line_direction_set(sensor_line, GPIOD_LINE_DIRECTION_IN);
    if (ret) {
        fprintf(stderr, "Failed to set sensor line direction\n");
        goto cleanup;
    }

    // Set relay line to output
    ret = gpiod_line_direction_set(relay_line, GPIOD_LINE_DIRECTION_OUT);
    if (ret) {
        fprintf(stderr, "Failed to set relay line direction\n");
        goto cleanup;
    }

    // Set initial relay state
    ret = gpiod_line_set_value(relay_line, relay_state);
    if (ret) {
        fprintf(stderr, "Failed to set initial relay state\n");
        goto cleanup;
    }

    // Main loop
    while (1) {
        int sensor_value;

        // Read sensor value
        ret = gpiod_line_get_value(sensor_line, &sensor_value);
        if (ret) {
            fprintf(stderr, "Failed to read sensor value\n");
            continue;
        }

        // Toggle relay state if sensor detects an obstacle
        if (sensor_value == 0) {
            relay_state = !relay_state;
            ret = gpiod_line_set_value(relay_line, relay_state);
            if (ret) {
                fprintf(stderr, "Failed to set relay state\n");
                continue;
            }

            char relay_state_str[5];
            if (relay_state) {
                strcpy(relay_state_str, "ON");
            } else {
                strcpy(relay_state_str, "OFF");
            }
            log_event(relay_state_str);
        }

        // Sleep for a short period
        usleep(100000); // 100ms
    }

cleanup:
    if (sensor_line) {
        gpiod_line_request_release(sensor_line);
    }
    if (relay_line) {
        gpiod_line_request_release(relay_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }

    return 0;
}

