#define PIR_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "motion_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *pir_sensor_line, *buzzer_line;
static FILE *log_file;

void handle_signal(int signum) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_free(buzzer_line);
    }

    if (pir_sensor_line) {
        gpiod_line_free(pir_sensor_line);
    }

    if (log_file) {
        fclose(log_file);
    }

    if (chip) {
        gpiod_chip_put(chip);
    }

    exit(signum);
}

int main() {
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_by_name(chip, "gpio%d", PIR_SENSOR_PIN, "PIR Sensor", &pir_sensor_line) < 0) {
        perror("Failed to request PIR sensor line");
        goto error_exit;
    }

    if (gpiod_line_request_by_name(chip, "gpio%d", BUZZER_PIN, "Buzzer", &buzzer_line) < 0) {
        perror("Failed to request buzzer line");
        goto error_exit;
    }

    if (gpiod_line_direction_output(pir_sensor_line) < 0) {
        perror("Failed to set PIR sensor line direction");
        goto error_exit;
    }

    if (gpiod_line_direction_output(buzzer_line) < 0) {
        perror("Failed to set buzzer line direction");
        goto error_exit;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        goto error_exit;
    }

    while (1) {
        if (gpiod_line_get_value(pir_sensor_line) == 1) {
            gpiod_line_set_value(buzzer_line, 1);
            usleep(2000000); // 2 seconds
            gpiod_line_set_value(buzzer_line, 0);

            time(&ts.tv_sec);
            tm = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_file, "%s\n", timestamp);
            fflush(log_file);
        }
    }

error_exit:
    if (buzzer_line) {
        gpiod_line_free(buzzer_line);
    }

    if (pir_sensor_line) {
        gpiod_line_free(pir_sensor_line);
    }

    if (log_file) {
        fclose(log_file);
    }

    if (chip) {
        gpiod_chip_put(chip);
    }

    return EXIT_FAILURE;
}

