#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    char line_str[10];
    int duration = 0;
    FILE *config_file;

    // Open configuration file
    config_file = fopen("watering.conf", "r");
    if (!config_file) {
        perror("Failed to open configuration file");
        return 1;
    }

    // Read duration from configuration file
    if (fgets(line_str, sizeof(line_str), config_file) == NULL) {
        fprintf(stderr, "Configuration file is empty\n");
        fclose(config_file);
        return 1;
    }

    // Parse duration from line
    if (sscanf(line_str, "duration=%d", &duration) != 1 || duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration in configuration file\n");
        fclose(config_file);
        return 1;
    }

    fclose(config_file);

    // Initialize GPIO chip
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Initialize GPIO line
    if (gpiod_line_request_by_name(chip, "gpio18", "Timed Watering", 0, &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
    }

    // Set GPIO line as output with active-low
    if (gpiod_line_direction_output(line) < 0) {
        perror("Failed to set GPIO line direction");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Set default low value (valve off)
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Print status messages
    printf("Valve is off\n");

    // Activate valve
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }
    printf("Valve is on\n");

    // Wait for configured duration
    if (stop_flag) {
        printf("Timed watering interrupted\n");
    } else {
        printf("Timed watering for %d seconds\n", duration);
        sleep(duration);
    }

    // Deactivate valve
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return 1;
    }
    printf("Valve is off\n");

    // Release GPIO line and close chip
    gpiod_line_release(line);
    gpiod_chip_put(chip);

    return 0;
}

