    }

    if ((middle_sensor = gpiod_line_request_by_name(chip, "gpio%d", MIDDLE_SENSOR_PIN, "middle_sensor", GPIOD_LINE_DIRECTION_INPUT)) == NULL) {
        perror("Failed to request middle sensor line");
        goto cleanup;
    }

    if ((right_sensor = gpiod_line_request_by_name(chip, "gpio%d", RIGHT_SENSOR_PIN, "right_sensor", GPIOD_LINE_DIRECTION_INPUT)) == NULL) {
        perror("Failed to request right sensor line");
        goto cleanup;
    }

    if ((left_pwm = gpiod_line_request_by_name(chip, "gpio%d", LEFT_PWM_PIN, "left_pwm", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        perror("Failed to request left PWM line");
        goto cleanup;
    }

    if ((right_pwm = gpiod_line_request_by_name(chip, "gpio%d", RIGHT_PWM_PIN, "right_pwm", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        perror("Failed to request right PWM line");
        goto cleanup;
    }

    if ((left_dir = gpiod_line_request_by_name(chip, "gpio%d", LEFT_DIR_PIN, "left_dir", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        perror("Failed to request left direction line");
        goto cleanup;
    }

    if ((right_dir = gpiod_line_request_by_name(chip, "gpio%d", RIGHT_DIR_PIN, "right_dir", GPIOD_LINE_DIRECTION_OUTPUT)) == NULL) {
        perror("Failed to request right direction line");
        goto cleanup;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        left_sensor_state = gpiod_line_get_value(left_sensor);
        middle_sensor_state = gpiod_line_get_value(middle_sensor);
        right_sensor_state = gpiod_line_get_value(right_sensor);

        if (middle_sensor_state == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor_state == 0) {
            left_speed = HALF_SPEED;
            right_speed = BASE_SPEED;
        } else if (right_sensor_state == 0) {
            left_speed = BASE_SPEED;
            right_speed = HALF_SPEED;
        } else {
            left_speed = STOP_SPEED;
            right_speed = STOP_SPEED;
        }

        gpiod_line_set_value(left_pwm, left_speed);
        gpiod_line_set_value(right_pwm, right_speed);

        log_control_cycle(left_sensor_state, middle_sensor_state, right_sensor_state, left_speed, right_speed);

        usleep(10000); // 10 ms delay
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (left_sensor) {
        gpiod_line_request_free(left_sensor);
    }
    if (middle_sensor) {
        gpiod_line_request_free(middle_sensor);
    }
    if (right_sensor) {
        gpiod_line_request_free(right_sensor);
    }
    if (left_pwm) {
        gpiod_line_request_free(left_pwm);
    }
    if (right_pwm) {
        gpiod_line_request_free(right_pwm);
    }
    if (left_dir) {
        gpiod_line_request_free(left_dir);
    }
    if (right_dir) {
        gpiod_line_request_free(right_dir);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }

    return 0;
}
