#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"

int i2c_fd;
int relay_state = 0;

void handle_sigint(int signum) {
    if (relay_state) {
        printf("Turning off relay\n");
        system("echo 0 > /sys/class/gpio/gpio23/value");
        relay_state = 0;
    }
    printf("Closing I2C handle and exiting...\n");
    close(i2c_fd);
    exit(0);
}

int read_lux() {
    int lux;
    char cmd[16];
    sprintf(cmd, "i2cset -y -f %s %02X %02X %02X", I2C_BUS, BH1750_ADDR, 0x00, 0x01);
    system(cmd);
    sleep(1); // Wait for 1 second to allow measurement
    sprintf(cmd, "i2cget -y -f %s %02X %02X %02X", I2C_BUS, BH1750_ADDR, 0x00, 0x02);
    FILE *pipe = popen(cmd, "r");
    if (pipe == NULL) {
        perror("Failed to execute i2cget");
        return -1;
    }
    fscanf(pipe, "%d", &lux);
    pclose(pipe);
    return lux;
}

void log_lux_and_state(int lux, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    sprintf(buffer, "%02d:%02d:%02d.%03d - Lux: %d, Relay: %s\n",
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, (int)(rawtime - (time_t)timeinfo) * 1000,
            lux, state ? "ON" : "OFF");

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    if (fputs(buffer, log_file) == EOF) {
        perror("Failed to write to log file");
    }
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    printf("Starting BH1750 illuminance monitoring...\n");

    while (1) {
        int lux = read_lux();
        if (lux < 0) {
            printf("Failed to read lux value, continuing...\n");
            continue;
        }

        if (lux < LUX_THRESHOLD && relay_state == 0) {
            printf("Lux below threshold, turning on relay...\n");
            system("echo 1 > /sys/class/gpio/gpio23/value");
            relay_state = 1;
        } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
            printf("Lux above threshold, turning off relay...\n");
            system("echo 0 > /sys/class/gpio/gpio23/value");
            relay_state = 0;
        }

        log_lux_and_state(lux, relay_state);

        sleep(1); // Wait for 1 second before next reading
    }

    return 0;
}

