#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define DEBOUNCE_DELAY 100000  // 100 ms in microseconds

void handle_sigint(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    gpioServoWrite(SERVO_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistors.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            usleep(DEBOUNCE_DELAY);
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                printf("Lock button pressed, setting servo to 1000 µs.\n");
                gpioServoWrite(SERVO_PIN, 1000);
            }
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            usleep(DEBOUNCE_DELAY);
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                printf("Unlock button pressed, setting servo to 2000 µs.\n");
                gpioServoWrite(SERVO_PIN, 2000);
            }
        }

        usleep(100000);  // 100 ms delay between checks
    }

    return 0;
}

