#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        stop = 1;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for motor 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for motor 2\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        if (gpioWrite(MOTOR1_PIN, PI_ON) < 0) {
            fprintf(stderr, "Failed to turn on motor 1\n");
            stop = 1;
        }
        gpioDelay(200000); // 200 ms delay

        if (gpioWrite(MOTOR1_PIN, PI_OFF) < 0) {
            fprintf(stderr, "Failed to turn off motor 1\n");
            stop = 1;
        }

        if (gpioWrite(MOTOR2_PIN, PI_ON) < 0) {
            fprintf(stderr, "Failed to turn on motor 2\n");
            stop = 1;
        }
        gpioDelay(300000); // 300 ms delay

        if (gpioWrite(MOTOR2_PIN, PI_OFF) < 0) {
            fprintf(stderr, "Failed to turn off motor 2\n");
            stop = 1;
        }
    }

    if (gpioWrite(MOTOR1_PIN, PI_OFF) < 0) {
        fprintf(stderr, "Failed to turn off motor 1 on exit\n");
    }

    if (gpioWrite(MOTOR2_PIN, PI_OFF) < 0) {
        fprintf(stderr, "Failed to turn off motor 2 on exit\n");
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

