#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <zmq.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>

#define GPIO_BASE 0x200000
#define GPIO_LENGTH 4096
#define GPIO_EXPORT (GPIO_BASE + 0x04)
#define GPIO_SET (GPIO_BASE + 0x1C)
#define GPIO_CLEAR (GPIO_BASE + 0x28)
#define GPIO_FSEL (GPIO_BASE + 0x0C)
#define GPIO_INPUT 0
#define GPIO_OUTPUT 1
#define GPIO_ACTIVE_LOW 0
#define GPIO_ACTIVE_HIGH 1
#define GPIO_SOUND_SENSOR 17
#define GPIO_ALARM_LED 27
#define ZMQ_TOPIC "SOUND_ALERTS"

volatile unsigned *gpio_base;

void handle_signal(int signum) {
    if (gpio_base) {
        unsigned long mask = 1 << GPIO_SOUND_SENSOR;
        unsigned long clear_mask = ~(1 << GPIO_SOUND_SENSOR);
        unsigned long set_mask = 1 << GPIO_ALARM_LED;

        // Release GPIO lines
        if (gpio_base) {
            if (gpio_base[GPIO_FSEL / 4] & (1 << (GPIO_SOUND_SENSOR % 10))) {
                gpio_base[GPIO_FSEL / 4] &= clear_mask;
            }
            if (gpio_base[GPIO_FSEL / 4] & (1 << (GPIO_ALARM_LED % 10))) {
                gpio_base[GPIO_FSEL / 4] &= clear_mask;
            }
        }

        // Release GPIO chip
        if (gpio_base) {
            if (gpio_base[GPIO_EXPORT / 4] & (1 << (GPIO_SOUND_SENSOR / 10))) {
                gpio_base[GPIO_EXPORT / 4] &= clear_mask;
            }
            if (gpio_base[GPIO_EXPORT / 4] & (1 << (GPIO_ALARM_LED / 10))) {
                gpio_base[GPIO_EXPORT / 4] &= clear_mask;
            }
        }

        // Release ZeroMQ sockets and context
        if (zmq_socket) {
            zmq_close(zmq_socket);
        }
        if (zmq_context) {
            zmq_ctx_destroy(zmq_context);
        }
    }
    exit(signum);
}

int main(int argc, char *argv[]) {
    int mode = -1;
    int zmq_socket = -1;
    void *zmq_context = NULL;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        mode = 0;
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        mode = 1;
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }

    int fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open /dev/mem");
        return 1;
    }

    gpio_base = mmap(NULL, GPIO_LENGTH, PROT_READ | PROT_WRITE, MAP_SHARED, fd, GPIO_BASE);
    if (gpio_base == MAP_FAILED) {
        perror("Failed to mmap GPIO base");
        close(fd);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (mode == 0) {
        // Sound sensor mode
        unsigned long mask = 1 << GPIO_SOUND_SENSOR;
        unsigned long clear_mask = ~(1 << GPIO_SOUND_SENSOR);

        // Export GPIO
        if (gpio_base[GPIO_EXPORT / 4] & (1 << (GPIO_SOUND_SENSOR / 10))) {
            gpio_base[GPIO_EXPORT / 4] |= mask;
        }

        // Set GPIO direction
        if (gpio_base[GPIO_FSEL / 4] & (1 << (GPIO_SOUND_SENSOR % 10))) {
            gpio_base[GPIO_FSEL / 4] &= clear_mask;
        }

        // Set GPIO to input
        gpio_base[GPIO_FSEL / 4] |= (GPIO_INPUT << (GPIO_SOUND_SENSOR % 10));

        // Set GPIO to active low
        if (gpio_base[GPIO_FSEL / 4] & (1 << (GPIO_SOUND_SENSOR % 10))) {
            gpio_base[GPIO_FSEL / 4] &= clear_mask;
        }
        gpio_base[GPIO_FSEL / 4] |= (GPIO_ACTIVE_LOW << (GPIO_SOUND_SENSOR % 10));

        zmq_context = zmq_ctx_new();
        if (!zmq_context) {
            perror("Failed to create ZeroMQ context");
            goto cleanup;
        }

        zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
        if (!zmq_socket) {
            perror("Failed to create ZeroMQ socket");
            goto cleanup;
        }

        if (zmq_bind(zmq_socket, "tcp://*:5555") == -1) {
            perror("Failed to bind ZeroMQ socket");
            goto cleanup;
        }

        while (1) {
