volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int pulse_duration = 0;
volatile int pulse_count = 0;
volatile int ir_command = 0;
volatile int ir_checksum = 0;
volatile int ir_inverted_checksum = 0;
volatile int ir_extended = 0;

void ir_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        pulse_end = tick;
        pulse_duration = pulse_end - pulse_start;
        pulse_start = 0;

        if (pulse_count == 0) {
            // Check for header
            if (pulse_duration >= 9000 && pulse_duration <= 11000) {
                pulse_count++;
            } else {
                pulse_count = 0;
            }
        } else if (pulse_count == 1) {
            // Check for header space
            if (pulse_duration >= 4500 && pulse_duration <= 5500) {
                pulse_count++;
            } else {
                pulse_count = 0;
            }
        } else if (pulse_count < 35) {
            // Check for data bits
            if (pulse_duration >= 560 && pulse_duration <= 660) {
                ir_command = (ir_command << 1) | (pulse_duration >= 1690 ? 1 : 0);
                ir_checksum ^= ir_command;
                pulse_count++;
            } else {
                pulse_count = 0;
            }
        } else if (pulse_count == 35) {
            // Check for inverted checksum
            if (pulse_duration >= 560 && pulse_duration <= 660) {
                ir_inverted_checksum = (ir_inverted_checksum << 1) | (pulse_duration >= 1690 ? 1 : 0);
                pulse_count++;
            } else {
                pulse_count = 0;
            }
        } else if (pulse_count == 36) {
            // Check for extended frame
            if (pulse_duration >= 560 && pulse_duration <= 660) {
                ir_extended = 1;
                pulse_count++;
            } else {
                pulse_count = 0;
            }
        } else {
            pulse_count = 0;
        }
    } else {
        pulse_start = tick;
    }
}

void sig_handler(int signum) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
    }
    if (gpioTerminate() < 0) {
        syslog(LOG_ERR, "Failed to terminate GPIO");
    }
    if (mosquitto_lib_destroy() < 0) {
        syslog(LOG_ERR, "Failed to destroy MQTT client");
    }
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO pull-up/down");
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_PIN, ir_callback) < 0) {
        syslog(LOG_ERR, "Failed to set alert function");
        return 1;
    }

    json_t *json_obj;
    json_t *json_command;
    json_t *json_checksum;
    json_t *json_extended;

    struct mosquitto *mosq;
    int rc;

    mosq = mosquitto_new("ir_decoder", true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        return 1;
    }

    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_connack_string(rc));
        return 1;
    }

    while (1) {
        if (pulse_count == 37 && (ir_extended || ir_checksum == ir_inverted_checksum)) {
            syslog(LOG_INFO, "Decoded command: 0x%08X", ir_command);

            json_obj = json_object();
            json_command = json_integer(ir_command);
            json_checksum = json_integer(ir_checksum);
            json_extended = json_boolean(ir_extended);

            json_object_set_new(json_obj, "command", json_command);
            json_object_set_new(json_obj, "checksum", json_checksum);
            json_object_set_new(json_obj, "extended", json_extended);

            rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, json_dumps(json_obj, 0), 0, 0, 0);
            if (rc) {
                syslog(LOG_ERR, "Failed to publish to MQTT: %s", mosquitto_strerror(rc));
            }

            json_decref(json_obj);
            pulse_count = 0;
            ir_command = 0;
            ir_checksum = 0;
            ir_inverted_checksum = 0;
            ir_extended = 0;
        }

        mosquitto_loop(mosq, 100, 1);
    }

    return 0;
}

