#define I2C_CMD_READ_DATA_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW 0x1C
#define I2C_CMD_READ_DATA_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH 0x1D
#define I2C_CMD_READ_DATA_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW 0x1E
#define I2C_CMD_READ_DATA_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH_LOW_HIGH 0x1F

