int read_sensor(int addr) {
    int result = -1;
    char buffer[BUFFER_SIZE];
    int bytes_read;

    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }

    if (write(i2c_fd, &I2C_CMD_START_CONVERSION, 1) != 1) {
        perror("write");
        return -1;
    }

    usleep(180000); // 180 ms

    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }

    if ((bytes_read = read(i2c_fd, buffer, BUFFER_SIZE)) < 0) {
        perror("read");
        return -1;
    }

    if (bytes_read < 3) {
        fprintf(stderr, "Incomplete data read from sensor %d\n", addr);
        return -1;
    }

    result = (buffer[0] << 8) | buffer[1];

    return result;
