#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_ADDR 0x70
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "airflow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY 100

int i2c_fd;
int log_fd;

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != -1) {
        fflush(log_fd);
        fclose(log_fd);
    }
    exit(0);
}

int read_sensor() {
    char buffer[2];
    int retries = 0;
    int result = -1;

    while (retries < RETRY_COUNT) {
        if (read(i2c_fd, buffer, 2) == 2) {
            result = (buffer[0] << 8) | buffer[1];
            break;
        }
        retries++;
        usleep(RETRY_DELAY * 1000);
    }

    if (result == -1) {
        if (errno == ENXIO) {
            fprintf(stderr, "Error: Missing sensor (ENXIO)\n");
        } else if (errno == EIO) {
            fprintf(stderr, "Error: Bus error (EIO)\n");
        }
    }

    return result;
}

int main() {
    struct sigaction sa;
    struct timespec sleep_time;
    int flow_value;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_fd = fopen(LOG_FILE, "a");
    if (log_fd == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install SIGINT handler");
        fclose(log_fd);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        flow_value = read_sensor();
        if (flow_value != -1) {
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);

            fprintf(log_fd, "%s %d\n", timestamp, flow_value);
        }

        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    fclose(log_fd);
    close(i2c_fd);
    return 0;
}

