int i2c_fd;

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(signum);
}

int read_i2c_register(uint8_t reg) {
    uint8_t data;
    int ret = read(i2c_fd, &data, 1);
    if (ret != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return data;
}

int write_i2c_register(uint8_t reg, uint8_t value) {
    int ret = write(i2c_fd, &value, 1);
    if (ret != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access/talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor identification
    uint8_t id = read_i2c_register(0x00);
    if (id != 0x73) {
        fprintf(stderr, "Invalid sensor ID, expected 0x73, got 0x%02X\n", id);
        close(i2c_fd);
        return 1;
    }

    // Power on the sensor
    write_i2c_register(0x01, 0x01);

    // Configure SMUX and enable spectral measurement
    write_i2c_register(0x06, 0x00); // SMUX = 0
    write_i2c_register(0x07, 0x01); // SP_EN = 1

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint8_t spectral_data[10];
        for (int i = 0; i < 10; i++) {
            spectral_data[i] = read_i2c_register(0x08 + i);
        }

        // Simplified lux approximation (example calculation)
        uint32_t lux = (spectral_data[0] + spectral_data[1] + spectral_data[2] + spectral_data[3] + spectral_data[4] + spectral_data[5] + spectral_data[6] + spectral_data[7] + spectral_data[8] + spectral_data[9]) / 10;

        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %u, %u, %u, %u, %u, %u, %u, %u, %u, %u, %u\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec,
                spectral_data[0], spectral_data[1], spectral_data[2], spectral_data[3], spectral_data[4],
                spectral_data[5], spectral_data[6], spectral_data[7], spectral_data[8], spectral_data[9], lux);

        fflush(log_file);
        usleep(5000000); // Sleep for 5 seconds
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

