#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDR 0x68
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define BACKOFF_MS 10

int i2c_fd = -1;
FILE *data_file = NULL;
FILE *error_file = NULL;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    exit(signum == SIGINT ? 0 : 1);
}

int read_sensor_data(int i2c_addr) {
    int retries = 0;
    int result = -1;
    while (retries < MAX_RETRIES) {
        result = read(i2c_fd, &data, sizeof(data));
        if (result == sizeof(data)) {
            break;
        } else if (result < 0) {
            if (errno == EINTR) {
                retries++;
                usleep(BACKOFF_MS * 1000);
            } else {
                fprintf(error_file, "%s: I2C read error (errno=%d)\n", ctime(&time), errno);
                break;
            }
        }
    }
    return result;
}

int main(int argc, char *argv[]) {
    int i2c_addr = DEFAULT_I2C_ADDR;
    int interval = DEFAULT_INTERVAL;
    char *filename = DEFAULT_FILENAME;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0) {
            i++;
            if (i < argc) {
                i2c_addr = strtol(argv[i], NULL, 0);
            }
        } else if (strcmp(argv[i], "-i") == 0) {
            i++;
            if (i < argc) {
