#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>

#define BH1750_ADDR 0x23
#define BH1750_MEAS_CONT_HIGH_RES 0x20
#define BH1750_MEAS_CONT_LOW_RES 0x10
#define BH1750_MEAS_CONT_HIGH_RES_1 0x21
#define BH1750_MEAS_CONT_LOW_RES_1 0x11

#define I2C_ADDR_BH1750 "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000

void handle_signal(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    close(i2c_fd);
    close(multicast_socket);
    exit(signum);
}

int main() {
    struct sockaddr_in multicast_addr;
    struct ip_mreq multicast_group;
    int multicast_socket;
    int i2c_fd;
    char buffer[2];
    uint16_t raw_value;
    float lux_value;

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    i2c_fd = open(I2C_ADDR_BH1750, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set up multicast socket
    multicast_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (multicast_socket < 0) {
        perror("Failed to create socket");
        close(i2c_fd);
        return 1;
    }

    // Configure multicast socket
    multicast_addr.sin_family = AF_INET;
    multicast_addr.sin_port = htons(MULTICAST_PORT);
    multicast_addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);

    if (bind(multicast_socket, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) < 0) {
        perror("Failed to bind socket");
        close(i2c_fd);
        close(multicast_socket);
        return 1;
    }

    // Join multicast group
    multicast_group.imr_multiaddr.s_addr = inet_addr(MULTICAST_ADDR);
    multicast_group.imr_interface.s_addr = htonl(INADDR_ANY);
    if (setsockopt(multicast_socket, IPPROTO_IP, IP_ADD_MEMBERSHIP, &multicast_group, sizeof(multicast_group)) < 0) {
        perror("Failed to join multicast group");
        close(i2c_fd);
        close(multicast_socket);
        return 1;
    }

    // Start continuous measurement
    if (write(i2c_fd, &BH1750_MEAS_CONT_HIGH_RES, 1) < 0) {
        perror("Failed to start continuous measurement");
        close(i2c_fd);
        close(multicast_socket);
        return 1;
    }

    while (1) {
        // Read raw value
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read raw value");
            sleep(1);
            continue;
        }

        // Convert raw value to lux
        raw_value = (buffer[0] << 8) | buffer[1];
        lux_value = (float)raw_value / 1.2;

        // Broadcast lux value
        char lux_str[20];
        sprintf(lux_str, "%f", lux_value);
        if (sendto(multicast_socket, lux_str, strlen(lux_str), 0, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) < 0) {
            perror("Failed to send lux value");
            sleep(1);
            continue;
        }

        // Sleep for 1 second
        sleep(1);
    }

    close(i2c_fd);
    close(multicast_socket);
    return 0;
}

