#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <time.h>

#define BUFFER_SIZE 1024
#define MAGIC_WORD 0x12345678
#define TLV_HEADER_SIZE 4
#define TLV_DATA_SIZE 4

// Function prototypes
void handle_signal(int signum);
int read_uart(int fd, char *buffer, int size);
int validate_frame(const char *frame, int frame_size);
void extract_data(const char *frame, int frame_size, struct tm *timestamp, int *object_index, float *range_m, float *velocity_mps);
void write_to_csv(const char *filename, struct tm *timestamp, int object_index, float range_m, float velocity_mps);

// Global variables
int fd = -1;
char buffer[BUFFER_SIZE];

int main() {
    struct termios options;
    struct tm timestamp;
    int object_index = 0;
    float range_m = 0.0f;
    float velocity_mps = 0.0f;
    char filename[] = "radar_data.csv";

    // Open UART
    fd = open("/dev/ttyS0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Failed to open UART");
        return 1;
    }

    // Configure UART
    tcgetattr(fd, &options);
    cfsetispeed(&options, B921600);
    cfsetospeed(&options, B921600);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    tcsetattr(fd, TCSANOW, &options);

    // Handle signals
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        int bytes_read = read_uart(fd, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            if (validate_frame(buffer, bytes_read)) {
                extract_data(buffer, bytes_read, &timestamp, &object_index, &range_m, &velocity_mps);
                write_to_csv(filename, &timestamp, object_index, range_m, velocity_mps);
            }
        }
    }

    // Cleanup
    close(fd);
    return 0;
}

void handle_signal(int signum) {
    // Cleanup resources
    close(fd);
    exit(signum);
}

int read_uart(int fd, char *buffer, int size) {
    int bytes_read = 0;
    int total_bytes = 0;

    while (total_bytes < size) {
        int bytes = read(fd, buffer + total_bytes, size - total_bytes);
        if (bytes == -1) {
            perror("Failed to read from UART");
            return -1;
        } else if (bytes == 0) {
            break;
        }
        total_bytes += bytes;
    }

    return total_bytes;
}

int validate_frame(const char *frame, int frame_size) {
    if (frame_size < 8) {
        return 0;
    }

    uint32_t magic_word = *(uint32_t *)frame;
    if (magic_word != MAGIC_WORD) {
        return 0;
    }

    int tlv_count = *(uint32_t *)(frame + 4);
    int offset = 8;

    for (int i = 0; i < tlv_count; i++) {
        if (offset + TLV_HEADER_SIZE + *(uint32_t *)(frame + offset) > frame_size) {
            return 0;
        }
        offset += TLV_HEADER_SIZE + *(uint32_t *)(frame + offset);
    }

    return 1;
}

void extract_data(const char *frame, int frame_size, struct tm *timestamp, int *object_index, float *range_m, float *velocity_mps) {
    int offset = 8;
    int tlv_count = *(uint32_t *)(frame + 4);

    for (int i = 0; i < tlv_count; i++) {
        uint32_t tlv_type = *(uint32_t *)(frame + offset);
        uint32_t tlv_length = *(uint32_t *)(frame + offset + 4);

        if (offset + TLV_HEADER_SIZE + tlv_length > frame_size) {
            continue;
        }

        switch (tlv_type) {
            case 0x01: // Timestamp
                *timestamp = *(struct tm *)(frame + offset + TLV_HEADER_SIZE);
                break;
            case 0x02: // Object Index
                *object_index = *(int *)(frame + offset + TLV_HEADER_SIZE);
                break;
            case 0x03: // Range (meters)
                *range_m = *(float *)(frame + offset + TLV_HEADER_SIZE);
                break;
            case 0x04: // Velocity (meters per second)
                *velocity_mps = *(float *)(frame + offset + TLV_HEADER_SIZE);
                break;
        }

        offset += TLV_HEADER_SIZE + tlv_length;
    }
}

void write_to_csv(const char *filename, struct tm *timestamp, int object_index, float range_m, float velocity_mps) {
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        perror("Failed to open CSV file");
        return;
    }

    fprintf(file, "%d-%02d-%02d %02d:%02d:%02d, %d, %.2f, %.2f\n",
            timestamp->tm_year + 1900, timestamp->tm_mon + 1, timestamp->tm_mday,
            timestamp->tm_hour, timestamp->tm_min, timestamp->tm_sec,
            object_index, range_m, velocity_mps);

    fclose(file);
}

