#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define UART_SPEED 115200
#define BUFFER_SIZE 1024
#define TIMEOUT_USEC 500000
#define SELECT_TIMEOUT_SEC 2

char line_buffer[BUFFER_SIZE];
int line_buffer_index = 0;
int fd;

void handle_signal(int signum) {
    if (fd != -1) {
        close(fd);
    }
    exit(signum);
}

void parse_and_log_detection(const char *line) {
    char *timestamp_str, *range_str;
    double range;
    struct tm *tm;
    time_t rawtime;

    timestamp_str = strtok(line, ",");
    range_str = strtok(NULL, "\n");

    if (timestamp_str && range_str) {
        rawtime = strtol(timestamp_str, NULL, 10);
        tm = localtime(&rawtime);

        if (tm != NULL) {
            range = atof(range_str);
            printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d, Range: %.2f meters\n",
                   tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                   tm->tm_hour, tm->tm_min, tm->tm_sec, range);
        }
    }
}

int main() {
    struct termios options;
    struct timeval timeout;
    fd_set read_fds;
    int bytes_read;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return errno;
    }

    if (tcgetattr(fd, &options) == -1) {
        perror("tcgetattr");
        close(fd);
        return errno;
    }

    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);

    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;

    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;

    if (tcsetattr(fd, TCSANOW, &options) == -1) {
        perror("tcsetattr");
        close(fd);
        return errno;
    }

    while (1) {
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);

        timeout.tv_sec = SELECT_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        if (select(fd + 1, &read_fds, NULL, NULL, &timeout) == -1) {
            perror("select");
            close(fd);
            return errno;
        }

        if (FD_ISSET(fd, &read_fds)) {
            bytes_read = read(fd, line_buffer + line_buffer_index, BUFFER_SIZE - line_buffer_index - 1);
            if (bytes_read == -1) {
                perror("read");
                close(fd);
                return errno;
            }

            line_buffer_index += bytes_read;

            for (int i = 0; i < line_buffer_index; i++) {
                if (line_buffer[i] == '\n') {
                    line_buffer[i] = '\0';
                    parse_and_log_detection(line_buffer);
                    line_buffer_index = 0;
                    break;
                }
            }
        }
    }

    close(fd);
    return 0;
}

