This C program reads data from a Texas Instruments AWR1642 mmWave radar sensor connected to a Raspberry Pi 4 Model B over UART. It opens the UART device in non-canonical mode, sets the baud rate to 115200, and configures the UART for 8N1. It uses `select()` to periodically check for data and handles partial reads by accumulating them into a line buffer. When a complete newline-terminated line is detected, it parses the line to extract the Unix timestamp and range, and logs the data in the specified format. The program also installs signal handlers for SIGINT and SIGTERM to ensure a graceful shutdown that closes the UART on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <termios.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200
#define TIMEOUT 100 // 100ms

static struct gpiod_chip *chip;
static struct gpiod_line *left_sensor, *middle_sensor, *right_sensor;
static struct termios options;
static FILE *uart_file;

void cleanup() {
    if (left_sensor) {
        gpiod_line_free(left_sensor);
        left_sensor = NULL;
    }
    if (middle_sensor) {
        gpiod_line_free(middle_sensor);
        middle_sensor = NULL;
    }
    if (right_sensor) {
        gpiod_line_free(right_sensor);
        right_sensor = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (uart_file) {
        fclose(uart_file);
        uart_file = NULL;
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    left_sensor = gpiod_line_request_any(chip, "left_sensor", "input", 0);
    if (!left_sensor) {
        fprintf(stderr, "Failed to request left sensor line\n");
        cleanup();
        exit(1);
    }

    middle_sensor = gpiod_line_request_any(chip, "middle_sensor", "input", 0);
    if (!middle_sensor) {
        fprintf(stderr, "Failed to request middle sensor line\n");
        cleanup();
        exit(1);
    }

    right_sensor = gpiod_line_request_any(chip, "right_sensor", "input", 0);
    if (!right_sensor) {
        fprintf(stderr, "Failed to request right sensor line\n");
        cleanup();
        exit(1);
    }

    gpiod_line_set_function(left_sensor, GPIOF_INPUT);
    gpiod_line_set_function(middle_sensor, GPIOF_INPUT);
    gpiod_line_set_function(right_sensor, GPIOF_INPUT);

    gpiod_line_set_value(left_sensor, 1); // Enable pull-up resistor
    gpiod_line_set_value(middle_sensor, 1);
    gpiod_line_set_value(right_sensor, 1);

    if (tcgetattr(0, &options) == -1) {
        perror("tcgetattr");
        cleanup();
        exit(1);
    }

    options.c_cflag = BAUD_RATE | CS8 | CREAD | CLOCAL;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;

    if (tcsetattr(0, TCSANOW, &options) == -1) {
        perror("tcsetattr");
        cleanup();
        exit(1);
    }

    if ((uart_file = fopen(UART_DEVICE, "w")) == NULL) {
        perror("fopen");
        cleanup();
        exit(1);
    }

    while (1) {
        int left_state = gpiod_line_get_value(left_sensor);
        int middle_state = gpiod_line_get_value(middle_sensor);
        int right_state = gpiod_line_get_value(right_sensor);

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);

        printf("%02d:%02d:%02d - Left: %d, Middle: %d, Right: %d\n",
               timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
               left_state, middle_state, right_state);

        if (left_state == 0 && middle_state == 0 && right_state == 0) {
            if (fprintf(uart_file, "EMERGENCY STOP!\n") == -1) {
                perror("fprintf");
            }
        }

        usleep(TIMEOUT * 1000); // Sleep for 100ms
    }

    cleanup();
    return 0;
}

